# Exact large-number transport and hashing.
# Small scalars remain human-readable in decimal. Large integers are emitted as
# complete signed-magnitude Base64, which is lossless and reconstructible, and
# therefore avoids Python's decimal-string safety limit without discarding a digit.
def _exact_integer_transport(value: int) -> str:
    sign = '-' if value < 0 else '+'
    magnitude = abs(value)
    bit_length = magnitude.bit_length()
    byte_length = max(1, (bit_length + 7) // 8)
    payload = magnitude.to_bytes(byte_length, 'big')
    encoded = base64.b64encode(payload).decode('ascii')
    digest = hashlib.sha256((b'-' if value < 0 else b'+') + payload).hexdigest()
    return (
        'EXACT_INTEGER('
        f'sign={sign},bit_length={bit_length},byte_length={byte_length},'
        f'magnitude_base64={encoded},sha256={digest})'
    )


def _exact_scalar_text(value) -> str:
    if isinstance(value, bool) or value is None:
        return str(value)
    if isinstance(value, int):
        if abs(value).bit_length() <= 1024:
            return str(value)
        return _exact_integer_transport(value)
    if isinstance(value, Fraction):
        numerator = value.numerator
        denominator = value.denominator
        if max(abs(numerator).bit_length(), denominator.bit_length()) <= 1024:
            return str(value)
        return (
            'EXACT_FRACTION('
            f'numerator={_exact_integer_transport(numerator)},'
            f'denominator={_exact_integer_transport(denominator)},'
            f'sha256={_deterministic_object_digest(value)})'
        )
    if isinstance(value, Decimal):
        return format(value, 'f')
    if isinstance(value, bytes):
        return 'EXACT_BYTES_BASE64(' + base64.b64encode(value).decode('ascii') + ')'
    return str(value)


def _digest_update(hasher, value) -> None:
    if value is None:
        hasher.update(b'N;')
    elif isinstance(value, bool):
        hasher.update(b'B1;' if value else b'B0;')
    elif isinstance(value, int):
        magnitude = abs(value)
        payload = magnitude.to_bytes(max(1, (magnitude.bit_length() + 7) // 8), 'big')
        hasher.update(b'I-' if value < 0 else b'I+')
        hasher.update(len(payload).to_bytes(8, 'big'))
        hasher.update(payload)
    elif isinstance(value, Fraction):
        hasher.update(b'Q[')
        _digest_update(hasher, value.numerator)
        _digest_update(hasher, value.denominator)
        hasher.update(b'];')
    elif isinstance(value, Decimal):
        encoded = format(value, 'f').encode('ascii')
        hasher.update(b'D')
        hasher.update(len(encoded).to_bytes(8, 'big'))
        hasher.update(encoded)
    elif isinstance(value, str):
        encoded = value.encode('utf-8')
        hasher.update(b'S')
        hasher.update(len(encoded).to_bytes(8, 'big'))
        hasher.update(encoded)
    elif isinstance(value, bytes):
        hasher.update(b'Y')
        hasher.update(len(value).to_bytes(8, 'big'))
        hasher.update(value)
    elif isinstance(value, dict):
        hasher.update(b'M{')
        hasher.update(len(value).to_bytes(8, 'big'))
        for key in sorted(value, key=lambda item: (type(item).__name__, _exact_scalar_text(item))):
            _digest_update(hasher, key)
            _digest_update(hasher, value[key])
        hasher.update(b'};')
    elif isinstance(value, tuple):
        hasher.update(b'T[')
        hasher.update(len(value).to_bytes(8, 'big'))
        for item in value:
            _digest_update(hasher, item)
        hasher.update(b'];')
    elif isinstance(value, list):
        hasher.update(b'L[')
        hasher.update(len(value).to_bytes(8, 'big'))
        for item in value:
            _digest_update(hasher, item)
        hasher.update(b'];')
    elif isinstance(value, (set, frozenset)):
        hasher.update(b'E{')
        encoded_items = sorted(_deterministic_object_digest(item) for item in value)
        for encoded in encoded_items:
            _digest_update(hasher, encoded)
        hasher.update(b'};')
    elif isinstance(value, complex):
        hasher.update(b'C[')
        _digest_update(hasher, value.real)
        _digest_update(hasher, value.imag)
        hasher.update(b'];')
    elif isinstance(value, float):
        encoded = value.hex().encode('ascii')
        hasher.update(b'F')
        hasher.update(len(encoded).to_bytes(8, 'big'))
        hasher.update(encoded)
    else:
        encoded = (type(value).__module__ + '.' + type(value).__qualname__ + ':' + str(value)).encode('utf-8')
        hasher.update(b'O')
        hasher.update(len(encoded).to_bytes(8, 'big'))
        hasher.update(encoded)


def _deterministic_object_digest(value) -> str:
    hasher = hashlib.sha256()
    _digest_update(hasher, value)
    return hasher.hexdigest()
