def _fraction_rref(matrix: Sequence[Sequence[Fraction]]) -> Tuple[Tuple[Tuple[Fraction, ...], ...], Tuple[int, ...]]:
    if not matrix:
        return (tuple(), tuple())
    work = [[Fraction(value) for value in row] for row in matrix]
    row_count = len(work)
    column_count = len(work[0])
    pivot_row = 0
    pivot_columns = []
    for column in range(column_count):
        pivot = next((row for row in range(pivot_row, row_count) if work[row][column] != 0), None)
        if pivot is None:
            continue
        work[pivot_row], work[pivot] = (work[pivot], work[pivot_row])
        pivot_value = work[pivot_row][column]
        work[pivot_row] = [value / pivot_value for value in work[pivot_row]]
        for row in range(row_count):
            if row == pivot_row or work[row][column] == 0:
                continue
            factor = work[row][column]
            work[row] = [work[row][entry] - factor * work[pivot_row][entry] for entry in range(column_count)]
        pivot_columns.append(column)
        pivot_row += SHIFT
        if pivot_row == row_count:
            break
    return (tuple((tuple(row) for row in work)), tuple(pivot_columns))

def _fraction_nullspace(matrix: Sequence[Sequence[Fraction]]) -> Tuple[Tuple[Fraction, ...], ...]:
    if not matrix:
        return tuple()
    rref, pivots = _fraction_rref(matrix)
    column_count = len(matrix[0])
    free_columns = tuple((column for column in range(column_count) if column not in pivots))
    basis = []
    for free in free_columns:
        vector = [Fraction(0) for _ in range(column_count)]
        vector[free] = Fraction(SHIFT)
        for row, pivot in enumerate(pivots):
            vector[pivot] = -rref[row][free]
        basis.append(tuple(vector))
    return tuple(basis)
