for p_zero_axis in range(3):
    p_active = [axis for axis in range(3) if axis != p_zero_axis]
    for p_s1 in (-1, 1):
        for p_s2 in (-1, 1):
            p_v = [0, 0, 0]
            p_v[p_active[0]] = p_s1
            p_v[p_active[1]] = p_s2
            p_C12_VERTICES.add(tuple(p_v))

def association_scheme_transpose(matrix):
    return tuple((tuple((p_Fraction(matrix[row][column]) for row in range(len(matrix)))) for column in range(len(matrix[0]))))

def association_scheme_multiply(left, right):
    return tuple((tuple((sum((p_Fraction(left[row][inner]) * p_Fraction(right[inner][column]) for inner in range(len(right)))) for column in range(len(right[0])))) for row in range(len(left))))

def association_scheme_add(left, right):
    return tuple((tuple((p_Fraction(left[row][column]) + p_Fraction(right[row][column]) for column in range(len(left[0])))) for row in range(len(left))))

def association_scheme_subtract(left, right):
    return tuple((tuple((p_Fraction(left[row][column]) - p_Fraction(right[row][column]) for column in range(len(left[0])))) for row in range(len(left))))

def association_scheme_identity(size):
    return tuple((tuple((p_Fraction(1) if row == column else p_Fraction(0) for column in range(size))) for row in range(size)))

def association_scheme_rank(matrix):
    work = [list(map(p_Fraction, row)) for row in matrix]
    if not work:
        return 0
    row_count = len(work)
    column_count = len(work[0])
    pivot_row = 0
    rank_value = 0
    for pivot_column in range(column_count):
        selected = next((row for row in range(pivot_row, row_count) if work[row][pivot_column] != 0), None)
        if selected is None:
            continue
        work[pivot_row], work[selected] = (work[selected], work[pivot_row])
        pivot = work[pivot_row][pivot_column]
        work[pivot_row] = [entry / pivot for entry in work[pivot_row]]
        for row in range(row_count):
            if row == pivot_row or work[row][pivot_column] == 0:
                continue
            factor = work[row][pivot_column]
            work[row] = [work[row][column] - factor * work[pivot_row][column] for column in range(column_count)]
        pivot_row += 1
        rank_value += 1
        if pivot_row == row_count:
            break
    return rank_value

def association_scheme_quadratic(matrix, vector):
    return sum((p_Fraction(vector[row]) * p_Fraction(matrix[row][column]) * p_Fraction(vector[column]) for row in range(len(vector)) for column in range(len(vector))))

def p_native_shell_cells():
    vertex_set = set()
    for zero_axis in range(3):
        active_axes = tuple((axis for axis in range(3) if axis != zero_axis))
        for first_sign in (-1, 1):
            for second_sign in (-1, 1):
                vertex = [0, 0, 0]
                vertex[active_axes[0]] = first_sign
                vertex[active_axes[1]] = second_sign
                vertex_set.add(tuple(vertex))
    vertices = tuple(sorted(vertex_set))
    vertex_index = {vertex: index for index, vertex in enumerate(vertices)}
    edges = tuple(((first, second) for first in range(len(vertices)) for second in range(first + 1, len(vertices)) if sum(((vertices[first][axis] - vertices[second][axis]) ** 2 for axis in range(3))) == 2))
    edge_index = {edge: index for index, edge in enumerate(edges)}
    face_sets = []
    for sx in (-1, 1):
        for sy in (-1, 1):
            for sz in (-1, 1):
                face_sets.append(tuple(sorted((vertex_index[0, sy, sz], vertex_index[sx, 0, sz], vertex_index[sx, sy, 0]))))
    for axis in range(3):
        for sign in (-1, 1):
            face_sets.append(tuple(sorted((index for index, vertex in enumerate(vertices) if vertex[axis] == sign))))
    assert len(set(face_sets)) == 14

    def boundary_cycle(face_set):
        face_vertices = set(face_set)
        start = min(face_vertices)
        neighbours = sorted((other for other in face_vertices if tuple(sorted((start, other))) in edge_index))
        current = neighbours[0]
        cycle = [start, current]
        previous = start
        while len(cycle) < len(face_vertices):
            candidates = sorted((other for other in face_vertices if other != previous and other not in cycle and (tuple(sorted((current, other))) in edge_index)))
            assert candidates
            next_vertex = candidates[0]
            cycle.append(next_vertex)
            previous, current = (current, next_vertex)
        assert tuple(sorted((cycle[-1], cycle[0]))) in edge_index
        return tuple(cycle)
    faces = tuple((boundary_cycle(face_set) for face_set in face_sets))
    boundary_1 = [[p_Fraction(0) for _ in edges] for _ in vertices]
    for edge_number, (tail, head) in enumerate(edges):
        boundary_1[tail][edge_number] = p_Fraction(-1)
        boundary_1[head][edge_number] = p_Fraction(1)
    boundary_2 = [[p_Fraction(0) for _ in faces] for _ in edges]
    for face_number, cycle in enumerate(faces):
        for tail, head in zip(cycle, cycle[1:] + cycle[:1]):
            edge_number = edge_index[tuple(sorted((tail, head)))]
            boundary_2[edge_number][face_number] = p_Fraction(1) if tail < head else p_Fraction(-1)
    return {'VERTICES': vertices, 'EDGES': edges, 'FACES': faces, 'BOUNDARY_1': tuple((tuple(row) for row in boundary_1)), 'BOUNDARY_2': tuple((tuple(row) for row in boundary_2))}

def spectral_projector_scale(matrix, scalar):
    factor = p_Fraction(scalar)
    return tuple((tuple((factor * p_Fraction(entry) for entry in row)) for row in matrix))

def spectral_projector_trace(matrix):
    return sum((p_Fraction(matrix[index][index]) for index in range(len(matrix))))

def spectral_projector_zero(rows, columns):
    return tuple((tuple((p_Fraction(0) for _ in range(columns))) for _ in range(rows)))

def spectral_projector_hadamard(left, right):
    return tuple((tuple((p_Fraction(left[row][column]) * p_Fraction(right[row][column]) for column in range(len(left[0])))) for row in range(len(left))))

def spectral_projector_frobenius(left, right):
    return sum((p_Fraction(left[row][column]) * p_Fraction(right[row][column]) for row in range(len(left)) for column in range(len(left[0]))))

def spectral_projector_charpoly_coefficients(matrix):
    """Exact Faddeev-LeVerrier characteristic polynomial coefficients."""
    size = len(matrix)
    identity = association_scheme_identity(size)
    b_matrix = identity
    coefficients = [p_Fraction(1)]
    for order in range(1, size + 1):
        product = association_scheme_multiply(matrix, b_matrix)
        coefficient = -spectral_projector_trace(product) / p_Fraction(order)
        coefficients.append(coefficient)
        b_matrix = association_scheme_add(product, spectral_projector_scale(identity, coefficient))
    return tuple(coefficients)

def spectral_projector_polynomial_value(coefficients, value):
    result = p_Fraction(0)
    x_value = p_Fraction(value)
    for coefficient in coefficients:
        result = result * x_value + p_Fraction(coefficient)
    return result

def spectral_projector_integer_roots(coefficients, search_bound):
    roots = tuple((candidate for candidate in range(-search_bound, search_bound + 1) if spectral_projector_polynomial_value(coefficients, candidate) == 0))
    return roots

def spectral_projector_lagrange_projector(separator, selected_root, all_roots):
    size = len(separator)
    identity = association_scheme_identity(size)
    numerator = identity
    denominator = p_Fraction(1)
    for root in all_roots:
        if root == selected_root:
            continue
        numerator = association_scheme_multiply(numerator, association_scheme_subtract(separator, spectral_projector_scale(identity, root)))
        denominator *= p_Fraction(selected_root - root)
    if denominator == 0:
        raise AssertionError('separator roots must be distinct')
    return spectral_projector_scale(numerator, p_Fraction(1, 1) / denominator)

def p_native_orbital_relations():
    cells = p_native_shell_cells()
    vertices = cells['VERTICES']
    edges = cells['EDGES']
    vertex_count = len(vertices)
    adjacency = {index: set() for index in range(vertex_count)}
    for first, second in edges:
        adjacency[first].add(second)
        adjacency[second].add(first)
    distances = [[vertex_count + 1 for _ in range(vertex_count)] for _ in range(vertex_count)]
    for source in range(vertex_count):
        distances[source][source] = 0
        frontier = {source}
        while frontier:
            next_frontier = set()
            for current in frontier:
                for target in adjacency[current]:
                    if distances[source][target] == vertex_count + 1:
                        distances[source][target] = distances[source][current] + 1
                        next_frontier.add(target)
            frontier = next_frontier
    signatures = ((0, 2), (1, 1), (2, 0), (2, -1), (3, -2))
    relations = []
    for graph_distance, dot_product in signatures:
        relation = []
        for first in range(vertex_count):
            row = []
            for second in range(vertex_count):
                current_dot = sum((vertices[first][axis] * vertices[second][axis] for axis in range(3)))
                row.append(p_Fraction(int(distances[first][second] == graph_distance and current_dot == dot_product)))
            relation.append(tuple(row))
        relations.append(tuple(relation))
    relation_sum = relations[0]
    for relation in relations[1:]:
        relation_sum = association_scheme_add(relation_sum, relation)
    all_ones = tuple((tuple((p_Fraction(1) for _ in range(vertex_count))) for _ in range(vertex_count)))
    assert relation_sum == all_ones
    assert all((sum((int(relation[row][column] != 0) for relation in relations)) == 1 for row in range(vertex_count) for column in range(vertex_count)))
    return {'CELLS': cells, 'VERTICES': vertices, 'DISTANCES': tuple((tuple(row) for row in distances)), 'SIGNATURES': signatures, 'RELATIONS': tuple(relations)}

def p_exact_bose_mesner_algebra_theorem():
    packet = p_native_orbital_relations()
    relations = packet['RELATIONS']
    relation_count = len(relations)
    size = len(relations[0])
    multiplication_tensor = []
    closure_checks = []
    for left_index, left in enumerate(relations):
        left_rows = []
        for right_index, right in enumerate(relations):
            product = association_scheme_multiply(left, right)
            coefficients = []
            for relation in relations:
                values = {product[row][column] for row in range(size) for column in range(size) if relation[row][column] == 1}
                assert len(values) == 1
                coefficients.append(next(iter(values)))
            reconstructed = spectral_projector_zero(size, size)
            for coefficient, relation in zip(coefficients, relations):
                reconstructed = association_scheme_add(reconstructed, spectral_projector_scale(relation, coefficient))
            closed = reconstructed == product
            closure_checks.append(closed)
            left_rows.append(tuple(coefficients))
        multiplication_tensor.append(tuple(left_rows))
    multiplication_tensor = tuple(multiplication_tensor)
    commutative = all((multiplication_tensor[left][right] == multiplication_tensor[right][left] for left in range(relation_count) for right in range(relation_count)))
    associative = True
    for a in range(relation_count):
        for b in range(relation_count):
            for c in range(relation_count):
                left_coefficients = tuple((sum((multiplication_tensor[a][b][middle] * multiplication_tensor[middle][c][target] for middle in range(relation_count))) for target in range(relation_count)))
                right_coefficients = tuple((sum((multiplication_tensor[b][c][middle] * multiplication_tensor[a][middle][target] for middle in range(relation_count))) for target in range(relation_count)))
                if left_coefficients != right_coefficients:
                    associative = False
    flattened_relations = tuple((tuple((entry for row in relation for entry in row)) for relation in relations))
    algebra_rank = association_scheme_rank(flattened_relations)
    identity = association_scheme_identity(size)
    all_ones = tuple((tuple((p_Fraction(1) for _ in range(size))) for _ in range(size)))
    relation_sum = spectral_projector_zero(size, size)
    for relation in relations:
        relation_sum = association_scheme_add(relation_sum, relation)
    checks = {'RELATION_MATRICES_ARE_LINEarly_INDEPENDENT': algebra_rank == relation_count, 'DIAGONAL_RELATION_IS_IDENTITY': relations[0] == identity, 'RELATION_SUM_IS_ALL_ONES': relation_sum == all_ones, 'EVERY_PRODUCT_CLOSES_IN_RELATION_BASIS': all(closure_checks), 'INTERSECTION_NUMBERS_ARE_NONNEGATIVE_INTEGERS': all((coefficient.denominator == 1 and coefficient >= 0 for left in multiplication_tensor for right in left for coefficient in right)), 'ALGEBRA_IS_COMMUTATIVE': commutative, 'ALGEBRA_IS_ASSOCIATIVE': associative, 'ALGEBRA_DIMENSION_IS_FIVE': algebra_rank == 5}
    assert all(checks.values())
    return {'ALGEBRA_DIMENSION': algebra_rank, 'RELATION_SIGNATURES': packet['SIGNATURES'], 'RELATION_VALENCIES': tuple((sum(relation[0]) for relation in relations)), 'INTERSECTION_NUMBER_TENSOR': multiplication_tensor, 'PROOF_OBLIGATIONS': checks, 'STATUS': 'EXACT_RANK_FIVE_BOSE_MESNER_ALGEBRA_THEOREM_PROVED'}

def p_exact_primitive_channel_projector_theorem():
    packet = p_native_orbital_relations()
    relations = packet['RELATIONS']
    relation_count = len(relations)
    size = len(relations[0])
    algebra = p_exact_bose_mesner_algebra_theorem()
    tensor = algebra['INTERSECTION_NUMBER_TENSOR']
    separator_base = relation_count + p_SHIFT
    separator_weights = (p_Fraction(0),) + tuple((p_Fraction(separator_base ** exponent) for exponent in range(relation_count - 1)))
    separator = spectral_projector_zero(size, size)
    for weight, relation in zip(separator_weights, relations):
        separator = association_scheme_add(separator, spectral_projector_scale(relation, weight))
    left_regular = []
    for target in range(relation_count):
        row = []
        for source in range(relation_count):
            coefficient = sum((separator_weights[relation] * tensor[relation][source][target] for relation in range(relation_count)))
            row.append(coefficient)
        left_regular.append(tuple(row))
    left_regular = tuple(left_regular)
    characteristic = spectral_projector_charpoly_coefficients(left_regular)
    search_bound = max((sum((abs(entry) for entry in row)) for row in left_regular))
    if search_bound.denominator != 1:
        raise AssertionError('integer relation algebra must have integer root bound')
    roots = spectral_projector_integer_roots(characteristic, int(search_bound))
    assert len(roots) == relation_count
    assert len(set(roots)) == relation_count
    projectors = tuple((spectral_projector_lagrange_projector(separator, root, roots) for root in roots))
    identity = association_scheme_identity(size)
    projector_sum = spectral_projector_zero(size, size)
    for projector in projectors:
        projector_sum = association_scheme_add(projector_sum, projector)
    orthogonality_failures = []
    projector_rows = []
    character_table = []
    for index, (root, projector) in enumerate(zip(roots, projectors)):
        if association_scheme_transpose(projector) != projector:
            orthogonality_failures.append((index, 'NOT_SYMMETRIC'))
        if association_scheme_multiply(projector, projector) != projector:
            orthogonality_failures.append((index, 'NOT_IDEMPOTENT'))
        for other_index, other in enumerate(projectors):
            product = association_scheme_multiply(projector, other)
            expected = projector if index == other_index else spectral_projector_zero(size, size)
            if product != expected:
                orthogonality_failures.append((index, other_index))
        rank = association_scheme_rank(projector)
        trace = spectral_projector_trace(projector)
        assert trace == rank
        characters = []
        for relation in relations:
            product = association_scheme_multiply(relation, projector)
            eigenvalue = spectral_projector_trace(product) / p_Fraction(rank)
            assert product == spectral_projector_scale(projector, eigenvalue)
            characters.append(eigenvalue)
        character_table.append(tuple(characters))
        projector_rows.append({'SEPARATOR_EIGENVALUE': root, 'RANK': rank, 'RELATION_CHARACTERS': tuple(characters), 'IS_CONSTANT_MODE': projector == tuple((tuple((p_Fraction(1, size) for _ in range(size))) for _ in range(size)))})
    assert projector_sum == identity
    constant_indices = tuple((index for index, row in enumerate(projector_rows) if row['IS_CONSTANT_MODE']))
    assert len(constant_indices) == 1
    constant_index = constant_indices[0]
    nontrivial_indices = tuple((index for index in range(relation_count) if index != constant_index))
    relation_reconstruction_failures = []
    for relation_index, relation in enumerate(relations):
        reconstructed = spectral_projector_zero(size, size)
        for projector_index, projector in enumerate(projectors):
            reconstructed = association_scheme_add(reconstructed, spectral_projector_scale(projector, character_table[projector_index][relation_index]))
        if reconstructed != relation:
            relation_reconstruction_failures.append(relation_index)
    valencies = tuple((sum(relation[0]) for relation in relations))
    multiplicities = tuple((row['RANK'] for row in projector_rows))
    weighted_row_orthogonality = []
    for first in range(relation_count):
        row = []
        for second in range(relation_count):
            value = sum((character_table[first][relation] * character_table[second][relation] / valencies[relation] for relation in range(relation_count)))
            expected = p_Fraction(size, multiplicities[first]) if first == second else p_Fraction(0)
            row.append(value == expected)
        weighted_row_orthogonality.append(tuple(row))
    weighted_column_orthogonality = []
    for first in range(relation_count):
        row = []
        for second in range(relation_count):
            value = sum((multiplicities[channel] * character_table[channel][first] * character_table[channel][second] for channel in range(relation_count)))
            expected = p_Fraction(size * valencies[first]) if first == second else p_Fraction(0)
            row.append(value == expected)
        weighted_column_orthogonality.append(tuple(row))
    dual_eigenmatrix = tuple((tuple((p_Fraction(multiplicities[channel], valencies[relation]) * character_table[channel][relation] for channel in range(relation_count))) for relation in range(relation_count)))
    eigenmatrix = tuple(character_table)
    pq_product = association_scheme_multiply(eigenmatrix, dual_eigenmatrix)
    qp_product = association_scheme_multiply(dual_eigenmatrix, eigenmatrix)
    scaled_identity = spectral_projector_scale(association_scheme_identity(relation_count), size)
    krein_rows = []
    krein_nonnegative = True
    for first in range(relation_count):
        for second in range(first, relation_count):
            hadamard = spectral_projector_hadamard(projectors[first], projectors[second])
            coefficients = tuple((spectral_projector_frobenius(hadamard, projectors[channel]) / p_Fraction(multiplicities[channel]) for channel in range(relation_count)))
            reconstructed = spectral_projector_zero(size, size)
            for coefficient, projector in zip(coefficients, projectors):
                reconstructed = association_scheme_add(reconstructed, spectral_projector_scale(projector, coefficient))
            assert reconstructed == hadamard
            krein_parameters = tuple((p_Fraction(size) * coefficient for coefficient in coefficients))
            if any((parameter < 0 for parameter in krein_parameters)):
                krein_nonnegative = False
            krein_rows.append({'CHANNEL_PAIR': (first, second), 'KREIN_PARAMETERS': krein_parameters})
    checks = {'SEPARATOR_WEIGHTS_ARE_NATIVE_AND_REFERENCE_FREE': separator_base == 6, 'LEFT_REGULAR_CHARACTERISTIC_HAS_FIVE_DISTINCT_INTEGER_ROOTS': len(roots) == 5, 'FIVE_PRIMITIVE_PROJECTORS_SUM_TO_IDENTITY': projector_sum == identity, 'PROJECTORS_ARE_SYMMETRIC_IDEMPOTENT_AND_ORTHOGONAL': not orthogonality_failures, 'RELATIONS_RECONSTRUCT_FROM_PROJECTOR_CHARACTERS': not relation_reconstruction_failures, 'PROJECTOR_RANKS_SUM_TO_TWELVE': sum(multiplicities) == size, 'EXACTLY_ONE_CONSTANT_PROJECTOR': len(constant_indices) == 1, 'EXACTLY_FOUR_NONTRIVIAL_PROJECTORS': len(nontrivial_indices) == 4, 'WEIGHTED_ROW_ORTHOGONALITY': all((all(row) for row in weighted_row_orthogonality)), 'WEIGHTED_COLUMN_ORTHOGONALITY': all((all(row) for row in weighted_column_orthogonality)), 'P_TIMES_Q_EQUALS_TWELVE_IDENTITY': pq_product == scaled_identity, 'Q_TIMES_P_EQUALS_TWELVE_IDENTITY': qp_product == scaled_identity, 'SCHUR_PRODUCTS_CLOSE_WITH_NONNEGATIVE_KREIN_PARAMETERS': krein_nonnegative}
    assert all(checks.values())
    return {'SEPARATOR_BASE': separator_base, 'SEPARATOR_WEIGHTS': separator_weights, 'LEFT_REGULAR_CHARACTERISTIC_COEFFICIENTS': characteristic, 'SEPARATOR_EIGENVALUES': roots, 'PROJECTOR_ROWS': tuple(projector_rows), 'CONSTANT_PROJECTOR_INDEX': constant_index, 'NONTRIVIAL_PROJECTOR_INDICES': nontrivial_indices, 'NONTRIVIAL_CHANNEL_COUNT': len(nontrivial_indices), 'EIGENMATRIX_P': eigenmatrix, 'DUAL_EIGENMATRIX_Q': dual_eigenmatrix, 'KREIN_PARAMETER_ROWS': tuple(krein_rows), 'PROJECTORS': projectors, 'PROOF_OBLIGATIONS': checks, 'STATUS': 'EXACT_FOUR_NONTRIVIAL_CHANNEL_PROJECTOR_THEOREM_PROVED'}

def p_exact_local_action_channel_response_theorem():
    packet = p_native_orbital_relations()
    relations = packet['RELATIONS']
    size = len(relations[0])
    channel = p_exact_primitive_channel_projector_theorem()
    projectors = channel['PROJECTORS']
    characters = channel['EIGENMATRIX_P']
    constant_index = channel['CONSTANT_PROJECTOR_INDEX']
    nontrivial_indices = channel['NONTRIVIAL_PROJECTOR_INDICES']
    identity = relations[0]
    edge_relation = relations[1]
    edge_valency = sum(edge_relation[0])
    laplacian = association_scheme_subtract(spectral_projector_scale(identity, edge_valency), edge_relation)
    normalized_stiffness = spectral_projector_scale(laplacian, p_Fraction(1, edge_valency))
    local_diagonal_coefficient = p_Fraction(1)
    local_edge_coefficient = -local_diagonal_coefficient / edge_valency
    unique_local_operator = association_scheme_add(spectral_projector_scale(identity, local_diagonal_coefficient), spectral_projector_scale(edge_relation, local_edge_coefficient))
    assert unique_local_operator == normalized_stiffness
    channel_rows = []
    green = spectral_projector_zero(size, size)
    for index, projector in enumerate(projectors):
        stiffness_eigenvalue = (p_Fraction(edge_valency) - characters[index][1]) / p_Fraction(edge_valency)
        is_constant = index == constant_index
        if is_constant:
            assert stiffness_eigenvalue == 0
            response_residue = p_Fraction(0)
        else:
            assert stiffness_eigenvalue > 0
            response_residue = p_Fraction(1, 1) / stiffness_eigenvalue
            green = association_scheme_add(green, spectral_projector_scale(projector, response_residue))
        channel_rows.append({'PROJECTOR_INDEX': index, 'PROJECTOR_RANK': association_scheme_rank(projector), 'IS_CONSTANT_MODE': is_constant, 'EDGE_CHARACTER': characters[index][1], 'NORMALIZED_STIFFNESS_EIGENVALUE': stiffness_eigenvalue, 'GREEN_RESIDUE': response_residue, 'ANTIPODAL_PARITY': characters[index][4], 'FULL_RELATION_SIGNATURE': characters[index]})
    constant_projector = projectors[constant_index]
    physical_identity = association_scheme_subtract(identity, constant_projector)
    assert association_scheme_multiply(normalized_stiffness, green) == physical_identity
    assert association_scheme_multiply(green, normalized_stiffness) == physical_identity
    assert association_scheme_multiply(green, constant_projector) == spectral_projector_zero(size, size)
    invariant_physical_kernel_dimension = len(nontrivial_indices)
    coefficient_ratio_freedom = invariant_physical_kernel_dimension - 1
    nontrivial_signatures = tuple((channel_rows[index]['FULL_RELATION_SIGNATURE'] for index in nontrivial_indices))
    full_signatures_are_distinct = len(set(nontrivial_signatures)) == len(nontrivial_signatures)
    local_eigenvalues = tuple((channel_rows[index]['NORMALIZED_STIFFNESS_EIGENVALUE'] for index in nontrivial_indices))
    local_distinct_eigenvalue_count = len(set(local_eigenvalues))
    checks = {'RANGE_ONE_AUTOMORPHISM_INVARIANT_ZERO_SUM_ACTION_RAY_IS_UNIQUE': local_diagonal_coefficient + edge_valency * local_edge_coefficient == 0, 'NORMALIZED_LOCAL_ACTION_EQUALS_GRAPH_LAPLACIAN_OVER_DEGREE': unique_local_operator == normalized_stiffness, 'CONSTANT_MODE_IS_THE_ONLY_ZERO_MODE': sum((row['NORMALIZED_STIFFNESS_EIGENVALUE'] == 0 for row in channel_rows)) == 1, 'ALL_FOUR_NONTRIVIAL_CHANNEL_STIFFNESSES_ARE_POSITIVE': all((channel_rows[index]['NORMALIZED_STIFFNESS_EIGENVALUE'] > 0 for index in nontrivial_indices)), 'GREEN_OPERATOR_IS_EXACT_PHYSICAL_INVERSE': association_scheme_multiply(normalized_stiffness, green) == physical_identity and association_scheme_multiply(green, normalized_stiffness) == physical_identity, 'EVERY_RESPONSE_RESIDUE_IS_POSITIVE': all((channel_rows[index]['GREEN_RESIDUE'] > 0 for index in nontrivial_indices)), 'NO_NEGATIVE_STIFFNESS_TACHYON_ON_PHYSICAL_SUBSPACE': all((channel_rows[index]['NORMALIZED_STIFFNESS_EIGENVALUE'] > 0 for index in nontrivial_indices)), 'FOUR_CHANNELS_ARE_DISTINGUISHED_BY_FULL_RELATION_CHARACTERS': full_signatures_are_distinct, 'LOCAL_NEAREST_NEIGHBOR_ACTION_HAS_A_SPECTRAL_DEGENERACY': local_distinct_eigenvalue_count < len(nontrivial_indices), 'FULL_INVARIANT_KERNEL_HAS_FOUR_CHANNEL_COEFFICIENTS': invariant_physical_kernel_dimension == 4, 'GEOMETRY_ONLY_KERNEL_HAS_THREE_RATIO_COORDINATES_BEFORE_PARENT_ACTION_SELECTOR': coefficient_ratio_freedom == 3}
    assert all(checks.values())
