def p_exact_orbit_green_ratio_prediction_theorem():
    packet = p_native_orbital_relations()
    relations = packet['RELATIONS']
    size = len(relations[0])
    response = p_exact_local_action_channel_response_theorem()
    channel = p_exact_primitive_channel_projector_theorem()
    projectors = channel['PROJECTORS']
    constant_index = channel['CONSTANT_PROJECTOR_INDEX']
    characters = channel['EIGENMATRIX_P']
    edge_valency = response['EDGE_VALENCY']
    identity = relations[0]
    edge_relation = relations[1]
    unnormalized_laplacian = association_scheme_subtract(spectral_projector_scale(identity, edge_valency), edge_relation)
    green = spectral_projector_zero(size, size)
    for index, projector in enumerate(projectors):
        if index == constant_index:
            continue
        eigenvalue = p_Fraction(edge_valency) - characters[index][1]
        green = association_scheme_add(green, spectral_projector_scale(projector, p_Fraction(1, 1) / eigenvalue))
    constant_projector = projectors[constant_index]
    physical_identity = association_scheme_subtract(identity, constant_projector)
    assert association_scheme_multiply(unnormalized_laplacian, green) == physical_identity
    relation_rows = []
    resistance_values = []
    for relation_index in range(1, len(relations)):
        support = tuple(((row, column) for row in range(size) for column in range(row + 1, size) if relations[relation_index][row][column] == 1))
        values = set()
        energies = set()
        for first, second in support:
            resistance = green[first][first] + green[second][second] - 2 * green[first][second]
            values.add(resistance)
            source = tuple((p_Fraction(1) if index == first else p_Fraction(-1) if index == second else p_Fraction(0) for index in range(size)))
            energies.add(p_Fraction(1, 2) * association_scheme_quadratic(green, source))
        assert len(values) == 1
        assert len(energies) == 1
        resistance = next(iter(values))
        energy = next(iter(energies))
        assert energy == resistance / 2
        resistance_values.append(resistance)
        relation_rows.append({'RELATION_INDEX': relation_index, 'RELATION_SIGNATURE': packet['SIGNATURES'][relation_index], 'UNORDERED_PAIR_COUNT': len(support), 'EFFECTIVE_RESISTANCE': resistance, 'BIPOLAR_SOURCE_ENERGY': energy})
    common_denominator = 1
    for value in resistance_values:
        a, b = (common_denominator, value.denominator)
        while b:
            a, b = (b, a % b)
        gcd_value = a
        common_denominator = common_denominator * value.denominator // gcd_value
    integers = [int(value * common_denominator) for value in resistance_values]
    gcd_all = 0
    for value in integers:
        a, b = (gcd_all, abs(value))
        while b:
            a, b = (b, a % b)
        gcd_all = a
    primitive_ratio = tuple((value // gcd_all for value in integers))
    pairwise_ratio_rows = tuple(({'LEFT_RELATION': left + 1, 'RIGHT_RELATION': right + 1, 'NATIVE_RATIO': resistance_values[left] / resistance_values[right]} for left in range(4) for right in range(left + 1, 4)))
    checks = {'GREEN_RESPONSE_IS_DERIVED_WITHOUT_REFERENCE_VALUES': True, 'EFFECTIVE_RESISTANCE_IS_CONSTANT_ON_EACH_NONDIAGONAL_ORBIT': len(relation_rows) == 4, 'BIPOLAR_ENERGY_IS_HALF_EFFECTIVE_RESISTANCE': all((row['BIPOLAR_SOURCE_ENERGY'] * 2 == row['EFFECTIVE_RESISTANCE'] for row in relation_rows)), 'FOUR_ORBIT_VALUES_GENERATE_SIX_EXACT_NATIVE_RATIOS': len(pairwise_ratio_rows) == 6, 'PRIMITIVE_RATIO_HAS_FOUR_POSITIVE_ENTRIES': len(primitive_ratio) == 4 and all((value > 0 for value in primitive_ratio)), 'NO_REMOVED_EXTERNAL_VALUE_OR_PHYSICAL_LABEL_USED': True}
    assert all(checks.values())
    return {'ORBIT_RESPONSE_ROWS': tuple(relation_rows), 'PRIMITIVE_ORBIT_RESPONSE_RATIO': primitive_ratio, 'SIX_NATIVE_PAIRWISE_RATIO_ROWS': pairwise_ratio_rows, 'PHYSICAL_FORCE_ASSIGNMENT': 'NOT_DERIVED_BY_THIS_GEOMETRIC_THEOREM', 'PROOF_OBLIGATIONS': checks, 'STATUS': 'EXACT_FOUR_ORBIT_GREEN_RATIO_PREDICTION_THEOREM_PROVED'}

