def gauge_polynomial_inverse(matrix):
    source = [list(map(p_Fraction, row)) for row in matrix]
    size = len(source)
    assert all((len(row) == size for row in source))
    augmented = [source[row] + [p_Fraction(1) if row == column else p_Fraction(0) for column in range(size)] for row in range(size)]
    for column in range(size):
        pivot = next((row for row in range(column, size) if augmented[row][column] != 0), None)
        if pivot is None:
            raise AssertionError('matrix must be invertible')
        augmented[column], augmented[pivot] = (augmented[pivot], augmented[column])
        divisor = augmented[column][column]
        augmented[column] = [entry / divisor for entry in augmented[column]]
        for row in range(size):
            if row == column:
                continue
            factor = augmented[row][column]
            if factor != 0:
                augmented[row] = [augmented[row][index] - factor * augmented[column][index] for index in range(2 * size)]
    inverse = tuple((tuple(row[size:]) for row in augmented))
    assert association_scheme_multiply(tuple((tuple(row) for row in source)), inverse) == association_scheme_identity(size)
    return inverse

def gauge_polynomial_column_projector(columns):
    column_tuple = tuple((tuple((p_Fraction(value) for value in column)) for column in columns))
    row_count = len(column_tuple[0])
    column_count = len(column_tuple)
    basis_matrix = tuple((tuple((column_tuple[column][row] for column in range(column_count))) for row in range(row_count)))
    transpose = association_scheme_transpose(basis_matrix)
    gram = association_scheme_multiply(transpose, basis_matrix)
    gram_inverse = gauge_polynomial_inverse(gram)
    projector = association_scheme_multiply(association_scheme_multiply(basis_matrix, gram_inverse), transpose)
    assert association_scheme_multiply(projector, projector) == projector
    assert association_scheme_transpose(projector) == projector
    assert association_scheme_rank(projector) == column_count
    return projector

def gauge_polynomial_poly_degree(polynomial):
    degrees = {sum(exponents) for exponents, coefficient in polynomial.items() if coefficient != 0}
    assert len(degrees) == 1
    return next(iter(degrees))

def gauge_polynomial_poly_laplacian(polynomial):
    result = {}
    for exponents, coefficient in polynomial.items():
        for axis in range(3):
            power = exponents[axis]
            if power < 2:
                continue
            lowered = list(exponents)
            lowered[axis] -= 2
            lowered = tuple(lowered)
            result[lowered] = result.get(lowered, p_Fraction(0)) + p_Fraction(coefficient) * power * (power - 1)
    return {exponents: coefficient for exponents, coefficient in result.items() if coefficient != 0}

def gauge_polynomial_poly_value(polynomial, vertex):
    value = p_Fraction(0)
    for exponents, coefficient in polynomial.items():
        term = p_Fraction(coefficient)
        for axis in range(3):
            term *= p_Fraction(vertex[axis]) ** exponents[axis]
        value += term
    return value

def gauge_polynomial_poly(*terms):
    result = {}
    for coefficient, exponents in terms:
        exponents = tuple(exponents)
        result[exponents] = result.get(exponents, p_Fraction(0)) + p_Fraction(coefficient)
    return {exponents: coefficient for exponents, coefficient in result.items() if coefficient != 0}

