    expected_parity = {'A1G_SCALAR': 1, 'T1U_VECTOR': -1, 'EG_DIAGONAL_QUADRUPOLE': 1, 'T2G_OFFDIAGONAL_QUADRUPOLE': 1, 'T2U_CUBIC': -1}
