    assert all((association_scheme_multiply(family_projectors[left], family_projectors[right]) == (spectral_projector_zero(len(vertices), len(vertices)) if left != right else family_projectors[left]) for left in family_projectors for right in family_projectors))
    spin_two_projector = association_scheme_add(family_projectors['EG_DIAGONAL_QUADRUPOLE'], family_projectors['T2G_OFFDIAGONAL_QUADRUPOLE'])
