def rational_kernel_nullspace(matrix):
    work = [list(map(p_Fraction, row)) for row in matrix]
    if not work:
        return tuple()
    row_count = len(work)
    column_count = len(work[0])
    pivot_columns = []
    pivot_row = 0
    for pivot_column in range(column_count):
        selected = next((row for row in range(pivot_row, row_count) if work[row][pivot_column] != 0), None)
        if selected is None:
            continue
        work[pivot_row], work[selected] = (work[selected], work[pivot_row])
        pivot = work[pivot_row][pivot_column]
        work[pivot_row] = [entry / pivot for entry in work[pivot_row]]
        for row in range(row_count):
            if row == pivot_row or work[row][pivot_column] == 0:
                continue
            factor = work[row][pivot_column]
            work[row] = [work[row][column] - factor * work[pivot_row][column] for column in range(column_count)]
        pivot_columns.append(pivot_column)
        pivot_row += 1
        if pivot_row == row_count:
            break
    free_columns = [column for column in range(column_count) if column not in pivot_columns]
    basis = []
    for free_column in free_columns:
        vector = [p_Fraction(0) for _ in range(column_count)]
        vector[free_column] = p_Fraction(1)
        for row, pivot_column in enumerate(pivot_columns):
            vector[pivot_column] = -work[row][free_column]
        basis.append(tuple(vector))
    return tuple(basis)

def primitive_charge_primitive_integer_vector(vector):
    denominators = [p_Fraction(entry).denominator for entry in vector]
    common = 1
    for denominator in denominators:
        common = common * denominator // p_math.gcd(common, denominator)
    integers = [int(p_Fraction(entry) * common) for entry in vector]
    divisor = 0
    for integer in integers:
        divisor = p_math.gcd(divisor, abs(integer))
    if divisor:
        integers = [integer // divisor for integer in integers]
    first_nonzero = next((integer for integer in integers if integer != 0), 1)
    if first_nonzero < 0:
        integers = [-integer for integer in integers]
    return tuple(integers)

