    constraint_names = ('UP_YUKAWA_U1_INVARIANCE', 'DOWN_YUKAWA_U1_INVARIANCE', 'CHARGED_LEPTON_YUKAWA_U1_INVARIANCE', 'SU3_SQUARED_U1_ANOMALY_CANCELLATION', 'SU2_SQUARED_U1_ANOMALY_CANCELLATION', 'GRAVITY_SQUARED_U1_ANOMALY_CANCELLATION')
