    assert all(checks.values())
    return {'FIELD_ORDER': labels, 'CONSTRAINT_ORDER': constraint_names, 'CONSTRAINT_MATRIX': constraints, 'CONSTRAINT_RANK': association_scheme_rank(constraints), 'NULLSPACE_DIMENSION': len(nullspace), 'PRIMITIVE_INTEGER_HYPERCHARGE_RAY': primitive, 'LINEAR_CONSTRAINT_RESIDUALS': linear_residuals, 'CUBIC_U1_ANOMALY': cubic_u1, 'CUBIC_SU3_ANOMALY': su3_cubic, 'LEFT_WEAK_DOUBLET_COUNT': weak_doublet_count, 'PROOF_OBLIGATIONS': checks, 'STATUS': 'EXACT_MINIMAL_CHIRAL_HYPERCHARGE_RAY_PROVED'}
