class _LaurentPolynomial:
    __slots__ = ('terms', 'variable_names')

    def __init__(self, terms=None, variable_names=()):
        self.variable_names = tuple(variable_names)
        cleaned = {}
        for exponent, coefficient in (terms or {}).items():
            coefficient = Fraction(coefficient)
            exponent = tuple((Fraction(value) for value in exponent))
            if coefficient:
                cleaned[exponent] = cleaned.get(exponent, Fraction(0)) + coefficient
        self.terms = {exponent: coefficient for exponent, coefficient in cleaned.items() if coefficient}

    @classmethod
    def constant(cls, value, variable_names):
        return cls({(Fraction(0),) * len(variable_names): Fraction(value)}, variable_names)

    @classmethod
    def monomial(cls, coefficient, exponents, variable_names):
        return cls({tuple((Fraction(value) for value in exponents)): Fraction(coefficient)}, variable_names)

    def __add__(self, other):
        if not isinstance(other, _LaurentPolynomial):
            other = self.constant(other, self.variable_names)
        result = dict(self.terms)
        for exponent, coefficient in other.terms.items():
            result[exponent] = result.get(exponent, Fraction(0)) + coefficient
        return _LaurentPolynomial(result, self.variable_names)
    __radd__ = __add__

    def __neg__(self):
        return _LaurentPolynomial({exponent: -coefficient for exponent, coefficient in self.terms.items()}, self.variable_names)

    def __sub__(self, other):
        return self + -other

    def __rsub__(self, other):
        return -self + other

    def __mul__(self, other):
        if not isinstance(other, _LaurentPolynomial):
            other = self.constant(other, self.variable_names)
        result = {}
        for left_exponent, left_coefficient in self.terms.items():
            for right_exponent, right_coefficient in other.terms.items():
                exponent = tuple((a + b for a, b in zip(left_exponent, right_exponent)))
                result[exponent] = result.get(exponent, Fraction(0)) + left_coefficient * right_coefficient
        return _LaurentPolynomial(result, self.variable_names)
    __rmul__ = __mul__

    def derivative(self, variable_index):
        result = {}
        for exponent, coefficient in self.terms.items():
            power = exponent[variable_index]
            if power:
                reduced = list(exponent)
                reduced[variable_index] -= 1
                reduced = tuple(reduced)
                result[reduced] = result.get(reduced, Fraction(0)) + coefficient * power
        return _LaurentPolynomial(result, self.variable_names)

    def canonical_rows(self):
        rows = []
        for exponent in sorted(self.terms, key=lambda item: tuple((float(value) for value in item))):
            coefficient = self.terms[exponent]
            factors = []
            for name, power in zip(self.variable_names, exponent):
                if power == 0:
                    continue
                factors.append(f'{name}^{power}')
            rows.append((coefficient, tuple(factors)))
        return tuple(rows)

    def __eq__(self, other):
        if not isinstance(other, _LaurentPolynomial):
            other = self.constant(other, self.variable_names)
        return self.terms == other.terms

def _gcd(a, b):
    a, b = (abs(int(a)), abs(int(b)))
    while b:
        a, b = (b, a % b)
    return a

def _primitive(values):
    divisor = 0
    for value in values:
        divisor = _gcd(divisor, value)
    divisor = divisor or 1
    return tuple((int(value) // divisor for value in values))

