def _pclean(p):
    return {m: c for m, c in p.items() if c}

def _pconst(c):
    return {} if c == 0 else {(): int(c)}

def _pvar(name):
    return {(str(name),): 1}

def _padd(a, b):
    out = dict(a)
    for m, c in b.items():
        out[m] = out.get(m, 0) + c
    return _pclean(out)

def _pscale(a, c):
    return _pclean({m: c * v for m, v in a.items()})

def _pmul(a, b):
    out = {}
    for ma, ca in a.items():
        for mb, cb in b.items():
            monomial = tuple(sorted(ma + mb))
            out[monomial] = out.get(monomial, 0) + ca * cb
    return _pclean(out)

def _pdiff(a, variable):
    out = {}
    for monomial, coefficient in a.items():
        count = monomial.count(variable)
        if count:
            reduced = list(monomial)
            reduced.remove(variable)
            reduced = tuple(reduced)
            out[reduced] = out.get(reduced, 0) + coefficient * count
    return _pclean(out)

def _perm_sign(p):
    inversions = sum((1 for i in range(len(p)) for j in range(i + 1, len(p)) if p[i] > p[j]))
    return -1 if inversions % 2 else 1

def _det_poly(matrix):
    n = len(matrix)
    total = {}
    for permutation in itertools.permutations(range(n)):
        term = _pconst(_perm_sign(permutation))
        for row in range(n):
            term = _pmul(term, matrix[row][permutation[row]])
        total = _padd(total, term)
    return total

def _minor(matrix, row, column):
    return [[matrix[i][j] for j in range(len(matrix)) if j != column] for i in range(len(matrix)) if i != row]

def _cofactor(matrix, row, column):
    return _pscale(_det_poly(_minor(matrix, row, column)), -1 if (row + column) % 2 else 1)

def _generic_symmetric_matrix(prefix):
    variables = []
    names = {}
    for i in range(4):
        for j in range(i, 4):
            name = f'{prefix}{i}{j}'
            variables.append(name)
            names[i, j] = name
            names[j, i] = name
    return ([[_pvar(names[i, j]) for j in range(4)] for i in range(4)], tuple(variables), names)

def _word_reduce(word):
    current = tuple(word)
    changed = True
    while changed:
        changed = False
        reduced = []
        index = 0
        while index < len(current):
            if index + 1 < len(current) and current[index:index + 2] in (('G', 'Gi'), ('Gi', 'G')):
                changed = True
                index += 2
            else:
                reduced.append(current[index])
                index += 1
        current = tuple(reduced)
    return current

