def _matrix_fraction_rank(matrix):
    a = [[Fraction(value) for value in row] for row in matrix]
    rows = len(a)
    columns = len(a[0]) if rows else 0
    rank = 0
    for column in range(columns):
        pivot = next((row for row in range(rank, rows) if a[row][column] != 0), None)
        if pivot is None:
            continue
        a[rank], a[pivot] = (a[pivot], a[rank])
        scale = a[rank][column]
        a[rank] = [value / scale for value in a[rank]]
        for row in range(rows):
            if row != rank and a[row][column] != 0:
                factor = a[row][column]
                a[row] = [a[row][j] - factor * a[rank][j] for j in range(columns)]
        rank += 1
        if rank == rows:
            break
    return rank

def _matmul_fraction_branch_a(a, b):
    return [[sum((a[i][k] * b[k][j] for k in range(len(b))), Fraction(0)) for j in range(len(b[0]))] for i in range(len(a))]

def _permutation_matrix(p):
    n = len(p)
    return [[Fraction(int(p[j] == i)) for j in range(n)] for i in range(n)]

def _commutant_system(generators):
    n = len(generators[0])
    equations = []
    for generator in generators:
        for i in range(n):
            for j in range(n):
                row = [Fraction(0) for _ in range(n * n)]
                for k in range(n):
                    row[i * n + k] += generator[k][j]
                    row[k * n + j] -= generator[i][k]
                equations.append(row)
    return equations

