def _gcd_branch_b(a, b):
    a, b = (abs(int(a)), abs(int(b)))
    while b:
        a, b = (b, a % b)
    return a

def _primitive_vector(values):
    values = tuple((int(value) for value in values))
    divisor = 0
    for value in values:
        divisor = _gcd_branch_b(divisor, value)
    if divisor == 0:
        return values
    reduced = tuple((value // divisor for value in values))
    for value in reduced:
        if value:
            return reduced if value > 0 else tuple((-entry for entry in reduced))
    return reduced

