def _mat_transpose(matrix):
    return tuple((tuple((matrix[row][column] for row in range(len(matrix)))) for column in range(len(matrix[0]))))

def _mat_multiply(left, right):
    right_t = _mat_transpose(right)
    return tuple((tuple((sum((a * b for a, b in zip(row, column)), Fraction(0)) for column in right_t)) for row in left))

def _mat_add(left, right):
    return tuple((tuple((left[i][j] + right[i][j] for j in range(len(left[0])))) for i in range(len(left))))

def _mat_subtract(left, right):
    return tuple((tuple((left[i][j] - right[i][j] for j in range(len(left[0])))) for i in range(len(left))))

def _determinant_branch_b(matrix):
    size = len(matrix)
    if size == 0:
        return Fraction(1)
    if size == 1:
        return Fraction(matrix[0][0])
    total = Fraction(0)
    for column in range(size):
        minor = tuple((tuple((matrix[row][other] for other in range(size) if other != column)) for row in range(1, size)))
        total += (Fraction(1) if column % 2 == 0 else Fraction(-1)) * matrix[0][column] * _determinant_branch_b(minor)
    return total

def _principal_minors(matrix):
    return tuple((_determinant_branch_b(tuple((tuple((matrix[i][j] for j in range(size))) for i in range(size)))) for size in range(1, len(matrix) + 1)))

def _charpoly3(matrix):
    trace = sum((matrix[i][i] for i in range(3)), Fraction(0))
    quadratic = matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0] + matrix[0][0] * matrix[2][2] - matrix[0][2] * matrix[2][0] + matrix[1][1] * matrix[2][2] - matrix[1][2] * matrix[2][1]
    return (Fraction(1), -trace, quadratic, -_determinant_branch_b(matrix))

def _cubic_discriminant_branch_b(coefficients):
    one, a, b, c = coefficients
    assert one == 1
    return a * a * b * b - 4 * b * b * b - 4 * a * a * a * c - 27 * c * c + 18 * a * b * c

