def _complete_native_shell_threshold_ratio_theorem(maximum_atomic_number=118):
    capacities = tuple((2 * n * n for n in range(1, 9)))
    rows = []
    closure_points = []
    remaining = 0
    shell_index = 1
    integrated = 0
    for atomic_number in range(1, maximum_atomic_number + 1):
        while atomic_number > integrated + capacities[shell_index - 1]:
            integrated += capacities[shell_index - 1]
            shell_index += 1
        occupancy = atomic_number - integrated
        capacity = capacities[shell_index - 1]
        threshold = Fraction(occupancy, shell_index * shell_index)
        closed_threshold = Fraction(capacity, shell_index * shell_index)
        normalized_ratio = threshold / closed_threshold
        rows.append((atomic_number, shell_index, occupancy, capacity, threshold, normalized_ratio))
        if occupancy == capacity:
            closure_points.append((atomic_number, shell_index, normalized_ratio))
