    for atomic_number, shell, ratio in closure_points:
        if atomic_number < maximum_atomic_number:
            next_row = rows[atomic_number]
            transitions.append((atomic_number, shell, ratio, next_row[0], next_row[1], next_row[5], next_row[5] < ratio))
