def _unique_native_family_selector_theorem():
    zero = Fraction(0)
    one = Fraction(1)
    cycle_symmetric = ((zero, one, one), (one, zero, one), (one, one, zero))
    parity = ((one, zero, zero), (zero, -one, zero), (zero, zero, one))
