            relation = tuple((tuple((Fraction(a) * cycle_symmetric[i][j] + Fraction(b) * parity_conjugate[i][j] for j in range(3))) for i in range(3)))
            transformed = _mat_multiply(_mat_multiply(parity, relation), parity)
