def _render_branch_d(value, prefix=''):
    lines = []
    if isinstance(value, dict):
        for key in sorted(value, key=str):
            current = f'{prefix}{key}'
            nested = value[key]
            if isinstance(nested, (dict, tuple, list)):
                lines.append(f'{current}:')
                lines.extend(_render_branch_d(nested, current + '.'))
            else:
                lines.append(f'{current} = {_exact_scalar_text(nested)}')
    elif isinstance(value, (tuple, list)):
        for index, nested in enumerate(value):
            current = f'{prefix}{index}'
            if isinstance(nested, (dict, tuple, list)):
                lines.append(f'{current}:')
                lines.extend(_render_branch_d(nested, current + '.'))
            else:
                lines.append(f'{current} = {_exact_scalar_text(nested)}')
    else:
        lines.append(f'{prefix} = {_exact_scalar_text(value)}')
    return lines
