def _gauss(re=0, im=0):
    return (Fraction(re), Fraction(im))

def _gadd(a, b):
    return (a[0] + b[0], a[1] + b[1])

def _gsub(a, b):
    return (a[0] - b[0], a[1] - b[1])

def _gmul(a, b):
    return (a[0] * b[0] - a[1] * b[1], a[0] * b[1] + a[1] * b[0])

def _gscale(c, a):
    return (Fraction(c) * a[0], Fraction(c) * a[1])

def _gconj(a):
    return (a[0], -a[1])

def _gdiv_i(a):
    return (a[1], -a[0])

def _gsum(values):
    total = _gauss()
    for value in values:
        total = _gadd(total, value)
    return total

def _gmatmul(a, b):
    bt = tuple(zip(*b))
    return tuple((tuple((_gsum((_gmul(x, y) for x, y in zip(row, column))) for column in bt)) for row in a))

def _gmatsub(a, b):
    return tuple((tuple((_gsub(a[i][j], b[i][j]) for j in range(len(a[0])))) for i in range(len(a))))

def _gtrace(a):
    return _gsum((a[i][i] for i in range(len(a))))

def _gdet(matrix):
    size = len(matrix)
    if size == 0:
        return _gauss(1)
    if size == 1:
        return matrix[0][0]
    total = _gauss()
    for column in range(size):
        minor = tuple((tuple((matrix[row][other] for other in range(size) if other != column)) for row in range(1, size)))
        term = _gmul(matrix[0][column], _gdet(minor))
        total = _gadd(total, term if column % 2 == 0 else _gscale(-1, term))
    return total

def _gcharpoly3(matrix):
    trace = _gtrace(matrix)
    assert trace[1] == 0
    quadratic = _gauss()
    for i, j in ((0, 1), (0, 2), (1, 2)):
        determinant = _gsub(_gmul(matrix[i][i], matrix[j][j]), _gmul(matrix[i][j], matrix[j][i]))
        quadratic = _gadd(quadratic, determinant)
    determinant = _gdet(matrix)
    assert quadratic[1] == 0 and determinant[1] == 0
    return (Fraction(1), -trace[0], quadratic[0], -determinant[0])

