    augmented = [[columns[j][i] for j in range(column_count)] + [target[i]] for i in range(row_count)]
    pivot_row = 0
    pivot_columns = []
    for column in range(column_count):
        pivot = next((row for row in range(pivot_row, row_count) if augmented[row][column] != 0), None)
        if pivot is None:
            continue
        augmented[pivot_row], augmented[pivot] = (augmented[pivot], augmented[pivot_row])
        scale = augmented[pivot_row][column]
        augmented[pivot_row] = [value / scale for value in augmented[pivot_row]]
