def _monomial_value(exponents, point):
    value = Fraction(1)
    for exponent, coordinate in zip(exponents, point):
        value *= coordinate ** exponent
    return value

def _monomial_derivative(exponents, point, axis, order=1):
    exponent = exponents[axis]
    if exponent < order:
        return Fraction(0)
    coefficient = Fraction(1)
    for step in range(order):
        coefficient *= exponent - step
    lowered = list(exponents)
    lowered[axis] -= order
    return coefficient * _monomial_value(tuple(lowered), point)

def _shift_point(point, axis, delta):
    shifted = list(point)
    shifted[axis] += delta
    return tuple(shifted)

def _forward_difference(exponents, point, axis, step):
    return (_monomial_value(exponents, _shift_point(point, axis, step)) - _monomial_value(exponents, point)) / step

def _central_second_difference(exponents, point, axis, step):
    plus = _monomial_value(exponents, _shift_point(point, axis, step))
    center = _monomial_value(exponents, point)
    minus = _monomial_value(exponents, _shift_point(point, axis, -step))
    return (plus - 2 * center + minus) / (step * step)

