def _geometry_matrix_power(a, n):
    result = _geometry_matrix_identity(len(a))
    base = tuple((tuple((Fraction(v) for v in row)) for row in a))
    exponent = int(n)
    while exponent:
        if exponent & 1:
            result = _geometry_matrix_matmul(result, base)
        base = _geometry_matrix_matmul(base, base)
        exponent //= 2
    return result

