def _geometry_matrix_inverse(a):
    n = len(a)
    aug = [list((Fraction(v) for v in row)) + [Fraction(int(i == j)) for j in range(n)] for i, row in enumerate(a)]
    for col in range(n):
        pivot = next((row for row in range(col, n) if aug[row][col] != 0), None)
        if pivot is None:
            raise ZeroDivisionError('singular matrix')
        aug[col], aug[pivot] = (aug[pivot], aug[col])
        divisor = aug[col][col]
        aug[col] = [value / divisor for value in aug[col]]
