def _z(real=0, imag=0):
    return (Fraction(real), Fraction(imag))

def _z794_add(left, right):
    return (left[0] + right[0], left[1] + right[1])

def _z794_sub(left, right):
    return (left[0] - right[0], left[1] - right[1])

def _z794_mul(left, right):
    return (left[0] * right[0] - left[1] * right[1], left[0] * right[1] + left[1] * right[0])

def _z794_scale(scale, value):
    scale = Fraction(scale)
    return (scale * value[0], scale * value[1])

def _z794_conj(value):
    return (value[0], -value[1])

def _zm794_identity(size):
    return tuple((tuple((_z(int(i == j), 0) for j in range(size))) for i in range(size)))

def _zm794_add(left, right):
    return tuple((tuple((_z794_add(left[i][j], right[i][j]) for j in range(len(left[0])))) for i in range(len(left))))

