def _rref_branch_a(matrix):
    values = [list(map(Fraction, row)) for row in matrix]
    if not values:
        return (tuple(), tuple())
    rows = len(values)
    cols = len(values[0])
    pivots = []
    pivot_row = 0
    for column in range(cols):
        selected = None
        for row in range(pivot_row, rows):
            if values[row][column] != 0:
                selected = row
                break
        if selected is None:
            continue
        values[pivot_row], values[selected] = (values[selected], values[pivot_row])
        pivot = values[pivot_row][column]
        values[pivot_row] = [entry / pivot for entry in values[pivot_row]]
        for row in range(rows):
            if row == pivot_row:
                continue
            factor = values[row][column]
            if factor != 0:
                values[row] = [values[row][index] - factor * values[pivot_row][index] for index in range(cols)]
        pivots.append(column)
        pivot_row += 1
        if pivot_row == rows:
            break
    return (tuple((tuple(row) for row in values)), tuple(pivots))

def _integer_null_vector(matrix):
    reduced, pivots = _rref_branch_a(matrix)
    columns = len(matrix[0])
    free = tuple((column for column in range(columns) if column not in pivots))
