def _row_stochastic_kernel(channel_count: int, diagonal_weight: int):
    if channel_count <= 1 or diagonal_weight <= 0:
        raise ValueError('positive channel count and diagonal weight required')
    denominator = diagonal_weight + channel_count - 1
    return tuple((tuple((Fraction(diagonal_weight if i == j else 1, denominator) for j in range(channel_count))) for i in range(channel_count)))

def _kernel_rowsum(kernel):
    return tuple((sum(row, Fraction(0)) for row in kernel))

def _matmul_fraction_branch_b(a, b):
    return tuple((tuple((sum((a[i][k] * b[k][j] for k in range(len(b))), Fraction(0)) for j in range(len(b[0])))) for i in range(len(a))))

def _matrix_power(matrix, exponent: int):
    n = len(matrix)
    result = tuple((tuple((Fraction(int(i == j), 1) for j in range(n))) for i in range(n)))
    base = matrix
    e = exponent
    while e:
        if e % 2:
            result = _matmul_fraction_branch_b(result, base)
        base = _matmul_fraction_branch_b(base, base)
        e //= 2
    return result

def _cylinder_weight(initial, kernel, path):
    if not path:
        return Fraction(1)
    weight = initial[path[0]]
    for left, right in zip(path, path[1:]):
        weight *= kernel[left][right]
    return weight

