def _tensor_matrix_identity(size):
    return tuple((tuple((Fraction(int(i == j)) for j in range(size))) for i in range(size)))

def _tensor_matrix_transpose(matrix):
    return tuple((tuple((matrix[j][i] for j in range(len(matrix)))) for i in range(len(matrix[0]))))

def _tensor_matrix_add(left, right):
    return tuple((tuple((left[i][j] + right[i][j] for j in range(len(left[0])))) for i in range(len(left))))

def _tensor_matrix_subtract(left, right):
    return tuple((tuple((left[i][j] - right[i][j] for j in range(len(left[0])))) for i in range(len(left))))

def _tensor_matrix_scale(scale, matrix):
    scale = Fraction(scale)
    return tuple((tuple((scale * value for value in row)) for row in matrix))

def _tensor_matrix_vec(matrix, vector):
    return tuple((sum((matrix[i][j] * vector[j] for j in range(len(vector))), Fraction(0)) for i in range(len(matrix))))

def _tensor_matrix_dot(left, right):
    return sum((left[i] * right[i] for i in range(len(left))), Fraction(0))

def _tensor_matrix_kron(left, right):
    return tuple((tuple((left[i][j] * right[a][b] for j in range(len(left[0])) for b in range(len(right[0])))) for i in range(len(left)) for a in range(len(right))))

def _tensor_matrix_power_tensor(single_site, level):
    if level < 1:
        raise ValueError('positive cylinder level required')
    result = single_site
    for _ in range(1, level):
        result = _tensor_matrix_kron(result, single_site)
    return result

def _tensor_matrix_inverse(matrix):
    size = len(matrix)
    augmented = [list(matrix[i]) + list(_tensor_matrix_identity(size)[i]) for i in range(size)]
    for column in range(size):
        pivot = next((row for row in range(column, size) if augmented[row][column] != 0), None)
        if pivot is None:
            raise ValueError('singular exact matrix')
        if pivot != column:
            augmented[column], augmented[pivot] = (augmented[pivot], augmented[column])
        pivot_value = augmented[column][column]
        augmented[column] = [value / pivot_value for value in augmented[column]]
        for row in range(size):
            if row == column:
                continue
            factor = augmented[row][column]
            if factor:
                augmented[row] = [augmented[row][entry] - factor * augmented[column][entry] for entry in range(2 * size)]
    return tuple((tuple(augmented[i][size:]) for i in range(size)))

def _tensor_matrix_determinant(matrix):
    rows = [list(row) for row in matrix]
    size = len(rows)
    determinant = Fraction(1)
    for column in range(size):
        pivot = next((row for row in range(column, size) if rows[row][column] != 0), None)
        if pivot is None:
            return Fraction(0)
        if pivot != column:
            rows[column], rows[pivot] = (rows[pivot], rows[column])
            determinant = -determinant
        pivot_value = rows[column][column]
        determinant *= pivot_value
        for row in range(column + 1, size):
            factor = rows[row][column] / pivot_value
            if factor:
                for entry in range(column, size):
                    rows[row][entry] -= factor * rows[column][entry]
    return determinant

