def _weak_compositions(total, parts):
    if parts == 1:
        yield (total,)
        return
    for first in range(total + 1):
        for tail in _weak_compositions(total - first, parts - 1):
            yield ((first,) + tail)

def _factorial(value):
    result = 1
    for factor in range(2, value + 1):
        result *= factor
    return result

def _multinomial(counts):
    result = _factorial(sum(counts))
    for count in counts:
        result //= _factorial(count)
    return result

