def _expr_add(left, right, scale=Fraction(1)):
    out = dict(left)
    for key, value in right.items():
        out[key] = out.get(key, Fraction(0)) + scale * value
        if out[key] == 0:
            del out[key]
    return out

def _expr_shift_difference(expression, axis, dimension):
    out = {}
    for (origin, shift), coefficient in expression.items():
        moved = list(shift)
        moved[axis] += 1
        moved_key = (origin, tuple(moved))
        out[moved_key] = out.get(moved_key, Fraction(0)) + coefficient
        base_key = (origin, shift)
        out[base_key] = out.get(base_key, Fraction(0)) - coefficient
    return {key: value for key, value in out.items() if value}

def _basis_form(degree, dimension):
    zero = tuple((0 for _ in range(dimension)))
    return {component: {(component, zero): Fraction(1)} for component in itertools.combinations(range(dimension), degree)}

def _exterior_derivative(form, degree, dimension):
    if degree >= dimension:
        return {}
    out = {}
    for target in itertools.combinations(range(dimension), degree + 1):
        expression = {}
        for position, axis in enumerate(target):
            source = target[:position] + target[position + 1:]
            differentiated = _expr_shift_difference(form[source], axis, dimension)
            expression = _expr_add(expression, differentiated, Fraction(-1 if position % 2 else 1))
        out[target] = expression
    return out

def _form_add(left, right):
    keys = set(left) | set(right)
    return {key: _expr_add(left.get(key, {}), right.get(key, {})) for key in keys}

def _matrix_rank(matrix):
    rows = [list(row) for row in matrix]
    if not rows:
        return 0
    row_count = len(rows)
    column_count = len(rows[0])
    pivot_row = 0
    for column in range(column_count):
        pivot = next((row for row in range(pivot_row, row_count) if rows[row][column] != 0), None)
        if pivot is None:
            continue
        rows[pivot_row], rows[pivot] = (rows[pivot], rows[pivot_row])
        value = rows[pivot_row][column]
        rows[pivot_row] = [entry / value for entry in rows[pivot_row]]
        for row in range(row_count):
            if row != pivot_row and rows[row][column] != 0:
                factor = rows[row][column]
                rows[row] = [rows[row][index] - factor * rows[pivot_row][index] for index in range(column_count)]
        pivot_row += 1
        if pivot_row == row_count:
            break
    return pivot_row

