def _wedge_contraction(axis):
    dimension = len(TRANSFORMER_LAYER_LABELS)
    size = DUAL ** dimension
    wedge = [[Fraction(0) for _ in range(size)] for _ in range(size)]
    contraction = [[Fraction(0) for _ in range(size)] for _ in range(size)]
    lower_mask = (SHIFT << axis) - SHIFT
    for mask in range(size):
        lower_count = (mask & lower_mask).bit_count()
        sign = Fraction(-1 if lower_count % DUAL else 1)
        bit = SHIFT << axis
        if not mask & bit:
            wedge[mask | bit][mask] = sign
        if mask & bit:
            contraction[mask ^ bit][mask] = sign
    return (tuple((tuple(row) for row in wedge)), tuple((tuple(row) for row in contraction)))

