def _pclean_branch_b(p):
    p = [Fraction(v) for v in p]
    while len(p) > 1 and p[-1] == 0:
        p.pop()
    return tuple(p) if p else (Fraction(0),)

def _padd_branch_b(a, b):
    n = max(len(a), len(b))
    return _pclean_branch_b(tuple(((Fraction(a[i]) if i < len(a) else Fraction(0)) + (Fraction(b[i]) if i < len(b) else Fraction(0)) for i in range(n))))

def _psub(a, b):
    n = max(len(a), len(b))
    return _pclean_branch_b(tuple(((Fraction(a[i]) if i < len(a) else Fraction(0)) - (Fraction(b[i]) if i < len(b) else Fraction(0)) for i in range(n))))

def _pscale_branch_b(c, a):
    c = Fraction(c)
    return _pclean_branch_b(tuple((c * Fraction(v) for v in a)))

def _pmul_branch_b(a, b):
    out = [Fraction(0) for _ in range(len(a) + len(b) - 1)]
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            out[i + j] += Fraction(x) * Fraction(y)
    return _pclean_branch_b(tuple(out))

def _pder(a):
    if len(a) <= 1:
        return (Fraction(0),)
    return _pclean_branch_b(tuple((Fraction(i) * Fraction(a[i]) for i in range(1, len(a)))))

def _peval(a, x):
    x = Fraction(x)
    total = Fraction(0)
    for coefficient in reversed(a):
        total = total * x + Fraction(coefficient)
    return total

def _rmake(p, q=(Fraction(1),)):
    p = _pclean_branch_b(p)
    q = _pclean_branch_b(q)
    if all((v == 0 for v in q)):
        raise ZeroDivisionError('zero polynomial denominator')
    if q[-1] < 0:
        p = _pscale_branch_b(-1, p)
        q = _pscale_branch_b(-1, q)
    return (p, q)

def _rzero():
    return ((Fraction(0),), (Fraction(1),))

def _rone():
    return ((Fraction(1),), (Fraction(1),))

def _radd(a, b):
    return _rmake(_padd_branch_b(_pmul_branch_b(a[0], b[1]), _pmul_branch_b(b[0], a[1])), _pmul_branch_b(a[1], b[1]))

def _rsub(a, b):
    return _rmake(_psub(_pmul_branch_b(a[0], b[1]), _pmul_branch_b(b[0], a[1])), _pmul_branch_b(a[1], b[1]))

