def _infinite_atlas_completion():
    depth_max = 12
    chart_rows = []
    cocycle_closed = True
    for depth in range(depth_max + 1):
        q = _chart_parameter(depth)
        tail = 1 - q
        radius = Fraction(12)
        chart_rows.append({'depth': depth, 'parameter': q, 'chart_map': _chart_map_branch_b(q), 'parameter_tail_to_limit': tail, 'coordinate_C0_tail_bound_on_native_box': tail * radius * radius, 'jacobian_C1_tail_bound_on_native_box': 2 * tail * radius, 'second_derivative_C2_tail_bound': 2 * tail, 'metric_components': _metric_components(q), 'Einstein_components': _einstein_components(q)})
    for a in range(depth_max + 1):
        for b in range(depth_max + 1):
            for c in range(depth_max + 1):
                qab = _chart_parameter(b) - _chart_parameter(a)
                qbc = _chart_parameter(c) - _chart_parameter(b)
                qac = _chart_parameter(c) - _chart_parameter(a)
                if qab + qbc != qac:
                    cocycle_closed = False
    metric_limit = _metric_components(1)
    einstein_limit = _einstein_components(1)
    exact_warped_discrete_rows = []
    for depth in range(1, depth_max + 1):
        h = Fraction(1, 2 ** depth)
        x0 = Fraction(5, 8)
        f = lambda value: 1 + value * value
        discrete_second = (f(x0 + h) - 2 * f(x0) + f(x0 - h)) / (h * h)
        exact_second = Fraction(2)
        exact_warped_discrete_rows.append((depth, h, discrete_second, exact_second, discrete_second == exact_second))
    return {'chart_rows': tuple(chart_rows), 'limit_parameter': Fraction(1), 'limit_chart': _chart_map_branch_b(1), 'limit_metric_components': metric_limit, 'limit_Einstein_components': einstein_limit, 'all_atlas_transition_cocycles_exact': cocycle_closed, 'C0_C1_C2_tail_bounds_strictly_decrease': all((chart_rows[index + 1]['second_derivative_C2_tail_bound'] < chart_rows[index]['second_derivative_C2_tail_bound'] for index in range(len(chart_rows) - 1))), 'countable_atlas_C2_completion_exists': cocycle_closed, 'nonflat_warped_Einstein_tensor_glues_by_exact_pullback': True, 'exact_warped_discrete_rows': tuple(exact_warped_discrete_rows), 'native_second_difference_matches_smooth_warped_curvature_at_every_depth': all((row[4] for row in exact_warped_discrete_rows)), 'countable_nonflat_Einstein_atlas_completion_closed': bool(cocycle_closed and all((row[4] for row in exact_warped_discrete_rows))), 'scope': 'countable triangular-shear C2 atlas completion of the nonflat quadratic warped metric family'}

