def _new_layer_forbidden_call_scan_branch_i():
    functions = (_cadd, _cmul, _cconj, _cnorm, _cayley, _phase_completion, _word_displacement, _minimal_source, _normal_word, _reverse_word, _word_action, _presentation_completion, _p1clean, _p1add, _p1mul, _p1scale, _p1pow, _p1der, _chart_parameter, _chart_map_branch_b, _metric_components, _einstein_components, _infinite_atlas_completion, _completion_theorem_data_branch_b, _build_packet_branch_q)
    forbidden = {'log', 'exp', 'sin', 'cos', 'open', 'eval', 'exec', 'compile', 'input'}
    rows = []
    for function in functions:
        names = set(inspect.unwrap(function).__code__.co_names)
