def prove_zero_bipolar_origin_algebra() -> None:
    one = Fraction(1)
    zero = Fraction(0)
    identity = ((one, zero), (zero, one))
    parity = ((one, zero), (zero, -one))
    complex_structure = ((zero, -one), (one, zero))

    def mm(left, right):
        return tuple(tuple(sum(left[i][k] * right[k][j] for k in range(2)) for j in range(2)) for i in range(2))

    def add(left, right):
        return tuple(tuple(left[i][j] + right[i][j] for j in range(2)) for i in range(2))

    def scale(value, matrix):
        return tuple(tuple(value * matrix[i][j] for j in range(2)) for i in range(2))

    parity_square = mm(parity, parity)
    complex_square = mm(complex_structure, complex_structure)
    anticommutator = add(mm(parity, complex_structure), mm(complex_structure, parity))
    projector_plus = scale(Fraction(1, 2), add(identity, parity))
    projector_minus = scale(Fraction(1, 2), add(identity, scale(-one, parity)))
    checks = {
        'parity_involution': parity_square == identity,
        'trace_zero': parity[0][0] + parity[1][1] == zero,
        'complex_square_minus_identity': complex_square == scale(-one, identity),
        'parity_complex_anticommutation': anticommutator == ((zero, zero), (zero, zero)),
        'projector_plus_idempotent': mm(projector_plus, projector_plus) == projector_plus,
        'projector_minus_idempotent': mm(projector_minus, projector_minus) == projector_minus,
        'projector_orthogonality': mm(projector_plus, projector_minus) == ((zero, zero), (zero, zero)),
        'projector_completeness': add(projector_plus, projector_minus) == identity,
    }
    print('DEFINITION = ZERO_BALANCE_WITH_MINIMAL_BIPOLAR_STRUCTURE')
    print('PARITY_OPERATOR =', parity)
    print('COMPLEX_STRUCTURE =', complex_structure)
    print('PROJECTOR_PLUS =', projector_plus)
    print('PROJECTOR_MINUS =', projector_minus)
    print('IDENTITIES =', checks)
    print('THEOREM_RESULT =', all(checks.values()))


