def prove_mass_ionization_separation() -> None:
    capacities = (2, 8, 18, 32, 32, 18, 8, 2)
    rows = []
    for depth in range(1, D8 + 1):
        mirror = D8 + SHIFT - depth
        symmetric_count = capacities[mirror - 1]
        per_particle_energy = Fraction(depth ** 4, 1)
        total_depth_energy = per_particle_energy * symmetric_count
        recovered = total_depth_energy / symmetric_count
        rows.append((depth, mirror, symmetric_count, total_depth_energy, recovered, recovered - per_particle_energy))
    gaps = []
    for depth in range(1, D8):
        direct_gap = Fraction((depth + 1) ** 4 - depth ** 4, 1)
        polynomial_gap = Fraction(4 * depth ** 3 + 6 * depth ** 2 + 4 * depth + 1, 1)
        gaps.append((depth, direct_gap, polynomial_gap, direct_gap - polynomial_gap))
    checks = {
        'per_particle_recovery_exact': all(row[-1] == 0 for row in rows),
        'quartic_gap_identity_exact': all(row[-1] == 0 for row in gaps),
        'mass_and_ionization_channels_are_separate_readouts': all(row[3] != row[4] for row in rows if row[2] != 1),
    }
    print('DEFINITION = TOTAL_DEPTH_ENERGY_AND_PER_PARTICLE_READOUT_SEPARATION')
    print('DEPTH_ENERGY_ROWS =', tuple(rows))
    print('QUARTIC_GAP_ROWS =', tuple(gaps))
    print('IDENTITIES =', checks)
    print('THEOREM_RESULT =', all(checks.values()))


