def prove_strong_weak_projection() -> None:
    pair_depths = ((1, 2), (3, 4), (5, 6))
    strong_rows = []
    for left, right in pair_depths:
        left_energy = Fraction(left ** 4, 1)
        right_energy = Fraction(right ** 4, 1)
        symmetric_gap = Fraction(2, 1) * abs(right_energy - left_energy) / (left_energy + right_energy)
        strong_rows.append((left, right, left_energy, right_energy, symmetric_gap))
    strong_mean = sum((row[-1] for row in strong_rows), Fraction(0)) / len(strong_rows)
    strong_projection = Decimal(strong_mean.numerator) / Decimal(strong_mean.denominator) / (PI_D * PI_D)
    weak_projection = Fraction(3, C12 + SHIFT)
    checks = {
        'three_visible_pair_channels': len(strong_rows) == 3,
        'strong_symmetric_gaps_positive': all(row[-1] > 0 for row in strong_rows),
        'strong_projection_positive': strong_projection > 0,
        'weak_projection_between_zero_and_one': 0 < weak_projection < 1,
        'strong_and_weak_are_distinct_projections': Decimal(weak_projection.numerator) / Decimal(weak_projection.denominator) != strong_projection,
    }
    print('DEFINITION = DEPTH_GRADIENT_STRONG_PROJECTION_AND_RECLOSURE_WEAK_PROJECTION')
    print('STRONG_PAIR_ROWS =', tuple(strong_rows))
    print('STRONG_PAIR_MEAN =', strong_mean)
    print('STRONG_ANGULAR_PROJECTION =', strong_projection)
    print('WEAK_RECLOSURE_PROJECTION =', weak_projection)
    print('IDENTITIES =', checks)
    print('THEOREM_RESULT =', all(checks.values()))


