def prove_causal_drive_lag_order() -> None:
    events = ('ZERO', 'DRIVER', 'CONNECTOR', 'FOLLOWER', 'RECLOSURE')
    immediate = tuple((events[i], events[i + 1]) for i in range(len(events) - 1))
    reachability = set(immediate)
    changed = True
    while changed:
        changed = False
        additions = set()
        for left, middle in reachability:
            for middle_b, right in reachability:
                if middle == middle_b and (left, right) not in reachability:
                    additions.add((left, right))
        if additions:
            reachability |= additions
            changed = True
    depths = {event: index for index, event in enumerate(events)}
    checks = {
        'acyclic': all(left != right for left, right in reachability),
        'unique_depth_order': len(set(depths.values())) == len(events),
        'driver_precedes_connector': ('DRIVER', 'CONNECTOR') in reachability,
        'connector_precedes_follower': ('CONNECTOR', 'FOLLOWER') in reachability,
        'all_paths_reclose': ('ZERO', 'RECLOSURE') in reachability,
    }
    print('DEFINITION = CAUSAL_DRIVE_CONNECTOR_FOLLOWER_RECLOSURE_ORDER')
    print('EVENTS =', events)
    print('IMMEDIATE_RELATIONS =', immediate)
    print('TRANSITIVE_RELATIONS =', tuple(sorted(reachability)))
    print('DEPTHS =', depths)
    print('IDENTITIES =', checks)
    print('THEOREM_RESULT =', all(checks.values()))


def prove_all_force_dependency_closure() -> None:
    dependencies = {
        'origin': (),
        'geometry': ('origin',),
        'action': ('geometry',),
        'electromagnetic': ('action',),
        'strong': ('action',),
        'weak': ('action',),
        'gravity': ('geometry', 'action'),
        'unified_field': ('electromagnetic', 'strong', 'weak', 'gravity'),
    }
    visiting = set()
    visited = set()
    order = []
    cycle = False

    def visit(node):
        nonlocal cycle
        if node in visited:
            return
        if node in visiting:
            cycle = True
            return
        visiting.add(node)
        for parent in dependencies[node]:
            visit(parent)
        visiting.remove(node)
        visited.add(node)
        order.append(node)

    for node in dependencies:
        visit(node)
    checks = {
        'acyclic_dependency_graph': not cycle,
        'all_nodes_reached': len(visited) == len(dependencies),
        'origin_is_first': order[0] == 'origin',
        'unified_field_is_last': order[-1] == 'unified_field',
        'four_interactions_are_direct_parents_of_unified_field': set(dependencies['unified_field']) == {'electromagnetic', 'strong', 'weak', 'gravity'},
    }
    print('DEFINITION = ONE_ORIGIN_TO_FOUR_INTERACTIONS_TO_UNIFIED_FIELD_DEPENDENCY_GRAPH')
    print('DEPENDENCIES =', dependencies)
    print('TOPOLOGICAL_ORDER =', tuple(order))
    print('IDENTITIES =', checks)
    print('THEOREM_RESULT =', all(checks.values()))




