_PRINTED_DERIVATION_FUNCTIONS = set()

@functools.lru_cache(maxsize=None)
def _local_function_names() -> set[str]:
    names = set()
    for name, value in globals().items():
        if not callable(value) or getattr(value, '__module__', None) != __name__:
            continue
        try:
            unwrapped = inspect.unwrap(value)
        except ValueError:
            continue
        if inspect.isfunction(unwrapped):
            names.add(name)
    return names

@functools.lru_cache(maxsize=None)
def _direct_function_dependencies(function_name: str) -> tuple[str, ...]:
    function = globals().get(function_name)
    if not callable(function):
        return ()
    function = inspect.unwrap(function)
    local_names = _local_function_names()
    ordered = []
    for instruction in dis.get_instructions(inspect.unwrap(function)):
        if instruction.opname in ('LOAD_GLOBAL', 'LOAD_NAME') and instruction.argval in local_names and instruction.argval != function_name:
            if instruction.argval not in ordered:
                ordered.append(instruction.argval)
    return tuple(ordered)

@functools.lru_cache(maxsize=None)
def _ordered_function_dependency_closure(function_name: str) -> tuple[str, ...]:
    ordered = []
    visiting = set()
    visited = set()
    def visit(name: str) -> None:
        if name in visited or name in visiting:
            return
        visiting.add(name)
        for child in _direct_function_dependencies(name):
            visit(child)
        visiting.remove(name)
        visited.add(name)
        ordered.append(name)
    visit(function_name)
    return tuple(ordered)

def _compact_source_text(text: str) -> str:
    return ' '.join(text.strip().split())

def _statement_explanation(node: ast.AST) -> str:
    if isinstance(node, (ast.Assign, ast.AnnAssign, ast.AugAssign)):
        return 'Compute the complete right-hand expression first, then assign the resulting exact object to the named variable on the left.'
    if isinstance(node, ast.Return):
        return 'Return the displayed object as the certificate produced by this function.'
    if isinstance(node, ast.If):
        return 'Evaluate the condition directly; execute the indented branch only for the corresponding truth value.'
    if isinstance(node, (ast.For, ast.AsyncFor)):
        return 'Iterate through the declared finite collection in order and apply the indented calculation to every element.'
    if isinstance(node, ast.While):
        return 'Repeat the indented calculation while the displayed condition remains true, with the state updated at each pass.'
    if isinstance(node, ast.Assert):
        return 'Require the displayed identity or inequality; stop the proof immediately if it is false.'
    if isinstance(node, ast.Expr) and isinstance(node.value, ast.Call):
        return 'Evaluate the displayed function call using the arguments shown in the source statement.'
    if isinstance(node, ast.Raise):
        return 'Reject the inadmissible case by raising the displayed exception.'
    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
        return 'Define the local helper function before it is used in the surrounding proof.'
    if isinstance(node, ast.With):
        return 'Enter the displayed controlled context, perform the indented computation, and leave the context afterward.'
    if isinstance(node, ast.Try):
        return 'Execute the primary calculation and handle only the explicitly listed exceptional branches.'
    return 'Execute this source statement exactly in the written order.'

@functools.lru_cache(maxsize=None)
def _source_level_steps(function_name: str) -> tuple[tuple[int, str, str], ...]:
    function = globals().get(function_name)
    if not callable(function):
        return ()
    function = inspect.unwrap(function)
    try:
        source_text = inspect.getsource(function)
        parsed = ast.parse(textwrap.dedent(source_text))
    except (OSError, TypeError, SyntaxError):
        return ()
    function_node = next((node for node in parsed.body if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))), None)
    if function_node is None:
        return ()
    rows = []
    counter = 0
    def walk_statements(statements, depth=0):
        nonlocal counter
        for statement in statements:
            counter += 1
            segment = ast.get_source_segment(textwrap.dedent(source_text), statement) or statement.__class__.__name__
            rows.append((depth, _compact_source_text(segment), _statement_explanation(statement)))
            nested_groups = []
            for attr in ('body', 'orelse', 'finalbody'):
                value = getattr(statement, attr, None)
                if isinstance(value, list) and value:
                    nested_groups.append(value)
            handlers = getattr(statement, 'handlers', None)
            if handlers:
                nested_groups.extend(handler.body for handler in handlers if getattr(handler, 'body', None))
            for group in nested_groups:
                walk_statements(group, depth + 1)
    walk_statements(function_node.body)
    return tuple(rows)

def _print_derivation_guide(index: int, title: str) -> None:
    guide = DERIVATION_GUIDES[index]
    print('DERIVATION GUIDE')
    print('THEOREM GOAL =', guide['goal'])
    print('PHYSICAL OR MATHEMATICAL MEANING =', guide['meaning'])
    print('DERIVATION ORDER')
    for number, phase in enumerate(guide['phases'], 1):
        print(f'  STEP {number}: {phase}')
    print('HOW TO READ THE SYMBOLS')
    print('  Fraction(a, b) is the exact rational number a divided by b; no decimal rounding is used.')
    print('  Decimal values are computed at the declared precision and are not external measured inputs.')
    print('  A matrix product multiplies corresponding entries of a left row and a right column and then adds them.')
    print('  True means that the immediately preceding identity or inequality was evaluated and passed.')
    print('  A theorem is True only when all mandatory conditions are joined by logical AND and pass.')
    dependencies = _ordered_function_dependency_closure(THEOREM_ROOTS[index])
    print('SOURCE-LEVEL DERIVATION FUNCTION COUNT =', len(dependencies))
    for function_number, function_name in enumerate(dependencies, 1):
        if function_name in _PRINTED_DERIVATION_FUNCTIONS:
            print(f'  FUNCTION {function_number}: {function_name} [DERIVATION ALREADY PRINTED; EXACT SAME FUNCTION REUSED]')
            continue
        _PRINTED_DERIVATION_FUNCTIONS.add(function_name)
        function = globals()[function_name]
        try:
            signature = str(inspect.signature(function))
        except (TypeError, ValueError):
            signature = '(signature unavailable)'
        print(f'  FUNCTION {function_number}: {function_name}{signature}')
        rows = _source_level_steps(function_name)
        for step_number, (depth, statement, explanation) in enumerate(rows, 1):
            indentation = '    ' + '  ' * depth
            print(f'{indentation}SOURCE STEP {step_number}: {statement}')
            print(f'{indentation}WHY THIS STEP IS VALID: {explanation}')

def _ordered_unique_fraction_pairs(text: str) -> tuple[tuple[int, int], ...]:
    seen = set()
    rows = []
    for numerator, denominator in re.findall(r'Fraction\((-?\d+)\s*,\s*(-?\d+)\)', text):
        pair = (int(numerator), int(denominator))
        if pair not in seen:
            seen.add(pair)
            rows.append(pair)
    return tuple(rows)

def _gcd_nonnegative(a: int, b: int) -> int:
    a, b = abs(a), abs(b)
    while b:
        a, b = b, a % b
    return a

def _line_explanations(line: str) -> tuple[str, ...]:
    stripped = line.strip()
    if not stripped:
        return ('The empty line separates two calculation blocks for readability.',)
    explanations = []
    if ' = ' in stripped:
        key, value = stripped.split(' = ', 1)
        key_lower = key.lower()
        explanations.append(f'Associate {key} with the exact result on the right. This equality reports a computed value, not a fitted estimate.')
        if key == 'DEFINITION':
            explanations.append('This line fixes the object being discussed before any conclusion is drawn.')
        if any(token in key_lower for token in ('matrix', 'operator', 'projector', 'tensor', 'coframe', 'metric')):
            explanations.append('This is a component-bearing linear-algebra object; row, column, and index positions are preserved in later operations.')
        if any(token in key_lower for token in ('ratio', 'fraction', 'coupling', 'probability', 'weight')):
            explanations.append('This is a dimensionless relative quantity; a common rescaling of numerator and denominator leaves it unchanged.')
        if any(token in key_lower for token in ('identity', 'checks', 'conditions')):
            explanations.append('Every listed item is a separate obligation. One False item prevents the complete theorem gate from passing.')
        if key in ('THEOREM_RESULT', 'RESULT'):
            explanations.append('This is the logical AND of the required conditions shown above.')
        if value in ('True', 'False'):
            explanations.append('The Boolean value is obtained by direct evaluation of the preceding condition.')
        if 'Decimal(' in value:
            explanations.append('Decimal arithmetic controls precision explicitly and avoids unintended binary floating-point rounding.')
        if re.fullmatch(r'-?\d+', value):
            explanations.append('The result is an integer and therefore contains no rounding approximation.')
    else:
        explanations.append('This line is a calculation-block title, a condition statement, or a transition between proof steps.')
    for numerator, denominator in _ordered_unique_fraction_pairs(stripped):
        if denominator == 0:
            explanations.append(f'Fraction({numerator}, {denominator}) is inadmissible because its denominator is zero.')
        else:
            gcd = _gcd_nonnegative(numerator, denominator)
            explanations.append(f'Fraction({numerator}, {denominator}) means {numerator} divided by {denominator}; the greatest common divisor is {gcd}.')
    return tuple(explanations)

def _print_stepwise_body(body: str) -> int:
    lines = body.splitlines()
    print('CALCULATION OUTPUT READING GUIDE')
    print('  Every line below is computed from the definitions in the source-level derivation.')
    print('  Fraction(a, b) is an exact reduced rational number; decimal rounding is not used.')
    print('  Dotted names and numeric indices identify nested dictionary, matrix, tensor, or sequence components.')
    print('  Each True entry in IDENTITIES or CONDITIONS is a directly evaluated equality or inequality.')
    print('  THEOREM_RESULT is True only when every mandatory subcondition is True.')
    print('ORIGINAL CALCULATION OUTPUT BEGIN')
    print(body)
    print('ORIGINAL CALCULATION OUTPUT END')
    return len(lines)

