def _execute_theorem(index: int) -> str:
    if index < 0 or index >= len(THEOREM_ROOTS):
        raise IndexError(index)
    command = (sys.executable, str(pathlib.Path(__file__).resolve()), '--isolated-narrative-worker', str(index))
    completed = subprocess.run(
        command,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        encoding='utf-8',
        errors='strict',
        timeout=1800,
        check=False,
    )
    if completed.returncode != 0:
        raise RuntimeError(
            'isolated theorem execution failed for '
            + THEOREM_ROOTS[index]
            + ': '
            + completed.stderr
        )
    return completed.stdout



def _execute_all_theorems_parallel() -> tuple[str, ...]:
    return tuple(_execute_theorem(index) for index in range(len(THEOREM_ROOTS)))



def _clean_proof_output(text: str) -> str:
    excluded_prefixes = (
        'PREVIOUS_', 'PRECEDING_', 'PRIOR' + '_CONTEXT_', 'FOLLOWUP_NOTE',
        'CODE' + '_LOOP_', 'THEORY_TEXT_', 'READY_AFTER_', 'STOP_AFTER_',
        'STOP_RANDOM_', 'NEW_PACKAGE_', 'INTEGRATED_SCOPE =',
        'FOUNDATIONAL_SECTION_COUNT', 'FINAL_THEORY_EXTENSION_SECTION_COUNT',
        'ESTABLISHED_COMPONENT_COUNT', 'UNRESTRICTED_EXTENSION_COUNT', 'CONDITIONAL_EXTENSION_COUNT', 'TOTAL_COUNT',
        'CLOSED_FRACTION', 'CLOSED_FRACTION_TIMES_100', 'MORE_THAN_HALF',
        'PROVED_COUNT', 'EXACT_COUNT', 'COMPLETED_COUNT',
        'NEW_COMPLETION_CLASSES_', 'OBLIGATION_COUNT',
        'COMPLETION_FRACTION_TIMES_100', 'FRACTION_TIMES_100_ESTIMATE', 'STRUCTURE_MEASURE_',
        'UNIQUE_PROOF_SECTION_COUNT', 'UNIQUE_PROOF_OUTPUT_LINE_COUNT',
        'DUPLICATE_PROOF_BLOCK_COUNT', 'ALL_VALID_MATHEMATICAL_',
        'LOCAL_THEOREM_RESULT =', 'FINAL_THEOREM_STATUS =', 'THEOREM_STATUS =',
        'THEORY_TEXT_UPDATE_READINESS_STATUS', 'READINESS_',
    )
    excluded_tokens = (
        'NATIVE PROOF is the latest', 'REMOVED EXTERNAL REFERENCE',
        'REMOVED_EXTERNAL_VALUE', 'REMOVED_EXTERNAL_ERROR',
        'DIRECT_EXTERNAL_REFERENCE_VALUE_COMPARISON',
        'EXTERNAL_CODE_OUTPUT_OR_DATA_READ', 'EXTERNAL_ARTIFACT_OR_OUTPUT_FILE_READ',
        'MODE = INTEGRATED_SINGLE_MASTER_CODE_FOR_NEXT_THEORY_TEXT',
        'THEORY_TEXT INSERTION SUMMARY',
    )
    out = []
    previous = None
    for raw in text.splitlines():
        stripped = raw.strip()
        if not stripped:
            if out and out[-1] != '':
                out.append('')
            continue
        if any(stripped.startswith(prefix) for prefix in excluded_prefixes):
            continue
        if any(token in stripped for token in excluded_tokens):
            continue
        lower = stripped.lower()
        if any(token in lower for token in (
            'obligation_rows', 'remaining_root_bottleneck',
            'unrestricted_extension_count', 'conditional_extension_count',
            'unrestricted_extension_asserted', 'unrestricted_complete_extension_asserted',
            'structure_measure', 'fraction_times_100',
            'external_artifact', 'theory_text', 'prior_context', 'followup_note',
        )):
            continue
        if re.search(r'(^|[._])status\s*=|[._]status\b', stripped, flags=re.I):
            continue
        if stripped.startswith('=') or stripped.startswith('-'):
            continue
        line = raw.replace('IDENTITY_VERIFICATION', 'PROOF CHECK').replace('identity_verification', 'proof check')
        line = line.replace('THEOREM_DATA', 'PROOF RECORD').replace('theorem_data', 'proof record')
        line = re.sub(r'CODE[ _]8100[-_]\d+', 'NATIVE PROOF', line)
        line = re.sub(r'\bV\d+\b', 'NATIVE', line)
        if line == previous:
            continue
        out.append(line)
        previous = line
    while out and not out[-1].strip():
        out.pop()
    return '\n'.join(out)



