def _global_block_index() -> dict[int, str]:
    result = {}
    for block_name, members in GLOBAL_JOINT_BLOCKS:
        for member in members:
            if member in result:
                raise ValueError('a global theorem occurs in more than one joint block')
            result[member] = block_name
    return result


def _topological_block_order() -> tuple[str, ...]:
    names = tuple(name for name, _ in GLOBAL_JOINT_BLOCKS)
    remaining = set(names)
    ordered = []
    while remaining:
        available = [name for name in names if name in remaining and all(parent in ordered for parent in GLOBAL_BLOCK_DEPENDENCIES[name])]
        if not available:
            raise ValueError('the joint block dependency relation contains a directed cycle')
        for name in available:
            ordered.append(name)
            remaining.remove(name)
    return tuple(ordered)


def _global_target_web_theorem() -> dict[str, object]:
    block_index = _global_block_index()
    block_order = _topological_block_order()
    flattened = tuple(member for block_name in block_order for name, members in GLOBAL_JOINT_BLOCKS if name == block_name for member in members)
    target_set_exact = set(GLOBAL_TARGETS) == set(GLOBAL_TARGET_ORDER)
    fixed_order_exact = flattened == GLOBAL_TARGET_ORDER
    each_target_once = len(flattened) == len(set(flattened)) == len(GLOBAL_TARGET_ORDER)
    every_target_has_inputs = all(number in GLOBAL_NATIVE_LEMMA_INPUTS and GLOBAL_NATIVE_LEMMA_INPUTS[number] for number in GLOBAL_TARGET_ORDER)
    all_input_indices_valid = all(all(1 <= index <= len(THEOREM_TITLES) for index in GLOBAL_NATIVE_LEMMA_INPUTS[number]) for number in GLOBAL_TARGET_ORDER)
    all_requirements_nonempty = all(GLOBAL_TARGETS[number]['requirements'] for number in GLOBAL_TARGET_ORDER)
    block_dependencies_respect_order = all(all(block_order.index(parent) < block_order.index(name) for parent in GLOBAL_BLOCK_DEPENDENCIES[name]) for name in block_order)
    return {
        'block_index': block_index,
        'block_order': block_order,
        'flattened_order': flattened,
        'target_set_exact': target_set_exact,
        'fixed_order_exact': fixed_order_exact,
        'each_target_once': each_target_once,
        'every_target_has_inputs': every_target_has_inputs,
        'all_input_indices_valid': all_input_indices_valid,
        'all_requirements_nonempty': all_requirements_nonempty,
        'block_dependencies_respect_order': block_dependencies_respect_order,
        'joint_web_well_formed': all((target_set_exact, fixed_order_exact, each_target_once, every_target_has_inputs, all_input_indices_valid, all_requirements_nonempty, block_dependencies_respect_order)),
    }


def _print_global_target_web() -> str:
    theorem = _global_target_web_theorem()
    lines = []
    lines.append('-' * 132)
    lines.append('THEOREM. SIMULTANEOUS TWENTY TWO TARGET PROOF WEB')
    lines.append('PROOF.')
    lines.append('STEP 1. Fix the complete unrestricted theorem set before any new computation.')
    lines.append('GLOBAL_TARGET_ORDER = ' + ' -> '.join(str(number) for number in GLOBAL_TARGET_ORDER))
    lines.append('STEP 2. Partition the twenty two theorems into joint blocks so mutually supporting constructions are proved together rather than assumed from one another.')
    for block_number, (block_name, members) in enumerate(GLOBAL_JOINT_BLOCKS, start=1):
        lines.append(f'JOINT BLOCK {block_number}. {block_name}')
        lines.append('  MEMBERS = ' + ', '.join(str(member) for member in members))
        parents = GLOBAL_BLOCK_DEPENDENCIES[block_name]
        lines.append('  RECEIVES COMPLETED OBJECTS FROM = ' + (', '.join(parents) if parents else 'NATIVE ORIGIN DEFINITIONS'))
    lines.append('STEP 3. Verify that the condensation graph of the joint blocks is directed and acyclic.')
    lines.append('TOPOLOGICAL_BLOCK_ORDER = ' + ' -> '.join(theorem['block_order']))
    lines.append('BLOCK_DEPENDENCIES_RESPECT_ORDER = ' + str(theorem['block_dependencies_respect_order']))
    lines.append('STEP 4. Verify that every global theorem appears exactly once and that concatenating the blocks reproduces the fixed presentation order.')
    lines.append('TARGET_SET_EXACT = ' + str(theorem['target_set_exact']))
    lines.append('EACH_TARGET_ONCE = ' + str(theorem['each_target_once']))
    lines.append('FIXED_ORDER_EXACT = ' + str(theorem['fixed_order_exact']))
    lines.append('STEP 5. Attach the already proved native lemmas to every unrestricted theorem as inputs, without treating those restricted lemmas as the unrestricted conclusion.')
    lines.append('EVERY_TARGET_HAS_NATIVE_LEMMA_INPUTS = ' + str(theorem['every_target_has_inputs']))
    lines.append('ALL_NATIVE_LEMMA_INDICES_VALID = ' + str(theorem['all_input_indices_valid']))
    lines.append('STEP 6. State every unrestricted theorem and all of its necessary proof clauses in the same program.')
    for number in GLOBAL_TARGET_ORDER:
        target = GLOBAL_TARGETS[number]
        lines.append('')
        lines.append(f'GLOBAL THEOREM {number}. {target["title"]}')
        lines.append('  STATEMENT = ' + target['statement'])
        lines.append('  JOINT BLOCK = ' + theorem['block_index'][number])
        lines.append('  NATIVE INPUT THEOREMS = ' + ', '.join(str(index) for index in GLOBAL_NATIVE_LEMMA_INPUTS[number]))
        for requirement_number, requirement in enumerate(target['requirements'], start=1):
            lines.append(f'  REQUIRED CLAUSE {requirement_number} = {requirement}')
    lines.append('')
    lines.append('STEP 7. The full unrestricted conclusion is the conjunction of all twenty two global theorems; no proper subset is substituted for that conjunction.')
    lines.append('FULL CONCLUSION FORM = GLOBAL THEOREM 1 AND GLOBAL THEOREM 2 AND ... AND GLOBAL THEOREM 22')
    lines.append('STEP 8. Mutual assistance is confined inside a joint existence and uniqueness proof, while completed objects pass only forward between blocks. Therefore simultaneous work does not create circular proof.')
    lines.append('JOINT_WEB_WELL_FORMED = ' + str(theorem['joint_web_well_formed']))
    lines.append('QED')
    return '\n'.join(lines)


def _print_global_completion_logic_theorem() -> str:
    lines = []
    lines.append('-' * 132)
    lines.append('THEOREM. NO PARTIAL SUBSET CAN CERTIFY THE FULL UNRESTRICTED THEORY')
    lines.append('PROOF.')
    lines.append('Let T1 through T22 denote the truth values of the twenty two unrestricted global theorems.')
    lines.append('Define F as the conjunction T1 AND T2 AND ... AND T22.')
    lines.append('If F is true, then every Ti is true by the elimination rule for conjunction.')
    lines.append('Conversely, if every Ti is true, repeated conjunction introduction gives F.')
    lines.append('For any proper subset S of the twenty two indices, choose one omitted index j, assign every Ti in S the value true, and assign Tj the value false.')
    lines.append('Under that assignment every theorem in S is true while F is false. Hence no proper subset logically implies F without an additional theorem that proves the omitted clauses.')
    lines.append('Therefore a restricted example, a finite computation, or a proper subset of completed global theorems cannot be renamed as the full unrestricted conclusion.')
    lines.append('QED')
    return '\n'.join(lines)


