def _alternating_sum(values: tuple[int, ...]) -> int:
    total = 0
    sign = 1
    for value in values:
        total += sign * value
        sign = -sign
    return total


def _pascal_row(order: int) -> tuple[int, ...]:
    if order < 0:
        raise ValueError(order)
    row = [1]
    for _ in range(order):
        next_row = [1]
        for index in range(len(row) - 1):
            next_row.append(row[index] + row[index + 1])
        next_row.append(1)
        row = next_row
    return tuple(row)


def _domain_consistency_theorem() -> dict[str, object]:
    sphere_four_cell_counts = (1, 0, 0, 0, 1)
    torus_four_cell_counts = _pascal_row(4)
    sphere_four_euler = _alternating_sum(sphere_four_cell_counts)
    torus_four_euler = _alternating_sum(torus_four_cell_counts)

    propagation_space = ('REAL_TIME_AXIS', 'FIXED_SPATIAL_SLICE')
    initial_slice = propagation_space[1]
    later_slice = propagation_space[1]
    product_propagation_preserves_slice_type = initial_slice == later_slice

    target_domain_complete = set(GLOBAL_TARGET_DOMAIN) == set(GLOBAL_TARGET_ORDER)
    target_domain_once = len(GLOBAL_TARGET_DOMAIN) == len(set(GLOBAL_TARGET_DOMAIN))
    every_domain_declared = all(domain in DOMAIN_TYPES for domain in GLOBAL_TARGET_DOMAIN.values())
    inclusion_closed = all(
        parent in DOMAIN_TYPES
        for parents in DOMAIN_INCLUSIONS.values()
        for parent in parents
    )

    all_carriers_not_forced_lorentz = (
        sphere_four_euler != 0
        and torus_four_euler == 0
        and GLOBAL_TARGET_DOMAIN[1] == 'ALL_SMOOTH_CARRIERS'
        and GLOBAL_TARGET_DOMAIN[15] == 'LORENTZ_ADMISSIBLE_CARRIERS'
    )
    causal_and_topology_change_separated = (
        product_propagation_preserves_slice_type
        and GLOBAL_TARGET_DOMAIN[2] == 'CAUSAL_PROPAGATION_SPACETIMES'
        and GLOBAL_TARGET_DOMAIN[19] == 'TOPOLOGY_TRANSITION_COBORDISMS'
    )
    chiral_targets_spin_typed = all(
        GLOBAL_TARGET_DOMAIN[number] == 'SPIN_GAUGE_PROPAGATION_SPACETIMES'
        for number in (8, 9, 10, 11, 12, 13, 14, 20, 21, 22)
    )

    theorem_result = all((
        target_domain_complete,
        target_domain_once,
        every_domain_declared,
        inclusion_closed,
        all_carriers_not_forced_lorentz,
        causal_and_topology_change_separated,
        chiral_targets_spin_typed,
    ))
    return {
        'sphere_four_cell_counts': sphere_four_cell_counts,
        'sphere_four_euler': sphere_four_euler,
        'torus_four_cell_counts': torus_four_cell_counts,
        'torus_four_euler': torus_four_euler,
        'product_propagation_preserves_slice_type': product_propagation_preserves_slice_type,
        'target_domain_complete': target_domain_complete,
        'target_domain_once': target_domain_once,
        'every_domain_declared': every_domain_declared,
        'inclusion_closed': inclusion_closed,
        'all_carriers_not_forced_lorentz': all_carriers_not_forced_lorentz,
        'causal_and_topology_change_separated': causal_and_topology_change_separated,
        'chiral_targets_spin_typed': chiral_targets_spin_typed,
        'theorem_result': theorem_result,
    }


def _print_domain_consistency_theorem() -> str:
    theorem = _domain_consistency_theorem()
    lines = []
    lines.append('-' * 132)
    lines.append('THEOREM. GLOBAL DOMAIN CONSISTENCY OF THE TWENTY TWO UNRESTRICTED TARGETS')
    lines.append('PROOF.')
    lines.append('STEP 1. Separate a mathematical four dimensional carrier from a physical Lorentzian propagation spacetime.')
    lines.append('A carrier is first generated as a smooth four dimensional object. A Lorentz metric is an additional structure and is not silently assigned to every carrier.')
    lines.append('STEP 2. Compute two exact Euler characteristics from their cell counts.')
    lines.append('For the four sphere the cell counts by dimension are 1, 0, 0, 0, 1.')
    lines.append('The alternating sum is 1 - 0 + 0 - 0 + 1 = ' + str(theorem['sphere_four_euler']) + '.')
    lines.append('For the four torus the cell counts are the fourth Pascal row 1, 4, 6, 4, 1.')
    lines.append('The alternating sum is 1 - 4 + 6 - 4 + 1 = ' + str(theorem['torus_four_euler']) + '.')
    lines.append('A compact Lorentz carrier requires a nowhere zero timelike line field. By the Poincare Hopf obstruction, a compact carrier with nonzero Euler characteristic cannot carry that field.')
    lines.append('Therefore the class of all smooth carriers and the class of Lorentz admissible carriers cannot be identified.')
    lines.append('ALL_CARRIERS_NOT_FORCED_LORENTZ = ' + str(theorem['all_carriers_not_forced_lorentz']))
    lines.append('STEP 3. Separate causal propagation from topology transition.')
    lines.append('A globally split propagation region has the form REAL TIME AXIS times one fixed spatial slice.')
    lines.append('Every constant time slice in this product has the same spatial type, so ordinary causal propagation does not change the slice topology.')
    lines.append('PRODUCT_PROPAGATION_PRESERVES_SLICE_TYPE = ' + str(theorem['product_propagation_preserves_slice_type']))
    lines.append('Topology changing histories are therefore represented in a separate cobordism sector and are not inserted into one globally hyperbolic propagation chart.')
    lines.append('CAUSAL_AND_TOPOLOGY_CHANGE_SEPARATED = ' + str(theorem['causal_and_topology_change_separated']))
    lines.append('STEP 4. Place chiral fermion, determinant, renormalization, scattering, and observable targets on the spin gauge propagation sector.')
    lines.append('This prevents a fermion determinant from being demanded on a carrier for which the required spinorial lifting data have not been constructed.')
    lines.append('CHIRAL_TARGETS_SPIN_TYPED = ' + str(theorem['chiral_targets_spin_typed']))
    lines.append('STEP 5. Assign every one of the twenty two fixed targets to exactly one declared domain while retaining the fixed target order.')
    for number in GLOBAL_TARGET_ORDER:
        lines.append('GLOBAL TARGET ' + str(number) + ' DOMAIN = ' + GLOBAL_TARGET_DOMAIN[number])
    lines.append('TARGET_DOMAIN_COMPLETE = ' + str(theorem['target_domain_complete']))
    lines.append('TARGET_DOMAIN_ONCE = ' + str(theorem['target_domain_once']))
    lines.append('EVERY_DOMAIN_DECLARED = ' + str(theorem['every_domain_declared']))
    lines.append('DOMAIN_INCLUSION_RELATIONS_CLOSED = ' + str(theorem['inclusion_closed']))
    lines.append('STEP 6. The twenty two targets remain simultaneous, but no theorem is applied outside the domain on which its objects are defined.')
    lines.append('This removes the hidden contradiction between all smooth carriers, causal Lorentz propagation, chiral spin matter, and topology changing quantum histories.')
    lines.append('THEOREM_RESULT = ' + str(theorem['theorem_result']))
    lines.append('QED')
    return '\n'.join(lines)



