def _binary_words_of_depth(depth: int) -> tuple[tuple[int, ...], ...]:
    if depth < 1:
        raise ValueError('depth must be positive')
    return tuple(tuple(bits) for bits in itertools.product((0, 1), repeat=depth))


def _complement_binary_word(word: tuple[int, ...]) -> tuple[int, ...]:
    return tuple(1 - bit for bit in word)


def _selector_obstruction_at_depth(depth: int) -> dict[str, object]:
    words = _binary_words_of_depth(depth)
    word_set = set(words)
    complement_map = {word: _complement_binary_word(word) for word in words}
    complement_is_involution = all(
        _complement_binary_word(complement_map[word]) == word
        for word in words
    )
    no_complement_fixed_point = all(complement_map[word] != word for word in words)
    canonical_pairs = {
        min(word, complement_map[word])
        for word in words
    }
    exact_pair_count = len(canonical_pairs) == 2 ** (depth - 1)

    def complement_invariant_score(word: tuple[int, ...]) -> int:
        weight = sum(word)
        return weight * (depth - weight)

    scores = {word: complement_invariant_score(word) for word in words}
    score_is_complement_invariant = all(
        scores[word] == scores[complement_map[word]]
        for word in words
    )
    minimum_score = min(scores.values())
    minimizing_words = tuple(word for word in words if scores[word] == minimum_score)
    paired_minimum_count_at_least_two = len(minimizing_words) >= 2

    remaining_after_orientation_bits = tuple(
        (orientation_bit_count, 2 ** (depth - orientation_bit_count))
        for orientation_bit_count in range(depth + 1)
    )
    one_orientation_bit_is_insufficient = (
        depth == 1
        or dict(remaining_after_orientation_bits)[1] > 1
    )
    uniqueness_requires_depth_bits = (
        dict(remaining_after_orientation_bits)[depth] == 1
        and all(
            remaining_count > 1
            for bit_count, remaining_count in remaining_after_orientation_bits
            if bit_count < depth
        )
    )

    zero_rule_branch = tuple(0 for _ in range(depth))
    one_rule_branch = tuple(1 for _ in range(depth))
    both_rules_are_prefix_compatible = all(
        zero_rule_branch[:level] == tuple(0 for _ in range(level))
        and one_rule_branch[:level] == tuple(1 for _ in range(level))
        for level in range(1, depth + 1)
    )
    compatible_rules_are_distinct = zero_rule_branch != one_rule_branch
    theorem_result = all((
        len(word_set) == 2 ** depth,
        complement_is_involution,
        no_complement_fixed_point,
        exact_pair_count,
        score_is_complement_invariant,
        paired_minimum_count_at_least_two,
        one_orientation_bit_is_insufficient,
        uniqueness_requires_depth_bits,
        both_rules_are_prefix_compatible,
        compatible_rules_are_distinct,
    ))
    return {
        'depth': depth,
        'state_count': len(words),
        'pair_count': len(canonical_pairs),
        'complement_is_involution': complement_is_involution,
        'no_complement_fixed_point': no_complement_fixed_point,
        'exact_pair_count': exact_pair_count,
        'score_is_complement_invariant': score_is_complement_invariant,
        'minimum_score': minimum_score,
        'minimizing_words': minimizing_words,
        'paired_minimum_count_at_least_two': paired_minimum_count_at_least_two,
        'remaining_after_orientation_bits': remaining_after_orientation_bits,
        'one_orientation_bit_is_insufficient': one_orientation_bit_is_insufficient,
        'uniqueness_requires_depth_bits': uniqueness_requires_depth_bits,
        'zero_rule_branch': zero_rule_branch,
        'one_rule_branch': one_rule_branch,
        'both_rules_are_prefix_compatible': both_rules_are_prefix_compatible,
        'compatible_rules_are_distinct': compatible_rules_are_distinct,
        'theorem_result': theorem_result,
    }


def _universal_selector_obstruction_theorem() -> dict[str, object]:
    depth_results = tuple(_selector_obstruction_at_depth(depth) for depth in range(1, 13))
    target_coverage_exact = set(GLOBAL_SELECTOR_INPUTS) == set(GLOBAL_TARGET_ORDER)
    all_targets_receive_three_requirements = all(
        len(set(GLOBAL_SELECTOR_INPUTS[number])) == 3
        for number in GLOBAL_TARGET_ORDER
    )
    all_finite_levels_exact = all(item['theorem_result'] for item in depth_results)
    symmetry_only_unique_selector_impossible = all(
        item['no_complement_fixed_point']
        and item['score_is_complement_invariant']
        and item['paired_minimum_count_at_least_two']
        for item in depth_results
    )
    finite_orientation_data_does_not_select_infinite_branch = all(
        dict(item['remaining_after_orientation_bits'])[min(3, item['depth'])] > 1
        for item in depth_results
        if item['depth'] > 3
    )
    full_independent_bit_specification_is_branch_data = all(
        item['uniqueness_requires_depth_bits']
        for item in depth_results
    )
    deterministic_compatibility_alone_is_not_unique = all(
        item['both_rules_are_prefix_compatible']
        and item['compatible_rules_are_distinct']
        for item in depth_results
    )
    target_specific_dynamical_update_still_required = all((
        symmetry_only_unique_selector_impossible,
        finite_orientation_data_does_not_select_infinite_branch,
        deterministic_compatibility_alone_is_not_unique,
    ))
    theorem_result = all((
        all_finite_levels_exact,
        target_coverage_exact,
        all_targets_receive_three_requirements,
        symmetry_only_unique_selector_impossible,
        finite_orientation_data_does_not_select_infinite_branch,
        full_independent_bit_specification_is_branch_data,
        deterministic_compatibility_alone_is_not_unique,
        target_specific_dynamical_update_still_required,
    ))
    return {
        'depth_results': depth_results,
        'target_coverage_exact': target_coverage_exact,
        'all_targets_receive_three_requirements': all_targets_receive_three_requirements,
        'all_finite_levels_exact': all_finite_levels_exact,
        'symmetry_only_unique_selector_impossible': symmetry_only_unique_selector_impossible,
        'finite_orientation_data_does_not_select_infinite_branch': finite_orientation_data_does_not_select_infinite_branch,
        'full_independent_bit_specification_is_branch_data': full_independent_bit_specification_is_branch_data,
        'deterministic_compatibility_alone_is_not_unique': deterministic_compatibility_alone_is_not_unique,
        'target_specific_dynamical_update_still_required': target_specific_dynamical_update_still_required,
        'theorem_result': theorem_result,
    }


def _print_universal_selector_obstruction_theorem() -> str:
    theorem = _universal_selector_obstruction_theorem()
    lines = []
    lines.append('-' * 132)
    lines.append('THEOREM. ZERO-BIPOLAR COMPLEMENT SYMMETRY CANNOT BY ITSELF SELECT ONE GLOBAL BRANCH')
    lines.append('PROOF.')
    lines.append('STEP 1. At depth n the branch space contains every binary word of length n. Therefore it contains exactly 2 to the n states.')
    lines.append('STEP 2. Define the zero-bipolar complement C by replacing every zero with one and every one with zero. Applying C twice returns the original word.')
    lines.append('STEP 3. No nonempty binary word equals its complement. Consequently every complement orbit has exactly two members and the number of orbits is 2 to the n minus one power.')
    lines.append('STEP 4. Let a candidate selector score respect exact zero-bipolar symmetry, so the score of a word equals the score of its complement. If one member minimizes the score, its distinct complement has the same score. A unique minimizer is therefore impossible under complement symmetry alone.')
    lines.append('STEP 5. The concrete exact score weight times n minus weight demonstrates the obstruction without fitted constants. Its minimum is reached by both the all-zero and all-one words.')
    lines.append('STEP 6. Supplying k independent orientation bits leaves 2 to the n minus k candidates. A unique word appears only after n bits have been supplied. Independent orientation data of the same size as the word is not a derived selector; it is the branch data itself.')
    lines.append('STEP 7. Prefix compatibility also does not create uniqueness. The rule append zero and the rule append one are both deterministic and exactly compatible with every bonding projection, but they generate distinct branches.')
    for item in theorem['depth_results']:
        lines.append(
            '  DEPTH ' + str(item['depth'])
            + ': STATES = ' + str(item['state_count'])
            + ', COMPLEMENT_ORBITS = ' + str(item['pair_count'])
            + ', MINIMIZERS_OF_SYMMETRIC_SCORE = ' + str(len(item['minimizing_words']))
            + ', UNIQUE_BITS_REQUIRED = ' + str(item['depth'])
            + ', RESULT = ' + str(item['theorem_result'])
        )
    lines.append('STEP 8. The obstruction is delivered to all twenty-two fixed global targets. Every target must therefore derive a target-specific dynamical update or an equivalent native orientation law; compatibility, positivity, completion, and symmetry alone cannot supply uniqueness.')
    for number in GLOBAL_TARGET_ORDER:
        lines.append('  TARGET ' + str(number) + ' SELECTOR_REQUIREMENTS = ' + ', '.join(GLOBAL_SELECTOR_INPUTS[number]))
    lines.append('  ALL_TWENTY_TWO_TARGETS_COVERED = ' + str(theorem['target_coverage_exact']))
    lines.append('  ALL_FINITE_LEVELS_EXACT = ' + str(theorem['all_finite_levels_exact']))
    lines.append('  SYMMETRY_ONLY_UNIQUE_SELECTOR_IMPOSSIBLE = ' + str(theorem['symmetry_only_unique_selector_impossible']))
    lines.append('  FINITE_ORIENTATION_DATA_DOES_NOT_SELECT_AN_INFINITE_BRANCH = ' + str(theorem['finite_orientation_data_does_not_select_infinite_branch']))
    lines.append('  FULL_INDEPENDENT_BIT_SPECIFICATION_IS_BRANCH_DATA = ' + str(theorem['full_independent_bit_specification_is_branch_data']))
    lines.append('  DETERMINISTIC_COMPATIBILITY_ALONE_IS_NOT_UNIQUE = ' + str(theorem['deterministic_compatibility_alone_is_not_unique']))
    lines.append('  TARGET_SPECIFIC_DYNAMICAL_UPDATE_STILL_REQUIRED = ' + str(theorem['target_specific_dynamical_update_still_required']))
    lines.append('UNIVERSAL_SELECTOR_OBSTRUCTION_THEOREM = ' + str(theorem['theorem_result']))
    lines.append('The theorem does not declare any unrestricted target complete. It proves that the missing uniqueness step cannot be obtained by renaming compatibility or completion as a selector. A genuine native dynamical law must be derived and then shown to be unique on each required global domain.')
    lines.append('QED')
    return '\n'.join(lines)


