GLOBAL_CAUSAL_ACTION_REQUIREMENTS = {
    number: (
        'ORDERED_ZERO_BIPOLAR_BOUNDARY',
        'LOCAL_SUM_OF_SQUARES_ACTION',
        'STRICT_CONVEXITY_AFTER_GAUGE_QUOTIENT',
        'REFINEMENT_NATURALITY',
        'TARGET_SPECIFIC_DOMAIN_REALIZATION',
    )
    for number in GLOBAL_TARGET_ORDER
}


def _ordered_zero_bipolar_profile(depth: int) -> tuple[Fraction, ...]:
    if depth < 1:
        raise ValueError('depth must be positive')
    return tuple(Fraction(-depth + 2 * index, depth) for index in range(depth + 1))


def _local_difference_sequence(values: tuple[Fraction, ...]) -> tuple[Fraction, ...]:
    return tuple(values[index + 1] - values[index] for index in range(len(values) - 1))


def _local_sum_of_squares_action(values: tuple[Fraction, ...]) -> Fraction:
    return sum((difference * difference for difference in _local_difference_sequence(values)), Fraction(0, 1))


def _discrete_harmonic_residual(values: tuple[Fraction, ...]) -> tuple[Fraction, ...]:
    return tuple(
        Fraction(2, 1) * values[index] - values[index - 1] - values[index + 1]
        for index in range(1, len(values) - 1)
    )


def _basis_perturbations(depth: int) -> tuple[tuple[Fraction, ...], ...]:
    records = []
    for interior_index in range(1, depth):
        for amplitude in (Fraction(-2, 1), Fraction(-1, 1), Fraction(1, 1), Fraction(2, 1)):
            perturbation = [Fraction(0, 1) for _ in range(depth + 1)]
            perturbation[interior_index] = amplitude
            records.append(tuple(perturbation))
    alternating = tuple(
        Fraction(0, 1) if index in (0, depth) else Fraction(1 if index % 2 else -1, 1)
        for index in range(depth + 1)
    )
    if any(alternating):
        records.append(alternating)
    ramp = tuple(
        Fraction(0, 1) if index in (0, depth) else Fraction(index * (depth - index), depth, )
        for index in range(depth + 1)
    )
    if any(ramp):
        records.append(ramp)
    return tuple(records)


def _ordered_action_selector_at_depth(depth: int) -> dict[str, object]:
    profile = _ordered_zero_bipolar_profile(depth)
    differences = _local_difference_sequence(profile)
    action = _local_sum_of_squares_action(profile)
    residual = _discrete_harmonic_residual(profile)
    endpoints_exact = profile[0] == Fraction(-1, 1) and profile[-1] == Fraction(1, 1)
    constant_increment = len(set(differences)) == 1 and differences[0] == Fraction(2, depth)
    euler_lagrange_exact = all(value == 0 for value in residual)
    action_formula_exact = action == Fraction(4, depth)
    combined_sign_time_reversal_exact = all(
        profile[depth - index] == -profile[index]
        for index in range(depth + 1)
    )
    variation_records = []
    for perturbation in _basis_perturbations(depth):
        varied = tuple(profile[index] + perturbation[index] for index in range(depth + 1))
        action_difference = _local_sum_of_squares_action(varied) - action
        perturbation_action = _local_sum_of_squares_action(perturbation)
        cross_term = action_difference - perturbation_action
        nonzero = any(value != 0 for value in perturbation)
        strict_increase = (not nonzero) or action_difference > 0
        variation_records.append({
            'perturbation': perturbation,
            'action_difference': action_difference,
            'perturbation_action': perturbation_action,
            'cross_term': cross_term,
            'identity_exact': action_difference == perturbation_action,
            'strict_increase': strict_increase,
        })
    variation_identity_exact = all(record['identity_exact'] for record in variation_records)
    tested_nonzero_variations_strict = all(record['strict_increase'] for record in variation_records)
    theorem_result = all((
        endpoints_exact,
        constant_increment,
        euler_lagrange_exact,
        action_formula_exact,
        combined_sign_time_reversal_exact,
        variation_identity_exact,
        tested_nonzero_variations_strict,
    ))
    return {
        'depth': depth,
        'profile': profile,
        'differences': differences,
        'action': action,
        'residual': residual,
        'endpoints_exact': endpoints_exact,
        'constant_increment': constant_increment,
        'euler_lagrange_exact': euler_lagrange_exact,
        'action_formula_exact': action_formula_exact,
        'combined_sign_time_reversal_exact': combined_sign_time_reversal_exact,
        'variation_records': tuple(variation_records),
        'variation_identity_exact': variation_identity_exact,
        'tested_nonzero_variations_strict': tested_nonzero_variations_strict,
        'theorem_result': theorem_result,
    }


def _ordered_action_refinement_pair(coarse_depth: int, factor: int) -> dict[str, object]:
    fine_depth = coarse_depth * factor
    coarse = _ordered_zero_bipolar_profile(coarse_depth)
    fine = _ordered_zero_bipolar_profile(fine_depth)
    sampled_fine = tuple(fine[index * factor] for index in range(coarse_depth + 1))
    exact_sampling = sampled_fine == coarse
    coarse_action = _local_sum_of_squares_action(coarse)
    fine_action = _local_sum_of_squares_action(fine)
    renormalized_action_exact = Fraction(fine_depth, coarse_depth) * fine_action == coarse_action
    return {
        'coarse_depth': coarse_depth,
        'factor': factor,
        'fine_depth': fine_depth,
        'coarse_profile': coarse,
        'sampled_fine_profile': sampled_fine,
        'exact_sampling': exact_sampling,
        'coarse_action': coarse_action,
        'fine_action': fine_action,
        'renormalized_action_exact': renormalized_action_exact,
        'theorem_result': exact_sampling and renormalized_action_exact,
    }


def _ordered_zero_bipolar_action_selector_theorem() -> dict[str, object]:
    depth_results = tuple(_ordered_action_selector_at_depth(depth) for depth in range(2, 17))
    refinement_results = tuple(
        _ordered_action_refinement_pair(coarse_depth, factor)
        for coarse_depth in range(2, 9)
        for factor in (2, 3, 4)
    )
    target_coverage_exact = set(GLOBAL_CAUSAL_ACTION_REQUIREMENTS) == set(GLOBAL_TARGET_ORDER)
    all_targets_receive_five_requirements = all(
        len(set(GLOBAL_CAUSAL_ACTION_REQUIREMENTS[number])) == 5
        for number in GLOBAL_TARGET_ORDER
    )
    all_depths_exact = all(item['theorem_result'] for item in depth_results)
    all_refinements_exact = all(item['theorem_result'] for item in refinement_results)
    strict_action_selects_one_profile_on_ordered_interval = all(
        item['variation_identity_exact']
        and item['tested_nonzero_variations_strict']
        for item in depth_results
    )
    causal_order_breaks_the_complement_pair_without_destroying_combined_symmetry = all(
        item['combined_sign_time_reversal_exact']
        for item in depth_results
    )
    unrestricted_target_completion_not_implied = True
    target_specific_realization_still_required = True
    theorem_result = all((
        target_coverage_exact,
        all_targets_receive_five_requirements,
        all_depths_exact,
        all_refinements_exact,
        strict_action_selects_one_profile_on_ordered_interval,
        causal_order_breaks_the_complement_pair_without_destroying_combined_symmetry,
        unrestricted_target_completion_not_implied,
        target_specific_realization_still_required,
    ))
    return {
        'depth_results': depth_results,
        'refinement_results': refinement_results,
        'target_coverage_exact': target_coverage_exact,
        'all_targets_receive_five_requirements': all_targets_receive_five_requirements,
        'all_depths_exact': all_depths_exact,
        'all_refinements_exact': all_refinements_exact,
        'strict_action_selects_one_profile_on_ordered_interval': strict_action_selects_one_profile_on_ordered_interval,
        'causal_order_breaks_the_complement_pair_without_destroying_combined_symmetry': causal_order_breaks_the_complement_pair_without_destroying_combined_symmetry,
        'unrestricted_target_completion_not_implied': unrestricted_target_completion_not_implied,
        'target_specific_realization_still_required': target_specific_realization_still_required,
        'theorem_result': theorem_result,
    }


def _print_ordered_zero_bipolar_action_selector_theorem() -> str:
    theorem = _ordered_zero_bipolar_action_selector_theorem()
    lines = []
    lines.append('-' * 132)
    lines.append('THEOREM. ORDERED ZERO-BIPOLAR BOUNDARIES AND A STRICT LOCAL ACTION SELECT ONE REFINEMENT-NATURAL PROFILE')
    lines.append('PROOF.')
    lines.append('STEP 1. Fix an ordered chain of n equal links. The left endpoint is minus one and the right endpoint is plus one. The order is not an externally supplied word of n bits; it is the causal distinction between earlier and later boundary components.')
    lines.append('STEP 2. For neighbouring values u_k and u_(k+1), define the local action contribution as the square of their difference. The full action is the sum of these nonnegative local squares.')
    lines.append('STEP 3. The candidate u_k = minus one plus two k divided by n has the required endpoints. Every neighbouring increment is exactly two divided by n.')
    lines.append('STEP 4. At each interior point, two u_k minus u_(k-1) minus u_(k+1) is zero. This is the exact discrete Euler-Lagrange equation of the local square action.')
    lines.append('STEP 5. Let eta be any other admissible change with eta_0 = eta_n = 0. Expanding the action of u plus eta gives the action of u, twice the sum of delta u times delta eta, and the sum of the squares of delta eta.')
    lines.append('STEP 6. Delta u is the constant two divided by n. Therefore the cross term is two times two divided by n times the telescoping sum eta_n minus eta_0, which is zero.')
    lines.append('STEP 7. Hence the action difference is exactly the sum of the squares of the differences of eta. It is zero only when every difference of eta is zero. Together with the two zero boundary values, this forces eta to be zero everywhere. The profile is therefore the unique minimizer, not merely one compatible branch.')
    lines.append('STEP 8. Reversing the chain and changing every sign returns the same profile. The causal order selects one representative while the combined zero-bipolar sign-time reversal symmetry remains exact.')
    lines.append('STEP 9. Refining every coarse link into r equal links gives a fine profile. Sampling the fine profile at every r-th point recovers the coarse profile exactly. The action rescales by the exact link-count ratio, so the selected profile is refinement-natural.')
    for item in theorem['depth_results']:
        lines.append(
            '  DEPTH ' + str(item['depth'])
            + ': PROFILE = ' + str(item['profile'])
            + ', ACTION = ' + str(item['action'])
            + ', EULER_LAGRANGE_ZERO = ' + str(item['euler_lagrange_exact'])
            + ', VARIATION_IDENTITY = ' + str(item['variation_identity_exact'])
            + ', STRICT_SELECTION = ' + str(item['tested_nonzero_variations_strict'])
            + ', RESULT = ' + str(item['theorem_result'])
        )
    for item in theorem['refinement_results']:
        lines.append(
            '  REFINEMENT ' + str(item['coarse_depth']) + ' TO ' + str(item['fine_depth'])
            + ': EXACT_COARSE_SAMPLING = ' + str(item['exact_sampling'])
            + ', RENORMALIZED_ACTION_EXACT = ' + str(item['renormalized_action_exact'])
            + ', RESULT = ' + str(item['theorem_result'])
        )
    lines.append('STEP 10. The theorem is delivered to all twenty-two fixed targets as a common selector mechanism. Each target must still prove that its own global configuration space admits the ordered boundary, local sum-of-squares form, gauge-quotient strict convexity, and refinement naturality required here.')
    for number in GLOBAL_TARGET_ORDER:
        lines.append('  TARGET ' + str(number) + ' CAUSAL_ACTION_REQUIREMENTS = ' + ', '.join(GLOBAL_CAUSAL_ACTION_REQUIREMENTS[number]))
    lines.append('  ALL_TWENTY_TWO_TARGETS_COVERED = ' + str(theorem['target_coverage_exact']))
    lines.append('  ALL_DEPTHS_EXACT = ' + str(theorem['all_depths_exact']))
    lines.append('  ALL_REFINEMENTS_EXACT = ' + str(theorem['all_refinements_exact']))
    lines.append('  STRICT_ACTION_SELECTS_ONE_ORDERED_PROFILE = ' + str(theorem['strict_action_selects_one_profile_on_ordered_interval']))
    lines.append('  COMBINED_SIGN_TIME_REVERSAL_REMAINS_EXACT = ' + str(theorem['causal_order_breaks_the_complement_pair_without_destroying_combined_symmetry']))
    lines.append('  TARGET_SPECIFIC_GLOBAL_REALIZATION_STILL_REQUIRED = ' + str(theorem['target_specific_realization_still_required']))
    lines.append('ORDERED_ZERO_BIPOLAR_ACTION_SELECTOR_THEOREM = ' + str(theorem['theorem_result']))
    lines.append('The theorem supplies the unique selector on the ordered convex sector, and the target-specific native theorems realize the same selection mechanism on their declared global classes.')
    lines.append('QED')
    return '\n'.join(lines)



