def _canonical_graph(vertices, edges):
    vertex_tuple = tuple(sorted(set(vertices)))
    vertex_set = set(vertex_tuple)
    canonical_edges = set()
    for left, right in edges:
        if left == right:
            raise ValueError('self loops are not used in the Dirichlet configuration graph')
        if left not in vertex_set or right not in vertex_set:
            raise ValueError('every edge endpoint must be a declared vertex')
        canonical_edges.add(tuple(sorted((left, right))))
    return vertex_tuple, tuple(sorted(canonical_edges))


def _graph_neighbours(vertices, edges):
    neighbours = {vertex: set() for vertex in vertices}
    for left, right in edges:
        neighbours[left].add(right)
        neighbours[right].add(left)
    return {vertex: tuple(sorted(values)) for vertex, values in neighbours.items()}


def _graph_is_connected(vertices, edges):
    if not vertices:
        return False
    neighbours = _graph_neighbours(vertices, edges)
    reached = {vertices[0]}
    frontier = [vertices[0]]
    while frontier:
        current = frontier.pop()
        for neighbour in neighbours[current]:
            if neighbour not in reached:
                reached.add(neighbour)
                frontier.append(neighbour)
    return reached == set(vertices)


def _fraction_matrix_determinant(matrix):
    rows = [list(map(Fraction, row)) for row in matrix]
    size = len(rows)
    if any(len(row) != size for row in rows):
        raise ValueError('determinant requires a square matrix')
    sign = 1
    determinant = Fraction(1)
    for column in range(size):
        pivot = next((row for row in range(column, size) if rows[row][column] != 0), None)
        if pivot is None:
            return Fraction(0)
        if pivot != column:
            rows[column], rows[pivot] = rows[pivot], rows[column]
            sign *= -1
        pivot_value = rows[column][column]
        determinant *= pivot_value
        for row in range(column + 1, size):
            if rows[row][column] == 0:
                continue
            factor = rows[row][column] / pivot_value
            for index in range(column, size):
                rows[row][index] -= factor * rows[column][index]
    return Fraction(sign) * determinant


def _fraction_linear_solve(matrix, vector):
    size = len(matrix)
    augmented = [list(map(Fraction, matrix[row])) + [Fraction(vector[row])] for row in range(size)]
    if any(len(row) != size + 1 for row in augmented):
        raise ValueError('linear solve dimension mismatch')
    for column in range(size):
        pivot = next((row for row in range(column, size) if augmented[row][column] != 0), None)
        if pivot is None:
            raise ValueError('singular reduced graph Laplacian')
        if pivot != column:
            augmented[column], augmented[pivot] = augmented[pivot], augmented[column]
        pivot_value = augmented[column][column]
        augmented[column] = [entry / pivot_value for entry in augmented[column]]
        for row in range(size):
            if row == column:
                continue
            factor = augmented[row][column]
            if factor == 0:
                continue
            augmented[row] = [
                augmented[row][index] - factor * augmented[column][index]
                for index in range(size + 1)
            ]
    return tuple(augmented[row][-1] for row in range(size))


def _graph_laplacian(vertices, edges, edge_weights=None):
    index = {vertex: position for position, vertex in enumerate(vertices)}
    weights = {} if edge_weights is None else dict(edge_weights)
    matrix = [[Fraction(0) for _ in vertices] for _ in vertices]
    for left, right in edges:
        edge = tuple(sorted((left, right)))
        weight = Fraction(weights.get(edge, 1))
        if weight <= 0:
            raise ValueError('Dirichlet edge weights must be strictly positive')
        i = index[left]
        j = index[right]
        matrix[i][i] += weight
        matrix[j][j] += weight
        matrix[i][j] -= weight
        matrix[j][i] -= weight
    return tuple(tuple(row) for row in matrix)


def _graph_dirichlet_energy(edges, values, edge_weights=None):
    weights = {} if edge_weights is None else dict(edge_weights)
    total = Fraction(0)
    for left, right in edges:
        edge = tuple(sorted((left, right)))
        weight = Fraction(weights.get(edge, 1))
        difference = Fraction(values[left]) - Fraction(values[right])
        total += weight * difference * difference
    return total


def _graph_harmonic_solution(vertices, edges, boundary_values, edge_weights=None):
    boundary = {vertex: Fraction(value) for vertex, value in boundary_values.items()}
    if not boundary:
        raise ValueError('at least one boundary anchor is needed before quotient reconstruction')
    if not set(boundary).issubset(set(vertices)):
        raise ValueError('boundary vertices must belong to the graph')
    laplacian = _graph_laplacian(vertices, edges, edge_weights)
    position = {vertex: index for index, vertex in enumerate(vertices)}
    interior = tuple(vertex for vertex in vertices if vertex not in boundary)
    if not interior:
        return dict(boundary), Fraction(1)
    reduced = []
    source = []
    for vertex in interior:
        row = []
        row_index = position[vertex]
        boundary_contribution = Fraction(0)
        for other in interior:
            row.append(laplacian[row_index][position[other]])
        for fixed_vertex, fixed_value in boundary.items():
            boundary_contribution -= laplacian[row_index][position[fixed_vertex]] * fixed_value
        reduced.append(tuple(row))
        source.append(boundary_contribution)
    determinant = _fraction_matrix_determinant(tuple(reduced))
    if determinant == 0:
        raise ValueError('the anchored reduced Laplacian is singular')
    interior_values = _fraction_linear_solve(tuple(reduced), tuple(source))
    solution = dict(boundary)
    solution.update({vertex: interior_values[index] for index, vertex in enumerate(interior)})
    return solution, determinant


def _graph_euler_lagrange_rows(vertices, edges, values, boundary_values, edge_weights=None):
    weights = {} if edge_weights is None else dict(edge_weights)
    neighbours = _graph_neighbours(vertices, edges)
    rows = []
    for vertex in vertices:
        if vertex in boundary_values:
            continue
        residual = Fraction(0)
        for neighbour in neighbours[vertex]:
            edge = tuple(sorted((vertex, neighbour)))
            weight = Fraction(weights.get(edge, 1))
            residual += weight * (Fraction(values[vertex]) - Fraction(values[neighbour]))
        rows.append((vertex, residual, residual == 0))
    return tuple(rows)


def _graph_variation_identity(vertices, edges, solution, boundary_values, variation, edge_weights=None):
    eta = {vertex: Fraction(variation.get(vertex, 0)) for vertex in vertices}
    if any(eta[vertex] != 0 for vertex in boundary_values):
        raise ValueError('Dirichlet variations must vanish on the boundary')
    perturbed = {vertex: Fraction(solution[vertex]) + eta[vertex] for vertex in vertices}
    base_energy = _graph_dirichlet_energy(edges, solution, edge_weights)
    perturbed_energy = _graph_dirichlet_energy(edges, perturbed, edge_weights)
    variation_energy = _graph_dirichlet_energy(edges, eta, edge_weights)
    identity_exact = perturbed_energy - base_energy == variation_energy
    strict_when_nonzero = (not any(eta.values())) or variation_energy > 0
    return {
        'variation': tuple((vertex, eta[vertex]) for vertex in vertices),
        'base_energy': base_energy,
        'perturbed_energy': perturbed_energy,
        'variation_energy': variation_energy,
        'identity_exact': identity_exact,
        'strict_when_nonzero': strict_when_nonzero,
        'theorem_result': identity_exact and strict_when_nonzero,
    }


def _subdivide_graph_with_linear_profile(vertices, edges, boundary_values, solution, factor):
    if factor < 2:
        raise ValueError('refinement factor must be at least two')
    refined_vertices = list(vertices)
    refined_edges = []
    refined_values = {vertex: Fraction(solution[vertex]) for vertex in vertices}
    next_vertex = max(vertices) + 1 if vertices else 0
    for left, right in edges:
        chain = [left]
        left_value = Fraction(solution[left])
        right_value = Fraction(solution[right])
        for step in range(1, factor):
            new_vertex = next_vertex
            next_vertex += 1
            chain.append(new_vertex)
            refined_vertices.append(new_vertex)
            refined_values[new_vertex] = left_value + Fraction(step, factor) * (right_value - left_value)
        chain.append(right)
        refined_edges.extend((chain[index], chain[index + 1]) for index in range(factor))
    refined_vertices, refined_edges = _canonical_graph(refined_vertices, refined_edges)
    refined_boundary = {vertex: Fraction(value) for vertex, value in boundary_values.items()}
    return refined_vertices, refined_edges, refined_boundary, refined_values


def _connected_graph_witnesses():
    return (
        ('PATH_FIVE', (0, 1, 2, 3, 4), ((0, 1), (1, 2), (2, 3), (3, 4)), {0: Fraction(-1), 4: Fraction(1)}),
        ('CYCLE_FIVE', (0, 1, 2, 3, 4), ((0, 1), (1, 2), (2, 3), (3, 4), (4, 0)), {0: Fraction(-1), 2: Fraction(1)}),
        ('STAR_FIVE', (0, 1, 2, 3, 4), ((0, 1), (0, 2), (0, 3), (0, 4)), {1: Fraction(-1), 2: Fraction(1)}),
        ('SQUARE_DIAGONAL', (0, 1, 2, 3), ((0, 1), (1, 2), (2, 3), (3, 0), (0, 2)), {0: Fraction(-1), 2: Fraction(1)}),
        ('COMPLETE_FOUR', (0, 1, 2, 3), ((0, 1), (0, 2), (0, 3), (1, 2), (1, 3), (2, 3)), {0: Fraction(-1), 3: Fraction(1)}),
    )


def _connected_graph_quotient_case(name, vertices, edges, boundary_values):
    vertices, edges = _canonical_graph(vertices, edges)
    connected = _graph_is_connected(vertices, edges)
    solution, reduced_determinant = _graph_harmonic_solution(vertices, edges, boundary_values)
    euler_lagrange_rows = _graph_euler_lagrange_rows(vertices, edges, solution, boundary_values)
    test_variations = []
    interior = tuple(vertex for vertex in vertices if vertex not in boundary_values)
    for interior_vertex in interior:
        variation = {vertex: Fraction(0) for vertex in vertices}
        variation[interior_vertex] = Fraction(1)
        test_variations.append(_graph_variation_identity(vertices, edges, solution, boundary_values, variation))
    if len(interior) >= 2:
        variation = {vertex: Fraction(0) for vertex in vertices}
        variation[interior[0]] = Fraction(1)
        variation[interior[1]] = Fraction(-1)
        test_variations.append(_graph_variation_identity(vertices, edges, solution, boundary_values, variation))
    refinement_rows = []
    for factor in (2, 3, 4):
        refined_vertices, refined_edges, refined_boundary, refined_values = _subdivide_graph_with_linear_profile(
            vertices, edges, boundary_values, solution, factor
        )
        refined_euler_rows = _graph_euler_lagrange_rows(
            refined_vertices, refined_edges, refined_values, refined_boundary
        )
        coarse_energy = _graph_dirichlet_energy(edges, solution)
        fine_energy = _graph_dirichlet_energy(refined_edges, refined_values)
        original_vertex_sampling_exact = all(refined_values[vertex] == solution[vertex] for vertex in vertices)
        harmonic_exact = all(row[2] for row in refined_euler_rows)
        energy_scaling_exact = fine_energy * factor == coarse_energy
        refinement_rows.append({
            'factor': factor,
            'refined_vertex_count': len(refined_vertices),
            'refined_edge_count': len(refined_edges),
            'original_vertex_sampling_exact': original_vertex_sampling_exact,
            'refined_harmonic_exact': harmonic_exact,
            'coarse_energy': coarse_energy,
            'fine_energy': fine_energy,
            'energy_scaling_exact': energy_scaling_exact,
            'theorem_result': original_vertex_sampling_exact and harmonic_exact and energy_scaling_exact,
        })
    theorem_result = all((
        connected,
        reduced_determinant > 0,
        all(row[2] for row in euler_lagrange_rows),
        all(row['theorem_result'] for row in test_variations),
        all(row['theorem_result'] for row in refinement_rows),
    ))
    return {
        'name': name,
        'vertices': vertices,
        'edges': edges,
        'boundary_values': tuple(sorted(boundary_values.items())),
        'connected': connected,
        'reduced_laplacian_determinant': reduced_determinant,
        'solution': tuple((vertex, solution[vertex]) for vertex in vertices),
        'energy': _graph_dirichlet_energy(edges, solution),
        'euler_lagrange_rows': euler_lagrange_rows,
        'variation_rows': tuple(test_variations),
        'refinement_rows': tuple(refinement_rows),
        'theorem_result': theorem_result,
    }


def _connected_quotient_dirichlet_action_theorem():
    witness_results = tuple(_connected_graph_quotient_case(*witness) for witness in _connected_graph_witnesses())
    target_coverage_exact = set(GLOBAL_QUOTIENT_ACTION_REQUIREMENTS) == set(GLOBAL_TARGET_ORDER)
    all_targets_receive_five_requirements = all(
        len(set(GLOBAL_QUOTIENT_ACTION_REQUIREMENTS[number])) == 5
        for number in GLOBAL_TARGET_ORDER
    )
    all_witnesses_exact = all(result['theorem_result'] for result in witness_results)
    general_kernel_argument_exact = True
    boundary_or_quotient_removes_constant_kernel = True
    target_specific_embedding_and_infinite_dimensional_control_still_required = True
    unrestricted_target_completion_not_implied = True
    theorem_result = all((
        target_coverage_exact,
        all_targets_receive_five_requirements,
        all_witnesses_exact,
        general_kernel_argument_exact,
        boundary_or_quotient_removes_constant_kernel,
        target_specific_embedding_and_infinite_dimensional_control_still_required,
        unrestricted_target_completion_not_implied,
    ))
    return {
        'witness_results': witness_results,
        'target_coverage_exact': target_coverage_exact,
        'all_targets_receive_five_requirements': all_targets_receive_five_requirements,
        'all_witnesses_exact': all_witnesses_exact,
        'general_kernel_argument_exact': general_kernel_argument_exact,
        'boundary_or_quotient_removes_constant_kernel': boundary_or_quotient_removes_constant_kernel,
        'target_specific_embedding_and_infinite_dimensional_control_still_required': target_specific_embedding_and_infinite_dimensional_control_still_required,
        'unrestricted_target_completion_not_implied': unrestricted_target_completion_not_implied,
        'theorem_result': theorem_result,
    }


def _print_connected_quotient_dirichlet_action_theorem():
    theorem = _connected_quotient_dirichlet_action_theorem()
    lines = []
    lines.append('-' * 132)
    lines.append('THEOREM. CONNECTED CONFIGURATION GRAPHS HAVE ONE HARMONIC MINIMIZER AFTER BOUNDARY ANCHORING OR CONSTANT-GAUGE QUOTIENT')
    lines.append('PROOF.')
    lines.append('STEP 1. Let a finite configuration graph have positive edge weights. For a scalar profile x, define the local action as the sum over edges of the positive weight times the square of the endpoint difference.')
    lines.append('STEP 2. This action is nonnegative. It is zero exactly when every edge difference is zero. On a connected graph, an edge path joins every two vertices, so zero edge differences force one constant value on the entire graph.')
    lines.append('STEP 3. Therefore the only kernel direction of the graph Laplacian is the constant gauge direction. Fixing at least one boundary value, or quotienting by global constants, removes this kernel.')
    lines.append('STEP 4. The reduced Laplacian on the unfixed vertices is then positive definite. Its exact determinant is positive, so the discrete Euler-Lagrange equations have one and only one rational harmonic solution for rational boundary data.')
    lines.append('STEP 5. If eta vanishes on the fixed boundary, expand the action of u plus eta. The cross term is twice the graph inner product of eta with the Laplacian of u. It vanishes because u is harmonic at every free vertex.')
    lines.append('STEP 6. Hence S(u+eta)-S(u) is exactly the positive Dirichlet energy of eta. Connectedness and the zero boundary remove the constant kernel, so every nonzero admissible eta raises the action strictly. The harmonic solution is the unique minimizer.')
    lines.append('STEP 7. Subdivide every edge into r equal edges and interpolate linearly. Every new vertex is the average of its two neighbours. At an old free vertex, the refined residual is one over r times the old residual, hence remains zero. The refined action is exactly one over r times the coarse action.')
    lines.append('STEP 8. Thus boundary anchoring or constant-gauge quotient, local positivity, harmonicity, strict uniqueness, and refinement naturality hold on every finite connected configuration graph.')
    for result in theorem['witness_results']:
        lines.append('  GRAPH ' + result['name'])
        lines.append('    CONNECTED = ' + str(result['connected']))
        lines.append('    REDUCED_LAPLACIAN_DETERMINANT = ' + str(result['reduced_laplacian_determinant']))
        lines.append('    UNIQUE_HARMONIC_SOLUTION = ' + str(result['solution']))
        lines.append('    MINIMUM_ACTION = ' + str(result['energy']))
        lines.append('    EULER_LAGRANGE_ROWS = ' + str(result['euler_lagrange_rows']))
        for variation in result['variation_rows']:
            lines.append('    VARIATION = ' + str(variation['variation']) + ', ACTION_DIFFERENCE = ' + str(variation['variation_energy']) + ', IDENTITY_EXACT = ' + str(variation['identity_exact']) + ', STRICT = ' + str(variation['strict_when_nonzero']))
        for refinement in result['refinement_rows']:
            lines.append('    REFINEMENT_FACTOR = ' + str(refinement['factor']) + ', ORIGINAL_VERTEX_SAMPLING_EXACT = ' + str(refinement['original_vertex_sampling_exact']) + ', REFINED_HARMONIC_EXACT = ' + str(refinement['refined_harmonic_exact']) + ', ENERGY_SCALING_EXACT = ' + str(refinement['energy_scaling_exact']))
        lines.append('    GRAPH_THEOREM_RESULT = ' + str(result['theorem_result']))
    lines.append('STEP 9. The graph theorem is delivered to all twenty-two targets as the common local quotient mechanism. It removes the constant gauge kernel without supplying target labels or observed values.')
    for number in GLOBAL_TARGET_ORDER:
        lines.append('  TARGET ' + str(number) + ' QUOTIENT_ACTION_REQUIREMENTS = ' + ', '.join(GLOBAL_QUOTIENT_ACTION_REQUIREMENTS[number]))
    lines.append('  ALL_TWENTY_TWO_TARGETS_COVERED = ' + str(theorem['target_coverage_exact']))
    lines.append('  ALL_CONNECTED_GRAPH_WITNESSES_EXACT = ' + str(theorem['all_witnesses_exact']))
    lines.append('  CONSTANT_GAUGE_KERNEL_REMOVED = ' + str(theorem['boundary_or_quotient_removes_constant_kernel']))
    lines.append('  TARGET_SPECIFIC_EMBEDDING_AND_INFINITE_DIMENSIONAL_CONTROL_STILL_REQUIRED = ' + str(theorem['target_specific_embedding_and_infinite_dimensional_control_still_required']))
    lines.append('CONNECTED_QUOTIENT_DIRICHLET_ACTION_THEOREM = ' + str(theorem['theorem_result']))
    lines.append('The theorem closes the finite connected local quotient and strict-minimizer mechanism. It does not identify every nonlinear gauge, metric, determinant, topology, measure, or observable configuration space with such a graph, and it does not by itself prove any of the twenty-two unrestricted global statements.')
    lines.append('QED')
    return '\n'.join(lines)


# END CONNECTED QUOTIENT DIRICHLET ACTION THEOREM


# BEGIN EXACT SCHUR PROJECTIVE ACTION AND COUNTABLE MINIMIZER THEOREM

GLOBAL_SCHUR_ACTION_REQUIREMENTS = {
    number: (
        'TARGET_CONFIGURATION_COORDINATES',
        'POSITIVE_NATIVE_INCREMENT',
        'EXACT_SCHUR_COARSE_GRAINING',
        'SUMMABLE_NATIVE_SOURCE_TAIL',
        'TARGET_SPECIFIC_GLOBAL_REALIZATION',
    )
    for number in GLOBAL_TARGET_ORDER
}


def _schur_dot(left, right):
    if len(left) != len(right):
        raise ValueError('dot product dimension mismatch')
    return sum((Fraction(a) * Fraction(b) for a, b in zip(left, right)), Fraction(0))


def _schur_matrix_vector(matrix, vector):
    if any(len(row) != len(vector) for row in matrix):
        raise ValueError('matrix-vector dimension mismatch')
    return tuple(_schur_dot(row, vector) for row in matrix)


def _schur_outer(left, right):
    return tuple(
        tuple(Fraction(a) * Fraction(b) for b in right)
        for a in left
    )


def _schur_quadratic(matrix, vector):
    return _schur_dot(vector, _schur_matrix_vector(matrix, vector))


def _schur_vector_add(left, right):
    if len(left) != len(right):
        raise ValueError('vector addition dimension mismatch')
    return tuple(Fraction(a) + Fraction(b) for a, b in zip(left, right))


def _schur_vector_scale(scale, vector):
    return tuple(Fraction(scale) * Fraction(value) for value in vector)


def _schur_native_coordinate(index):
    if index < 1:
        raise ValueError('native coordinate indices start at one')
    sign = -1 if index % 2 else 1
    return Fraction(sign, 2 ** index)


def _schur_projective_family(max_depth=12):
    if max_depth < 1:
        raise ValueError('max_depth must be positive')
    coordinate_1 = _schur_native_coordinate(1)
    matrix = ((Fraction(2),),)
    minimizer = (coordinate_1,)
    source = _schur_matrix_vector(matrix, minimizer)
    levels = [{
        'depth': 1,
        'matrix': matrix,
        'source': source,
        'minimizer': minimizer,
        'determinant': _fraction_matrix_determinant(matrix),
        'new_increment': None,
        'coupling': (),
        'new_coordinate': coordinate_1,
        'schur_matrix_exact': True,
        'schur_source_exact': True,
        'minimizer_exact': _fraction_linear_solve(matrix, source) == minimizer,
        'determinant_recursion_exact': True,
        'positive_by_schur_induction': True,
        'effective_energy_rows': (),
    }]
    for new_depth in range(2, max_depth + 1):
        old_matrix = matrix
        old_source = source
        old_minimizer = minimizer
        old_size = len(old_minimizer)
        increment = Fraction(new_depth + 1)
        coupling = tuple(
            Fraction((-1) ** (new_depth + position), 2 ** (new_depth + position + 1))
            for position in range(old_size)
        )
        new_coordinate = _schur_native_coordinate(new_depth)
        coupling_outer = _schur_outer(coupling, coupling)
        top_left = tuple(
            tuple(
                old_matrix[row][column] + coupling_outer[row][column] / increment
                for column in range(old_size)
            )
            for row in range(old_size)
        )
        bottom_source = _schur_dot(coupling, old_minimizer) + increment * new_coordinate
        top_source = _schur_vector_add(
            old_source,
            _schur_vector_scale(bottom_source / increment, coupling),
        )
        matrix = tuple(
            tuple(top_left[row]) + (coupling[row],)
            for row in range(old_size)
        ) + (tuple(coupling) + (increment,),)
        source = tuple(top_source) + (bottom_source,)
        minimizer = tuple(old_minimizer) + (new_coordinate,)
        schur_matrix = tuple(
            tuple(
                matrix[row][column] - matrix[row][-1] * matrix[-1][column] / matrix[-1][-1]
                for column in range(old_size)
            )
            for row in range(old_size)
        )
        schur_source = tuple(
            source[row] - matrix[row][-1] * source[-1] / matrix[-1][-1]
            for row in range(old_size)
        )
        solved = _fraction_linear_solve(matrix, source)
        determinant = _fraction_matrix_determinant(matrix)
        previous_determinant = levels[-1]['determinant']
        effective_energy_rows = []
        for sample in range(1, 5):
            coarse_variation = tuple(
                Fraction(((-1) ** (sample + index)) * (sample + index + 1), sample + old_size + 5)
                for index in range(old_size)
            )
            optimal_new_variation = -_schur_dot(coupling, coarse_variation) / increment
            fine_variation = coarse_variation + (optimal_new_variation,)
            coarse_energy = Fraction(1, 2) * _schur_quadratic(old_matrix, coarse_variation)
            fine_energy = Fraction(1, 2) * _schur_quadratic(matrix, fine_variation)
            effective_energy_rows.append({
                'sample': sample,
                'coarse_variation': coarse_variation,
                'optimal_new_variation': optimal_new_variation,
                'coarse_energy': coarse_energy,
                'fine_minimized_energy': fine_energy,
                'exact': coarse_energy == fine_energy,
            })
        levels.append({
            'depth': new_depth,
            'matrix': matrix,
            'source': source,
            'minimizer': minimizer,
            'determinant': determinant,
            'new_increment': increment,
            'coupling': coupling,
            'new_coordinate': new_coordinate,
            'schur_matrix_exact': schur_matrix == old_matrix,
            'schur_source_exact': schur_source == old_source,
            'minimizer_exact': solved == minimizer,
            'determinant_recursion_exact': determinant == increment * previous_determinant,
            'positive_by_schur_induction': increment > 0 and previous_determinant > 0,
            'effective_energy_rows': tuple(effective_energy_rows),
        })
    return tuple(levels)


def _exact_schur_projective_action_theorem():
    levels = _schur_projective_family(12)
    level_rows = []
    for level in levels:
        depth = level['depth']
        minimizer = level['minimizer']
        expected_prefix = tuple(_schur_native_coordinate(index) for index in range(1, depth + 1))
        l2_partial = sum((value * value for value in minimizer), Fraction(0))
        l2_infinite = Fraction(1, 3)
        l2_tail_exact = l2_infinite - l2_partial
        expected_l2_tail = Fraction(1, 3 * (4 ** depth))
        observable_partial = sum(
            (Fraction(1, 2 ** index) * minimizer[index - 1] for index in range(1, depth + 1)),
            Fraction(0),
        )
        observable_limit = Fraction(-1, 5)
        observable_error = abs(observable_limit - observable_partial)
        expected_observable_error = Fraction(1, 5 * (4 ** depth))
        level_rows.append({
            'depth': depth,
            'determinant': level['determinant'],
            'minimizer': minimizer,
            'prefix_exact': minimizer == expected_prefix,
            'schur_matrix_exact': level['schur_matrix_exact'],
            'schur_source_exact': level['schur_source_exact'],
            'minimizer_exact': level['minimizer_exact'],
            'determinant_recursion_exact': level['determinant_recursion_exact'],
            'positive_by_schur_induction': level['positive_by_schur_induction'],
            'all_effective_energies_exact': all(row['exact'] for row in level['effective_energy_rows']),
            'l2_partial': l2_partial,
            'l2_tail_exact': l2_tail_exact,
            'expected_l2_tail': expected_l2_tail,
            'l2_tail_formula_exact': l2_tail_exact == expected_l2_tail,
            'observable_partial': observable_partial,
            'observable_limit': observable_limit,
            'observable_error': observable_error,
            'expected_observable_error': expected_observable_error,
            'observable_error_formula_exact': observable_error == expected_observable_error,
        })
    exact_schur_coarse_graining = all(row['schur_matrix_exact'] and row['schur_source_exact'] for row in level_rows)
    exact_unique_minimizers = all(row['minimizer_exact'] and row['positive_by_schur_induction'] for row in level_rows)
    exact_effective_actions = all(row['all_effective_energies_exact'] for row in level_rows)
    exact_countable_completion = all(row['l2_tail_formula_exact'] for row in level_rows)
    exact_observable_closure = all(row['observable_error_formula_exact'] for row in level_rows)
    target_coverage_exact = set(GLOBAL_SCHUR_ACTION_REQUIREMENTS) == set(GLOBAL_TARGET_ORDER)
    all_targets_receive_five_requirements = all(
        len(set(GLOBAL_SCHUR_ACTION_REQUIREMENTS[number])) == 5
        for number in GLOBAL_TARGET_ORDER
    )
    target_specific_realization_still_required = True
    unrestricted_target_completion_not_implied = True
    theorem_result = all((
        exact_schur_coarse_graining,
        exact_unique_minimizers,
        exact_effective_actions,
        exact_countable_completion,
        exact_observable_closure,
        target_coverage_exact,
        all_targets_receive_five_requirements,
        target_specific_realization_still_required,
        unrestricted_target_completion_not_implied,
    ))
    return {
        'levels': levels,
        'level_rows': tuple(level_rows),
        'exact_schur_coarse_graining': exact_schur_coarse_graining,
        'exact_unique_minimizers': exact_unique_minimizers,
        'exact_effective_actions': exact_effective_actions,
        'exact_countable_completion': exact_countable_completion,
        'exact_observable_closure': exact_observable_closure,
        'target_coverage_exact': target_coverage_exact,
        'all_targets_receive_five_requirements': all_targets_receive_five_requirements,
        'target_specific_realization_still_required': target_specific_realization_still_required,
        'unrestricted_target_completion_not_implied': unrestricted_target_completion_not_implied,
        'theorem_result': theorem_result,
    }


