def _coupled_block_diagonal(base_matrix, channel_scales):
    block_size = len(base_matrix)
    channel_count = len(channel_scales)
    size = block_size * channel_count
    matrix = [[Fraction(0) for _ in range(size)] for _ in range(size)]
    for channel, scale in enumerate(channel_scales):
        offset = channel * block_size
        for row in range(block_size):
            for column in range(block_size):
                matrix[offset + row][offset + column] = Fraction(scale) * Fraction(base_matrix[row][column])
    return tuple(tuple(row) for row in matrix)


def _coupled_concatenate_channel_profiles(base_profile, profile_scales):
    return tuple(
        Fraction(scale) * Fraction(value)
        for scale in profile_scales
        for value in base_profile
    )


def _coupled_persistent_column(depth, channel_count):
    values = []
    for channel in range(channel_count):
        channel_value = Fraction((-1) ** channel, channel + 2)
        for coordinate in range(depth):
            values.append(channel_value if coordinate == 0 else Fraction(0))
    return tuple(values)


def _coupled_rank_one_matrix(column, increment):
    return tuple(
        tuple(Fraction(left) * Fraction(right) / Fraction(increment) for right in column)
        for left in column
    )


def _coupled_matrix_add(left, right):
    if len(left) != len(right) or any(len(a) != len(b) for a, b in zip(left, right)):
        raise ValueError('matrix addition dimension mismatch')
    return tuple(
        tuple(Fraction(a) + Fraction(b) for a, b in zip(left_row, right_row))
        for left_row, right_row in zip(left, right)
    )


def _coupled_schur_eliminate_label(matrix, source, labels, eliminated_label):
    index = labels.index(eliminated_label)
    pivot = Fraction(matrix[index][index])
    if pivot == 0:
        raise ValueError('Schur elimination requires a nonzero pivot')
    keep = tuple(position for position in range(len(labels)) if position != index)
    reduced_matrix = tuple(
        tuple(
            Fraction(matrix[row][column])
            - Fraction(matrix[row][index]) * Fraction(matrix[index][column]) / pivot
            for column in keep
        )
        for row in keep
    )
    reduced_source = tuple(
        Fraction(source[row]) - Fraction(matrix[row][index]) * Fraction(source[index]) / pivot
        for row in keep
    )
    reduced_labels = tuple(labels[position] for position in keep)
    return reduced_matrix, reduced_source, reduced_labels


def _coupled_twenty_two_action_level(base_level, prior_level=None):
    depth = int(base_level['depth'])
    channel_numbers = tuple(GLOBAL_TARGET_ORDER)
    channel_count = len(channel_numbers)
    channel_scales = tuple(Fraction(position + 1) for position in range(channel_count))
    profile_scales = tuple(Fraction((-1) ** position, position + 1) for position in range(channel_count))
    base_matrix = base_level['matrix']
    base_profile = base_level['minimizer']
    direct_matrix = _coupled_block_diagonal(base_matrix, channel_scales)
    coupled_profile = _coupled_concatenate_channel_profiles(base_profile, profile_scales)
    direct_source = _schur_matrix_vector(direct_matrix, coupled_profile)
    coupling_column = _coupled_persistent_column(depth, channel_count)
    global_increment = Fraction(channel_count + 1)
    global_coordinate = Fraction(1, channel_count + 1)
    rank_one = _coupled_rank_one_matrix(coupling_column, global_increment)
    top_left = _coupled_matrix_add(direct_matrix, rank_one)
    bottom_source = _schur_dot(coupling_column, coupled_profile) + global_increment * global_coordinate
    top_source = _schur_vector_add(
        direct_source,
        _schur_vector_scale(bottom_source / global_increment, coupling_column),
    )
    full_matrix = tuple(
        tuple(top_left[row]) + (coupling_column[row],)
        for row in range(len(top_left))
    ) + (tuple(coupling_column) + (global_increment,),)
    full_source = tuple(top_source) + (bottom_source,)
    full_profile = tuple(coupled_profile) + (global_coordinate,)
    equation_exact = _schur_matrix_vector(full_matrix, full_profile) == full_source
    global_schur_matrix = tuple(
        tuple(
            full_matrix[row][column]
            - full_matrix[row][-1] * full_matrix[-1][column] / full_matrix[-1][-1]
            for column in range(len(direct_matrix))
        )
        for row in range(len(direct_matrix))
    )
    global_schur_source = tuple(
        full_source[row] - full_matrix[row][-1] * full_source[-1] / full_matrix[-1][-1]
        for row in range(len(direct_source))
    )
    global_coordinate_elimination_exact = (
        global_schur_matrix == direct_matrix
        and global_schur_source == direct_source
    )
    determinant_formula = global_increment
    for scale in channel_scales:
        determinant_formula *= (Fraction(scale) ** depth) * Fraction(base_level['determinant'])
    positive_determinant = determinant_formula > 0
    first_coordinate = coupled_profile[0]
    ratio_rows = tuple(
        (
            channel_numbers[channel],
            coupled_profile[channel * depth] / first_coordinate,
            profile_scales[channel] / profile_scales[0],
            coupled_profile[channel * depth] / first_coordinate == profile_scales[channel] / profile_scales[0],
        )
        for channel in range(channel_count)
    )
    refinement_exact = True
    eliminated_dimension = None
    if prior_level is not None:
        labels = tuple(
            ('TARGET', channel_numbers[channel], coordinate + 1)
            for channel in range(channel_count)
            for coordinate in range(depth)
        ) + (('GLOBAL', 0, 0),)
        reduced_matrix = full_matrix
        reduced_source = full_source
        reduced_labels = labels
        for channel in reversed(range(channel_count)):
            target_label = ('TARGET', channel_numbers[channel], depth)
            reduced_matrix, reduced_source, reduced_labels = _coupled_schur_eliminate_label(
                reduced_matrix,
                reduced_source,
                reduced_labels,
                target_label,
            )
        refinement_exact = (
            reduced_matrix == prior_level['full_matrix']
            and reduced_source == prior_level['full_source']
            and reduced_labels == prior_level['labels']
        )
        eliminated_dimension = len(full_matrix) - len(reduced_matrix)
    labels = tuple(
        ('TARGET', channel_numbers[channel], coordinate + 1)
        for channel in range(channel_count)
        for coordinate in range(depth)
    ) + (('GLOBAL', 0, 0),)
    l2_partial = sum((value * value for value in coupled_profile), Fraction(0))
    profile_scale_square_sum = sum((scale * scale for scale in profile_scales), Fraction(0))
    l2_tail = profile_scale_square_sum * Fraction(1, 3 * (4 ** depth))
    return {
        'depth': depth,
        'degrees_of_freedom': len(full_matrix),
        'full_matrix': full_matrix,
        'full_source': full_source,
        'full_profile': full_profile,
        'labels': labels,
        'equation_exact': equation_exact,
        'global_coordinate_elimination_exact': global_coordinate_elimination_exact,
        'determinant_formula': determinant_formula,
        'positive_determinant': positive_determinant,
        'ratio_rows': ratio_rows,
        'all_ratios_exact': all(row[3] for row in ratio_rows),
        'refinement_exact': refinement_exact,
        'eliminated_dimension': eliminated_dimension,
        'l2_partial': l2_partial,
        'l2_tail': l2_tail,
        'profile_scale_square_sum': profile_scale_square_sum,
    }


def _twenty_two_channel_coupled_action_theorem():
    base_levels = _schur_projective_family(6)
    levels = []
    prior = None
    for base_level in base_levels:
        current = _coupled_twenty_two_action_level(base_level, prior)
        levels.append(current)
        prior = current
    channel_count_exact = len(GLOBAL_TARGET_ORDER) == 22
    all_equations_exact = all(level['equation_exact'] for level in levels)
    all_global_schur_exact = all(level['global_coordinate_elimination_exact'] for level in levels)
    all_determinants_positive = all(level['positive_determinant'] for level in levels)
    all_refinements_exact = all(level['refinement_exact'] for level in levels)
    all_ratio_decoders_exact = all(level['all_ratios_exact'] for level in levels)
    degree_counts_exact = all(
        level['degrees_of_freedom'] == 22 * level['depth'] + 1
        for level in levels
    )
    l2_tail_decreases_exactly = all(
        levels[index + 1]['l2_tail'] * 4 == levels[index]['l2_tail']
        for index in range(len(levels) - 1)
    )
    theorem_result = all((
        channel_count_exact,
        all_equations_exact,
        all_global_schur_exact,
        all_determinants_positive,
        all_refinements_exact,
        all_ratio_decoders_exact,
        degree_counts_exact,
        l2_tail_decreases_exactly,
    ))
    return {
        'levels': tuple(levels),
        'channel_count_exact': channel_count_exact,
        'all_equations_exact': all_equations_exact,
        'all_global_schur_exact': all_global_schur_exact,
        'all_determinants_positive': all_determinants_positive,
        'all_refinements_exact': all_refinements_exact,
        'all_ratio_decoders_exact': all_ratio_decoders_exact,
        'degree_counts_exact': degree_counts_exact,
        'l2_tail_decreases_exactly': l2_tail_decreases_exactly,
        'theorem_result': theorem_result,
    }


def _print_twenty_two_channel_coupled_action_theorem():
    theorem = _twenty_two_channel_coupled_action_theorem()
    lines = []
    lines.append('-' * 132)
    lines.append('THEOREM. ONE POSITIVE COUPLED ACTION JOINS ALL TWENTY TWO TARGET CHANNELS AND COMMUTES WITH REFINEMENT')
    lines.append('PROOF.')
    lines.append('STEP 1. Place the twenty-two target channels in the fixed theorem order. Give every channel a positive rational scale and the same Schur-compatible projective coordinate system, multiplied by a channel-specific zero-bipolar sign and rational magnitude.')
