# BEGIN RESIDUAL DIMENSION GENESIS THEOREM


def _residual_matrix_product(left, right):
    return tuple(
        tuple(
            sum((Fraction(left[row][inner]) * Fraction(right[inner][column]) for inner in range(2)), Fraction(0))
            for column in range(2)
        )
        for row in range(2)
    )


def _residual_matrix_scale(matrix, scalar):
    factor = Fraction(scalar)
    return tuple(tuple(factor * Fraction(value) for value in row) for row in matrix)


def _residual_matrix_trace(matrix):
    return sum((Fraction(matrix[index][index]) for index in range(2)), Fraction(0))


def _residual_inner(left, right):
    return sum(
        (Fraction(left[row][column]) * Fraction(right[row][column]) for row in range(2) for column in range(2)),
        Fraction(0),
    ) / 2


def _residual_flatten(matrix):
    return tuple(Fraction(matrix[row][column]) for row in range(2) for column in range(2))


def _residual_gram(matrices):
    return tuple(tuple(_residual_inner(left, right) for right in matrices) for left in matrices)


def _positive_compositions(total):
    if total == 0:
        return ((),)
    rows = []
    for first in range(1, total + 1):
        for tail in _positive_compositions(total - first):
            rows.append((first,) + tail)
    return tuple(rows)


def _route_name(composition):
    if composition == (1, 1, 1):
        return 'FULLY_SEQUENTIAL'
    if composition == (3,):
        return 'DIRECT_RANK_THREE'
    return 'MIXED_' + '_'.join(str(value) for value in composition)


def _route_record(composition, residual_basis):
    active_count = 0
    rank_path = [0]
    anisotropy_path = []
    for jump in composition:
        active_count += jump
        active = residual_basis[:active_count]
        rank_path.append(fraction_rank(tuple(_residual_flatten(matrix) for matrix in active)))
        covariance_diagonal = tuple(Fraction(1) if index < active_count else Fraction(0) for index in range(3))
        anisotropy_path.append(max(covariance_diagonal) - min(covariance_diagonal))
    jump_square_action = sum((jump * jump for jump in composition))
    return {
        'name': _route_name(composition),
        'composition': composition,
        'rank_path': tuple(rank_path),
        'event_count': len(composition),
        'first_nonzero_rank': rank_path[1],
        'maximum_rank_jump': max(composition),
        'jump_square_action': jump_square_action,
        'anisotropy_path': tuple(anisotropy_path),
        'transient_anisotropy_present': any(value != 0 for value in anisotropy_path[:-1]),
        'shell_closure_event': len(composition),
        'final_rank': rank_path[-1],
    }


def _archimedean_closure_bounds(iterations=12):
    decimal_two = Decimal(2)
    side = decimal_two.sqrt()
    edge_count = 4
    rows = []
    for step in range(iterations + 1):
        half_chord = side / decimal_two
        apothem = (Decimal(1) - half_chord * half_chord).sqrt()
        lower = Decimal(edge_count) * side / decimal_two
        upper = Decimal(edge_count) * half_chord / apothem
        rows.append({
            'step': step,
            'edge_count': edge_count,
            'lower_closure_constant': +lower,
            'upper_closure_constant': +upper,
            'interval_width': +(upper - lower),
            'contains_internal_circle_constant': lower < PI_D < upper,
        })
        inner = Decimal(4) - side * side
        side = (decimal_two - inner.sqrt()).sqrt()
        edge_count *= 2
    lower_monotone = all(rows[index]['lower_closure_constant'] < rows[index + 1]['lower_closure_constant'] for index in range(len(rows) - 1))
    upper_monotone = all(rows[index]['upper_closure_constant'] > rows[index + 1]['upper_closure_constant'] for index in range(len(rows) - 1))
    widths_shrink = all(rows[index]['interval_width'] > rows[index + 1]['interval_width'] for index in range(len(rows) - 1))
    all_contain = all(row['contains_internal_circle_constant'] for row in rows)
    return {
        'rows': tuple(rows),
        'lower_monotone': lower_monotone,
        'upper_monotone': upper_monotone,
        'widths_shrink': widths_shrink,
        'all_contain_internal_circle_constant': all_contain,
    }


