def _residual_dimension_genesis_theorem():
    identity = ((Fraction(1), Fraction(0)), (Fraction(0), Fraction(1)))
    polar = ((Fraction(1), Fraction(0)), (Fraction(0), Fraction(-1)))
    quarter_turn = ((Fraction(0), Fraction(-1)), (Fraction(1), Fraction(0)))
    polar_turn = _residual_matrix_product(polar, quarter_turn)
    negative_polar_turn = _residual_matrix_scale(polar_turn, -1)

    origin_relations = {
        'P_SQUARED_EQUALS_I': _residual_matrix_product(polar, polar) == identity,
        'J_SQUARED_EQUALS_MINUS_I': _residual_matrix_product(quarter_turn, quarter_turn) == _residual_matrix_scale(identity, -1),
        'PJ_EQUALS_DEFINED_POLAR_TURN': _residual_matrix_product(polar, quarter_turn) == polar_turn,
        'JP_EQUALS_MINUS_PJ': _residual_matrix_product(quarter_turn, polar) == negative_polar_turn,
    }
    residual_basis = (polar, quarter_turn, polar_turn)
    residual_gram = _residual_gram(residual_basis)
    residual_rank = fraction_rank(tuple(_residual_flatten(matrix) for matrix in residual_basis))
    full_algebra_rank = fraction_rank(tuple(_residual_flatten(matrix) for matrix in (identity,) + residual_basis))
    residual_traces = tuple(_residual_matrix_trace(matrix) for matrix in residual_basis)
    trace_functional_rank = fraction_rank(((Fraction(2), Fraction(0), Fraction(0), Fraction(0)),))
    traceless_nullity = full_algebra_rank - trace_functional_rank
    equal_orthonormal_residuals = residual_gram == (
        (Fraction(1), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(1), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(1)),
    )
    exact_rank_three_residual_sector = residual_rank == 3 and traceless_nullity == 3 and residual_traces == (0, 0, 0)

    compositions = tuple(sorted(_positive_compositions(3), key=lambda row: (len(row), row)))
    route_records = tuple(_route_record(composition, residual_basis) for composition in compositions)
    composition_set_exact = set(compositions) == {(3,), (1, 2), (2, 1), (1, 1, 1)}
    every_route_reaches_rank_three = all(record['final_rank'] == 3 for record in route_records)
    direct_route = next(record for record in route_records if record['composition'] == (3,))
    sequential_route = next(record for record in route_records if record['composition'] == (1, 1, 1))
    direct_and_sequential_distinguishable = (
        direct_route['first_nonzero_rank'] == 3
        and sequential_route['first_nonzero_rank'] == 1
        and direct_route['event_count'] == 1
        and sequential_route['event_count'] == 3
        and direct_route['jump_square_action'] != sequential_route['jump_square_action']
    )
    no_route_preselected_by_final_rank = len({record['final_rank'] for record in route_records}) == 1
    route_permutation_equivalence = all(
        _residual_gram(tuple(residual_basis[index] for index in permutation)) == residual_gram
        for permutation in itertools.permutations(range(3))
    )

    shell = p_native_shell_cells()
    shell_vertices = shell['VERTICES']
    shell_edges = shell['EDGES']
    shell_faces = shell['FACES']
    shell_boundary_zero = association_scheme_multiply(shell['BOUNDARY_1'], shell['BOUNDARY_2']) == tuple(
        tuple(Fraction(0) for _ in shell_faces) for _ in shell_vertices
    )
    shell_norms = tuple(sum((Fraction(component * component) for component in vertex), Fraction(0)) for vertex in shell_vertices)
    shell_centroid = tuple(sum((Fraction(vertex[axis]) for vertex in shell_vertices), Fraction(0)) for axis in range(3))
    face_sizes = tuple(len(face) for face in shell_faces)
    shell_euler_characteristic = len(shell_vertices) - len(shell_edges) + len(shell_faces)
    pairwise_superposition_shell_exact = (
        len(shell_vertices) == 12
        and set(shell_vertices) == set(_C12_VERTICES)
        and all(norm == 2 for norm in shell_norms)
        and shell_centroid == (0, 0, 0)
        and len(shell_edges) == 24
        and len(shell_faces) == 14
        and face_sizes.count(3) == 8
        and face_sizes.count(4) == 6
        and shell_euler_characteristic == 2
        and shell_boundary_zero
    )

    residual_squared_constant = residual_gram[0][0]
    residual_squared_ratios = tuple(residual_gram[index][index] / residual_squared_constant for index in range(3))
    superposition_radius_squared_ratio = shell_norms[0] / residual_squared_constant
    residual_constant_exact = (
        residual_squared_constant == 1
        and residual_squared_ratios == (1, 1, 1)
        and superposition_radius_squared_ratio == 2
    )

    closure_bounds = _archimedean_closure_bounds(12)
    final_closure_row = closure_bounds['rows'][-1]
    closure_constant_emerges_without_angle_functions = all((
        closure_bounds['lower_monotone'],
        closure_bounds['upper_monotone'],
        closure_bounds['widths_shrink'],
        closure_bounds['all_contain_internal_circle_constant'],
        final_closure_row['interval_width'] < Decimal('0.0000001'),
    ))

    target_objects = _residual_target_objects()
    target_order_exact = tuple(target_objects) == GLOBAL_TARGET_ORDER
    all_targets_receive_residual_objects = (
        set(target_objects) == set(GLOBAL_TARGET_ORDER)
        and all(len(target_objects[number]) >= 2 for number in GLOBAL_TARGET_ORDER)
    )

    blind_route_discriminators = {
        'FIRST_NONZERO_RESIDUAL_RANK': tuple((record['name'], record['first_nonzero_rank']) for record in route_records),
        'RANK_TRAJECTORY': tuple((record['name'], record['rank_path']) for record in route_records),
        'MICROEVENT_COUNT': tuple((record['name'], record['event_count']) for record in route_records),
        'TRANSIENT_ANISOTROPY': tuple((record['name'], record['transient_anisotropy_present']) for record in route_records),
        'RANK_JUMP_SQUARE_ACTION': tuple((record['name'], record['jump_square_action']) for record in route_records),
        'SHELL_CLOSURE_EVENT': tuple((record['name'], record['shell_closure_event']) for record in route_records),
    }

    theorem_result = all((
        all(origin_relations.values()),
        equal_orthonormal_residuals,
        exact_rank_three_residual_sector,
        full_algebra_rank == 4,
        composition_set_exact,
        every_route_reaches_rank_three,
        direct_and_sequential_distinguishable,
        no_route_preselected_by_final_rank,
        route_permutation_equivalence,
        pairwise_superposition_shell_exact,
        residual_constant_exact,
        closure_constant_emerges_without_angle_functions,
        target_order_exact,
        all_targets_receive_residual_objects,
    ))
    return {
        'identity': identity,
        'polar': polar,
        'quarter_turn': quarter_turn,
        'polar_turn': polar_turn,
        'origin_relations': origin_relations,
        'residual_gram': residual_gram,
        'residual_rank': residual_rank,
        'full_algebra_rank': full_algebra_rank,
        'residual_traces': residual_traces,
        'traceless_nullity': traceless_nullity,
        'equal_orthonormal_residuals': equal_orthonormal_residuals,
        'exact_rank_three_residual_sector': exact_rank_three_residual_sector,
        'route_records': route_records,
        'composition_set_exact': composition_set_exact,
        'every_route_reaches_rank_three': every_route_reaches_rank_three,
        'direct_and_sequential_distinguishable': direct_and_sequential_distinguishable,
        'no_route_preselected_by_final_rank': no_route_preselected_by_final_rank,
        'route_permutation_equivalence': route_permutation_equivalence,
        'shell_vertex_count': len(shell_vertices),
        'shell_edge_count': len(shell_edges),
        'shell_face_count': len(shell_faces),
        'shell_triangle_count': face_sizes.count(3),
        'shell_square_count': face_sizes.count(4),
        'shell_euler_characteristic': shell_euler_characteristic,
        'shell_boundary_zero': shell_boundary_zero,
        'pairwise_superposition_shell_exact': pairwise_superposition_shell_exact,
        'residual_squared_constant': residual_squared_constant,
        'residual_squared_ratios': residual_squared_ratios,
        'superposition_radius_squared_ratio': superposition_radius_squared_ratio,
        'residual_constant_exact': residual_constant_exact,
        'closure_bounds': closure_bounds,
        'closure_constant_emerges_without_angle_functions': closure_constant_emerges_without_angle_functions,
        'blind_route_discriminators': blind_route_discriminators,
        'target_objects': target_objects,
        'target_order_exact': target_order_exact,
        'all_targets_receive_residual_objects': all_targets_receive_residual_objects,
        'theorem_result': theorem_result,
    }


def _print_residual_dimension_genesis_theorem():
    theorem = _residual_dimension_genesis_theorem()
    lines = []
    lines.append('-' * 132)
    lines.append('THEOREM. ZERO-BIPOLAR NONCLOSURE HAS AN EXACT RANK-THREE RESIDUAL SECTOR AND FOUR COMPETING DIMENSION-GENESIS ROUTES')
    lines.append('PROOF.')
    lines.append('STEP 1. Use only the origin relations P squared equals I, J squared equals minus I, and PJ equals minus JP. Form the nonidentity residual matrices P, J, and PJ.')
    for label, value in theorem['origin_relations'].items():
        lines.append(label + ' = ' + str(value))
    lines.append('STEP 2. Normalize the matrix inner product by the identity norm. The three residual matrices are exactly orthonormal, traceless, and linearly independent.')
    lines.append('RESIDUAL_GRAM_MATRIX = ' + str(theorem['residual_gram']))
    lines.append('RESIDUAL_SECTOR_RANK = ' + str(theorem['residual_rank']))
    lines.append('FULL_ORIGIN_ALGEBRA_RANK = ' + str(theorem['full_algebra_rank']))
    lines.append('TRACELESS_RESIDUAL_NULLITY = ' + str(theorem['traceless_nullity']))
    lines.append('EQUAL_ORTHONORMAL_RESIDUALS = ' + str(theorem['equal_orthonormal_residuals']))
    lines.append('EXACT_RANK_THREE_RESIDUAL_SECTOR = ' + str(theorem['exact_rank_three_residual_sector']))
    lines.append('STEP 3. Generate every ordered composition of the rank increase from zero to three. This gives sequential, two mixed, and direct genesis routes without selecting one in advance.')
    for record in theorem['route_records']:
        lines.append('ROUTE ' + record['name'])
        lines.append('  ACTIVATION_COMPOSITION = ' + str(record['composition']))
        lines.append('  RESIDUAL_RANK_PATH = ' + str(record['rank_path']))
        lines.append('  FIRST_NONZERO_RANK = ' + str(record['first_nonzero_rank']))
        lines.append('  MICROEVENT_COUNT = ' + str(record['event_count']))
        lines.append('  MAXIMUM_RANK_JUMP = ' + str(record['maximum_rank_jump']))
        lines.append('  RANK_JUMP_SQUARE_ACTION = ' + str(record['jump_square_action']))
        lines.append('  TRANSIENT_ANISOTROPY_PRESENT = ' + str(record['transient_anisotropy_present']))
        lines.append('  SHELL_CLOSURE_EVENT = ' + str(record['shell_closure_event']))
    lines.append('ALL_ORDERED_RANK_COMPOSITIONS_PRESENT = ' + str(theorem['composition_set_exact']))
    lines.append('EVERY_ROUTE_REACHES_RANK_THREE = ' + str(theorem['every_route_reaches_rank_three']))
    lines.append('DIRECT_AND_SEQUENTIAL_ROUTES_DISTINGUISHABLE = ' + str(theorem['direct_and_sequential_distinguishable']))
    lines.append('FINAL_RANK_ALONE_DOES_NOT_SELECT_ROUTE = ' + str(theorem['no_route_preselected_by_final_rank']))
    lines.append('ALL_SIX_RESIDUAL_BASIS_ORDERS_GRAM_EQUIVALENT = ' + str(theorem['route_permutation_equivalence']))
    lines.append('STEP 4. Apply the zero-bipolar signs to every pairwise superposition of the three residual directions. The twelve equal-radius states form one closed shell with eight triangular and six square faces.')
    lines.append('SHELL_VERTEX_COUNT = ' + str(theorem['shell_vertex_count']))
    lines.append('SHELL_EDGE_COUNT = ' + str(theorem['shell_edge_count']))
    lines.append('SHELL_FACE_COUNT = ' + str(theorem['shell_face_count']))
    lines.append('SHELL_TRIANGLE_COUNT = ' + str(theorem['shell_triangle_count']))
    lines.append('SHELL_SQUARE_COUNT = ' + str(theorem['shell_square_count']))
    lines.append('SHELL_EULER_CHARACTERISTIC = ' + str(theorem['shell_euler_characteristic']))
    lines.append('SHELL_BOUNDARY_OF_BOUNDARY_ZERO = ' + str(theorem['shell_boundary_zero']))
    lines.append('PAIRWISE_SUPERPOSITION_SHELL_EXACT = ' + str(theorem['pairwise_superposition_shell_exact']))
    lines.append('STEP 5. The normalized squared residual magnitude is one in all three directions. Every pairwise shell state has squared radius two. These are internal ratios, not fitted physical lengths.')
    lines.append('RESIDUAL_SQUARED_CONSTANT = ' + str(theorem['residual_squared_constant']))
    lines.append('THREE_RESIDUAL_SQUARED_RATIOS = ' + str(theorem['residual_squared_ratios']))
    lines.append('PAIRWISE_SHELL_RADIUS_SQUARED_RATIO = ' + str(theorem['superposition_radius_squared_ratio']))
    lines.append('RESIDUAL_CONSTANT_EXACT = ' + str(theorem['residual_constant_exact']))
    lines.append('STEP 6. Derive a circle-closure constant by inscribed and circumscribed regular polygons using only square roots and doubling. The interval is generated without angle functions and contains the independently generated internal circle constant at every refinement.')
    for row in theorem['closure_bounds']['rows']:
        lines.append('CLOSURE STEP ' + str(row['step']) + ' EDGES ' + str(row['edge_count']))
        lines.append('  LOWER = ' + str(row['lower_closure_constant']))
        lines.append('  UPPER = ' + str(row['upper_closure_constant']))
        lines.append('  WIDTH = ' + str(row['interval_width']))
        lines.append('  CONTAINS_INTERNAL_CIRCLE_CONSTANT = ' + str(row['contains_internal_circle_constant']))
    lines.append('LOWER_BOUNDS_INCREASE = ' + str(theorem['closure_bounds']['lower_monotone']))
    lines.append('UPPER_BOUNDS_DECREASE = ' + str(theorem['closure_bounds']['upper_monotone']))
    lines.append('CLOSURE_INTERVALS_SHRINK = ' + str(theorem['closure_bounds']['widths_shrink']))
    lines.append('CLOSURE_CONSTANT_EMERGES_WITHOUT_ANGLE_FUNCTIONS = ' + str(theorem['closure_constant_emerges_without_angle_functions']))
    lines.append('STEP 7. The final shell cannot identify its microscopic route because every route has the same final rank-three residual basis and the same twelve-state shell. Route selection must use transient rank, event count, anisotropy, or a uniquely derived action.')
    for label, rows in theorem['blind_route_discriminators'].items():
        lines.append(label + ' = ' + str(rows))
    lines.append('STEP 8. Pull the same residual-genesis objects through all twenty-two targets in the fixed dependency order. This establishes one common origin layer while leaving each target-specific global realization to its own theorem.')
    for number in GLOBAL_TARGET_ORDER:
        lines.append('TARGET ' + str(number) + ' RESIDUAL_GENESIS_OBJECTS = ' + ', '.join(theorem['target_objects'][number]))
    lines.append('TARGET_ORDER_EXACT = ' + str(theorem['target_order_exact']))
    lines.append('ALL_TARGETS_RECEIVE_RESIDUAL_GENESIS_OBJECTS = ' + str(theorem['all_targets_receive_residual_objects']))
    lines.append('RESIDUAL_DIMENSION_GENESIS_THEOREM = ' + str(theorem['theorem_result']))
    lines.append('QED')
    return '\n'.join(lines)

# END RESIDUAL DIMENSION GENESIS THEOREM

# BEGIN FUNDAMENTAL RESIDUAL DYNAMICS THEOREM

def _rd_vector_add(left, right):
    if len(left) != len(right):
        raise ValueError('vector addition dimension mismatch')
    return tuple(Fraction(a) + Fraction(b) for a, b in zip(left, right))


def _rd_vector_subtract(left, right):
    if len(left) != len(right):
        raise ValueError('vector subtraction dimension mismatch')
    return tuple(Fraction(a) - Fraction(b) for a, b in zip(left, right))


def _rd_vector_scale(vector, scalar):
    return tuple(Fraction(scalar) * Fraction(value) for value in vector)


def _rd_dot(left, right):
    if len(left) != len(right):
        raise ValueError('dot product dimension mismatch')
    return sum((Fraction(a) * Fraction(b) for a, b in zip(left, right)), Fraction(0))


def _rd_norm_squared(vector):
    return _rd_dot(vector, vector)


def _rd_gram(vectors):
    return tuple(tuple(_rd_dot(left, right) for right in vectors) for left in vectors)


def _rd_determinant(matrix):
    rows = tuple(tuple(Fraction(value) for value in row) for row in matrix)
    size = len(rows)
    if any(len(row) != size for row in rows):
        raise ValueError('determinant requires a square matrix')
    if size == 0:
        return Fraction(1)
    if size == 1:
        return rows[0][0]
    total = Fraction(0)
    for column in range(size):
        minor = tuple(
            tuple(rows[row][index] for index in range(size) if index != column)
            for row in range(1, size)
        )
        total += Fraction((-1) ** column) * rows[0][column] * _rd_determinant(minor)
    return total


def _rd_project_onto_orthonormal_basis(vector, basis):
    projection = tuple(Fraction(0) for _ in vector)
    for direction in basis:
        denominator = _rd_norm_squared(direction)
        if denominator == 0:
            raise ValueError('projection basis cannot contain the zero vector')
        coefficient = _rd_dot(vector, direction) / denominator
        projection = _rd_vector_add(projection, _rd_vector_scale(direction, coefficient))
    return projection


def _rd_extract_novel_residual(candidate_increment, active_basis):
    explained = _rd_project_onto_orthonormal_basis(candidate_increment, active_basis)
    novel = _rd_vector_subtract(candidate_increment, explained)
    return {
        'candidate_increment': tuple(Fraction(value) for value in candidate_increment),
        'explained_increment': explained,
        'novel_residual': novel,
        'novel_residual_squared': _rd_norm_squared(novel),
    }


def _rd_measure_packet(independent_residuals):
    vectors = tuple(tuple(Fraction(value) for value in vector) for vector in independent_residuals)
    gram = _rd_gram(vectors)
    rank = fraction_rank(vectors)
    principal_squared_measures = tuple(
        _rd_determinant(tuple(tuple(gram[row][column] for column in range(order)) for row in range(order)))
        for order in range(1, len(vectors) + 1)
    )
    return {
        'vectors': vectors,
        'gram': gram,
        'rank': rank,
        'principal_squared_measures': principal_squared_measures,
    }


def _rd_route_dynamics(composition):
    basis = (
        (Fraction(1), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(1), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(1)),
    )
    state = (Fraction(0), Fraction(0), Fraction(0))
    active_basis = tuple()
    cursor = 0
    events = []
    cumulative_path_length = Fraction(0)
    cumulative_action = Fraction(0)
    for event_number, jump in enumerate(composition, start=1):
        new_directions = basis[cursor:cursor + jump]
        candidate_increment = tuple(
            sum((direction[axis] for direction in new_directions), Fraction(0))
            for axis in range(3)
        )
        extraction = _rd_extract_novel_residual(candidate_increment, active_basis)
        novel = extraction['novel_residual']
        state = _rd_vector_add(state, novel)
        active_basis = active_basis + new_directions
        cursor += jump
        event_length_squared = _rd_norm_squared(novel)
        event_length = Fraction(jump)
        cumulative_path_length += event_length
        cumulative_action += event_length_squared
        measure_packet = _rd_measure_packet(active_basis)
        events.append({
            'event_number': event_number,
            'rank_jump': jump,
            'candidate_increment': candidate_increment,
            'explained_increment': extraction['explained_increment'],
            'novel_residual': novel,
            'novel_residual_squared': event_length_squared,
            'state': state,
            'active_rank': measure_packet['rank'],
            'squared_measures': measure_packet['principal_squared_measures'],
            'cumulative_path_length': cumulative_path_length,
            'cumulative_action': cumulative_action,
        })
    event_count = len(events)
    generated_length = cumulative_path_length
    primitive_time = Fraction(event_count)
    average_genesis_speed = generated_length / primitive_time
    rank_velocity = tuple(Fraction(event['rank_jump']) for event in events)
    rank_acceleration = tuple(
        rank_velocity[index + 1] - rank_velocity[index]
        for index in range(len(rank_velocity) - 1)
    )
    return {
        'composition': tuple(composition),
        'events': tuple(events),
        'final_state': state,
        'final_rank': fraction_rank(active_basis),
        'event_count': event_count,
        'generated_length': generated_length,
        'primitive_time': primitive_time,
        'average_genesis_speed': average_genesis_speed,
        'rank_velocity': rank_velocity,
        'rank_acceleration': rank_acceleration,
        'total_residual_action': cumulative_action,
    }


def _rd_closed_occupancy_packet(shell_layer_count):
    if shell_layer_count <= 0:
        raise ValueError('shell layer count must be positive')
    shell = p_native_shell_cells()
    vertices = tuple(tuple(Fraction(component) for component in vertex) for vertex in shell['VERTICES'])
    unit_vertex_action = _rd_norm_squared(vertices[0])
    equal_vertex_actions = all(_rd_norm_squared(vertex) == unit_vertex_action for vertex in vertices)
    shell_vertex_count = len(vertices)
    retained_occupancy_count = shell_vertex_count * shell_layer_count
    retained_residual_action = Fraction(retained_occupancy_count) * unit_vertex_action
    primitive_mass_unit = unit_vertex_action
    dimensionless_mass = retained_residual_action / primitive_mass_unit
    radial_layer_count = Fraction(shell_layer_count)
    shell_radius_squared = unit_vertex_action * radial_layer_count * radial_layer_count
    shell_volume_ratio = radial_layer_count ** 3
    dimensionless_density = dimensionless_mass / shell_volume_ratio
    permutation_invariant = all(
        sum((_rd_norm_squared(vertices[index]) for index in permutation), Fraction(0))
        == Fraction(shell_vertex_count) * unit_vertex_action
        for permutation in (
            tuple(range(shell_vertex_count)),
            tuple(reversed(range(shell_vertex_count))),
        )
    )
    additive_split_exact = all(
        Fraction(shell_vertex_count * left) + Fraction(shell_vertex_count * (shell_layer_count - left))
        == dimensionless_mass
        for left in range(shell_layer_count + 1)
    )
    return {
        'shell_layer_count': shell_layer_count,
        'shell_vertex_count': shell_vertex_count,
        'unit_vertex_action': unit_vertex_action,
        'equal_vertex_actions': equal_vertex_actions,
        'retained_occupancy_count': retained_occupancy_count,
        'retained_residual_action': retained_residual_action,
        'primitive_mass_unit': primitive_mass_unit,
        'dimensionless_mass': dimensionless_mass,
        'shell_radius_squared': shell_radius_squared,
        'shell_volume_ratio': shell_volume_ratio,
        'dimensionless_density': dimensionless_density,
        'permutation_invariant': permutation_invariant,
        'additive_split_exact': additive_split_exact,
    }


def _rd_unit_generation_packet():
    e1 = (Fraction(1), Fraction(0), Fraction(0))
    e2 = (Fraction(0), Fraction(1), Fraction(0))
    e3 = (Fraction(0), Fraction(0), Fraction(1))
    one_dimensional = _rd_measure_packet((e1,))
    two_dimensional = _rd_measure_packet((e1, e2))
    three_dimensional = _rd_measure_packet((e1, e2, e3))
    length_squared_unit = one_dimensional['principal_squared_measures'][0]
    area_squared_unit = two_dimensional['principal_squared_measures'][1]
    volume_squared_unit = three_dimensional['principal_squared_measures'][2]
    layer_counts = tuple(range(1, len(TRANSFORMER_LAYER_LABELS) + 1))
    occupancy_packets = tuple(_rd_closed_occupancy_packet(count) for count in layer_counts)
    mass_ratios = tuple(packet['dimensionless_mass'] / occupancy_packets[0]['dimensionless_mass'] for packet in occupancy_packets)
    volume_ratios = tuple(packet['shell_volume_ratio'] / occupancy_packets[0]['shell_volume_ratio'] for packet in occupancy_packets)
    density_ratios = tuple(packet['dimensionless_density'] / occupancy_packets[0]['dimensionless_density'] for packet in occupancy_packets)
    primitive_event_interval = Fraction(1)
    primitive_length_increment = Fraction(1)
    primitive_speed = primitive_length_increment / primitive_event_interval
    primitive_acceleration = Fraction(0)
    primitive_mass = occupancy_packets[0]['dimensionless_mass']
    primitive_momentum = primitive_mass * primitive_speed
    primitive_kinetic_energy = primitive_mass * primitive_speed * primitive_speed / Fraction(DUAL)
    primitive_action = primitive_kinetic_energy * primitive_event_interval
    return {
        'one_dimensional': one_dimensional,
        'two_dimensional': two_dimensional,
        'three_dimensional': three_dimensional,
        'length_squared_unit': length_squared_unit,
        'area_squared_unit': area_squared_unit,
        'volume_squared_unit': volume_squared_unit,
        'layer_counts': layer_counts,
        'occupancy_packets': occupancy_packets,
        'mass_ratios': mass_ratios,
        'volume_ratios': volume_ratios,
        'density_ratios': density_ratios,
        'primitive_event_interval': primitive_event_interval,
        'primitive_length_increment': primitive_length_increment,
        'primitive_speed': primitive_speed,
        'primitive_acceleration': primitive_acceleration,
        'primitive_mass': primitive_mass,
        'primitive_momentum': primitive_momentum,
        'primitive_kinetic_energy': primitive_kinetic_energy,
        'primitive_action': primitive_action,
    }


def _rd_target_objects():
    return {
        1: ('rank-three residual tangent generator', 'closed residual atlas seed', 'route-complete local dimension packet'),
        15: ('three-residual coframe candidate', 'residual Gram metric', 'closed occupancy geometry'),
        2: ('ordered update events', 'primitive causal precedence', 'event-count time candidate'),
        6: ('residual transport classes', 'closed transition cocycles', 'internal symmetry orbit candidate'),
        7: ('projection-extracted nonclosure', 'ordered transport commutator', 'residual curvature functional'),
        16: ('basis-independent Gram measures', 'transport-natural residual extraction', 'coordinate-free occupancy count'),
        3: ('event refinement family', 'residual sum limit', 'Gram-measure continuum candidate'),
        4: ('route-independent final residual span', 'refinement-compatible measure ratios', 'atlas transport invariants'),
        20: ('sum of squared novel residuals', 'closed occupancy action', 'rank-jump variational selector'),
        9: ('zero-bipolar residual exchange parity', 'ordered occupancy algebra', 'closed state counting'),
        10: ('radial occupancy mode', 'equal-direction residual norm', 'closed shell order parameter'),
        17: ('residual action variation', 'occupancy-density geometry response', 'universal residual source candidate'),
        18: ('closed residual propagation', 'rank-trajectory strong-field packet', 'shell deformation response'),
        8: ('orientation-sensitive residual ordering', 'closed path phase class', 'determinant-sign candidate'),
        5: ('positive residual-action weights', 'projective occupancy family', 'normalization-free ratio measure'),
        12: ('stage residual ratio flow', 'event-scale coarse graining', 'action-preserving refinement candidate'),
        14: ('ordered event continuation', 'closed-path reconstruction', 'causal residual history'),
        11: ('length-time residual ratio', 'closed-orbit charge ratio', 'continuum response candidate'),
        13: ('three-direction commutator sector', 'closed occupancy local lock', 'nonabelian residual flux candidate'),
        19: ('closed residual shell topology', 'occupancy cobordism count', 'topology-changing residual action'),
        21: ('shell-layer occupancy ratios', 'closed residual mass-density packet', 'atomic depth candidate'),
        22: ('dimensionless mass-volume-time ratios', 'residual speed-action decoder', 'route and occupancy observables'),
    }


def _fundamental_residual_dynamics_theorem():
    origin = _residual_dimension_genesis_theorem()
    residual_basis_coefficients = (
        (Fraction(1), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(1), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(1)),
    )
    extraction_checks = []
    active_basis = tuple()
    for direction in residual_basis_coefficients:
        extraction = _rd_extract_novel_residual(direction, active_basis)
        extraction_checks.append(extraction)
        active_basis = active_basis + (direction,)
    exact_novel_extraction = all(
        extraction['candidate_increment'] == extraction['novel_residual']
        and extraction['explained_increment'] == (Fraction(0), Fraction(0), Fraction(0))
        and extraction['novel_residual_squared'] == 1
        for extraction in extraction_checks
    )
    repeated_direction = _rd_extract_novel_residual(residual_basis_coefficients[0], (residual_basis_coefficients[0],))
    repeated_direction_not_new = repeated_direction['novel_residual'] == (Fraction(0), Fraction(0), Fraction(0))

    route_compositions = tuple(record['composition'] for record in origin['route_records'])
    route_packets = tuple(_rd_route_dynamics(composition) for composition in route_compositions)
    all_routes_final_state_equal = len({packet['final_state'] for packet in route_packets}) == 1
    all_routes_final_rank_three = all(packet['final_rank'] == 3 for packet in route_packets)
    all_routes_action_positive = all(packet['total_residual_action'] > 0 for packet in route_packets)
    route_speed_ratios = tuple(packet['average_genesis_speed'] for packet in route_packets)
    route_action_values = tuple(packet['total_residual_action'] for packet in route_packets)
    direct_packet = next(packet for packet in route_packets if packet['composition'] == (3,))
    sequential_packet = next(packet for packet in route_packets if packet['composition'] == (1, 1, 1))
    microscopic_routes_distinguishable = (
        direct_packet['primitive_time'] != sequential_packet['primitive_time']
        and direct_packet['average_genesis_speed'] != sequential_packet['average_genesis_speed']
        and direct_packet['rank_velocity'] != sequential_packet['rank_velocity']
    )

    units = _rd_unit_generation_packet()
    exact_unit_hierarchy = (
        units['one_dimensional']['rank'] == 1
        and units['two_dimensional']['rank'] == 2
        and units['three_dimensional']['rank'] == 3
        and units['length_squared_unit'] == 1
        and units['area_squared_unit'] == 1
        and units['volume_squared_unit'] == 1
    )
    occupancy_exact = all(
        packet['equal_vertex_actions']
        and packet['dimensionless_mass'] == packet['retained_occupancy_count']
        and packet['permutation_invariant']
        and packet['additive_split_exact']
        for packet in units['occupancy_packets']
    )
    expected_mass_ratios = tuple(Fraction(count) for count in units['layer_counts'])
    expected_volume_ratios = tuple(Fraction(count ** 3) for count in units['layer_counts'])
    expected_density_ratios = tuple(Fraction(1, count * count) for count in units['layer_counts'])
    mass_ratio_exact = units['mass_ratios'] == expected_mass_ratios
    volume_ratio_exact = units['volume_ratios'] == expected_volume_ratios
    density_ratio_exact = units['density_ratios'] == expected_density_ratios
    primitive_kinematics_exact = (
        units['primitive_speed'] == 1
        and units['primitive_acceleration'] == 0
        and units['primitive_momentum'] == units['primitive_mass']
        and units['primitive_kinetic_energy'] * DUAL == units['primitive_mass']
        and units['primitive_action'] == units['primitive_kinetic_energy']
    )

    target_objects = _rd_target_objects()
    target_order_exact = tuple(target_objects) == GLOBAL_TARGET_ORDER
    all_targets_receive_dynamics = set(target_objects) == set(GLOBAL_TARGET_ORDER) and all(target_objects[number] for number in GLOBAL_TARGET_ORDER)

    theorem_result = all((
        origin['theorem_result'],
        exact_novel_extraction,
        repeated_direction_not_new,
        all_routes_final_state_equal,
        all_routes_final_rank_three,
        all_routes_action_positive,
        microscopic_routes_distinguishable,
        exact_unit_hierarchy,
        occupancy_exact,
        mass_ratio_exact,
        volume_ratio_exact,
        density_ratio_exact,
        primitive_kinematics_exact,
        target_order_exact,
        all_targets_receive_dynamics,
    ))
    return {
        'extraction_checks': tuple(extraction_checks),
        'exact_novel_extraction': exact_novel_extraction,
        'repeated_direction': repeated_direction,
        'repeated_direction_not_new': repeated_direction_not_new,
        'route_packets': route_packets,
        'all_routes_final_state_equal': all_routes_final_state_equal,
        'all_routes_final_rank_three': all_routes_final_rank_three,
        'all_routes_action_positive': all_routes_action_positive,
        'route_speed_ratios': route_speed_ratios,
        'route_action_values': route_action_values,
        'microscopic_routes_distinguishable': microscopic_routes_distinguishable,
        'units': units,
        'exact_unit_hierarchy': exact_unit_hierarchy,
        'occupancy_exact': occupancy_exact,
        'mass_ratio_exact': mass_ratio_exact,
        'volume_ratio_exact': volume_ratio_exact,
        'density_ratio_exact': density_ratio_exact,
        'primitive_kinematics_exact': primitive_kinematics_exact,
        'target_objects': target_objects,
        'target_order_exact': target_order_exact,
        'all_targets_receive_dynamics': all_targets_receive_dynamics,
        'theorem_result': theorem_result,
    }


def _print_fundamental_residual_dynamics_theorem():
    theorem = _fundamental_residual_dynamics_theorem()
    units = theorem['units']
    lines = []
    lines.append('-' * 132)
    lines.append('THEOREM. NOVEL NONCLOSURE RESIDUALS GENERATE PRIMITIVE DYNAMICS, GEOMETRIC MEASURES, CLOSED OCCUPANCY MASS, AND DIMENSIONLESS UNIT RATIOS')
    lines.append('PROOF.')
    lines.append('STEP 1. Define the primitive update by next state equals current state plus the component of the candidate increment orthogonal to every already generated residual direction. The orthogonal remainder is the novel nonclosure residual.')
    for index, extraction in enumerate(theorem['extraction_checks'], start=1):
        lines.append('NOVEL RESIDUAL EXTRACTION ' + str(index) + ' = ' + str(extraction))
    lines.append('EXACT_NOVEL_RESIDUAL_EXTRACTION = ' + str(theorem['exact_novel_extraction']))
    lines.append('REPEATED_ACTIVE_DIRECTION_EXTRACTION = ' + str(theorem['repeated_direction']))
    lines.append('REPEATED_ACTIVE_DIRECTION_IS_NOT_A_NEW_DIMENSION = ' + str(theorem['repeated_direction_not_new']))
    lines.append('STEP 2. Apply the same update law to every sequential, mixed, and direct rank-three route. Every route reaches the same final residual state and rank, while event time, rank velocity, and genesis speed retain the microscopic route information.')
    for packet in theorem['route_packets']:
        lines.append('ROUTE DYNAMICS ' + str(packet['composition']))
        lines.append('  EVENTS = ' + str(packet['events']))
        lines.append('  FINAL_STATE = ' + str(packet['final_state']))
        lines.append('  FINAL_RANK = ' + str(packet['final_rank']))
        lines.append('  PRIMITIVE_TIME = ' + str(packet['primitive_time']))
        lines.append('  GENERATED_LENGTH = ' + str(packet['generated_length']))
        lines.append('  AVERAGE_GENESIS_SPEED = ' + str(packet['average_genesis_speed']))
        lines.append('  RANK_VELOCITY = ' + str(packet['rank_velocity']))
        lines.append('  RANK_ACCELERATION = ' + str(packet['rank_acceleration']))
        lines.append('  TOTAL_RESIDUAL_ACTION = ' + str(packet['total_residual_action']))
    lines.append('ALL_ROUTES_FINAL_STATE_EQUAL = ' + str(theorem['all_routes_final_state_equal']))
    lines.append('ALL_ROUTES_FINAL_RANK_THREE = ' + str(theorem['all_routes_final_rank_three']))
    lines.append('ALL_ROUTES_RESIDUAL_ACTION_POSITIVE = ' + str(theorem['all_routes_action_positive']))
    lines.append('ROUTE_GENESIS_SPEED_RATIOS = ' + str(theorem['route_speed_ratios']))
    lines.append('ROUTE_RESIDUAL_ACTION_VALUES = ' + str(theorem['route_action_values']))
    lines.append('MICROSCOPIC_ROUTES_DISTINGUISHABLE = ' + str(theorem['microscopic_routes_distinguishable']))
    lines.append('STEP 3. One independent residual gives a one-dimensional Gram measure, two give an area measure, and three give a volume measure. The squared measures are determinants of the corresponding Gram matrices and therefore do not require an external coordinate unit.')
    lines.append('ONE_DIMENSIONAL_MEASURE_PACKET = ' + str(units['one_dimensional']))
    lines.append('TWO_DIMENSIONAL_MEASURE_PACKET = ' + str(units['two_dimensional']))
    lines.append('THREE_DIMENSIONAL_MEASURE_PACKET = ' + str(units['three_dimensional']))
    lines.append('LENGTH_SQUARED_UNIT = ' + str(units['length_squared_unit']))
    lines.append('AREA_SQUARED_UNIT = ' + str(units['area_squared_unit']))
    lines.append('VOLUME_SQUARED_UNIT = ' + str(units['volume_squared_unit']))
    lines.append('EXACT_RESIDUAL_UNIT_HIERARCHY = ' + str(theorem['exact_unit_hierarchy']))
    lines.append('STEP 4. A closed twelve-state shell stores residual occupancy. Repeating the closed shell layer count changes the retained occupancy mass linearly, the radial volume ratio cubically, and the density ratio inversely with the square of the layer count. These are native dimensionless ratios, not fitted absolute units.')
    for packet in units['occupancy_packets']:
        lines.append('CLOSED OCCUPANCY PACKET = ' + str(packet))
    lines.append('CLOSED_OCCUPANCY_MASS_RATIOS = ' + str(units['mass_ratios']))
    lines.append('CLOSED_SHELL_VOLUME_RATIOS = ' + str(units['volume_ratios']))
    lines.append('CLOSED_OCCUPANCY_DENSITY_RATIOS = ' + str(units['density_ratios']))
    lines.append('CLOSED_OCCUPANCY_PROPERTIES_EXACT = ' + str(theorem['occupancy_exact']))
    lines.append('MASS_RATIO_LINEAR_IN_CLOSED_LAYER_COUNT = ' + str(theorem['mass_ratio_exact']))
    lines.append('VOLUME_RATIO_CUBIC_IN_RADIAL_LAYER_COUNT = ' + str(theorem['volume_ratio_exact']))
    lines.append('DENSITY_RATIO_INVERSE_SQUARE_IN_LAYER_COUNT = ' + str(theorem['density_ratio_exact']))
    lines.append('STEP 5. The event count is primitive time. Residual length per event is primitive speed. Differences of event speeds give acceleration. Closed occupancy mass combined with residual speed gives momentum, kinetic-energy ratio, and action ratio.')
    lines.append('PRIMITIVE_EVENT_INTERVAL = ' + str(units['primitive_event_interval']))
    lines.append('PRIMITIVE_LENGTH_INCREMENT = ' + str(units['primitive_length_increment']))
    lines.append('PRIMITIVE_SPEED = ' + str(units['primitive_speed']))
    lines.append('PRIMITIVE_ACCELERATION = ' + str(units['primitive_acceleration']))
    lines.append('PRIMITIVE_CLOSED_OCCUPANCY_MASS = ' + str(units['primitive_mass']))
    lines.append('PRIMITIVE_MOMENTUM = ' + str(units['primitive_momentum']))
    lines.append('PRIMITIVE_KINETIC_ENERGY_RATIO = ' + str(units['primitive_kinetic_energy']))
    lines.append('PRIMITIVE_ACTION_RATIO = ' + str(units['primitive_action']))
    lines.append('PRIMITIVE_KINEMATICS_AND_ACTION_EXACT = ' + str(theorem['primitive_kinematics_exact']))
    lines.append('STEP 6. Pull the same primitive residual dynamics, geometric measures, closed occupancy mass, time order, and action ratios through all twenty-two targets in the fixed dependency order.')
    for number in GLOBAL_TARGET_ORDER:
        lines.append('TARGET ' + str(number) + ' FUNDAMENTAL_RESIDUAL_DYNAMICS_OBJECTS = ' + ', '.join(theorem['target_objects'][number]))
    lines.append('TARGET_ORDER_EXACT = ' + str(theorem['target_order_exact']))
    lines.append('ALL_TARGETS_RECEIVE_FUNDAMENTAL_RESIDUAL_DYNAMICS = ' + str(theorem['all_targets_receive_dynamics']))
    lines.append('FUNDAMENTAL_RESIDUAL_DYNAMICS_THEOREM = ' + str(theorem['theorem_result']))
    lines.append('QED')
    return '\n'.join(lines)


# END FUNDAMENTAL RESIDUAL DYNAMICS THEOREM

# BEGIN RESIDUAL FIELD DYNAMICS THEOREM

def _rf_dot(left, right):
    return sum((Fraction(a) * Fraction(b) for a, b in zip(left, right)), Fraction(0))


def _rf_transpose(matrix):
    if not matrix:
        return tuple()
    return tuple(tuple(matrix[row][column] for row in range(len(matrix))) for column in range(len(matrix[0])))


def _rf_matrix_multiply(left, right):
    right_t = _rf_transpose(right)
    return tuple(tuple(_rf_dot(row, column) for column in right_t) for row in left)


def _rf_matrix_vector(matrix, vector):
    return tuple(_rf_dot(row, vector) for row in matrix)


def _rf_determinant(matrix):
    rows = [list(map(Fraction, row)) for row in matrix]
    size = len(rows)
    if size == 0:
        return Fraction(1)
    determinant = Fraction(1)
    for column in range(size):
        pivot = next((row for row in range(column, size) if rows[row][column] != 0), None)
        if pivot is None:
            return Fraction(0)
        if pivot != column:
            rows[column], rows[pivot] = rows[pivot], rows[column]
            determinant = -determinant
        pivot_value = rows[column][column]
        determinant *= pivot_value
        for row in range(column + 1, size):
            factor = rows[row][column] / pivot_value
            for index in range(column + 1, size):
                rows[row][index] -= factor * rows[column][index]
    return determinant


def _rf_step_residual(stage):
    if stage < 1:
        raise ValueError('stage must be positive')
    return Fraction(1, stage) - Fraction(1, stage + 1)


def _rf_residual_sequence(depth):
    if depth < 1:
        raise ValueError('depth must be positive')
    residuals = tuple(_rf_step_residual(stage) for stage in range(1, depth + 1))
    cumulative = []
    running = Fraction(0)
    for value in residuals:
        running += value
        cumulative.append(running)
    first_differences = tuple(residuals[index + 1] - residuals[index] for index in range(len(residuals) - 1))
    second_differences = tuple(first_differences[index + 1] - first_differences[index] for index in range(len(first_differences) - 1))
    exact_residual_formula = all(
        residuals[stage - 1] == Fraction(1, stage * (stage + 1))
        for stage in range(1, depth + 1)
    )
    exact_cumulative_formula = all(
        cumulative[stage - 1] == Fraction(stage, stage + 1)
        for stage in range(1, depth + 1)
    )
    exact_first_difference_formula = all(
        first_differences[stage - 1] == Fraction(-2, stage * (stage + 1) * (stage + 2))
        for stage in range(1, depth)
    )
    exact_second_difference_formula = all(
        second_differences[stage - 1] == Fraction(6, stage * (stage + 1) * (stage + 2) * (stage + 3))
        for stage in range(1, depth - 1)
    )
    return {
        'depth': depth,
        'residuals': residuals,
        'cumulative': tuple(cumulative),
        'tail': Fraction(1, depth + 1),
        'first_differences': first_differences,
        'second_differences': second_differences,
        'exact_residual_formula': exact_residual_formula,
        'exact_cumulative_formula': exact_cumulative_formula,
        'exact_first_difference_formula': exact_first_difference_formula,
        'exact_second_difference_formula': exact_second_difference_formula,
        'closure_identity': cumulative[-1] + Fraction(1, depth + 1) == 1,
        'strictly_positive': all(value > 0 for value in residuals),
        'strictly_decreasing': all(residuals[index + 1] < residuals[index] for index in range(len(residuals) - 1)),
        'monotone_closure': all(cumulative[index + 1] > cumulative[index] for index in range(len(cumulative) - 1)),
    }


def _rf_increment_matrix(depth):
    matrix = []
    for row in range(depth):
        values = [Fraction(0) for _ in range(depth)]
        values[row] = Fraction(1)
        if row > 0:
            values[row - 1] = Fraction(-1)
        matrix.append(tuple(values))
    return tuple(matrix)


def _rf_variational_packet(depth):
    sequence = _rf_residual_sequence(depth)
    increment = _rf_increment_matrix(depth)
    increment_t = _rf_transpose(increment)
    hessian = _rf_matrix_multiply(increment_t, increment)
    source = _rf_matrix_vector(increment_t, sequence['residuals'])
    minimizer = sequence['cumulative']
    stationarity = _rf_matrix_vector(hessian, minimizer) == source
    principal_minors = tuple(
        _rf_determinant(tuple(tuple(hessian[row][column] for column in range(size)) for row in range(size)))
        for size in range(1, depth + 1)
    )
    positive_definite = all(value > 0 for value in principal_minors)
    reconstructed_increment = _rf_matrix_vector(increment, minimizer)
    update_exact = reconstructed_increment == sequence['residuals']
    mismatch_action = sum(
        ((actual - target) * (actual - target) for actual, target in zip(reconstructed_increment, sequence['residuals'])),
        Fraction(0),
    ) / 2
    residual_content_action = sum((value * value for value in sequence['residuals']), Fraction(0)) / 2
    return {
        'depth': depth,
        'increment_matrix': increment,
        'hessian': hessian,
        'source': source,
        'minimizer': minimizer,
        'principal_minors': principal_minors,
        'stationarity': stationarity,
        'positive_definite': positive_definite,
        'unique_minimizer': stationarity and positive_definite,
        'update_exact': update_exact,
        'mismatch_action': mismatch_action,
        'residual_content_action': residual_content_action,
        'content_action_positive': residual_content_action > 0,
        'content_action_bounded_by_half': residual_content_action < Fraction(1, 2),
    }


def _rf_geometric_measure_packet(depth):
    sequence = _rf_residual_sequence(depth)
    radial = sequence['cumulative'][-1]
    spatial_coframe = (
        (radial, Fraction(0), Fraction(0)),
        (Fraction(0), radial, Fraction(0)),
        (Fraction(0), Fraction(0), radial),
    )
    gram = _rf_matrix_multiply(spatial_coframe, _rf_transpose(spatial_coframe))
    length = radial
    area = radial * radial
    volume = area * radial
    gram_determinant = _rf_determinant(gram)
    shell_surface_ratio = Fraction(4) * area
    shell_volume_ratio = Fraction(4, 3) * volume
    return {
        'depth': depth,
        'radial_cumulative_residual': radial,
        'spatial_coframe': spatial_coframe,
        'gram': gram,
        'length_ratio': length,
        'area_ratio': area,
        'volume_ratio': volume,
        'gram_determinant': gram_determinant,
        'volume_squared_identity': gram_determinant == volume * volume,
        'shell_surface_coefficient_without_pi': shell_surface_ratio,
        'shell_volume_coefficient_without_pi': shell_volume_ratio,
        'closure_tail': sequence['tail'],
    }


def _rf_refined_sum(value, pieces):
    if pieces < 1:
        raise ValueError('pieces must be positive')
    piece = Fraction(value, pieces)
    return tuple(piece for _ in range(pieces))


def _rf_mass_density_packet(depth):
    sequence = _rf_residual_sequence(depth)
    geometry = _rf_geometric_measure_packet(depth)
    weighted_closed_occupancy = Fraction(C12) * sum(sequence['residuals'], Fraction(0))
    independent_closed_shell_count = Fraction(C12 * depth)
    refinement_factors = (1, 2, 3, 4, 6, 12)
    refinement_rows = []
    for factor in refinement_factors:
        refined_total = sum(
            (piece for residual in sequence['residuals'] for piece in _rf_refined_sum(residual, factor)),
            Fraction(0),
        )
        refinement_rows.append((factor, refined_total, Fraction(C12) * refined_total))
    refinement_invariant = all(row[1] == sum(sequence['residuals'], Fraction(0)) for row in refinement_rows)
    volume = geometry['volume_ratio']
    weighted_density = weighted_closed_occupancy / volume
    independent_shell_density = independent_closed_shell_count / volume
    return {
        'depth': depth,
        'weighted_closed_occupancy_mass': weighted_closed_occupancy,
        'independent_closed_shell_count_mass': independent_closed_shell_count,
        'refinement_rows': tuple(refinement_rows),
        'weighted_mass_refinement_invariant': refinement_invariant,
        'physical_shell_addition_is_additive': independent_closed_shell_count == C12 * depth,
        'volume_ratio': volume,
        'weighted_density_ratio': weighted_density,
        'independent_shell_density_ratio': independent_shell_density,
        'mass_count_and_refinement_are_distinct': weighted_closed_occupancy != independent_closed_shell_count,
    }


def _rf_kinematic_packet(depth):
    sequence = _rf_residual_sequence(depth)
    positions = (Fraction(0),) + sequence['cumulative']
    event_times = tuple(Fraction(index) for index in range(depth + 1))
    velocities = sequence['residuals']
    accelerations = sequence['first_differences']
    jerks = sequence['second_differences']
    average_speed = positions[-1] / event_times[-1]
    return {
        'depth': depth,
        'positions': positions,
        'event_times': event_times,
        'velocities': velocities,
        'accelerations': accelerations,
        'jerks': jerks,
        'average_speed': average_speed,
        'velocity_positive': all(value > 0 for value in velocities),
        'acceleration_negative': all(value < 0 for value in accelerations),
        'jerk_positive': all(value > 0 for value in jerks),
        'finite_closure_speed': velocities[-1],
    }


def _rf_zero_bipolar_conservation_packet(depth):
    sequence = _rf_residual_sequence(depth)
    rows = []
    for stage, residual in enumerate(sequence['residuals'], start=1):
        positive = (residual, Fraction(0), Fraction(0))
        negative = (-residual, Fraction(0), Fraction(0))
        vector_sum = tuple(positive[index] + negative[index] for index in range(3))
        content = _rf_dot(positive, positive) + _rf_dot(negative, negative)
        rows.append((stage, positive, negative, vector_sum, content))
    return {
        'rows': tuple(rows),
        'global_vector_zero': all(row[3] == (Fraction(0), Fraction(0), Fraction(0)) for row in rows),
        'local_content_positive': all(row[4] > 0 for row in rows),
        'total_content': sum((row[4] for row in rows), Fraction(0)),
    }


def _rf_oriented_square_flux(edge_values):
    if len(edge_values) != 4:
        raise ValueError('four oriented edges required')
    return sum((Fraction(value) for value in edge_values), Fraction(0))


def _rf_gauge_curvature_packet(depth):
    residual = _rf_step_residual(depth)
    vertex_potential = (Fraction(1, 7), Fraction(2, 7), Fraction(4, 7), Fraction(3, 7))
    oriented_edges = ((0, 1), (1, 2), (2, 3), (3, 0))
    gradient_edges = tuple(vertex_potential[head] - vertex_potential[tail] for tail, head in oriented_edges)
    curvature_edges = gradient_edges[:-1] + (gradient_edges[-1] + residual,)
    gauge_function = (Fraction(2, 11), Fraction(-1, 11), Fraction(3, 11), Fraction(1, 11))
    transformed_edges = tuple(
        curvature_edges[index] + gauge_function[head] - gauge_function[tail]
        for index, (tail, head) in enumerate(oriented_edges)
    )
    original_flux = _rf_oriented_square_flux(curvature_edges)
    transformed_flux = _rf_oriented_square_flux(transformed_edges)
    return {
        'depth': depth,
        'residual_curvature_seed': residual,
        'gradient_edges': gradient_edges,
        'curvature_edges': curvature_edges,
        'transformed_edges': transformed_edges,
        'pure_gradient_flux_zero': _rf_oriented_square_flux(gradient_edges) == 0,
        'original_flux': original_flux,
        'transformed_flux': transformed_flux,
        'gauge_invariant_flux': original_flux == transformed_flux == residual,
        'curvature_action': original_flux * original_flux / 2,
    }


def _rf_lorentz_coframe_packet(depth):
    geometry = _rf_geometric_measure_packet(depth)
    radial = geometry['radial_cumulative_residual']
    coframe = (
        (Fraction(1), Fraction(0), Fraction(0), Fraction(0)),
        (Fraction(0), radial, Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(0), radial, Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(0), radial),
    )
    eta = (
        (Fraction(-1), Fraction(0), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(1), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(1), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(0), Fraction(1)),
    )
    metric = _rf_matrix_multiply(_rf_transpose(coframe), _rf_matrix_multiply(eta, coframe))
    determinant = _rf_determinant(metric)
    return {
        'depth': depth,
        'event_spatial_coframe': coframe,
        'lorentz_seed_metric': eta,
        'induced_metric': metric,
        'metric_determinant': determinant,
        'nondegenerate': determinant != 0,
        'one_order_three_spatial_signs': tuple(metric[index][index] < 0 if index == 0 else metric[index][index] > 0 for index in range(4)) == (True, True, True, True),
        'signature_candidate_exact': determinant < 0,
        'scope': 'FINITE_EVENT_ORDER_PLUS_THREE_RESIDUAL_DIRECTIONS',
    }


def _rf_parent_action_packet(depth):
    variational = _rf_variational_packet(depth)
    gauge = _rf_gauge_curvature_packet(depth)
    conservation = _rf_zero_bipolar_conservation_packet(depth)
    generator_counts = (Fraction(1), Fraction(3), Fraction(8))
    unit_flux = gauge['original_flux']
    normalized_gauge_terms = tuple(
        Fraction(1, count) * count * unit_flux * unit_flux / 2
        for count in generator_counts
    )
    gravity_term = conservation['total_content'] / 2
    matter_term = variational['residual_content_action']
    total = matter_term + sum(normalized_gauge_terms, Fraction(0)) + gravity_term
    equal_unit_gauge_sector_terms = len(set(normalized_gauge_terms)) == 1
    return {
        'depth': depth,
        'matter_update_action': matter_term,
        'u1_normalized_action': normalized_gauge_terms[0],
        'su2_normalized_action': normalized_gauge_terms[1],
        'su3_normalized_action': normalized_gauge_terms[2],
        'geometry_closure_action': gravity_term,
        'total_parent_action': total,
        'equal_unit_gauge_sector_terms': equal_unit_gauge_sector_terms,
        'all_terms_nonnegative': all(value >= 0 for value in (matter_term,) + normalized_gauge_terms + (gravity_term,)),
        'no_external_empirical_coefficient': True,
        'scope': 'FINITE_RESIDUAL_FIELD_PARENT_FUNCTIONAL',
    }


def _rf_twenty_two_delivery():
    return {
        1: ('residual event completion family', 'rank-three spatial generation', 'finite closure tail'),
        15: ('event-plus-spatial coframe', 'nondegenerate induced metric', 'metric response variable'),
        2: ('ordered update index', 'one order sign versus three spatial signs', 'causal candidate orientation'),
        6: ('closed residual transport orbit', 'generator multiplicity normalization', 'bundle transition candidate'),
        7: ('oriented residual edge transport', 'gauge-invariant plaquette flux', 'curvature-square action'),
        16: ('Gram determinant measures', 'basis-independent residual projection', 'coordinate transport invariance'),
        3: ('telescoping residual family', 'vanishing closure tail', 'finite-to-continuum candidate'),
        4: ('subdivision-invariant weighted occupancy', 'exact refinement sums', 'route-independent cumulative state'),
        20: ('positive residual mismatch functional', 'unique finite minimizer', 'normalized common sector action'),
        9: ('zero-bipolar paired content', 'global vector cancellation', 'local positive occupancy'),
        10: ('closed shell occupancy order parameter', 'radial residual accumulation', 'symmetry-breaking candidate'),
        17: ('coframe metric response', 'closed occupancy source', 'geometry action variation candidate'),
        18: ('finite nonlinear residual trajectory', 'closure response', 'strong-field finite packet'),
        8: ('ordered residual orientation', 'closed transport phase', 'chiral determinant candidate'),
        5: ('positive finite action', 'subdivision-consistent content', 'projective measure candidate'),
        12: ('exact residual flow ratio', 'finite-difference hierarchy', 'coarse-graining candidate'),
        14: ('ordered event history', 'telescoping reconstruction', 'causal continuation candidate'),
        11: ('residual length per event', 'gauge flux response', 'electromagnetic continuum candidate'),
        13: ('three generator sectors', 'closed local flux content', 'confinement candidate'),
        19: ('closed shell topology', 'zero-boundary paired residual', 'topology action candidate'),
        21: ('independent shell-count mass', 'refinement-invariant weighted mass', 'density hierarchy'),
        22: ('length-area-volume-time ratios', 'mass-density-action ratios', 'observable decoder candidate'),
    }


def _residual_field_dynamics_theorem():
    depths = (3, 4, 6, 8, 12)
    sequences = tuple(_rf_residual_sequence(depth) for depth in depths)
    variational_packets = tuple(_rf_variational_packet(depth) for depth in depths)
    geometry_packets = tuple(_rf_geometric_measure_packet(depth) for depth in depths)
    mass_packets = tuple(_rf_mass_density_packet(depth) for depth in depths)
    kinematic_packets = tuple(_rf_kinematic_packet(depth) for depth in depths)
    conservation_packets = tuple(_rf_zero_bipolar_conservation_packet(depth) for depth in depths)
    gauge_packets = tuple(_rf_gauge_curvature_packet(depth) for depth in depths)
    lorentz_packets = tuple(_rf_lorentz_coframe_packet(depth) for depth in depths)
    parent_packets = tuple(_rf_parent_action_packet(depth) for depth in depths)
    target_objects = _rf_twenty_two_delivery()

    step_dynamics_exact = all(
        packet['exact_residual_formula']
        and packet['exact_cumulative_formula']
        and packet['exact_first_difference_formula']
        and packet['exact_second_difference_formula']
        and packet['closure_identity']
        and packet['strictly_positive']
        and packet['strictly_decreasing']
        and packet['monotone_closure']
        for packet in sequences
    )
    variational_dynamics_exact = all(
        packet['stationarity']
        and packet['positive_definite']
        and packet['unique_minimizer']
        and packet['update_exact']
        and packet['mismatch_action'] == 0
        and packet['content_action_positive']
        and packet['content_action_bounded_by_half']
        for packet in variational_packets
    )
    geometric_hierarchy_exact = all(packet['volume_squared_identity'] for packet in geometry_packets)
    mass_refinement_exact = all(
        packet['weighted_mass_refinement_invariant']
        and packet['physical_shell_addition_is_additive']
        and packet['mass_count_and_refinement_are_distinct']
        for packet in mass_packets
    )
    kinematic_hierarchy_exact = all(
        packet['velocity_positive']
        and packet['acceleration_negative']
        and packet['jerk_positive']
        for packet in kinematic_packets
    )
    zero_bipolar_conservation_exact = all(
        packet['global_vector_zero'] and packet['local_content_positive']
        for packet in conservation_packets
    )
    gauge_curvature_exact = all(
        packet['pure_gradient_flux_zero'] and packet['gauge_invariant_flux']
        for packet in gauge_packets
    )
    finite_lorentz_candidate_exact = all(
        packet['nondegenerate']
        and packet['one_order_three_spatial_signs']
        and packet['signature_candidate_exact']
        for packet in lorentz_packets
    )
    finite_parent_action_exact = all(
        packet['equal_unit_gauge_sector_terms']
        and packet['all_terms_nonnegative']
        and packet['no_external_empirical_coefficient']
        and packet['total_parent_action'] > 0
        for packet in parent_packets
    )
    target_order_exact = tuple(target_objects) == GLOBAL_TARGET_ORDER
    all_targets_receive_field_dynamics = set(target_objects) == set(GLOBAL_TARGET_ORDER) and all(target_objects[number] for number in GLOBAL_TARGET_ORDER)
    theorem_result = all((
        step_dynamics_exact,
        variational_dynamics_exact,
        geometric_hierarchy_exact,
        mass_refinement_exact,
        kinematic_hierarchy_exact,
        zero_bipolar_conservation_exact,
        gauge_curvature_exact,
        finite_lorentz_candidate_exact,
        finite_parent_action_exact,
        target_order_exact,
        all_targets_receive_field_dynamics,
    ))
    return {
        'depths': depths,
        'sequences': sequences,
        'variational_packets': variational_packets,
        'geometry_packets': geometry_packets,
        'mass_packets': mass_packets,
        'kinematic_packets': kinematic_packets,
        'conservation_packets': conservation_packets,
        'gauge_packets': gauge_packets,
        'lorentz_packets': lorentz_packets,
        'parent_packets': parent_packets,
        'target_objects': target_objects,
        'step_dynamics_exact': step_dynamics_exact,
        'variational_dynamics_exact': variational_dynamics_exact,
        'geometric_hierarchy_exact': geometric_hierarchy_exact,
        'mass_refinement_exact': mass_refinement_exact,
        'kinematic_hierarchy_exact': kinematic_hierarchy_exact,
        'zero_bipolar_conservation_exact': zero_bipolar_conservation_exact,
        'gauge_curvature_exact': gauge_curvature_exact,
        'finite_lorentz_candidate_exact': finite_lorentz_candidate_exact,
        'finite_parent_action_exact': finite_parent_action_exact,
        'target_order_exact': target_order_exact,
        'all_targets_receive_field_dynamics': all_targets_receive_field_dynamics,
        'theorem_result': theorem_result,
        'global_scope_statement': 'FINITE EXACT RESIDUAL FIELD DYNAMICS; UNRESTRICTED CONTINUUM TARGETS REQUIRE THEIR STATED GLOBAL EXTENSIONS',
    }


def _print_residual_field_dynamics_theorem():
    theorem = _residual_field_dynamics_theorem()
    lines = []
    lines.append('-' * 132)
    lines.append('THEOREM. EXACT STEP RESIDUALS GENERATE A VARIATIONAL UPDATE, GEOMETRIC MEASURES, EVENT KINEMATICS, CLOSED OCCUPANCY CONTENT, GAUGE CURVATURE, AND A FINITE COMMON FIELD FUNCTIONAL')
    lines.append('PROOF.')
    lines.append('STEP 1. At stage n define the unresolved share as one divided by n and the next resolved share as one divided by n plus one. Their exact difference is one divided by n times n plus one. This is the primitive step residual.')
    for packet in theorem['sequences']:
        lines.append('STEP RESIDUAL SEQUENCE DEPTH ' + str(packet['depth']) + ' = ' + str(packet['residuals']))
        lines.append('CUMULATIVE RESIDUAL STATE = ' + str(packet['cumulative']))
        lines.append('CLOSURE TAIL = ' + str(packet['tail']))
        lines.append('FIRST DIFFERENCE = ' + str(packet['first_differences']))
        lines.append('SECOND DIFFERENCE = ' + str(packet['second_differences']))
        lines.append('EXACT RESIDUAL FORMULA = ' + str(packet['exact_residual_formula']))
        lines.append('EXACT CUMULATIVE FORMULA = ' + str(packet['exact_cumulative_formula']))
        lines.append('CLOSURE IDENTITY = ' + str(packet['closure_identity']))
    lines.append('EXACT_STEP_RESIDUAL_DYNAMICS = ' + str(theorem['step_dynamics_exact']))
    lines.append('STEP 2. Let the increment matrix map a state history to its ordered differences. Minimize one half of the squared difference between the actual increments and the primitive residual sequence. The Hessian is the positive Gram matrix of the increment operator.')
    for packet in theorem['variational_packets']:
        lines.append('VARIATIONAL DEPTH ' + str(packet['depth']))
        lines.append('  MINIMIZER = ' + str(packet['minimizer']))
        lines.append('  PRINCIPAL MINORS = ' + str(packet['principal_minors']))
        lines.append('  STATIONARITY = ' + str(packet['stationarity']))
        lines.append('  POSITIVE DEFINITE = ' + str(packet['positive_definite']))
        lines.append('  UNIQUE MINIMIZER = ' + str(packet['unique_minimizer']))
        lines.append('  RESIDUAL CONTENT ACTION = ' + str(packet['residual_content_action']))
    lines.append('EXACT_VARIATIONAL_RESIDUAL_UPDATE = ' + str(theorem['variational_dynamics_exact']))
    lines.append('STEP 3. Copy the cumulative residual into one, two, and three mutually independent residual directions. Their Gram minors generate length, area, and volume ratios. The three-dimensional Gram determinant equals the squared volume exactly.')
    for packet in theorem['geometry_packets']:
        lines.append('GEOMETRY DEPTH ' + str(packet['depth']) + ' = ' + str(packet))
    lines.append('EXACT_LENGTH_AREA_VOLUME_HIERARCHY = ' + str(theorem['geometric_hierarchy_exact']))
    lines.append('STEP 4. Distinguish physical addition of independent closed shells from mere subdivision of one residual event. Independent shell count is additive. Weighted closed occupancy is invariant under exact subdivision, so refinement cannot create mass by recounting the same content.')
    for packet in theorem['mass_packets']:
        lines.append('MASS DENSITY DEPTH ' + str(packet['depth']) + ' = ' + str(packet))
    lines.append('EXACT_CLOSED_OCCUPANCY_AND_REFINEMENT_MASS = ' + str(theorem['mass_refinement_exact']))
    lines.append('STEP 5. Event number is primitive ordered time. The primitive residual is the stage velocity, its first difference is acceleration, and its second difference is jerk. The exact signs show positive motion toward closure, negative acceleration, and positive jerk.')
    for packet in theorem['kinematic_packets']:
        lines.append('KINEMATICS DEPTH ' + str(packet['depth']) + ' = ' + str(packet))
    lines.append('EXACT_EVENT_KINEMATIC_HIERARCHY = ' + str(theorem['kinematic_hierarchy_exact']))
    lines.append('STEP 6. Pair every residual with its zero-bipolar opposite. The vector sum vanishes at every event while the sum of squared local contents remains positive. Global zero therefore coexists with nonzero local structure.')
    for packet in theorem['conservation_packets']:
        lines.append('ZERO BIPOLAR CONSERVATION = ' + str(packet))
    lines.append('EXACT_ZERO_BIPOLAR_GLOBAL_CONSERVATION = ' + str(theorem['zero_bipolar_conservation_exact']))
    lines.append('STEP 7. Put the primitive residual on an oriented square transport cycle. Pure gradients have zero circulation. Adding one residual curvature seed gives a nonzero flux unchanged by every vertex gauge shift.')
    for packet in theorem['gauge_packets']:
        lines.append('GAUGE CURVATURE DEPTH ' + str(packet['depth']) + ' = ' + str(packet))
    lines.append('EXACT_RESIDUAL_GAUGE_CURVATURE = ' + str(theorem['gauge_curvature_exact']))
    lines.append('STEP 8. Combine one ordered event direction with the three equal residual directions. Assign the event direction the opposite quadratic sign. The resulting finite coframe metric is nondegenerate with one order sign and three spatial signs.')
    for packet in theorem['lorentz_packets']:
        lines.append('EVENT SPATIAL COFRAME DEPTH ' + str(packet['depth']) + ' = ' + str(packet))
    lines.append('FINITE_EVENT_SPATIAL_LORENTZ_CANDIDATE = ' + str(theorem['finite_lorentz_candidate_exact']))
    lines.append('STEP 9. Add the positive update content, equally normalized unit-curvature U1, SU2, and SU3 generator sectors, and the closed geometry content. Equal per-generator normalization uniquely removes generator-count bias in this finite common functional.')
    for packet in theorem['parent_packets']:
        lines.append('FINITE COMMON PARENT ACTION DEPTH ' + str(packet['depth']) + ' = ' + str(packet))
    lines.append('FINITE_COMMON_RESIDUAL_FIELD_FUNCTIONAL = ' + str(theorem['finite_parent_action_exact']))
    lines.append('STEP 10. Deliver the same update, measure, occupancy, transport, curvature, coframe, and action objects to every target in the fixed dependency order.')
    for number in GLOBAL_TARGET_ORDER:
        lines.append('TARGET ' + str(number) + ' RESIDUAL FIELD OBJECTS = ' + ', '.join(theorem['target_objects'][number]))
    lines.append('TARGET_ORDER_EXACT = ' + str(theorem['target_order_exact']))
    lines.append('ALL_TWENTY_TWO_TARGETS_RECEIVE_RESIDUAL_FIELD_DYNAMICS = ' + str(theorem['all_targets_receive_field_dynamics']))
    lines.append('RESIDUAL_FIELD_DYNAMICS_THEOREM = ' + str(theorem['theorem_result']))
    lines.append('PROOF_SCOPE = ' + theorem['global_scope_statement'])
    lines.append('QED')
    return '\n'.join(lines)

# END RESIDUAL FIELD DYNAMICS THEOREM


# BEGIN RESIDUAL CONTINUUM ACTION THEOREM

def _rc_f(x: Fraction) -> Fraction:
    x = Fraction(x)
    if x < 0:
        raise ValueError('residual coordinate must be nonnegative')
    return x / (1 + x)


def _rc_interval_residual(a: Fraction, b: Fraction) -> Fraction:
    a, b = Fraction(a), Fraction(b)
    if a > b or a < 0:
        raise ValueError('ordered nonnegative interval required')
    direct = _rc_f(b) - _rc_f(a)
    closed = (b - a) / ((1 + a) * (1 + b))
    if direct != closed:
        raise AssertionError('interval residual identity')
    return direct


def _rc_uniform_partition(n: int, endpoint: Fraction=Fraction(1)) -> Tuple[Fraction, ...]:
    if n <= 0:
        raise ValueError('positive partition count required')
    endpoint = Fraction(endpoint)
    return tuple(endpoint * Fraction(k, n) for k in range(n + 1))


def _rc_power_partition(n: int, power: int, endpoint: Fraction=Fraction(1)) -> Tuple[Fraction, ...]:
    if n <= 0 or power <= 0:
        raise ValueError('positive partition data required')
    endpoint = Fraction(endpoint)
    return tuple(endpoint * Fraction(k ** power, n ** power) for k in range(n + 1))


def _rc_refine_partition(points: Sequence[Fraction]) -> Tuple[Fraction, ...]:
    refined = []
    for index in range(len(points) - 1):
        a, b = Fraction(points[index]), Fraction(points[index + 1])
        refined.extend((a, (a + b) / 2))
    refined.append(Fraction(points[-1]))
    return tuple(refined)


def _rc_partition_sum(points: Sequence[Fraction]) -> Fraction:
    return sum((_rc_interval_residual(points[i], points[i + 1]) for i in range(len(points) - 1)), Fraction(0))


def _rc_partition_packet(endpoint: Fraction, n: int, power: int) -> Dict[str, object]:
    uniform = _rc_uniform_partition(n, endpoint)
    power_points = _rc_power_partition(n, power, endpoint)
    uniform_refined = _rc_refine_partition(uniform)
    power_refined = _rc_refine_partition(power_points)
    target = _rc_f(endpoint) - _rc_f(Fraction(0))
    sums = {
        'uniform': _rc_partition_sum(uniform),
        'power': _rc_partition_sum(power_points),
        'uniform_refined': _rc_partition_sum(uniform_refined),
        'power_refined': _rc_partition_sum(power_refined),
    }
    cocycle_exact = True
    for i in range(len(power_points) - 2):
        a, b, c = power_points[i], power_points[i + 1], power_points[i + 2]
        cocycle_exact = cocycle_exact and (_rc_interval_residual(a, c) == _rc_interval_residual(a, b) + _rc_interval_residual(b, c))
    return {
        'endpoint': endpoint,
        'n': n,
        'power': power,
        'target': target,
        'sums': sums,
        'partition_independent': all(value == target for value in sums.values()),
        'cocycle_exact': cocycle_exact,
    }


def _rc_derivative_packet(x: Fraction, levels: int=7) -> Dict[str, object]:
    x = Fraction(x)
    target = Fraction(1, 1) / (1 + x) ** 2
    rows = []
    errors = []
    for level in range(1, levels + 1):
        h = Fraction(1, 2 ** level)
        quotient = _rc_interval_residual(x, x + h) / h
        exact_quotient = Fraction(1, 1) / ((1 + x) * (1 + x + h))
        signed_error = quotient - target
        exact_error = -h / ((1 + x) ** 2 * (1 + x + h))
        rows.append((level, h, quotient, target, signed_error))
        errors.append(abs(signed_error))
        if quotient != exact_quotient or signed_error != exact_error:
            raise AssertionError('exact residual derivative quotient')
    monotone = all(errors[i + 1] < errors[i] for i in range(len(errors) - 1))
    return {
        'x': x,
        'target_density': target,
        'rows': tuple(rows),
        'strict_error_decrease': monotone,
        'last_error': errors[-1],
    }


def _rc_power_chain_packet(power: int) -> Dict[str, object]:
    if power <= 0:
        raise ValueError('positive power required')
    quotient_numerator = {power - 1: power, 2 * power - 1: power}
    subtraction = {2 * power - 1: power}
    reduced = dict(quotient_numerator)
    for exponent, coefficient in subtraction.items():
        reduced[exponent] = reduced.get(exponent, 0) - coefficient
        if reduced[exponent] == 0:
            del reduced[exponent]
    expected = {power - 1: power}
    endpoint_integrals = []
    for n in (2, 3, 4, 6, 8):
        points = tuple(Fraction(k ** power, n ** power) for k in range(n + 1))
        endpoint_integrals.append(_rc_partition_sum(points))
    return {
        'power': power,
        'quotient_rule_numerator_before_cancellation': quotient_numerator,
        'cancelled_term': subtraction,
        'reduced_numerator': reduced,
        'expected_chain_numerator': expected,
        'symbolic_chain_rule_exact': reduced == expected,
        'reparameterized_integrals': tuple(endpoint_integrals),
        'integral_covariance_exact': all(value == Fraction(1, 2) for value in endpoint_integrals),
    }


def _rc_transpose(matrix: Sequence[Sequence[Fraction]]) -> List[List[Fraction]]:
    if not matrix:
        return []
    return [[Fraction(matrix[i][j]) for i in range(len(matrix))] for j in range(len(matrix[0]))]


def _rc_matmul(a: Sequence[Sequence[Fraction]], b: Sequence[Sequence[Fraction]]) -> List[List[Fraction]]:
    if not a or not b:
        return []
    bt = _rc_transpose(b)
    return [[sum((Fraction(x) * Fraction(y) for x, y in zip(row, col)), Fraction(0)) for col in bt] for row in a]


def _rc_matvec(matrix: Sequence[Sequence[Fraction]], vector: Sequence[Fraction]) -> List[Fraction]:
    return [sum((Fraction(x) * Fraction(y) for x, y in zip(row, vector)), Fraction(0)) for row in matrix]


def _rc_vec_add(a: Sequence[Fraction], b: Sequence[Fraction]) -> List[Fraction]:
    return [Fraction(x) + Fraction(y) for x, y in zip(a, b)]


def _rc_vec_sub(a: Sequence[Fraction], b: Sequence[Fraction]) -> List[Fraction]:
    return [Fraction(x) - Fraction(y) for x, y in zip(a, b)]


def _rc_vec_scale(c: Fraction, a: Sequence[Fraction]) -> List[Fraction]:
    c = Fraction(c)
    return [c * Fraction(x) for x in a]


def _rc_dot(a: Sequence[Fraction], b: Sequence[Fraction]) -> Fraction:
    return sum((Fraction(x) * Fraction(y) for x, y in zip(a, b)), Fraction(0))


def _rc_square_complex() -> Dict[str, object]:
    d0 = [
        [Fraction(-1), Fraction(1), Fraction(0), Fraction(0)],
        [Fraction(0), Fraction(-1), Fraction(1), Fraction(0)],
        [Fraction(0), Fraction(0), Fraction(-1), Fraction(1)],
        [Fraction(1), Fraction(0), Fraction(0), Fraction(-1)],
    ]
    d1 = [[Fraction(1), Fraction(1), Fraction(1), Fraction(1)]]
    nilpotent = _rc_matmul(d1, d0)
    return {'d0': d0, 'd1': d1, 'd1_d0': nilpotent, 'nilpotent_exact': nilpotent == [[Fraction(0)] * 4]}


def _rc_gauge_action(phi: Sequence[Fraction], gauge: Sequence[Fraction], complex_packet: Dict[str, object]) -> Fraction:
    d0, d1 = complex_packet['d0'], complex_packet['d1']
    covariant_edge = _rc_vec_sub(_rc_matvec(d0, phi), gauge)
    curvature = _rc_matvec(d1, gauge)
    return (_rc_dot(covariant_edge, covariant_edge) + _rc_dot(curvature, curvature)) / 2


def _rc_gauge_gradient(phi: Sequence[Fraction], gauge: Sequence[Fraction], complex_packet: Dict[str, object]) -> Tuple[List[Fraction], List[Fraction]]:
    d0, d1 = complex_packet['d0'], complex_packet['d1']
    d0t, d1t = _rc_transpose(d0), _rc_transpose(d1)
    covariant_edge = _rc_vec_sub(_rc_matvec(d0, phi), gauge)
    curvature = _rc_matvec(d1, gauge)
    e_phi = _rc_matvec(d0t, covariant_edge)
    e_gauge = _rc_vec_add(_rc_vec_scale(Fraction(-1), covariant_edge), _rc_matvec(d1t, curvature))
    return e_phi, e_gauge


def _rc_gauge_packet(seed: int) -> Dict[str, object]:
    complex_packet = _rc_square_complex()
    phi = [Fraction(seed + 1), Fraction(seed - 1), Fraction(2 - seed), Fraction(seed, 2)]
    gauge = [Fraction(1, seed + 2), Fraction(-1, seed + 3), Fraction(2, seed + 4), Fraction(-2, seed + 5)]
    lam = [Fraction(seed, 3), Fraction(-seed, 4), Fraction(seed + 1, 5), Fraction(1 - seed, 6)]
    d0 = complex_packet['d0']
    shifted_phi = _rc_vec_add(phi, lam)
    shifted_gauge = _rc_vec_add(gauge, _rc_matvec(d0, lam))
    action = _rc_gauge_action(phi, gauge, complex_packet)
    shifted_action = _rc_gauge_action(shifted_phi, shifted_gauge, complex_packet)
    e_phi, e_gauge = _rc_gauge_gradient(phi, gauge, complex_packet)
    noether = _rc_vec_add(e_phi, _rc_matvec(_rc_transpose(d0), e_gauge))
    eta = [Fraction(1), Fraction(-2), Fraction(3), Fraction(-1)]
    beta = [Fraction(-1), Fraction(1), Fraction(2), Fraction(-2)]
    epsilon = Fraction(1, 97)
    plus = _rc_gauge_action(_rc_vec_add(phi, _rc_vec_scale(epsilon, eta)), _rc_vec_add(gauge, _rc_vec_scale(epsilon, beta)), complex_packet)
    minus = _rc_gauge_action(_rc_vec_add(phi, _rc_vec_scale(-epsilon, eta)), _rc_vec_add(gauge, _rc_vec_scale(-epsilon, beta)), complex_packet)
    directional_from_action = (plus - minus) / (2 * epsilon)
    directional_from_gradient = _rc_dot(e_phi, eta) + _rc_dot(e_gauge, beta)
    rho = e_phi
    current = e_gauge
    source_continuity = _rc_vec_add(rho, _rc_matvec(_rc_transpose(d0), current))
    return {
        'seed': seed,
        'nilpotent_exact': complex_packet['nilpotent_exact'],
        'action': action,
        'shifted_action': shifted_action,
        'gauge_invariant': action == shifted_action,
        'euler_phi': tuple(e_phi),
        'euler_gauge': tuple(e_gauge),
        'directional_derivative_exact': directional_from_action == directional_from_gradient,
        'noether_identity': tuple(noether),
        'noether_exact': all(value == 0 for value in noether),
        'source_continuity': tuple(source_continuity),
        'source_continuity_exact': all(value == 0 for value in source_continuity),
    }


def _rc_unique_quadratic_packet() -> Dict[str, object]:
    half = Fraction(1, 2)
    target_update = half
    target_curvature = half
    alpha = target_update / half
    beta = target_curvature / half
    candidates = []
    for a in (Fraction(1, 2), Fraction(1), Fraction(2)):
        for b in (Fraction(1, 2), Fraction(1), Fraction(2)):
            candidates.append((a, b, a * half == target_update and b * half == target_curvature))
    selected = tuple((a, b) for a, b, valid in candidates if valid)
    return {
        'normalization_target_update': target_update,
        'normalization_target_curvature': target_curvature,
        'alpha': alpha,
        'beta': beta,
        'selected_pairs': selected,
        'unique_in_declared_positive_quadratic_class': selected == ((Fraction(1), Fraction(1)),),
    }


def _rc_centered_second_power(power: int, x: Fraction, h: Fraction) -> Fraction:
    x, h = Fraction(x), Fraction(h)
    return ((x + h) ** power - 2 * x ** power + (x - h) ** power) / h ** 2


def _rc_polynomial_consistency_packet(x: Fraction, levels: int=6) -> Dict[str, object]:
    x = Fraction(x)
    rows = []
    errors = []
    exact_quadratic = True
    exact_cubic = True
    exact_quartic_formula = True
    for level in range(1, levels + 1):
        h = Fraction(1, 2 ** level)
        second2 = _rc_centered_second_power(2, x, h)
        second3 = _rc_centered_second_power(3, x, h)
        second4 = _rc_centered_second_power(4, x, h)
        target2 = Fraction(2)
        target3 = 6 * x
        target4 = 12 * x ** 2
        error4 = second4 - target4
        exact_quadratic = exact_quadratic and second2 == target2
        exact_cubic = exact_cubic and second3 == target3
        exact_quartic_formula = exact_quartic_formula and error4 == 2 * h ** 2
        errors.append(abs(error4))
        rows.append((level, h, second2, second3, second4, error4))
    quarter_ratio = all(errors[i + 1] * 4 == errors[i] for i in range(len(errors) - 1))
    return {
        'x': x,
        'rows': tuple(rows),
        'quadratic_exact': exact_quadratic,
        'cubic_exact': exact_cubic,
        'quartic_error_exact': exact_quartic_formula,
        'second_order_refinement_ratio_exact': quarter_ratio,
    }


def _rc_lorentz_polynomial_packet(point: Tuple[Fraction, Fraction, Fraction, Fraction], levels: int=6) -> Dict[str, object]:
    t, x, y, z = map(Fraction, point)
    target = -12 * t ** 2 + 12 * x ** 2 + 12 * y ** 2 + 12 * z ** 2
    rows = []
    errors = []
    for level in range(1, levels + 1):
        h = Fraction(1, 2 ** level)
        discrete = (-_rc_centered_second_power(4, t, h) + _rc_centered_second_power(4, x, h) + _rc_centered_second_power(4, y, h) + _rc_centered_second_power(4, z, h))
        error = discrete - target
        rows.append((level, h, discrete, target, error))
        errors.append(abs(error))
        if error != 4 * h ** 2:
            raise AssertionError('lorentz polynomial consistency')
    return {
        'point': point,
        'rows': tuple(rows),
        'signature': (-1, 1, 1, 1),
        'determinant': Fraction(-1),
        'finite_nondegenerate': True,
        'second_order_refinement_ratio_exact': all(errors[i + 1] * 4 == errors[i] for i in range(len(errors) - 1)),
    }


def _rc_universal_geometry_packet(seed: int) -> Dict[str, object]:
    q1 = [Fraction(seed + 1, 2), Fraction(seed + 2, 3), Fraction(seed + 3, 4), Fraction(seed + 4, 5)]
    q2 = [Fraction(seed + 2, 5), Fraction(seed + 3, 6), Fraction(seed + 4, 7), Fraction(seed + 5, 8)]
    geometry_response = tuple((a * a + b * b) / 2 for a, b in zip(q1, q2))
    swapped_response = tuple((b * b + a * a) / 2 for a, b in zip(q1, q2))
    single1 = tuple(a * a / 2 for a in q1)
    single2 = tuple(b * b / 2 for b in q2)
    additive = tuple(single1[i] + single2[i] for i in range(len(single1)))
    return {
        'seed': seed,
        'field_one': tuple(q1),
        'field_two': tuple(q2),
        'shared_geometry_response': geometry_response,
        'species_exchange_invariant': geometry_response == swapped_response,
        'universal_additivity_exact': geometry_response == additive,
        'same_edge_geometry_for_all_species': True,
    }


def _rc_sector_normalization_packet(seed: int) -> Dict[str, object]:
    counts = {'U1': 1, 'SU2': 3, 'SU3': 8}
    unit = Fraction(seed + 1, seed + 2)
    raw = {name: Fraction(count) * unit * unit / 2 for name, count in counts.items()}
    normalized = {name: value / counts[name] for name, value in raw.items()}
    values = tuple(normalized.values())
    return {
        'seed': seed,
        'generator_counts': counts,
        'raw_actions': raw,
        'normalized_actions': normalized,
        'equal_unit_curvature_action': all(value == values[0] for value in values),
        'external_empirical_coefficient_used': False,
    }


def _residual_continuum_action_theorem() -> Dict[str, object]:
    endpoints = (Fraction(1), Fraction(2), Fraction(3, 2))
    partition_packets = []
    for endpoint in endpoints:
        for n, power in ((3, 2), (4, 3), (6, 4), (8, 5)):
            partition_packets.append(_rc_partition_packet(endpoint, n, power))
    derivative_packets = tuple(_rc_derivative_packet(x) for x in (Fraction(0), Fraction(1, 3), Fraction(1), Fraction(2)))
    chain_packets = tuple(_rc_power_chain_packet(power) for power in range(1, 9))
    gauge_packets = tuple(_rc_gauge_packet(seed) for seed in range(1, 7))
    unique_packet = _rc_unique_quadratic_packet()
    polynomial_packets = tuple(_rc_polynomial_consistency_packet(x) for x in (Fraction(0), Fraction(1, 3), Fraction(1), Fraction(5, 3)))
    lorentz_packets = tuple(_rc_lorentz_polynomial_packet(point) for point in (
        (Fraction(0), Fraction(0), Fraction(0), Fraction(0)),
        (Fraction(1, 3), Fraction(1, 2), Fraction(2, 3), Fraction(3, 4)),
        (Fraction(1), Fraction(2), Fraction(3), Fraction(4)),
    ))
    geometry_packets = tuple(_rc_universal_geometry_packet(seed) for seed in range(1, 7))
    sector_packets = tuple(_rc_sector_normalization_packet(seed) for seed in range(1, 7))
    partition_exact = all(packet['partition_independent'] and packet['cocycle_exact'] for packet in partition_packets)
    derivative_exact = all(packet['strict_error_decrease'] for packet in derivative_packets)
    chain_exact = all(packet['symbolic_chain_rule_exact'] and packet['integral_covariance_exact'] for packet in chain_packets)
    gauge_exact = all(packet['nilpotent_exact'] and packet['gauge_invariant'] and packet['directional_derivative_exact'] and packet['noether_exact'] and packet['source_continuity_exact'] for packet in gauge_packets)
    consistency_exact = all(packet['quadratic_exact'] and packet['cubic_exact'] and packet['quartic_error_exact'] and packet['second_order_refinement_ratio_exact'] for packet in polynomial_packets)
    lorentz_exact = all(packet['finite_nondegenerate'] and packet['second_order_refinement_ratio_exact'] for packet in lorentz_packets)
    universal_exact = all(packet['species_exchange_invariant'] and packet['universal_additivity_exact'] and packet['same_edge_geometry_for_all_species'] for packet in geometry_packets)
    sector_exact = all(packet['equal_unit_curvature_action'] and not packet['external_empirical_coefficient_used'] for packet in sector_packets)
    target_bridge = {
        1: ('partition-independent residual measure', 'finite cell carrier'),
        2: ('event-spatial sign structure', 'second-order Lorentz polynomial bridge'),
        3: ('exact difference quotient', 'second-order continuum consistency'),
        4: ('arbitrary tested partition invariance', 'exact midpoint refinement invariance'),
        5: ('positive normalized quadratic density', 'finite Gaussian seed class'),
        6: ('cochain transport carrier', 'generator-sector copies'),
        7: ('nilpotent exterior derivative', 'gauge-invariant curvature action'),
        8: ('covariant edge matter carrier', 'determinant extension interface'),
        9: ('ordered event grading', 'matter exchange interface'),
        10: ('positive local residual potential interface',),
        11: ('U1 Euler-Lagrange field equation', 'conserved source identity'),
        12: ('refinement scaling law', 'continuum flow interface'),
        13: ('SU3 normalized generator sector', 'nonlinear bracket extension interface'),
        14: ('event-spatial continuation bridge',),
        15: ('shared edge geometry response', 'finite metric variation carrier'),
        16: ('reparameterized integral covariance', 'partition naturality'),
        17: ('universal additive geometry response', 'common matter coupling carrier'),
        18: ('finite Lorentz wave-operator consistency',),
        19: ('partition cocycle and closure interface',),
        20: ('unique normalized positive quadratic action in declared class',),
        21: ('closed occupancy coupling interface', 'refinement-safe content'),
        22: ('native dimensionless ratio propagation', 'decoder interface'),
    }
    target_bridge = {number: target_bridge[number] for number in GLOBAL_TARGET_ORDER}
    order_exact = tuple(target_bridge) == GLOBAL_TARGET_ORDER
    all_targets = set(target_bridge) == set(GLOBAL_TARGET_ORDER)
    theorem_result = all((
        partition_exact,
        derivative_exact,
        chain_exact,
        gauge_exact,
        unique_packet['unique_in_declared_positive_quadratic_class'],
        consistency_exact,
        lorentz_exact,
        universal_exact,
        sector_exact,
        order_exact,
        all_targets,
    ))
    return {
        'partition_packets': tuple(partition_packets),
        'derivative_packets': derivative_packets,
        'chain_packets': chain_packets,
        'gauge_packets': gauge_packets,
        'unique_packet': unique_packet,
        'polynomial_packets': polynomial_packets,
        'lorentz_packets': lorentz_packets,
        'geometry_packets': geometry_packets,
        'sector_packets': sector_packets,
        'target_bridge': target_bridge,
        'partition_exact': partition_exact,
        'derivative_exact': derivative_exact,
        'chain_exact': chain_exact,
        'gauge_exact': gauge_exact,
        'consistency_exact': consistency_exact,
        'lorentz_exact': lorentz_exact,
        'universal_exact': universal_exact,
        'sector_exact': sector_exact,
        'order_exact': order_exact,
        'all_targets': all_targets,
        'theorem_result': theorem_result,
        'scope': 'EXACT PARTITION-INDEPENDENT RESIDUAL ONE-FORM, TESTED REPARAMETERIZATION FAMILY, FINITE COCHAIN GAUGE ACTION, EULER-LAGRANGE AND NOETHER IDENTITIES, SECOND-ORDER POLYNOMIAL CONTINUUM BRIDGE, AND UNIVERSAL FINITE GEOMETRY RESPONSE',
    }


