    lines.append('NATIVE_GENERATOR_SECTOR_NORMALIZATION = ' + str(theorem['sector_exact']))
    lines.append('STEP 10. Deliver the partition measure, local density, covariance family, cochain curvature, field equations, conservation identity, continuum bridge, Lorentz sign structure, and universal geometry response to all targets in the fixed dependency order.')
