# END RESIDUAL CONTINUUM ACTION THEOREM

# BEGIN RESIDUAL NONABELIAN MATTER THEOREM

def _rm_g(real=0, imag=0):
    return (Fraction(real), Fraction(imag))


def _rm_g_add(left, right):
    return (left[0] + right[0], left[1] + right[1])


def _rm_g_sub(left, right):
    return (left[0] - right[0], left[1] - right[1])


def _rm_g_neg(value):
    return (-value[0], -value[1])


def _rm_g_mul(left, right):
    return (
        left[0] * right[0] - left[1] * right[1],
        left[0] * right[1] + left[1] * right[0],
    )


def _rm_g_conj(value):
    return (value[0], -value[1])


def _rm_g_is_zero(value):
    return value == (Fraction(0), Fraction(0))


def _rm_m_zero(rows, columns):
    zero = _rm_g()
    return tuple(tuple(zero for _ in range(columns)) for _ in range(rows))


def _rm_m_eye(size):
    zero = _rm_g()
    one = _rm_g(1)
    return tuple(tuple(one if row == column else zero for column in range(size)) for row in range(size))


def _rm_m_add(left, right):
    return tuple(
        tuple(_rm_g_add(left[row][column], right[row][column]) for column in range(len(left[0])))
        for row in range(len(left))
    )


def _rm_m_sub(left, right):
    return tuple(
        tuple(_rm_g_sub(left[row][column], right[row][column]) for column in range(len(left[0])))
        for row in range(len(left))
    )


def _rm_m_scale(matrix, scalar):
    scalar_g = scalar if isinstance(scalar, tuple) else _rm_g(scalar)
    return tuple(tuple(_rm_g_mul(entry, scalar_g) for entry in row) for row in matrix)


def _rm_m_mul(left, right):
    zero = _rm_g()
    rows = []
    for row in range(len(left)):
        output_row = []
        for column in range(len(right[0])):
            value = zero
            for inner in range(len(right)):
                value = _rm_g_add(value, _rm_g_mul(left[row][inner], right[inner][column]))
            output_row.append(value)
        rows.append(tuple(output_row))
    return tuple(rows)


def _rm_m_dagger(matrix):
    return tuple(
        tuple(_rm_g_conj(matrix[column][row]) for column in range(len(matrix)))
        for row in range(len(matrix[0]))
    )


def _rm_m_trace(matrix):
    value = _rm_g()
    for index in range(len(matrix)):
        value = _rm_g_add(value, matrix[index][index])
    return value


def _rm_m_commutator(left, right):
    return _rm_m_sub(_rm_m_mul(left, right), _rm_m_mul(right, left))


def _rm_m_anticommutator(left, right):
    return _rm_m_add(_rm_m_mul(left, right), _rm_m_mul(right, left))


def _rm_m_kron(left, right):
    rows = []
    for left_row in left:
        for right_row in right:
            row = []
            for left_entry in left_row:
                for right_entry in right_row:
                    row.append(_rm_g_mul(left_entry, right_entry))
            rows.append(tuple(row))
    return tuple(rows)


def _rm_m_block(top_left, top_right, bottom_left, bottom_right):
    rows = []
    for row in range(len(top_left)):
        rows.append(tuple(top_left[row]) + tuple(top_right[row]))
    for row in range(len(bottom_left)):
        rows.append(tuple(bottom_left[row]) + tuple(bottom_right[row]))
    return tuple(rows)


def _rm_m_flat_real(matrix):
    values = []
    for row in matrix:
        for entry in row:
            values.extend((entry[0], entry[1]))
    return tuple(values)


def _rm_m_rank_span(matrices):
    if not matrices:
        return 0
    columns = [_rm_m_flat_real(matrix) for matrix in matrices]
    rows = tuple(tuple(columns[column][row] for column in range(len(columns))) for row in range(len(columns[0])))
    return fraction_rank(rows)


def _rm_m_frobenius_inner(left, right):
    total = Fraction(0)
    for row in range(len(left)):
        for column in range(len(left[0])):
            product = _rm_g_mul(_rm_g_conj(left[row][column]), right[row][column])
            total += product[0]
    return total


def _rm_m_norm_squared(matrix):
    return _rm_m_frobenius_inner(matrix, matrix)


def _rm_m_det(matrix):
    size = len(matrix)
    if size == 0:
        return _rm_g(1)
    if size == 1:
        return matrix[0][0]
    total = _rm_g()
    for column in range(size):
        minor = tuple(
            tuple(matrix[row][inner] for inner in range(size) if inner != column)
            for row in range(1, size)
        )
        term = _rm_g_mul(matrix[0][column], _rm_m_det(minor))
        total = _rm_g_add(total, term if column % 2 == 0 else _rm_g_neg(term))
    return total


def _rm_m_is_zero(matrix):
    return all(_rm_g_is_zero(entry) for row in matrix for entry in row)


def _rm_vector_apply(matrix, vector):
    output = []
    for row in range(len(matrix)):
        value = _rm_g()
        for column in range(len(vector)):
            value = _rm_g_add(value, _rm_g_mul(matrix[row][column], vector[column]))
        output.append(value)
    return tuple(output)


def _rm_vector_inner(left, right):
    total = Fraction(0)
    for first, second in zip(left, right):
        total += _rm_g_mul(_rm_g_conj(first), second)[0]
    return total


def _rm_matrix_unit(size, row, column, value=None):
    value = _rm_g(1) if value is None else value
    zero = _rm_g()
    return tuple(
        tuple(value if (outer == row and inner == column) else zero for inner in range(size))
        for outer in range(size)
    )


def _rm_lie_basis(size):
    imaginary = _rm_g(0, 1)
    basis = []
    for first in range(size):
        for second in range(first + 1, size):
            antisymmetric = _rm_m_sub(
                _rm_matrix_unit(size, first, second),
                _rm_matrix_unit(size, second, first),
            )
            symmetric_imaginary = _rm_m_scale(
                _rm_m_add(
                    _rm_matrix_unit(size, first, second),
                    _rm_matrix_unit(size, second, first),
                ),
                imaginary,
            )
            basis.extend((antisymmetric, symmetric_imaginary))
    for diagonal in range(size - 1):
        entries = [[_rm_g() for _ in range(size)] for _ in range(size)]
        entries[diagonal][diagonal] = imaginary
        entries[diagonal + 1][diagonal + 1] = _rm_g_neg(imaginary)
        basis.append(tuple(tuple(row) for row in entries))
    return tuple(basis)


def _rm_lie_algebra_packet(size):
    basis = _rm_lie_basis(size)
    dimension_expected = size * size - 1
    antihermitian = all(_rm_m_dagger(generator) == _rm_m_scale(generator, -1) for generator in basis)
    traceless = all(_rm_m_trace(generator) == _rm_g() for generator in basis)
    independent = _rm_m_rank_span(basis) == dimension_expected == len(basis)
    closure = True
    noncommuting_pairs = 0
    for left in basis:
        for right in basis:
            bracket = _rm_m_commutator(left, right)
            if not _rm_m_is_zero(bracket):
                noncommuting_pairs += 1
            if _rm_m_rank_span(basis + (bracket,)) != dimension_expected:
                closure = False
    jacobi = True
    for first in basis:
        for second in basis:
            for third in basis:
                cyclic = _rm_m_add(
                    _rm_m_add(
                        _rm_m_commutator(first, _rm_m_commutator(second, third)),
                        _rm_m_commutator(second, _rm_m_commutator(third, first)),
                    ),
                    _rm_m_commutator(third, _rm_m_commutator(first, second)),
                )
                if not _rm_m_is_zero(cyclic):
                    jacobi = False
    norms = tuple(_rm_m_norm_squared(generator) for generator in basis)
    return {
        'size': size,
        'dimension': len(basis),
        'dimension_expected': dimension_expected,
        'antihermitian': antihermitian,
        'traceless': traceless,
        'independent': independent,
        'closure': closure,
        'jacobi': jacobi,
        'noncommuting_pair_count': noncommuting_pairs,
        'generator_norms': norms,
        'basis': basis,
        'theorem_result': all((antihermitian, traceless, independent, closure, jacobi, noncommuting_pairs > 0)),
    }


def _rm_conjugate(group_element, matrix):
    return _rm_m_mul(_rm_m_mul(group_element, matrix), _rm_m_dagger(group_element))


def _rm_nonabelian_curvature_packet(size):
    lie = _rm_lie_algebra_packet(size)
    basis = lie['basis']
    connections = basis[:3]
    curvatures = {}
    for first in range(3):
        for second in range(first + 1, 3):
            curvatures[(first, second)] = _rm_m_commutator(connections[first], connections[second])
    if size == 2:
        group = (
            (_rm_g(), _rm_g(1)),
            (_rm_g(-1), _rm_g()),
        )
    else:
        group = (
            (_rm_g(), _rm_g(1), _rm_g()),
            (_rm_g(), _rm_g(), _rm_g(1)),
            (_rm_g(1), _rm_g(), _rm_g()),
        )
    unitary = _rm_m_mul(_rm_m_dagger(group), group) == _rm_m_eye(size)
    determinant_one = _rm_m_det(group) == _rm_g(1)
    transformed_connections = tuple(_rm_conjugate(group, connection) for connection in connections)
    gauge_covariance = True
    for key, curvature in curvatures.items():
        first, second = key
        transformed_curvature = _rm_m_commutator(transformed_connections[first], transformed_connections[second])
        if transformed_curvature != _rm_conjugate(group, curvature):
            gauge_covariance = False
    bianchi = _rm_m_add(
        _rm_m_add(
            _rm_m_commutator(connections[0], _rm_m_commutator(connections[1], connections[2])),
            _rm_m_commutator(connections[1], _rm_m_commutator(connections[2], connections[0])),
        ),
        _rm_m_commutator(connections[2], _rm_m_commutator(connections[0], connections[1])),
    )
    bianchi_exact = _rm_m_is_zero(bianchi)
    combined_variation = _rm_m_zero(size, size)
    for generator in basis:
        combined_variation = _rm_m_sub(combined_variation, generator)
    variations = (combined_variation, combined_variation, combined_variation)
    delta_curvatures = {}
    for first in range(3):
        for second in range(first + 1, 3):
            delta_curvatures[(first, second)] = _rm_m_add(
                _rm_m_commutator(variations[first], connections[second]),
                _rm_m_commutator(connections[first], variations[second]),
            )
    directional_derivative = sum(
        _rm_m_frobenius_inner(curvatures[key], delta_curvatures[key])
        for key in curvatures
    )
    euler_gradients = []
    for first in range(3):
        gradient = _rm_m_zero(size, size)
        for second in range(3):
            if first == second:
                continue
            curvature = (
                curvatures[(first, second)]
                if first < second
                else _rm_m_scale(curvatures[(second, first)], -1)
            )
            gradient = _rm_m_add(gradient, _rm_m_commutator(connections[second], curvature))
        euler_gradients.append(gradient)
    gradient_pairing = sum(
        _rm_m_frobenius_inner(euler_gradients[index], variations[index])
        for index in range(3)
    )
    variation_exact = directional_derivative == gradient_pairing
    action = sum(_rm_m_norm_squared(curvature) for curvature in curvatures.values()) / 2
    curvature_nonzero = any(not _rm_m_is_zero(curvature) for curvature in curvatures.values())
    return {
        'size': size,
        'unitary_group_element': unitary,
        'determinant_one': determinant_one,
        'curvature_nonzero': curvature_nonzero,
        'gauge_covariance': gauge_covariance,
        'bianchi_exact': bianchi_exact,
        'yang_mills_action': action,
        'directional_derivative': directional_derivative,
        'gradient_pairing': gradient_pairing,
        'variation_exact': variation_exact,
        'theorem_result': all((lie['theorem_result'], unitary, determinant_one, curvature_nonzero, gauge_covariance, bianchi_exact, variation_exact, action > 0)),
    }


def _rm_clifford_chiral_packet():
    zero = _rm_g()
    one = _rm_g(1)
    imaginary = _rm_g(0, 1)
    two_by_two_zero = _rm_m_zero(2, 2)
    identity_two = _rm_m_eye(2)
    sigma_one = ((zero, one), (one, zero))
    sigma_two = ((zero, _rm_g(0, -1)), (imaginary, zero))
    sigma_three = ((one, zero), (zero, _rm_g(-1)))
    gamma_zero = _rm_m_block(two_by_two_zero, identity_two, _rm_m_scale(identity_two, -1), two_by_two_zero)
    gamma_space = tuple(
        _rm_m_block(two_by_two_zero, sigma, sigma, two_by_two_zero)
        for sigma in (sigma_one, sigma_two, sigma_three)
    )
    gamma = (gamma_zero,) + gamma_space
    metric_signs = (-1, 1, 1, 1)
    clifford = True
    for first in range(4):
        for second in range(4):
            expected = _rm_m_zero(4, 4)
            if first == second:
                expected = _rm_m_scale(_rm_m_eye(4), 2 * metric_signs[first])
            if _rm_m_anticommutator(gamma[first], gamma[second]) != expected:
                clifford = False
    product = _rm_m_eye(4)
    for generator in gamma:
        product = _rm_m_mul(product, generator)
    chirality = _rm_m_scale(product, _rm_g(0, -1))
    chirality_square = _rm_m_mul(chirality, chirality) == _rm_m_eye(4)
    chirality_anticommutes = all(_rm_m_is_zero(_rm_m_anticommutator(chirality, generator)) for generator in gamma)
    projector_plus = _rm_m_scale(_rm_m_add(_rm_m_eye(4), chirality), Fraction(1, 2))
    projector_minus = _rm_m_scale(_rm_m_sub(_rm_m_eye(4), chirality), Fraction(1, 2))
    projector_exact = all((
        _rm_m_mul(projector_plus, projector_plus) == projector_plus,
        _rm_m_mul(projector_minus, projector_minus) == projector_minus,
        _rm_m_is_zero(_rm_m_mul(projector_plus, projector_minus)),
        _rm_m_add(projector_plus, projector_minus) == _rm_m_eye(4),
        _rm_m_trace(projector_plus) == _rm_g(2),
        _rm_m_trace(projector_minus) == _rm_g(2),
    ))
    chirality_swap = all(
        _rm_m_mul(projector_plus, generator) == _rm_m_mul(generator, projector_minus)
        and _rm_m_mul(projector_minus, generator) == _rm_m_mul(generator, projector_plus)
        for generator in gamma
    )
    momentum = (Fraction(1), Fraction(1), Fraction(2), Fraction(2))
    dirac = _rm_m_zero(4, 4)
    for coefficient, generator in zip(momentum, gamma):
        dirac = _rm_m_add(dirac, _rm_m_scale(generator, coefficient))
    norm = -momentum[0] * momentum[0] + sum(value * value for value in momentum[1:])
    dirac_square = _rm_m_mul(dirac, dirac) == _rm_m_scale(_rm_m_eye(4), norm)
    return {
        'signature': metric_signs,
        'clifford_exact': clifford,
        'chirality_square_exact': chirality_square,
        'chirality_anticommutes': chirality_anticommutes,
        'projector_exact': projector_exact,
        'chirality_swap_exact': chirality_swap,
        'dirac_square_norm': norm,
        'dirac_square_exact': dirac_square,
        'theorem_result': all((clifford, chirality_square, chirality_anticommutes, projector_exact, chirality_swap, dirac_square)),
    }


def _rm_car_packet(mode_count=3):
    zero = _rm_g()
    one = _rm_g(1)
    annihilation = ((zero, one), (zero, zero))
    creation = _rm_m_dagger(annihilation)
    parity = ((one, zero), (zero, _rm_g(-1)))
    identity_two = _rm_m_eye(2)
    operators = []
    for mode in range(mode_count):
        operator = ((_rm_g(1),),)
        for position in range(mode_count):
            factor = parity if position < mode else annihilation if position == mode else identity_two
            operator = _rm_m_kron(operator, factor)
        operators.append(operator)
    creators = tuple(_rm_m_dagger(operator) for operator in operators)
    dimension = 2 ** mode_count
    zero_matrix = _rm_m_zero(dimension, dimension)
    identity = _rm_m_eye(dimension)
    car_exact = True
    for first in range(mode_count):
        for second in range(mode_count):
            if _rm_m_anticommutator(operators[first], operators[second]) != zero_matrix:
                car_exact = False
            expected = identity if first == second else zero_matrix
            if _rm_m_anticommutator(operators[first], creators[second]) != expected:
                car_exact = False
    nilpotent = all(_rm_m_is_zero(_rm_m_mul(operator, operator)) for operator in operators)
    number_operator = zero_matrix
    for creator, operator in zip(creators, operators):
        number_operator = _rm_m_add(number_operator, _rm_m_mul(creator, operator))
    diagonal = tuple(number_operator[index][index][0] for index in range(dimension))
    multiplicities = tuple(diagonal.count(Fraction(number)) for number in range(mode_count + 1))
    expected_multiplicities = tuple(
        len(tuple(itertools.combinations(range(mode_count), number)))
        for number in range(mode_count + 1)
    )
    number_spectrum_exact = multiplicities == expected_multiplicities and all(
        number_operator[row][column] == (_rm_g(diagonal[row]) if row == column else _rm_g())
        for row in range(dimension)
        for column in range(dimension)
    )
    return {
        'mode_count': mode_count,
        'fock_dimension': dimension,
        'car_exact': car_exact,
        'nilpotent_annihilators': nilpotent,
        'number_multiplicities': multiplicities,
        'expected_binomial_multiplicities': expected_multiplicities,
        'number_spectrum_exact': number_spectrum_exact,
        'theorem_result': all((car_exact, nilpotent, number_spectrum_exact)),
    }


def _rm_higgs_stabilizer_packet():
    leading = Fraction(1)
    quadratic = -2 * leading
    constant = leading
    value_at_unit = leading + quadratic + constant
    derivative_at_unit = 4 * leading + 2 * quadratic
    square_identity = (leading, quadratic, constant) == (Fraction(1), Fraction(-2), Fraction(1))
    positive_minima = all((value_at_unit == 0, derivative_at_unit == 0, 12 * leading + 2 * quadratic > 0, 2 * quadratic < 0, square_identity))
    zero = _rm_g()
    one = _rm_g(1)
    imaginary = _rm_g(0, 1)
    sigma_one = ((zero, one), (one, zero))
    sigma_two = ((zero, _rm_g(0, -1)), (imaginary, zero))
    sigma_three = ((one, zero), (zero, _rm_g(-1)))
    minus_i_half = _rm_g(0, Fraction(-1, 2))
    su2 = tuple(_rm_m_scale(sigma, minus_i_half) for sigma in (sigma_one, sigma_two, sigma_three))
    hypercharge = _rm_m_scale(_rm_m_eye(2), minus_i_half)
    vacuum = (zero, one)
    orbit_vectors = tuple(_rm_vector_apply(generator, vacuum) for generator in su2 + (hypercharge,))
    gram = tuple(tuple(_rm_vector_inner(left, right) for right in orbit_vectors) for left in orbit_vectors)
    rank = fraction_rank(gram)
    nullspace = _fraction_nullspace(gram)
    expected_null = (Fraction(0), Fraction(0), Fraction(1), Fraction(1))
    null_exact = len(nullspace) == 1 and nullspace[0] in (expected_null, tuple(-value for value in expected_null))
    unbroken_generator = _rm_m_add(su2[2], hypercharge)
    unbroken_annihilates = all(_rm_g_is_zero(value) for value in _rm_vector_apply(unbroken_generator, vacuum))
    broken_norms = tuple(gram[index][index] for index in range(4))
    return {
        'quartic_coefficients': (leading, quadratic, constant),
        'zero_bipolar_minima_exact': positive_minima,
        'orbit_gram': gram,
        'orbit_rank': rank,
        'stabilizer_nullspace': nullspace,
        'one_unbroken_direction': null_exact,
        'unbroken_generator_annihilates_vacuum': unbroken_annihilates,
        'gauge_orbit_norms': broken_norms,
        'theorem_result': all((positive_minima, rank == 3, null_exact, unbroken_annihilates)),
    }


def _rm_transfer_measure_packet():
    kernel = ((Fraction(2), Fraction(1)), (Fraction(1), Fraction(2)))
    states = (0, 1)
    paths = tuple(itertools.product(states, repeat=4))
    weights = {}
    for path in paths:
        weight = Fraction(1)
        for index in range(3):
            weight *= kernel[path[index]][path[index + 1]]
        weights[path] = weight
    normalization = sum(weights.values(), Fraction(0))
    probabilities = {path: weight / normalization for path, weight in weights.items()}
    positive_normalized = all(value > 0 for value in probabilities.values()) and sum(probabilities.values(), Fraction(0)) == 1
    half_states = tuple(itertools.product(states, repeat=2))
    reflection_matrix = []
    for left in half_states:
        row = []
        for right in half_states:
            path = (left[0], left[1], right[1], right[0])
            row.append(weights[path])
        reflection_matrix.append(tuple(row))
    reflection_matrix = tuple(reflection_matrix)
    principal_minors_nonnegative = True
    for order in range(1, len(half_states) + 1):
        for indices in itertools.combinations(range(len(half_states)), order):
            submatrix = tuple(tuple(_rm_g(reflection_matrix[row][column]) for column in indices) for row in indices)
            determinant = _rm_m_det(submatrix)
            if determinant[1] != 0 or determinant[0] < 0:
                principal_minors_nonnegative = False
    transfer = tuple(tuple(value / 3 for value in row) for row in kernel)
    blocked = tuple(
        tuple(sum(transfer[row][inner] * transfer[inner][column] for inner in range(2)) for column in range(2))
        for row in range(2)
    )
    q = transfer[0][0] - transfer[0][1]
    q_blocked = blocked[0][0] - blocked[0][1]
    blocking_exact = q_blocked == q * q
    fixed_points = tuple(value for value in (Fraction(0), Fraction(1)) if value * value == value)
    return {
        'path_count': len(paths),
        'normalization': normalization,
        'positive_normalized_measure': positive_normalized,
        'reflection_matrix': reflection_matrix,
        'reflection_principal_minors_nonnegative': principal_minors_nonnegative,
        'transfer_nontrivial_ratio': q,
        'blocked_ratio': q_blocked,
        'blocking_semigroup_exact': blocking_exact,
        'blocking_fixed_points': fixed_points,
        'theorem_result': all((positive_normalized, principal_minors_nonnegative, blocking_exact, Fraction(0) < q < Fraction(1))),
    }


def _rm_constant_curvature_packet():
    metric = (Fraction(-1), Fraction(1), Fraction(1), Fraction(1))
    dimension = len(metric)
    curvature = Fraction(1)
    riemann = {}
    for first in range(dimension):
        for second in range(dimension):
            for third in range(dimension):
                for fourth in range(dimension):
                    g_first_third = metric[first] if first == third else Fraction(0)
                    g_second_fourth = metric[second] if second == fourth else Fraction(0)
                    g_first_fourth = metric[first] if first == fourth else Fraction(0)
                    g_second_third = metric[second] if second == third else Fraction(0)
                    riemann[(first, second, third, fourth)] = curvature * (
                        g_first_third * g_second_fourth - g_first_fourth * g_second_third
                    )
    symmetries = True
    bianchi = True
    for first in range(dimension):
        for second in range(dimension):
            for third in range(dimension):
                for fourth in range(dimension):
                    value = riemann[(first, second, third, fourth)]
                    if value != -riemann[(second, first, third, fourth)]:
                        symmetries = False
                    if value != -riemann[(first, second, fourth, third)]:
                        symmetries = False
                    if value != riemann[(third, fourth, first, second)]:
                        symmetries = False
                    cyclic = (
                        riemann[(first, second, third, fourth)]
                        + riemann[(first, third, fourth, second)]
                        + riemann[(first, fourth, second, third)]
                    )
                    if cyclic != 0:
                        bianchi = False
    ricci = [[Fraction(0) for _ in range(dimension)] for _ in range(dimension)]
    for second in range(dimension):
        for fourth in range(dimension):
            for first in range(dimension):
                inverse = Fraction(1, metric[first])
                ricci[second][fourth] += inverse * riemann[(first, second, first, fourth)]
    scalar = sum(Fraction(1, metric[index]) * ricci[index][index] for index in range(dimension))
    einstein = tuple(
        tuple(
            ricci[row][column] - Fraction(1, 2) * (metric[row] if row == column else 0) * scalar
            for column in range(dimension)
        )
        for row in range(dimension)
    )
    ricci_exact = all(
        ricci[row][column] == (Fraction(dimension - 1) * metric[row] if row == column else 0)
        for row in range(dimension)
        for column in range(dimension)
    )
    scalar_exact = scalar == dimension * (dimension - 1)
    einstein_exact = all(
        einstein[row][column] == (Fraction(-3) * metric[row] if row == column else 0)
        for row in range(dimension)
        for column in range(dimension)
    )
    trace = sum(Fraction(1, metric[index]) * einstein[index][index] for index in range(dimension))
    trace_identity = trace == -scalar
    return {
        'dimension': dimension,
        'riemann_symmetries_exact': symmetries,
        'algebraic_bianchi_exact': bianchi,
        'ricci_exact': ricci_exact,
        'scalar_curvature': scalar,
        'scalar_exact': scalar_exact,
        'einstein_tensor': einstein,
        'einstein_exact': einstein_exact,
        'einstein_trace': trace,
        'trace_identity_exact': trace_identity,
        'theorem_result': all((symmetries, bianchi, ricci_exact, scalar_exact, einstein_exact, trace_identity)),
    }


