# BEGIN ABSTRACT SOURCE MULTI-PROJECTION THEOREM

def _mp_matvec(matrix, vector):
    return tuple(
        sum(Fraction(matrix[row][column]) * Fraction(vector[column]) for column in range(len(vector)))
        for row in range(len(matrix))
    )


def _mp_add(first, second):
    return tuple(Fraction(a) + Fraction(b) for a, b in zip(first, second))


def _mp_projection_family():
    return {
        'RELATION_PAIRING': (
            (Fraction(1), Fraction(0), Fraction(1), Fraction(0)),
            (Fraction(0), Fraction(1), Fraction(0), Fraction(1)),
        ),
        'ORDER_PAIRING': (
            (Fraction(1), Fraction(1), Fraction(0), Fraction(0)),
            (Fraction(0), Fraction(0), Fraction(1), Fraction(1)),
        ),
        'CLOSURE_PAIRING': (
            (Fraction(1), Fraction(0), Fraction(0), Fraction(1)),
            (Fraction(0), Fraction(1), Fraction(1), Fraction(0)),
        ),
    }


def _mp_stack_rows(matrices):
    rows = []
    for matrix in matrices:
        rows.extend(tuple(tuple(Fraction(value) for value in row) for row in matrix))
    return tuple(rows)


def _mp_reconstruct(readouts):
    relation = readouts['RELATION_PAIRING']
    order = readouts['ORDER_PAIRING']
    closure = readouts['CLOSURE_PAIRING']
    first = (relation[0] + order[0] - closure[1]) / 2
    second = (relation[1] + order[0] - closure[0]) / 2
    third = (relation[0] + order[1] - closure[0]) / 2
    fourth = (relation[1] + order[1] - closure[1]) / 2
    return (first, second, third, fourth)


def _mp_common_content(readout):
    return sum(Fraction(value) for value in readout)


def _mp_readout_compatibility(readouts):
    totals = tuple(_mp_common_content(readouts[name]) for name in (
        'RELATION_PAIRING',
        'ORDER_PAIRING',
        'CLOSURE_PAIRING',
    ))
    reconstructed = _mp_reconstruct(readouts)
    family = _mp_projection_family()
    replay = {name: _mp_matvec(matrix, reconstructed) for name, matrix in family.items()}
    exact_replay = all(replay[name] == tuple(readouts[name]) for name in family)
    return {
        'totals': totals,
        'common_total_exact': len(set(totals)) == 1,
        'reconstructed': reconstructed,
        'replayed': replay,
        'exact_replay': exact_replay,
        'compatible': len(set(totals)) == 1 and exact_replay,
    }


def _mp_projection_reconstruction_packet():
    family = _mp_projection_family()
    source = (Fraction(3), Fraction(4), Fraction(2), Fraction(1))
    readouts = {name: _mp_matvec(matrix, source) for name, matrix in family.items()}
    visible_forms = {
        name: (
            'BALANCED' if values[0] == values[1]
            else 'FIRST_DOMINANT' if values[0] > values[1]
            else 'SECOND_DOMINANT'
        )
        for name, values in readouts.items()
    }
    individual_ranks = {name: fraction_rank(matrix) for name, matrix in family.items()}
    names = tuple(family)
    pair_ranks = {}
    for first_index in range(len(names)):
        for second_index in range(first_index + 1, len(names)):
            pair = (names[first_index], names[second_index])
            pair_ranks[pair] = fraction_rank(_mp_stack_rows((family[pair[0]], family[pair[1]])))
    joint_rank = fraction_rank(_mp_stack_rows(tuple(family.values())))
    reconstructed = _mp_reconstruct(readouts)
    compatibility = _mp_readout_compatibility(readouts)
    kernel_witnesses = {
        'RELATION_PAIRING': (Fraction(1), Fraction(0), Fraction(-1), Fraction(0)),
        'ORDER_PAIRING': (Fraction(1), Fraction(-1), Fraction(0), Fraction(0)),
        'CLOSURE_PAIRING': (Fraction(1), Fraction(0), Fraction(0), Fraction(-1)),
    }
    single_projection_ambiguity = {}
    for name, witness in kernel_witnesses.items():
        shifted = _mp_add(source, witness)
        same_readout = _mp_matvec(family[name], shifted) == readouts[name]
        single_projection_ambiguity[name] = {
            'kernel_witness': witness,
            'shifted_source': shifted,
            'same_readout': same_readout,
            'source_changed': shifted != source,
        }
    all_single_ambiguous = all(
        item['same_readout'] and item['source_changed']
        for item in single_projection_ambiguity.values()
    )
    all_pair_incomplete = all(rank < len(source) for rank in pair_ranks.values())
    theorem_result = all((
        tuple(readouts['RELATION_PAIRING']) == (Fraction(5), Fraction(5)),
        tuple(readouts['ORDER_PAIRING']) == (Fraction(7), Fraction(3)),
        tuple(readouts['CLOSURE_PAIRING']) == (Fraction(4), Fraction(6)),
        len(set(visible_forms.values())) == 3,
        all(rank == 2 for rank in individual_ranks.values()),
        all_pair_incomplete,
        joint_rank == len(source),
        reconstructed == source,
        compatibility['compatible'],
        all_single_ambiguous,
    ))
    return {
        'source': source,
        'projection_family': family,
        'readouts': readouts,
        'visible_forms': visible_forms,
        'individual_ranks': individual_ranks,
        'pair_ranks': pair_ranks,
        'joint_rank': joint_rank,
        'reconstructed': reconstructed,
        'compatibility': compatibility,
        'single_projection_ambiguity': single_projection_ambiguity,
        'all_single_projections_noninjective': all_single_ambiguous,
        'all_projection_pairs_incomplete': all_pair_incomplete,
        'joint_projection_injective': joint_rank == len(source),
        'theorem_result': theorem_result,
    }


def _mp_discrete_readout_label(readout):
    first, second = readout
    if first > second:
        return 'FIRST_CLOSED_CHANNEL'
    if second > first:
        return 'SECOND_CLOSED_CHANNEL'
    return 'BALANCED_BOUNDARY'


def _mp_closure_transition_packet():
    family = _mp_projection_family()
    projection = family['RELATION_PAIRING']
    states = []
    readouts = []
    labels = []
    increments = []
    for step in range(11):
        t = Fraction(step, 10)
        state = (Fraction(1) - t, t, Fraction(0), Fraction(0))
        states.append(state)
        readout = _mp_matvec(projection, state)
        readouts.append(readout)
        labels.append(_mp_discrete_readout_label(readout))
        if step:
            increments.append(tuple(states[step][index] - states[step - 1][index] for index in range(4)))
    common_contents = tuple(sum(state) for state in states)
    uniform_increment = len(set(increments)) == 1
    continuous_internal_path = all(
        increments[index] == (Fraction(-1, 10), Fraction(1, 10), Fraction(0), Fraction(0))
        for index in range(len(increments))
    )
    expected_labels = (
        ('FIRST_CLOSED_CHANNEL',) * 5
        + ('BALANCED_BOUNDARY',)
        + ('SECOND_CLOSED_CHANNEL',) * 5
    )
    discrete_transition_exact = tuple(labels) == expected_labels
    theorem_result = all((
        len(set(common_contents)) == 1,
        common_contents[0] == 1,
        uniform_increment,
        continuous_internal_path,
        discrete_transition_exact,
    ))
    return {
        'states': tuple(states),
        'readouts': tuple(readouts),
        'labels': tuple(labels),
        'increments': tuple(increments),
        'common_contents': common_contents,
        'common_content_preserved': len(set(common_contents)) == 1,
        'uniform_internal_increment': uniform_increment,
        'continuous_internal_path': continuous_internal_path,
        'discrete_projection_transition_exact': discrete_transition_exact,
        'theorem_result': theorem_result,
    }


def _mp_transition_kind(old_source, new_source, old_projection_name, new_projection_name):
    old_source = tuple(Fraction(value) for value in old_source)
    new_source = tuple(Fraction(value) for value in new_source)
    if old_source == new_source and old_projection_name != new_projection_name:
        return 'OBSERVATION_MAP_CHANGE'
    if sum(old_source) == sum(new_source):
        return 'INTERNAL_CLOSURE_REARRANGEMENT'
    return 'SOURCE_CONTENT_CHANGE'


def _mp_transition_classification_packet():
    source = (Fraction(4), Fraction(3), Fraction(1), Fraction(2))
    same_source = source
    rearranged_source = (Fraction(3), Fraction(4), Fraction(1), Fraction(2))
    changed_source = (Fraction(5), Fraction(3), Fraction(1), Fraction(2))
    observer_change = _mp_transition_kind(source, same_source, 'RELATION_PAIRING', 'ORDER_PAIRING')
    closure_change = _mp_transition_kind(source, rearranged_source, 'RELATION_PAIRING', 'RELATION_PAIRING')
    source_change = _mp_transition_kind(source, changed_source, 'RELATION_PAIRING', 'RELATION_PAIRING')
    theorem_result = (
        observer_change == 'OBSERVATION_MAP_CHANGE'
        and closure_change == 'INTERNAL_CLOSURE_REARRANGEMENT'
        and source_change == 'SOURCE_CONTENT_CHANGE'
    )
    return {
        'observation_map_change': observer_change,
        'internal_closure_rearrangement': closure_change,
        'source_content_change': source_change,
        'old_total': sum(source),
        'rearranged_total': sum(rearranged_source),
        'changed_total': sum(changed_source),
        'theorem_result': theorem_result,
    }


def _mp_impossible_combination_packet():
    compatible = {
        'RELATION_PAIRING': (Fraction(5), Fraction(5)),
        'ORDER_PAIRING': (Fraction(7), Fraction(3)),
        'CLOSURE_PAIRING': (Fraction(6), Fraction(4)),
    }
    incompatible = {
        'RELATION_PAIRING': (Fraction(5), Fraction(5)),
        'ORDER_PAIRING': (Fraction(7), Fraction(3)),
        'CLOSURE_PAIRING': (Fraction(7), Fraction(4)),
    }
    compatible_packet = _mp_readout_compatibility(compatible)
    incompatible_packet = _mp_readout_compatibility(incompatible)
    theorem_result = compatible_packet['compatible'] and not incompatible_packet['compatible']
    return {
        'compatible_readouts': compatible,
        'compatible_packet': compatible_packet,
        'incompatible_readouts': incompatible,
        'incompatible_packet': incompatible_packet,
        'incompatible_total_constraint_detected': not incompatible_packet['common_total_exact'],
        'incompatible_roundtrip_detected': not incompatible_packet['exact_replay'],
        'theorem_result': theorem_result,
    }


def _mp_forward_reverse_family_packet():
    family = _mp_projection_family()
    sources = (
        (Fraction(4), Fraction(3), Fraction(1), Fraction(2)),
        (Fraction(1), Fraction(0), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(1), Fraction(2), Fraction(3)),
        (Fraction(5, 2), Fraction(7, 3), Fraction(11, 5), Fraction(13, 7)),
        (Fraction(-1), Fraction(2), Fraction(-3), Fraction(4)),
    )
    records = []
    for source in sources:
        readouts = {name: _mp_matvec(matrix, source) for name, matrix in family.items()}
        reconstructed = _mp_reconstruct(readouts)
        replayed = {name: _mp_matvec(matrix, reconstructed) for name, matrix in family.items()}
        records.append({
            'source': source,
            'readouts': readouts,
            'reconstructed': reconstructed,
            'source_recovered': reconstructed == source,
            'readouts_recovered': replayed == readouts,
            'common_invariant': tuple(_mp_common_content(readouts[name]) for name in family),
        })
    theorem_result = all(
        record['source_recovered']
        and record['readouts_recovered']
        and len(set(record['common_invariant'])) == 1
        for record in records
    )
    return {
        'records': tuple(records),
        'source_count': len(records),
        'all_sources_recovered': all(record['source_recovered'] for record in records),
        'all_readouts_recovered': all(record['readouts_recovered'] for record in records),
        'all_common_invariants_agree': all(len(set(record['common_invariant'])) == 1 for record in records),
        'theorem_result': theorem_result,
    }


