    lines.append('FORWARD REVERSE FAMILY PACKET = ' + str(theorem['forward_reverse']))
    lines.append('FORWARD_REVERSE_SOURCE_RECONSTRUCTION_EXACT = ' + str(theorem['forward_reverse']['theorem_result']))
