def _tr_reconstruct_spatial_from_ratio_and_norm(direction_ratio, spatial_norm_squared):
    direction_ratio = tuple(Fraction(component) for component in direction_ratio)
    spatial_norm_squared = Fraction(spatial_norm_squared)
    direction_norm_squared = _tr_spatial_norm_squared(direction_ratio)
    if direction_norm_squared == 0:
        if spatial_norm_squared != 0:
            raise ValueError('nonzero norm cannot use zero direction')
        return tuple(Fraction(0) for _ in direction_ratio)
    scale_squared = spatial_norm_squared / direction_norm_squared
    scale = _tr_fraction_square_root(scale_squared)
    if scale is None:
        return None
    return tuple(scale * component for component in direction_ratio)


