def _mtr_fraction_matrix(rows):
    return [[Fraction(value) for value in row] for row in rows]


def _mtr_transpose(matrix):
    return [list(column) for column in zip(*matrix)] if matrix else []


def _tensor_matrix_multiply(left, right):
    if not left or not right:
        return []
    right_t = _mtr_transpose(right)
    return [
        [sum((Fraction(a) * Fraction(b) for a, b in zip(row, column)), Fraction(0)) for column in right_t]
        for row in left
    ]


def _mtr_matvec(matrix, vector):
    return [
        sum((Fraction(value) * Fraction(component) for value, component in zip(row, vector)), Fraction(0))
        for row in matrix
    ]


def _mtr_vec_add(left, right):
    return tuple(Fraction(a) + Fraction(b) for a, b in zip(left, right))


def _mtr_vec_sub(left, right):
    return tuple(Fraction(a) - Fraction(b) for a, b in zip(left, right))


def _mtr_vec_scale(scale, vector):
    return tuple(Fraction(scale) * Fraction(value) for value in vector)


def _mtr_dot(left, right):
    return sum((Fraction(a) * Fraction(b) for a, b in zip(left, right)), Fraction(0))


def _mtr_norm_squared(vector):
    return _mtr_dot(vector, vector)


def _mtr_identity(size):
    return [[Fraction(int(row == column)) for column in range(size)] for row in range(size)]


def _mtr_matrix_equal(left, right):
    return left == right


def _mtr_vector_equal(left, right):
    return tuple(Fraction(value) for value in left) == tuple(Fraction(value) for value in right)


def _mtr_zero_observation_equivalence():
    latent_candidates = (
        (Fraction(0), Fraction(0)),
        (Fraction(1), Fraction(-1)),
        (Fraction(-1), Fraction(1)),
        (Fraction(2), Fraction(-2)),
    )
    eventless_observations = tuple((Fraction(0),) for _ in latent_candidates)
    eventless_classes = len(set(eventless_observations))
    separator_observations = tuple((left + right, left - right) for left, right in latent_candidates)
    separator_classes = len(set(separator_observations))
    signed_totals = tuple(left + right for left, right in latent_candidates)
    theorem_result = (
        eventless_classes == 1
        and separator_classes == len(latent_candidates)
        and all(total == 0 for total in signed_totals)
    )
    return {
        'latent_candidates': latent_candidates,
        'eventless_observations': eventless_observations,
        'eventless_equivalence_class_count': eventless_classes,
        'separator_observations': separator_observations,
        'separator_class_count': separator_classes,
        'all_signed_totals_zero': all(total == 0 for total in signed_totals),
        'zero_is_one_observational_equivalence_class_before_event_separation': eventless_classes == 1,
        'first_event_separator_creates_distinguishable_relations': separator_classes == len(latent_candidates),
        'theorem_result': theorem_result,
    }


