    lines.append('ALL_FOUR_READOUTS_RECONSTRUCT_ONE_SOURCE = ' + str(theorem['frame']['all_four_readouts_reconstruct_one_source']))
    lines.append('INCOMPATIBLE_READOUT_REJECTED = ' + str(theorem['frame']['incompatible_readout_rejected']))
