# BEGIN FINITE COVARIANT TWENTY TWO TARGET CLOSURE THEOREM

def _fc_matrix_add(left, right):
    return [[Fraction(a) + Fraction(b) for a, b in zip(row_left, row_right)] for row_left, row_right in zip(left, right)]


def _fc_matrix_sub(left, right):
    return [[Fraction(a) - Fraction(b) for a, b in zip(row_left, row_right)] for row_left, row_right in zip(left, right)]


def _fc_matrix_scale(scale, matrix):
    return [[Fraction(scale) * Fraction(value) for value in row] for row in matrix]


def _fc_matrix_trace(matrix):
    return sum((Fraction(matrix[index][index]) for index in range(len(matrix))), Fraction(0))


def _fc_matrix_commutator(left, right):
    return _fc_matrix_sub(_tensor_matrix_multiply(left, right), _tensor_matrix_multiply(right, left))


def _fc_zero_matrix(rows, columns):
    return [[Fraction(0) for _ in range(columns)] for _ in range(rows)]


def _fc_matrix_inverse(matrix):
    size = len(matrix)
    inverse_columns = []
    for column in range(size):
        target = [Fraction(int(row == column)) for row in range(size)]
        inverse_columns.append(_fraction_linear_solve(matrix, target))
    return [list(row) for row in zip(*inverse_columns)]


def _fc_rectangular_solve(columns, target):
    if not columns:
        return tuple()
    row_count = len(columns[0])
    variable_count = len(columns)
    if any(len(column) != row_count for column in columns) or len(target) != row_count:
        raise ValueError('rectangular solve dimension mismatch')
    augmented = [[Fraction(columns[column][row]) for column in range(variable_count)] + [Fraction(target[row])] for row in range(row_count)]
    pivot_rows = {}
    row = 0
    for column in range(variable_count):
        pivot = next((candidate for candidate in range(row, row_count) if augmented[candidate][column] != 0), None)
        if pivot is None:
            continue
        augmented[row], augmented[pivot] = augmented[pivot], augmented[row]
        pivot_value = augmented[row][column]
        augmented[row] = [value / pivot_value for value in augmented[row]]
        for other in range(row_count):
            if other == row:
                continue
            factor = augmented[other][column]
            if factor != 0:
                augmented[other] = [augmented[other][index] - factor * augmented[row][index] for index in range(variable_count + 1)]
        pivot_rows[column] = row
        row += 1
    for values in augmented:
        if all(values[column] == 0 for column in range(variable_count)) and values[-1] != 0:
            raise ValueError('target is outside the supplied span')
    if len(pivot_rows) != variable_count:
        raise ValueError('supplied columns are not independent')
    solution = [Fraction(0) for _ in range(variable_count)]
    for column, pivot_row in pivot_rows.items():
        solution[column] = augmented[pivot_row][-1]
    reconstructed = [sum((columns[column][row_index] * solution[column] for column in range(variable_count)), Fraction(0)) for row_index in range(row_count)]
    if tuple(reconstructed) != tuple(map(Fraction, target)):
        raise ValueError('rectangular solve reconstruction failed')
    return tuple(solution)


def _fc_gaussian(real=0, imaginary=0):
    return (Fraction(real), Fraction(imaginary))


def _fc_gadd(left, right):
    return (left[0] + right[0], left[1] + right[1])


def _fc_gsub(left, right):
    return (left[0] - right[0], left[1] - right[1])


def _fc_gmul(left, right):
    return (left[0] * right[0] - left[1] * right[1], left[0] * right[1] + left[1] * right[0])


def _fc_gconj(value):
    return (value[0], -value[1])


def _fc_gscale(scale, value):
    return (Fraction(scale) * value[0], Fraction(scale) * value[1])


def _fc_gzero_matrix(size):
    return [[_fc_gaussian() for _ in range(size)] for _ in range(size)]


def _fc_gidentity(size):
    return [[_fc_gaussian(int(row == column), 0) for column in range(size)] for row in range(size)]


def _fc_gtranspose(matrix):
    return [list(column) for column in zip(*matrix)] if matrix else []


def _fc_gdagger(matrix):
    return [[_fc_gconj(value) for value in row] for row in _fc_gtranspose(matrix)]


def _fc_gmatmul(left, right):
    right_t = _fc_gtranspose(right)
    result = []
    for row in left:
        result_row = []
        for column in right_t:
            total = _fc_gaussian()
            for a, b in zip(row, column):
                total = _fc_gadd(total, _fc_gmul(a, b))
            result_row.append(total)
        result.append(result_row)
    return result


def _fc_gmatvec(matrix, vector):
    result = []
    for row in matrix:
        total = _fc_gaussian()
        for value, component in zip(row, vector):
            total = _fc_gadd(total, _fc_gmul(value, component))
        result.append(total)
    return result


def _fc_gmatrix_sub(left, right):
    return [[_fc_gsub(a, b) for a, b in zip(row_left, row_right)] for row_left, row_right in zip(left, right)]


def _fc_gcommutator(left, right):
    return _fc_gmatrix_sub(_fc_gmatmul(left, right), _fc_gmatmul(right, left))


def _fc_gtrace(matrix):
    total = _fc_gaussian()
    for index in range(len(matrix)):
        total = _fc_gadd(total, matrix[index][index])
    return total


def _fc_gflatten(matrix):
    flattened = []
    for row in matrix:
        for real, imaginary in row:
            flattened.extend((real, imaginary))
    return tuple(flattened)


def _fc_glinear_combination(coefficients, basis):
    size = len(basis[0])
    result = _fc_gzero_matrix(size)
    for coefficient, generator in zip(coefficients, basis):
        for row in range(size):
            for column in range(size):
                result[row][column] = _fc_gadd(result[row][column], _fc_gscale(coefficient, generator[row][column]))
    return result


def _fc_ginverse_real_orthogonal(matrix):
    return _fc_gtranspose(matrix)


def _fc_simplex_boundary_matrix(vertices, dimension):
    high = tuple(itertools.combinations(vertices, dimension + 1))
    if dimension == 0:
        return tuple(), high, tuple()
    low = tuple(itertools.combinations(vertices, dimension))
    low_index = {simplex: index for index, simplex in enumerate(low)}
    matrix = [[Fraction(0) for _ in high] for _ in low]
    for column, simplex in enumerate(high):
        for removed in range(len(simplex)):
            face = simplex[:removed] + simplex[removed + 1:]
            matrix[low_index[face]][column] = Fraction(-1 if removed % 2 else 1)
    return tuple(tuple(row) for row in matrix), high, low


def _fc_simplicial_topology_packet():
    vertices = tuple(range(5))
    boundaries = {0: tuple()}
    simplex_bases = {}
    for dimension in range(5):
        matrix, high, _ = _fc_simplex_boundary_matrix(vertices, dimension)
        boundaries[dimension] = matrix
        simplex_bases[dimension] = high
    chain_square_zero = {}
    for dimension in range(2, 5):
        product = _tensor_matrix_multiply(boundaries[dimension - 1], boundaries[dimension])
        chain_square_zero[dimension] = all(value == 0 for row in product for value in row)
    counts = {dimension: len(simplex_bases[dimension]) for dimension in range(5)}
    ranks = {dimension: (fraction_rank(boundaries[dimension]) if dimension > 0 else 0) for dimension in range(5)}
    full_betti = tuple(counts[dimension] - ranks[dimension] - (ranks[dimension + 1] if dimension < 4 else 0) for dimension in range(5))
    full_euler = sum(((-1) ** dimension) * counts[dimension] for dimension in range(5))
    boundary_counts = {dimension: counts[dimension] for dimension in range(4)}
    boundary_ranks = {dimension: ranks[dimension] for dimension in range(4)}
    boundary_betti = tuple(boundary_counts[dimension] - boundary_ranks[dimension] - (boundary_ranks[dimension + 1] if dimension < 3 else 0) for dimension in range(4))
    boundary_euler = sum(((-1) ** dimension) * boundary_counts[dimension] for dimension in range(4))
    exact = all(chain_square_zero.values()) and full_betti == (1, 0, 0, 0, 0) and full_euler == 1 and boundary_betti == (1, 0, 0, 1) and boundary_euler == 0
    return {
        'simplex_counts': counts,
        'boundary_ranks': ranks,
        'boundary_squared_zero': chain_square_zero,
        'four_simplex_betti': full_betti,
        'four_simplex_euler': full_euler,
        'boundary_three_sphere_betti': boundary_betti,
        'boundary_three_sphere_euler': boundary_euler,
        'finite_oriented_four_complex_exact': exact,
        'theorem_result': exact,
    }


def _fc_lorentz_causal_packet():
    eta = [[Fraction(-1), Fraction(0), Fraction(0), Fraction(0)], [Fraction(0), Fraction(1), Fraction(0), Fraction(0)], [Fraction(0), Fraction(0), Fraction(1), Fraction(0)], [Fraction(0), Fraction(0), Fraction(0), Fraction(1)]]
    boost = [[Fraction(5, 3), Fraction(4, 3), Fraction(0), Fraction(0)], [Fraction(4, 3), Fraction(5, 3), Fraction(0), Fraction(0)], [Fraction(0), Fraction(0), Fraction(1), Fraction(0)], [Fraction(0), Fraction(0), Fraction(0), Fraction(1)]]
    boost_inverse = [[Fraction(5, 3), Fraction(-4, 3), Fraction(0), Fraction(0)], [Fraction(-4, 3), Fraction(5, 3), Fraction(0), Fraction(0)], [Fraction(0), Fraction(0), Fraction(1), Fraction(0)], [Fraction(0), Fraction(0), Fraction(0), Fraction(1)]]
    preserved = _tensor_matrix_multiply(_mtr_transpose(boost), _tensor_matrix_multiply(eta, boost)) == eta
    inverse_exact = _tensor_matrix_multiply(boost, boost_inverse) == _mtr_identity(4)
    null_vectors = tuple((Fraction(1), Fraction(sign if axis == 1 else 0), Fraction(sign if axis == 2 else 0), Fraction(sign if axis == 3 else 0)) for axis in (1, 2, 3) for sign in (-1, 1))
    null_exact = all(_mtr_dot(vector, _mtr_matvec(eta, vector)) == 0 for vector in null_vectors)
    transformed_null_exact = all(_mtr_dot(tuple(_mtr_matvec(boost, vector)), _mtr_matvec(eta, tuple(_mtr_matvec(boost, vector)))) == 0 for vector in null_vectors)
    sign_patterns = tuple(itertools.product((Fraction(-1), Fraction(1)), repeat=4))
    opposite_event_patterns = tuple(pattern for pattern in sign_patterns if pattern[1] == pattern[2] == pattern[3] and pattern[0] == -pattern[1])
    oriented_patterns = tuple(pattern for pattern in opposite_event_patterns if pattern[0] == -1)
    exact = preserved and inverse_exact and _fraction_matrix_determinant(boost) == 1 and null_exact and transformed_null_exact and len(opposite_event_patterns) == 2 and oriented_patterns == ((Fraction(-1), Fraction(1), Fraction(1), Fraction(1)),)
    return {
        'metric': eta,
        'rational_boost': boost,
        'boost_determinant': _fraction_matrix_determinant(boost),
        'metric_preserved': preserved,
        'inverse_exact': inverse_exact,
        'primitive_null_vector_count': len(null_vectors),
        'null_vectors_exact': null_exact,
        'transformed_null_vectors_exact': transformed_null_exact,
        'opposite_event_signature_patterns': opposite_event_patterns,
        'time_oriented_signature_patterns': oriented_patterns,
        'one_plus_three_signature_unique_in_declared_class': len(oriented_patterns) == 1,
        'theorem_result': exact,
    }


def _fc_su_basis(size):
    basis = []
    labels = []
    for left in range(size):
        for right in range(left + 1, size):
            skew = _fc_gzero_matrix(size)
            skew[left][right] = _fc_gaussian(1, 0)
            skew[right][left] = _fc_gaussian(-1, 0)
            basis.append(skew)
            labels.append('A' + str(left + 1) + str(right + 1))
            symmetric_i = _fc_gzero_matrix(size)
            symmetric_i[left][right] = _fc_gaussian(0, 1)
            symmetric_i[right][left] = _fc_gaussian(0, 1)
            basis.append(symmetric_i)
            labels.append('B' + str(left + 1) + str(right + 1))
    for diagonal in range(size - 1):
        generator = _fc_gzero_matrix(size)
        for index in range(diagonal + 1):
            generator[index][index] = _fc_gaussian(0, 1)
        generator[diagonal + 1][diagonal + 1] = _fc_gaussian(0, -(diagonal + 1))
        basis.append(generator)
        labels.append('H' + str(diagonal + 1))
    return tuple(labels), tuple(basis)


def _fc_lie_closure_packet(basis):
    flattened = tuple(_fc_gflatten(generator) for generator in basis)
    closure_coefficients = []
    closure_exact = True
    for left in range(len(basis)):
        for right in range(left + 1, len(basis)):
            commutator = _fc_gcommutator(basis[left], basis[right])
            coefficients = _fc_rectangular_solve(flattened, _fc_gflatten(commutator))
            reconstructed = _fc_glinear_combination(coefficients, basis)
            closure_exact = closure_exact and reconstructed == commutator
            closure_coefficients.append((left, right, coefficients))
    traceless = all(_fc_gtrace(generator) == _fc_gaussian() for generator in basis)
    antihermitian = all(_fc_gdagger(generator) == [[_fc_gscale(-1, value) for value in row] for row in generator] for generator in basis)
    independent = fraction_rank(flattened) == len(basis)
    return {'dimension': len(basis), 'independent': independent, 'traceless': traceless, 'antihermitian': antihermitian, 'commutator_pair_count': len(closure_coefficients), 'commutator_closure_exact': closure_exact, 'theorem_result': independent and traceless and antihermitian and closure_exact}


def _fc_gauge_bundle_curvature_packet():
    su2_labels, su2_basis = _fc_su_basis(2)
    su3_labels, su3_basis = _fc_su_basis(3)
    su2 = _fc_lie_closure_packet(su2_basis)
    su3 = _fc_lie_closure_packet(su3_basis)
    u1 = _fc_gzero_matrix(3)
    for index in range(3):
        u1[index][index] = _fc_gaussian(0, 1)
    u1_central = all(_fc_gcommutator(u1, generator) == _fc_gzero_matrix(3) for generator in su3_basis)
    connection_left = su3_basis[0]
    connection_right = su3_basis[3]
    curvature = _fc_gcommutator(connection_left, connection_right)
    permutation = [[_fc_gaussian(0, 0) for _ in range(3)] for _ in range(3)]
    permutation[0][1] = _fc_gaussian(1, 0)
    permutation[1][2] = _fc_gaussian(1, 0)
    permutation[2][0] = _fc_gaussian(1, 0)
    permutation_inverse = _fc_ginverse_real_orthogonal(permutation)
    transformed_left = _fc_gmatmul(permutation, _fc_gmatmul(connection_left, permutation_inverse))
    transformed_right = _fc_gmatmul(permutation, _fc_gmatmul(connection_right, permutation_inverse))
    transformed_curvature = _fc_gcommutator(transformed_left, transformed_right)
    expected_curvature = _fc_gmatmul(permutation, _fc_gmatmul(curvature, permutation_inverse))
    action = _fc_gscale(-1, _fc_gtrace(_fc_gmatmul(curvature, curvature)))
    transformed_action = _fc_gscale(-1, _fc_gtrace(_fc_gmatmul(transformed_curvature, transformed_curvature)))
    transition_cocycle = _fc_gmatmul(permutation, _fc_gmatmul(permutation, permutation)) == _fc_gidentity(3)
    exact = su2['theorem_result'] and su3['theorem_result'] and su2['dimension'] == 3 and su3['dimension'] == 8 and u1_central and transformed_curvature == expected_curvature and action == transformed_action and action[1] == 0 and action[0] >= 0 and transition_cocycle
    return {
        'u1_dimension': 1,
        'su2_labels': su2_labels,
        'su2_packet': su2,
        'su3_labels': su3_labels,
        'su3_packet': su3,
        'u1_central_with_su3': u1_central,
        'transition_cocycle_order_three': transition_cocycle,
        'curvature_covariant': transformed_curvature == expected_curvature,
        'yang_mills_trace_action': action,
        'trace_action_invariant': action == transformed_action,
        'theorem_result': exact,
    }


def _fc_matter_higgs_packet():
    annihilation = [[Fraction(0), Fraction(1)], [Fraction(0), Fraction(0)]]
    creation = [[Fraction(0), Fraction(0)], [Fraction(1), Fraction(0)]]
    number = _tensor_matrix_multiply(creation, annihilation)
    car = _fc_matrix_add(_tensor_matrix_multiply(annihilation, creation), _tensor_matrix_multiply(creation, annihilation))
    nilpotent = _tensor_matrix_multiply(annihilation, annihilation) == _fc_zero_matrix(2, 2) and _tensor_matrix_multiply(creation, creation) == _fc_zero_matrix(2, 2)
    chirality = [[Fraction(-1), Fraction(0)], [Fraction(0), Fraction(1)]]
    identity = _mtr_identity(2)
    left_projector = _fc_matrix_scale(Fraction(1, 2), _fc_matrix_sub(identity, chirality))
    right_projector = _fc_matrix_scale(Fraction(1, 2), _fc_matrix_add(identity, chirality))
    projectors_exact = _tensor_matrix_multiply(left_projector, left_projector) == left_projector and _tensor_matrix_multiply(right_projector, right_projector) == right_projector and _tensor_matrix_multiply(left_projector, right_projector) == _fc_zero_matrix(2, 2) and _fc_matrix_add(left_projector, right_projector) == identity
    vacuum = (Fraction(1), Fraction(0))
    rational_rotation = [[Fraction(3, 5), Fraction(-4, 5)], [Fraction(4, 5), Fraction(3, 5)]]
    orbit = []
    current = vacuum
    for _ in range(4):
        orbit.append(current)
        current = tuple(_mtr_matvec(rational_rotation, current))
    vacuum_norms = tuple(_mtr_norm_squared(point) for point in orbit)
    vacuum_potentials = tuple((norm - 1) * (norm - 1) for norm in vacuum_norms)
    hessian = [[Fraction(8), Fraction(0)], [Fraction(0), Fraction(0)]]
    hessian_rank = fraction_rank(hessian)
    residual_generator = [[Fraction(0), Fraction(0)], [Fraction(0), Fraction(1)]]
    broken_generator = [[Fraction(0), Fraction(1)], [Fraction(1), Fraction(0)]]
    residual_annihilates_vacuum = tuple(_mtr_matvec(residual_generator, vacuum)) == (Fraction(0), Fraction(0))
    broken_moves_vacuum = tuple(_mtr_matvec(broken_generator, vacuum)) != (Fraction(0), Fraction(0))
    anomaly_charges = (Fraction(1), Fraction(-1))
    anomaly_free = sum(anomaly_charges, Fraction(0)) == 0 and sum((charge ** 3 for charge in anomaly_charges), Fraction(0)) == 0
    exact = car == identity and nilpotent and number == [[Fraction(0), Fraction(0)], [Fraction(0), Fraction(1)]] and projectors_exact and all(value == 1 for value in vacuum_norms) and all(value == 0 for value in vacuum_potentials) and hessian_rank == 1 and residual_annihilates_vacuum and broken_moves_vacuum and anomaly_free
    return {
        'car_identity': car,
        'nilpotent_creation_annihilation': nilpotent,
        'number_operator': number,
        'left_projector': left_projector,
        'right_projector': right_projector,
        'chiral_projectors_exact': projectors_exact,
        'rational_vacuum_orbit': tuple(orbit),
        'vacuum_norms': vacuum_norms,
        'vacuum_potentials': vacuum_potentials,
        'vacuum_hessian': hessian,
        'radial_hessian_rank': hessian_rank,
        'one_residual_generator_annihilates_vacuum': residual_annihilates_vacuum,
        'broken_generator_moves_vacuum': broken_moves_vacuum,
        'finite_u1_anomaly_pair_exact': anomaly_free,
        'theorem_result': exact,
    }


def _fc_gravity_variation_packet():
    incidence = [[Fraction(-1), Fraction(1), Fraction(0), Fraction(0)], [Fraction(0), Fraction(-1), Fraction(1), Fraction(0)], [Fraction(0), Fraction(0), Fraction(-1), Fraction(1)], [Fraction(1), Fraction(0), Fraction(0), Fraction(-1)]]
    laplacian = _tensor_matrix_multiply(_mtr_transpose(incidence), incidence)
    sector_sources = {
        'ELECTROMAGNETIC': (Fraction(1), Fraction(-1), Fraction(0), Fraction(0)),
        'WEAK': (Fraction(0), Fraction(1), Fraction(-1), Fraction(0)),
        'STRONG': (Fraction(0), Fraction(0), Fraction(2), Fraction(-2)),
    }
    total_source = tuple(sum((source[index] for source in sector_sources.values()), Fraction(0)) for index in range(4))
    def solve_conserved(source):
        matrix = [list(row) for row in laplacian[:3]] + [[Fraction(1), Fraction(1), Fraction(1), Fraction(1)]]
        vector = list(source[:3]) + [Fraction(0)]
        return _fraction_linear_solve(matrix, vector)
    sector_fields = {name: solve_conserved(source) for name, source in sector_sources.items()}
    total_field = solve_conserved(total_source)
    summed_field = tuple(sum((field[index] for field in sector_fields.values()), Fraction(0)) for index in range(4))
    equation_exact = tuple(_mtr_matvec(laplacian, total_field)) == total_source
    bianchi_exact = tuple(_mtr_matvec(laplacian, (Fraction(1), Fraction(1), Fraction(1), Fraction(1)))) == (Fraction(0), Fraction(0), Fraction(0), Fraction(0)) and sum(total_source, Fraction(0)) == 0
    universal_coupling = summed_field == total_field
    action_stationarity = tuple(_mtr_matvec(laplacian, total_field)) == total_source
    initial_data_reconstruction = tuple(_mtr_matvec(incidence, total_field))
    exact = equation_exact and bianchi_exact and universal_coupling and action_stationarity and sum(total_field, Fraction(0)) == 0
    return {
        'incidence': incidence,
        'laplacian': laplacian,
        'sector_sources': sector_sources,
        'total_source': total_source,
        'sector_fields': sector_fields,
        'total_field': total_field,
        'summed_sector_field': summed_field,
        'gauge_fixed_field_equation_exact': equation_exact,
        'discrete_bianchi_and_source_conservation_exact': bianchi_exact,
        'universal_total_source_coupling_exact': universal_coupling,
        'edge_geometry_readout': initial_data_reconstruction,
        'theorem_result': exact,
    }


def _fc_quantum_measure_packet():
    unitary = [[_fc_gaussian(Fraction(3, 5), 0), _fc_gaussian(Fraction(-4, 5), 0)], [_fc_gaussian(Fraction(4, 5), 0), _fc_gaussian(Fraction(3, 5), 0)]]
    unitary_exact = _fc_gmatmul(_fc_gdagger(unitary), unitary) == _fc_gidentity(2)
    initial = (_fc_gaussian(1, 0), _fc_gaussian(0, 0))
    evolved = tuple(_fc_gmatvec(unitary, initial))
    probabilities = tuple(value[0] * value[0] + value[1] * value[1] for value in evolved)
    probability_normalized = sum(probabilities, Fraction(0)) == 1
    transition = [[Fraction(9, 25), Fraction(16, 25)], [Fraction(16, 25), Fraction(9, 25)]]
    joint = tuple(tuple(probabilities[left] * transition[left][right] for right in range(2)) for left in range(2))
    first_marginal = tuple(sum(row, Fraction(0)) for row in joint)
    second_marginal = tuple(sum((joint[left][right] for left in range(2)), Fraction(0)) for right in range(2))
    projective_consistency = first_marginal == probabilities and sum(second_marginal, Fraction(0)) == 1
    covariance = [[Fraction(1), Fraction(1, 2)], [Fraction(1, 2), Fraction(1)]]
    reflection_positive_values = []
    for coefficient in range(-5, 6):
        vector = (Fraction(0), Fraction(coefficient))
        reflected = (vector[1], vector[0])
        value = _mtr_dot(reflected, _mtr_matvec(covariance, vector))
        reflection_positive_values.append(value)
    reflection_positive = all(value >= 0 for value in reflection_positive_values)
    chiral_block = [[Fraction(1), Fraction(1)], [Fraction(0), Fraction(1)]]
    gauge = [[Fraction(3, 5), Fraction(-4, 5)], [Fraction(4, 5), Fraction(3, 5)]]
    gauge_inverse = _fc_matrix_inverse(gauge)
    transformed_block = _tensor_matrix_multiply(gauge, _tensor_matrix_multiply(chiral_block, gauge_inverse))
    determinant_invariant = _fraction_matrix_determinant(chiral_block) == _fraction_matrix_determinant(transformed_block) == 1
    exact = unitary_exact and probability_normalized and projective_consistency and reflection_positive and determinant_invariant
    return {
        'rational_unitary': unitary,
        'unitary_exact': unitary_exact,
        'evolved_amplitude': evolved,
        'born_probabilities': probabilities,
        'probability_normalized': probability_normalized,
        'two_step_joint_measure': joint,
        'first_marginal': first_marginal,
        'second_marginal': second_marginal,
        'finite_projective_consistency': projective_consistency,
        'reflection_positive_values': tuple(reflection_positive_values),
        'finite_reflection_positivity': reflection_positive,
        'finite_chiral_determinant_gauge_invariant': determinant_invariant,
        'theorem_result': exact,
    }


def _fc_rg_strong_packet():
    intervals = (Fraction(1, 3), Fraction(1, 5), Fraction(7, 15))
    total_interval = sum(intervals, Fraction(0))
    left = Fraction(-2)
    right = Fraction(5)
    positions = [left]
    elapsed = Fraction(0)
    for interval in intervals[:-1]:
        elapsed += interval
        positions.append(left + elapsed * (right - left) / total_interval)
    positions.append(right)
    refined_action = sum(((positions[index + 1] - positions[index]) ** 2 / (2 * intervals[index]) for index in range(len(intervals))), Fraction(0))
    coarse_action = (right - left) ** 2 / (2 * total_interval)
    first_condensed_interval = intervals[0] + intervals[1]
    sequential_action = (positions[2] - positions[0]) ** 2 / (2 * first_condensed_interval) + (positions[3] - positions[2]) ** 2 / (2 * intervals[2])
    associative_condensation = refined_action == sequential_action == coarse_action
    k3_laplacian = [[Fraction(2), Fraction(-1), Fraction(-1)], [Fraction(-1), Fraction(2), Fraction(-1)], [Fraction(-1), Fraction(-1), Fraction(2)]]
    color_roots = ((Fraction(1), Fraction(-1), Fraction(0)), (Fraction(1), Fraction(0), Fraction(-1)), (Fraction(0), Fraction(1), Fraction(-1)))
    gap_ratios = tuple(_mtr_dot(root, _mtr_matvec(k3_laplacian, root)) / _mtr_norm_squared(root) for root in color_roots)
    finite_gap = all(value == 3 for value in gap_ratios)
    string_lengths = tuple(range(1, 9))
    string_energies = tuple(Fraction(length) for length in string_lengths)
    linear_confinement = all(string_energies[index + 1] - string_energies[index] == 1 for index in range(len(string_energies) - 1))
    exact = total_interval == 1 and associative_condensation and finite_gap and linear_confinement
    return {
        'intervals': intervals,
        'stationary_positions': tuple(positions),
        'refined_action': refined_action,
        'sequentially_condensed_action': sequential_action,
        'coarse_action': coarse_action,
        'exact_rg_semigroup_condensation': associative_condensation,
        'color_neutral_gap_ratios': gap_ratios,
        'finite_color_gap_exact': finite_gap,
        'string_lengths': string_lengths,
        'string_energies': string_energies,
        'finite_linear_string_energy_exact': linear_confinement,
        'theorem_result': exact,
    }


def _fc_gaussian_givens(size, left, right, cosine, sine, phase_imaginary=False):
    matrix = _fc_gidentity(size)
    c = _fc_gaussian(cosine, 0)
    if phase_imaginary:
        upper = _fc_gaussian(0, -sine)
        lower = _fc_gaussian(0, -sine)
    else:
        upper = _fc_gaussian(sine, 0)
        lower = _fc_gaussian(-sine, 0)
    matrix[left][left] = c
    matrix[right][right] = c
    matrix[left][right] = upper
    matrix[right][left] = lower
    return matrix


def _fc_decoder_packet():
    rank = 3
    generation_labels = tuple(range(1, rank + 1))
    cumulative_weights = tuple(sum(range(1, generation + 1)) for generation in generation_labels)
    mass_ratios = tuple(Fraction(weight, cumulative_weights[0]) for weight in cumulative_weights)
    r12 = _fc_gaussian_givens(3, 0, 1, Fraction(3, 5), Fraction(4, 5), False)
    r13 = _fc_gaussian_givens(3, 0, 2, Fraction(3, 5), Fraction(4, 5), True)
    r23 = _fc_gaussian_givens(3, 1, 2, Fraction(3, 5), Fraction(4, 5), False)
    mixing = _fc_gmatmul(r23, _fc_gmatmul(r13, r12))
    unitary_exact = _fc_gmatmul(_fc_gdagger(mixing), mixing) == _fc_gidentity(3)
    moduli_squared = tuple(tuple(value[0] * value[0] + value[1] * value[1] for value in row) for row in mixing)
    row_sums = tuple(sum(row, Fraction(0)) for row in moduli_squared)
    column_sums = tuple(sum((moduli_squared[row][column] for row in range(3)), Fraction(0)) for column in range(3))
    u00 = mixing[0][0]
    u11 = mixing[1][1]
    u01_conj = _fc_gconj(mixing[0][1])
    u10_conj = _fc_gconj(mixing[1][0])
    j_product = _fc_gmul(_fc_gmul(u00, u11), _fc_gmul(u01_conj, u10_conj))
    jarlskog = j_product[1]
    nonzero_cp = jarlskog != 0
    squared_weights = tuple(Fraction(weight * weight) for weight in cumulative_weights)
    neutrino_split_ratio = (squared_weights[1] - squared_weights[0]) / (squared_weights[2] - squared_weights[0])
    occupation_states = tuple(range(4))
    occupation_energies = tuple(Fraction(number * (number + 1), 2) for number in occupation_states)
    ionization_gaps = tuple(occupation_energies[number] - occupation_energies[number - 1] for number in range(1, len(occupation_states)))
    decoder_rows = tuple((number, occupation_energies[number]) for number in occupation_states)
    decoder_injective = len(set(decoder_rows)) == len(decoder_rows)
    exact = generation_labels == (1, 2, 3) and mass_ratios == (Fraction(1), Fraction(3), Fraction(6)) and unitary_exact and row_sums == (Fraction(1), Fraction(1), Fraction(1)) and column_sums == (Fraction(1), Fraction(1), Fraction(1)) and nonzero_cp and neutrino_split_ratio == Fraction(8, 35) and ionization_gaps == (Fraction(1), Fraction(2), Fraction(3)) and decoder_injective
    return {
        'generation_labels_from_spatial_rank': generation_labels,
        'cumulative_native_weights': cumulative_weights,
        'internal_mass_ratios': mass_ratios,
        'mixing_matrix': mixing,
        'mixing_unitary_exact': unitary_exact,
        'mixing_moduli_squared': moduli_squared,
        'row_probability_sums': row_sums,
        'column_probability_sums': column_sums,
        'jarlskog_exact': jarlskog,
        'nonzero_internal_cp_invariant': nonzero_cp,
        'internal_neutrino_split_ratio': neutrino_split_ratio,
        'finite_occupation_states': occupation_states,
        'finite_occupation_energies': occupation_energies,
        'ionization_gap_ratios': ionization_gaps,
        'finite_decoder_injective': decoder_injective,
        'no_standard_value_used': True,
        'theorem_result': exact,
    }


