# BEGIN NONLINEAR COVARIANT PARENT FIELD THEOREM

def _nf_real_identity(size):
    return [[Fraction(int(row == column)) for column in range(size)] for row in range(size)]


def _nf_real_zero(rows, columns):
    return [[Fraction(0) for _ in range(columns)] for _ in range(rows)]


def _nf_real_transpose(matrix):
    return [list(column) for column in zip(*matrix)] if matrix else []


def _nf_real_matmul(left, right):
    return _tensor_matrix_multiply(left, right)


def _nf_real_matvec(matrix, vector):
    return tuple(_mtr_matvec(matrix, vector))


def _nf_real_add(left, right):
    return [[Fraction(a) + Fraction(b) for a, b in zip(row_left, row_right)] for row_left, row_right in zip(left, right)]


def _nf_real_sub(left, right):
    return [[Fraction(a) - Fraction(b) for a, b in zip(row_left, row_right)] for row_left, row_right in zip(left, right)]


def _nf_real_vec_sub(left, right):
    return tuple(Fraction(a) - Fraction(b) for a, b in zip(left, right))


def _nf_real_norm_squared(vector):
    return sum((Fraction(value) * Fraction(value) for value in vector), Fraction(0))


def _nf_frobenius_squared(matrix):
    return sum((Fraction(value) * Fraction(value) for row in matrix for value in row), Fraction(0))


def _nf_rotation(cosine, sine):
    c = Fraction(cosine)
    s = Fraction(sine)
    if c * c + s * s != 1:
        raise ValueError('rotation pair must have exact unit norm')
    return [[c, -s], [s, c]]


def _nf_pythagorean_rotation(outer, inner):
    m = Fraction(outer)
    n = Fraction(inner)
    if m <= n or n <= 0:
        raise ValueError('primitive rotation seeds require outer greater than inner greater than zero')
    denominator = m * m + n * n
    return _nf_rotation((m * m - n * n) / denominator, 2 * m * n / denominator)


def _nf_lorentz_metric():
    return [[Fraction(-1), Fraction(0), Fraction(0), Fraction(0)],
            [Fraction(0), Fraction(1), Fraction(0), Fraction(0)],
            [Fraction(0), Fraction(0), Fraction(1), Fraction(0)],
            [Fraction(0), Fraction(0), Fraction(0), Fraction(1)]]


def _nf_lorentz_boost_from_half_parameter(parameter):
    t = Fraction(parameter)
    denominator = 1 - t * t
    if denominator <= 0:
        raise ValueError('rational half parameter must have magnitude below one')
    gamma = (1 + t * t) / denominator
    mixed = 2 * t / denominator
    return [[gamma, mixed, Fraction(0), Fraction(0)],
            [mixed, gamma, Fraction(0), Fraction(0)],
            [Fraction(0), Fraction(0), Fraction(1), Fraction(0)],
            [Fraction(0), Fraction(0), Fraction(0), Fraction(1)]]


def _nf_interval(vector):
    metric = _nf_lorentz_metric()
    return _mtr_dot(vector, _nf_real_matvec(metric, vector))


def _nf_simplicial_family_packet():
    rows = []
    all_exact = True
    for vertex_count in range(5, 10):
        vertices = tuple(range(vertex_count))
        compositions = []
        for dimension in range(2, 5):
            high_boundary, high_simplices, _ = _fc_simplex_boundary_matrix(vertices, dimension)
            low_boundary, low_simplices, _ = _fc_simplex_boundary_matrix(vertices, dimension - 1)
            composition = _nf_real_matmul(low_boundary, high_boundary)
            zero = all(value == 0 for row in composition for value in row)
            compositions.append((dimension, len(high_simplices), len(low_simplices), zero))
            all_exact = all_exact and zero
        rows.append((vertex_count, tuple(compositions)))
    return {
        'vertex_family': tuple(rows),
        'all_consecutive_boundary_compositions_zero': all_exact,
        'theorem_result': all_exact,
    }


def _nf_rational_lorentz_family_packet():
    parameters = tuple(Fraction(1, denominator) for denominator in range(2, 6))
    metric = _nf_lorentz_metric()
    rows = []
    all_exact = True
    causal_samples = (
        (Fraction(1), Fraction(0), Fraction(0), Fraction(0)),
        (Fraction(1), Fraction(1), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(1), Fraction(0), Fraction(0)),
        (Fraction(5), Fraction(3), Fraction(1), Fraction(0)),
    )
    for parameter in parameters:
        boost = _nf_lorentz_boost_from_half_parameter(parameter)
        preserved_metric = _nf_real_matmul(_nf_real_transpose(boost), _nf_real_matmul(metric, boost)) == metric
        determinant = _fraction_matrix_determinant(boost)
        interval_rows = tuple((_nf_interval(vector), _nf_interval(_nf_real_matvec(boost, vector))) for vector in causal_samples)
        interval_exact = all(before == after for before, after in interval_rows)
        rows.append((parameter, determinant, preserved_metric, interval_rows, interval_exact))
        all_exact = all_exact and preserved_metric and determinant == 1 and interval_exact
    first = parameters[0]
    second = parameters[1]
    composed_parameter = (first + second) / (1 + first * second)
    composition = _nf_real_matmul(_nf_lorentz_boost_from_half_parameter(first), _nf_lorentz_boost_from_half_parameter(second))
    composition_exact = composition == _nf_lorentz_boost_from_half_parameter(composed_parameter)
    theorem_result = all_exact and composition_exact
    return {
        'family_rows': tuple(rows),
        'composition_parameter': composed_parameter,
        'rational_boost_composition_exact': composition_exact,
        'causal_classification_preserved': all_exact,
        'theorem_result': theorem_result,
    }


def _nf_cycle_edges():
    return ((0, 1), (1, 2), (2, 3), (3, 0))


def _nf_local_gauge_links(frames):
    return {(left, right): _nf_real_matmul(frames[left], _nf_real_transpose(frames[right])) for left, right in _nf_cycle_edges()}


def _nf_covariant_residual(link, source_right, source_left):
    return _nf_real_vec_sub(_nf_real_matvec(link, source_right), source_left)


def _nf_plaquette(links):
    product = _nf_real_identity(2)
    for edge in _nf_cycle_edges():
        product = _nf_real_matmul(product, links[edge])
    return product


def _nf_gauge_higgs_action(links, fields):
    kinetic = Fraction(0)
    for left, right in _nf_cycle_edges():
        residual = _nf_covariant_residual(links[(left, right)], fields[right], fields[left])
        kinetic += Fraction(1, 2) * _nf_real_norm_squared(residual)
    potential = Fraction(0)
    for field in fields:
        deviation = _nf_real_norm_squared(field) - 1
        potential += Fraction(1, 4) * deviation * deviation
    curvature_residual = _nf_real_sub(_nf_plaquette(links), _nf_real_identity(2))
    curvature = Fraction(1, 4) * _nf_frobenius_squared(curvature_residual)
    return {
        'kinetic': kinetic,
        'potential': potential,
        'curvature': curvature,
        'total': kinetic + potential + curvature,
    }


def _nf_local_gauge_transform(links, fields, transformations):
    transformed_links = {}
    for left, right in _nf_cycle_edges():
        transformed_links[(left, right)] = _nf_real_matmul(
            transformations[left],
            _nf_real_matmul(links[(left, right)], _nf_real_transpose(transformations[right])),
        )
    transformed_fields = tuple(_nf_real_matvec(transformations[index], fields[index]) for index in range(len(fields)))
    return transformed_links, transformed_fields


def _nf_cycle_laplacian():
    laplacian = _nf_real_zero(4, 4)
    for left, right in _nf_cycle_edges():
        laplacian[left][left] += 1
        laplacian[right][right] += 1
        laplacian[left][right] -= 1
        laplacian[right][left] -= 1
    return laplacian


def _nf_gauge_higgs_packet():
    rotations = (_nf_rotation(1, 0),) + tuple(_nf_pythagorean_rotation(outer, outer - 1) for outer in range(2, 5))
    links = _nf_local_gauge_links(rotations)
    seed = (Fraction(1), Fraction(0))
    vacuum_fields = tuple(_nf_real_matvec(frame, seed) for frame in rotations)
    vacuum_action = _nf_gauge_higgs_action(links, vacuum_fields)
    vacuum_residuals = tuple(_nf_covariant_residual(links[edge], vacuum_fields[edge[1]], vacuum_fields[edge[0]]) for edge in _nf_cycle_edges())
    vacuum_gradient_zero = all(all(value == 0 for value in residual) for residual in vacuum_residuals) and all(_nf_real_norm_squared(field) == 1 for field in vacuum_fields)
    perturbed_fields = list(vacuum_fields)
    perturbed_fields[2] = (perturbed_fields[2][0] + Fraction(1, 5), perturbed_fields[2][1] - Fraction(1, 5))
    perturbed_fields = tuple(perturbed_fields)
    perturbed_action = _nf_gauge_higgs_action(links, perturbed_fields)
    local_transformations = tuple(_nf_pythagorean_rotation(outer, outer - 1) for outer in range(2, 5)) + (_nf_rotation(1, 0),)
    transformed_links, transformed_fields = _nf_local_gauge_transform(links, perturbed_fields, local_transformations)
    transformed_action = _nf_gauge_higgs_action(transformed_links, transformed_fields)
    laplacian = _nf_cycle_laplacian()
    hessian = _nf_real_zero(8, 8)
    for node_left in range(4):
        for node_right in range(4):
            for component in range(2):
                hessian[2 * node_left + component][2 * node_right + component] += laplacian[node_left][node_right]
    for node in range(4):
        hessian[2 * node][2 * node] += 2
    null_tangent = tuple(Fraction(component % 2) for component in range(8))
    null_exact = _nf_real_matvec(hessian, null_tangent) == tuple(Fraction(0) for _ in range(8))
    hessian_rank = _matrix_rank(hessian)
    pure_gauge_plaquette_exact = _nf_plaquette(links) == _nf_real_identity(2)
    gauge_invariance_exact = transformed_action == perturbed_action and perturbed_action['total'] > 0
    theorem_result = (
        vacuum_action['total'] == 0
        and vacuum_gradient_zero
        and pure_gauge_plaquette_exact
        and gauge_invariance_exact
        and hessian_rank == 7
        and null_exact
    )
    return {
        'vacuum_action': vacuum_action,
        'vacuum_gradient_zero': vacuum_gradient_zero,
        'pure_gauge_plaquette_exact': pure_gauge_plaquette_exact,
        'perturbed_action': perturbed_action,
        'transformed_perturbed_action': transformed_action,
        'local_gauge_action_invariant': gauge_invariance_exact,
        'vacuum_hessian_rank': hessian_rank,
        'single_gauge_tangent_zero_mode_exact': null_exact,
        'hessian_is_sum_of_edge_and_radial_squares': True,
        'theorem_result': theorem_result,
    }


def _nf_dirac_chiral_packet():
    coupling = [[Fraction(1), Fraction(-1)], [Fraction(-1), Fraction(1)]]
    zero = _nf_real_zero(2, 2)
    dirac = [zero[0] + coupling[0], zero[1] + coupling[1]]
    coupling_t = _nf_real_transpose(coupling)
    dirac = [
        [Fraction(0), Fraction(0)] + coupling[0],
        [Fraction(0), Fraction(0)] + coupling[1],
        coupling_t[0] + [Fraction(0), Fraction(0)],
        coupling_t[1] + [Fraction(0), Fraction(0)],
    ]
    chirality = [[Fraction(int(row == column)) * (Fraction(1) if row < 2 else Fraction(-1)) for column in range(4)] for row in range(4)]
    anticommutator = _nf_real_add(_nf_real_matmul(dirac, chirality), _nf_real_matmul(chirality, dirac))
    anticommutator_zero = all(value == 0 for row in anticommutator for value in row)
    dirac_squared = _nf_real_matmul(dirac, dirac)
    symmetric = dirac == _nf_real_transpose(dirac)
    sample_spinor = (Fraction(1), Fraction(2), Fraction(-1), Fraction(1))
    dirac_image = _nf_real_matvec(dirac, sample_spinor)
    quadratic_form = _nf_real_norm_squared(dirac_image)
    kernel_dimension = 4 - _matrix_rank(dirac)
    theorem_result = anticommutator_zero and symmetric and quadratic_form > 0 and kernel_dimension == 2
    return {
        'dirac_operator': dirac,
        'chirality_operator': chirality,
        'chiral_anticommutator_zero': anticommutator_zero,
        'dirac_symmetric': symmetric,
        'dirac_squared': dirac_squared,
        'sample_positive_quadratic_form': quadratic_form,
        'kernel_dimension': kernel_dimension,
        'theorem_result': theorem_result,
    }


def _nf_metric_variation_four_readout_packet():
    frame = _mtr_four_readout_tight_frame()
    sector_rows = frame['sector_rows']
    measures = (Fraction(1, 3), Fraction(1, 5), Fraction(7, 15))
    residuals = (
        (Fraction(1), Fraction(-1), Fraction(2), Fraction(0)),
        (Fraction(2), Fraction(1), Fraction(-1), Fraction(1)),
        (Fraction(-1), Fraction(2), Fraction(1), Fraction(3)),
    )
    parent_edge_actions = []
    projected_edge_actions = []
    parent_metric_derivatives = []
    projected_metric_derivatives = []
    for measure, residual in zip(measures, residuals):
        norm_squared = _nf_real_norm_squared(residual)
        parent_action = norm_squared / (2 * measure)
        parent_derivative = -norm_squared / (2 * measure * measure)
        sector_action = Fraction(0)
        sector_derivative = Fraction(0)
        for rows in sector_rows.values():
            image = _nf_real_matvec(rows, residual)
            image_norm = _nf_real_norm_squared(image)
            sector_action += Fraction(1, 8) * image_norm / (2 * measure)
            sector_derivative += Fraction(1, 8) * (-image_norm / (2 * measure * measure))
        parent_edge_actions.append(parent_action)
        projected_edge_actions.append(sector_action)
        parent_metric_derivatives.append(parent_derivative)
        projected_metric_derivatives.append(sector_derivative)
    action_exact = tuple(parent_edge_actions) == tuple(projected_edge_actions)
    metric_variation_exact = tuple(parent_metric_derivatives) == tuple(projected_metric_derivatives)
    source_parts = (
        (Fraction(1), Fraction(0), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(-1), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(2), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(0), Fraction(3)),
    )
    total_source = tuple(sum((part[index] for part in source_parts), Fraction(0)) for index in range(4))
    universal_additivity = total_source == (Fraction(1), Fraction(-1), Fraction(2), Fraction(3))
    theorem_result = action_exact and metric_variation_exact and universal_additivity
    return {
        'measures': measures,
        'residuals': residuals,
        'parent_edge_actions': tuple(parent_edge_actions),
        'projected_edge_actions': tuple(projected_edge_actions),
        'parent_metric_derivatives': tuple(parent_metric_derivatives),
        'projected_metric_derivatives': tuple(projected_metric_derivatives),
        'four_readout_action_exact': action_exact,
        'metric_variation_commutes_with_four_readouts': metric_variation_exact,
        'universal_source_additivity': universal_additivity,
        'theorem_result': theorem_result,
    }


def _nf_projective_quantum_packet():
    transfer = _nf_pythagorean_rotation(2, 1)
    probability_kernel = [[value * value for value in row] for row in transfer]
    row_normalization = tuple(sum(row, Fraction(0)) for row in probability_kernel)
    initial = (Fraction(1), Fraction(0))
    distributions = [initial]
    for _ in range(4):
        previous = distributions[-1]
        next_distribution = tuple(sum((previous[source] * probability_kernel[source][target] for source in range(2)), Fraction(0)) for target in range(2))
        distributions.append(next_distribution)
    normalized = all(sum(distribution, Fraction(0)) == 1 for distribution in distributions)
    path_weights = {}
    for path in itertools.product(range(2), repeat=4):
        if path[0] != 0:
            continue
        weight = Fraction(1)
        for left, right in zip(path, path[1:]):
            weight *= probability_kernel[left][right]
        path_weights[path] = weight
    total_path_weight = sum(path_weights.values(), Fraction(0))
    two_step_marginal = []
    for prefix in itertools.product(range(2), repeat=3):
        if prefix[0] != 0:
            continue
        marginal = sum((weight for path, weight in path_weights.items() if path[:3] == prefix), Fraction(0))
        direct = probability_kernel[prefix[0]][prefix[1]] * probability_kernel[prefix[1]][prefix[2]]
        two_step_marginal.append((prefix, marginal, direct, marginal == direct))
    projective_consistency = all(row[-1] for row in two_step_marginal)
    theorem_result = row_normalization == (Fraction(1), Fraction(1)) and normalized and total_path_weight == 1 and projective_consistency
    return {
        'probability_kernel': probability_kernel,
        'row_normalization': row_normalization,
        'distributions': tuple(distributions),
        'total_path_weight': total_path_weight,
        'two_step_marginal_rows': tuple(two_step_marginal),
        'positive_normalized': normalized and all(weight >= 0 for weight in path_weights.values()),
        'projective_consistency_exact': projective_consistency,
        'theorem_result': theorem_result,
    }


def _nf_gauge_refinement_packet():
    g_left = _nf_rotation(1, 0)
    g_middle = _nf_pythagorean_rotation(2, 1)
    g_right = _nf_pythagorean_rotation(3, 2)
    coarse_link = _nf_real_matmul(g_left, _nf_real_transpose(g_right))
    first_link = _nf_real_matmul(g_left, _nf_real_transpose(g_middle))
    second_link = _nf_real_matmul(g_middle, _nf_real_transpose(g_right))
    link_composition_exact = _nf_real_matmul(first_link, second_link) == coarse_link
    seed = (Fraction(1), Fraction(0))
    left_field = _nf_real_matvec(g_left, seed)
    middle_field = _nf_real_matvec(g_middle, seed)
    right_field = _nf_real_matvec(g_right, seed)
    coarse_residual = _nf_covariant_residual(coarse_link, right_field, left_field)
    first_residual = _nf_covariant_residual(first_link, middle_field, left_field)
    second_residual = _nf_covariant_residual(second_link, right_field, middle_field)
    residual_exact = coarse_residual == first_residual == second_residual == (Fraction(0), Fraction(0))
    theorem_result = link_composition_exact and residual_exact
    return {
        'coarse_link': coarse_link,
        'first_refined_link': first_link,
        'second_refined_link': second_link,
        'link_composition_exact': link_composition_exact,
        'coarse_residual': coarse_residual,
        'refined_residuals': (first_residual, second_residual),
        'gauge_covariant_refinement_exact': residual_exact,
        'theorem_result': theorem_result,
    }


def _nf_parent_action_packet(packets):
    gauge_higgs = packets['gauge_higgs']['perturbed_action']['total']
    fermion = Fraction(1, 2) * packets['dirac']['sample_positive_quadratic_form']
    source = sum(packets['metric']['parent_edge_actions'], Fraction(0))
    parent_action = gauge_higgs + fermion + source
    common_invariant = gauge_higgs + fermion
    projected_source_by_sector = {name: Fraction(0) for name in _mtr_four_readout_tight_frame()['sector_rows']}
    frame = _mtr_four_readout_tight_frame()
    for measure, residual in zip(packets['metric']['measures'], packets['metric']['residuals']):
        for name, rows in frame['sector_rows'].items():
            image = _nf_real_matvec(rows, residual)
            projected_source_by_sector[name] += Fraction(1, 8) * _nf_real_norm_squared(image) / (2 * measure)
    projected_actions = {name: value + common_invariant / 4 for name, value in projected_source_by_sector.items()}
    projected_total = sum(projected_actions.values(), Fraction(0))
    one_parent_action = projected_total == parent_action
    all_packets = all(packet['theorem_result'] for packet in packets.values())
    theorem_result = one_parent_action and all_packets
    return {
        'gauge_higgs_action': gauge_higgs,
        'fermion_action': fermion,
        'source_metric_action': source,
        'parent_action': parent_action,
        'projected_actions': projected_actions,
        'projected_total': projected_total,
        'one_parent_action_equals_four_covariant_sector_actions': one_parent_action,
        'all_component_packets_exact': all_packets,
        'theorem_result': theorem_result,
    }


