def _pdl_uniform_intervals(level):
    count = 2 ** level
    return tuple(Fraction(1, count) for _ in range(count))


def _pdl_path_incidence(edge_count):
    matrix = [[Fraction(0) for _ in range(edge_count + 1)] for _ in range(edge_count)]
    for edge in range(edge_count):
        matrix[edge][edge] = Fraction(-1)
        matrix[edge][edge + 1] = Fraction(1)
    return matrix


def _pdl_stiffness(intervals):
    incidence = _pdl_path_incidence(len(intervals))
    weights = [[Fraction(0) for _ in intervals] for _ in intervals]
    for index, interval in enumerate(intervals):
        weights[index][index] = Fraction(1, 1) / interval
    return _tensor_matrix_multiply(_mtr_transpose(incidence), _tensor_matrix_multiply(weights, incidence))


def _pdl_prolongation(coarse_level, fine_level):
    if fine_level < coarse_level:
        raise ValueError('fine level must not precede coarse level')
    coarse_edges = 2 ** coarse_level
    fine_edges = 2 ** fine_level
    ratio = fine_edges // coarse_edges
    matrix = [[Fraction(0) for _ in range(coarse_edges + 1)] for _ in range(fine_edges + 1)]
    for fine_node in range(fine_edges + 1):
        coarse_left = min(fine_node // ratio, coarse_edges - 1)
        remainder = fine_node - coarse_left * ratio
        if fine_node == fine_edges:
            matrix[fine_node][coarse_edges] = Fraction(1)
        else:
            weight_right = Fraction(remainder, ratio)
            matrix[fine_node][coarse_left] = Fraction(1) - weight_right
            matrix[fine_node][coarse_left + 1] = weight_right
    return matrix


def _pdl_submatrix(matrix, rows, columns):
    return [[matrix[row][column] for column in columns] for row in rows]


def _pdl_matrix_sub(left, right):
    return [[left[row][column] - right[row][column] for column in range(len(left[0]))] for row in range(len(left))]


def _pdl_condensed_endpoint_matrix(stiffness):
    size = len(stiffness)
    boundary = (0, size - 1)
    interior = tuple(range(1, size - 1))
    boundary_block = _pdl_submatrix(stiffness, boundary, boundary)
    if not interior:
        return boundary_block
    boundary_interior = _pdl_submatrix(stiffness, boundary, interior)
    interior_boundary = _pdl_submatrix(stiffness, interior, boundary)
    interior_block = _pdl_submatrix(stiffness, interior, interior)
    inverse = _fc_matrix_inverse(interior_block)
    correction = _tensor_matrix_multiply(boundary_interior, _tensor_matrix_multiply(inverse, interior_boundary))
    return _pdl_matrix_sub(boundary_block, correction)


def _pdl_affine_source_at_nodes(level):
    edge_count = 2 ** level
    history = []
    for node in range(edge_count + 1):
        event = Fraction(node, edge_count)
        history.append((
            Fraction(1) + Fraction(2) * event,
            Fraction(2) - event,
            event,
            Fraction(3) * event,
        ))
    return tuple(history)


def _pdl_component_histories(history):
    return tuple(tuple(state[component] for state in history) for component in range(len(history[0])))


def _pdl_event_direct_system_packet():
    levels = tuple(range(5))
    stiffness = {level: _pdl_stiffness(_pdl_uniform_intervals(level)) for level in levels}
    prolongations = {(coarse, fine): _pdl_prolongation(coarse, fine) for coarse in levels for fine in levels if coarse <= fine}
    transitivity_rows = []
    for first in levels:
        for second in levels:
            for third in levels:
                if first <= second <= third:
                    composed = _tensor_matrix_multiply(prolongations[(second, third)], prolongations[(first, second)])
                    transitivity_rows.append((first, second, third, composed == prolongations[(first, third)]))
    naturality_rows = []
    condensation_rows = []
    affine_rows = []
    expected_endpoint = [[Fraction(1), Fraction(-1)], [Fraction(-1), Fraction(1)]]
    for coarse in levels[:-1]:
        fine = coarse + 1
        p = prolongations[(coarse, fine)]
        natural = _tensor_matrix_multiply(_mtr_transpose(p), _tensor_matrix_multiply(stiffness[fine], p))
        naturality_rows.append((coarse, fine, natural == stiffness[coarse]))
    for level in levels:
        condensed = _pdl_condensed_endpoint_matrix(stiffness[level])
        condensation_rows.append((level, condensed, condensed == expected_endpoint))
        history = _pdl_affine_source_at_nodes(level)
        if level > 0:
            previous = _pdl_affine_source_at_nodes(level - 1)
            p = prolongations[(level - 1, level)]
            reconstructed = []
            for component_history in _pdl_component_histories(previous):
                reconstructed.append(tuple(_mtr_matvec(p, component_history)))
            reconstructed_history = tuple(tuple(reconstructed[component][node] for component in range(4)) for node in range(len(history)))
            affine_rows.append((level - 1, level, reconstructed_history == history))
    theorem_result = (
        all(row[3] for row in transitivity_rows)
        and all(row[2] for row in naturality_rows)
        and all(row[2] for row in condensation_rows)
        and all(row[2] for row in affine_rows)
    )
    return {
        'levels': levels,
        'node_counts': tuple(2 ** level + 1 for level in levels),
        'prolongation_transitivity_rows': tuple(transitivity_rows),
        'stiffness_naturality_rows': tuple(naturality_rows),
        'endpoint_condensation_rows': tuple(condensation_rows),
        'affine_source_compatibility_rows': tuple(affine_rows),
        'prolongation_transitivity_exact': all(row[3] for row in transitivity_rows),
        'stiffness_naturality_exact': all(row[2] for row in naturality_rows),
        'condensation_path_independent_exact': all(row[2] for row in condensation_rows),
        'affine_source_defines_compatible_direct_system': all(row[2] for row in affine_rows),
        'theorem_result': theorem_result,
    }


def _pdl_simplex_inclusion(vertices_small, vertices_large, dimension):
    small_basis = tuple(itertools.combinations(tuple(range(vertices_small)), dimension + 1))
    large_basis = tuple(itertools.combinations(tuple(range(vertices_large)), dimension + 1))
    large_index = {simplex: index for index, simplex in enumerate(large_basis)}
    matrix = [[Fraction(0) for _ in small_basis] for _ in large_basis]
    for column, simplex in enumerate(small_basis):
        matrix[large_index[simplex]][column] = Fraction(1)
    return matrix


def _pdl_simplicial_direct_system_packet():
    vertex_counts = tuple(range(5, 10))
    chain_rows = []
    transitivity_rows = []
    for small, large in zip(vertex_counts[:-1], vertex_counts[1:]):
        for dimension in range(1, 5):
            boundary_small, _, _ = _fc_simplex_boundary_matrix(tuple(range(small)), dimension)
            boundary_large, _, _ = _fc_simplex_boundary_matrix(tuple(range(large)), dimension)
            include_high = _pdl_simplex_inclusion(small, large, dimension)
            include_low = _pdl_simplex_inclusion(small, large, dimension - 1)
            left = _tensor_matrix_multiply(boundary_large, include_high)
            right = _tensor_matrix_multiply(include_low, boundary_small)
            chain_rows.append((small, large, dimension, left == right))
    for first, second, third in zip(vertex_counts[:-2], vertex_counts[1:-1], vertex_counts[2:]):
        for dimension in range(5):
            direct = _pdl_simplex_inclusion(first, third, dimension)
            composed = _tensor_matrix_multiply(_pdl_simplex_inclusion(second, third, dimension), _pdl_simplex_inclusion(first, second, dimension))
            transitivity_rows.append((first, second, third, dimension, direct == composed))
    theorem_result = all(row[3] for row in chain_rows) and all(row[4] for row in transitivity_rows)
    return {
        'vertex_counts': vertex_counts,
        'chain_map_rows': tuple(chain_rows),
        'inclusion_transitivity_rows': tuple(transitivity_rows),
        'simplicial_inclusions_commute_with_boundary': all(row[3] for row in chain_rows),
        'simplicial_inclusions_are_transitive': all(row[4] for row in transitivity_rows),
        'theorem_result': theorem_result,
    }


def _pdl_lorentz_boost(half_parameter):
    parameter = Fraction(half_parameter)
    denominator = Fraction(1) - parameter * parameter
    gamma = (Fraction(1) + parameter * parameter) / denominator
    mixed = Fraction(2) * parameter / denominator
    return [
        [gamma, mixed, Fraction(0), Fraction(0)],
        [mixed, gamma, Fraction(0), Fraction(0)],
        [Fraction(0), Fraction(0), Fraction(1), Fraction(0)],
        [Fraction(0), Fraction(0), Fraction(0), Fraction(1)],
    ]


def _pdl_lorentz_compose_parameter(left, right):
    left = Fraction(left)
    right = Fraction(right)
    return (left + right) / (Fraction(1) + left * right)


def _pdl_lorentz_transport_packet():
    metric = [[Fraction(-1), Fraction(0), Fraction(0), Fraction(0)], [Fraction(0), Fraction(1), Fraction(0), Fraction(0)], [Fraction(0), Fraction(0), Fraction(1), Fraction(0)], [Fraction(0), Fraction(0), Fraction(0), Fraction(1)]]
    parameters = tuple(Fraction(1, DUAL + SHIFT + offset) for offset in range(1, 5))
    isometry_rows = []
    for parameter in parameters:
        boost = _pdl_lorentz_boost(parameter)
        isometry_rows.append((parameter, _tensor_matrix_multiply(_mtr_transpose(boost), _tensor_matrix_multiply(metric, boost)) == metric, _fraction_matrix_determinant(boost) == 1))
    composition_rows = []
    for left in parameters:
        for right in parameters:
            composed_parameter = _pdl_lorentz_compose_parameter(left, right)
            matrix_product = _tensor_matrix_multiply(_pdl_lorentz_boost(right), _pdl_lorentz_boost(left))
            composition_rows.append((left, right, composed_parameter, matrix_product == _pdl_lorentz_boost(composed_parameter)))
    total = Fraction(1, 2)
    first = Fraction(1, 5)
    second = (total - first) / (Fraction(1) - total * first)
    split_exact = _tensor_matrix_multiply(_pdl_lorentz_boost(second), _pdl_lorentz_boost(first)) == _pdl_lorentz_boost(total)
    causal_samples = ((Fraction(1), Fraction(0), Fraction(0), Fraction(0)), (Fraction(1), Fraction(1), Fraction(0), Fraction(0)), (Fraction(1), Fraction(2), Fraction(0), Fraction(0)))
    causal_rows = []
    boost = _pdl_lorentz_boost(parameters[0])
    for vector in causal_samples:
        before = _mtr_dot(vector, _mtr_matvec(metric, vector))
        transformed = tuple(_mtr_matvec(boost, vector))
        after = _mtr_dot(transformed, _mtr_matvec(metric, transformed))
        causal_rows.append((vector, before, after, before == after))
    theorem_result = all(row[1] and row[2] for row in isometry_rows) and all(row[3] for row in composition_rows) and split_exact and all(row[3] for row in causal_rows)
    return {
        'generated_half_parameters': parameters,
        'isometry_rows': tuple(isometry_rows),
        'composition_rows': tuple(composition_rows),
        'refinement_split': (total, first, second),
        'refinement_split_exact': split_exact,
        'causal_interval_rows': tuple(causal_rows),
        'rational_lorentz_groupoid_exact': theorem_result,
        'theorem_result': theorem_result,
    }


def _pdl_rotation(half_parameter):
    parameter = Fraction(half_parameter)
    denominator = Fraction(1) + parameter * parameter
    cosine = (Fraction(1) - parameter * parameter) / denominator
    sine = Fraction(2) * parameter / denominator
    return [[cosine, -sine], [sine, cosine]]


def _pdl_rotation_inverse(matrix):
    return _mtr_transpose(matrix)


def _pdl_vector_sub(left, right):
    return tuple(Fraction(a) - Fraction(b) for a, b in zip(left, right))


def _pdl_gauge_direct_system_packet():
    frame_parameters = tuple(Fraction(index, index + DUAL + SHIFT) for index in range(5))
    frames = tuple(_pdl_rotation(parameter) for parameter in frame_parameters)
    links = tuple(_tensor_matrix_multiply(frames[(index + 1) % len(frames)], _pdl_rotation_inverse(frames[index])) for index in range(len(frames)))
    base = (Fraction(1), Fraction(0))
    vacuum_fields = tuple(tuple(_mtr_matvec(frame, base)) for frame in frames)
    vacuum_residuals = tuple(_pdl_vector_sub(vacuum_fields[(index + 1) % len(frames)], tuple(_mtr_matvec(links[index], vacuum_fields[index]))) for index in range(len(frames)))
    holonomy = _mtr_identity(2)
    for link in links:
        holonomy = _tensor_matrix_multiply(link, holonomy)
    perturbed_fields = list(vacuum_fields)
    perturbed_fields[2] = _pdl_vector_sub(perturbed_fields[2], (Fraction(-1, 3), Fraction(1, 4)))
    perturbed_fields = tuple(perturbed_fields)
    residuals = tuple(_pdl_vector_sub(perturbed_fields[(index + 1) % len(frames)], tuple(_mtr_matvec(links[index], perturbed_fields[index]))) for index in range(len(frames)))
    action = sum((_mtr_norm_squared(residual) for residual in residuals), Fraction(0))
    local_parameters = tuple(Fraction(1, index + DUAL + SHIFT + 2) for index in range(len(frames)))
    local_frames = tuple(_pdl_rotation(parameter) for parameter in local_parameters)
    transformed_fields = tuple(tuple(_mtr_matvec(local_frames[index], perturbed_fields[index])) for index in range(len(frames)))
    transformed_links = tuple(_tensor_matrix_multiply(local_frames[(index + 1) % len(frames)], _tensor_matrix_multiply(links[index], _pdl_rotation_inverse(local_frames[index]))) for index in range(len(frames)))
    transformed_residuals = tuple(_pdl_vector_sub(transformed_fields[(index + 1) % len(frames)], tuple(_mtr_matvec(transformed_links[index], transformed_fields[index]))) for index in range(len(frames)))
    transformed_action = sum((_mtr_norm_squared(residual) for residual in transformed_residuals), Fraction(0))
    covariance_rows = tuple(transformed_residuals[index] == tuple(_mtr_matvec(local_frames[(index + 1) % len(frames)], residuals[index])) for index in range(len(frames)))
    coarse_link = links[0]
    intermediate = _pdl_rotation(Fraction(2, 7))
    left_refined = _tensor_matrix_multiply(intermediate, _pdl_rotation_inverse(frames[0]))
    right_refined = _tensor_matrix_multiply(frames[1], _pdl_rotation_inverse(intermediate))
    refinement_exact = _tensor_matrix_multiply(right_refined, left_refined) == coarse_link
    theorem_result = all(residual == (Fraction(0), Fraction(0)) for residual in vacuum_residuals) and holonomy == _mtr_identity(2) and action > 0 and transformed_action == action and all(covariance_rows) and refinement_exact
    return {
        'frame_parameters': frame_parameters,
        'vacuum_residuals': vacuum_residuals,
        'loop_holonomy': holonomy,
        'perturbed_action': action,
        'transformed_action': transformed_action,
        'covariant_residual_rows': covariance_rows,
        'local_gauge_action_invariant': transformed_action == action,
        'coarse_link_refinement_exact': refinement_exact,
        'theorem_result': theorem_result,
    }


def _pdl_dirac_ward_packet():
    levels = tuple(range(1, 5))
    rows = []
    for level in levels:
        edge_count = 2 ** level
        incidence = _pdl_path_incidence(edge_count)
        vertex_count = edge_count + 1
        zero_v = [[Fraction(0) for _ in range(vertex_count)] for _ in range(vertex_count)]
        zero_e = [[Fraction(0) for _ in range(edge_count)] for _ in range(edge_count)]
        top = [zero_v[row] + list(_mtr_transpose(incidence)[row]) for row in range(vertex_count)]
        bottom = [list(incidence[row]) + zero_e[row] for row in range(edge_count)]
        dirac = top + bottom
        chirality = [[Fraction(0) for _ in range(vertex_count + edge_count)] for _ in range(vertex_count + edge_count)]
        for index in range(vertex_count):
            chirality[index][index] = Fraction(1)
        for index in range(edge_count):
            chirality[vertex_count + index][vertex_count + index] = Fraction(-1)
        anticommutator = _fc_matrix_add(_tensor_matrix_multiply(chirality, dirac), _tensor_matrix_multiply(dirac, chirality))
        symmetric = _mtr_transpose(dirac) == dirac
        kernel_dimension = len(dirac) - fraction_rank(dirac)
        stiffness = _tensor_matrix_multiply(_mtr_transpose(incidence), incidence)
        constant = tuple(Fraction(1) for _ in range(vertex_count))
        source = tuple(Fraction(-1) if index == 0 else Fraction(1) if index == vertex_count - 1 else Fraction(0) for index in range(vertex_count))
        ward = tuple(_mtr_matvec(stiffness, constant)) == tuple(Fraction(0) for _ in range(vertex_count)) and _mtr_dot(constant, source) == 0
        system = [list(stiffness[row]) for row in range(vertex_count - 1)] + [[Fraction(1) for _ in range(vertex_count)]]
        rhs = list(source[:vertex_count - 1]) + [Fraction(0)]
        field = tuple(_fraction_linear_solve(system, rhs))
        equation_exact = tuple(_mtr_matvec(stiffness, field)) == source and sum(field, Fraction(0)) == 0
        rows.append((level, symmetric, all(value == 0 for row in anticommutator for value in row), kernel_dimension == 1, ward, equation_exact))
    theorem_result = all(all(row[index] for index in range(1, 6)) for row in rows)
    return {
        'levels': levels,
        'dirac_ward_rows': tuple(rows),
        'chiral_anticommutation_all_levels': all(row[2] for row in rows),
        'single_constant_zero_mode_all_levels': all(row[3] for row in rows),
        'ward_noether_identity_all_levels': all(row[4] for row in rows),
        'conserved_source_equation_all_levels': all(row[5] for row in rows),
        'theorem_result': theorem_result,
    }


def _pdl_matrix_power(matrix, power):
    result = _mtr_identity(len(matrix))
    for _ in range(power):
        result = _tensor_matrix_multiply(matrix, result)
    return result


def _pdl_quantum_projective_packet():
    primitive_half_parameter = Fraction(1, DUAL + SHIFT)
    rotation = _pdl_rotation(primitive_half_parameter)
    transition = [[value * value for value in row] for row in rotation]
    initial = (Fraction(1), Fraction(0))
    levels = tuple(range(1, 7))
    measures = {}
    previous = {tuple(): Fraction(1)}
    marginal_rows = []
    normalization_rows = []
    for level in levels:
        current = {}
        for path, weight in previous.items():
            state = 0 if not path else path[-1]
            for next_state in range(2):
                current[path + (next_state,)] = weight * transition[state][next_state]
        measures[level] = current
        normalization_rows.append((level, sum(current.values(), Fraction(0)) == 1))
        if level > 1:
            marginalized = {}
            for path, weight in current.items():
                prefix = path[:-1]
                marginalized[prefix] = marginalized.get(prefix, Fraction(0)) + weight
            marginal_rows.append((level, marginalized == measures[level - 1]))
        previous = current
    semigroup_rows = []
    for left in range(1, 5):
        for right in range(1, 5):
            semigroup_rows.append((left, right, _tensor_matrix_multiply(_pdl_matrix_power(transition, right), _pdl_matrix_power(transition, left)) == _pdl_matrix_power(transition, left + right)))
    reflection_values = []
    for left in range(-5, 6):
        for right in range(-5, 6):
            vector = (Fraction(left), Fraction(right))
            reflection_values.append(_mtr_dot(vector, _mtr_matvec(transition, vector)))
    theorem_result = all(row[1] for row in normalization_rows) and all(row[1] for row in marginal_rows) and all(row[2] for row in semigroup_rows) and all(value >= 0 for value in reflection_values)
    return {
        'primitive_half_parameter': primitive_half_parameter,
        'rational_rotation': rotation,
        'positive_transition': transition,
        'level_path_counts': tuple((level, len(measures[level])) for level in levels),
        'normalization_rows': tuple(normalization_rows),
        'marginal_rows': tuple(marginal_rows),
        'semigroup_rows': tuple(semigroup_rows),
        'reflection_minimum': min(reflection_values),
        'positive_projective_measure_direct_system_exact': theorem_result,
        'theorem_result': theorem_result,
    }


def _pdl_parent_four_readout_packet():
    frame = _mtr_four_readout_tight_frame()
    analysis = frame['analysis_matrix']
    levels = tuple(range(5))
    rows = []
    for level in levels:
        intervals = _pdl_uniform_intervals(level)
        history = _pdl_affine_source_at_nodes(level)
        parent_action = Fraction(0)
        projected_action = Fraction(0)
        reconstruction_exact = True
        metric_derivative_exact = True
        for edge, interval in enumerate(intervals):
            residual = _pdl_vector_sub(history[edge + 1], history[edge])
            parent_edge = _mtr_norm_squared(residual) / (Fraction(2) * interval)
            readout = tuple(_mtr_matvec(analysis, residual))
            projected_edge = Fraction(1, 16) * _mtr_norm_squared(readout) / interval
            parent_action += parent_edge
            projected_action += projected_edge
            reconstructed = tuple(Fraction(value, 8) for value in _mtr_matvec(_mtr_transpose(analysis), readout))
            reconstruction_exact = reconstruction_exact and reconstructed == residual
            parent_derivative = -_mtr_norm_squared(residual) / (Fraction(2) * interval * interval)
            projected_derivative = -Fraction(1, 16) * _mtr_norm_squared(readout) / (interval * interval)
            metric_derivative_exact = metric_derivative_exact and parent_derivative == projected_derivative
        stiffness = _pdl_stiffness(intervals)
        component_histories = _pdl_component_histories(history)
        parent_equations = tuple(tuple(_mtr_matvec(stiffness, component)) for component in component_histories)
        readout_history = tuple(tuple(_mtr_matvec(analysis, state)) for state in history)
        readout_components = tuple(tuple(readout_history[node][component] for node in range(len(history))) for component in range(8))
        projected_equations = tuple(tuple(_mtr_matvec(stiffness, component)) for component in readout_components)
        equation_commutes = True
        for node in range(len(history)):
            parent_at_node = tuple(parent_equations[component][node] for component in range(4))
            projected_at_node = tuple(projected_equations[component][node] for component in range(8))
            equation_commutes = equation_commutes and projected_at_node == tuple(_mtr_matvec(analysis, parent_at_node))
        rows.append((level, parent_action, projected_action, parent_action == projected_action, reconstruction_exact, metric_derivative_exact, equation_commutes))
    refinement_rows = []
    for coarse in levels[:-1]:
        fine = coarse + 1
        p = _pdl_prolongation(coarse, fine)
        coarse_history = _pdl_affine_source_at_nodes(coarse)
        fine_history = _pdl_affine_source_at_nodes(fine)
        coarse_readout = tuple(tuple(_mtr_matvec(analysis, state)) for state in coarse_history)
        fine_readout = tuple(tuple(_mtr_matvec(analysis, state)) for state in fine_history)
        reconstructed_components = []
        for component in range(8):
            coarse_component = tuple(coarse_readout[node][component] for node in range(len(coarse_readout)))
            reconstructed_components.append(tuple(_mtr_matvec(p, coarse_component)))
        reconstructed = tuple(tuple(reconstructed_components[component][node] for component in range(8)) for node in range(len(fine_readout)))
        refinement_rows.append((coarse, fine, reconstructed == fine_readout))
    theorem_result = all(row[3] and row[4] and row[5] and row[6] for row in rows) and all(row[2] for row in refinement_rows)
    return {
        'level_rows': tuple(rows),
        'readout_refinement_rows': tuple(refinement_rows),
        'parent_action_equals_four_readouts_all_levels': all(row[3] for row in rows),
        'joint_source_reconstruction_all_levels': all(row[4] for row in rows),
        'metric_variation_commutes_all_levels': all(row[5] for row in rows),
        'field_equation_projection_commutes_all_levels': all(row[6] for row in rows),
        'readout_refinement_naturality_exact': all(row[2] for row in refinement_rows),
        'theorem_result': theorem_result,
    }


