def _fds_execute_all_theorems_safe():
    worker_count = max(SHIFT, min(DUAL * DUAL, os.cpu_count() or SHIFT, len(THEOREM_ROOTS)))
    results = [None] * len(THEOREM_ROOTS)
    with tempfile.TemporaryDirectory(prefix='native_stepwise_safe_theorems_') as directory:
        for batch_start in range(0, len(THEOREM_ROOTS), worker_count):
            processes = []
            for index in range(batch_start, min(batch_start + worker_count, len(THEOREM_ROOTS))):
                output_path = os.path.join(directory, 'theorem_' + str(index).zfill(DUAL) + '.out')
                error_path = os.path.join(directory, 'theorem_' + str(index).zfill(DUAL) + '.err')
                output_handle = open(output_path, 'w', encoding='utf-8')
                error_handle = open(error_path, 'w', encoding='utf-8')
                process = subprocess.Popen([sys.executable, __file__, '--theorem-body', str(index)], stdout=output_handle, stderr=error_handle, text=True)
                output_handle.close()
                error_handle.close()
                processes.append((index, process, output_path, error_path))
            for index, process, output_path, error_path in processes:
                return_code = process.wait()
                if return_code != 0:
                    error_text = pathlib.Path(error_path).read_text(encoding='utf-8') if os.path.exists(error_path) else ''
                    raise RuntimeError('theorem ' + str(index + SHIFT) + ' failed: ' + error_text)
                results[index] = pathlib.Path(output_path).read_text(encoding='utf-8')
    if any(result is None for result in results):
        raise RuntimeError('safe theorem execution returned an incomplete result set')
    return tuple(result for result in results if result is not None)


