def _ucc_geometric_sum(ratio, last_index):
    ratio = Fraction(ratio)
    if last_index < 0:
        return Fraction(0)
    if ratio == 1:
        return Fraction(last_index + SHIFT)
    return (Fraction(1) - ratio ** (last_index + SHIFT)) / (Fraction(1) - ratio)


def _ucc_geometric_tail(ratio, first_index):
    ratio = Fraction(ratio)
    if not (Fraction(0) <= ratio < Fraction(1)):
        raise ValueError('the tail ratio must lie in the unit interval')
    return ratio ** first_index / (Fraction(1) - ratio)


def _ucc_vector_scale(scale, vector):
    scale = Fraction(scale)
    return tuple(scale * Fraction(value) for value in vector)


def _ucc_vector_add(left, right):
    return tuple(Fraction(a) + Fraction(b) for a, b in zip(left, right))


def _ucc_vector_sub(left, right):
    return tuple(Fraction(a) - Fraction(b) for a, b in zip(left, right))


def _ucc_vector_dot(left, right):
    return sum((Fraction(a) * Fraction(b) for a, b in zip(left, right)), Fraction(0))


def _ucc_vector_norm_squared(vector):
    return _ucc_vector_dot(vector, vector)


def _ucc_matrix_vector(matrix, vector):
    return tuple(sum((Fraction(value) * Fraction(vector[column]) for column, value in enumerate(row)), Fraction(0)) for row in matrix)


def _ucc_matrix_multiply(left, right):
    if not left or not right:
        return tuple()
    right_transpose = tuple(zip(*right))
    return tuple(tuple(sum((Fraction(a) * Fraction(b) for a, b in zip(row, column)), Fraction(0)) for column in right_transpose) for row in left)


def _ucc_matrix_transpose(matrix):
    return tuple(tuple(Fraction(value) for value in column) for column in zip(*matrix))


def _ucc_identity(size):
    return tuple(tuple(Fraction(1) if row == column else Fraction(0) for column in range(size)) for row in range(size))


def _ucc_energy_of_coefficients(coefficients, weight_base=DUAL):
    return sum((Fraction(weight_base) ** level * _ucc_vector_norm_squared(vector) for level, vector in enumerate(coefficients)), Fraction(0))


def _ucc_geometric_coefficient_family(last_level, seed=None, ratio=None):
    seed = seed or (Fraction(1), Fraction(-1), Fraction(1, DUAL), Fraction(1, DUAL + SHIFT))
    ratio = Fraction(ratio or Fraction(1, DUAL + SHIFT))
    return tuple(_ucc_vector_scale(ratio ** level, seed) for level in range(last_level + SHIFT))


def _ucc_weighted_energy_completion_packet():
    seed = (Fraction(1), Fraction(-1), Fraction(1, DUAL), Fraction(1, DUAL + SHIFT))
    ratio = Fraction(1, DUAL + SHIFT)
    energy_ratio = Fraction(DUAL) * ratio * ratio
    seed_energy = _ucc_vector_norm_squared(seed)
    infinite_energy = seed_energy / (Fraction(1) - energy_ratio)
    truncation_rows = []
    previous_energy = Fraction(-1)
    for level in range(D8 + SHIFT):
        coefficients = _ucc_geometric_coefficient_family(level, seed, ratio)
        energy = _ucc_energy_of_coefficients(coefficients)
        expected = seed_energy * _ucc_geometric_sum(energy_ratio, level)
        tail = infinite_energy - energy
        expected_tail = seed_energy * _ucc_geometric_tail(energy_ratio, level + SHIFT)
        monotone = previous_energy < energy if level > 0 else energy > 0
        truncation_rows.append((level, energy, expected, tail, expected_tail, energy == expected, tail == expected_tail, monotone))
        previous_energy = energy
    cauchy_rows = []
    for coarse in range(DUAL):
        for fine in range(coarse + SHIFT, D8 + SHIFT):
            difference_energy = seed_energy * sum((energy_ratio ** level for level in range(coarse + SHIFT, fine + SHIFT)), Fraction(0))
            tail_bound = seed_energy * _ucc_geometric_tail(energy_ratio, coarse + SHIFT)
            cauchy_rows.append((coarse, fine, difference_energy, tail_bound, difference_energy <= tail_bound))
    mismatch = _ucc_vector_add(seed, (Fraction(1), Fraction(0), Fraction(0), Fraction(0)))
    mismatch_distance = _ucc_vector_norm_squared(_ucc_vector_sub(mismatch, seed))
    theorem_result = (
        Fraction(0) < energy_ratio < Fraction(1)
        and all(row[5] and row[6] and row[7] for row in truncation_rows)
        and all(row[4] for row in cauchy_rows)
        and truncation_rows[-1][3] < truncation_rows[0][3]
        and mismatch_distance > 0
    )
    return {
        'seed': seed,
        'coefficient_ratio': ratio,
        'weighted_energy_ratio': energy_ratio,
        'seed_energy': seed_energy,
        'infinite_energy': infinite_energy,
        'truncation_rows': tuple(truncation_rows),
        'cauchy_rows': tuple(cauchy_rows),
        'finite_core_dense_by_exact_tail': all(row[6] for row in truncation_rows) and Fraction(0) < energy_ratio < Fraction(1),
        'completion_limit_unique': mismatch_distance > 0,
        'completion_is_positive_definite': seed_energy > 0 and mismatch_distance > 0,
        'theorem_result': theorem_result,
    }


def _ucc_four_readout_completion_packet():
    frame = _mtr_four_readout_tight_frame()
    analysis = tuple(tuple(Fraction(value) for value in row) for row in frame['analysis_matrix'])
    synthesis = tuple(tuple(Fraction(value, D8) for value in row) for row in _ucc_matrix_transpose(analysis))
    seed = (Fraction(1), Fraction(-1), Fraction(1, DUAL), Fraction(1, DUAL + SHIFT))
    ratio = Fraction(1, DUAL + SHIFT)
    source_energy_ratio = Fraction(DUAL) * ratio * ratio
    source_seed_energy = _ucc_vector_norm_squared(seed)
    source_infinite_energy = source_seed_energy / (Fraction(1) - source_energy_ratio)
    readout_seed = _ucc_matrix_vector(analysis, seed)
    readout_seed_energy = _ucc_vector_norm_squared(readout_seed)
    raw_readout_infinite_energy = readout_seed_energy / (Fraction(1) - source_energy_ratio)
    reconstruction = _ucc_matrix_vector(synthesis, readout_seed)
    level_rows = []
    for level in range(D8 + SHIFT):
        source_coefficients = _ucc_geometric_coefficient_family(level, seed, ratio)
        readout_coefficients = tuple(_ucc_matrix_vector(analysis, vector) for vector in source_coefficients)
        reconstructed = tuple(_ucc_matrix_vector(synthesis, vector) for vector in readout_coefficients)
        source_action = Fraction(1, DUAL) * _ucc_energy_of_coefficients(source_coefficients)
        projected_action = Fraction(1, DUAL * D8) * _ucc_energy_of_coefficients(readout_coefficients)
        level_rows.append((level, reconstructed == source_coefficients, source_action, projected_action, source_action == projected_action))
    theorem_result = (
        frame['tight_frame_exact']
        and reconstruction == seed
        and readout_seed_energy == D8 * source_seed_energy
        and raw_readout_infinite_energy == D8 * source_infinite_energy
        and all(row[1] and row[4] for row in level_rows)
    )
    return {
        'analysis_matrix': analysis,
        'synthesis_matrix': synthesis,
        'frame_operator': frame['frame_operator'],
        'source_infinite_energy': source_infinite_energy,
        'raw_readout_infinite_energy': raw_readout_infinite_energy,
        'reconstruction_exact': reconstruction == seed,
        'bounded_readout_norm_ratio': readout_seed_energy / source_seed_energy,
        'level_rows': tuple(level_rows),
        'one_parent_action_equals_four_completed_readout_actions': all(row[4] for row in level_rows),
        'four_readouts_extend_uniquely_to_energy_completion': theorem_result,
        'theorem_result': theorem_result,
    }


def _ucc_variational_gamma_completion_packet():
    source_seed = (Fraction(1, DUAL), Fraction(-1, DUAL + SHIFT), Fraction(1, G5), Fraction(-1, D8))
    ratio = Fraction(1, DUAL + SHIFT)
    energy_ratio = Fraction(DUAL) * ratio * ratio
    source_seed_energy = _ucc_vector_norm_squared(source_seed)
    infinite_source_energy = source_seed_energy / (Fraction(1) - energy_ratio)
    rows = []
    for level in range(D8 + SHIFT):
        source = _ucc_geometric_coefficient_family(level, source_seed, ratio)
        minimizer = source
        euler_residual = tuple(_ucc_vector_sub(state, forcing) for state, forcing in zip(minimizer, source))
        source_energy = _ucc_energy_of_coefficients(source)
        minimum_action = -Fraction(1, DUAL) * source_energy
        expected_minimum = -Fraction(1, DUAL) * source_seed_energy * _ucc_geometric_sum(energy_ratio, level)
        recovery_tail = infinite_source_energy - source_energy
        rows.append((level, all(all(value == 0 for value in residual) for residual in euler_residual), minimum_action, expected_minimum, recovery_tail, minimum_action == expected_minimum))
    perturbation = (Fraction(1), Fraction(0), Fraction(0), Fraction(0))
    perturbed_excess = Fraction(1, DUAL) * _ucc_vector_norm_squared(perturbation)
    limit_minimum = -Fraction(1, DUAL) * infinite_source_energy
    theorem_result = (
        all(row[1] and row[5] for row in rows)
        and rows[-1][4] < rows[0][4]
        and perturbed_excess > 0
        and rows[-1][2] > limit_minimum
    )
    return {
        'source_seed': source_seed,
        'source_infinite_energy': infinite_source_energy,
        'finite_minimizer_rows': tuple(rows),
        'limit_minimum_action': limit_minimum,
        'strict_perturbation_excess': perturbed_excess,
        'euler_lagrange_commutes_with_truncation': all(row[1] for row in rows),
        'quadratic_parent_actions_gamma_converge': theorem_result,
        'minimizers_converge_in_energy': rows[-1][4] < rows[0][4],
        'theorem_result': theorem_result,
    }


def _ucc_rational_rotation(parameter):
    parameter = Fraction(parameter)
    denominator = Fraction(1) + parameter * parameter
    cosine = (Fraction(1) - parameter * parameter) / denominator
    sine = Fraction(DUAL) * parameter / denominator
    return ((cosine, -sine), (sine, cosine))


def _ucc_block_diagonal_pair(matrix):
    zero = Fraction(0)
    return (
        (matrix[0][0], matrix[0][1], zero, zero),
        (matrix[1][0], matrix[1][1], zero, zero),
        (zero, zero, matrix[0][0], matrix[0][1]),
        (zero, zero, matrix[1][0], matrix[1][1]),
    )


def _ucc_bounded_covariant_extension_packet():
    rotation = _ucc_rational_rotation(Fraction(1, DUAL + SHIFT))
    gauge = _ucc_block_diagonal_pair(rotation)
    gauge_transpose_gauge = _ucc_matrix_multiply(_ucc_matrix_transpose(gauge), gauge)
    chirality = (
        (Fraction(1), Fraction(0), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(-1), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(1), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(0), Fraction(-1)),
    )
    seed = (Fraction(1), Fraction(2), Fraction(-1), Fraction(3))
    gauge_seed = _ucc_matrix_vector(gauge, seed)
    chirality_seed = _ucc_matrix_vector(chirality, seed)
    eta = (
        (Fraction(-1), Fraction(0), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(1), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(1), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(0), Fraction(1)),
    )
    boost = (
        (Fraction(5, 3), Fraction(4, 3), Fraction(0), Fraction(0)),
        (Fraction(4, 3), Fraction(5, 3), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(1), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(0), Fraction(1)),
    )
    boost_metric = _ucc_matrix_multiply(_ucc_matrix_transpose(boost), _ucc_matrix_multiply(eta, boost))
    causal_seed = (Fraction(2), Fraction(1), Fraction(1), Fraction(0))
    boosted_seed = _ucc_matrix_vector(boost, causal_seed)
    causal_before = _ucc_vector_dot(causal_seed, _ucc_matrix_vector(eta, causal_seed))
    causal_after = _ucc_vector_dot(boosted_seed, _ucc_matrix_vector(eta, boosted_seed))
    ratio = Fraction(1, DUAL + SHIFT)
    level_rows = []
    for level in range(D8 + SHIFT):
        coefficients = _ucc_geometric_coefficient_family(level, seed, ratio)
        gauge_coefficients = tuple(_ucc_matrix_vector(gauge, vector) for vector in coefficients)
        chirality_coefficients = tuple(_ucc_matrix_vector(chirality, vector) for vector in coefficients)
        level_rows.append((
            level,
            _ucc_energy_of_coefficients(gauge_coefficients) == _ucc_energy_of_coefficients(coefficients),
            _ucc_energy_of_coefficients(chirality_coefficients) == _ucc_energy_of_coefficients(coefficients),
        ))
    theorem_result = (
        gauge_transpose_gauge == _ucc_identity(4)
        and _ucc_vector_norm_squared(gauge_seed) == _ucc_vector_norm_squared(seed)
        and _ucc_vector_norm_squared(chirality_seed) == _ucc_vector_norm_squared(seed)
        and boost_metric == eta
        and causal_before == causal_after
        and all(row[1] and row[2] for row in level_rows)
    )
    return {
        'gauge_rotation': gauge,
        'gauge_isometry_exact': gauge_transpose_gauge == _ucc_identity(4),
        'chirality_isometry_exact': _ucc_vector_norm_squared(chirality_seed) == _ucc_vector_norm_squared(seed),
        'lorentz_boost': boost,
        'lorentz_metric_preserved': boost_metric == eta,
        'causal_bilinear_preserved': causal_before == causal_after,
        'level_rows': tuple(level_rows),
        'gauge_chirality_lorentz_extend_on_dense_core': theorem_result,
        'theorem_result': theorem_result,
    }


def _ucc_nonlinear_closure_completion_packet():
    ratio = Fraction(1, DUAL + SHIFT)
    seed = (Fraction(1), Fraction(2), Fraction(-1), Fraction(0))
    rotation = _ucc_block_diagonal_pair(_ucc_rational_rotation(ratio))
    seed_norm = _ucc_vector_norm_squared(seed)
    quartic_ratio = Fraction(1, DUAL) * ratio ** 4
    infinite_potential = seed_norm * seed_norm / (Fraction(1) - quartic_ratio)
    rows = []
    for level in range(D8 + SHIFT):
        potential = Fraction(0)
        rotated_potential = Fraction(0)
        for index in range(level + SHIFT):
            field = _ucc_vector_scale(ratio ** index, seed)
            rotated = _ucc_matrix_vector(rotation, field)
            weight = Fraction(1, DUAL) ** index
            potential += weight * _ucc_vector_norm_squared(field) ** DUAL
            rotated_potential += weight * _ucc_vector_norm_squared(rotated) ** DUAL
        expected = seed_norm * seed_norm * _ucc_geometric_sum(quartic_ratio, level)
        tail = infinite_potential - potential
        rows.append((level, potential, expected, rotated_potential, tail, potential == expected == rotated_potential))
    theorem_result = Fraction(0) < quartic_ratio < Fraction(1) and all(row[5] for row in rows) and rows[-1][4] < rows[0][4]
    return {
        'quartic_ratio': quartic_ratio,
        'infinite_quartic_closure_potential': infinite_potential,
        'truncation_rows': tuple(rows),
        'nonlinear_potential_gauge_invariant': all(row[1] == row[3] for row in rows),
        'nonlinear_potential_converges': rows[-1][4] < rows[0][4],
        'theorem_result': theorem_result,
    }


def _ucc_markov_path_measure_packet():
    rotation = _ucc_rational_rotation(Fraction(1, DUAL + SHIFT))
    transition = tuple(tuple(value * value for value in row) for row in rotation)
    initial = (Fraction(1, DUAL), Fraction(1, DUAL))
    path_levels = {}
    consistency_rows = []
    for length in range(SHIFT, D8 + SHIFT):
        paths = {}
        for path in itertools.product(range(DUAL), repeat=length):
            weight = initial[path[0]]
            for index in range(length - SHIFT):
                weight *= transition[path[index]][path[index + SHIFT]]
            paths[path] = weight
        path_levels[length] = paths
        normalized = sum(paths.values(), Fraction(0)) == 1
        positive = all(weight >= 0 for weight in paths.values())
        marginal_exact = True
        if length > SHIFT:
            previous = path_levels[length - SHIFT]
            for prefix, previous_weight in previous.items():
                marginal = sum((weight for path, weight in paths.items() if path[:-1] == prefix), Fraction(0))
                marginal_exact = marginal_exact and marginal == previous_weight
        consistency_rows.append((length, len(paths), normalized, positive, marginal_exact))
    semigroup = _ucc_matrix_multiply(transition, transition)
    two_step_direct = tuple(tuple(sum((transition[row][middle] * transition[middle][column] for middle in range(DUAL)), Fraction(0)) for column in range(DUAL)) for row in range(DUAL))
    reflection_vectors = tuple(itertools.product(range(-DUAL, DUAL + SHIFT), repeat=DUAL))
    reflection_rows = []
    for vector in reflection_vectors:
        value = _ucc_vector_dot(vector, _ucc_matrix_vector(transition, vector))
        reflection_rows.append((vector, value, value >= 0))
    theorem_result = (
        all(sum(row, Fraction(0)) == 1 for row in transition)
        and all(row[2] and row[3] and row[4] for row in consistency_rows)
        and semigroup == two_step_direct
        and all(row[2] for row in reflection_rows)
    )
    return {
        'transition_kernel': transition,
        'path_level_rows': tuple(consistency_rows),
        'transition_semigroup_exact': semigroup == two_step_direct,
        'reflection_rows': tuple(reflection_rows),
        'positive_normalized_projective_premeasure': all(row[2] and row[3] and row[4] for row in consistency_rows),
        'finite_alphabet_cylinder_extension_unique_on_generated_sigma_class': theorem_result,
        'theorem_result': theorem_result,
    }


def _ucc_piecewise_affine_density_packet():
    rows = []
    for level in range(D8 + SHIFT):
        interval_count = DUAL ** level
        derivative_error_one_component = Fraction(1, ROUTE_TRIPLET * interval_count * interval_count)
        four_component_error = ROUTE_TRIPLET + SHIFT
        four_component_error *= derivative_error_one_component
        rows.append((level, interval_count, derivative_error_one_component, four_component_error))
    ratio_rows = []
    for index in range(len(rows) - SHIFT):
        ratio_rows.append((rows[index][0], rows[index + SHIFT][0], rows[index][3] / rows[index + SHIFT][3]))
    theorem_result = all(row[2] == DUAL * DUAL for row in ratio_rows) and rows[-1][3] < rows[0][3]
    return {
        'test_field': 'four component quadratic coordinate field on the unit four cube',
        'error_rows': tuple(rows),
        'refinement_ratio_rows': tuple(ratio_rows),
        'piecewise_affine_energy_error_second_order': all(row[2] == DUAL * DUAL for row in ratio_rows),
        'dense_core_constructive_for_declared_polynomial_and_energy_closure_class': theorem_result,
        'theorem_result': theorem_result,
    }


