# BEGIN COMPACT SMOOTH COVARIANT REPRESENTATION THEOREM

def _scr_poly_clean(poly):
    return {tuple(power): Fraction(value) for power, value in poly.items() if Fraction(value) != 0}


def _scr_poly_constant(value):
    value = Fraction(value)
    return {} if value == 0 else {(0, 0, 0, 0): value}


def _scr_poly_variable(axis):
    power = [0, 0, 0, 0]
    power[axis] = 1
    return {tuple(power): Fraction(1)}


def _scr_poly_add(left, right):
    result = dict(left)
    for power, value in right.items():
        result[power] = result.get(power, Fraction(0)) + Fraction(value)
    return _scr_poly_clean(result)


def _scr_poly_sub(left, right):
    return _scr_poly_add(left, {power: -Fraction(value) for power, value in right.items()})


def _scr_poly_scale(scale, poly):
    scale = Fraction(scale)
    return _scr_poly_clean({power: scale * Fraction(value) for power, value in poly.items()})


def _scr_poly_mul(left, right):
    result = {}
    for power_left, value_left in left.items():
        for power_right, value_right in right.items():
            power = tuple(a + b for a, b in zip(power_left, power_right))
            result[power] = result.get(power, Fraction(0)) + Fraction(value_left) * Fraction(value_right)
    return _scr_poly_clean(result)


def _scr_poly_pow(poly, exponent):
    exponent = int(exponent)
    result = _scr_poly_constant(1)
    base = dict(poly)
    while exponent:
        if exponent % 2:
            result = _scr_poly_mul(result, base)
        base = _scr_poly_mul(base, base)
        exponent //= 2
    return result


def _scr_poly_derivative(poly, axis):
    result = {}
    for power, value in poly.items():
        if power[axis] == 0:
            continue
        reduced = list(power)
        factor = reduced[axis]
        reduced[axis] -= 1
        result[tuple(reduced)] = result.get(tuple(reduced), Fraction(0)) + Fraction(factor) * Fraction(value)
    return _scr_poly_clean(result)


def _scr_poly_integral_unit(poly):
    total = Fraction(0)
    for power, value in poly.items():
        denominator = Fraction(1)
        for exponent in power:
            denominator *= exponent + 1
        total += Fraction(value) / denominator
    return total


def _scr_poly_evaluate(poly, point):
    total = Fraction(0)
    for power, value in poly.items():
        term = Fraction(value)
        for coordinate, exponent in zip(point, power):
            term *= Fraction(coordinate) ** exponent
        total += term
    return total


def _scr_poly_compose(poly, substitutions):
    result = _scr_poly_constant(0)
    for power, value in poly.items():
        term = _scr_poly_constant(value)
        for axis, exponent in enumerate(power):
            if exponent:
                term = _scr_poly_mul(term, _scr_poly_pow(substitutions[axis], exponent))
        result = _scr_poly_add(result, term)
    return _scr_poly_clean(result)


def _scr_falling(value, order):
    result = 1
    for offset in range(order):
        result *= value - offset
    return result


def _scr_factorial(value):
    result = 1
    for entry in range(2, value + 1):
        result *= entry
    return result


def _scr_binomial(n, k):
    if k < 0 or k > n:
        return 0
    return _scr_factorial(n) // (_scr_factorial(k) * _scr_factorial(n - k))


def _scr_geometric_derivative_tail(ratio, start, order):
    ratio = Fraction(ratio)
    start = int(start)
    order = int(order)
    total = Fraction(0)
    for k in range(order + 1):
        total += Fraction(_scr_binomial(order, k) * _scr_falling(start, order - k) * _scr_factorial(k)) * ratio ** k / (Fraction(1) - ratio) ** (k + 1)
    return ratio ** start * total


def _scr_analytic_smooth_core_packet():
    ratio = Fraction(1, ROUTE_TRIPLET)
    derivative_orders = tuple(range(9))
    truncation_levels = tuple(range(9))
    tail_rows = []
    monotone_rows = []
    for order in derivative_orders:
        tails = []
        for truncation in truncation_levels:
            start = truncation + 1
            tail = _scr_geometric_derivative_tail(ratio, start, order)
            tails.append(tail)
            finite_check = sum((Fraction(_scr_falling(index, order)) * ratio ** index for index in range(start, start + 16)), Fraction(0))
            remainder = _scr_geometric_derivative_tail(ratio, start + 16, order)
            tail_rows.append((order, truncation, tail, finite_check + remainder, tail == finite_check + remainder))
        eventual_start = 2 * order
        eventual = tuple(_scr_geometric_derivative_tail(ratio, start + 1, order) < _scr_geometric_derivative_tail(ratio, start, order) for start in range(max(1, eventual_start), max(1, eventual_start) + 8))
        monotone_rows.append((order, eventual_start, all(eventual)))
    components = []
    variables = tuple(_scr_poly_variable(axis) for axis in range(4))
    for component in range(4):
        truncations = []
        for degree in range(7):
            poly = _scr_poly_constant(0)
            for power in range(degree + 1):
                poly = _scr_poly_add(poly, _scr_poly_scale(Fraction(component + 1) * ratio ** power, _scr_poly_pow(variables[component], power)))
            truncations.append(poly)
        components.append(tuple(truncations))
    nested_exact = all(
        all(
            all(components[component][degree].get(power, Fraction(0)) == value for power, value in components[component][degree - 1].items())
            for degree in range(1, 7)
        )
        for component in range(4)
    )
    theorem_result = all(row[4] for row in tail_rows) and all(row[2] for row in monotone_rows) and nested_exact
    return {
        'ratio': ratio,
        'derivative_tail_rows': tuple(tail_rows),
        'eventual_monotone_rows': tuple(monotone_rows),
        'component_truncations': tuple(components),
        'all_derivative_tail_formulas_exact': all(row[4] for row in tail_rows),
        'every_fixed_derivative_tail_eventually_contracts': all(row[2] for row in monotone_rows),
        'finite_polynomial_core_nested': nested_exact,
        'rational_analytic_limit_is_c_infinity_on_unit_four_cube': all(row[4] for row in tail_rows) and all(row[2] for row in monotone_rows),
        'theorem_result': theorem_result,
    }


def _scr_affine_atlas_gluing_packet():
    variables = tuple(_scr_poly_variable(axis) for axis in range(4))
    one = _scr_poly_constant(1)
    field = _scr_poly_add(
        _scr_poly_add(
            _scr_poly_add(_scr_poly_add(one, _scr_poly_scale(2, variables[0])), _scr_poly_scale(3, variables[1])),
            _scr_poly_add(_scr_poly_scale(4, variables[2]), _scr_poly_scale(5, variables[3])),
        ),
        _scr_poly_add(_scr_poly_mul(variables[0], variables[1]), _scr_poly_mul(variables[2], variables[3])),
    )
    inverse_substitution = (
        _scr_poly_sub(one, variables[0]),
        variables[2],
        variables[1],
        variables[3],
    )
    forward_substitution = inverse_substitution
    field_chart_b = _scr_poly_compose(field, inverse_substitution)
    field_back_in_chart_a = _scr_poly_compose(field_chart_b, forward_substitution)
    chart_roundtrip_exact = field_back_in_chart_a == field
    jacobian_inverse = (
        (Fraction(-1), Fraction(0), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(1), Fraction(0)),
        (Fraction(0), Fraction(1), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(0), Fraction(1)),
    )
    gradient_a_in_b = tuple(_scr_poly_compose(_scr_poly_derivative(field, axis), inverse_substitution) for axis in range(4))
    gradient_b = tuple(_scr_poly_derivative(field_chart_b, axis) for axis in range(4))
    expected_gradient_b = []
    for y_axis in range(4):
        expected = _scr_poly_constant(0)
        for x_axis in range(4):
            expected = _scr_poly_add(expected, _scr_poly_scale(jacobian_inverse[x_axis][y_axis], gradient_a_in_b[x_axis]))
        expected_gradient_b.append(expected)
    chain_rule_exact = tuple(expected_gradient_b) == gradient_b
    chi_a = _scr_poly_sub(one, variables[0])
    chi_b = variables[0]
    partition_sum = _scr_poly_add(chi_a, chi_b)
    glued = _scr_poly_add(_scr_poly_mul(chi_a, field), _scr_poly_mul(chi_b, field_back_in_chart_a))
    partition_of_unity_exact = partition_sum == one and glued == field
    eta = [[Fraction(-1 if row == 0 and column == 0 else int(row == column)) for column in range(4)] for row in range(4)]
    jacobian = [list(row) for row in jacobian_inverse]
    metric_pullback = _tensor_matrix_multiply(_mtr_transpose(jacobian), _tensor_matrix_multiply(eta, jacobian))
    metric_exact = metric_pullback == eta
    test_points = tuple((Fraction(a, 4), Fraction(b, 4), Fraction(c, 4), Fraction(d, 4)) for a in range(5) for b in range(5) for c in range(5) for d in range(5))
    value_rows = []
    for point in test_points:
        mapped = (Fraction(1) - point[0], point[2], point[1], point[3])
        value_rows.append((_scr_poly_evaluate(field, point), _scr_poly_evaluate(field_chart_b, mapped), _scr_poly_evaluate(field, point) == _scr_poly_evaluate(field_chart_b, mapped)))
    theorem_result = chart_roundtrip_exact and chain_rule_exact and partition_of_unity_exact and metric_exact and all(row[2] for row in value_rows)
    return {
        'chart_a_field': field,
        'chart_b_field': field_chart_b,
        'chart_roundtrip_exact': chart_roundtrip_exact,
        'chain_rule_exact': chain_rule_exact,
        'partition_of_unity_gluing_exact': partition_of_unity_exact,
        'lorentz_metric_affine_atlas_invariant': metric_exact,
        'grid_value_rows': tuple(value_rows),
        'all_overlap_values_exact': all(row[2] for row in value_rows),
        'theorem_result': theorem_result,
    }


def _scr_epsilon(left, middle, right):
    if len({left, middle, right}) < 3:
        return 0
    permutation = (left, middle, right)
    inversions = sum(1 for i in range(3) for j in range(i + 1, 3) if permutation[i] > permutation[j])
    return -1 if inversions % 2 else 1


def _scr_color_add(left, right):
    return tuple(_scr_poly_add(a, b) for a, b in zip(left, right))


def _scr_color_scale(scale, vector):
    return tuple(_scr_poly_scale(scale, entry) for entry in vector)


def _scr_color_cross(left, right):
    result = []
    for color in range(3):
        entry = _scr_poly_constant(0)
        for a in range(3):
            for b in range(3):
                sign = _scr_epsilon(color, a, b)
                if sign:
                    entry = _scr_poly_add(entry, _scr_poly_scale(sign, _scr_poly_mul(left[a], right[b])))
        result.append(entry)
    return tuple(result)


def _scr_color_derivative(vector, axis):
    return tuple(_scr_poly_derivative(entry, axis) for entry in vector)


def _scr_nonabelian_smooth_curvature_packet():
    x = tuple(_scr_poly_variable(axis) for axis in range(4))
    zero = _scr_poly_constant(0)
    connection = (
        (x[1], x[2], zero),
        (zero, x[0], x[3]),
        (x[3], zero, x[0]),
        (x[2], x[1], zero),
    )
    curvature = {}
    for mu in range(4):
        for nu in range(mu + 1, 4):
            derivative = _scr_color_add(_scr_color_derivative(connection[nu], mu), _scr_color_scale(-1, _scr_color_derivative(connection[mu], nu)))
            curvature[(mu, nu)] = _scr_color_add(derivative, _scr_color_cross(connection[mu], connection[nu]))
    def oriented_curvature(mu, nu):
        if mu < nu:
            return curvature[(mu, nu)]
        return _scr_color_scale(-1, curvature[(nu, mu)])
    def covariant_derivative(axis, vector):
        return _scr_color_add(_scr_color_derivative(vector, axis), _scr_color_cross(connection[axis], vector))
    bianchi_rows = []
    for mu, nu, rho in itertools.combinations(range(4), 3):
        cyclic = _scr_color_add(
            _scr_color_add(covariant_derivative(mu, oriented_curvature(nu, rho)), covariant_derivative(nu, oriented_curvature(rho, mu))),
            covariant_derivative(rho, oriented_curvature(mu, nu)),
        )
        exact = all(not component for component in cyclic)
        bianchi_rows.append((mu, nu, rho, cyclic, exact))
    action = Fraction(0)
    for field_strength in curvature.values():
        for component in field_strength:
            action += Fraction(1, 4) * _scr_poly_integral_unit(_scr_poly_mul(component, component))
    rotation = (
        (Fraction(3, 5), Fraction(-4, 5), Fraction(0)),
        (Fraction(4, 5), Fraction(3, 5), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(1)),
    )
    def rotate(vector):
        result = []
        for row in rotation:
            entry = _scr_poly_constant(0)
            for coefficient, component in zip(row, vector):
                entry = _scr_poly_add(entry, _scr_poly_scale(coefficient, component))
            result.append(entry)
        return tuple(result)
    rotated_connection = tuple(rotate(vector) for vector in connection)
    rotated_curvature = {}
    for mu in range(4):
        for nu in range(mu + 1, 4):
            derivative = _scr_color_add(_scr_color_derivative(rotated_connection[nu], mu), _scr_color_scale(-1, _scr_color_derivative(rotated_connection[mu], nu)))
            rotated_curvature[(mu, nu)] = _scr_color_add(derivative, _scr_color_cross(rotated_connection[mu], rotated_connection[nu]))
    curvature_covariant = all(rotated_curvature[key] == rotate(value) for key, value in curvature.items())
    rotated_action = Fraction(0)
    for field_strength in rotated_curvature.values():
        for component in field_strength:
            rotated_action += Fraction(1, 4) * _scr_poly_integral_unit(_scr_poly_mul(component, component))
    rotation_orthogonal = _tensor_matrix_multiply(_mtr_transpose(rotation), rotation) == _mtr_identity(3)
    theorem_result = all(row[4] for row in bianchi_rows) and action > 0 and rotation_orthogonal and curvature_covariant and rotated_action == action
    return {
        'connection': connection,
        'curvature': curvature,
        'bianchi_rows': tuple(bianchi_rows),
        'nonabelian_bianchi_identity_exact': all(row[4] for row in bianchi_rows),
        'yang_mills_action': action,
        'global_adjoint_rotation_orthogonal': rotation_orthogonal,
        'curvature_adjoint_covariance_exact': curvature_covariant,
        'rotated_yang_mills_action': rotated_action,
        'yang_mills_action_invariant': rotated_action == action,
        'theorem_result': theorem_result,
    }


def _scr_rat(num, den=None):
    den = _scr_poly_constant(1) if den is None else den
    return (_scr_poly_clean(num), _scr_poly_clean(den))


def _scr_rat_add(left, right):
    return _scr_rat(_scr_poly_add(_scr_poly_mul(left[0], right[1]), _scr_poly_mul(right[0], left[1])), _scr_poly_mul(left[1], right[1]))


def _scr_rat_scale(scale, value):
    return _scr_rat(_scr_poly_scale(scale, value[0]), value[1])


def _scr_rat_mul(left, right):
    return _scr_rat(_scr_poly_mul(left[0], right[0]), _scr_poly_mul(left[1], right[1]))


def _scr_rat_derivative(value, axis):
    numerator = _scr_poly_sub(_scr_poly_mul(_scr_poly_derivative(value[0], axis), value[1]), _scr_poly_mul(value[0], _scr_poly_derivative(value[1], axis)))
    denominator = _scr_poly_mul(value[1], value[1])
    return _scr_rat(numerator, denominator)


def _scr_rat_equal(left, right):
    return _scr_poly_mul(left[0], right[1]) == _scr_poly_mul(right[0], left[1])


def _scr_rat_zero(value):
    return not value[0]


def _scr_smooth_lorentz_gravity_packet():
    one = _scr_poly_constant(1)
    time = _scr_poly_variable(0)
    scale = _scr_poly_add(one, time)
    scale_squared = _scr_poly_mul(scale, scale)
    scale_sixth = _scr_poly_pow(scale, 6)
    hubble = _scr_rat(one, scale)
    density = _scr_rat(_scr_poly_constant(3), scale_squared)
    pressure = _scr_rat(_scr_poly_constant(-1), scale_squared)
    conservation = _scr_rat_add(_scr_rat_derivative(density, 0), _scr_rat_scale(3, _scr_rat_mul(hubble, _scr_rat_add(density, pressure))))
    ricci_scalar = _scr_rat(_scr_poly_constant(6), scale_squared)
    spatial_einstein = _scr_rat(_scr_poly_constant(-1))
    pressure_times_metric = _scr_rat_mul(pressure, _scr_rat(scale_squared))
    spatial_equation_exact = _scr_rat_equal(spatial_einstein, pressure_times_metric)
    samples = tuple(Fraction(index, 8) for index in range(9))
    signature_rows = []
    for sample in samples:
        a_value = _scr_poly_evaluate(scale, (sample, Fraction(0), Fraction(0), Fraction(0)))
        metric = (Fraction(-1), a_value * a_value, a_value * a_value, a_value * a_value)
        determinant = -a_value ** 6
        signature_rows.append((sample, a_value, metric, determinant, metric[0] < 0 and all(value > 0 for value in metric[1:]) and determinant < 0))
    refinement_rows = []
    for level in range(6):
        denominator = 2 ** level
        nodes = tuple(Fraction(index, denominator) for index in range(denominator + 1))
        values = tuple(Fraction(1) + node for node in nodes)
        midpoint_exact = all((values[index] + values[index + 1]) / 2 == Fraction(1) + (nodes[index] + nodes[index + 1]) / 2 for index in range(len(nodes) - 1))
        refinement_rows.append((level, len(nodes), midpoint_exact))
    theorem_result = _scr_rat_zero(conservation) and spatial_equation_exact and all(row[4] for row in signature_rows) and all(row[2] for row in refinement_rows) and not _scr_rat_zero(ricci_scalar)
    return {
        'scale_factor': scale,
        'metric_determinant_polynomial': _scr_poly_scale(-1, scale_sixth),
        'hubble': hubble,
        'density': density,
        'pressure': pressure,
        'ricci_scalar': ricci_scalar,
        'perfect_fluid_conservation_exact': _scr_rat_zero(conservation),
        'spatial_einstein_equation_exact': spatial_equation_exact,
        'signature_rows': signature_rows,
        'lorentz_signature_nondegenerate_all_samples': all(row[4] for row in signature_rows),
        'affine_scale_refinement_rows': tuple(refinement_rows),
        'metric_refinement_exact': all(row[2] for row in refinement_rows),
        'nonflat_curvature_exact': not _scr_rat_zero(ricci_scalar),
        'theorem_result': theorem_result,
    }


def _scr_weak_parent_four_readout_packet():
    ratio = Fraction(1, ROUTE_TRIPLET)
    frame = _mtr_four_readout_tight_frame()
    analysis = frame['analysis_matrix']
    transpose = _mtr_transpose(analysis)
    rows = []
    total_parent = Fraction(0)
    total_projected = Fraction(0)
    for level in range(10):
        coefficient = tuple(Fraction(component + 1) * ratio ** level for component in range(4))
        weight = Fraction((level + 1) ** 2)
        source = tuple(weight * value for value in coefficient)
        euler = tuple(weight * value - source[index] for index, value in enumerate(coefficient))
        readout = tuple(_mtr_matvec(analysis, coefficient))
        reconstructed = tuple(Fraction(value, 8) for value in _mtr_matvec(transpose, readout))
        parent = Fraction(1, 2) * weight * _mtr_norm_squared(coefficient)
        projected = Fraction(1, 16) * weight * _mtr_norm_squared(readout)
        total_parent += parent
        total_projected += projected
        test = tuple(Fraction((level + 1) * (index + 1), index + 2) for index in range(4))
        weak_residual = _mtr_dot(euler, test)
        rows.append((level, coefficient, source, euler, reconstructed, parent, projected, weak_residual, euler == (Fraction(0),) * 4 and reconstructed == coefficient and parent == projected and weak_residual == 0))
    tail_bounds = []
    for truncation in range(8):
        tail = sum((Fraction((level + 1) ** 2) * sum((Fraction(component + 1) ** 2 for component in range(4)), Fraction(0)) * ratio ** (2 * level) / 2 for level in range(truncation + 1, truncation + 41)), Fraction(0))
        remainder_ratio = ratio * ratio
        next_level = truncation + 41
        rough_remainder = Fraction(30) * Fraction((next_level + 1) ** 2) * ratio ** (2 * next_level) / (Fraction(1) - remainder_ratio) ** 3
        tail_bounds.append((truncation, tail, rough_remainder, tail + rough_remainder))
    theorem_result = all(row[8] for row in rows) and total_parent == total_projected and all(tail_bounds[index + 1][3] < tail_bounds[index][3] for index in range(len(tail_bounds) - 1))
    return {
        'level_rows': tuple(rows),
        'weak_euler_lagrange_exact_all_levels': all(row[3] == (Fraction(0),) * 4 and row[7] == 0 for row in rows),
        'four_readout_reconstruction_exact_all_levels': all(row[4] == row[1] for row in rows),
        'parent_action_equals_four_projected_actions_all_levels': all(row[5] == row[6] for row in rows),
        'total_parent_action': total_parent,
        'total_projected_action': total_projected,
        'tail_bound_rows': tuple(tail_bounds),
        'energy_tail_contracts': all(tail_bounds[index + 1][3] < tail_bounds[index][3] for index in range(len(tail_bounds) - 1)),
        'theorem_result': theorem_result,
    }


def _scr_target_representation_packet(packets):
    previous = _universal_covariant_energy_completion_theorem()
    previous_status = {number: status for number, _, status in previous['targets']['ordered_targets']}
    target_names = {number: name for number, name, _ in previous['targets']['ordered_targets']}
    bridge = {
        1: ('atlas',),
        2: ('gravity',),
        3: ('analytic', 'variation'),
        4: ('atlas', 'analytic'),
        5: ('previous',),
        6: ('gauge',),
        7: ('gauge', 'variation'),
        8: ('variation',),
        9: ('previous',),
        10: ('analytic', 'previous'),
        11: ('variation',),
        12: ('analytic', 'variation'),
        13: ('gauge', 'previous'),
        14: ('previous',),
        15: ('gravity',),
        16: ('atlas',),
        17: ('gravity', 'variation'),
        18: ('gravity', 'variation'),
        19: ('atlas', 'previous'),
        20: ('variation',),
        21: ('previous',),
        22: ('previous',),
    }
    packet_status = {
        'analytic': packets['analytic']['theorem_result'],
        'atlas': packets['atlas']['theorem_result'],
        'gauge': packets['gauge']['theorem_result'],
        'gravity': packets['gravity']['theorem_result'],
        'variation': packets['variation']['theorem_result'],
        'previous': previous['theorem_result'],
    }
    ordered = []
    strengthened = []
    for number in GLOBAL_TARGET_ORDER:
        names = bridge[number]
        status = previous_status[number] and all(packet_status[name] for name in names)
        ordered.append((number, target_names[number], names, status))
        if any(name != 'previous' for name in names):
            strengthened.append(number)
    return {
        'ordered_targets': tuple(ordered),
        'compact_smooth_target_count': sum(1 for _, _, _, status in ordered if status),
        'compact_smooth_target_total': len(ordered),
        'smoothly_strengthened_targets': tuple(strengthened),
        'smoothly_strengthened_target_count': len(strengthened),
        'all_twenty_two_receive_compact_smooth_objects': all(status for _, _, _, status in ordered),
        'unrestricted_global_completion_count': 0,
        'unrestricted_global_completion_total': len(ordered),
        'theorem_result': all(status for _, _, _, status in ordered) and len(strengthened) >= 11,
    }


def _compact_smooth_covariant_representation_theorem():
    packets = {
        'analytic': _scr_analytic_smooth_core_packet(),
        'atlas': _scr_affine_atlas_gluing_packet(),
        'gauge': _scr_nonabelian_smooth_curvature_packet(),
        'gravity': _scr_smooth_lorentz_gravity_packet(),
        'variation': _scr_weak_parent_four_readout_packet(),
    }
    targets = _scr_target_representation_packet(packets)
    theorem_result = all(packet['theorem_result'] for packet in packets.values()) and targets['theorem_result']
    return {
        'definition': 'The compact smooth native class consists of rational analytic event-residual fields on the unit oriented four-cube, glued by exact affine Lorentz-compatible atlas maps, equipped with polynomial nonabelian connections, a nondegenerate smooth Lorentz metric, and the weak parent action reconstructed by four jointly complete readouts.',
        'packets': packets,
        'targets': targets,
        'theorem_result': theorem_result,
        'scope': 'Exact compact rational-analytic smooth representation and weak variational theorem on the declared unit-four-cube atlas class; not an unrestricted theorem for every smooth four-manifold, every interacting continuum quantum field measure, the continuum Yang-Mills mass gap, every nonlinear Einstein solution, or every physical observable decoder.',
    }


