    lines.append('LORENTZ_SIGNATURE_NONDEGENERATE_ALL_SAMPLES = ' + str(gravity['lorentz_signature_nondegenerate_all_samples']))
    lines.append('NONFLAT_CURVATURE_EXACT = ' + str(gravity['nonflat_curvature_exact']))
