    lines.append('UNRESTRICTED_GLOBAL_COMPLETION_COUNT = ' + str(targets['unrestricted_global_completion_count']) + '/' + str(targets['unrestricted_global_completion_total']))
    lines.append('COMPACT_SMOOTH_COVARIANT_REPRESENTATION_THEOREM = ' + str(theorem['theorem_result']))
    lines.append('SCOPE. ' + theorem['scope'])
    return '\n'.join(lines)

