    lines.append('STEP 5. Use a symmetric positive transition kernel. Cylinder weights are positive, normalized, marginally consistent, and invariant under the local two-state relabeling, so the projective path premeasure descends across the cover.')
    lines.append('CHART_RELABELING_INVARIANCE = ' + str(measure['chart_relabeling_invariance']))
    lines.append('POSITIVE_NORMALIZED_PROJECTIVE_FAMILY = ' + str(measure['positive_normalized_projective_family']))
    lines.append('CYLINDER_MEASURE_CHART_GLUING_EXACT = ' + str(measure['cylinder_measure_chart_gluing_exact']))
