    lines.append('NO_UNIFORM_POSITIVE_LOWER_BOUND = ' + str(gap['no_uniform_positive_lower_bound']))
    lines.append('UNIFORM_CONTINUUM_GAP_AXIOM_NECESSARY = ' + str(gap['uniform_continuum_gap_axiom_necessary']))
    lines.append('STEP 5. Solve the same zero-residual weak equation with two distinct global constant fields. Both have zero action and satisfy every local stationary equation, so a global causal boundary or initial selector is necessary for a unique physical solution.')
    lines.append('GLOBAL_SOLUTION_ONE = ' + str(boundary['solution_one']))
    lines.append('GLOBAL_SOLUTION_TWO = ' + str(boundary['solution_two']))
    lines.append('BOTH_STATIONARY_ZERO_ACTION = ' + str(boundary['both_stationary_zero_action']))
