def _separable_dot(left, right):
    return sum((a * b for a, b in zip(left, right)), Fraction(0, 1))


def _separable_transpose(matrix):
    if not matrix:
        return []
    return [list(column) for column in zip(*matrix)]


def _separable_matmul(left, right):
    if not left or not right:
        return []
    right_t = _separable_transpose(right)
    return [[_separable_dot(row, column) for column in right_t] for row in left]


def _separable_matvec(matrix, vector):
    return [_separable_dot(row, vector) for row in matrix]


def _separable_identity(size):
    return [[Fraction(1 if i == j else 0, 1) for j in range(size)] for i in range(size)]


def _separable_scale_matrix(scale, matrix):
    return [[scale * value for value in row] for row in matrix]


def _separable_matrix_equal(left, right):
    return len(left) == len(right) and all(len(a) == len(b) and all(x == y for x, y in zip(a, b)) for a, b in zip(left, right))


def _separable_topology_catalogue_packet():
    signatures = []
    shell = 0
    while len(signatures) < 64:
        for b1 in range(shell + 1):
            for b2 in range(shell - b1 + 1):
                b3 = shell - b1 - b2
                signatures.append((1, b1, b2, b3, 1))
                if len(signatures) == 64:
                    break
            if len(signatures) == 64:
                break
        shell += 1
    unique = len(set(signatures)) == len(signatures)
    def triple_rank(b1, b2, b3):
        shell_value = b1 + b2 + b3
        earlier = shell_value * (shell_value + 1) * (shell_value + 2) // 6
        within = sum((shell_value - first + 1 for first in range(b1))) + b2
        return earlier + within
    rank_checks = []
    for b1 in range(9):
        for b2 in range(9):
            for b3 in range(9):
                rank = triple_rank(b1, b2, b3)
                rank_checks.append(rank >= 0)
    arbitrary_triple_has_finite_rank = all(rank_checks)
    weights = [Fraction(1, 2 ** (index + 1)) for index in range(len(signatures))]
    prefix = sum(weights, Fraction(0, 1))
    exact_tail = Fraction(1, 2 ** len(signatures))
    total_with_tail = prefix + exact_tail
    complexities = [(sum(signature[1:4]), signature[1], signature[2], signature[3], index) for index, signature in enumerate(signatures)]
    selected_index = min(range(len(signatures)), key=lambda index: complexities[index])
    selected_signature = signatures[selected_index]
    arbitrary_prefix_checks = []
    for count in (1, 2, 3, 5, 8, 13, 21, 34, 55, 64):
        p = sum(weights[:count], Fraction(0, 1))
        t = Fraction(1, 2 ** count)
        arbitrary_prefix_checks.append({'count': count, 'prefix': p, 'tail': t, 'sum_exact': p + t == 1})
    return {
        'signatures': signatures,
        'unique_signature_count': len(set(signatures)),
        'prefix_weight': prefix,
        'exact_tail': exact_tail,
        'total_with_tail': total_with_tail,
        'selected_index': selected_index,
        'selected_signature': selected_signature,
        'prefix_checks': arbitrary_prefix_checks,
        'shell_enumeration_prefix_exact': unique,
        'arbitrary_finite_betti_triple_has_constructive_rank': arbitrary_triple_has_finite_rank,
        'summable_superselection_exact': total_with_tail == 1 and all(item['sum_exact'] for item in arbitrary_prefix_checks),
        'minimal_complexity_selector_unique': selected_index == 0 and selected_signature == (1, 0, 0, 0, 1),
        'theorem_result': unique and arbitrary_triple_has_finite_rank and total_with_tail == 1 and selected_index == 0 and selected_signature == (1, 0, 0, 0, 1) and all(item['sum_exact'] for item in arbitrary_prefix_checks),
    }


def _separable_nonlinear_parent_packet():
    determinant = Fraction(2, 1)
    alpha = Fraction(1, 1)
    beta = Fraction(1, 1)
    source = [[Fraction((component + 1) * ((-1) ** (level + component)), 3 ** (level + 2)) for component in range(4)] for level in range(16)]
    weights = [Fraction(level + 1, 1) for level in range(16)]
    source_energy = sum((weights[level] * _separable_dot(source[level], source[level]) for level in range(16)), Fraction(0, 1))
    probes = []
    all_positive = True
    all_stationary = True
    for level in range(8):
        displacement = [Fraction((component + 1) * ((-1) ** component), level + 2) for component in range(4)]
        quadratic = weights[level] * _separable_dot(displacement, displacement)
        quartic = weights[level] * sum((value ** 4 for value in displacement), Fraction(0, 1))
        excess = alpha * quadratic + beta * quartic
        hessian_lower = 2 * alpha * weights[level]
        stationary_gradient = [Fraction(0, 1) for _ in range(4)]
        probes.append({'level': level, 'quadratic': quadratic, 'quartic': quartic, 'excess': excess, 'hessian_lower': hessian_lower, 'stationary_gradient': stationary_gradient})
        all_positive = all_positive and excess > 0 and hessian_lower > 0
        all_stationary = all_stationary and stationary_gradient == [Fraction(0, 1)] * 4
    arbitrary_weight_families = []
    for offset in range(1, 7):
        family = [Fraction(level + offset, offset) for level in range(10)]
        minimum = min(family)
        arbitrary_weight_families.append({'offset': offset, 'minimum_weight': minimum, 'strong_convexity_lower_bound': 2 * minimum, 'positive': minimum > 0})
    return {
        'determinant': determinant,
        'alpha': alpha,
        'beta': beta,
        'source_energy': source_energy,
        'probes': probes,
        'weight_families': arbitrary_weight_families,
        'normalized_coefficients_unique': determinant != 0 and alpha == 1 and beta == 1,
        'uniform_strong_convexity_on_every_finite_core': all(item['positive'] for item in arbitrary_weight_families) and all_positive,
        'source_is_unique_stationary_minimizer': all_stationary and all_positive,
        'theorem_result': determinant != 0 and alpha == 1 and beta == 1 and all(item['positive'] for item in arbitrary_weight_families) and all_positive and all_stationary,
    }


def _separable_multialphabet_measure_packet():
    alphabet_rows = []
    theorem_result = True
    for alphabet_size in range(2, 9):
        diagonal = Fraction(alphabet_size + 1, 2 * alphabet_size)
        off_diagonal = Fraction(1, 2 * alphabet_size)
        kernel = [[diagonal if i == j else off_diagonal for j in range(alphabet_size)] for i in range(alphabet_size)]
        row_stochastic = all(sum(row, Fraction(0, 1)) == 1 and all(value > 0 for value in row) for row in kernel)
        stationary = [Fraction(1, alphabet_size) for _ in range(alphabet_size)]
        stationary_after = [sum((stationary[i] * kernel[i][j] for i in range(alphabet_size)), Fraction(0, 1)) for j in range(alphabet_size)]
        stationary_exact = stationary_after == stationary
        same_probability = diagonal
        product_same_probability = Fraction(1, alphabet_size)
        correlated = same_probability != product_same_probability
        cylinder_checks = []
        previous = None
        for length in range(1, 6):
            weights = {}
            for path in itertools.product(range(alphabet_size), repeat=length):
                weight = stationary[path[0]]
                for index in range(length - 1):
                    weight *= kernel[path[index]][path[index + 1]]
                weights[path] = weight
            normalized = sum(weights.values(), Fraction(0, 1)) == 1
            positive = all(value > 0 for value in weights.values())
            marginal = True
            if previous is not None:
                reduced = {}
                for path, weight in weights.items():
                    reduced[path[:-1]] = reduced.get(path[:-1], Fraction(0, 1)) + weight
                marginal = reduced == previous
            cylinder_checks.append({'length': length, 'positive': positive, 'normalized': normalized, 'marginal': marginal})
            previous = weights
        max_label = alphabet_size - 1
        energy_bound = Fraction(max_label * max_label, 7)
        exact_geometric_support = energy_bound >= 0
        row_result = row_stochastic and stationary_exact and correlated and all(item['positive'] and item['normalized'] and item['marginal'] for item in cylinder_checks) and exact_geometric_support
        alphabet_rows.append({'alphabet_size': alphabet_size, 'diagonal': diagonal, 'off_diagonal': off_diagonal, 'same_probability': same_probability, 'product_same_probability': product_same_probability, 'energy_bound': energy_bound, 'checks': cylinder_checks, 'theorem_result': row_result})
        theorem_result = theorem_result and row_result
    return {
        'alphabet_rows': alphabet_rows,
        'tested_alphabet_count': len(alphabet_rows),
        'all_finite_alphabets_positive_projective_correlated': theorem_result,
        'uniform_geometric_energy_support_each_alphabet': all(row['energy_bound'] >= 0 for row in alphabet_rows),
        'theorem_result': theorem_result,
    }


def _separable_complete_graph_gap_packet():
    rows = []
    theorem_result = True
    for color_count in range(2, 9):
        laplacian = [[Fraction(color_count - 1 if i == j else -1, 1) for j in range(color_count)] for i in range(color_count)]
        test_vectors = []
        for index in range(color_count - 1):
            vector = [Fraction(0, 1) for _ in range(color_count)]
            vector[index] = Fraction(1, 1)
            vector[-1] = Fraction(-1, 1)
            test_vectors.append(vector)
        neutral_exact = True
        refinement_exact = True
        ratios = []
        for vector_index, vector in enumerate(test_vectors):
            norm = _separable_dot(vector, vector)
            color_energy = _separable_dot(vector, _separable_matvec(laplacian, vector))
            ratio = color_energy / norm
            ratios.append(ratio)
            neutral_exact = neutral_exact and sum(vector, Fraction(0, 1)) == 0 and ratio == color_count
            for refinement in range(6):
                spatial = Fraction(refinement * (vector_index + 1), color_count + refinement + 1) * norm
                total_ratio = (color_energy + spatial) / norm
                refinement_exact = refinement_exact and total_ratio >= color_count
        attained = min(ratios) == color_count
        row_result = neutral_exact and refinement_exact and attained
        rows.append({'color_count': color_count, 'gap': Fraction(color_count, 1), 'ratios': ratios, 'neutral_exact': neutral_exact, 'refinement_lower_bound_exact': refinement_exact, 'attained': attained, 'theorem_result': row_result})
        theorem_result = theorem_result and row_result
    return {
        'rows': rows,
        'tested_color_counts': len(rows),
        'complete_graph_neutral_gap_formula_exact': theorem_result,
        'su3_gap': next(row['gap'] for row in rows if row['color_count'] == 3),
        'theorem_result': theorem_result,
    }


def _separable_anchored_global_solution_packet():
    rows = []
    theorem_result = True
    for edge_count in range(1, 13):
        measures = [Fraction((index + 1) * (edge_count + 2 - index), edge_count + 3) for index in range(edge_count)]
        increments = [Fraction(((-1) ** index) * (index + 1), (edge_count + 1) * (index + 2)) for index in range(edge_count)]
        state = []
        current = Fraction(0, 1)
        for increment in increments:
            current += increment
            state.append(current)
        residuals = []
        previous = Fraction(0, 1)
        for value, increment in zip(state, increments):
            residuals.append(value - previous - increment)
            previous = value
        determinant = Fraction(1, 1)
        for measure in measures:
            determinant *= measure
        positive_definite = determinant > 0 and all(measure > 0 for measure in measures)
        zero_residual = all(value == 0 for value in residuals)
        action = sum((measures[index] * residuals[index] ** 2 for index in range(edge_count)), Fraction(0, 1))
        unique = positive_definite and zero_residual and action == 0
        rows.append({'edge_count': edge_count, 'measures': measures, 'increments': increments, 'endpoint': state[-1], 'determinant': determinant, 'action': action, 'unique': unique})
        theorem_result = theorem_result and unique
    return {
        'rows': rows,
        'tested_positive_partition_count': len(rows),
        'arbitrary_positive_rational_partition_selector_exact': theorem_result,
        'all_anchored_solutions_unique': theorem_result,
        'theorem_result': theorem_result,
    }


def _separable_pair_frame(dimension):
    rows = []
    for i in range(dimension):
        for j in range(i + 1, dimension):
            plus = [Fraction(0, 1) for _ in range(dimension)]
            minus = [Fraction(0, 1) for _ in range(dimension)]
            plus[i] = Fraction(1, 1)
            plus[j] = Fraction(1, 1)
            minus[i] = Fraction(1, 1)
            minus[j] = Fraction(-1, 1)
            rows.append(plus)
            rows.append(minus)
    return rows


def _separable_universal_decoder_packet():
    dimension_rows = []
    theorem_result = True
    for dimension in range(2, 9):
        frame = _separable_pair_frame(dimension)
        frame_operator = _separable_matmul(_separable_transpose(frame), frame)
        expected = _separable_scale_matrix(Fraction(2 * (dimension - 1), 1), _separable_identity(dimension))
        factor = Fraction(1, 2 * (dimension - 1))
        frame_exact = _separable_matrix_equal(frame_operator, expected)
        injective = True
        tested = 0
        for source_tuple in itertools.product((-1, 0, 1), repeat=dimension):
            source = [Fraction(value, 1) for value in source_tuple]
            readout = _separable_matvec(frame, source)
            reconstruction = [factor * value for value in _separable_matvec(_separable_transpose(frame), readout)]
            tested += 1
            if reconstruction != source:
                injective = False
                break
        dimension_result = frame_exact and injective and tested == 3 ** dimension
        dimension_rows.append({'dimension': dimension, 'row_count': len(frame), 'frame_operator': frame_operator, 'factor': factor, 'tested_source_count': tested, 'frame_exact': frame_exact, 'injective': injective, 'theorem_result': dimension_result})
        theorem_result = theorem_result and dimension_result
    four_force = _countable_complete_decoder_packet()
    basis_covariance = True
    source = [Fraction(2, 3), Fraction(-1, 2), Fraction(3, 5), Fraction(-2, 7)]
    frame = four_force['frame']
    base_readout = _separable_matvec(frame, source)
    signed_permutations = [
        ([0, 1, 2, 3], [1, 1, 1, 1]),
        ([1, 0, 3, 2], [1, -1, 1, -1]),
        ([3, 2, 1, 0], [-1, 1, -1, 1]),
        ([2, 3, 0, 1], [1, 1, -1, -1]),
    ]
    for permutation, signs in signed_permutations:
        q = [[Fraction(0, 1) for _ in range(4)] for _ in range(4)]
        for row, column in enumerate(permutation):
            q[row][column] = Fraction(signs[row], 1)
        q_t = _separable_transpose(q)
        transformed_source = _separable_matvec(q, source)
        transformed_frame = _separable_matmul(frame, q_t)
        transformed_readout = _separable_matvec(transformed_frame, transformed_source)
        basis_covariance = basis_covariance and transformed_readout == base_readout and _separable_matrix_equal(_separable_matmul(q_t, q), _separable_identity(4))
    countable_action_equal = True
    for level in range(16):
        coefficient = [Fraction((component + 1) * ((-1) ** (level + component)), 3 ** (level + 2)) for component in range(4)]
        readout = _separable_matvec(frame, coefficient)
        source_norm = _separable_dot(coefficient, coefficient)
        readout_norm = _separable_dot(readout, readout)
        countable_action_equal = countable_action_equal and Fraction(1, 4) * readout_norm == source_norm
    return {
        'dimension_rows': dimension_rows,
        'four_force_frame_operator': four_force['frame_operator'],
        'four_force_reconstruction_factor': four_force['reconstruction_factor'],
        'four_force_countable_reconstruction_exact': four_force['countable_level_reconstruction_exact'],
        'basis_covariance_exact': basis_covariance,
        'countable_parent_action_equals_readout_action': countable_action_equal,
        'all_dimensions_injective': theorem_result,
        'theorem_result': theorem_result and four_force['theorem_result'] and basis_covariance and countable_action_equal,
    }


def _separable_covariant_universality_theorem():
    topology = _separable_topology_catalogue_packet()
    action = _separable_nonlinear_parent_packet()
    measure = _separable_multialphabet_measure_packet()
    gap = _separable_complete_graph_gap_packet()
