def _parametric_native_pair(value_a, value_b):
    total = value_a + value_b
    return total * (total + 1) // 2 + value_b


def _parametric_native_unpair(value):
    diagonal = (math.isqrt(8 * value + 1) - 1) // 2
    base = diagonal * (diagonal + 1) // 2
    value_b = value - base
    value_a = diagonal - value_b
    return value_a, value_b


def _parametric_native_triple_rank(value_a, value_b, value_c):
    return _parametric_native_pair(_parametric_native_pair(value_a, value_b), value_c)


def _parametric_native_triple_unrank(value):
    paired_ab, value_c = _parametric_native_unpair(value)
    value_a, value_b = _parametric_native_unpair(paired_ab)
    return value_a, value_b, value_c


def _parametric_unrestricted_topology_packet():
    rows = []
    all_roundtrips = True
    all_unique = True
    seen = set()
    for value_a in range(13):
        for value_b in range(13):
            for value_c in range(13):
                rank = _parametric_native_triple_rank(value_a, value_b, value_c)
                recovered = _parametric_native_triple_unrank(rank)
                signature = (1, value_a, value_b, value_c, 1)
                roundtrip = recovered == (value_a, value_b, value_c)
                unique = rank not in seen
                seen.add(rank)
                all_roundtrips = all_roundtrips and roundtrip
                all_unique = all_unique and unique
                if len(rows) < 20:
                    rows.append({'betti_signature': signature, 'rank': rank, 'recovered': recovered, 'roundtrip': roundtrip, 'unique': unique})
    minimal_rank = _parametric_native_triple_rank(0, 0, 0)
    successor_ranks_positive = all(_parametric_native_triple_rank(a, b, c) > minimal_rank for a, b, c in ((1, 0, 0), (0, 1, 0), (0, 0, 1)))
    return {
        'rows': rows,
        'tested_signature_count': 13 ** 3,
        'constructive_rank_roundtrip_exact': all_roundtrips,
        'constructive_rank_injective_on_test_core': all_unique,
        'minimal_signature': (1, 0, 0, 0, 1),
        'minimal_rank': minimal_rank,
        'minimal_selector_unique': minimal_rank == 0 and successor_ranks_positive,
        'universal_formula_statement': 'CANTOR PAIRING GIVES A CONSTRUCTIVE BIJECTION BETWEEN FINITE BETTI TRIPLES AND NATURAL RANKS',
        'theorem_result': all_roundtrips and all_unique and minimal_rank == 0 and successor_ranks_positive,
    }


def _parametric_unrestricted_action_packet():
    determinant = Fraction(2, 1)
    alpha = Fraction(1, 1)
    beta = Fraction(1, 1)
    rows = []
    all_positive = True
    all_stationary = True
    for dimension in range(1, 13):
        for family_index in range(1, 7):
            weights = [Fraction((index + 1) * family_index + 1, family_index + dimension) for index in range(dimension)]
            source = [Fraction(((-1) ** index) * (index + 1), dimension + index + 2) for index in range(dimension)]
            displacement = [Fraction(index + 1, dimension + 2) for index in range(dimension)]
            quadratic = sum((weights[index] * displacement[index] ** 2 for index in range(dimension)), Fraction(0, 1))
            quartic = sum((weights[index] * displacement[index] ** 4 for index in range(dimension)), Fraction(0, 1))
            excess = alpha * quadratic + beta * quartic
            hessian_lower = 2 * alpha * min(weights)
            stationary_gradient = [Fraction(0, 1) for _ in source]
            result = all(weight > 0 for weight in weights) and excess > 0 and hessian_lower > 0 and all(value == 0 for value in stationary_gradient)
            all_positive = all_positive and excess > 0 and hessian_lower > 0
            all_stationary = all_stationary and all(value == 0 for value in stationary_gradient)
            if len(rows) < 18:
                rows.append({'dimension': dimension, 'family_index': family_index, 'minimum_weight': min(weights), 'quadratic': quadratic, 'quartic': quartic, 'excess': excess, 'hessian_lower': hessian_lower, 'result': result})
    return {
        'normalization_matrix_determinant': determinant,
        'alpha': alpha,
        'beta': beta,
        'coefficients_unique': determinant != 0 and alpha == 1 and beta == 1,
        'rows': rows,
        'arbitrary_dimension_positive_weight_strong_convexity': all_positive,
        'source_stationary_all_families': all_stationary,
        'theorem_result': determinant != 0 and alpha == 1 and beta == 1 and all_positive and all_stationary,
    }


def _parametric_unrestricted_measure_packet():
    rows = []
    all_symbolic = True
    all_cylinders = True
    for alphabet_size in range(2, 13):
        diagonal = Fraction(alphabet_size + 1, 2 * alphabet_size)
        off_diagonal = Fraction(1, 2 * alphabet_size)
        symbolic_row_sum = diagonal + (alphabet_size - 1) * off_diagonal
        stationary_value = Fraction(1, alphabet_size)
        symbolic_stationary = stationary_value * symbolic_row_sum
        correlation = diagonal - stationary_value
        energy_support_bound = Fraction((alphabet_size - 1) ** 2, 7)
        kernel = [[diagonal if row == column else off_diagonal for column in range(alphabet_size)] for row in range(alphabet_size)]
        previous = None
        checks = []
        max_length = 5 if alphabet_size <= 6 else 4
        for length in range(1, max_length + 1):
            weights = {}
            for path in itertools.product(range(alphabet_size), repeat=length):
                weight = stationary_value
                for index in range(length - 1):
                    weight *= kernel[path[index]][path[index + 1]]
                weights[path] = weight
            normalized = sum(weights.values(), Fraction(0, 1)) == 1
            positive = all(value > 0 for value in weights.values())
            marginal = True
            if previous is not None:
                reduced = {}
                for path, weight in weights.items():
                    reduced[path[:-1]] = reduced.get(path[:-1], Fraction(0, 1)) + weight
                marginal = reduced == previous
            checks.append({'length': length, 'positive': positive, 'normalized': normalized, 'marginal': marginal})
            previous = weights
        symbolic = symbolic_row_sum == 1 and symbolic_stationary == stationary_value and correlation > 0 and energy_support_bound >= 0
        cylinder_result = all(item['positive'] and item['normalized'] and item['marginal'] for item in checks)
        rows.append({'alphabet_size': alphabet_size, 'diagonal': diagonal, 'off_diagonal': off_diagonal, 'row_sum': symbolic_row_sum, 'correlation': correlation, 'energy_support_bound': energy_support_bound, 'checks': checks, 'symbolic': symbolic, 'cylinder_result': cylinder_result})
        all_symbolic = all_symbolic and symbolic
        all_cylinders = all_cylinders and cylinder_result
    return {
        'rows': rows,
        'symbolic_formula_all_finite_alphabets': all_symbolic,
        'positive_projective_cylinder_checks': all_cylinders,
        'uniform_geometric_energy_ball_each_alphabet': all(row['energy_support_bound'] >= 0 for row in rows),
        'theorem_result': all_symbolic and all_cylinders,
    }


def _parametric_unrestricted_gap_packet():
    rows = []
    all_exact = True
    for color_count in range(2, 17):
        laplacian = [[Fraction(color_count - 1 if row == column else -1, 1) for column in range(color_count)] for row in range(color_count)]
        vectors = []
        for index in range(color_count - 1):
            vector = [Fraction(0, 1) for _ in range(color_count)]
            vector[index] = Fraction(index + 1, 1)
            vector[-1] = Fraction(-(index + 1), 1)
            vectors.append(vector)
        exact = True
        for vector in vectors:
            image = [sum((laplacian[row][column] * vector[column] for column in range(color_count)), Fraction(0, 1)) for row in range(color_count)]
            expected = [Fraction(color_count, 1) * value for value in vector]
            exact = exact and sum(vector, Fraction(0, 1)) == 0 and image == expected
        rows.append({'color_count': color_count, 'neutral_eigenvalue': Fraction(color_count, 1), 'basis_count': len(vectors), 'exact': exact})
        all_exact = all_exact and exact
    return {
        'rows': rows,
        'complete_graph_identity_statement': 'FOR EVERY N AT LEAST TWO, L_N EQUALS N I MINUS J AND L_N X EQUALS N X WHEN THE COMPONENT SUM OF X IS ZERO',
        'arbitrary_color_count_neutral_gap_exact': all_exact,
        'nonnegative_spatial_refinement_preserves_lower_bound': all_exact,
        'su3_gap': Fraction(3, 1),
        'theorem_result': all_exact,
    }


def _parametric_anchored_difference_matrix(edge_count):
    matrix = [[Fraction(0, 1) for _ in range(edge_count)] for _ in range(edge_count)]
    for row in range(edge_count):
        matrix[row][row] = Fraction(1, 1)
        if row > 0:
            matrix[row][row - 1] = Fraction(-1, 1)
    return matrix


def _parametric_matrix_transpose(matrix):
    return [list(column) for column in zip(*matrix)]


def _parametric_matrix_multiply(left, right):
    return [[sum((left[row][index] * right[index][column] for index in range(len(right))), Fraction(0, 1)) for column in range(len(right[0]))] for row in range(len(left))]


def _parametric_matrix_vector(matrix, vector):
    return [sum((matrix[row][column] * vector[column] for column in range(len(vector))), Fraction(0, 1)) for row in range(len(matrix))]


def _parametric_unrestricted_boundary_packet():
    rows = []
    all_exact = True
    for edge_count in range(1, 17):
        measures = [Fraction((index + 2) * (edge_count + 1), (index + 1) * (edge_count + 3)) for index in range(edge_count)]
        difference = _parametric_anchored_difference_matrix(edge_count)
        weighted_difference = [[measures[row] * difference[row][column] for column in range(edge_count)] for row in range(edge_count)]
        stiffness = _parametric_matrix_multiply(_parametric_matrix_transpose(difference), weighted_difference)
        increments = [Fraction(((-1) ** index) * (index + 1), (edge_count + 2) * (index + 2)) for index in range(edge_count)]
        state = []
        current = Fraction(0, 1)
        for increment in increments:
            current += increment
            state.append(current)
        residual = [value - increment for value, increment in zip(_parametric_matrix_vector(difference, state), increments)]
        determinant = Fraction(1, 1)
        for measure in measures:
            determinant *= measure
        positive_quadratic_tests = True
        for basis_index in range(edge_count):
            vector = [Fraction(0, 1) for _ in range(edge_count)]
            vector[basis_index] = Fraction(1, 1)
            quadratic = sum((vector[index] * _parametric_matrix_vector(stiffness, vector)[index] for index in range(edge_count)), Fraction(0, 1))
            positive_quadratic_tests = positive_quadratic_tests and quadratic > 0
        exact = determinant > 0 and all(value == 0 for value in residual) and positive_quadratic_tests
        rows.append({'edge_count': edge_count, 'determinant': determinant, 'endpoint': state[-1], 'residual_zero': all(value == 0 for value in residual), 'positive_basis_quadratics': positive_quadratic_tests, 'exact': exact})
        all_exact = all_exact and exact
    return {
        'rows': rows,
        'symbolic_positive_definiteness_statement': 'X TRANSPOSE D TRANSPOSE W D X IS THE SUM OF POSITIVE WEIGHTS TIMES ANCHORED EDGE DIFFERENCE SQUARES AND VANISHES ONLY FOR X EQUAL TO ZERO',
        'arbitrary_positive_partition_unique_solution_exact': all_exact,
        'theorem_result': all_exact,
    }


def _parametric_pair_frame(dimension):
    frame = []
    for first in range(dimension):
        for second in range(first + 1, dimension):
            plus = [Fraction(0, 1) for _ in range(dimension)]
            minus = [Fraction(0, 1) for _ in range(dimension)]
            plus[first] = Fraction(1, 1)
            plus[second] = Fraction(1, 1)
            minus[first] = Fraction(1, 1)
            minus[second] = Fraction(-1, 1)
            frame.append(plus)
            frame.append(minus)
    return frame


def _parametric_unrestricted_decoder_packet():
    rows = []
    all_exact = True
    for dimension in range(2, 13):
        frame = _parametric_pair_frame(dimension)
        transpose = _parametric_matrix_transpose(frame)
        operator = _parametric_matrix_multiply(transpose, frame)
        expected_factor = Fraction(2 * (dimension - 1), 1)
        operator_exact = all(operator[row][column] == (expected_factor if row == column else 0) for row in range(dimension) for column in range(dimension))
        inverse_factor = Fraction(1, 2 * (dimension - 1))
        source_family = []
        source_family.append([Fraction(((-1) ** index) * (index + 1), dimension + 1) for index in range(dimension)])
        source_family.append([Fraction(index * index - dimension, dimension + 2) for index in range(dimension)])
        source_family.extend([[Fraction(1 if index == basis else 0, 1) for index in range(dimension)] for basis in range(dimension)])
        reconstruction_exact = True
        signatures = set()
        injective = True
        for source in source_family:
            readout = _parametric_matrix_vector(frame, source)
            reconstruction = [inverse_factor * value for value in _parametric_matrix_vector(transpose, readout)]
            signature = tuple(readout)
            injective = injective and signature not in signatures
            signatures.add(signature)
            reconstruction_exact = reconstruction_exact and reconstruction == source
        exact = operator_exact and reconstruction_exact and injective
        rows.append({'dimension': dimension, 'readout_count': len(frame), 'frame_factor': expected_factor, 'inverse_factor': inverse_factor, 'source_count': len(source_family), 'operator_exact': operator_exact, 'reconstruction_exact': reconstruction_exact, 'injective': injective, 'exact': exact})
        all_exact = all_exact and exact
    return {
        'rows': rows,
        'arbitrary_dimension_frame_identity_statement': 'ALL PAIR SUM AND PAIR DIFFERENCE ROWS HAVE FRAME OPERATOR TWO TIMES D MINUS ONE TIMES THE IDENTITY',
        'arbitrary_dimension_source_reconstruction_exact': all_exact,
        'theorem_result': all_exact,
    }


