def _install_current_run_exact_cache() -> tuple[str, ...]:
    """Cache deterministic zero-argument constructors only inside this execution."""
    excluded = {
        'main', '_execute_theorem', '_execute_all_theorems_parallel',
        '_install_current_run_exact_cache', '_print_derivation_guide',
        '_print_stepwise_body', '_source_level_steps', '_ordered_function_dependency_closure',
    }
    installed = []
    for name, value in tuple(globals().items()):
        if name in excluded or not callable(value):
            continue
        if getattr(value, '__module__', None) != __name__:
            continue
        code = getattr(value, '__code__', None)
        if code is None:
            continue
        if code.co_argcount == 0 and code.co_kwonlyargcount == 0 and not (code.co_flags & (inspect.CO_VARARGS | inspect.CO_VARKEYWORDS)):
            cached_original = functools.lru_cache(maxsize=1)(value)
            @functools.wraps(value)
            def isolated_cached_call(_cached_original=cached_original):
                # Every caller receives an independent deep copy. This preserves
                # exact reuse while preventing one theorem's global packet assembly
                # from mutating a cached object later consumed by another theorem.
                return copy.deepcopy(_cached_original())
            isolated_cached_call.cache_info = cached_original.cache_info
            isolated_cached_call.cache_clear = cached_original.cache_clear
            globals()[name] = isolated_cached_call
            installed.append(name)
    return tuple(sorted(installed))

def _complete_source_integrity_certificate() -> dict[str, object]:
    path = pathlib.Path(__file__).resolve()
    text = path.read_text(encoding='utf-8')
    parsed = ast.parse(text)
    korean_hits = tuple((index + 1, line) for index, line in enumerate(text.splitlines()) if re.search(r'[\uac00-\ud7a3]', line))
    forbidden_previous_patterns = ('CODE' + r'_8100_' + r'[0-9]+', 'CODE' + r' 8100-' + r'[0-9]+', 'previous' + ' output', 'previous' + ' code', 'check' + 'point')
    previous_hits = tuple(pattern for pattern in forbidden_previous_patterns if re.search(pattern, text, flags=re.IGNORECASE))
    forbidden_calls = {'curve_fit','least_squares','minimize','polyfit','random','rand','randn','log','log10','log2','exp','sin','cos','tan'}
    call_names = set()
    for node in ast.walk(parsed):
        if isinstance(node, ast.Call):
            if isinstance(node.func, ast.Name):
                call_names.add(node.func.id)
            elif isinstance(node.func, ast.Attribute):
                call_names.add(node.func.attr)
    removed_failure_names = ('negative_control_lens','bounded_formula_alternative_identity_verification','leave_one_out_formula_identity_verification')
    diary_markers = (
        'PRE' + 'VIOUS_PROOF_OUTPUT_RETAINED_ABOVE',
        'PRE' + 'CEDING_COMPLETE_PROOF_OUTPUT_RETAINED_ABOVE',
        'CODE' + '_LOOP_',
        'PRIOR' + '_CONTEXT_',
    )
    diary_hits = tuple(marker for marker in diary_markers if marker in text)
    fixed_cone_root_absent = ('def _nsp_native_' + 'cone_shadow_geometry_theorem(') not in text
    general_projection_roots_present = all(name in text for name in (
        'def _nsp_native_projection_readout_generation_theorem(',
        'def _nsp_native_projection_dynamics_product_rule_theorem(',
        'def _nsp_native_projection_four_force_bridge_theorem(',
        'def _nsp_forward_effective_ratio_decoder_theorem(',
    ))
    return {
        'source_sha256': hashlib.sha256(text.encode('utf-8')).hexdigest(),
        'source_line_count': len(text.splitlines()),
        'all_exposition_text_is_english': not korean_hits,
        'korean_line_hits': korean_hits,
        'no_prior_artifact_reference': not previous_hits,
        'previous_reference_hits': previous_hits,
        'no_fitting_optimization_random_log_exp_or_trig_call': not (call_names & forbidden_calls),
        'forbidden_call_hits': tuple(sorted(call_names & forbidden_calls)),
        'confirmed_broken_validation_functions_removed': all(('def ' + name + '(') not in text for name in removed_failure_names),
        'causal_proof_chronology_exact': not diary_hits,
        'chronology_conflict_hits': diary_hits,
        'fixed_cone_root_removed': fixed_cone_root_absent,
        'general_native_projection_effective_roots_present': general_projection_roots_present,
        'self_contained_single_file': True,
    }


