def _flatten_complete_certificate(value, prefix=''):
    if isinstance(value, dict):
        for key in sorted(value, key=str):
            child = f'{prefix}.{key}' if prefix else str(key)
            yield from _flatten_complete_certificate(value[key], child)
    elif isinstance(value, (tuple, list)):
        for index, item in enumerate(value):
            yield from _flatten_complete_certificate(item, f'{prefix}[{index}]')
    else:
        yield prefix, value


def _root_theorem_gate(function_name: str, result) -> tuple[bool, str]:
    if function_name == '_global_target_web_theorem':
        passed = bool(
            result['target_set_exact']
            and result['fixed_order_exact']
            and result['each_target_once']
            and result['joint_web_well_formed']
        )
        return passed, 'global target web exactness'
    if isinstance(result, dict) and 'theorem_result' in result:
        return result['theorem_result'] is True, 'top-level theorem_result'
    if isinstance(result, dict) and 'THEOREM_RESULT' in result:
        return result['THEOREM_RESULT'] is True, 'top-level THEOREM_RESULT'
    return False, 'missing explicit theorem gate'


def _print_unique_source_derivation(function_name: str, title: str) -> None:
    print('THEOREM GOAL = Recompute ' + title + ' from its declared definitions and verify every explicit gate.')
    print('DERIVATION POLICY = Every source statement is listed once globally; repeated dependencies are referenced without duplicating their explanation.')
    dependencies = _ordered_function_dependency_closure(function_name)
    print('DEPENDENCY FUNCTION COUNT =', len(dependencies))
    for function_number, dependency_name in enumerate(dependencies, 1):
        if dependency_name in _PRINTED_DERIVATION_FUNCTIONS:
            print(f'  FUNCTION {function_number}: {dependency_name} [EXACT DERIVATION ALREADY PRINTED]')
            continue
        _PRINTED_DERIVATION_FUNCTIONS.add(dependency_name)
        function = globals()[dependency_name]
        try:
            signature = str(inspect.signature(function))
        except (TypeError, ValueError):
            signature = '(signature unavailable)'
        print(f'  FUNCTION {function_number}: {dependency_name}{signature}')
        for step_number, (depth, statement, explanation) in enumerate(_source_level_steps(dependency_name), 1):
            indentation = '    ' + '  ' * depth
            print(f'{indentation}SOURCE STEP {step_number}: {statement}')
            print(f'{indentation}WHY THIS STEP IS VALID: {explanation}')



