def _foi_zero_matrix(rows, cols):
    return tuple(tuple(Fraction(0, 1) for _ in range(cols)) for _ in range(rows))


def _foi_transpose(matrix):
    return tuple(tuple(matrix[i][j] for i in range(len(matrix))) for j in range(len(matrix[0])))


def _foi_matmul(left, right):
    return tuple(
        tuple(
            sum((left[i][k] * right[k][j] for k in range(len(right))), Fraction(0, 1))
            for j in range(len(right[0]))
        )
        for i in range(len(left))
    )


def _foi_matvec(matrix, vector):
    return tuple(
        sum((matrix[i][j] * vector[j] for j in range(len(vector))), Fraction(0, 1))
        for i in range(len(matrix))
    )


def _foi_matrix_add(left, right):
    return tuple(
        tuple(left[i][j] + right[i][j] for j in range(len(left[0])))
        for i in range(len(left))
    )


def _foi_matrix_sub(left, right):
    return tuple(
        tuple(left[i][j] - right[i][j] for j in range(len(left[0])))
        for i in range(len(left))
    )


def _foi_matrix_scale(scale, matrix):
    return tuple(tuple(scale * value for value in row) for row in matrix)


def _foi_identity(size):
    return tuple(
        tuple(Fraction(1 if i == j else 0, 1) for j in range(size))
        for i in range(size)
    )


def _foi_commutator(left, right):
    return _foi_matrix_sub(_foi_matmul(left, right), _foi_matmul(right, left))


def _foi_root_system_packet():
    systems = {
        'U1': {
            'rank': 1,
            'roots': tuple(),
            'cartan': ((Fraction(1, 1),),),
            'algebra_dimension': 1,
        },
        'A1': {
            'rank': 1,
            'roots': ((1,), (-1,)),
            'cartan': ((Fraction(2, 1),),),
            'algebra_dimension': 3,
        },
        'A2': {
            'rank': 2,
            'roots': ((1, 0), (-1, 0), (0, 1), (0, -1), (1, 1), (-1, -1)),
            'cartan': ((Fraction(2, 1), Fraction(-1, 1)), (Fraction(-1, 1), Fraction(2, 1))),
            'algebra_dimension': 8,
        },
    }
    rows = []
    exact = True
    dimensions = []
    for name, data in systems.items():
        root_set = set(data['roots'])
        negative_closed = all(tuple(-value for value in root) in root_set for root in data['roots'])
        dimension_exact = data['algebra_dimension'] == data['rank'] + len(data['roots'])
        if len(data['cartan']) == 1:
            determinant = data['cartan'][0][0]
        else:
            determinant = data['cartan'][0][0] * data['cartan'][1][1] - data['cartan'][0][1] * data['cartan'][1][0]
        positive_cartan = determinant > 0
        exact = exact and negative_closed and dimension_exact and positive_cartan
        dimensions.append(data['algebra_dimension'])
        rows.append({
            'name': name,
            'rank': data['rank'],
            'root_count': len(data['roots']),
            'algebra_dimension': data['algebra_dimension'],
            'cartan_determinant': determinant,
            'negative_root_closure': negative_closed,
            'dimension_exact': dimension_exact,
        })
    dimensions_unique = len(set(dimensions)) == len(dimensions)
    theorem = exact and dimensions_unique
    return {
        'systems': systems,
        'rows': tuple(rows),
        'dimensions_unique': dimensions_unique,
        'u1_a1_a2_operator_classes_distinct': theorem,
        'theorem_result': theorem,
    }


def _foi_anomaly_free_chiral_ray_packet():
    q_left = Fraction(1, 1)
    lepton_left = -3 * q_left
    higgs = 3 * q_left
    up_right = q_left + higgs
    down_right = q_left - higgs
    electron_right = lepton_left - higgs
    charges = {
        'Q_LEFT': q_left,
        'U_RIGHT': up_right,
        'D_RIGHT': down_right,
        'L_LEFT': lepton_left,
        'E_RIGHT': electron_right,
        'HIGGS': higgs,
    }
    su3_mixed = 2 * q_left - up_right - down_right
    su2_mixed = 3 * q_left + lepton_left
    gravitational = 6 * q_left - 3 * up_right - 3 * down_right + 2 * lepton_left - electron_right
    cubic = 6 * q_left ** 3 - 3 * up_right ** 3 - 3 * down_right ** 3 + 2 * lepton_left ** 3 - electron_right ** 3
    yukawa_up = up_right - q_left - higgs
    yukawa_down = down_right - q_left + higgs
    yukawa_electron = electron_right - lepton_left + higgs
    weak_doublet_count = 3 + 1
    global_doublet_parity_even = weak_doublet_count % 2 == 0
    integer_electric_charge_ratios = {
        'UP_LEFT': q_left + 3,
        'DOWN_LEFT': q_left - 3,
        'NEUTRINO_LEFT': lepton_left + 3,
        'ELECTRON_LEFT': lepton_left - 3,
        'UP_RIGHT': up_right,
        'DOWN_RIGHT': down_right,
        'ELECTRON_RIGHT': electron_right,
    }
    left_right_charge_match = (
        integer_electric_charge_ratios['UP_LEFT'] == integer_electric_charge_ratios['UP_RIGHT']
        and integer_electric_charge_ratios['DOWN_LEFT'] == integer_electric_charge_ratios['DOWN_RIGHT']
        and integer_electric_charge_ratios['ELECTRON_LEFT'] == integer_electric_charge_ratios['ELECTRON_RIGHT']
    )
    anomaly_rows = {
        'SU3_SQUARED_U1': su3_mixed,
        'SU2_SQUARED_U1': su2_mixed,
        'GRAVITY_SQUARED_U1': gravitational,
        'U1_CUBED': cubic,
    }
    yukawa_rows = {
        'UP': yukawa_up,
        'DOWN': yukawa_down,
        'ELECTRON': yukawa_electron,
    }
    anomalies_zero = all(value == 0 for value in anomaly_rows.values())
    yukawa_exact = all(value == 0 for value in yukawa_rows.values())
    primitive_ray = tuple(charges[name] for name in ('Q_LEFT', 'U_RIGHT', 'D_RIGHT', 'L_LEFT', 'E_RIGHT', 'HIGGS'))
    primitive_gcd = math.gcd(*[abs(value.numerator) for value in primitive_ray])
    primitive_exact = primitive_gcd == 1
    theorem = anomalies_zero and yukawa_exact and global_doublet_parity_even and left_right_charge_match and primitive_exact
    return {
        'charges': charges,
        'primitive_ray': primitive_ray,
        'anomaly_rows': anomaly_rows,
        'yukawa_rows': yukawa_rows,
        'weak_doublet_count': weak_doublet_count,
        'global_doublet_parity_even': global_doublet_parity_even,
        'integer_electric_charge_ratios': integer_electric_charge_ratios,
        'left_right_electric_charge_match': left_right_charge_match,
        'primitive_integer_ray_exact': primitive_exact,
        'theorem_result': theorem,
    }


def _foi_electromagnetic_operator_packet():
    d0 = (
        (Fraction(-1, 1), Fraction(1, 1), Fraction(0, 1)),
        (Fraction(0, 1), Fraction(-1, 1), Fraction(1, 1)),
        (Fraction(1, 1), Fraction(0, 1), Fraction(-1, 1)),
    )
    d1 = ((Fraction(1, 1), Fraction(1, 1), Fraction(1, 1)),)
    boundary_squared = _foi_matmul(d1, d0)
    laplacian = _foi_matmul(_foi_transpose(d0), d0)
    constant = (Fraction(1, 1), Fraction(1, 1), Fraction(1, 1))
    gauge_kernel = _foi_matvec(laplacian, constant)
    source = (Fraction(1, 1), Fraction(-1, 1), Fraction(0, 1))
    source_conserved = sum(source, Fraction(0, 1)) == 0
    abelian_generators = (((Fraction(0, 1), Fraction(1, 1)), (Fraction(-1, 1), Fraction(0, 1))),)
    abelian_commutator_zero = _foi_commutator(abelian_generators[0], abelian_generators[0]) == _foi_zero_matrix(2, 2)
    theorem = boundary_squared == _foi_zero_matrix(1, 3) and gauge_kernel == (Fraction(0, 1),) * 3 and source_conserved and abelian_commutator_zero
    return {
        'd0': d0,
        'd1': d1,
        'boundary_squared': boundary_squared,
        'laplacian': laplacian,
        'gauge_kernel': gauge_kernel,
        'source_conserved': source_conserved,
        'abelian_commutator_zero': abelian_commutator_zero,
        'theorem_result': theorem,
    }


def _foi_weak_chiral_operator_packet():
    left_projector = (
        (Fraction(1, 1), Fraction(0, 1), Fraction(0, 1), Fraction(0, 1)),
        (Fraction(0, 1), Fraction(1, 1), Fraction(0, 1), Fraction(0, 1)),
        (Fraction(0, 1), Fraction(0, 1), Fraction(0, 1), Fraction(0, 1)),
        (Fraction(0, 1), Fraction(0, 1), Fraction(0, 1), Fraction(0, 1)),
    )
    right_projector = _foi_matrix_sub(_foi_identity(4), left_projector)
    j2 = ((Fraction(0, 1), Fraction(1, 1)), (Fraction(-1, 1), Fraction(0, 1)))
    k2 = ((Fraction(0, 1), Fraction(1, 1)), (Fraction(1, 1), Fraction(0, 1)))
    j = (
        (j2[0][0], j2[0][1], Fraction(0, 1), Fraction(0, 1)),
        (j2[1][0], j2[1][1], Fraction(0, 1), Fraction(0, 1)),
        (Fraction(0, 1), Fraction(0, 1), Fraction(0, 1), Fraction(0, 1)),
        (Fraction(0, 1), Fraction(0, 1), Fraction(0, 1), Fraction(0, 1)),
    )
    k = (
        (k2[0][0], k2[0][1], Fraction(0, 1), Fraction(0, 1)),
        (k2[1][0], k2[1][1], Fraction(0, 1), Fraction(0, 1)),
        (Fraction(0, 1), Fraction(0, 1), Fraction(0, 1), Fraction(0, 1)),
        (Fraction(0, 1), Fraction(0, 1), Fraction(0, 1), Fraction(0, 1)),
    )
    commutator = _foi_commutator(j, k)
    nonabelian = commutator != _foi_zero_matrix(4, 4)
    projector_exact = _foi_matmul(left_projector, left_projector) == left_projector and _foi_matmul(right_projector, right_projector) == right_projector
    orthogonal_chiral_split = _foi_matmul(left_projector, right_projector) == _foi_zero_matrix(4, 4)
    left_support = _foi_matmul(j, left_projector) == j and _foi_matmul(k, left_projector) == k
    right_annihilated = _foi_matmul(j, right_projector) == _foi_zero_matrix(4, 4) and _foi_matmul(k, right_projector) == _foi_zero_matrix(4, 4)
    theorem = nonabelian and projector_exact and orthogonal_chiral_split and left_support and right_annihilated
    return {
        'left_projector': left_projector,
        'right_projector': right_projector,
        'commutator': commutator,
        'nonabelian': nonabelian,
        'projector_exact': projector_exact,
        'orthogonal_chiral_split': orthogonal_chiral_split,
        'left_support': left_support,
        'right_annihilated': right_annihilated,
        'theorem_result': theorem,
    }


def _foi_strong_color_operator_packet():
    identity = _foi_identity(3)
    ones = tuple(tuple(Fraction(1, 1) for _ in range(3)) for _ in range(3))
    laplacian = _foi_matrix_sub(_foi_matrix_scale(Fraction(3, 1), identity), ones)
    neutral_basis = (
        (Fraction(1, 1), Fraction(-1, 1), Fraction(0, 1)),
        (Fraction(1, 1), Fraction(0, 1), Fraction(-1, 1)),
    )
    gap_exact = all(_foi_matvec(laplacian, vector) == tuple(Fraction(3, 1) * value for value in vector) for vector in neutral_basis)
    permutation_exact = True
    for permutation in itertools.permutations(range(3)):
        p = tuple(tuple(Fraction(1 if permutation[i] == j else 0, 1) for j in range(3)) for i in range(3))
        transformed = _foi_matmul(_foi_matmul(p, laplacian), _foi_transpose(p))
        permutation_exact = permutation_exact and transformed == laplacian
    left_right_vector_like = _foi_matrix_add(laplacian, laplacian) == _foi_matrix_scale(Fraction(2, 1), laplacian)
    theorem = gap_exact and permutation_exact and left_right_vector_like
    return {
        'laplacian': laplacian,
        'neutral_basis': neutral_basis,
        'neutral_gap': Fraction(3, 1),
        'gap_exact': gap_exact,
        'color_permutation_invariant': permutation_exact,
        'left_right_vector_like': left_right_vector_like,
        'theorem_result': theorem,
    }


def _foi_gravity_operator_packet():
    eta = (
        (Fraction(-1, 1), Fraction(0, 1), Fraction(0, 1), Fraction(0, 1)),
        (Fraction(0, 1), Fraction(1, 1), Fraction(0, 1), Fraction(0, 1)),
        (Fraction(0, 1), Fraction(0, 1), Fraction(1, 1), Fraction(0, 1)),
        (Fraction(0, 1), Fraction(0, 1), Fraction(0, 1), Fraction(1, 1)),
    )
    source_a = (
        (Fraction(2, 1), Fraction(1, 2), Fraction(0, 1), Fraction(0, 1)),
        (Fraction(1, 2), Fraction(3, 1), Fraction(0, 1), Fraction(0, 1)),
        (Fraction(0, 1), Fraction(0, 1), Fraction(5, 1), Fraction(0, 1)),
        (Fraction(0, 1), Fraction(0, 1), Fraction(0, 1), Fraction(7, 1)),
    )
    source_b = (
        (Fraction(1, 1), Fraction(0, 1), Fraction(1, 3), Fraction(0, 1)),
        (Fraction(0, 1), Fraction(4, 1), Fraction(0, 1), Fraction(0, 1)),
        (Fraction(1, 3), Fraction(0, 1), Fraction(6, 1), Fraction(0, 1)),
        (Fraction(0, 1), Fraction(0, 1), Fraction(0, 1), Fraction(8, 1)),
    )
    def trace_reversal(source):
        eta_trace = sum((eta[i][i] * source[i][i] for i in range(4)), Fraction(0, 1))
        return tuple(
            tuple(source[i][j] - Fraction(1, 2) * eta[i][j] * eta_trace for j in range(4))
            for i in range(4)
        )
    response_a = trace_reversal(source_a)
    response_b = trace_reversal(source_b)
    response_sum = trace_reversal(_foi_matrix_add(source_a, source_b))
    additive = response_sum == _foi_matrix_add(response_a, response_b)
    symmetric = all(response_a[i][j] == response_a[j][i] and response_b[i][j] == response_b[j][i] for i in range(4) for j in range(4))
    c_values = (Fraction(1, 1), Fraction(2, 1), Fraction(5, 1))
    t_values = (Fraction(0, 1), Fraction(1, 2), Fraction(3, 1))
    rows = []
    frw_exact = True
    for c in c_values:
        for t in t_values:
            scale = c + t
            hubble = Fraction(1, 1) / scale
            hubble_derivative = -Fraction(1, 1) / (scale * scale)
            density = 3 * hubble * hubble
            pressure = -(2 * hubble_derivative + 3 * hubble * hubble)
            density_derivative = -6 * hubble ** 3
            conservation = density_derivative + 3 * hubble * (density + pressure)
            ricci = 6 * (hubble_derivative + 2 * hubble * hubble)
            exact = scale > 0 and conservation == 0 and ricci > 0
            frw_exact = frw_exact and exact
            rows.append({'c': c, 't': t, 'scale': scale, 'density': density, 'pressure': pressure, 'conservation': conservation, 'ricci': ricci, 'exact': exact})
    theorem = additive and symmetric and frw_exact
    return {
        'eta': eta,
        'response_additive': additive,
        'symmetric_rank_two_response': symmetric,
        'frw_rows': tuple(rows),
        'global_nonflat_conservation_exact': frw_exact,
        'theorem_result': theorem,
    }


def _foi_force_signature_assignment_packet(root_packet, electromagnetic, weak, strong, gravity):
    signatures = {
        'ELECTROMAGNETIC': {
            'internal_algebra_dimension': root_packet['systems']['U1']['algebra_dimension'],
            'root_count': len(root_packet['systems']['U1']['roots']),
            'abelian': electromagnetic['abelian_commutator_zero'],
            'chiral': False,
            'neutral_gap': Fraction(0, 1),
            'universal_metric_response': False,
            'symmetric_rank_two': False,
        },
        'WEAK': {
            'internal_algebra_dimension': root_packet['systems']['A1']['algebra_dimension'],
            'root_count': len(root_packet['systems']['A1']['roots']),
            'abelian': False,
            'chiral': weak['left_support'] and weak['right_annihilated'],
            'neutral_gap': Fraction(0, 1),
            'universal_metric_response': False,
            'symmetric_rank_two': False,
        },
        'STRONG': {
            'internal_algebra_dimension': root_packet['systems']['A2']['algebra_dimension'],
            'root_count': len(root_packet['systems']['A2']['roots']),
            'abelian': False,
            'chiral': False,
            'neutral_gap': strong['neutral_gap'],
            'universal_metric_response': False,
            'symmetric_rank_two': False,
        },
        'GRAVITY': {
            'internal_algebra_dimension': 0,
            'root_count': 0,
            'abelian': False,
            'chiral': False,
            'neutral_gap': Fraction(0, 1),
            'universal_metric_response': gravity['response_additive'],
            'symmetric_rank_two': gravity['symmetric_rank_two_response'],
        },
    }
    signature_tuples = {
        name: tuple(data[key] for key in ('internal_algebra_dimension', 'root_count', 'abelian', 'chiral', 'neutral_gap', 'universal_metric_response', 'symmetric_rank_two'))
        for name, data in signatures.items()
    }
    all_distinct = len(set(signature_tuples.values())) == 4
    selectors = {
        'ELECTROMAGNETIC': lambda row: row['internal_algebra_dimension'] == 1 and row['root_count'] == 0 and row['abelian'],
        'WEAK': lambda row: row['internal_algebra_dimension'] == 3 and row['root_count'] == 2 and row['chiral'],
        'STRONG': lambda row: row['internal_algebra_dimension'] == 8 and row['root_count'] == 6 and row['neutral_gap'] == 3,
        'GRAVITY': lambda row: row['internal_algebra_dimension'] == 0 and row['universal_metric_response'] and row['symmetric_rank_two'],
    }
    assignment_rows = []
    unique_assignment = True
    for force_name, selector in selectors.items():
        matches = tuple(name for name, row in signatures.items() if selector(row))
        exact = matches == (force_name,)
        unique_assignment = unique_assignment and exact
        assignment_rows.append({'force': force_name, 'matches': matches, 'unique': exact})
    theorem = all_distinct and unique_assignment
    return {
        'signatures': signatures,
        'signature_tuples': signature_tuples,
        'all_signatures_distinct': all_distinct,
        'assignment_rows': tuple(assignment_rows),
        'unique_operator_assignment': unique_assignment,
        'theorem_result': theorem,
    }


def _foi_parent_action_normalization_packet():
    frame = _qoc_frame()
    blocks = tuple(tuple(frame[2 * sector + offset] for offset in range(2)) for sector in range(4))
    block_grams = tuple(_foi_matmul(_foi_transpose(block), block) for block in blocks)
    total_gram = _foi_zero_matrix(4, 4)
    for gram in block_grams:
        total_gram = _foi_matrix_add(total_gram, gram)
    expected_total = _foi_matrix_scale(Fraction(4, 1), _foi_identity(4))
    equal_weight = Fraction(1, 4)
    normalized = _foi_zero_matrix(4, 4)
    for gram in block_grams:
        normalized = _foi_matrix_add(normalized, _foi_matrix_scale(equal_weight, gram))
    permutation_invariant_coefficients_unique = True
    coefficient_rows = []
    for numerator in range(-4, 9):
        candidate = Fraction(numerator, 4)
        invariant_tuple = (candidate,) * 4
        weighted = _foi_zero_matrix(4, 4)
        for coefficient, gram in zip(invariant_tuple, block_grams):
            weighted = _foi_matrix_add(weighted, _foi_matrix_scale(coefficient, gram))
        exact = weighted == _foi_identity(4)
        coefficient_rows.append({'candidate': candidate, 'normalized_identity': exact})
        if exact != (candidate == equal_weight):
            permutation_invariant_coefficients_unique = False
    source_rows = (
        (Fraction(1, 1), Fraction(2, 1), Fraction(3, 1), Fraction(5, 1)),
        (Fraction(2, 1), Fraction(-1, 1), Fraction(4, 1), Fraction(3, 1)),
        (Fraction(-3, 1), Fraction(5, 1), Fraction(1, 1), Fraction(2, 1)),
    )
    action_rows = []
    action_exact = True
    for source in source_rows:
        parent = sum((value * value for value in source), Fraction(0, 1))
        sector_actions = []
        for block in blocks:
            readout = _foi_matvec(block, source)
            sector_actions.append(equal_weight * sum((value * value for value in readout), Fraction(0, 1)))
        exact = sum(sector_actions, Fraction(0, 1)) == parent
        action_exact = action_exact and exact
        action_rows.append({'source': source, 'parent_action': parent, 'sector_actions': tuple(sector_actions), 'exact': exact})
    theorem = total_gram == expected_total and normalized == _foi_identity(4) and permutation_invariant_coefficients_unique and action_exact
    return {
        'block_grams': block_grams,
        'total_gram': total_gram,
        'equal_sector_weight': equal_weight,
        'normalized_operator': normalized,
        'coefficient_rows': tuple(coefficient_rows),
        'permutation_invariant_coefficients_unique': permutation_invariant_coefficients_unique,
        'action_rows': tuple(action_rows),
        'parent_action_equals_four_sector_actions': action_exact,
        'theorem_result': theorem,
    }


