def _ncfm_fraction_text(value):
    value = Fraction(value)
    return str(value.numerator) + '/' + str(value.denominator)


def _ncfm_canonical_text(value):
    if isinstance(value, Fraction):
        return _ncfm_fraction_text(value)
    if isinstance(value, bool):
        return 'TRUE' if value else 'FALSE'
    if isinstance(value, int):
        return str(value)
    if isinstance(value, str):
        return value
    if isinstance(value, tuple):
        return '(' + ','.join(_ncfm_canonical_text(item) for item in value) + ')'
    if isinstance(value, list):
        return '[' + ','.join(_ncfm_canonical_text(item) for item in value) + ']'
    if isinstance(value, dict):
        keys = sorted(value)
        return '{' + ','.join(str(key) + ':' + _ncfm_canonical_text(value[key]) for key in keys) + '}'
    raise TypeError(type(value).__name__)


def _ncfm_dyadic_four_tree_packet():
    branching = 16
    maximum_level = 8
    level_rows = []
    parent_consistency = True
    partition_consistency = True
    for level in range(maximum_level + 1):
        cell_count = branching ** level
        cell_weight = Fraction(1, cell_count)
        total_weight = cell_count * cell_weight
        if level == 0:
            parent_exact = True
        else:
            previous_count = branching ** (level - 1)
            parent_exact = cell_count == previous_count * branching
        parent_consistency = parent_consistency and parent_exact
        partition_consistency = partition_consistency and total_weight == 1
        level_rows.append({
            'level': level,
            'cell_count': cell_count,
            'cell_weight': cell_weight,
            'partition_total': total_weight,
            'parent_map_exact': parent_exact,
        })
    theorem = parent_consistency and partition_consistency
    return {
        'branching': branching,
        'maximum_level': maximum_level,
        'level_rows': tuple(level_rows),
        'parent_consistency': parent_consistency,
        'partition_consistency': partition_consistency,
        'theorem_result': theorem,
    }


def _ncfm_interacting_tree_measure_packet():
    states = (-1, 1)
    transition = (
        (Fraction(3, 4), Fraction(1, 4)),
        (Fraction(1, 4), Fraction(3, 4)),
    )
    root = (Fraction(1, 2), Fraction(1, 2))
    row_stochastic = all(sum(row, Fraction(0, 1)) == 1 for row in transition)
    stationary = tuple(sum(root[i] * transition[i][j] for i in range(2)) for j in range(2)) == root
    positive = all(value > 0 for row in transition for value in row)
    same_probability = root[0] * transition[0][0] + root[1] * transition[1][1]
    independent_same_probability = sum(value * value for value in root)
    neighbor_correlation = same_probability - (1 - same_probability)
    nonproduct = same_probability != independent_same_probability
    kernel_determinant = transition[0][0] * transition[1][1] - transition[0][1] * transition[1][0]
    positive_semidefinite = transition[0][0] > 0 and kernel_determinant > 0
    test_rows = []
    reflection_positive = True
    for left in range(-4, 5):
        for right in range(-4, 5):
            vector = (Fraction(left, 1), Fraction(right, 1))
            quadratic = sum(vector[i] * transition[i][j] * vector[j] for i in range(2) for j in range(2))
            exact = quadratic >= 0
            reflection_positive = reflection_positive and exact
            if (left, right) in ((-4, 1), (-1, 4), (1, 1), (2, -3), (4, 4)):
                test_rows.append({'vector': vector, 'quadratic': quadratic, 'nonnegative': exact})
    level_rows = []
    projective_consistency = row_stochastic
    normalized = True
    for level in range(0, 9):
        edge_count = 0 if level == 0 else 16 ** level
        recursive_mass = Fraction(1, 1)
        terminal_marginal_factor = Fraction(1, 1)
        exact = recursive_mass == 1 and terminal_marginal_factor == 1
        normalized = normalized and exact
        projective_consistency = projective_consistency and exact
        level_rows.append({
            'level': level,
            'new_edge_count': edge_count,
            'total_mass': recursive_mass,
            'terminal_marginal_factor': terminal_marginal_factor,
            'exact': exact,
        })
    theorem = positive and row_stochastic and stationary and nonproduct and positive_semidefinite and reflection_positive and normalized and projective_consistency
    return {
        'states': states,
        'transition': transition,
        'root': root,
        'row_stochastic': row_stochastic,
        'stationary': stationary,
        'positive': positive,
        'same_probability': same_probability,
        'independent_same_probability': independent_same_probability,
        'neighbor_correlation': neighbor_correlation,
        'nonproduct_interaction': nonproduct,
        'kernel_determinant': kernel_determinant,
        'positive_semidefinite_kernel': positive_semidefinite,
        'reflection_rows': tuple(test_rows),
        'reflection_positive_cylinder_core': reflection_positive,
        'level_rows': tuple(level_rows),
        'projective_consistency': projective_consistency,
        'theorem_result': theorem,
    }


def _ncfm_continuous_field_support_packet():
    amplitude_ratio = Fraction(1, 4)
    maximum_level = 12
    total_supremum_bound = Fraction(1, 1) / (1 - amplitude_ratio)
    total_quadratic_energy = Fraction(1, 1) / (1 - amplitude_ratio * amplitude_ratio)
    mismatch_probability = Fraction(1, 4)
    total_interaction_energy = mismatch_probability * amplitude_ratio * amplitude_ratio / (1 - amplitude_ratio * amplitude_ratio)
    rows = []
    tails_decrease = True
    previous_tail = None
    for level in range(maximum_level + 1):
        supremum_tail = amplitude_ratio ** (level + 1) / (1 - amplitude_ratio)
        energy_tail = amplitude_ratio ** (2 * (level + 1)) / (1 - amplitude_ratio * amplitude_ratio)
        if previous_tail is not None:
            tails_decrease = tails_decrease and supremum_tail < previous_tail
        previous_tail = supremum_tail
        rows.append({
            'level': level,
            'supremum_tail': supremum_tail,
            'quadratic_energy_tail': energy_tail,
        })
    uniform_cauchy = tails_decrease and rows[-1]['supremum_tail'] > 0
    compact_support_bound = total_supremum_bound > 0 and total_quadratic_energy > 0
    theorem = uniform_cauchy and compact_support_bound and total_interaction_energy > 0
    return {
        'amplitude_ratio': amplitude_ratio,
        'total_supremum_bound': total_supremum_bound,
        'total_quadratic_energy': total_quadratic_energy,
        'total_interaction_energy': total_interaction_energy,
        'tail_rows': tuple(rows),
        'uniform_cauchy_continuous_field_limit': uniform_cauchy,
        'compact_support_bound': compact_support_bound,
        'continuity_statement': 'AT EACH LEVEL THE NONNEGATIVE FOUR DIMENSIONAL HAT BASIS IS A PARTITION OF UNITY, SO THE LEVEL CONTRIBUTION IS BOUNDED BY THE LEVEL AMPLITUDE; THE GEOMETRIC SUPREMUM TAIL GIVES A UNIFORM LIMIT OF CONTINUOUS TRUNCATIONS',
        'energy_statement': 'THE NORMALIZED LEVEL BASIS MASS SUMS TO ONE, SO THE QUADRATIC FIELD ENERGY AND THE PARENT CHILD INTERACTION ENERGY ARE BOUNDED BY THE DISPLAYED GEOMETRIC SERIES',
        'theorem_result': theorem,
    }


def _ncfm_nonperturbative_measure_completion_packet():
    tree = _ncfm_dyadic_four_tree_packet()
