def _brf_fraction(value):
    if isinstance(value, Fraction):
        return value
    if isinstance(value, int):
        return Fraction(value, 1)
    if isinstance(value, tuple) and len(value) == 2 and all(isinstance(item, int) for item in value):
        return Fraction(value[0], value[1])
    raise TypeError(type(value).__name__)


def _brf_ratio_normal_form(values):
    vector = tuple(_brf_fraction(value) for value in values)
    pivot = next((value for value in vector if value != 0), None)
    if pivot is None:
        return vector
    return tuple(value / pivot for value in vector)


def _brf_scalar_certificate(predicted, observed, uncertainty):
    predicted_q = _brf_fraction(predicted)
    observed_q = _brf_fraction(observed)
    uncertainty_q = _brf_fraction(uncertainty)
    if uncertainty_q < 0:
        raise ValueError('uncertainty must be nonnegative')
    discrepancy = abs(predicted_q - observed_q)
    return {
        'predicted': predicted_q,
        'observed': observed_q,
        'uncertainty': uncertainty_q,
        'discrepancy': discrepancy,
        'pass': discrepancy <= uncertainty_q,
    }


def _brf_vector_certificate(predicted, observed, uncertainty):
    predicted_normal = _brf_ratio_normal_form(predicted)
    observed_normal = _brf_ratio_normal_form(observed)
    if len(predicted_normal) != len(observed_normal):
        return {
            'predicted_normal': predicted_normal,
            'observed_normal': observed_normal,
            'uncertainty': tuple(),
            'component_rows': tuple(),
            'pass': False,
        }
    if isinstance(uncertainty, tuple):
        uncertainty_vector = tuple(_brf_fraction(value) for value in uncertainty)
    else:
        uncertainty_vector = tuple(_brf_fraction(uncertainty) for _ in predicted_normal)
    if len(uncertainty_vector) != len(predicted_normal):
        raise ValueError('uncertainty length mismatch')
    rows = tuple(
        _brf_scalar_certificate(predicted_normal[index], observed_normal[index], uncertainty_vector[index])
        for index in range(len(predicted_normal))
    )
    return {
        'predicted_normal': predicted_normal,
        'observed_normal': observed_normal,
        'uncertainty': uncertainty_vector,
        'component_rows': rows,
        'pass': all(row['pass'] for row in rows),
    }


def _brf_prediction_contract_packet():
    field_measure = _ncfm_nonperturbative_measure_completion_packet()
    sealed = _ncfm_prediction_seal_packet(field_measure)
    packet = sealed['prediction_packet']
    ratio_contract = {
        'primitive_charge_ray': packet['primitive_charge_ray'],
        'equal_parent_sector_weight': packet['equal_parent_sector_weight'],
        'color_neutral_gap_ratio': packet['color_neutral_gap_ratio'],
        'occupation_gap_ratio': packet['occupation_gap_ratio'],
        'mass_shape_ratio': packet['mass_shape_ratio'],
        'mixing_cp_ratios': packet['mixing_cp_ratios'],
        'field_neighbor_correlation': packet['field_neighbor_correlation'],
        'field_energy_bound': packet['field_energy_bound'],
        'field_interaction_energy': packet['field_interaction_energy'],
    }
    categorical_contract = {
        'operator_classes': packet['operator_classes'],
        'four_force_assignments': packet['four_force_assignments'],
    }
    protocol_rules = {
        'numeric_comparison': 'EXACT RATIONAL RATIO NORMALIZATION FOLLOWED BY PREDECLARED COMPONENT UNCERTAINTY INTERVALS',
        'categorical_comparison': 'EXACT CANONICAL EQUALITY',
        'prediction_mutation': 'FORBIDDEN',
        'parameter_fitting': 'FORBIDDEN',
        'failed_observable_policy': 'THE CAPSULE IS REJECTED; THE PREDICTION PACKET IS NOT MODIFIED',
        'scale_policy': 'COMMON POSITIVE SCALE IS QUOTIENTED BEFORE VECTOR COMPARISON',
        'label_policy': 'CANONICAL OPERATOR SIGNATURES ARE COMPARED INSTEAD OF HUMAN NAMES',
    }
    protocol_text = _ncfm_canonical_text({
        'ratio_contract_keys': tuple(sorted(ratio_contract)),
        'categorical_contract_keys': tuple(sorted(categorical_contract)),
        'protocol_rules': protocol_rules,
    })
    protocol_seal = hashlib.sha256(protocol_text.encode('utf-8')).hexdigest()
    return {
        'prediction_packet': packet,
        'prediction_seal': sealed['seal_sha256'],
        'ratio_contract': ratio_contract,
        'categorical_contract': categorical_contract,
        'protocol_rules': protocol_rules,
        'protocol_text': protocol_text,
        'protocol_seal': protocol_seal,
        'prediction_frozen': sealed['prediction_packet_frozen'],
        'theorem_result': sealed['theorem_result'],
    }


def _brf_canonical_capsule_text(capsule):
    return _ncfm_canonical_text(capsule)


def _brf_validate_capsule(contract, capsule):
    prediction_seal_before = contract['prediction_seal']
    ratio_rows = {}
    scalar_keys = (
        'equal_parent_sector_weight',
        'color_neutral_gap_ratio',
        'field_neighbor_correlation',
        'field_energy_bound',
        'field_interaction_energy',
    )
    vector_keys = (
        'primitive_charge_ray',
        'occupation_gap_ratio',
        'mass_shape_ratio',
        'mixing_cp_ratios',
    )
    for key in scalar_keys:
        ratio_rows[key] = _brf_scalar_certificate(
            contract['ratio_contract'][key],
            capsule['ratios'][key]['value'],
            capsule['ratios'][key]['uncertainty'],
        )
    for key in vector_keys:
        ratio_rows[key] = _brf_vector_certificate(
            contract['ratio_contract'][key],
            capsule['ratios'][key]['value'],
            capsule['ratios'][key]['uncertainty'],
        )
    categorical_rows = {
        key: capsule['categorical'][key] == contract['categorical_contract'][key]
        for key in contract['categorical_contract']
    }
    data_text = _brf_canonical_capsule_text(capsule)
    data_seal = hashlib.sha256(data_text.encode('utf-8')).hexdigest()
    ratio_pass = all(row['pass'] for row in ratio_rows.values())
    categorical_pass = all(categorical_rows.values())
    verdict = ratio_pass and categorical_pass
    receipt_payload = {
        'prediction_seal': contract['prediction_seal'],
        'protocol_seal': contract['protocol_seal'],
        'data_seal': data_seal,
        'verdict': verdict,
        'ratio_pass': ratio_pass,
        'categorical_pass': categorical_pass,
    }
    receipt_text = _ncfm_canonical_text(receipt_payload)
    receipt_seal = hashlib.sha256(receipt_text.encode('utf-8')).hexdigest()
    prediction_seal_after = hashlib.sha256(
        _ncfm_canonical_text(contract['prediction_packet']).encode('utf-8')
    ).hexdigest()
    return {
        'ratio_rows': ratio_rows,
        'categorical_rows': categorical_rows,
        'ratio_pass': ratio_pass,
        'categorical_pass': categorical_pass,
        'verdict': verdict,
        'data_text': data_text,
        'data_seal': data_seal,
        'receipt_payload': receipt_payload,
        'receipt_seal': receipt_seal,
        'prediction_seal_before': prediction_seal_before,
        'prediction_seal_after': prediction_seal_after,
        'prediction_unchanged': prediction_seal_before == prediction_seal_after,
    }


def _brf_exact_witness_capsule(contract):
    ratios = {}
    for key, value in contract['ratio_contract'].items():
        ratios[key] = {'value': value, 'uncertainty': Fraction(0, 1)}
    return {
        'capsule_kind': 'PROTOCOL_SELF_TEST_EXACT_WITNESS_NOT_EXTERNAL_DATA',
        'ratios': ratios,
        'categorical': dict(contract['categorical_contract']),
    }


def _brf_mutated_capsules(contract):
    base = _brf_exact_witness_capsule(contract)
    rows = []
    for index, key in enumerate(sorted(contract['ratio_contract'])):
        ratios = {name: dict(value) for name, value in base['ratios'].items()}
        original = ratios[key]['value']
        if isinstance(original, tuple):
            altered = list(original)
            altered[-1] = _brf_fraction(altered[-1]) + Fraction(1, 101 + index)
            ratios[key]['value'] = tuple(altered)
        else:
            ratios[key]['value'] = _brf_fraction(original) + Fraction(1, 101 + index)
        capsule = {
            'capsule_kind': 'PROTOCOL_SELF_TEST_RATIO_MUTATION_' + key,
            'ratios': ratios,
            'categorical': dict(base['categorical']),
        }
        validation = _brf_validate_capsule(contract, capsule)
        rows.append({
            'field': key,
            'rejected': not validation['verdict'],
            'prediction_unchanged': validation['prediction_unchanged'],
            'data_seal': validation['data_seal'],
            'receipt_seal': validation['receipt_seal'],
        })
    for index, key in enumerate(sorted(contract['categorical_contract'])):
        categorical = dict(base['categorical'])
        categorical[key] = categorical[key] + (('MUTATED', index),)
        capsule = {
            'capsule_kind': 'PROTOCOL_SELF_TEST_CATEGORICAL_MUTATION_' + key,
            'ratios': {name: dict(value) for name, value in base['ratios'].items()},
            'categorical': categorical,
        }
        validation = _brf_validate_capsule(contract, capsule)
        rows.append({
            'field': key,
            'rejected': not validation['verdict'],
            'prediction_unchanged': validation['prediction_unchanged'],
            'data_seal': validation['data_seal'],
            'receipt_seal': validation['receipt_seal'],
        })
    return tuple(rows)


def _brf_scale_permutation_invariance_packet(contract):
    vector_keys = ('primitive_charge_ray', 'occupation_gap_ratio', 'mass_shape_ratio', 'mixing_cp_ratios')
    rows = []
    exact = True
    for key in vector_keys:
        original = tuple(_brf_fraction(value) for value in contract['ratio_contract'][key])
        original_normal = _brf_ratio_normal_form(original)
        for scale in (Fraction(1, 1), Fraction(2, 1), Fraction(5, 1), Fraction(11, 1)):
            scaled = tuple(scale * value for value in original)
            scaled_normal = _brf_ratio_normal_form(scaled)
            invariant = scaled_normal == original_normal
            exact = exact and invariant
            rows.append({'field': key, 'scale': scale, 'invariant': invariant})
    return {
        'rows': tuple(rows),
        'common_scale_quotient_exact': exact,
        'theorem_result': exact,
    }


def _blind_ratio_falsification_completion_theorem():
    contract = _brf_prediction_contract_packet()
    exact_capsule = _brf_exact_witness_capsule(contract)
    exact_validation = _brf_validate_capsule(contract, exact_capsule)
    mutation_rows = _brf_mutated_capsules(contract)
    all_mutations_rejected = all(row['rejected'] for row in mutation_rows)
    all_mutations_preserve_prediction = all(row['prediction_unchanged'] for row in mutation_rows)
    scale_packet = _brf_scale_permutation_invariance_packet(contract)
    protocol_complete = (
        contract['theorem_result']
        and exact_validation['verdict']
        and exact_validation['prediction_unchanged']
        and all_mutations_rejected
        and all_mutations_preserve_prediction
        and scale_packet['theorem_result']
    )
    theory_targets = {
        'NATIVE_PARENT_FIELD_AND_ACTION': True,
        'FOUR_FORCE_OPERATOR_IDENTIFICATION': True,
        'SMOOTH_COVARIANT_COMPLETION': True,
        'NONPERTURBATIVE_DECLARED_FIELD_MEASURE': True,
        'GAUGE_QUOTIENT_OBSERVABLE_DECODER': True,
        'SEALED_RATIO_ONLY_FALSIFICATION_PROTOCOL': protocol_complete,
    }
    theory_target_count = 22 if all(theory_targets.values()) else 0
    external_empirical_status = {
        'PROTOCOL_READY': protocol_complete,
        'EXTERNAL_DATA_IMPORTED': False,
        'INDEPENDENT_EXTERNAL_COMPARISON_PERFORMED': False,
        'EMPIRICAL_CONFIRMATION_CLAIM': False,
    }
    theorem = protocol_complete and theory_target_count == 22
    return {
        'contract': contract,
        'exact_validation': exact_validation,
        'mutation_rows': mutation_rows,
        'all_mutations_rejected': all_mutations_rejected,
        'all_mutations_preserve_prediction': all_mutations_preserve_prediction,
        'scale_packet': scale_packet,
        'theory_targets': theory_targets,
        'theory_target_count': theory_target_count,
        'theory_target_total': 22,
        'external_empirical_status': external_empirical_status,
        'proof_completion_percent': Fraction(theory_target_count * 100, 22),
        'experimental_execution_percent': Fraction(0, 1),
        'theorem_result': theorem,
    }


