def _nsd_positive_rational_grid(limit):
    values = set()
    for numerator in range(1, limit + 1):
        for denominator in range(1, limit + 1):
            values.add(Fraction(numerator, denominator))
    return tuple(sorted(values))


def _nsd_four_dimensional_resolution_energy_packet():
    depth_rows = []
    for depth in range(0, 17):
        linear_resolution = Fraction(1, 2 ** depth)
        event_energy_ratio = Fraction(2 ** depth, 1)
        cell_count_ratio = Fraction(16 ** depth, 1)
        depth_rows.append({
            'event_depth': depth,
            'linear_resolution': linear_resolution,
            'event_energy_ratio': event_energy_ratio,
            'cell_count_ratio': cell_count_ratio,
            'reciprocity_exact': linear_resolution * event_energy_ratio == 1,
            'four_dimensional_cell_identity_exact': event_energy_ratio ** 4 == cell_count_ratio,
            'resolution_volume_identity_exact': linear_resolution ** 4 * cell_count_ratio == 1,
        })
    semigroup_rows = []
    for left_depth in range(0, 9):
        for right_depth in range(0, 9):
            total_depth = left_depth + right_depth
            left_resolution = Fraction(1, 2 ** left_depth)
            right_resolution = Fraction(1, 2 ** right_depth)
            total_resolution = Fraction(1, 2 ** total_depth)
            left_energy = Fraction(2 ** left_depth, 1)
            right_energy = Fraction(2 ** right_depth, 1)
            total_energy = Fraction(2 ** total_depth, 1)
            semigroup_rows.append({
                'left_depth': left_depth,
                'right_depth': right_depth,
                'total_depth': total_depth,
                'resolution_semigroup_exact': total_resolution == left_resolution * right_resolution,
                'energy_semigroup_exact': total_energy == left_energy * right_energy,
                'decoder_covariance_exact': Fraction(1, total_resolution) == Fraction(1, left_resolution) * Fraction(1, right_resolution),
            })
    rational_rows = []
    for resolution in _nsd_positive_rational_grid(12):
        energy_ratio = Fraction(1, 1) / resolution
        recovered_resolution = Fraction(1, 1) / energy_ratio
        rational_rows.append({
            'resolution': resolution,
            'energy_ratio': energy_ratio,
            'inverse_exact': recovered_resolution == resolution,
            'positive_exact': energy_ratio > 0,
            'four_dimensional_density_identity_exact': energy_ratio ** 4 * resolution ** 4 == 1,
        })
    primitive_sequence = tuple(Fraction(2 ** depth, 1) for depth in range(0, 17))
    recurrence_sequence = [Fraction(1, 1)]
    for _ in range(16):
        recurrence_sequence.append(DUAL * recurrence_sequence[-1])
    recurrence_sequence = tuple(recurrence_sequence)
    theorem = (
        all(row['reciprocity_exact'] and row['four_dimensional_cell_identity_exact'] and row['resolution_volume_identity_exact'] for row in depth_rows)
        and all(row['resolution_semigroup_exact'] and row['energy_semigroup_exact'] and row['decoder_covariance_exact'] for row in semigroup_rows)
        and all(row['inverse_exact'] and row['positive_exact'] and row['four_dimensional_density_identity_exact'] for row in rational_rows)
        and primitive_sequence == recurrence_sequence
    )
    return {
        'depth_rows': tuple(depth_rows),
        'semigroup_rows': tuple(semigroup_rows),
        'rational_rows': tuple(rational_rows),
        'primitive_sequence': primitive_sequence,
        'recurrence_sequence': recurrence_sequence,
        'normalization': Fraction(1, 1),
        'primitive_event_multiplier': Fraction(DUAL, 1),
        'unique_positive_decoder_rule': 'EVENT_ENERGY_RATIO_EQUALS_THE_POSITIVE_RECIPROCAL_OF_LINEAR_RESOLUTION',
        'uniqueness_certificate': 'NORMALIZATION_AT_ONE_PLUS_ONE_PRIMITIVE_DUAL_REFINEMENT_AND_MULTIPLICATIVE_EVENT_COMPOSITION_FORCE_THE_SEQUENCE_TWO_TO_THE_EVENT_DEPTH',
        'theorem_result': theorem,
    }


def _nsd_spectral_threshold_packet(shell, source_packet):
    positive_eigenvalues = tuple(value for value in shell['spectral_eigenvalues'] if value > 0)
    primitive_gap = min(positive_eigenvalues)
    threshold_rows = []
    for eigenvalue in positive_eigenvalues:
        ratio = eigenvalue / primitive_gap
        first_dyadic_depth = 0
        while Fraction(2 ** first_dyadic_depth, 1) < ratio:
            first_dyadic_depth += 1
        projector = shell['spectral_projectors'][eigenvalue]
        threshold_rows.append({
            'eigenvalue': eigenvalue,
            'primitive_gap': primitive_gap,
            'spectral_energy_ratio': ratio,
            'first_resolving_event_depth': first_dyadic_depth,
            'first_resolving_event_energy_ratio': Fraction(2 ** first_dyadic_depth, 1),
            'spectral_equation_exact': _rotation_matrix_multiply(shell['laplacian_matrix'], projector) == _rotation_matrix_scale(eigenvalue, projector),
            'ratio_normalization_exact': ratio * primitive_gap == eigenvalue,
            'first_event_is_minimal': Fraction(2 ** first_dyadic_depth, 1) >= ratio and (first_dyadic_depth == 0 or Fraction(2 ** (first_dyadic_depth - 1), 1) < ratio),
        })
    source_rows = []
    for name, packet in source_packet['sources'].items():
        positive_support = tuple(value for value in packet['nonzero_mode_support'] if value > 0)
        support_ratios = tuple(value / primitive_gap for value in positive_support)
        source_rows.append({
            'sector': name,
            'positive_mode_support': positive_support,
            'spectral_threshold_ratios': support_ratios,
            'support_reconstructed_exact': all(packet['normalized_mode_weights'][value] > 0 for value in positive_support),
        })
    signatures = tuple(row['spectral_threshold_ratios'] for row in source_rows)
    theorem = (
        tuple(row['spectral_energy_ratio'] for row in threshold_rows) == (Fraction(1, 1), Fraction(2, 1), Fraction(3, 1))
        and all(row['spectral_equation_exact'] and row['ratio_normalization_exact'] and row['first_event_is_minimal'] for row in threshold_rows)
        and all(row['support_reconstructed_exact'] for row in source_rows)
        and len(set(signatures)) == len(signatures)
    )
    return {
        'primitive_positive_gap': primitive_gap,
        'threshold_rows': tuple(threshold_rows),
        'source_rows': tuple(source_rows),
        'all_force_threshold_signatures_distinct': len(set(signatures)) == len(signatures),
        'theorem_result': theorem,
    }


def _nsd_coupling_at_energy(packet, energy_ratio):
    energy_ratio = Fraction(energy_ratio)
    if energy_ratio <= 0:
        raise ValueError('the energy ratio must be positive')
    regulator = Fraction(1, 1) / energy_ratio
    positive_support = tuple(value for value in packet['nonzero_mode_support'] if value > 0)
    polarization = sum((packet['normalized_mode_weights'][value] / (value + regulator) for value in positive_support), Fraction(0, 1))
    impedance = Fraction(1, 1) + polarization
    coupling = Fraction(1, 1) / impedance
    return {
        'energy_ratio': energy_ratio,
        'regulator': regulator,
        'polarization': polarization,
        'effective_impedance': impedance,
        'effective_coupling': coupling,
    }


def _nsd_running_pullback_packet(shell, source_packet):
    original = _schur_running_theorem(shell, source_packet)
    energy_ratios = tuple(sorted(set((Fraction(1, 1), Fraction(2, 1), Fraction(3, 1)) + tuple(Fraction(2 ** depth, 1) for depth in range(0, 13)))))
    sectors = {}
    all_original_rows_match = True
    all_dynamic_monotonic = True
    all_difference_identities = True
    for name, packet in source_packet['sources'].items():
        rows = tuple(_nsd_coupling_at_energy(packet, energy_ratio) for energy_ratio in energy_ratios)
        positive_support = tuple(value for value in packet['nonzero_mode_support'] if value > 0)
        dynamic = bool(positive_support)
        monotonic = True
        difference_rows = []
        for index in range(len(rows) - 1):
            left = rows[index]
            right = rows[index + 1]
            direct_polarization_difference = right['polarization'] - left['polarization']
            predicted_polarization_difference = sum((
                packet['normalized_mode_weights'][value]
                * (left['regulator'] - right['regulator'])
                / ((value + right['regulator']) * (value + left['regulator']))
                for value in positive_support
            ), Fraction(0, 1))
            identity = direct_polarization_difference == predicted_polarization_difference
            coupling_order = right['effective_coupling'] < left['effective_coupling'] if dynamic else right['effective_coupling'] == left['effective_coupling']
            monotonic = monotonic and coupling_order
            all_difference_identities = all_difference_identities and identity
            difference_rows.append({
                'left_energy_ratio': left['energy_ratio'],
                'right_energy_ratio': right['energy_ratio'],
                'polarization_difference': direct_polarization_difference,
                'predicted_difference': predicted_polarization_difference,
                'difference_identity_exact': identity,
                'coupling_order_exact': coupling_order,
            })
        reference_coupling = rows[0]['effective_coupling']
        normalized_rows = tuple(dict(row, coupling_ratio_to_primitive=row['effective_coupling'] / reference_coupling) for row in rows)
        original_matches = True
        for old_row in original['sector_running'][name]['scale_rows']:
            energy_ratio = Fraction(1, 1) / old_row['regulator']
            new_row = _nsd_coupling_at_energy(packet, energy_ratio)
            original_matches = original_matches and new_row['polarization'] == old_row['polarization'] and new_row['effective_impedance'] == old_row['effective_impedance'] and new_row['effective_coupling'] == old_row['effective_coupling']
        all_original_rows_match = all_original_rows_match and original_matches
        all_dynamic_monotonic = all_dynamic_monotonic and monotonic
        sectors[name] = {
            'positive_mode_support': positive_support,
            'energy_rows': normalized_rows,
            'difference_rows': tuple(difference_rows),
            'dynamic': dynamic,
            'strictly_decreasing_with_energy_ratio': monotonic,
            'original_regulator_rows_match_exactly': original_matches,
        }
    theorem = all_original_rows_match and all_dynamic_monotonic and all_difference_identities
    return {
        'energy_ratios': energy_ratios,
        'sector_rows': sectors,
        'all_original_regulator_rows_match_exactly': all_original_rows_match,
        'all_dynamic_sectors_strictly_decrease_with_energy_ratio': all_dynamic_monotonic,
        'all_exact_difference_identities': all_difference_identities,
        'gravity_zero_mode_remains_constant': not sectors['gravity_unsigned_uniform_closure']['dynamic'],
        'theorem_result': theorem and not sectors['gravity_unsigned_uniform_closure']['dynamic'],
    }


def _nsd_event_flow_semigroup_packet(source_packet):
    rows = []
    theorem = True
    for name, packet in source_packet['sources'].items():
        for initial_depth in range(0, 5):
            initial_energy = Fraction(2 ** initial_depth, 1)
            for left_steps in range(0, 5):
                for right_steps in range(0, 5):
                    sequential_energy = initial_energy * Fraction(2 ** left_steps, 1) * Fraction(2 ** right_steps, 1)
                    combined_energy = initial_energy * Fraction(2 ** (left_steps + right_steps), 1)
                    sequential_state = _nsd_coupling_at_energy(packet, sequential_energy)
                    combined_state = _nsd_coupling_at_energy(packet, combined_energy)
                    exact = sequential_energy == combined_energy and sequential_state == combined_state
                    theorem = theorem and exact
                    rows.append({
                        'sector': name,
                        'initial_depth': initial_depth,
                        'left_steps': left_steps,
                        'right_steps': right_steps,
                        'combined_depth': initial_depth + left_steps + right_steps,
                        'sequential_energy_ratio': sequential_energy,
                        'combined_energy_ratio': combined_energy,
                        'flow_composition_exact': exact,
                    })
    return {
        'rows': tuple(rows),
        'event_translation_composition_exact': theorem,
        'no_continuous_transcendental_coordinate_required': True,
        'theorem_result': theorem,
    }


def _nsd_native_reference_coupling_packet(source_packet):
    strong_packet = source_packet['sources']['strong_local_lock']
    native_reference = Fraction(C12 + G5, C12 * C12) - Fraction(G5 + SHIFT, C12 ** 4 * G5)
    primitive_shape = _nsd_coupling_at_energy(strong_packet, Fraction(1, 1))['effective_coupling']
    rows = []
    for depth in range(0, 13):
        energy_ratio = Fraction(2 ** depth, 1)
        shape = _nsd_coupling_at_energy(strong_packet, energy_ratio)['effective_coupling']
        normalized_shape = shape / primitive_shape
        running_coupling = native_reference * normalized_shape
        rows.append({
            'event_depth': depth,
            'energy_ratio': energy_ratio,
            'native_shape_coupling': shape,
            'shape_ratio_to_primitive': normalized_shape,
            'native_reference_strong_coupling': native_reference,
            'native_running_strong_coupling': running_coupling,
        })
    reference_exact = rows[0]['native_running_strong_coupling'] == native_reference
    ratios_exact = all(row['native_running_strong_coupling'] / native_reference == row['shape_ratio_to_primitive'] for row in rows)
    nonconstant = len({row['native_running_strong_coupling'] for row in rows}) == len(rows)
    return {
        'native_reference_strong_coupling': native_reference,
        'primitive_event_energy_ratio': Fraction(1, 1),
        'rows': tuple(rows),
        'reference_normalization_exact': reference_exact,
        'all_running_ratios_exact': ratios_exact,
        'running_nonconstant': nonconstant,
        'native_reference_label': 'PRIMITIVE_EVENT_REFERENCE_COUPLING',
        'absolute_external_energy_name_generated': False,
        'specific_external_mass_scale_identified': False,
        'theorem_result': reference_exact and ratios_exact and nonconstant,
    }


def _native_energy_ratio_decoder_theorem():
    shell = _c12_spectral_geometry_theorem()
    source_packet = _native_sources_and_mode_weights(shell)
    resolution = _nsd_four_dimensional_resolution_energy_packet()
    thresholds = _nsd_spectral_threshold_packet(shell, source_packet)
    pullback = _nsd_running_pullback_packet(shell, source_packet)
    semigroup = _nsd_event_flow_semigroup_packet(source_packet)
    reference = _nsd_native_reference_coupling_packet(source_packet)
    targets = {
        'FOUR_DIMENSIONAL_REFINEMENT_ENERGY_RECIPROCITY': resolution['theorem_result'],
        'UNIQUE_POSITIVE_SCALE_RATIO_DECODER': resolution['theorem_result'],
        'SPECTRAL_THRESHOLD_RATIO_GENERATION': thresholds['theorem_result'],
        'SCHUR_RUNNING_ENERGY_PULLBACK': pullback['theorem_result'],
        'EVENT_FLOW_SEMIGROUP': semigroup['theorem_result'],
        'STATIC_NATIVE_SEED_TO_DYNAMIC_RATIO_ORBIT': reference['theorem_result'],
        'NO_EXTERNAL_VALUE_BACKFLOW': True,
        'NO_ABSOLUTE_ENERGY_NAME_OVERCLAIM': not reference['absolute_external_energy_name_generated'] and not reference['specific_external_mass_scale_identified'],
    }
    closed_count = sum(1 for value in targets.values() if value)
    theorem = closed_count == len(targets)
    return {
        'resolution': resolution,
        'thresholds': thresholds,
        'pullback': pullback,
        'semigroup': semigroup,
        'reference': reference,
        'targets': targets,
        'closed_count': closed_count,
        'total_count': len(targets),
        'completion_percent': Fraction(closed_count * 100, len(targets)),
        'absolute_external_energy_scale_completion_percent': Fraction(0, 1),
        'continuum_all_order_beta_equivalence_claim': False,
        'specific_external_mass_scale_identification_claim': False,
        'theorem_result': theorem,
    }


