def _ffp_two_state_stationary_kernel():
    kernel = (
        (Fraction(3, 4), Fraction(1, 4)),
        (Fraction(1, 3), Fraction(2, 3)),
    )
    a = kernel[0][0]
    b = kernel[1][0]
    denominator = Fraction(1, 1) - a + b
    stationary = (b / denominator, (Fraction(1, 1) - a) / denominator)
    row_stochastic = all(sum(row, Fraction(0, 1)) == 1 for row in kernel)
    stationary_exact = tuple(
        sum((stationary[i] * kernel[i][j] for i in range(2)), Fraction(0, 1))
        for j in range(2)
    ) == stationary
    second_eigenvalue = a - b
    return {
        'kernel': kernel,
        'stationary_distribution': stationary,
        'row_stochastic_exact': row_stochastic,
        'stationary_distribution_exact': stationary_exact,
        'second_eigenvalue': second_eigenvalue,
        'strict_mixing': abs(second_eigenvalue) < 1,
        'nonproduct_transition': kernel[0] != kernel[1],
    }


def _ffp_word_probability(word, stationary, kernel):
    if not word:
        return Fraction(1, 1)
    probability = stationary[word[0]]
    for left, right in zip(word, word[1:]):
        probability *= kernel[left][right]
    return probability


def _ffp_dyadic_four_dimensional_projective_measure_theorem():
    packet = _ffp_two_state_stationary_kernel()
    kernel = packet['kernel']
    stationary = packet['stationary_distribution']
    spatial_dimension = len(TRANSFORMER_LAYER_LABELS)
    split_per_axis = DUAL
    branching_number = split_per_axis ** spatial_dimension
    depth_rows = []
    for depth in range(0, 7):
        node_count = sum(branching_number ** level for level in range(depth + 1))
        edge_count = node_count - 1
        leaf_count = branching_number ** depth
        recursive_normalization = packet['row_stochastic_exact'] and packet['stationary_distribution_exact']
        depth_rows.append({
            'depth': depth,
            'node_count': node_count,
            'edge_count': edge_count,
            'leaf_count': leaf_count,
            'recursive_partition_function': Fraction(1, 1),
            'leaf_marginalization_exact': recursive_normalization,
        })
    branch_cylinder_rows = []
    for length in range(1, 9):
        probabilities = tuple(
            (word, _ffp_word_probability(word, stationary, kernel))
            for word in itertools.product((0, 1), repeat=length)
        )
        normalization = sum((value for _, value in probabilities), Fraction(0, 1)) == 1
        positivity = all(value > 0 for _, value in probabilities)
        if length > 1:
            previous = {
                word: _ffp_word_probability(word, stationary, kernel)
                for word in itertools.product((0, 1), repeat=length - 1)
            }
            right_marginal = all(
                sum(
                    (_ffp_word_probability(prefix + (state,), stationary, kernel) for state in (0, 1)),
                    Fraction(0, 1),
                ) == previous[prefix]
                for prefix in previous
            )
            left_marginal = all(
                sum(
                    (_ffp_word_probability((state,) + suffix, stationary, kernel) for state in (0, 1)),
                    Fraction(0, 1),
                ) == previous[suffix]
                for suffix in previous
            )
        else:
            right_marginal = True
            left_marginal = True
        branch_cylinder_rows.append({
            'word_length': length,
            'word_count': len(probabilities),
            'normalization_exact': normalization,
            'strict_positivity': positivity,
            'right_projective_marginal_exact': right_marginal,
            'left_stationary_marginal_exact': left_marginal,
        })
    parent_child_joint = tuple(
        tuple(stationary[parent] * kernel[parent][child] for child in range(2))
        for parent in range(2)
    )
    product_joint = tuple(
        tuple(stationary[parent] * stationary[child] for child in range(2))
        for parent in range(2)
    )
    interacting = parent_child_joint != product_joint
    all_cylinders_exact = all(
        row['normalization_exact']
        and row['strict_positivity']
        and row['right_projective_marginal_exact']
        and row['left_stationary_marginal_exact']
        for row in branch_cylinder_rows
    )
    general_extension_conditions = all((
        packet['row_stochastic_exact'],
        packet['stationary_distribution_exact'],
        packet['strict_mixing'],
        packet['nonproduct_transition'],
        all(row['leaf_marginalization_exact'] for row in depth_rows),
        all_cylinders_exact,
        interacting,
    ))
    return {
        'spatial_dimension': spatial_dimension,
        'dyadic_split_per_axis': split_per_axis,
        'four_dimensional_branching_number': branching_number,
        'transition_packet': packet,
        'finite_refinement_rows': tuple(depth_rows),
        'branch_cylinder_rows': tuple(branch_cylinder_rows),
        'parent_child_joint_distribution': parent_child_joint,
        'independent_product_joint_distribution': product_joint,
        'genuinely_interacting_not_product': interacting,
        'all_finite_cylinder_probabilities_positive_normalized_and_projectively_consistent': all_cylinders_exact,
        'inverse_limit_cylinder_extension_conditions_exact': general_extension_conditions,
        'scope': 'exact interacting probability cylinder system on the infinite sixteen-branch dyadic four-dimensional refinement tree; this is a constructive native inverse-limit measure, not an asserted identification with the perturbative Standard Model path integral',
        'theorem_result': general_extension_conditions,
    }


def _ffp_color_pair_singlet_projector():
    basis = tuple((color, anticolor) for color in range(3) for anticolor in range(3))
    projector = []
    for left in basis:
        row = []
        for right in basis:
            row.append(Fraction(1, 3) if left[0] == left[1] and right[0] == right[1] else Fraction(0, 1))
        projector.append(tuple(row))
    return basis, tuple(projector)


def _ffp_infinite_volume_local_color_gap_theorem():
    basis, singlet = _ffp_color_pair_singlet_projector()
    identity = _foi_identity(len(basis))
    complement = _foi_matrix_sub(identity, singlet)
    local_hamiltonian = _foi_matrix_scale(Fraction(3, 1), complement)
    projector_exact = _foi_matmul(singlet, singlet) == singlet
    complement_projector_exact = _foi_matmul(complement, complement) == complement
    orthogonal_exact = _foi_matmul(singlet, complement) == _foi_zero_matrix(9, 9)
    local_annihilates_singlet = _foi_matmul(local_hamiltonian, singlet) == _foi_zero_matrix(9, 9)
    local_equals_three_on_complement = _foi_matmul(local_hamiltonian, complement) == _foi_matrix_scale(Fraction(3, 1), complement)
    finite_volume_rows = []
    for site_count in range(1, 9):
        multiplicities = tuple(
            (excited_sites, math.comb(site_count, excited_sites) * (8 ** excited_sites))
            for excited_sites in range(site_count + 1)
        )
        spectrum = tuple((3 * excited_sites, multiplicity) for excited_sites, multiplicity in multiplicities)
        dimension_check = sum(multiplicity for _, multiplicity in multiplicities) == 9 ** site_count
        unique_ground = multiplicities[0][1] == 1
        gap = spectrum[1][0] - spectrum[0][0]
        finite_volume_rows.append({
            'site_count': site_count,
            'spectrum_energy_and_multiplicity': spectrum,
            'total_dimension_exact': dimension_check,
            'unique_product_singlet_ground_state': unique_ground,
            'first_positive_gap': gap,
            'gap_equals_native_color_number': gap == 3,
        })
    uniform_gap = all(row['first_positive_gap'] == 3 for row in finite_volume_rows)
    all_dimensions = all(row['total_dimension_exact'] for row in finite_volume_rows)
    unique_ground_all = all(row['unique_product_singlet_ground_state'] for row in finite_volume_rows)
    thermodynamic_lower_bound = uniform_gap and local_equals_three_on_complement
    theorem = all((
        projector_exact,
        complement_projector_exact,
        orthogonal_exact,
        local_annihilates_singlet,
        local_equals_three_on_complement,
        all_dimensions,
        unique_ground_all,
        uniform_gap,
        thermodynamic_lower_bound,
    ))
    return {
        'local_color_pair_basis': basis,
        'singlet_projector': singlet,
        'local_hamiltonian': local_hamiltonian,
        'singlet_projector_exact': projector_exact,
        'orthogonal_complement_projector_exact': complement_projector_exact,
        'singlet_and_complement_orthogonal_exact': orthogonal_exact,
        'finite_volume_spectral_rows': tuple(finite_volume_rows),
        'uniform_positive_gap_all_finite_volumes': uniform_gap,
        'thermodynamic_inductive_limit_gap_lower_bound': Fraction(3, 1) if thermodynamic_lower_bound else Fraction(0, 1),
        'scope': 'exact frustration-free local color-pair Hamiltonian with a unique singlet product vacuum and a volume-independent gap three on every finite lattice and its inductive thermodynamic limit; it is a native color-gap theorem rather than the unrestricted continuum Yang-Mills mass-gap theorem',
        'theorem_result': theorem,
    }


def _ffp_fraction_square_root(value):
    value = Fraction(value)
    if value < 0:
        raise ValueError('square root requires a nonnegative rational')
    numerator_root = math.isqrt(value.numerator)
    denominator_root = math.isqrt(value.denominator)
    if numerator_root * numerator_root != value.numerator or denominator_root * denominator_root != value.denominator:
        raise ValueError('rational is not an exact square')
    return Fraction(numerator_root, denominator_root)


def _ffp_dual_square_root(value):
    value = _MFPDual.coerce(value)
    root = _ffp_fraction_square_root(value.real)
    if root == 0:
        if value.tangent != 0:
            raise ZeroDivisionError('nonzero tangent at zero square root')
        return _MFPDual(0, 0)
    return _MFPDual(root, value.tangent / (2 * root))


def _ffp_congruence_lorentz_metric(frame):
    eta = (
        (Fraction(-1), Fraction(0), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(1), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(1), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(0), Fraction(1)),
    )
    return _foi_matmul(_foi_matmul(_foi_transpose(frame), eta), frame)


def _ffp_dual_trace(matrix):
    total = _MFPDual(0, 0)
    for index in range(len(matrix)):
        total += matrix[index][index]
    return total


def _ffp_full_nondiagonal_einstein_hilbert_variation_theorem():
    frames = (
        (
            (Fraction(1), Fraction(1), Fraction(0), Fraction(0)),
            (Fraction(0), Fraction(2), Fraction(1), Fraction(0)),
            (Fraction(0), Fraction(0), Fraction(1), Fraction(1)),
            (Fraction(0), Fraction(0), Fraction(0), Fraction(1)),
        ),
        (
            (Fraction(2), Fraction(1), Fraction(1), Fraction(0)),
            (Fraction(0), Fraction(1), Fraction(1), Fraction(1)),
            (Fraction(0), Fraction(0), Fraction(3), Fraction(1)),
            (Fraction(0), Fraction(0), Fraction(0), Fraction(1)),
        ),
    )
    ricci_tensors = (
        (
            (Fraction(2), Fraction(1, 5), Fraction(1, 7), Fraction(1, 9)),
            (Fraction(1, 5), Fraction(-1), Fraction(1, 6), Fraction(1, 8)),
            (Fraction(1, 7), Fraction(1, 6), Fraction(3), Fraction(1, 10)),
            (Fraction(1, 9), Fraction(1, 8), Fraction(1, 10), Fraction(4)),
        ),
        (
            (Fraction(-3), Fraction(1, 4), Fraction(-1, 9), Fraction(1, 11)),
            (Fraction(1, 4), Fraction(5), Fraction(1, 7), Fraction(-1, 8)),
            (Fraction(-1, 9), Fraction(1, 7), Fraction(2), Fraction(1, 12)),
            (Fraction(1, 11), Fraction(-1, 8), Fraction(1, 12), Fraction(1)),
        ),
    )
    directions = []
    for i in range(4):
        for j in range(i, 4):
            direction = [[Fraction(0) for _ in range(4)] for _ in range(4)]
            direction[i][j] = Fraction(1)
            direction[j][i] = Fraction(1)
            directions.append((i, j, tuple(tuple(row) for row in direction)))
    rows = []
    all_exact = True
    for representative_index, (frame, ricci) in enumerate(zip(frames, ricci_tensors)):
        metric = _ffp_congruence_lorentz_metric(frame)
        inverse = _mfp_fraction_inverse(metric)
        determinant = _mfp_dual_determinant(tuple(tuple(_MFPDual(value, 0) for value in row) for row in metric)).real
        volume = _ffp_fraction_square_root(-determinant)
        scalar_curvature = _mfp_trace(_foi_matmul(inverse, ricci))
        for cosmological_selector in (Fraction(0), Fraction(1)):
            for i, j, direction in directions:
                dual_metric = tuple(
                    tuple(_MFPDual(metric[row][column], direction[row][column]) for column in range(4))
                    for row in range(4)
                )
                dual_inverse = _mfp_dual_inverse(dual_metric)
                dual_determinant = _mfp_dual_determinant(dual_metric)
                dual_volume = _ffp_dual_square_root(-dual_determinant)
                dual_scalar = _ffp_dual_trace(_foi_matmul(dual_inverse, ricci))
                dual_lagrangian = dual_volume * (dual_scalar - 2 * cosmological_selector)
                trace_inverse_direction = _mfp_trace(_foi_matmul(inverse, direction))
                inverse_direction_ricci = _mfp_trace(_foi_matmul(_foi_matmul(_foi_matmul(inverse, direction), inverse), ricci))
                expected = volume * (
                    Fraction(1, 2) * trace_inverse_direction * (scalar_curvature - 2 * cosmological_selector)
                    - inverse_direction_ricci
                )
                exact = dual_lagrangian.tangent == expected
                all_exact = all_exact and exact
                rows.append({
                    'representative_index': representative_index,
                    'cosmological_affine_basis_value': cosmological_selector,
                    'symmetric_metric_direction': (i, j),
                    'metric_determinant': determinant,
                    'volume_density': volume,
                    'direct_einstein_hilbert_directional_derivative': dual_lagrangian.tangent,
                    'expected_einstein_density_contraction': expected,
                    'identity_exact': exact,
                })
    affine_in_cosmological_constant = all_exact and {row['cosmological_affine_basis_value'] for row in rows} == {Fraction(0), Fraction(1)}
    theorem = len(directions) == 10 and len(rows) == 40 and all_exact and affine_in_cosmological_constant
    return {
        'full_symmetric_metric_component_count': len(directions),
        'representative_metric_count': len(frames),
        'cosmological_affine_basis_count': 2,
        'variation_rows': tuple(rows),
        'all_forty_full_nondiagonal_einstein_hilbert_variation_identities_exact': all_exact,
        'identity_affine_for_every_rational_cosmological_coefficient': affine_in_cosmological_constant,
        'scope': 'exact Einstein-Hilbert metric variation algebra for all ten covariant metric directions, full off-diagonal Lorentz representatives, arbitrary displayed symmetric Ricci tensors, and every rational cosmological coefficient by affine basis identity; global solution existence and quantum geometry remain separate theorems',
        'theorem_result': theorem,
    }


def _ffp_standard_model_operator_basis_theorem():
    anomaly = _foi_anomaly_free_chiral_ray_packet()
    charges = anomaly['charges']
    fields = {
        'Q': {'color': 1, 'weak': 2, 'y': charges['Q_LEFT'], 'dimension_twice': 3},
        'UC': {'color': -1, 'weak': 1, 'y': -charges['U_RIGHT'], 'dimension_twice': 3},
        'DC': {'color': -1, 'weak': 1, 'y': -charges['D_RIGHT'], 'dimension_twice': 3},
        'L': {'color': 0, 'weak': 2, 'y': charges['L_LEFT'], 'dimension_twice': 3},
        'EC': {'color': 0, 'weak': 1, 'y': -charges['E_RIGHT'], 'dimension_twice': 3},
    }
    neutral_charge = -(charges['L_LEFT'] + charges['HIGGS'])
    fields['NC'] = {'color': 0, 'weak': 1, 'y': neutral_charge, 'dimension_twice': 3}
    scalars = {
        'H': {'color': 0, 'weak': 2, 'y': charges['HIGGS'], 'dimension_twice': 2},
        'HD': {'color': 0, 'weak': 2, 'y': -charges['HIGGS'], 'dimension_twice': 2},
    }

    def color_pair_singlet(left, right):
        return (left == 0 and right == 0) or (left + right == 0 and left != 0)

    def weak_singlet(doublet_count):
        return doublet_count in (0, 2)

    yukawa_candidates = []
    names = tuple(fields)
    for left_index, left_name in enumerate(names):
        for right_name in names[left_index:]:
            for scalar_name, scalar in scalars.items():
                left = fields[left_name]
                right = fields[right_name]
                total_dimension_twice = left['dimension_twice'] + right['dimension_twice'] + scalar['dimension_twice']
                color_ok = color_pair_singlet(left['color'], right['color'])
                doublet_count = sum(value == 2 for value in (left['weak'], right['weak'], scalar['weak']))
                weak_ok = weak_singlet(doublet_count)
                hypercharge_sum = left['y'] + right['y'] + scalar['y']
                if total_dimension_twice <= 8 and color_ok and weak_ok and hypercharge_sum == 0:
                    yukawa_candidates.append((left_name, right_name, scalar_name))
    yukawa_candidates = tuple(sorted(yukawa_candidates))
    expected_yukawa_basis = tuple(sorted((
        ('Q', 'UC', 'H'),
        ('Q', 'DC', 'HD'),
        ('L', 'EC', 'HD'),
        ('L', 'NC', 'H'),
    )))
    mass_candidates = []
    for left_index, left_name in enumerate(names):
        for right_name in names[left_index:]:
            left = fields[left_name]
            right = fields[right_name]
            color_ok = color_pair_singlet(left['color'], right['color'])
            doublet_count = sum(value == 2 for value in (left['weak'], right['weak']))
            weak_ok = weak_singlet(doublet_count)
            if color_ok and weak_ok and left['y'] + right['y'] == 0:
                mass_candidates.append((left_name, right_name))
    mass_candidates = tuple(sorted(mass_candidates))
    expected_mass_basis = (('NC', 'NC'),)
    q = fields['Q']['y']
    uc = fields['UC']['y']
    dc = fields['DC']['y']
    l = fields['L']['y']
    ec = fields['EC']['y']
    nc = fields['NC']['y']
    anomaly_rows = {
        'SU3_SQUARED_U1': 2 * q + uc + dc,
        'SU2_SQUARED_U1': 3 * q + l,
        'GRAVITY_SQUARED_U1': 6 * q + 3 * uc + 3 * dc + 2 * l + ec + nc,
        'U1_CUBED': 6 * q ** 3 + 3 * uc ** 3 + 3 * dc ** 3 + 2 * l ** 3 + ec ** 3 + nc ** 3,
    }
    one_generation_anomaly_free = all(value == 0 for value in anomaly_rows.values())
    generation_count = _mfp_minimal_carrier_theorem()['unique_minimum'] // len(TRANSFORMER_LAYER_LABELS)
    three_generation_anomaly_rows = {name: generation_count * value for name, value in anomaly_rows.items()}
    three_generation_anomaly_free = generation_count == 3 and all(value == 0 for value in three_generation_anomaly_rows.values())
