        yukawa_candidates == expected_yukawa_basis,
        mass_candidates == expected_mass_basis,
        one_generation_anomaly_free,
        three_generation_anomaly_free,
        global_su2_anomaly_free,
        operator_counts['yukawa_invariants_per_generation'] == 4,
