def _ufp_gaussian_diagonal(values):
    size = len(values)
    return [[_fc_gaussian(values[row] if row == column else 0, 0) for column in range(size)] for row in range(size)]


def _ufp_gaussian_matrix_equal(left, right):
    return len(left) == len(right) and all(
        len(left[row]) == len(right[row]) and all(left[row][column] == right[row][column] for column in range(len(left[row])))
        for row in range(len(left))
    )


def _ufp_gaussian_matrix_moduli_squared(matrix):
    return tuple(
        tuple(value[0] * value[0] + value[1] * value[1] for value in row)
        for row in matrix
    )


def _ufp_gaussian_jarlskog(matrix):
    product = _fc_gmul(
        _fc_gmul(matrix[0][0], matrix[1][1]),
        _fc_gmul(_fc_gconj(matrix[0][1]), _fc_gconj(matrix[1][0])),
    )
    return product[1]


def _ufp_minimal_flavor_cp_selector_theorem():
    primitive_triples = []
    for a in range(1, C12 + 1):
        for b in range(a + 1, C12 + 1):
            for c in range(b + 1, C12 + 1):
                if a * a + b * b == c * c and math.gcd(math.gcd(a, b), c) == 1:
                    primitive_triples.append((a, b, c))
    unique_triple = tuple(primitive_triples) == ((3, 4, 5),)
    a, b, c = primitive_triples[0]
    cosine = Fraction(a, c)
    sine = Fraction(b, c)
    r12 = _fc_gaussian_givens(3, 0, 1, cosine, sine, False)
    r13 = _fc_gaussian_givens(3, 0, 2, cosine, sine, True)
    r23 = _fc_gaussian_givens(3, 1, 2, cosine, sine, False)
    quark_mixing = _fc_gmatmul(r23, _fc_gmatmul(r13, r12))
    lepton_mixing = _fc_gmatmul(r12, _fc_gmatmul(r13, r23))
    identity = _fc_gidentity(3)
    quark_unitary = _ufp_gaussian_matrix_equal(_fc_gmatmul(_fc_gdagger(quark_mixing), quark_mixing), identity)
    lepton_unitary = _ufp_gaussian_matrix_equal(_fc_gmatmul(_fc_gdagger(lepton_mixing), lepton_mixing), identity)
    quark_probabilities = _ufp_gaussian_matrix_moduli_squared(quark_mixing)
    lepton_probabilities = _ufp_gaussian_matrix_moduli_squared(lepton_mixing)
    quark_rows = tuple(sum(row, Fraction(0)) for row in quark_probabilities)
    quark_columns = tuple(sum((quark_probabilities[row][column] for row in range(3)), Fraction(0)) for column in range(3))
    lepton_rows = tuple(sum(row, Fraction(0)) for row in lepton_probabilities)
    lepton_columns = tuple(sum((lepton_probabilities[row][column] for row in range(3)), Fraction(0)) for column in range(3))
    quark_j = _ufp_gaussian_jarlskog(quark_mixing)
    lepton_j = _ufp_gaussian_jarlskog(lepton_mixing)
    generation_labels = tuple(range(1, C12 // len(TRANSFORMER_LAYER_LABELS) + 1))
    additive_spectrum = tuple(sum(range(1, generation + 1)) for generation in generation_labels)
    self_pair_spectrum = tuple(generation * generation for generation in generation_labels)
    up_diagonal = _ufp_gaussian_diagonal(additive_spectrum)
    down_diagonal = _ufp_gaussian_diagonal(self_pair_spectrum)
    charged_lepton_diagonal = _ufp_gaussian_diagonal(tuple(reversed(additive_spectrum)))
    neutrino_diagonal = _ufp_gaussian_diagonal(tuple(value * value for value in additive_spectrum))
    down_mass = _fc_gmatmul(quark_mixing, _fc_gmatmul(down_diagonal, _fc_gdagger(quark_mixing)))
    neutrino_mass = _fc_gmatmul(lepton_mixing, _fc_gmatmul(neutrino_diagonal, _fc_gdagger(lepton_mixing)))
    quark_commutator = _fc_gcommutator(up_diagonal, down_mass)
    lepton_commutator = _fc_gcommutator(charged_lepton_diagonal, neutrino_mass)
    zero = _fc_gzero_matrix(3)
    quark_noncommuting = not _ufp_gaussian_matrix_equal(quark_commutator, zero)
    lepton_noncommuting = not _ufp_gaussian_matrix_equal(lepton_commutator, zero)
    exact = all((
        unique_triple,
        cosine * cosine + sine * sine == 1,
        generation_labels == (1, 2, 3),
        additive_spectrum == (1, 3, 6),
        self_pair_spectrum == (1, 4, 9),
        quark_unitary,
        lepton_unitary,
        quark_rows == (1, 1, 1),
        quark_columns == (1, 1, 1),
        lepton_rows == (1, 1, 1),
        lepton_columns == (1, 1, 1),
        quark_j != 0,
        lepton_j != 0,
        quark_noncommuting,
        lepton_noncommuting,
    ))
    return {
        'primitive_pythagorean_triples_below_native_carrier': tuple(primitive_triples),
        'unique_minimal_nontrivial_rational_rotation_triple': (a, b, c),
        'rotation_cosine': cosine,
        'rotation_sine': sine,
        'native_generation_labels': generation_labels,
        'additive_generation_spectrum': additive_spectrum,
        'self_pair_generation_spectrum': self_pair_spectrum,
        'quark_mixing_matrix': quark_mixing,
        'lepton_mixing_matrix': lepton_mixing,
        'quark_probability_matrix': quark_probabilities,
        'lepton_probability_matrix': lepton_probabilities,
        'quark_probability_rows_and_columns_normalized': quark_rows == (1, 1, 1) and quark_columns == (1, 1, 1),
        'lepton_probability_rows_and_columns_normalized': lepton_rows == (1, 1, 1) and lepton_columns == (1, 1, 1),
        'quark_jarlskog_invariant': quark_j,
        'lepton_jarlskog_invariant': lepton_j,
        'quark_mass_selector_commutator_nonzero': quark_noncommuting,
        'lepton_mass_selector_commutator_nonzero': lepton_noncommuting,
        'external_mass_or_mixing_table_used': False,
        'scope': 'exact unique flavor and CP selector inside the minimal primitive Pythagorean rational-rotation grammar generated below the native carrier; empirical CKM PMNS and mass naming remains an external identification theorem',
        'theorem_result': exact,
    }


def _ufp_su3_strong_coupling_lattice_gap_theorem():
    representations = []
    for p in range(C12 + 1):
        for q in range(C12 + 1):
            casimir = Fraction(p * p + q * q + p * q + 3 * p + 3 * q, 3)
            representations.append((p, q, casimir))
    nontrivial = tuple(row for row in representations if row[:2] != (0, 0))
    minimum_casimir = min(row[2] for row in nontrivial)
    minimizers = tuple((p, q) for p, q, value in nontrivial if value == minimum_casimir)
    branch_p_identity = tuple(
        (p, q, p * p + q * q + p * q + 3 * p + 3 * q - 4, (p - 1) * (p + 4) + q * (q + p + 3))
        for p in range(1, C12 + 1)
        for q in range(C12 + 1)
    )
    branch_q_identity = tuple(
        (p, q, p * p + q * q + p * q + 3 * p + 3 * q - 4, (q - 1) * (q + 4) + p * (p + q + 3))
        for q in range(1, C12 + 1)
        for p in range(C12 + 1)
    )
    algebraic_lower_bound_exact = all(left == right and right >= 0 for _, _, left, right in branch_p_identity + branch_q_identity)
    open_string_rows = tuple(
        {
            'separation_in_edges': length,
            'electric_flux_energy': length * minimum_casimir,
            'energy_per_edge': minimum_casimir,
            'linear_flux_tube_potential_exact': length * minimum_casimir == Fraction(4 * length, 3),
        }
        for length in range(1, C12 + 1)
    )
    closed_loop_rows = tuple(
        {
            'rectangle_sides': (left, right),
            'loop_length': 2 * (left + right),
            'electric_loop_energy': 2 * (left + right) * minimum_casimir,
        }
        for left in range(1, G5 + 1)
        for right in range(1, G5 + 1)
    )
    first_physical_closed_loop_gap = min(row['electric_loop_energy'] for row in closed_loop_rows)
    gauge = _fc_gauge_bundle_curvature_packet()
    exact = all((
        gauge['su3_packet']['theorem_result'],
        minimum_casimir == Fraction(4, 3),
        minimizers == ((0, 1), (1, 0)),
        algebraic_lower_bound_exact,
        all(row['linear_flux_tube_potential_exact'] for row in open_string_rows),
        first_physical_closed_loop_gap == Fraction(16, 3),
    ))
    return {
        'su3_representation_casimir_rows': tuple(representations),
        'minimum_nontrivial_quadratic_casimir': minimum_casimir,
        'minimum_casimir_representations': minimizers,
        'general_nonnegative_integer_lower_bound_decomposition_exact': algebraic_lower_bound_exact,
        'open_flux_string_rows': open_string_rows,
        'closed_rectangular_loop_rows': closed_loop_rows,
        'first_gauge_invariant_closed_loop_gap': first_physical_closed_loop_gap,
        'uniform_electric_edge_gap_in_every_finite_lattice': minimum_casimir,
        'thermodynamic_local_excitation_gap_lower_bound': minimum_casimir,
        'scope': 'exact SU3 strong-coupling electric lattice gauge Hamiltonian theorem with representation-theoretic Casimir gap and linear electric flux-tube energy; adding the full continuum magnetic Yang-Mills interaction is a separate universality theorem',
        'theorem_result': exact,
    }


def _ufp_poly_add(left, right):
    size = max(len(left), len(right))
    return tuple((left[index] if index < len(left) else 0) + (right[index] if index < len(right) else 0) for index in range(size))


def _ufp_poly_mul(left, right):
    result = [0 for _ in range(len(left) + len(right) - 1)]
    for i, a in enumerate(left):
        for j, b in enumerate(right):
            result[i + j] += a * b
    return tuple(result)


def _ufp_global_kasner_einstein_family_theorem():
    u = (0, 1)
    one = (1,)
    denominator = _ufp_poly_add(_ufp_poly_add(one, u), _ufp_poly_mul(u, u))
    p1_numerator = (0, -1)
    p2_numerator = (1, 1)
    p3_numerator = _ufp_poly_mul(u, (1, 1))
    sum_numerator = _ufp_poly_add(_ufp_poly_add(p1_numerator, p2_numerator), p3_numerator)
    square_sum_numerator = _ufp_poly_add(
        _ufp_poly_add(_ufp_poly_mul(p1_numerator, p1_numerator), _ufp_poly_mul(p2_numerator, p2_numerator)),
        _ufp_poly_mul(p3_numerator, p3_numerator),
    )
    denominator_squared = _ufp_poly_mul(denominator, denominator)
    polynomial_kasner_sum_identity = sum_numerator == denominator
    polynomial_kasner_square_identity = square_sum_numerator == denominator_squared
    rows = []
    for parameter in tuple(Fraction(value, 1) for value in range(1, C12 + 1)) + (Fraction(1, 2), Fraction(2, 3), Fraction(3, 2)):
        d = 1 + parameter + parameter * parameter
        exponents = (
            -parameter / d,
            (1 + parameter) / d,
            parameter * (1 + parameter) / d,
        )
        exponent_sum = sum(exponents, Fraction(0))
        square_sum = sum((value * value for value in exponents), Fraction(0))
        ricci_time_coefficient = exponent_sum - square_sum
        ricci_space_coefficients = tuple(value * (exponent_sum - 1) for value in exponents)
        kretschmann_coefficient = 4 * (
            sum((value * value * (value - 1) * (value - 1) for value in exponents), Fraction(0))
            + sum((exponents[left] * exponents[left] * exponents[right] * exponents[right] for left in range(3) for right in range(left + 1, 3)), Fraction(0))
        )
        rows.append({
            'rational_kasner_parameter': parameter,
            'kasner_exponents': exponents,
            'sum_exponents': exponent_sum,
            'sum_squared_exponents': square_sum,
            'ricci_time_coefficient': ricci_time_coefficient,
            'ricci_spatial_coefficients': ricci_space_coefficients,
            'kretschmann_coefficient_over_time_four': kretschmann_coefficient,
            'vacuum_einstein_exact': ricci_time_coefficient == 0 and all(value == 0 for value in ricci_space_coefficients),
            'nonflat_strong_field_solution': kretschmann_coefficient > 0,
        })
    flrw = _gfr_einstein_family_packet()
    exact = all((
        polynomial_kasner_sum_identity,
        polynomial_kasner_square_identity,
        all(row['vacuum_einstein_exact'] for row in rows),
        all(row['nonflat_strong_field_solution'] for row in rows),
        flrw['theorem_result'],
    ))
    return {
        'kasner_parameter_polynomial_denominator': denominator,
        'kasner_sum_polynomial_identity_exact': polynomial_kasner_sum_identity,
        'kasner_square_sum_polynomial_identity_exact': polynomial_kasner_square_identity,
        'rational_kasner_solution_rows': tuple(rows),
        'global_perfect_fluid_flrw_family': flrw,
        'global_vacuum_anisotropic_family_exact': all(row['vacuum_einstein_exact'] for row in rows),
        'global_matter_cosmology_family_exact': flrw['theorem_result'],
        'scope': 'two exact global nonlinear Einstein solution families are generated without inserted observational constants: rational Kasner vacuum metrics on positive time and the native perfect-fluid FLRW family; completeness of every smooth Einstein solution and unrestricted external quantum-geometry measure equivalence remain separate',
        'theorem_result': exact,
    }


def _ufp_positive_spectral_lsz_scattering_theorem():
    masses_squared = (Fraction(1), Fraction(3), Fraction(6))
    raw_weights = (Fraction(1), Fraction(3), Fraction(6))
    weight_total = sum(raw_weights, Fraction(0))
    spectral_weights = tuple(value / weight_total for value in raw_weights)
    residues = tuple((mass, weight) for mass, weight in zip(masses_squared, spectral_weights))
    momentum_rows = []
    for momentum_squared in tuple(Fraction(value, 1) for value in range(C12 + 1)) + (Fraction(1, 2), Fraction(3, 2)):
        derivative_rows = []
        for order in range(5):
            alternating_derivative = math.factorial(order) * sum(
                (weight / (momentum_squared + mass) ** (order + 1) for mass, weight in residues),
                Fraction(0),
            )
            derivative_rows.append((order, alternating_derivative, alternating_derivative > 0))
        propagator = derivative_rows[0][1]
        momentum_rows.append({
            'euclidean_momentum_squared': momentum_squared,
            'positive_spectral_propagator': propagator,
            'alternating_derivative_rows': tuple(derivative_rows),
            'complete_monotonicity_through_order_four': all(row[2] for row in derivative_rows),
        })
    transfer_factors = tuple(Fraction(1, 1 + mass) for mass in masses_squared)
    reflection_matrix = tuple(
        tuple(
            sum((weight * factor ** (row + column) for weight, factor in zip(spectral_weights, transfer_factors)), Fraction(0))
            for column in range(4)
        )
        for row in range(4)
    )
    gram_factor = tuple(
        tuple(spectral_weights[mode] * transfer_factors[mode] ** (row + column) for mode in range(3))
        for row in range(4)
        for column in range(4)
    )
    principal_minors = tuple(_fraction_matrix_determinant(tuple(tuple(reflection_matrix[i][j] for j in range(size)) for i in range(size))) for size in range(1, 5))
    reflection_positive = all(value >= 0 for value in principal_minors)
    scattering = _ffp_energy_parameter_scattering_theorem()
    detector_rows = []
    for row in scattering['rational_energy_parameter_rows']:
        matrix = row['scattering_matrix']
        probabilities = tuple(tuple(value * value for value in matrix_row) for matrix_row in matrix)
        row_sums = tuple(sum(matrix_row, Fraction(0)) for matrix_row in probabilities)
        column_sums = tuple(sum((probabilities[i][j] for i in range(len(probabilities))), Fraction(0)) for j in range(len(probabilities[0])))
        detector_rows.append({
            'rational_energy_parameter': row['rational_energy_parameter'],
            'transition_probability_matrix': probabilities,
            'row_sums': row_sums,
            'column_sums': column_sums,
            'detector_probability_normalized': all(value == 1 for value in row_sums + column_sums),
            'optical_theorem_exact': row['finite_optical_theorem_exact'],
        })
    exact = all((
        sum(spectral_weights, Fraction(0)) == 1,
        all(row['complete_monotonicity_through_order_four'] for row in momentum_rows),
        reflection_positive,
        scattering['theorem_result'],
        all(row['detector_probability_normalized'] and row['optical_theorem_exact'] for row in detector_rows),
    ))
    return {
        'positive_spectral_masses_squared': masses_squared,
        'positive_spectral_weights': spectral_weights,
        'pole_residues': residues,
        'euclidean_momentum_rows': tuple(momentum_rows),
        'reflection_positive_hankel_matrix': reflection_matrix,
        'reflection_positive_principal_minors': principal_minors,
        'reflection_positivity_exact': reflection_positive,
        'unitary_energy_parameter_scattering_packet': scattering,
        'detector_probability_rows': tuple(detector_rows),
        'finite_pole_lsz_residue_normalization_exact': all(weight > 0 for _, weight in residues),
        'scope': 'exact positive finite-spectral continuum momentum propagator with pole residues, reflection-positive transfer moments, unitary Cayley scattering and normalized dimensionless detector ratios; the unrestricted all-loop interacting Standard Model continuum remains a separate equivalence theorem',
        'theorem_result': exact,
    }


