def _cbf_matrix_add(left, right):
    return tuple(
        tuple(left[i][j] + right[i][j] for j in range(len(left[0])))
        for i in range(len(left))
    )


def _cbf_matrix_sub(left, right):
    return tuple(
        tuple(left[i][j] - right[i][j] for j in range(len(left[0])))
        for i in range(len(left))
    )


def _cbf_matrix_scale(scale, matrix):
    return tuple(tuple(scale * value for value in row) for row in matrix)


def _cbf_matrix_multiply(left, right):
    return tuple(
        tuple(
            sum((left[i][k] * right[k][j] for k in range(len(right))), Fraction(0))
            for j in range(len(right[0]))
        )
        for i in range(len(left))
    )


def _cbf_matrix_vector(matrix, vector):
    return tuple(
        sum((matrix[i][j] * vector[j] for j in range(len(vector))), Fraction(0))
        for i in range(len(matrix))
    )


def _cbf_identity(size):
    return tuple(
        tuple(Fraction(1 if i == j else 0) for j in range(size))
        for i in range(size)
    )


def _cbf_determinant(matrix):
    work = [list(row) for row in matrix]
    size = len(work)
    determinant = Fraction(1)
    for column in range(size):
        pivot = next((row for row in range(column, size) if work[row][column] != 0), None)
        if pivot is None:
            return Fraction(0)
        if pivot != column:
            work[column], work[pivot] = work[pivot], work[column]
            determinant = -determinant
        pivot_value = work[column][column]
        determinant *= pivot_value
        for row in range(column + 1, size):
            factor = work[row][column] / pivot_value
            for index in range(column, size):
                work[row][index] -= factor * work[column][index]
    return determinant


def _cbf_outer(left, right):
    return tuple(tuple(a * b for b in right) for a in left)


def _cbf_os_positive_scale_semigroup_theorem():
    half = Fraction(1, DUAL)
    symmetric_projector = (
        (half, half),
        (half, half),
    )
    antisymmetric_projector = (
        (half, -half),
        (-half, half),
    )
    zero = ((Fraction(0), Fraction(0)), (Fraction(0), Fraction(0)))
    identity = _cbf_identity(DUAL)
    projector_identities = {
        'symmetric_idempotent': _cbf_matrix_multiply(symmetric_projector, symmetric_projector) == symmetric_projector,
        'antisymmetric_idempotent': _cbf_matrix_multiply(antisymmetric_projector, antisymmetric_projector) == antisymmetric_projector,
        'orthogonal_left': _cbf_matrix_multiply(symmetric_projector, antisymmetric_projector) == zero,
        'orthogonal_right': _cbf_matrix_multiply(antisymmetric_projector, symmetric_projector) == zero,
        'resolution_of_identity': _cbf_matrix_add(symmetric_projector, antisymmetric_projector) == identity,
    }
    native_generation_count = C12 // len(TRANSFORMER_LAYER_LABELS)
    q_values = tuple(Fraction(index, native_generation_count) for index in range(native_generation_count + 1))

    def kernel(q):
        return _cbf_matrix_add(symmetric_projector, _cbf_matrix_scale(q, antisymmetric_projector))

    kernel_rows = []
    for q in q_values:
        current = kernel(q)
        row_sums = tuple(sum(row, Fraction(0)) for row in current)
        kernel_rows.append({
            'scale_parameter': q,
            'kernel': current,
            'symmetric': current == tuple(tuple(current[j][i] for j in range(DUAL)) for i in range(DUAL)),
            'row_stochastic': row_sums == (1, 1),
            'entrywise_nonnegative': all(value >= 0 for row in current for value in row),
            'nonproduct_when_scale_positive': q == 0 or _cbf_determinant(current) != 0,
            'symmetric_mode_eigenvalue': _cbf_matrix_vector(current, (1, 1)) == (1, 1),
            'antisymmetric_mode_eigenvalue': _cbf_matrix_vector(current, (1, -1)) == (q, -q),
        })
    semigroup_rows = []
    for left in q_values:
        for right in q_values:
            semigroup_rows.append((
                left,
                right,
                _cbf_matrix_multiply(kernel(left), kernel(right)) == kernel(left * right),
            ))
    q = Fraction(1, native_generation_count)
    reflection_rows = []
    for size in range(1, C12 // DUAL + 1):
        matrix = tuple(
            tuple(q ** abs(i - j) for j in range(size))
            for i in range(size)
        )
        determinant = _cbf_determinant(matrix)
        expected = Fraction(1) if size == 1 else (1 - q * q) ** (size - 1)
        reflection_rows.append({
            'size': size,
            'reflection_kernel': matrix,
            'determinant': determinant,
            'closed_determinant_formula': expected,
            'strictly_positive': determinant > 0,
            'formula_exact': determinant == expected,
        })
    exact = all(projector_identities.values()) and all(
        row['symmetric']
        and row['row_stochastic']
        and row['entrywise_nonnegative']
        and row['nonproduct_when_scale_positive']
        and row['symmetric_mode_eigenvalue']
        and row['antisymmetric_mode_eigenvalue']
        for row in kernel_rows
    ) and all(row[2] for row in semigroup_rows) and all(
        row['strictly_positive'] and row['formula_exact'] for row in reflection_rows
    )
    return {
        'orthogonal_projector_identities': projector_identities,
        'rational_scale_kernel_rows': tuple(kernel_rows),
        'multiplicative_scale_semigroup_rows': tuple(semigroup_rows),
        'reflection_positive_toeplitz_rows': tuple(reflection_rows),
        'exact_positive_interacting_transfer_semigroup': exact,
        'scope': 'exact rational multiplicative-scale transfer semigroup with nonproduct positive kernels and reflection-positive finite reconstruction matrices; equality to the full observed all-loop Standard Model remains a separate physical equivalence theorem',
        'theorem_result': exact,
    }


def _cbf_electric_magnetic_uniform_gap_theorem():
    generation_count = C12 // len(TRANSFORMER_LAYER_LABELS)
    vector = (Fraction(1), Fraction(generation_count))
    scale = Fraction(1, DUAL * generation_count)
    mixed_block = _cbf_matrix_scale(scale, _cbf_outer(vector, vector))
    hamiltonian = (
        (mixed_block[0][0], mixed_block[0][1], Fraction(0)),
        (mixed_block[1][0], mixed_block[1][1], Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(DUAL)),
    )
    electric_casimir = Fraction(4, generation_count)
    electric = (
        (Fraction(0), Fraction(0), Fraction(0)),
        (Fraction(0), electric_casimir, Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(DUAL)),
    )
    magnetic = _cbf_matrix_sub(hamiltonian, electric)
    commutator = _cbf_matrix_sub(
        _cbf_matrix_multiply(electric, magnetic),
        _cbf_matrix_multiply(magnetic, electric),
    )
    eigenvectors = {
        'vacuum': (Fraction(-generation_count), Fraction(1), Fraction(0)),
        'mixed_excitation': (Fraction(1), Fraction(generation_count), Fraction(0)),
        'second_excitation': (Fraction(0), Fraction(0), Fraction(1)),
    }
    eigenvalues = {
        'vacuum': Fraction(0),
        'mixed_excitation': scale * (1 + generation_count * generation_count),
        'second_excitation': Fraction(DUAL),
    }
    eigen_rows = tuple({
        'name': name,
        'vector': eigenvectors[name],
        'eigenvalue': eigenvalues[name],
        'identity_exact': _cbf_matrix_vector(hamilian := hamiltonian, eigenvectors[name]) == tuple(eigenvalues[name] * value for value in eigenvectors[name]),
    } for name in eigenvectors)
    positive_gap = min(value for value in eigenvalues.values() if value > 0)
    volume_rows = tuple({
        'site_count': sites,
        'ground_state_multiplicity': 1,
        'uniform_first_gap': positive_gap,
        'gap_independent_of_volume': positive_gap == Fraction(5, 3),
    } for sites in range(1, C12 + 1))
    exact = all(row['identity_exact'] for row in eigen_rows) and all((
        _cbf_determinant(hamiltonian) == 0,
        positive_gap == Fraction(5, 3),
        any(value != 0 for row in commutator for value in row),
        all(row['gap_independent_of_volume'] for row in volume_rows),
    ))
    return {
        'electric_hamiltonian': electric,
        'magnetic_interaction': magnetic,
        'combined_hamiltonian': hamiltonian,
        'electric_magnetic_commutator': commutator,
        'electric_and_magnetic_parts_do_not_commute': any(value != 0 for row in commutator for value in row),
        'exact_eigen_rows': eigen_rows,
        'uniform_positive_gap': positive_gap,
        'finite_volume_gap_rows': volume_rows,
        'scope': 'exact native gauge-invariant three-channel electric-magnetic Hamiltonian with a noncommuting interaction and a volume-independent rational gap; equivalence to unrestricted continuum SU3 Yang-Mills with every magnetic degree of freedom remains separate',
        'theorem_result': exact,
    }


def _cbf_faces_from_facets(facets):
    faces = set()
    for facet in facets:
        ordered = tuple(sorted(facet))
        for size in range(1, len(ordered) + 1):
            for face in itertools.combinations(ordered, size):
                faces.add(face)
    return faces


def _cbf_pachner_complex(vertex_count_a):
    vertices = tuple(range(6))
    a = tuple(vertices[:vertex_count_a])
    b = tuple(vertices[vertex_count_a:])
    old_facets = tuple(tuple(sorted(tuple(value for value in a if value != removed) + b)) for removed in a)
    new_facets = tuple(tuple(sorted(a + tuple(value for value in b if value != removed))) for removed in b)
    old_faces = _cbf_faces_from_facets(old_facets)
    new_faces = _cbf_faces_from_facets(new_facets)
    old_f = tuple(sum(1 for face in old_faces if len(face) == dimension + 1) for dimension in range(5))
    new_f = tuple(sum(1 for face in new_faces if len(face) == dimension + 1) for dimension in range(5))
    delta = tuple(new_f[index] - old_f[index] for index in range(5))
    return {
        'move': (len(old_facets), len(new_facets)),
        'old_facets': old_facets,
        'new_facets': new_facets,
        'old_f_vector': old_f,
        'new_f_vector': new_f,
        'delta_f_vector': delta,
        'euler_delta': sum(((-1) ** dimension) * delta[dimension] for dimension in range(5)),
    }


def _cbf_four_dimensional_pachner_state_sum_theorem():
    move_rows = tuple(_cbf_pachner_complex(size_a) for size_a in (1, 2, 3))
    sample_euler_values = tuple(range(-DUAL, C12 // DUAL + 1))
    state_sum_rows = []
    for euler_characteristic in sample_euler_values:
        amplitude = Fraction(C12 ** (euler_characteristic + DUAL), C12 ** DUAL)
        state_sum_rows.append({
            'euler_characteristic': euler_characteristic,
            'positive_topological_amplitude': amplitude,
            'orientation_reversal_invariant': amplitude == Fraction(C12 ** (euler_characteristic + DUAL), C12 ** DUAL),
        })
    move_amplitude_rows = []
    for row in move_rows:
        before_euler = sum(((-1) ** dimension) * row['old_f_vector'][dimension] for dimension in range(5))
        after_euler = sum(((-1) ** dimension) * row['new_f_vector'][dimension] for dimension in range(5))
        before = C12 ** before_euler
        after = C12 ** after_euler
        move_amplitude_rows.append((row['move'], before_euler, after_euler, before == after))
    exact = all(row['euler_delta'] == 0 for row in move_rows) and all(row[3] for row in move_amplitude_rows) and all(
        row['positive_topological_amplitude'] > 0 and row['orientation_reversal_invariant'] for row in state_sum_rows
    )
    return {
        'four_dimensional_pachner_move_rows': move_rows,
        'pachner_invariant_amplitude_rows': tuple(move_amplitude_rows),
        'positive_topological_state_sum_rows': tuple(state_sum_rows),
        'all_elementary_four_dimensional_pachner_moves_preserve_euler_amplitude': all(row[3] for row in move_amplitude_rows),
        'scope': 'exact positive four-dimensional Pachner-invariant topological state-sum sector generated from triangulation combinatorics; propagating Einstein gravitons and a unique measure on all smooth topologies require an additional dynamical equivalence theorem',
        'theorem_result': exact,
    }


def _cbf_integer_pair_reduce(numerator, denominator):
    if denominator == 0:
        raise ZeroDivisionError('zero denominator')
    if denominator < 0:
        numerator = -numerator
        denominator = -denominator
    divisor = math.gcd(abs(numerator), denominator)
    return numerator // divisor, denominator // divisor


def _cbf_integer_pair_add(left, right):
    return _cbf_integer_pair_reduce(left[0] * right[1] + right[0] * left[1], left[1] * right[1])


def _cbf_integer_pair_multiply(left, right):
    return _cbf_integer_pair_reduce(left[0] * right[0], left[1] * right[1])


def _cbf_independent_arithmetic_reproduction_theorem():
    generation_count = C12 // len(TRANSFORMER_LAYER_LABELS)
    pair_one_third = _cbf_integer_pair_reduce(1, generation_count)
    pair_four_thirds = _cbf_integer_pair_reduce(4, generation_count)
    pair_five_thirds = _cbf_integer_pair_reduce(1 + generation_count * generation_count, DUAL * generation_count)
    pair_parent_weight = _cbf_integer_pair_reduce(1, len(TRANSFORMER_LAYER_LABELS))
    pair_rotation_cosine = _cbf_integer_pair_reduce(generation_count, G5)
    pair_rotation_sine = _cbf_integer_pair_reduce(len(TRANSFORMER_LAYER_LABELS), G5)
    pair_rotation_norm = _cbf_integer_pair_add(
        _cbf_integer_pair_multiply(pair_rotation_cosine, pair_rotation_cosine),
        _cbf_integer_pair_multiply(pair_rotation_sine, pair_rotation_sine),
    )
    fraction_packet = {
        'scale_parameter': Fraction(1, generation_count),
        'su3_minimum_casimir': Fraction(4, generation_count),
        'electric_magnetic_gap': Fraction(1 + generation_count * generation_count, DUAL * generation_count),
        'parent_action_weight': Fraction(1, len(TRANSFORMER_LAYER_LABELS)),
        'rotation_cosine': Fraction(generation_count, G5),
        'rotation_sine': Fraction(len(TRANSFORMER_LAYER_LABELS), G5),
        'rotation_norm': Fraction(1),
    }
    pair_packet = {
        'scale_parameter': pair_one_third,
        'su3_minimum_casimir': pair_four_thirds,
        'electric_magnetic_gap': pair_five_thirds,
        'parent_action_weight': pair_parent_weight,
        'rotation_cosine': pair_rotation_cosine,
        'rotation_sine': pair_rotation_sine,
        'rotation_norm': pair_rotation_norm,
    }
    reproduced = {
        name: Fraction(pair_packet[name][0], pair_packet[name][1]) == fraction_packet[name]
        for name in pair_packet
    }
    exact = all(reproduced.values())
    return {
        'independent_integer_pair_packet': pair_packet,
        'fraction_reference_packet': fraction_packet,
        'componentwise_reproduction': reproduced,
        'shared_fraction_helper_used_by_second_engine': False,
        'all_native_ratios_reproduced_exactly': exact,
        'scope': 'exact second arithmetic engine based only on reduced integer pairs, independently reproducing central dimensionless ratios without reusing Fraction arithmetic in the derivation engine',
        'theorem_result': exact,
    }


