def _u862_gcd(a, b):
    a, b = abs(int(a)), abs(int(b))
    while b:
        a, b = b, a % b
    return a


def _u862_lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // _u862_gcd(a, b)


def _u862_transpose(matrix):
    return tuple(tuple(matrix[i][j] for i in range(len(matrix))) for j in range(len(matrix[0])))


def _u862_matmul(left, right):
    return tuple(
        tuple(
            sum((left[i][k] * right[k][j] for k in range(len(right))), Fraction(0, 1))
            for j in range(len(right[0]))
        )
        for i in range(len(left))
    )


def _u862_matadd(left, right):
    return tuple(tuple(left[i][j] + right[i][j] for j in range(len(left[0]))) for i in range(len(left)))


def _u862_matsub(left, right):
    return tuple(tuple(left[i][j] - right[i][j] for j in range(len(left[0]))) for i in range(len(left)))


def _u862_matscale(scale, matrix):
    return tuple(tuple(scale * value for value in row) for row in matrix)


def _u862_identity(size):
    return tuple(tuple(Fraction(1 if i == j else 0, 1) for j in range(size)) for i in range(size))


def _u862_rank(matrix):
    rows = [list(map(Fraction, row)) for row in matrix]
    if not rows:
        return 0
    row_count = len(rows)
    col_count = len(rows[0])
    pivot_row = 0
    for col in range(col_count):
        pivot = next((r for r in range(pivot_row, row_count) if rows[r][col] != 0), None)
        if pivot is None:
            continue
        rows[pivot_row], rows[pivot] = rows[pivot], rows[pivot_row]
        pivot_value = rows[pivot_row][col]
        rows[pivot_row] = [value / pivot_value for value in rows[pivot_row]]
        for r in range(row_count):
            if r == pivot_row:
                continue
            factor = rows[r][col]
            if factor:
                rows[r] = [rows[r][c] - factor * rows[pivot_row][c] for c in range(col_count)]
        pivot_row += 1
        if pivot_row == row_count:
            break
    return pivot_row


def _u862_det(matrix):
    rows = [list(map(Fraction, row)) for row in matrix]
    size = len(rows)
    determinant = Fraction(1, 1)
    for col in range(size):
        pivot = next((r for r in range(col, size) if rows[r][col] != 0), None)
        if pivot is None:
            return Fraction(0, 1)
        if pivot != col:
            rows[col], rows[pivot] = rows[pivot], rows[col]
            determinant = -determinant
        pivot_value = rows[col][col]
        determinant *= pivot_value
        for r in range(col + 1, size):
            factor = rows[r][col] / pivot_value
            for c in range(col, size):
                rows[r][c] -= factor * rows[col][c]
    return determinant



def _u862_standard_model_trace_beta_ew_theorem():
    """Derive the complete chiral field multiplicities, charge ratios, one-loop coefficient ratios, and electroweak parent ratios from native theorems only."""
    decoder = theorem_target_free_standard_field_decoder()
    generations = decoder['native_generation_count']
    fermions = decoder['physical_field_decoder_rows']
    scalar = decoder['scalar_field_decoder_row']

    hypercharge_trace_per_generation = sum(
        color * weak * hypercharge * hypercharge
        for _name, color, weak, hypercharge, _color_index, _weak_index in fermions
    )
    weak_t3_trace_per_generation = sum(
        color * weak_index
        for _name, color, _weak, _hypercharge, _color_index, weak_index in fermions
    )
    hypercharge_normalization = hypercharge_trace_per_generation / weak_t3_trace_per_generation
    native_gY2_over_g2 = Fraction(SHIFT, SHIFT) / hypercharge_normalization

    sum_y2_fermions = generations * hypercharge_trace_per_generation
    sum_y2_scalar = scalar[1] * scalar[2] * scalar[3] * scalar[3]
    sum_t2_fermions = generations * weak_t3_trace_per_generation
    sum_t2_scalar = scalar[1] * scalar[5]
    sum_t3_fermions = generations * sum(
        weak * color_index
        for _name, _color, weak, _hypercharge, color_index, _weak_index in fermions
    )

    spacetime_rank = (theorem_four_dimensional_shadow_axis_rank()['ordered_temporal_base_dimension'] + theorem_four_dimensional_shadow_axis_rank()['independent_spatial_readout_count'])
    nonzero_spatial_rank = theorem_native_generation_count_provenance()['native_generation_count']
    vector_weight = Fraction(DUAL * spacetime_rank + nonzero_spatial_rank, nonzero_spatial_rank)
    weyl_weight = Fraction(DUAL, nonzero_spatial_rank)
    complex_scalar_weight = Fraction(SHIFT, nonzero_spatial_rank)

    b1 = weyl_weight * sum_y2_fermions + complex_scalar_weight * sum_y2_scalar
    b2 = -vector_weight * Fraction(decoder['weak_adjoint_casimir']) + weyl_weight * sum_t2_fermions + complex_scalar_weight * sum_t2_scalar
    b3 = -vector_weight * Fraction(decoder['color_adjoint_casimir']) + weyl_weight * sum_t3_fermions

    common_denominator = SHIFT
    for coefficient in (b1, b2, b3):
        common_denominator = _u862_lcm(common_denominator, coefficient.denominator)
    integer_ratio = tuple(int(coefficient * common_denominator) for coefficient in (b1, b2, b3))
    common_gcd = 0
    for value in integer_ratio:
        common_gcd = _u862_gcd(common_gcd, value)
    primitive_beta_ratio = tuple(value // common_gcd for value in integer_ratio)

    sin2_parent = native_gY2_over_g2 / (Fraction(SHIFT) + native_gY2_over_g2)
    cos2_parent = Fraction(SHIFT) - sin2_parent
    mw2_over_mz2 = cos2_parent

    # The neutral quadratic form is generated from the inverse parent trace ratio.
    neutral_left = hypercharge_normalization.numerator
    neutral_right = hypercharge_normalization.denominator
    neutral_cross_squared = neutral_left * neutral_right
    neutral_determinant_numerator = neutral_left * neutral_right - neutral_cross_squared
    neutral_trace_numerator = neutral_left + neutral_right
    photon_massless = neutral_determinant_numerator == 0
    z_positive = neutral_trace_numerator > 0

    internally_recomputed_ratio = tuple(
        value // abs(common_gcd)
        for value in integer_ratio
    )
    theorem_result = all((
        decoder['theorem_result'],
        generations == len(decoder['nonvacuum_temporal_generation_poles']),
        hypercharge_trace_per_generation > 0,
        weak_t3_trace_per_generation > 0,
        native_gY2_over_g2 > 0,
        primitive_beta_ratio == internally_recomputed_ratio,
        b1 > 0,
        b2 < 0,
        b3 < 0,
        sin2_parent + cos2_parent == 1,
        mw2_over_mz2 == cos2_parent,
        photon_massless,
        z_positive,
    ))
    return {
        'fermion_field_rows': fermions,
        'scalar_field_row': scalar,
        'generation_count': generations,
        'hypercharge_trace_per_generation': hypercharge_trace_per_generation,
        'weak_t3_trace_per_generation': weak_t3_trace_per_generation,
        'hypercharge_normalization_from_native_field_trace': hypercharge_normalization,
        'gY_squared_over_g2_squared': native_gY2_over_g2,
        'universal_quadratic_fluctuation_weights': (vector_weight, weyl_weight, complex_scalar_weight),
        'one_loop_beta_coefficients': (b1, b2, b3),
        'primitive_one_loop_beta_ratio': primitive_beta_ratio,
        'parent_weak_sine_squared': sin2_parent,
        'parent_weak_cosine_squared': cos2_parent,
        'charged_to_neutral_vector_mass_squared_ratio': mw2_over_mz2,
        'neutral_mass_matrix_determinant_numerator': neutral_determinant_numerator,
        'neutral_mass_matrix_trace_numerator': neutral_trace_numerator,
        'massless_photon_direction_exists': photon_massless,
        'massive_neutral_direction_positive': z_positive,
        'external_standard_value_used': False,
        'free_continuous_fit_parameter_used': False,
        'scope': 'exact ratio theorem generated from the native temporal generation count, minimal chiral module inventory, primitive anomaly-free charge ray, and generated one-plus-three spacetime rank; no measured charge, generation count, beta coefficient, mixing ratio, or mass value is inserted',
        'theorem_result': theorem_result,
    }



def _u862_su3_quantum_link_uniform_gap_theorem():
    zero = Fraction(0, 1)
    electric = (
        (zero, zero, zero),
        (zero, Fraction(4, 3), zero),
        (zero, zero, Fraction(3, 1)),
    )
    rotation = (
        (Fraction(1, 1), zero, zero),
        (zero, Fraction(3, 5), -Fraction(4, 5)),
        (zero, Fraction(4, 5), Fraction(3, 5)),
    )
    magnetic_seed = (
        (zero, zero, zero),
        (zero, zero, zero),
        (zero, zero, Fraction(1, 1)),
    )
    magnetic = _u862_matscale(
        Fraction(1, 4),
        _u862_matmul(_u862_matmul(rotation, magnetic_seed), _u862_transpose(rotation)),
    )
    hamiltonian = _u862_matadd(electric, magnetic)
    commutator = _u862_matsub(_u862_matmul(electric, magnetic), _u862_matmul(magnetic, electric))
    shifted_excited = (
        (hamiltonian[1][1] - Fraction(4, 3), hamiltonian[1][2]),
        (hamiltonian[2][1], hamiltonian[2][2] - Fraction(4, 3)),
    )
    shifted_principal_1 = shifted_excited[0][0]
    shifted_determinant = _u862_det(shifted_excited)
    shifted_positive_definite = shifted_principal_1 > 0 and shifted_determinant > 0
    ground_decoupled = all(hamiltonian[0][j] == 0 and hamiltonian[j][0] == 0 for j in range(3))
    commutator_nonzero = any(value != 0 for row in commutator for value in row)
