def _u880_time_origin_data():
    depths = tuple(range(len(_u876_projection_frame_data()[0])))
    branch_counts = tuple(DUAL ** depth for depth in depths)
    new_residual_counts = tuple(
        SHIFT if depth == 0 else branch_counts[depth] - SHIFT
        for depth in depths
    )
    cumulative_levels = [Fraction(SHIFT)]
    genesis_rows = [(0, branch_counts[0], new_residual_counts[0], cumulative_levels[0])]
    for depth in depths[SHIFT:]:
        cumulative_levels.append(cumulative_levels[-SHIFT] + new_residual_counts[depth])
        genesis_rows.append((depth, branch_counts[depth], new_residual_counts[depth], cumulative_levels[-SHIFT]))
    cumulative_levels = tuple(cumulative_levels)
    temporal_poles = tuple(Fraction(SHIFT, branch_count) for branch_count in branch_counts)
    level_total = sum(cumulative_levels, Fraction(0))
    positive_residues = tuple(level / level_total for level in cumulative_levels)
    elementary_one = sum(temporal_poles, Fraction(0))
    elementary_two = sum(
        (temporal_poles[left] * temporal_poles[right] for left in range(len(temporal_poles)) for right in range(left + SHIFT, len(temporal_poles))),
        Fraction(0),
    )
    elementary_three = sum(
        (
            temporal_poles[first] * temporal_poles[second] * temporal_poles[third]
            for first in range(len(temporal_poles))
            for second in range(first + SHIFT, len(temporal_poles))
            for third in range(second + SHIFT, len(temporal_poles))
        ),
        Fraction(0),
    )
    elementary_four = temporal_poles[0] * temporal_poles[1] * temporal_poles[2] * temporal_poles[3]
    recurrence_coefficients = (elementary_one, elementary_two, elementary_three, elementary_four)
    moments = tuple(
        sum(
            (positive_residues[index] * temporal_poles[index] ** order for index in range(len(temporal_poles))),
            Fraction(0),
        )
        for order in range(ROUTE_TRIPLET * C12)
    )
    return {
        'depths': depths,
        'branch_counts': branch_counts,
        'new_residual_counts': new_residual_counts,
        'cumulative_levels': cumulative_levels,
        'genesis_rows': tuple(genesis_rows),
        'temporal_poles': temporal_poles,
        'positive_residues': positive_residues,
        'recurrence_coefficients': recurrence_coefficients,
        'moments': moments,
    }


