def _u880_temporal_lorentzian_mass_theorem():
    """Generate a positive mass form from temporal correlations and a one-time-plus-three-residual Lorentzian form, then prove exact preservation under complete force projection."""
    data = _u880_time_origin_data()
    moments = data['moments']
    difference = _u880_temporal_difference_matrix()
    difference_inverse = _u878_matrix_inverse(difference)
    labels, force_frame, force_inverse = _u876_projection_frame_data()
    normalized_force = _u876_scale(Fraction(SHIFT, DUAL), force_frame)
    normalized_inverse = _u876_transpose(normalized_force)
    lorentzian_residual_metric = (
        (Fraction(-SHIFT), Fraction(0), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(SHIFT), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(SHIFT), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(0), Fraction(SHIFT)),
    )
    force_lorentzian_metric = _u876_multiply(_u876_multiply(normalized_force, lorentzian_residual_metric), normalized_inverse)
    temporal_mass = tuple(tuple(moments[row + column] for column in range(len(force_frame))) for row in range(len(force_frame)))
    leading_minors = tuple(
        _u877_determinant(tuple(tuple(temporal_mass[row][column] for column in range(size)) for row in range(size)))
        for size in range(SHIFT, len(force_frame) + SHIFT)
    )
    force_to_temporal = _u876_multiply(difference_inverse, normalized_inverse)
    force_mass = _u876_multiply(_u876_multiply(_u876_transpose(force_to_temporal), temporal_mass), force_to_temporal)
    rows = []
    for start in range(DUAL * C12):
        temporal_window = tuple(moments[start + offset] for offset in range(len(force_frame)))
        residual_coordinates = _u876_matvec(difference, temporal_window)
        force_coordinates = _u876_matvec(normalized_force, residual_coordinates)
        temporal_mass_value = _u880_quadratic(temporal_mass, temporal_window)
        force_mass_value = _u880_quadratic(force_mass, force_coordinates)
        residual_interval = _u880_quadratic(lorentzian_residual_metric, residual_coordinates)
        force_interval = _u880_quadratic(force_lorentzian_metric, force_coordinates)
        rows.append((start, temporal_mass_value, force_mass_value, residual_interval, force_interval, temporal_mass_value == force_mass_value, residual_interval == force_interval, temporal_mass_value > 0))
    theorem_result = all((
        all(minor > 0 for minor in leading_minors),
        _u877_determinant(lorentzian_residual_metric) == -SHIFT,
        _u877_determinant(force_lorentzian_metric) == -SHIFT,
        _u876_multiply(normalized_inverse, normalized_force) == _u876_identity(len(force_frame)),
        all(row[-3] and row[-2] and row[-1] for row in rows),
    ))
    return {
        'proof_title': 'TEMPORAL LORENTZIAN MASS THEOREM',
        'force_labels': labels,
        'temporal_hankel_mass_operator': temporal_mass,
        'positive_mass_leading_minors': leading_minors,
        'residual_lorentzian_metric': lorentzian_residual_metric,
        'force_lorentzian_metric': force_lorentzian_metric,
        'force_mass_operator': force_mass,
        'mass_and_interval_covariance_rows': tuple(rows),
        'scope': 'exact positive quadratic mass form derived from one scalar time-correlation stream and exact one-primary-time plus three-generated-residual Lorentzian form, both transported without loss to the complete force coordinates',
        'actual_si_mass_and_unrestricted_spacetime_identity': False,
        'theorem_result': theorem_result,
    }


def _u880_temporal_variational_action_theorem():
    """Derive the companion evolution as the unique zero of a positive temporal action and prove exact variational equivalence after residual and force projection."""
    data = _u880_time_origin_data()
    moments = data['moments']
    companion = _u880_temporal_companion_matrix()
    difference = _u880_temporal_difference_matrix()
    labels, force_frame, force_inverse = _u876_projection_frame_data()
    normalized_force = _u876_scale(Fraction(SHIFT, DUAL), force_frame)
    temporal_to_force = _u876_multiply(normalized_force, difference)
    force_to_temporal = _u878_matrix_inverse(temporal_to_force)
    force_companion = _u876_multiply(_u876_multiply(temporal_to_force, companion), force_to_temporal)
    temporal_mass = tuple(tuple(moments[row + column] for column in range(len(force_frame))) for row in range(len(force_frame)))
    force_mass = _u876_multiply(_u876_multiply(_u876_transpose(force_to_temporal), temporal_mass), force_to_temporal)
    offsets = (
        (Fraction(SHIFT), Fraction(0), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(SHIFT), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(SHIFT), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(0), Fraction(SHIFT)),
        (Fraction(-SHIFT), Fraction(SHIFT), Fraction(0), Fraction(0)),
        (Fraction(SHIFT), Fraction(-DUAL), Fraction(SHIFT), Fraction(0)),
    )
    rows = []
    for start in range(DUAL * C12):
        current = tuple(moments[start + offset] for offset in range(len(force_frame)))
        unique_target = _u876_matvec(companion, current)
        current_force = _u876_matvec(temporal_to_force, current)
        force_target = _u876_matvec(force_companion, current_force)
        target_covariance = _u876_matvec(temporal_to_force, unique_target) == force_target
        zero_action = _u880_quadratic(temporal_mass, tuple(Fraction(0) for _ in range(len(force_frame))))
        offset_rows = []
        for offset in offsets:
            candidate = tuple(unique_target[index] + offset[index] for index in range(len(force_frame)))
            difference_vector = tuple(candidate[index] - unique_target[index] for index in range(len(force_frame)))
            temporal_action = _u880_quadratic(temporal_mass, difference_vector)
            candidate_force = _u876_matvec(temporal_to_force, candidate)
            force_difference = tuple(candidate_force[index] - force_target[index] for index in range(len(force_frame)))
            force_action = _u880_quadratic(force_mass, force_difference)
            offset_rows.append((offset, temporal_action, force_action, temporal_action == force_action, temporal_action > zero_action))
        rows.append((start, current, unique_target, current_force, force_target, target_covariance, zero_action, tuple(offset_rows), all(row[-2] and row[-1] for row in offset_rows)))
    theorem_result = all((
        all(minor > 0 for minor in _u880_temporal_lorentzian_mass_theorem()['positive_mass_leading_minors']),
        all(row[-3] == 0 for row in rows),
        all(row[-4] and row[-1] for row in rows),
        _u876_multiply(_u876_multiply(force_to_temporal, force_companion), temporal_to_force) == companion,
    ))
    return {
        'proof_title': 'TEMPORAL VARIATIONAL ACTION THEOREM',
        'temporal_companion_matrix': companion,
        'force_companion_matrix': force_companion,
        'temporal_positive_action_metric': temporal_mass,
        'force_positive_action_metric': force_mass,
        'all_variational_evolution_rows': tuple(rows),
        'scope': 'exact positive least-action characterization of the unique temporal companion step and exact equality of that action after residual generation and complete four-force projection',
        'theorem_result': theorem_result,
    }


