# ---------- exact Gaussian-rational matrix algebra ----------
def _u863_cadd(a,b): return (a[0]+b[0],a[1]+b[1])
def _u863_cneg(a): return (-a[0],-a[1])
def _u863_csub(a,b): return _u863_cadd(a,_u863_cneg(b))
def _u863_cmul(a,b): return (a[0]*b[0]-a[1]*b[1],a[0]*b[1]+a[1]*b[0])
def _u863_cconj(a): return (a[0],-a[1])
def _u863_C(x=0,y=0): return (Fraction(x),Fraction(y))
_u863_C0=_u863_C(0); _u863_C1=_u863_C(1); _u863_CI=_u863_C(0,1)

def _u863_cmat_zero(n,m): return tuple(tuple(_u863_C0 for _ in range(m)) for _ in range(n))
def _u863_cmat_id(n): return tuple(tuple(_u863_C1 if i==j else _u863_C0 for j in range(n)) for i in range(n))
def _u863_cmat_add(A,B): return tuple(tuple(_u863_cadd(A[i][j],B[i][j]) for j in range(len(A[0]))) for i in range(len(A)))
def _u863_cmat_scale(s,A): return tuple(tuple(_u863_cmul(s,x) for x in row) for row in A)
def _u863_cmat_mul(A,B):
    return tuple(tuple(_u863_sum_c((_u863_cmul(A[i][k],B[k][j]) for k in range(len(B)))) for j in range(len(B[0]))) for i in range(len(A)))
def _u863_sum_c(xs):
    z=_u863_C0
    for x in xs:z=_u863_cadd(z,x)
    return z
def _u863_cmat_dag(A): return tuple(tuple(_u863_cconj(A[j][i]) for j in range(len(A))) for i in range(len(A[0])))
def _u863_ckron(A,B):
    return tuple(tuple(_u863_cmul(A[i//len(B)][j//len(B[0])],B[i%len(B)][j%len(B[0])]) for j in range(len(A[0])*len(B[0]))) for i in range(len(A)*len(B)))

def _u863_wilson_dirac_theorem():
    s1=((_u863_C0,_u863_C1),(_u863_C1,_u863_C0))
    s2=((_u863_C0,_u863_cneg(_u863_CI)),(_u863_CI,_u863_C0))
    s3=((_u863_C1,_u863_C0),(_u863_C0,_u863_C(-1)))
    i2=_u863_cmat_id(2)
    gammas=(_u863_ckron(s1,s1),_u863_ckron(s1,s2),_u863_ckron(s1,s3),_u863_ckron(s2,i2))
    gamma5=_u863_ckron(s3,i2)
    I4=_u863_cmat_id(4)
    cliff=[]
    for mu in range(4):
        for nu in range(4):
            anti=_u863_cmat_add(_u863_cmat_mul(gammas[mu],gammas[nu]),_u863_cmat_mul(gammas[nu],gammas[mu]))
            expected=_u863_cmat_scale(_u863_C(2 if mu==nu else 0),I4)
            cliff.append((mu,nu,anti==expected))
    g5sq=_u863_cmat_mul(gamma5,gamma5)==I4
    g5anti=all(_u863_cmat_add(_u863_cmat_mul(gamma5,g),_u863_cmat_mul(g,gamma5))==_u863_cmat_zero(4,4) for g in gammas)
    corners=[]
    for code in range(16):
        bits=tuple((code>>mu)&1 for mu in range(4))
        k=sum(bits)
        mass=Fraction(2*k,1)
        D=_u863_cmat_scale(_u863_C(mass),I4)
        det=mass**4
        corners.append((bits,k,mass,det,det==0))
    unique_zero=sum(1 for row in corners if row[-1])==1 and corners[0][-1]
    # noncorner rational unit-circle samples: (sin,cos)=(0,1),(3/5,4/5),(4/5,3/5)
    pairs=((Fraction(0),Fraction(1)),(Fraction(3,5),Fraction(4,5)),(Fraction(4,5),Fraction(3,5)))
    samples=[]
    for a in range(3):
      sc=tuple(pairs[(a+mu)%3] for mu in range(4))
      scalar=sum((1-c for s,c in sc),Fraction(0))
      D=_u863_cmat_scale(_u863_C(scalar),I4)
      for mu,(s,c) in enumerate(sc):
          D=_u863_cmat_add(D,_u863_cmat_scale(_u863_C(0,s),gammas[mu]))
      lhs=_u863_cmat_dag(D)
      rhs=_u863_cmat_mul(_u863_cmat_mul(gamma5,D),gamma5)
      samples.append((sc,lhs==rhs))
    result=all(x[2] for x in cliff) and g5sq and g5anti and unique_zero and all(x[1] for x in samples)
    return {'clifford_rows':tuple(cliff),'gamma5_squared_identity':g5sq,'gamma5_anticommutes':g5anti,'corner_rows':tuple(corners),'unique_massless_corner':unique_zero,'gamma5_hermiticity_samples':tuple(samples),'theorem_result':result}

# ---------- sparse polynomial algebra in four momentum components ----------
def _u863_pclean(p): return {m:c for m,c in p.items() if c}
def _u863_padd(a,b):
    out=dict(a)
    for m,c in b.items(): out[m]=out.get(m,Fraction(0))+c
    return _u863_pclean(out)
def _u863_pscale(s,a): return _u863_pclean({m:s*c for m,c in a.items()})
def _u863_pmul(a,b):
    out={}
    for ma,ca in a.items():
      for mb,cb in b.items():
        m=tuple(ma[i]+mb[i] for i in range(4));out[m]=out.get(m,Fraction(0))+ca*cb
    return _u863_pclean(out)
def _u863_pzero(): return {}
def _u863_pone(c=1): return {(0,0,0,0):Fraction(c)} if c else {}
def _u863_kvar(i):
    e=[0,0,0,0];e[i]=1;return {tuple(e):Fraction(1)}

def _u863_einstein_poly(h):
    eta=(-1,1,1,1);k=tuple(_u863_kvar(i) for i in range(4))
    k2=_u863_pzero()
    for r in range(4): k2=_u863_padd(k2,_u863_pscale(Fraction(eta[r]),_u863_pmul(k[r],k[r])))
    trace=_u863_pzero()
    for r in range(4): trace=_u863_padd(trace,_u863_pscale(Fraction(eta[r]),h[r][r]))
    divdiv=_u863_pzero()
    for r in range(4):
      for s in range(4):
        divdiv=_u863_padd(divdiv,_u863_pscale(Fraction(eta[r]*eta[s]),_u863_pmul(_u863_pmul(k[r],k[s]),h[r][s])))
    G=[[_u863_pzero() for _ in range(4)] for _ in range(4)]
    for mu in range(4):
      for nu in range(4):
        val=_u863_pzero()
        for s in range(4):
          val=_u863_padd(val,_u863_pscale(Fraction(eta[s]),_u863_pmul(_u863_pmul(k[s],k[nu]),h[s][mu])))
          val=_u863_padd(val,_u863_pscale(Fraction(eta[s]),_u863_pmul(_u863_pmul(k[s],k[mu]),h[s][nu])))
        val=_u863_padd(val,_u863_pscale(Fraction(-1),_u863_pmul(k2,h[mu][nu])))
        val=_u863_padd(val,_u863_pscale(Fraction(-1),_u863_pmul(_u863_pmul(k[mu],k[nu]),trace)))
        if mu==nu:
          val=_u863_padd(val,_u863_pscale(Fraction(-eta[mu]),_u863_padd(divdiv,_u863_pscale(Fraction(-1),_u863_pmul(k2,trace)))))
        G[mu][nu]=_u863_pscale(Fraction(1,2),val)
    return tuple(tuple(x for x in row) for row in G)

def _u863_linearized_einstein_theorem():
    eta=(-1,1,1,1);k=tuple(_u863_kvar(i) for i in range(4))
    gauge_rows=[]
    for xi_idx in range(4):
      h=[[_u863_pzero() for _ in range(4)] for _ in range(4)]
      for mu in range(4):
       for nu in range(4):
        val=_u863_pzero()
        if nu==xi_idx: val=_u863_padd(val,k[mu])
        if mu==xi_idx: val=_u863_padd(val,k[nu])
        h[mu][nu]=val
      G=_u863_einstein_poly(h)
      gauge_rows.append((xi_idx,all(not G[mu][nu] for mu in range(4) for nu in range(4))))
    order=[(mu,nu) for mu in range(4) for nu in range(mu,4)]
    bianchi_rows=[]
    for pair in order:
      h=[[_u863_pzero() for _ in range(4)] for _ in range(4)]
      mu,nu=pair;h[mu][nu]=_u863_pone();h[nu][mu]=_u863_pone()
      G=_u863_einstein_poly(h)
      residual=[]
      for nu2 in range(4):
        val=_u863_pzero()
        for mu2 in range(4): val=_u863_padd(val,_u863_pscale(Fraction(eta[mu2]),_u863_pmul(k[mu2],G[mu2][nu2])))
        residual.append(val)
      bianchi_rows.append((pair,all(not x for x in residual)))
    symmetry_rows=[]
    # E output is symmetric for every basis
    for pair in order:
      h=[[_u863_pzero() for _ in range(4)] for _ in range(4)];mu,nu=pair;h[mu][nu]=_u863_pone();h[nu][mu]=_u863_pone();G=_u863_einstein_poly(h)
      symmetry_rows.append((pair,all(G[i][j]==G[j][i] for i in range(4) for j in range(4))))
    result=all(r[1] for r in gauge_rows+bianchi_rows+symmetry_rows)
    return {'gauge_nil_rows':tuple(gauge_rows),'bianchi_rows':tuple(bianchi_rows),'symmetry_rows':tuple(symmetry_rows),'theorem_result':result}

# ---------- Laurent polynomial / Hopf renormalization algebra ----------
def _u863_lclean(p): return {e:c for e,c in p.items() if c}
def _u863_ladd(a,b):
    o=dict(a)
    for e,c in b.items():o[e]=o.get(e,Fraction(0))+c
    return _u863_lclean(o)
def _u863_lmul(a,b):
    o={}
    for ea,ca in a.items():
      for eb,cb in b.items():o[ea+eb]=o.get(ea+eb,Fraction(0))+ca*cb
    return _u863_lclean(o)
def _u863_lpown(a,n):
    out={0:Fraction(1)}
    for _ in range(n):out=_u863_lmul(out,a)
    return out
def _u863_lscale(s,a):return _u863_lclean({e:s*c for e,c in a.items()})

def _u863_hopf_renormalization_theorem():
    coassoc=[];antipode=[]
    for n in range(0,17):
      triples=[]
      ok=True
      for a in range(n+1):
       for b in range(n-a+1):
        c=n-a-b
        left=math.comb(n,a+b)*math.comb(a+b,a)
        right=math.comb(n,a)*math.comb(n-a,b)
        ok=ok and left==right
        triples.append((a,b,c,left,right,left==right))
      coassoc.append((n,tuple(triples),ok))
      conv=sum(Fraction(math.comb(n,k)*((-1)**k)) for k in range(n+1))
      antipode.append((n,conv,conv==(1 if n==0 else 0)))
    phi={-1:Fraction(1),0:Fraction(1)}
    phiminus={-1:Fraction(-1)}
    ren_rows=[]
    for n in range(0,13):
      conv={}
      for k in range(n+1):
        term=_u863_lmul(_u863_lpown(phiminus,k),_u863_lpown(phi,n-k))
        term=_u863_lscale(Fraction(math.comb(n,k)),term)
        conv=_u863_ladd(conv,term)
      ren_rows.append((n,conv,conv=={0:Fraction(1)}))
    result=all(r[2] for r in coassoc) and all(r[2] for r in antipode) and all(r[2] for r in ren_rows)
    return {'coassociativity_rows':tuple(coassoc),'antipode_rows':tuple(antipode),'birkhoff_renormalized_character_rows':tuple(ren_rows),'theorem_result':result}

# ---------- sl3 Chevalley BRST _u863_ghost nilpotency ----------
def _u863_rmatmul(A,B):return tuple(tuple(sum((A[i][k]*B[k][j] for k in range(len(B))),Fraction(0)) for j in range(len(B[0]))) for i in range(len(A)))
def _u863_rmatsub(A,B):return tuple(tuple(A[i][j]-B[i][j] for j in range(len(A[0]))) for i in range(len(A)))
def _u863_bracket(A,B):return _u863_rmatsub(_u863_rmatmul(A,B),_u863_rmatmul(B,A))
def _u863_M(entries):
    A=[[Fraction(0) for _ in range(3)] for _ in range(3)]
    for (i,j),v in entries.items():A[i][j]=Fraction(v)
    return tuple(tuple(r) for r in A)
def _u863_sl3_basis():
    return (_u863_M({(0,1):1}),_u863_M({(1,0):1}),_u863_M({(1,2):1}),_u863_M({(2,1):1}),_u863_M({(0,2):1}),_u863_M({(2,0):1}),_u863_M({(0,0):1,(1,1):-1}),_u863_M({(1,1):1,(2,2):-1}))
def _u863_coords(A):
    out=[A[0][1],A[1][0],A[1][2],A[2][1],A[0][2],A[2][0],A[0][0],-A[2][2]]
    recon=_u863_M({(0,1):out[0],(1,0):out[1],(1,2):out[2],(2,1):out[3],(0,2):out[4],(2,0):out[5],(0,0):out[6],(1,1):-out[6]+out[7],(2,2):-out[7]})
    assert recon==A
    return tuple(out)
def _u863_wedge_sign(mask1,mask2):
    if mask1 & mask2:return 0
    inv=0
    for i in range(8):
      if (mask1>>i)&1:
       inv+=sum(1 for j in range(i) if (mask2>>j)&1)
    return -1 if inv%2 else 1
def _u863_ewedge(a,b):
    o={}
    for ma,ca in a.items():
      for mb,cb in b.items():
       s=_u863_wedge_sign(ma,mb)
       if s:o[ma|mb]=o.get(ma|mb,Fraction(0))+ca*cb*s
    return {m:c for m,c in o.items() if c}
def _u863_eadd(a,b):
    o=dict(a)
    for m,c in b.items():o[m]=o.get(m,Fraction(0))+c
    return {m:c for m,c in o.items() if c}
def _u863_escale(s,a):return {m:s*c for m,c in a.items() if s*c}
def _u863_ghost(i):return {1<<i:Fraction(1)}

def _u863_brst_theorem():
    B=_u863_sl3_basis();f=[[[Fraction(0) for _ in range(8)] for _ in range(8)] for _ in range(8)]
    jacobi=True
    for b in range(8):
      for c in range(8):
        co=_u863_coords(_u863_bracket(B[b],B[c]))
        for a in range(8):f[a][b][c]=co[a]
    # Jacobi via structure constants
    jac_rows=[]
    for a in range(8):
      for b in range(8):
       for c in range(8):
        for d in range(8):
          val=sum((f[e][a][b]*f[d][e][c]+f[e][b][c]*f[d][e][a]+f[e][c][a]*f[d][e][b] for e in range(8)),Fraction(0))
          if val:jacobi=False
    sc=[]
    for a in range(8):
      val={}
      for b in range(8):
       for c in range(8):
        if f[a][b][c]:val=_u863_eadd(val,_u863_escale(Fraction(-1,2)*f[a][b][c],_u863_ewedge(_u863_ghost(b),_u863_ghost(c))))
      sc.append(val)
    def s_monomial(mask):
      inds=[i for i in range(8) if (mask>>i)&1]
      total={}
      for pos,i in enumerate(inds):
        left={0:Fraction(1)}
        for j in inds[:pos]:left=_u863_ewedge(left,_u863_ghost(j))
        right={0:Fraction(1)}
        for j in inds[pos+1:]:right=_u863_ewedge(right,_u863_ghost(j))
        term=_u863_ewedge(_u863_ewedge(left,sc[i]),right)
        total=_u863_eadd(total,_u863_escale(Fraction(-1 if pos%2 else 1),term))
      return total
    def s_elem(elem):
      total={}
      for mask,coef in elem.items():total=_u863_eadd(total,_u863_escale(coef,s_monomial(mask)))
      return total
    nil=[]
    for a in range(8):
      s2=s_elem(sc[a]);nil.append((a,s2,not s2))
    result=jacobi and all(r[2] for r in nil)
    return {'jacobi_exact':jacobi,'brst_ghost_variations':tuple(sc),'brst_squared_rows':tuple(nil),'theorem_result':result}




