class _GateNullWriter:
    def write(self, text):
        return len(text)

    def flush(self):
        return None


def _gate_primary_worker(function_name: str) -> int:
    function = globals().get(function_name)
    if function_name not in ORDERED_PRIMARY_THEOREM_ROOTS or not callable(function):
        return 2
    result = function()
    passed, _ = _root_theorem_gate(function_name, result)
    return 0 if passed else 3


def _gate_narrative_worker(index: int) -> int:
    if index < 0 or index >= len(THEOREM_ROOTS):
        return 2
    function = globals().get(THEOREM_ROOTS[index])
    if not callable(function):
        return 3
    with contextlib.redirect_stdout(_GateNullWriter()):
        function()
    return 0


