def _u864_rat_const(value):
    return _scr_rat(_scr_poly_constant(value))


def _u864_rat_var(axis):
    return _scr_rat(_scr_poly_variable(axis))


def _u864_rat_neg(value):
    return _scr_rat_scale(Fraction(-1), value)


def _u864_rat_sub(left, right):
    return _scr_rat_add(left, _u864_rat_neg(right))


def _u864_rat_inv(value):
    if not value[0]:
        raise ZeroDivisionError('zero rational function')
    return _scr_rat(value[1], value[0])


def _u864_rat_div(left, right):
    return _scr_rat_mul(left, _u864_rat_inv(right))


def _u864_rat_pow(value, exponent):
    result = _u864_rat_const(1)
    for _ in range(exponent):
        result = _scr_rat_mul(result, value)
    return result


def _u864_rat_coord_derivative(value, coordinate):
    if coordinate == 1:
        return _scr_rat_derivative(value, 0)
    if coordinate == 2:
        return _scr_rat_derivative(value, 1)
    return _u864_rat_const(0)


def _u864_schwarzschild_full_ricci_packet():
    variable_count = 3
    zero_power = (0, 0, 0)

    def poly_clean(poly):
        return {power: Fraction(value) for power, value in poly.items() if value}

    def poly_constant(value):
        value = Fraction(value)
        return {} if value == 0 else {zero_power: value}

    def poly_variable(axis):
        power = [0, 0, 0]
        power[axis] = 1
        return {tuple(power): Fraction(1)}

    def poly_add(left, right):
        result = dict(left)
        for power, value in right.items():
            result[power] = result.get(power, Fraction(0)) + value
        return poly_clean(result)

    def poly_neg(value):
        return {power: -coefficient for power, coefficient in value.items()}

    def poly_sub(left, right):
        return poly_add(left, poly_neg(right))

    def poly_mul(left, right):
        result = {}
        for left_power, left_value in left.items():
            for right_power, right_value in right.items():
                power = tuple(left_power[index] + right_power[index] for index in range(variable_count))
                result[power] = result.get(power, Fraction(0)) + left_value * right_value
        return poly_clean(result)

    def poly_derivative(value, axis):
        result = {}
        for power, coefficient in value.items():
            if power[axis]:
                reduced = list(power)
                factor = reduced[axis]
                reduced[axis] -= 1
                result[tuple(reduced)] = coefficient * factor
        return poly_clean(result)

    def rat(numerator, denominator=None):
        if not isinstance(numerator, dict):
            numerator = poly_constant(numerator)
        if denominator is None:
            denominator = poly_constant(1)
        elif not isinstance(denominator, dict):
            denominator = poly_constant(denominator)
        if not denominator:
            raise ZeroDivisionError('zero rational denominator')
        if not numerator:
            return ({}, poly_constant(1))
        leading = max(denominator)
        if denominator[leading] < 0:
            numerator = poly_neg(numerator)
            denominator = poly_neg(denominator)
        return (poly_clean(numerator), poly_clean(denominator))

    def rat_add(left, right):
        return rat(
            poly_add(poly_mul(left[0], right[1]), poly_mul(right[0], left[1])),
            poly_mul(left[1], right[1]),
        )

    def rat_neg(value):
        return rat(poly_neg(value[0]), value[1])

    def rat_sub(left, right):
        return rat_add(left, rat_neg(right))

    def rat_mul(left, right):
        return rat(poly_mul(left[0], right[0]), poly_mul(left[1], right[1]))

    def rat_inv(value):
        if not value[0]:
            raise ZeroDivisionError('zero rational function')
        return rat(value[1], value[0])

    def rat_div(left, right):
        return rat_mul(left, rat_inv(right))

    def rat_scale(scale, value):
        return rat({power: Fraction(scale) * coefficient for power, coefficient in value[0].items()}, value[1])

    def rat_derivative(value, axis):
        return rat(
            poly_sub(
                poly_mul(poly_derivative(value[0], axis), value[1]),
                poly_mul(value[0], poly_derivative(value[1], axis)),
            ),
            poly_mul(value[1], value[1]),
        )

    def rat_equal(left, right):
        return not poly_sub(poly_mul(left[0], right[1]), poly_mul(right[0], left[1]))

    def rat_zero(value):
        return not value[0]

    r = rat(poly_variable(0))
    x = rat(poly_variable(1))
    mass = rat(poly_variable(2))
    one = rat(1)
    zero = rat(0)
    lapse = rat_div(rat_sub(r, rat_scale(2, mass)), r)
    angular = rat_sub(one, rat_mul(x, x))
    metric = [[zero for _ in range(4)] for _ in range(4)]
    inverse = [[zero for _ in range(4)] for _ in range(4)]
    metric[0][0] = rat_neg(lapse)
    inverse[0][0] = rat_neg(rat_inv(lapse))
    metric[1][1] = rat_inv(lapse)
    inverse[1][1] = lapse
    metric[2][2] = rat_div(rat_mul(r, r), angular)
    inverse[2][2] = rat_div(angular, rat_mul(r, r))
    metric[3][3] = rat_mul(rat_mul(r, r), angular)
    inverse[3][3] = rat_inv(metric[3][3])

    def coordinate_derivative(value, coordinate):
        if coordinate == 1:
            return rat_derivative(value, 0)
        if coordinate == 2:
            return rat_derivative(value, 1)
        return zero

    christoffel = [[[zero for _ in range(4)] for _ in range(4)] for _ in range(4)]
    for rho in range(4):
        for mu in range(4):
            for nu in range(4):
                entry = zero
                for sigma in range(4):
                    bracket = rat_add(
                        rat_add(
                            coordinate_derivative(metric[sigma][nu], mu),
                            coordinate_derivative(metric[sigma][mu], nu),
                        ),
                        rat_neg(coordinate_derivative(metric[mu][nu], sigma)),
                    )
                    entry = rat_add(entry, rat_scale(Fraction(1, 2), rat_mul(inverse[rho][sigma], bracket)))
                christoffel[rho][mu][nu] = entry

    ricci = [[zero for _ in range(4)] for _ in range(4)]
    for mu in range(4):
        for nu in range(4):
            entry = zero
            for rho in range(4):
                entry = rat_add(entry, coordinate_derivative(christoffel[rho][mu][nu], rho))
                entry = rat_sub(entry, coordinate_derivative(christoffel[rho][mu][rho], nu))
                for sigma in range(4):
                    entry = rat_add(entry, rat_mul(christoffel[rho][rho][sigma], christoffel[sigma][mu][nu]))
                    entry = rat_sub(entry, rat_mul(christoffel[rho][nu][sigma], christoffel[sigma][mu][rho]))
            ricci[mu][nu] = entry

    def riemann_component(rho, sigma, mu, nu):
        entry = rat_sub(
            coordinate_derivative(christoffel[rho][nu][sigma], mu),
            coordinate_derivative(christoffel[rho][mu][sigma], nu),
        )
        for lam in range(4):
            entry = rat_add(entry, rat_mul(christoffel[rho][mu][lam], christoffel[lam][nu][sigma]))
            entry = rat_sub(entry, rat_mul(christoffel[rho][nu][lam], christoffel[lam][mu][sigma]))
        return entry

    selected_curvature = riemann_component(1, 0, 1, 0)
    ricci_rows = tuple((mu, nu, rat_zero(ricci[mu][nu])) for mu in range(4) for nu in range(4))
    theorem_result = all(row[2] for row in ricci_rows) and not rat_zero(selected_curvature)
    return {
        'coordinate_chart': '(time, radius, cosine_polar_angle, azimuth)',
        'dimensionless_mass_symbol_is_internal_scale_variable': True,
        'nonzero_christoffel_component_count': sum(not rat_zero(christoffel[rho][mu][nu]) for rho in range(4) for mu in range(4) for nu in range(4)),
        'ricci_zero_rows': ricci_rows,
        'all_sixteen_ricci_components_zero': all(row[2] for row in ricci_rows),
        'selected_riemann_component_nonzero': not rat_zero(selected_curvature),
        'selected_riemann_numerator_term_count': len(selected_curvature[0]),
        'selected_riemann_denominator_term_count': len(selected_curvature[1]),
        'selected_riemann_cross_multiplication_nonzero': not rat_equal(selected_curvature, zero),
        'theorem_result': theorem_result,
    }

