def _u864_action_matrix_mesonic(generator):
    dimension = 9
    matrix = [[Fraction(0) for _ in range(dimension)] for _ in range(dimension)]
    def index(i, j):
        return 3 * i + j
    for i in range(3):
        for j in range(3):
            column = index(i, j)
            for a in range(3):
                matrix[index(a, j)][column] += generator[a][i]
            for b in range(3):
                matrix[index(i, b)][column] -= generator[j][b]
    return tuple(tuple(row) for row in matrix)


def _u864_action_matrix_baryonic(generator):
    dimension = 27
    matrix = [[Fraction(0) for _ in range(dimension)] for _ in range(dimension)]
    def index(i, j, k):
        return 9 * i + 3 * j + k
    for i in range(3):
        for j in range(3):
            for k in range(3):
                column = index(i, j, k)
                for a in range(3):
                    matrix[index(a, j, k)][column] += generator[a][i]
                for b in range(3):
                    matrix[index(i, b, k)][column] += generator[b][j]
                for c in range(3):
                    matrix[index(i, j, c)][column] += generator[c][k]
    return tuple(tuple(row) for row in matrix)


