def _u865_levi_civita_four(first, second, third, fourth):
    values = (first, second, third, fourth)
    if len(set(values)) < 4:
        return 0
    inversions = sum(1 for left in range(4) for right in range(left + 1, 4) if values[left] > values[right])
    return -1 if inversions % 2 else 1


