def _quadratic_pair_add(left, right):
    """Add a+b*sqrt(15) and c+d*sqrt(15) exactly."""
    return (left[0] + right[0], left[1] + right[1])


def _quadratic_pair_multiply(left, right):
    """Multiply two elements of Q(sqrt(15)) exactly."""
    return (
        left[0] * right[0] + 15 * left[1] * right[1],
        left[0] * right[1] + left[1] * right[0],
    )


def _quadratic_matrix_vector_multiply(matrix, vector):
    rows = []
    for row in matrix:
        total = (Fraction(0), Fraction(0))
        for entry, component in zip(row, vector):
            total = _quadratic_pair_add(total, _quadratic_pair_multiply(entry, component))
        rows.append(total)
    return tuple(rows)


