def _u867_outer(left, right):
    return tuple(tuple(a * b for b in right) for a in left)


def _u867_matrix_sum(matrices):
    if not matrices:
        return tuple()
    result = _u865_zero_matrix(len(matrices[0]), len(matrices[0][0]))
    for matrix in matrices:
        result = _u865_add(result, matrix)
    return result


def _u867_matrix_power(matrix, exponent):
    result = _u865_identity(len(matrix))
    factor = matrix
    power = int(exponent)
    while power:
        if power % 2:
            result = _u865_multiply(result, factor)
        factor = _u865_multiply(factor, factor)
        power //= 2
    return result


def _u867_matvec(matrix, vector):
    return tuple(
        sum((matrix[row][column] * vector[column] for column in range(len(vector))), Fraction(0))
        for row in range(len(matrix))
    )


def _u867_dot(left, right):
    return sum((left[index] * right[index] for index in range(len(left))), Fraction(0))


