def _u869_factorial(n):
    value = 1
    for k in range(2, n + 1):
        value *= k
    return value


def _u869_finite_certificate_nonimplication_theorem():
    """Construct exact pairs that agree on every declared finite certificate but differ on an unrestricted target."""
    cutoff = 8

    common_scattering_prefix = tuple(Fraction(1, n + 1) for n in range(cutoff + 1))
    scattering_extension_a = common_scattering_prefix + tuple(
        common_scattering_prefix[-1] / (2 ** k) for k in range(1, 5)
    )
    scattering_extension_b = common_scattering_prefix + tuple(
        common_scattering_prefix[-1] / (3 ** k) for k in range(1, 5)
    )
    scattering_prefix_equal = scattering_extension_a[: cutoff + 1] == scattering_extension_b[: cutoff + 1]
    scattering_tail_distinct = scattering_extension_a[cutoff + 1 :] != scattering_extension_b[cutoff + 1 :]

    tested_gap_prefix = tuple((volume, Fraction(4, 3)) for volume in range(1, cutoff + 1))
    gapped_extension = tested_gap_prefix + tuple(
        (volume, Fraction(4, 3)) for volume in range(cutoff + 1, cutoff + 9)
    )
    gapless_extension = tested_gap_prefix + tuple(
        (volume, Fraction(0)) for volume in range(cutoff + 1, cutoff + 9)
    )
    gap_prefix_equal = gapped_extension[:cutoff] == gapless_extension[:cutoff]
    gap_targets_distinct = (
        min(value for _, value in gapped_extension) > 0
        and min(value for _, value in gapless_extension) == 0
    )

    jet_order = cutoff
    polynomial_degree = jet_order + 1
    zero_profile_jet = tuple(Fraction(0) for _ in range(jet_order + 1))
    delayed_profile_jet = tuple(
        Fraction(0) if order < polynomial_degree else Fraction(_u869_factorial(polynomial_degree))
        for order in range(jet_order + 1)
    )
    finite_jets_equal = zero_profile_jet == delayed_profile_jet
    zero_profile_at_one = Fraction(0)
    delayed_profile_at_one = Fraction(1) ** polynomial_degree
    global_profiles_distinct = zero_profile_at_one != delayed_profile_at_one

    native_ratios = (Fraction(1), Fraction(3), Fraction(6))
    decoder_a = tuple(zip(('LIGHT', 'MIDDLE', 'HEAVY'), native_ratios))
    decoder_b = tuple(zip(('LIGHT', 'HEAVY', 'MIDDLE'), native_ratios))
    decoder_internal_multisets_equal = sorted(value for _, value in decoder_a) == sorted(value for _, value in decoder_b)
    decoder_identifications_distinct = decoder_a != decoder_b

    sealed_packet = (Fraction(1, 4), Fraction(3, 8), Fraction(5, 8))
    sealed_digest = hashlib.sha256('|'.join(str(value) for value in sealed_packet).encode('utf-8')).hexdigest()
    matching_external_dataset = sealed_packet
    nonmatching_external_dataset = sealed_packet[:-1] + (Fraction(2, 3),)
    same_internal_seal_in_both_worlds = sealed_digest == hashlib.sha256('|'.join(str(value) for value in sealed_packet).encode('utf-8')).hexdigest()
    reproduction_world_a = {'internal_certificate': sealed_digest, 'third_party_certificate': sealed_digest}
    reproduction_world_b = {'internal_certificate': sealed_digest, 'third_party_certificate': None}
    reproduction_internal_certificates_equal = reproduction_world_a['internal_certificate'] == reproduction_world_b['internal_certificate']
    independent_reproduction_outcomes_distinct = (
        reproduction_world_a['third_party_certificate'] == sealed_digest
        and reproduction_world_b['third_party_certificate'] is None
    )
    empirical_outcomes_distinct = (
        sealed_packet == matching_external_dataset
        and sealed_packet != nonmatching_external_dataset
    )

    rows = (
        {
            'target': 'ALL_ORDER_STANDARD_MODEL_AMPLITUDES',
            'finite_certificate_agreement': scattering_prefix_equal,
            'unrestricted_target_difference': scattering_tail_distinct,
            'conclusion': 'a finite coefficient certificate does not uniquely determine the all-order continuation',
        },
        {
            'target': 'UNIFORM_INFINITE_VOLUME_SU3_GAP',
            'finite_certificate_agreement': gap_prefix_equal,
            'unrestricted_target_difference': gap_targets_distinct,
            'conclusion': 'a finite-volume positive gap certificate does not imply a uniform infinite-volume gap',
        },
        {
            'target': 'GLOBAL_NONLINEAR_QUANTUM_GEOMETRY',
            'finite_certificate_agreement': finite_jets_equal,
            'unrestricted_target_difference': global_profiles_distinct,
            'conclusion': 'a finite local curvature jet does not determine the global smooth geometry',
        },
        {
            'target': 'UNIQUE_PHYSICAL_MASS_MIXING_ATOMIC_DECODER',
            'finite_certificate_agreement': decoder_internal_multisets_equal,
            'unrestricted_target_difference': decoder_identifications_distinct,
            'conclusion': 'an internal ratio multiset does not uniquely determine external particle names',
        },
        {
            'target': 'INDEPENDENT_CODE_REPRODUCTION',
            'finite_certificate_agreement': reproduction_internal_certificates_equal,
            'unrestricted_target_difference': independent_reproduction_outcomes_distinct,
            'conclusion': 'the same internal certificate is compatible with either the presence or absence of a separate third-party certificate',
        },
        {
            'target': 'BLIND_EMPIRICAL_CONFIRMATION',
            'finite_certificate_agreement': same_internal_seal_in_both_worlds,
            'unrestricted_target_difference': empirical_outcomes_distinct,
            'conclusion': 'a sealed prediction packet does not internally determine the external experimental outcome',
        },
    )
    each_countermodel_exact = all(
        row['finite_certificate_agreement'] and row['unrestricted_target_difference']
        for row in rows
    )
    theorem_result = all((
        scattering_prefix_equal,
        scattering_tail_distinct,
        gap_prefix_equal,
        gap_targets_distinct,
        finite_jets_equal,
        global_profiles_distinct,
        decoder_internal_multisets_equal,
        decoder_identifications_distinct,
        reproduction_internal_certificates_equal,
        independent_reproduction_outcomes_distinct,
        same_internal_seal_in_both_worlds,
        empirical_outcomes_distinct,
        each_countermodel_exact,
    ))
    return {
        'proof_title': 'FINITE CERTIFICATE NONIMPLICATION THEOREM',
        'finite_order_cutoff': cutoff,
        'scattering_common_prefix': common_scattering_prefix,
        'scattering_extension_a': scattering_extension_a,
        'scattering_extension_b': scattering_extension_b,
        'tested_gap_prefix': tested_gap_prefix,
        'gapped_extension': gapped_extension,
        'gapless_extension': gapless_extension,
        'zero_profile_jet': zero_profile_jet,
        'delayed_profile_jet': delayed_profile_jet,
        'decoder_a': decoder_a,
        'decoder_b': decoder_b,
        'zero_profile_at_one': zero_profile_at_one,
        'delayed_profile_at_one': delayed_profile_at_one,
        'reproduction_world_a': reproduction_world_a,
        'reproduction_world_b': reproduction_world_b,
        'sealed_packet': sealed_packet,
        'sealed_packet_sha256': sealed_digest,
        'countermodel_rows': rows,
        'countermodel_count': len(rows),
        'each_unrestricted_target_has_an_exact_nonimplication_witness': each_countermodel_exact,
        'unrestricted_completion_is_not_a_consequence_of_the_finite_native_certificate_alone': theorem_result,
        'scope': 'exact logical separation between the complete declared native certificate and six unrestricted physical or external conclusions; the theorem proves nonimplication, not failure of the native results',
        'theorem_result': theorem_result,
    }


def _u869_minimal_unrestricted_completion_theorem():
    """Prove the minimal six-condition implication structure for an unrestricted physical completion."""
    native = _u868_no_jump_dependency_proof_theorem()
    nonimplication = _u869_finite_certificate_nonimplication_theorem()
    obligation_names = (
        'CONTINUUM_STANDARD_MODEL_AMPLITUDE_EQUIVALENCE',
        'UNIFORM_FOUR_DIMENSIONAL_SU3_GAP',
        'UNIQUE_MASS_MIXING_ATOMIC_DECODER',
        'GLOBAL_NONLINEAR_QUANTUM_GRAVITY_MEASURE',
        'INDEPENDENT_CODE_REPRODUCTION',
        'BLIND_EMPIRICAL_CONFIRMATION',
    )
    truth_rows = []
    for mask in range(1 << len(obligation_names)):
        assignment = tuple(bool((mask >> index) & 1) for index in range(len(obligation_names)))
        completion = bool(native['theorem_result'] and all(assignment))
        truth_rows.append({
            'assignment': tuple(zip(obligation_names, assignment)),
            'unrestricted_completion': completion,
        })
    all_true_assignment = tuple(True for _ in obligation_names)
    all_true_row = next(row for row in truth_rows if tuple(value for _, value in row['assignment']) == all_true_assignment)
    necessity_rows = []
    for omitted_index, omitted_name in enumerate(obligation_names):
        assignment = [True for _ in obligation_names]
        assignment[omitted_index] = False
        row = next(
            item for item in truth_rows
            if tuple(value for _, value in item['assignment']) == tuple(assignment)
        )
        necessity_rows.append({
            'omitted_obligation': omitted_name,
            'all_other_obligations_present': True,
            'unrestricted_completion_after_omission': row['unrestricted_completion'],
            'obligation_is_logically_necessary_in_this_completion_definition': not row['unrestricted_completion'],
        })
    all_obligations_jointly_sufficient = all_true_row['unrestricted_completion'] is True
    every_obligation_necessary = all(
        row['obligation_is_logically_necessary_in_this_completion_definition']
        for row in necessity_rows
    )
    internally_established_obligation_flags = tuple(False for _ in obligation_names)
    unconditional_unrestricted_completion = bool(
        native['theorem_result'] and all(internally_established_obligation_flags)
    )
    theorem_result = all((
        native['theorem_result'],
        nonimplication['theorem_result'],
        len(truth_rows) == 64,
        all_obligations_jointly_sufficient,
        every_obligation_necessary,
        unconditional_unrestricted_completion is False,
    ))
    return {
        'proof_title': 'MINIMAL UNRESTRICTED COMPLETION THEOREM',
        'declared_native_proof_certificate': native,
        'finite_certificate_nonimplication_certificate': nonimplication,
        'unrestricted_completion_obligations': obligation_names,
        'truth_table_rows': tuple(truth_rows),
        'truth_table_row_count': len(truth_rows),
        'necessity_rows': tuple(necessity_rows),
        'all_six_obligations_jointly_sufficient_by_definition': all_obligations_jointly_sufficient,
        'each_obligation_is_necessary_when_the_other_five_are_present': every_obligation_necessary,
        'internally_established_unrestricted_obligation_flags': tuple(zip(obligation_names, internally_established_obligation_flags)),
        'unconditional_unrestricted_physical_completion': unconditional_unrestricted_completion,
        'conditional_completion_statement': 'the declared native theorem plus the six separately proved or externally established obligations implies unrestricted physical completion',
        'scope': 'minimal exact dependency structure required to promote the declared native four-force theorem to an unrestricted empirical Standard-Model, SU3, quantum-gravity, reproduction, and blind-validation theorem',
        'theorem_result': theorem_result,
    }


