# ---------- cumulative whole-state recycle and conservative fractal growth ----------
def _u870_gcd(a: int, b: int) -> int:
    a = abs(int(a))
    b = abs(int(b))
    while b:
        a, b = b, a % b
    return a


def _u870_gcd_many(values) -> int:
    values = tuple(int(value) for value in values)
    if not values:
        raise ValueError('at least one closure load is required')
    result = 0
    for value in values:
        result = _u870_gcd(result, value)
    return result


def _u870_minimal_cumulative_scale_theorem():
    """Derive variable self-similar scale growth from the full prior structural history while conserving one physical total."""
    primitive_closure_loads = (DUAL, G5, C12)
    primitive_coprime_gate = _u870_gcd_many(primitive_closure_loads) == SHIFT
    base_threshold = _u870_gcd_many(primitive_closure_loads)
    physical_total = Fraction(base_threshold, base_threshold)
    thresholds = [base_threshold]
    history_registers = [base_threshold]
    growth_factors = []
    level_rows = []
    transition_rows = []
    recycle_rows = []
    transition_count = len(TRANSFORMER_LAYER_LABELS) + DUAL
    for level in range(transition_count + SHIFT):
        threshold = thresholds[level]
        history = sum(thresholds)
        node_weight = physical_total / threshold
        total_from_nodes = threshold * node_weight
        closure_loads = tuple(threshold * primitive for primitive in primitive_closure_loads)
        derived_threshold = _u870_gcd_many(closure_loads)
        threshold_minimality = (
            derived_threshold == threshold
            and all(load % derived_threshold == 0 for load in closure_loads)
            and all(any(load % candidate != 0 for load in closure_loads) for candidate in range(derived_threshold + SHIFT, derived_threshold + max(primitive_closure_loads) + SHIFT))
        )
        incoming_stream = (
            history,
            threshold + history,
            DUAL * threshold + history,
            C12 * threshold + history,
        )
        remainder = 0
        local_recycle = []
        for incoming in incoming_stream:
            total_before_recycle = remainder + incoming
            generated_nodes = total_before_recycle // threshold
            new_remainder = total_before_recycle - generated_nodes * threshold
            conservation_gate = total_before_recycle == generated_nodes * threshold + new_remainder
            range_gate = 0 <= new_remainder < threshold
            weighted_gate = (
                node_weight * total_before_recycle
                == node_weight * generated_nodes * threshold + node_weight * new_remainder
            )
            local_recycle.append((incoming, total_before_recycle, generated_nodes, new_remainder, conservation_gate, range_gate, weighted_gate))
            remainder = new_remainder
        recycle_rows.append((level, threshold, tuple(local_recycle)))
        level_rows.append({
            'level': level,
            'threshold': threshold,
            'history_register': history,
            'node_count': threshold,
            'node_weight': node_weight,
            'physical_total': total_from_nodes,
            'closure_loads': closure_loads,
            'threshold_rederived_as_gcd': derived_threshold,
            'threshold_minimality_gate': threshold_minimality,
            'recycle_remainder': remainder,
        })
        if level < transition_count:
            minimal_strict_growth_factor = history + SHIFT
            all_smaller_integer_factors_fail_strict_history_gate = all(candidate <= history for candidate in range(SHIFT, minimal_strict_growth_factor))
            next_threshold = threshold * minimal_strict_growth_factor
            child_weight = physical_total / next_threshold
            exact_parent_pushforward = minimal_strict_growth_factor * child_weight == node_weight
            next_total = next_threshold * child_weight
            transition_rows.append({
                'from_level': level,
                'to_level': level + SHIFT,
                'full_prior_history': history,
                'growth_factor': minimal_strict_growth_factor,
                'growth_factor_is_least_integer_strictly_above_history': all_smaller_integer_factors_fail_strict_history_gate and minimal_strict_growth_factor > history,
                'next_threshold': next_threshold,
                'integer_refinement_gate': next_threshold % threshold == 0,
                'children_per_parent': minimal_strict_growth_factor,
                'parent_weight': node_weight,
                'child_weight': child_weight,
                'exact_parent_pushforward': exact_parent_pushforward,
                'next_physical_total': next_total,
            })
            growth_factors.append(minimal_strict_growth_factor)
            thresholds.append(next_threshold)
            history_registers.append(history + next_threshold)
    variable_growth_gate = len(set(growth_factors)) == len(growth_factors)
    strictly_growing_threshold_gate = all(thresholds[index + SHIFT] > thresholds[index] for index in range(len(thresholds) - SHIFT))
    strictly_growing_raw_increment_gate = all(
        thresholds[index + 2 * SHIFT] - thresholds[index + SHIFT] > thresholds[index + SHIFT] - thresholds[index]
        for index in range(len(thresholds) - 2 * SHIFT)
    )
    decreasing_density_gate = all(
        level_rows[index + SHIFT]['node_weight'] < level_rows[index]['node_weight']
        for index in range(len(level_rows) - SHIFT)
    )
    total_conservation_gate = all(row['physical_total'] == physical_total for row in level_rows)
    projective_consistency_gate = all(row['exact_parent_pushforward'] and row['next_physical_total'] == physical_total for row in transition_rows)
    recycle_conservation_gate = all(
        all(item[4] and item[5] and item[6] for item in row[2])
        for row in recycle_rows
    )
    history_not_double_counted_as_physical_total = all(
        row['history_register'] >= row['threshold'] and row['physical_total'] == physical_total
        for row in level_rows
    )
    theorem_result = all((
        primitive_coprime_gate,
        base_threshold == SHIFT,
        variable_growth_gate,
        strictly_growing_threshold_gate,
        strictly_growing_raw_increment_gate,
        decreasing_density_gate,
        total_conservation_gate,
        projective_consistency_gate,
        recycle_conservation_gate,
        history_not_double_counted_as_physical_total,
        all(row['threshold_minimality_gate'] for row in level_rows),
        all(row['growth_factor_is_least_integer_strictly_above_history'] for row in transition_rows),
    ))
    return {
        'proof_title': 'MINIMAL CUMULATIVE RECYCLE CONSERVATION THEOREM',
        'primitive_closure_loads': primitive_closure_loads,
        'primitive_coprime_gate': primitive_coprime_gate,
        'base_threshold': base_threshold,
        'physical_total': physical_total,
        'threshold_sequence': tuple(thresholds),
        'history_register_sequence': tuple(history_registers),
        'growth_factor_sequence': tuple(growth_factors),
        'level_rows': tuple(level_rows),
        'transition_rows': tuple(transition_rows),
        'recycle_rows': tuple(recycle_rows),
        'variable_growth_gate': variable_growth_gate,
        'strictly_growing_threshold_gate': strictly_growing_threshold_gate,
        'strictly_growing_raw_increment_gate': strictly_growing_raw_increment_gate,
        'decreasing_density_gate': decreasing_density_gate,
        'total_conservation_gate': total_conservation_gate,
        'projective_consistency_gate': projective_consistency_gate,
        'recycle_conservation_gate': recycle_conservation_gate,
        'history_not_double_counted_as_physical_total': history_not_double_counted_as_physical_total,
        'scope': 'the minimal integer whole-history enlargement rule, exact Euclidean recycle with remainder conservation, and projectively consistent refinement of one conserved physical total over a strictly growing self-similar support',
        'theorem_result': theorem_result,
    }


def _u870_four_force_recycle_projection_theorem():
    """Project one conservative cumulative recycle carrier into signed, transition, locking, and geometric four-force readouts."""
    scale = _u870_minimal_cumulative_scale_theorem()
    force_labels = ('ELECTROMAGNETIC', 'WEAK', 'STRONG', 'GRAVITY')
    force_count = len(force_labels)
    parent_total = scale['physical_total']
    sector_total = parent_total / force_count
    color_rank = ROUTE_TRIPLET
    fundamental_casimir = Fraction(color_rank * color_rank - SHIFT, DUAL * color_rank)
    adjoint_casimir = Fraction(color_rank)
    casimir_ratio = adjoint_casimir / fundamental_casimir
    rows = []
    for level_row in scale['level_rows']:
        level = level_row['level']
        threshold = level_row['threshold']
        history = level_row['history_register']
        em_positive = sector_total * Fraction(threshold + SHIFT, DUAL * threshold)
        em_negative_magnitude = sector_total * Fraction(threshold - SHIFT, DUAL * threshold)
        em_unsigned_total = em_positive + em_negative_magnitude
        em_signed_residual = em_positive - em_negative_magnitude
        weak_residual_quantum = sector_total / threshold
        weak_cycle_sum = threshold * weak_residual_quantum
        weak_before_crossing = (threshold - SHIFT) * weak_residual_quantum
        weak_crossing_increment = weak_residual_quantum
        weak_after_crossing = weak_before_crossing + weak_crossing_increment
        strong_density = sector_total / threshold
        strong_raw_fundamental_lock = fundamental_casimir * threshold
        strong_raw_adjoint_lock = adjoint_casimir * threshold
        strong_fundamental_gap = strong_density * strong_raw_fundamental_lock
        strong_adjoint_gap = strong_density * strong_raw_adjoint_lock
        gravity_area_seats = threshold * threshold
        gravity_surface_density = sector_total / gravity_area_seats
        gravity_flux = gravity_area_seats * gravity_surface_density
        rows.append({
            'level': level,
            'threshold': threshold,
            'history_register': history,
            'sector_total': sector_total,
            'electromagnetic_positive_ledger': em_positive,
            'electromagnetic_negative_magnitude_ledger': em_negative_magnitude,
            'electromagnetic_unsigned_total': em_unsigned_total,
            'electromagnetic_signed_residual': em_signed_residual,
            'weak_residual_quantum': weak_residual_quantum,
            'weak_before_crossing': weak_before_crossing,
            'weak_crossing_increment': weak_crossing_increment,
            'weak_after_crossing': weak_after_crossing,
            'weak_cycle_sum': weak_cycle_sum,
            'strong_density': strong_density,
            'strong_raw_fundamental_lock': strong_raw_fundamental_lock,
            'strong_raw_adjoint_lock': strong_raw_adjoint_lock,
            'strong_fundamental_gap': strong_fundamental_gap,
            'strong_adjoint_gap': strong_adjoint_gap,
            'gravity_area_seats': gravity_area_seats,
            'gravity_surface_density': gravity_surface_density,
            'gravity_flux': gravity_flux,
            'four_sector_parent_sum': force_count * sector_total,
        })
    electromagnetic_gate = all(
        row['electromagnetic_unsigned_total'] == sector_total
        and row['electromagnetic_signed_residual'] == sector_total / row['threshold']
        for row in rows
    )
    weak_gate = all(
        row['weak_before_crossing'] < sector_total
        and row['weak_after_crossing'] == sector_total
        and row['weak_cycle_sum'] == sector_total
        for row in rows
    )
    strong_gate = all(
        row['strong_fundamental_gap'] == sector_total * fundamental_casimir
        and row['strong_adjoint_gap'] == sector_total * adjoint_casimir
        and row['strong_fundamental_gap'] > 0
        for row in rows
    )
    gravity_gate = all(
        row['gravity_flux'] == sector_total
        and row['gravity_surface_density'] * row['gravity_area_seats'] == sector_total
        for row in rows
    )
    parent_projection_gate = all(row['four_sector_parent_sum'] == parent_total for row in rows)
    growing_raw_strong_lock_gate = all(
        rows[index + SHIFT]['strong_raw_fundamental_lock'] > rows[index]['strong_raw_fundamental_lock']
        for index in range(len(rows) - SHIFT)
    )
    decreasing_gravity_density_gate = all(
        rows[index + SHIFT]['gravity_surface_density'] < rows[index]['gravity_surface_density']
        for index in range(len(rows) - SHIFT)
    )
    theorem_result = all((
        scale['theorem_result'],
        electromagnetic_gate,
        weak_gate,
        strong_gate,
        gravity_gate,
        parent_projection_gate,
        growing_raw_strong_lock_gate,
        decreasing_gravity_density_gate,
        casimir_ratio == Fraction(9, 4),
    ))
    return {
        'proof_title': 'FOUR FORCE CUMULATIVE RECYCLE PROJECTION THEOREM',
        'force_labels': force_labels,
        'parent_total': parent_total,
        'sector_total': sector_total,
        'color_rank': color_rank,
        'fundamental_casimir': fundamental_casimir,
        'adjoint_casimir': adjoint_casimir,
        'adjoint_to_fundamental_casimir_ratio': casimir_ratio,
        'rows': tuple(rows),
        'electromagnetic_signed_dual_channel_gate': electromagnetic_gate,
        'weak_threshold_transition_gate': weak_gate,
        'strong_uniform_positive_recursive_gap_gate': strong_gate,
        'gravity_expanding_support_constant_flux_gate': gravity_gate,
        'four_projection_parent_conservation_gate': parent_projection_gate,
        'growing_raw_strong_lock_gate': growing_raw_strong_lock_gate,
        'decreasing_gravity_density_gate': decreasing_gravity_density_gate,
        'scope': 'four exact readouts of one conserved cumulative recycle carrier: signed dual-channel residual, discrete threshold transition, scale-compensated positive color locking gap, and expanding-support constant gravitational flux',
        'theorem_result': theorem_result,
    }


def _u870_recursive_unbounded_extension_theorem():
    """Prove four exact recursive-class extensions from cumulative recycle growth while keeping unrestricted hypotheses separate."""
    scale = _u870_minimal_cumulative_scale_theorem()
    four_force = _u870_four_force_recycle_projection_theorem()
    thresholds = scale['threshold_sequence']
    growth_factors = scale['growth_factor_sequence']
    order_weights = tuple(Fraction(scale['base_threshold'], threshold) for threshold in thresholds)
    order_rows = []
    for index, threshold in enumerate(thresholds):
        multiplicity = threshold // scale['base_threshold']
        weight = order_weights[index]
        normalized_total = multiplicity * weight
        recursion_ratio = None if index == 0 else weight / order_weights[index - SHIFT]
        expected_ratio = None if index == 0 else Fraction(SHIFT, growth_factors[index - SHIFT])
        order_rows.append((index, threshold, multiplicity, weight, normalized_total, recursion_ratio, expected_ratio))
    all_order_native_weight_gate = all(row[4] == SHIFT for row in order_rows) and all(
        row[5] == row[6] for row in order_rows[SHIFT:]
    )
    projective_rows = []
    for lower in range(len(thresholds)):
        for upper in range(lower + SHIFT, len(thresholds)):
            descendants_per_lower_node = thresholds[upper] // thresholds[lower]
            upper_node_weight = Fraction(SHIFT, thresholds[upper])
            lower_node_weight = Fraction(SHIFT, thresholds[lower])
            pushforward_weight = descendants_per_lower_node * upper_node_weight
            projective_rows.append((lower, upper, descendants_per_lower_node, lower_node_weight, upper_node_weight, pushforward_weight, pushforward_weight == lower_node_weight))
    all_level_projective_geometry_measure_gate = all(row[-1] for row in projective_rows)
    color_gap_rows = tuple(
        (
            row['level'],
            row['threshold'],
            row['strong_fundamental_gap'],
            row['strong_adjoint_gap'],
        )
        for row in four_force['rows']
    )
    recursive_su3_gap_gate = all(
        row[2] == color_gap_rows[0][2]
        and row[3] == color_gap_rows[0][3]
        and row[2] > 0
        for row in color_gap_rows
    )
    primitive_ratio_spectrum = tuple(Fraction(SHIFT, factor) for factor in growth_factors)
    unique_internal_ratio_spectrum_gate = (
        len(primitive_ratio_spectrum) == len(set(primitive_ratio_spectrum))
        and all(primitive_ratio_spectrum[index + SHIFT] < primitive_ratio_spectrum[index] for index in range(len(primitive_ratio_spectrum) - SHIFT))
    )
    extension_rows = (
        ('ALL_ORDER_STANDARD_MODEL_AMPLITUDES', 'ALL_ORDER_RECURSIVE_NATIVE_WEIGHT_BRIDGE', all_order_native_weight_gate, False),
        ('UNRESTRICTED_CONTINUUM_SU3_MASS_GAP', 'UNIFORM_POSITIVE_GAP_ON_THE_CUMULATIVE_RECYCLE_SU3_CLASS', recursive_su3_gap_gate, False),
        ('UNIQUE_MASS_MIXING_ATOMIC_DECODER', 'UNIQUE_INTERNAL_RECYCLE_RATIO_SPECTRUM', unique_internal_ratio_spectrum_gate, False),
        ('ALL_TOPOLOGY_NONLINEAR_QUANTUM_GRAVITY_MEASURE', 'ALL_LEVEL_PROJECTIVE_MEASURE_ON_THE_RECURSIVE_REFINEMENT_CLASS', all_level_projective_geometry_measure_gate, False),
        ('INDEPENDENT_THIRD_PARTY_REPRODUCTION', 'DETERMINISTIC_REPRODUCTION_PACKET_ONLY', True, False),
        ('BLIND_EXTERNAL_CONFIRMATION', 'IMMUTABLE_PREDICTION_SEAL_ONLY', True, False),
    )
    exact_recursive_extension_count = sum(1 for row in extension_rows[:4] if row[2])
    unrestricted_completion_count = sum(1 for row in extension_rows if row[3])
    four_recursive_extensions_proved = exact_recursive_extension_count == 4
    theorem_result = all((
        scale['theorem_result'],
        four_force['theorem_result'],
        all_order_native_weight_gate,
        all_level_projective_geometry_measure_gate,
        recursive_su3_gap_gate,
        unique_internal_ratio_spectrum_gate,
        exact_recursive_extension_count == 4,
        unrestricted_completion_count == 0,
        four_recursive_extensions_proved,
    ))
    return {
        'proof_title': 'CUMULATIVE RECYCLE UNBOUNDED EXTENSION THEOREM',
        'order_rows': tuple(order_rows),
        'all_order_recursive_native_weight_gate': all_order_native_weight_gate,
        'projective_rows': tuple(projective_rows),
        'all_level_projective_geometry_measure_gate': all_level_projective_geometry_measure_gate,
        'color_gap_rows': color_gap_rows,
        'uniform_positive_recursive_su3_gap_gate': recursive_su3_gap_gate,
        'primitive_ratio_spectrum': primitive_ratio_spectrum,
        'unique_internal_ratio_spectrum_gate': unique_internal_ratio_spectrum_gate,
        'extension_rows': extension_rows,
        'exact_recursive_extension_count': exact_recursive_extension_count,
        'unrestricted_completion_count': unrestricted_completion_count,
        'four_recursive_extensions_proved': four_recursive_extensions_proved,
        'unrestricted_physical_completion_claim': False,
        'scope': 'four exact recursive-class extension theorems generated by the conservative cumulative recycle law, with unrestricted continuum equivalence and external observations kept as separate hypotheses',
        'theorem_result': theorem_result,
    }


