def _u871_path_probability(word, initial, transition):
    weight = initial[word[0]]
    for index in range(len(word) - SHIFT):
        weight *= transition[word[index]][word[index + SHIFT]]
    return weight


def _u871_projective_continuum_amplitude_uniqueness_theorem():
    """Construct the unique positive nonfactorizing cylinder amplitude functional on the infinite recursive path class."""
