def _u871_givens_rotation(axis_left, axis_right, first, second):
    denominator = first * first + second * second
    cosine = Fraction(first * first - second * second, denominator)
    sine = Fraction(DUAL * first * second, denominator)
    matrix = [list(row) for row in _u865_identity(ROUTE_TRIPLET)]
    matrix[axis_left][axis_left] = cosine
    matrix[axis_left][axis_right] = sine
    matrix[axis_right][axis_left] = -sine
    matrix[axis_right][axis_right] = cosine
    return tuple(tuple(row) for row in matrix)


