def _u873_identity(size):
    return tuple(tuple(Fraction(int(row == column)) for column in range(size)) for row in range(size))


def _u873_transpose(matrix):
    return tuple(tuple(matrix[row][column] for row in range(len(matrix))) for column in range(len(matrix[0])))


def _u873_multiply(left, right):
    right_t = _u873_transpose(right)
    return tuple(tuple(sum((a * b for a, b in zip(row, column)), Fraction(0)) for column in right_t) for row in left)


def _u873_add(left, right):
    return tuple(tuple(left[row][column] + right[row][column] for column in range(len(left[0]))) for row in range(len(left)))


def _u873_scale(scalar, matrix):
    return tuple(tuple(scalar * value for value in row) for row in matrix)


def _u873_kron(left, right):
    return tuple(
        tuple(
            left[row // len(right)][column // len(right[0])] * right[row % len(right)][column % len(right[0])]
            for column in range(len(left[0]) * len(right[0]))
        )
        for row in range(len(left) * len(right))
    )


def _u873_outer(vector):
    return tuple(tuple(left * right for right in vector) for left in vector)


def _u873_spectral_matrix(projectors, eigenvalues, exponent):
    size = len(projectors[0])
    result = tuple(tuple(Fraction(0) for _ in range(size)) for _ in range(size))
    for projector, eigenvalue in zip(projectors, eigenvalues):
        result = _u873_add(result, _u873_scale(eigenvalue ** exponent, projector))
    return result


