        singlets['theorem_result'],
        decomposition['theorem_result'],
        len(gauge_invariant_rows) == len(motif_rows),
        network_gap == expected_gap,
        all(row[-1] for row in hilbert_rows),
        all(row[-1] for row in disjoint_union_rows),
        all(row[3] >= network_gap for row in gauge_invariant_rows),
