def _u874_dot(left, right):
    return sum((left[index] * right[index] for index in range(len(left))), Fraction(0))


def _u874_norm2(vector):
    return _u874_dot(vector, vector)


def _u874_kron_vector(left, right):
    return tuple(a * b for a in left for b in right)


def _u874_apply_one_site(vector, particle_count, site, matrix):
    dimension = DUAL ** particle_count
    result = [Fraction(0) for _ in range(dimension)]
    bit_weight = DUAL ** (particle_count - site - SHIFT)
    for index, amplitude in enumerate(vector):
        old_bit = (index // bit_weight) % DUAL
        base = index - old_bit * bit_weight
        for new_bit in range(DUAL):
            result[base + new_bit * bit_weight] += matrix[new_bit][old_bit] * amplitude
    return tuple(result)


def _u874_apply_controlled_flip(vector, particle_count, control, target):
    dimension = DUAL ** particle_count
    result = [Fraction(0) for _ in range(dimension)]
    control_weight = DUAL ** (particle_count - control - SHIFT)
    target_weight = DUAL ** (particle_count - target - SHIFT)
    for index, amplitude in enumerate(vector):
        control_bit = (index // control_weight) % DUAL
        mapped = index
        if control_bit == SHIFT:
            target_bit = (index // target_weight) % DUAL
            mapped = index + (SHIFT - DUAL * target_bit) * target_weight
        result[mapped] += amplitude
    return tuple(result)


def _u874_interacting_fock_scattering_theorem():
    """Construct exact norm-preserving interacting circuits for every finite particle number and prove separated-cluster factorization."""
    one_particle = (
        (Fraction(ROUTE_TRIPLET, G5), Fraction(-len(TRANSFORMER_LAYER_LABELS), G5)),
        (Fraction(len(TRANSFORMER_LAYER_LABELS), G5), Fraction(ROUTE_TRIPLET, G5)),
    )
    one_particle_transpose = tuple(tuple(one_particle[j][i] for j in range(DUAL)) for i in range(DUAL))
    one_particle_orthogonal = all(
        sum((one_particle_transpose[i][k] * one_particle[k][j] for k in range(DUAL)), Fraction(0)) == (SHIFT if i == j else 0)
        for i in range(DUAL) for j in range(DUAL)
    )

    def forward(vector, particle_count, coupled_edges):
        state = tuple(vector)
        for site in range(particle_count):
            state = _u874_apply_one_site(state, particle_count, site, one_particle)
        for control, target in coupled_edges:
            state = _u874_apply_controlled_flip(state, particle_count, control, target)
        return state

    def inverse(vector, particle_count, coupled_edges):
        state = tuple(vector)
        for control, target in reversed(tuple(coupled_edges)):
            state = _u874_apply_controlled_flip(state, particle_count, control, target)
        for site in reversed(range(particle_count)):
            state = _u874_apply_one_site(state, particle_count, site, one_particle_transpose)
        return state

    particle_rows = []
    for particle_count in range(SHIFT, D8 + SHIFT):
        dimension = DUAL ** particle_count
        coupled_edges = tuple((site, site + SHIFT) for site in range(particle_count - SHIFT))
        basis_reconstruction_gate = True
        norm_gate = True
        for basis_index in range(dimension):
            basis = tuple(Fraction(SHIFT if index == basis_index else 0) for index in range(dimension))
            evolved = forward(basis, particle_count, coupled_edges)
            reconstructed = inverse(evolved, particle_count, coupled_edges)
            basis_reconstruction_gate = basis_reconstruction_gate and reconstructed == basis
            norm_gate = norm_gate and _u874_norm2(evolved) == SHIFT
        particle_rows.append((particle_count, dimension, len(coupled_edges), basis_reconstruction_gate, norm_gate))

    product_state = _u874_kron_vector((Fraction(ROUTE_TRIPLET, G5), Fraction(len(TRANSFORMER_LAYER_LABELS), G5)), (Fraction(SHIFT), Fraction(0)))
    entangled_state = _u874_apply_controlled_flip(product_state, DUAL, 0, SHIFT)
    coefficient_determinant = entangled_state[0] * entangled_state[3] - entangled_state[SHIFT] * entangled_state[DUAL]
    genuine_two_body_interaction_gate = coefficient_determinant != 0

    cluster_rows = []
    particle_count = len(TRANSFORMER_LAYER_LABELS)
    cluster_edges = ((0, SHIFT), (DUAL, ROUTE_TRIPLET))
    for basis_index in range(DUAL ** particle_count):
        basis = tuple(Fraction(SHIFT if index == basis_index else 0) for index in range(DUAL ** particle_count))
        full = forward(basis, particle_count, cluster_edges)
        left_index = basis_index // (DUAL ** DUAL)
        right_index = basis_index % (DUAL ** DUAL)
        left_basis = tuple(Fraction(SHIFT if index == left_index else 0) for index in range(DUAL ** DUAL))
        right_basis = tuple(Fraction(SHIFT if index == right_index else 0) for index in range(DUAL ** DUAL))
        left = forward(left_basis, DUAL, ((0, SHIFT),))
        right = forward(right_basis, DUAL, ((0, SHIFT),))
        factorized = _u874_kron_vector(left, right)
        cluster_rows.append((basis_index, full == factorized))

    theorem_result = all((
        one_particle_orthogonal,
        all(row[3] and row[4] for row in particle_rows),
        genuine_two_body_interaction_gate,
        all(row[1] for row in cluster_rows),
    ))
    return {
        'proof_title': 'INTERACTING FINITE FOCK SCATTERING THEOREM',
        'one_particle_rational_scattering': one_particle,
        'one_particle_orthogonality_gate': one_particle_orthogonal,
        'finite_particle_rows': tuple(particle_rows),
        'entangled_two_particle_output': entangled_state,
        'two_particle_coefficient_determinant': coefficient_determinant,
        'genuine_two_body_interaction_gate': genuine_two_body_interaction_gate,
        'separated_cluster_factorization_rows': tuple(cluster_rows),
        'scope': 'exact rational norm-preserving interacting circuits for every finite particle number in the declared binary carrier, with nonzero connected two-body entanglement and exact factorization for disconnected clusters',
        'all_standard_model_lsz_amplitudes_identified': False,
        'theorem_result': theorem_result,
    }


def _u874_su3_flux_tube_coercivity_theorem():
    """Prove a uniform gauge-invariant flux-tube coercive gap on the recursive direct-limit carrier and its square-summable completion."""
    singlet = _u864_su3_color_singlet_theorem()
