def _u875_zero(rows, columns):
    return tuple(tuple(Fraction(0) for _ in range(columns)) for _ in range(rows))


def _u875_identity(size):
    return tuple(tuple(Fraction(SHIFT if row == column else 0) for column in range(size)) for row in range(size))


def _u875_add(left, right):
    return tuple(tuple(left[row][column] + right[row][column] for column in range(len(left[0]))) for row in range(len(left)))


def _u875_sub(left, right):
    return tuple(tuple(left[row][column] - right[row][column] for column in range(len(left[0]))) for row in range(len(left)))


def _u875_scale(scalar, matrix):
    return tuple(tuple(scalar * value for value in row) for row in matrix)


def _u875_transpose(matrix):
    return tuple(tuple(matrix[column][row] for column in range(len(matrix))) for row in range(len(matrix[0])))


def _u875_multiply(left, right):
    return tuple(
        tuple(
            sum((left[row][pivot] * right[pivot][column] for pivot in range(len(right))), Fraction(0))
            for column in range(len(right[0]))
        )
        for row in range(len(left))
    )


def _u875_kron(left, right):
    return tuple(
        tuple(
            left[row // len(right)][column // len(right[0])] * right[row % len(right)][column % len(right[0])]
            for column in range(len(left[0]) * len(right[0]))
        )
        for row in range(len(left) * len(right))
    )


def _u875_inverse(matrix):
    size = len(matrix)
    augmented = [list(matrix[row]) + list(_u875_identity(size)[row]) for row in range(size)]
    for pivot_column in range(size):
        pivot_row = next(row for row in range(pivot_column, size) if augmented[row][pivot_column] != 0)
        if pivot_row != pivot_column:
            augmented[pivot_column], augmented[pivot_row] = augmented[pivot_row], augmented[pivot_column]
        pivot = augmented[pivot_column][pivot_column]
        augmented[pivot_column] = [value / pivot for value in augmented[pivot_column]]
        for row in range(size):
            if row == pivot_column:
                continue
            factor = augmented[row][pivot_column]
            if factor != 0:
                augmented[row] = [augmented[row][column] - factor * augmented[pivot_column][column] for column in range(DUAL * size)]
    return tuple(tuple(augmented[row][size:]) for row in range(size))


