def _u875_graph_connected(vertex_count, edges):
    adjacency = [[] for _ in range(vertex_count)]
    for left, right in edges:
        adjacency[left].append(right)
        adjacency[right].append(left)
    reached = {0}
    frontier = [0]
    while frontier:
        vertex = frontier.pop()
        for neighbor in adjacency[vertex]:
            if neighbor not in reached:
                reached.add(neighbor)
                frontier.append(neighbor)
    return len(reached) == vertex_count


def _u875_graph_girth(vertex_count, edges):
    adjacency = [[] for _ in range(vertex_count)]
    for left, right in edges:
        adjacency[left].append(right)
        adjacency[right].append(left)
    best = None
    for start in range(vertex_count):
        distance = [-SHIFT] * vertex_count
        parent = [-SHIFT] * vertex_count
        distance[start] = 0
        queue = [start]
        cursor = 0
        while cursor < len(queue):
            vertex = queue[cursor]
            cursor += SHIFT
            for neighbor in adjacency[vertex]:
                if distance[neighbor] < 0:
                    distance[neighbor] = distance[vertex] + SHIFT
                    parent[neighbor] = vertex
                    queue.append(neighbor)
                elif parent[vertex] != neighbor:
                    cycle_length = distance[vertex] + distance[neighbor] + SHIFT
                    if best is None or cycle_length < best:
                        best = cycle_length
    return best


