def _u877_diagonal(values):
    size = len(values)
    return tuple(
        tuple(Fraction(values[row]) if row == column else Fraction(0, 1) for column in range(size))
        for row in range(size)
    )


def _u877_trace(matrix):
    return sum((matrix[index][index] for index in range(len(matrix))), Fraction(0, 1))


def _u877_quadratic(matrix, vector):
    return _u876_dot(vector, _u876_matvec(matrix, vector))


def _u877_determinant(matrix):
    work = [list(row) for row in matrix]
    size = len(work)
    determinant = Fraction(1, 1)
    sign = SHIFT
    for column in range(size):
        pivot = next((row for row in range(column, size) if work[row][column] != 0), None)
        if pivot is None:
            return Fraction(0, 1)
        if pivot != column:
            work[column], work[pivot] = work[pivot], work[column]
            sign = -sign
        pivot_value = work[column][column]
        determinant *= pivot_value
        for row in range(column + SHIFT, size):
            if work[row][column] == 0:
                continue
            factor = work[row][column] / pivot_value
            for entry in range(column, size):
                work[row][entry] -= factor * work[column][entry]
    return determinant * sign


def _u877_native_observer_anchor_data():
    first_rotation = (
        (Fraction(ROUTE_TRIPLET, G5), Fraction(len(TRANSFORMER_LAYER_LABELS), G5)),
        (Fraction(-len(TRANSFORMER_LAYER_LABELS), G5), Fraction(ROUTE_TRIPLET, G5)),
    )
    second_rotation = (
        (Fraction(G5, C12 + SHIFT), Fraction(C12, C12 + SHIFT)),
        (Fraction(-C12, C12 + SHIFT), Fraction(G5, C12 + SHIFT)),
    )
    observer_frame = _u876_block_diagonal(first_rotation, second_rotation)
    native_levels = (Fraction(SHIFT), Fraction(DUAL), Fraction(G5), Fraction(C12))
    native_diagonal = _u877_diagonal(native_levels)
    anchor = _u876_multiply(_u876_multiply(observer_frame, native_diagonal), _u876_transpose(observer_frame))
    return native_levels, observer_frame, native_diagonal, anchor


