def _u878_matrix_inverse(matrix):
    size = len(matrix)
    work = [list(matrix[row]) + list(_u876_identity(size)[row]) for row in range(size)]
    for column in range(size):
        pivot = next((row for row in range(column, size) if work[row][column] != 0), None)
        if pivot is None:
            raise AssertionError('singular exact matrix')
        work[column], work[pivot] = work[pivot], work[column]
        pivot_value = work[column][column]
        work[column] = [value / pivot_value for value in work[column]]
        for row in range(size):
            if row == column:
                continue
            factor = work[row][column]
            if factor != 0:
                work[row] = [work[row][entry] - factor * work[column][entry] for entry in range(DUAL * size)]
    return tuple(tuple(work[row][size + column] for column in range(size)) for row in range(size))


def _u878_projector_scale_kernel(scale):
    labels, frame, inverse = _u876_projection_frame_data()
    projectors = tuple(
        _u876_scale(Fraction(SHIFT, len(frame)), _u876_outer(row, row))
        for row in frame
    )
    kernel = _u876_zero(len(frame), len(frame))
    for degree, projector in enumerate(projectors):
        kernel = _u876_add(kernel, _u876_scale(scale ** degree, projector))
    shadow = _u876_multiply(_u876_multiply(frame, kernel), inverse)
    return labels, projectors, kernel, shadow


