def _u879_all_order_source_moment_theorem():
    """Generate every integer-order source moment from four native poles and prove exact projection covariance and unique recurrence without order-by-order parameter insertion."""
    labels, frame, inverse = _u876_projection_frame_data()
    normalized_frame = _u876_scale(Fraction(SHIFT, DUAL), frame)
    normalized_inverse = _u876_transpose(normalized_frame)
    poles = (Fraction(SHIFT), Fraction(SHIFT, DUAL), Fraction(SHIFT, len(TRANSFORMER_LAYER_LABELS)), Fraction(SHIFT, D8))
    mass_levels = (Fraction(SHIFT), Fraction(DUAL), Fraction(G5), Fraction(C12))
    residue_total = sum(mass_levels, Fraction(0))
    residues = tuple(level / residue_total for level in mass_levels)
    coefficients = (Fraction(15, 8), Fraction(35, 32), Fraction(15, 64), Fraction(SHIFT, 64))
    root_identity_rows = tuple(
        (
            pole,
            pole ** 4,
            coefficients[0] * pole ** 3 - coefficients[1] * pole ** 2 + coefficients[2] * pole - coefficients[3],
            pole ** 4 == coefficients[0] * pole ** 3 - coefficients[1] * pole ** 2 + coefficients[2] * pole - coefficients[3],
        )
        for pole in poles
    )
    moments = tuple(
        sum((residues[index] * poles[index] ** order for index in range(len(poles))), Fraction(0))
        for order in range(DUAL * C12 + SHIFT)
    )
    recurrence_rows = []
    for order in range(len(moments) - len(poles)):
        generated = coefficients[0] * moments[order + 3] - coefficients[1] * moments[order + 2] + coefficients[2] * moments[order + 1] - coefficients[3] * moments[order]
        recurrence_rows.append((order, moments[order + 4], generated, moments[order + 4] == generated))
    source_vectors = (
        (Fraction(SHIFT), Fraction(0), Fraction(0), Fraction(0)),
        (Fraction(SHIFT), Fraction(DUAL), Fraction(ROUTE_TRIPLET), Fraction(G5)),
        (Fraction(-SHIFT), Fraction(DUAL), Fraction(-ROUTE_TRIPLET), Fraction(C12)),
    )
    covariance_rows = []
    for order in range(C12 + SHIFT):
        latent = _u877_diagonal(tuple(pole ** order for pole in poles))
        shadow = _u876_multiply(_u876_multiply(normalized_frame, latent), normalized_inverse)
        recovered = _u876_multiply(_u876_multiply(normalized_inverse, shadow), normalized_frame)
        for source in source_vectors:
            latent_source = _u876_matvec(normalized_inverse, source)
            shadow_value = _u877_quadratic(shadow, source)
            latent_value = _u877_quadratic(latent, latent_source)
            covariance_rows.append((order, source, shadow_value, latent_value, recovered == latent, shadow_value == latent_value))
    theorem_result = all((
        sum(residues, Fraction(0)) == SHIFT,
        all(residue > 0 for residue in residues),
        all(row[-1] for row in root_identity_rows),
        all(row[-1] for row in recurrence_rows),
        all(row[-2] and row[-1] for row in covariance_rows),
        _u876_multiply(normalized_inverse, normalized_frame) == _u876_identity(len(frame)),
    ))
    return {
        'proof_title': 'ALL ORDER SOURCE MOMENT THEOREM',
        'force_labels': labels,
        'native_poles': poles,
        'native_positive_residues': residues,
        'characteristic_recurrence_coefficients': coefficients,
        'pole_characteristic_identity_rows': root_identity_rows,
        'generated_source_moments': moments,
        'all_checked_recurrence_rows': tuple(recurrence_rows),
        'projection_covariance_rows': tuple(covariance_rows),
        'scope': 'exact all-integer-order source-moment generation and complete-frame covariance in the declared four-pole origin model, with one characteristic recurrence replacing independent order-by-order inputs',
        'actual_standard_model_all_field_correlation_identity': False,
        'theorem_result': theorem_result,
    }


