            right_propagator = _u877_diagonal(tuple(Fraction(SHIFT, SHIFT - pole * right_source) for pole in poles))
            left_inverse = _u877_diagonal(tuple(SHIFT - pole * left_source for pole in poles))
            right_inverse = _u877_diagonal(tuple(SHIFT - pole * right_source for pole in poles))
