# ---------- primitive polarity occupancy, double-zero algebra, and relation-root geometry ----------
def _double_zero_state_data():
    labels = ('EMPTY_ZERO', 'NEGATIVE', 'POSITIVE', 'FULL_ZERO')
    occupancies = (
        (0, 0),
        (1, 0),
        (0, 1),
        (1, 1),
    )
    projectors = (
        ((Fraction(0), Fraction(0)), (Fraction(0), Fraction(0))),
        ((Fraction(SHIFT), Fraction(0)), (Fraction(0), Fraction(0))),
        ((Fraction(0), Fraction(0)), (Fraction(0), Fraction(SHIFT))),
        ((Fraction(SHIFT), Fraction(0)), (Fraction(0), Fraction(SHIFT))),
    )
    shadow_sign = tuple(Fraction(positive - negative) for negative, positive in occupancies)
    total_burden = tuple(Fraction(negative + positive) for negative, positive in occupancies)
    closure_pair = tuple(Fraction(min(negative, positive)) for negative, positive in occupancies)
    open_residual = tuple(Fraction(abs(positive - negative)) for negative, positive in occupancies)
    zero_type = (Fraction(-SHIFT), Fraction(0), Fraction(0), Fraction(SHIFT))
    characters = tuple(
        tuple(Fraction(SHIFT if ((character[0] * state[0] + character[1] * state[1]) % DUAL == 0) else -SHIFT) for state in occupancies)
        for character in occupancies
    )
    xor_table = tuple(
        tuple(occupancies.index((left[0] ^ right[0], left[1] ^ right[1])) for right in occupancies)
        for left in occupancies
    )
    force_readout = (
        total_burden,
        shadow_sign,
        zero_type,
        closure_pair,
    )
    return {
        'labels': labels,
        'occupancies': occupancies,
        'projectors': projectors,
        'shadow_sign': shadow_sign,
        'total_burden': total_burden,
        'closure_pair': closure_pair,
        'open_residual': open_residual,
        'zero_type': zero_type,
        'characters': characters,
        'xor_table': xor_table,
        'force_readout': force_readout,
    }


def _relation_dot(left, right):
    return sum((Fraction(left[index]) * Fraction(right[index]) for index in range(len(left))), Fraction(0))


def _relation_subtract(left, right):
    return tuple(Fraction(left[index]) - Fraction(right[index]) for index in range(len(left)))


def _relation_cross(left, right):
    return (
        left[1] * right[2] - left[2] * right[1],
        left[2] * right[0] - left[0] * right[2],
        left[0] * right[1] - left[1] * right[0],
    )


def _relation_root_polytope_data():
    roots = []
    for source in range(len(_double_zero_state_data()['labels'])):
        for target in range(len(_double_zero_state_data()['labels'])):
            if source == target:
                continue
            vector = tuple(Fraction((SHIFT if axis == source else 0) - (SHIFT if axis == target else 0)) for axis in range(len(_double_zero_state_data()['labels'])))
            coordinate = (
                vector[0] - vector[1],
                vector[1] - vector[2],
                vector[2] - vector[3],
            )
            roots.append((source, target, vector, coordinate))
    roots = tuple(roots)
    pair_to_index = {(row[0], row[1]): index for index, row in enumerate(roots)}
    edges = tuple(
        (left, right)
        for left in range(len(roots))
        for right in range(left + SHIFT, len(roots))
        if _relation_dot(roots[left][2], roots[right][2]) == SHIFT
    )
    edge_set = frozenset(frozenset(edge) for edge in edges)
    facet_map = {}
    support_rows = []
    for triple in itertools.combinations(range(len(roots)), ROUTE_TRIPLET):
        first, second, third = (roots[index][3] for index in triple)
        normal = _relation_cross(_relation_subtract(second, first), _relation_subtract(third, first))
        if normal == (0, 0, 0):
            continue
        level = _relation_dot(normal, first)
        offsets = tuple(_relation_dot(normal, row[3]) - level for row in roots)
        one_side = all(value <= 0 for value in offsets) or all(value >= 0 for value in offsets)
        if not one_side:
            continue
        equality = frozenset(index for index, value in enumerate(offsets) if value == 0)
        if len(equality) < ROUTE_TRIPLET:
            continue
        if equality not in facet_map:
            facet_map[equality] = (normal, level)
            support_rows.append((tuple(sorted(equality)), normal, level, min(offsets), max(offsets), one_side))
    facets = tuple(sorted((tuple(sorted(facet)) for facet in facet_map), key=lambda row: (len(row), row)))
    triangles = tuple(face for face in facets if len(face) == ROUTE_TRIPLET)
    squares = tuple(face for face in facets if len(face) == len(TRANSFORMER_LAYER_LABELS))
    vertex_degrees = tuple(sum(SHIFT for edge in edges if vertex in edge) for vertex in range(len(roots)))
    edge_face_rows = []
    for edge in edges:
        containing = tuple(face for face in facets if edge[0] in face and edge[1] in face)
        edge_face_rows.append((edge, containing, tuple(len(face) for face in containing)))
    opposite_pairs = tuple(
        (left, right)
        for left in range(len(roots))
        for right in range(left + SHIFT, len(roots))
        if all(roots[left][2][axis] == -roots[right][2][axis] for axis in range(len(roots[left][2])))
    )
    return {
        'roots': roots,
        'pair_to_index': pair_to_index,
        'edges': edges,
        'edge_set': edge_set,
        'facets': facets,
        'triangles': triangles,
        'squares': squares,
        'support_rows': tuple(support_rows),
        'vertex_degrees': vertex_degrees,
        'edge_face_rows': tuple(edge_face_rows),
        'opposite_pairs': opposite_pairs,
    }


def _canonical_face_cycle(face, edge_set):
    vertices = tuple(sorted(face))
    if len(vertices) == ROUTE_TRIPLET:
        return vertices
    adjacency = {
        vertex: tuple(sorted(other for other in vertices if other != vertex and frozenset((vertex, other)) in edge_set))
        for vertex in vertices
    }
    start = vertices[0]
    second = adjacency[start][0]
    cycle = [start, second]
    while len(cycle) < len(vertices):
        previous = cycle[-DUAL]
        current = cycle[-SHIFT]
        candidates = tuple(vertex for vertex in adjacency[current] if vertex != previous and vertex != start)
        if not candidates:
            candidates = tuple(vertex for vertex in adjacency[current] if vertex != previous)
        cycle.append(candidates[0])
    return tuple(cycle)


def _surface_chain_data():
    data = _relation_root_polytope_data()
    faces = data['triangles'] + data['squares']
    raw_cycles = tuple(_canonical_face_cycle(face, data['edge_set']) for face in faces)
    edge_index = {edge: index for index, edge in enumerate(data['edges'])}

    def cycle_coefficients(cycle):
        coefficients = {}
        for index in range(len(cycle)):
            source = cycle[index]
            target = cycle[(index + SHIFT) % len(cycle)]
            edge = (source, target) if source < target else (target, source)
            coefficients[edge] = SHIFT if source < target else -SHIFT
        return coefficients

    raw_coefficients = tuple(cycle_coefficients(cycle) for cycle in raw_cycles)
    edge_faces = {edge: [] for edge in data['edges']}
    for face_index, coefficients in enumerate(raw_coefficients):
        for edge, coefficient in coefficients.items():
            edge_faces[edge].append((face_index, coefficient))
    signs = {0: SHIFT}
    stack = [0]
    while stack:
        face_index = stack.pop()
        for edge, coefficient in raw_coefficients[face_index].items():
            for other_index, other_coefficient in edge_faces[edge]:
                if other_index == face_index:
                    continue
                required = -signs[face_index] * coefficient // other_coefficient
                if other_index not in signs:
                    signs[other_index] = required
                    stack.append(other_index)
                else:
                    assert signs[other_index] == required
    oriented_cycles = tuple(cycle if signs[index] == SHIFT else tuple(reversed(cycle)) for index, cycle in enumerate(raw_cycles))
    oriented_coefficients = tuple(cycle_coefficients(cycle) for cycle in oriented_cycles)
    boundary_one = [[Fraction(0) for _ in data['edges']] for _ in data['roots']]
    for column, (source, target) in enumerate(data['edges']):
        boundary_one[source][column] = Fraction(-SHIFT)
        boundary_one[target][column] = Fraction(SHIFT)
    boundary_two = [[Fraction(0) for _ in faces] for _ in data['edges']]
    for column, coefficients in enumerate(oriented_coefficients):
        for edge, coefficient in coefficients.items():
            boundary_two[edge_index[edge]][column] = Fraction(coefficient)
    boundary_one = tuple(tuple(row) for row in boundary_one)
    boundary_two = tuple(tuple(row) for row in boundary_two)
    boundary_composition = _u876_multiply(boundary_one, boundary_two)
    total_surface_boundary = tuple(sum((boundary_two[row][column] for column in range(len(faces))), Fraction(0)) for row in range(len(data['edges'])))
    return {
        'faces': faces,
        'raw_cycles': raw_cycles,
        'orientation_signs': tuple(signs[index] for index in range(len(faces))),
        'oriented_cycles': oriented_cycles,
        'boundary_one': boundary_one,
        'boundary_two': boundary_two,
        'boundary_composition': boundary_composition,
        'total_surface_boundary': total_surface_boundary,
    }


def _encode_radix(value, base):
    digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    if value == 0:
        return '0'
    result = ''
    remaining = value
    while remaining:
        remaining, digit = divmod(remaining, base)
        result = digits[digit] + result
    return result


def _decode_radix(text, base):
    digits = {character: index for index, character in enumerate('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ')}
    value = 0
    for character in text:
        value = value * base + digits[character]
    return value


def _double_zero_primitive_algebra_theorem():
    """Derive four primitive occupancy states, two inequivalent zero states, and the complete character frame from two polarity projectors."""
    data = _double_zero_state_data()
    empty, negative, positive, full = data['projectors']
    matrix_rows = (
        ('EMPTY_ZERO', _matrix_trace(empty), _matrix_fraction_rank(empty)),
        ('NEGATIVE', _matrix_trace(negative), _matrix_fraction_rank(negative)),
        ('POSITIVE', _matrix_trace(positive), _matrix_fraction_rank(positive)),
        ('FULL_ZERO', _matrix_trace(full), _matrix_fraction_rank(full)),
    )
    zero_fiber = tuple(index for index, value in enumerate(data['shadow_sign']) if value == 0)
    character_gram = _u876_multiply(data['characters'], _u876_transpose(data['characters']))
    labels, existing_frame, existing_inverse = _u876_projection_frame_data()
    xor_rows = []
    for left in range(len(data['occupancies'])):
        for right in range(len(data['occupancies'])):
            result = data['xor_table'][left][right]
            reverse = data['xor_table'][right][left]
            xor_rows.append((left, right, result, reverse, result == reverse))
    pair_shadow_rows = tuple(
        (
            data['labels'][index],
            data['shadow_sign'][index],
            data['closure_pair'][index],
            (data['shadow_sign'][index], data['closure_pair'][index]),
        )
        for index in range(len(data['labels']))
    )
    theorem_result = all((
        _matrix_add(negative, positive) == full,
        empty != full,
        zero_fiber == (0, ROUTE_TRIPLET),
        data['shadow_sign'] == (Fraction(0), Fraction(-SHIFT), Fraction(SHIFT), Fraction(0)),
        data['closure_pair'] == (Fraction(0), Fraction(0), Fraction(0), Fraction(SHIFT)),
        tuple(row[2] for row in matrix_rows) == (0, SHIFT, SHIFT, DUAL),
        tuple(row[1] for row in matrix_rows) == (0, SHIFT, SHIFT, DUAL),
        len(set((row[1], row[2]) for row in pair_shadow_rows)) == len(pair_shadow_rows),
        character_gram == _u876_scale(Fraction(len(data['characters'])), _u876_identity(len(data['characters']))),
        data['characters'] == existing_frame,
        _u876_multiply(existing_inverse, data['characters']) == _u876_identity(len(data['characters'])),
        all(row[-1] for row in xor_rows),
        all(data['xor_table'][state][state] == 0 for state in range(len(data['occupancies']))),
    ))
    return {
        'proof_title': 'DOUBLE ZERO PRIMITIVE ALGEBRA THEOREM',
        'primitive_state_labels': data['labels'],
        'polarity_occupancies': data['occupancies'],
        'primitive_projectors': data['projectors'],
        'projector_trace_rank_rows': matrix_rows,
        'signed_shadow_values': data['shadow_sign'],
        'zero_shadow_fiber': zero_fiber,
        'closure_pair_values': data['closure_pair'],
        'shadow_closure_bijection_rows': pair_shadow_rows,
        'primitive_xor_table': data['xor_table'],
        'primitive_xor_rows': tuple(xor_rows),
        'character_frame': data['characters'],
        'character_gram': character_gram,
        'scope': 'exact four-state occupancy algebra generated by two polarity projectors, with empty zero and full zero distinct in the origin layer although both have zero signed shadow',
        'theorem_result': theorem_result,
    }


def _residual_closure_conservation_theorem():
    """Prove the unique lossless decomposition of every nonnegative polarity ledger into signed residual and closed pairs."""
    branch_identities = (
        ('POSITIVE_DOMINANT', ('N=C', 'P=C+D'), ('R=D', 'T=2C+D'), ('N=C', 'P=C+R')),
        ('NEGATIVE_DOMINANT', ('N=C+D', 'P=C'), ('R=-D', 'T=2C+D'), ('N=C-R', 'P=C')),
    )
    rows = []
    for negative_count in range(C12 + SHIFT):
        for positive_count in range(C12 + SHIFT):
            residual = positive_count - negative_count
            closure = min(negative_count, positive_count)
            total = negative_count + positive_count
            recovered_negative = closure + max(-residual, 0)
            recovered_positive = closure + max(residual, 0)
            rows.append((negative_count, positive_count, residual, closure, total, recovered_negative, recovered_positive, total == abs(residual) + DUAL * closure, recovered_negative == negative_count, recovered_positive == positive_count))
    balanced_rows = tuple(
        (count, count, 0, count, DUAL * count, abs(0) + DUAL * count)
        for count in range(C12 + SHIFT)
    )
    sample = next(row for row in rows if row[0] == ROUTE_TRIPLET and row[1] == DUAL)
    theorem_result = all((
        all(row[-3] and row[-2] and row[-1] for row in rows),
        all(row[4] == row[5] for row in balanced_rows),
        sample[2:7] == (-SHIFT, DUAL, G5, ROUTE_TRIPLET, DUAL),
        branch_identities[0][1:] == (('N=C', 'P=C+D'), ('R=D', 'T=2C+D'), ('N=C', 'P=C+R')),
        branch_identities[1][1:] == (('N=C+D', 'P=C'), ('R=-D', 'T=2C+D'), ('N=C-R', 'P=C')),
    ))
    return {
        'proof_title': 'RESIDUAL CLOSURE CONSERVATION THEOREM',
        'general_branch_identities': branch_identities,
        'all_checked_nonnegative_ledger_rows': tuple(rows),
        'balanced_full_zero_rows': balanced_rows,
        'negative_dominant_example': sample,
        'conservation_identity': 'T=ABS(R)+2C',
        'reconstruction_identity': ('N=C+MAX(-R,0)', 'P=C+MAX(R,0)'),
        'scope': 'lossless signed-residual and closed-pair decomposition of a two-polarity ledger, distinguishing cancellation in the shadow from deletion in the origin ledger',
        'theorem_result': theorem_result,
    }


def _radix_independent_relation_structure_theorem():
    """Prove that numeral bases and state names change representation only, while rank, character orthogonality, relation roots, edges, and facets remain invariant."""
    state_data = _double_zero_state_data()
    root_data = _relation_root_polytope_data()
    representation_rows = tuple(
        (value, tuple((base, _encode_radix(value, base), _decode_radix(_encode_radix(value, base), base)) for base in (DUAL, ROUTE_TRIPLET, TOTAL, C12)))
        for value in range(C12)
    )
    permutation_rows = []
    original_facets = frozenset(frozenset(face) for face in root_data['facets'])
    original_edges = frozenset(frozenset(edge) for edge in root_data['edges'])
    for permutation in itertools.permutations(range(len(state_data['labels']))):
        column_permuted = tuple(tuple(row[permutation[column]] for column in range(len(permutation))) for row in state_data['characters'])
        gram = _u876_multiply(column_permuted, _u876_transpose(column_permuted))
        index_map = {
            index: root_data['pair_to_index'][(permutation[root[0]], permutation[root[1]])]
            for index, root in enumerate(root_data['roots'])
        }
        mapped_edges = frozenset(frozenset((index_map[edge[0]], index_map[edge[1]])) for edge in root_data['edges'])
        mapped_facets = frozenset(frozenset(index_map[vertex] for vertex in face) for face in root_data['facets'])
        permutation_rows.append((permutation, gram == _u876_scale(Fraction(len(permutation)), _u876_identity(len(permutation))), mapped_edges == original_edges, mapped_facets == original_facets))
    shadow_image = tuple(sorted(set(state_data['shadow_sign'])))
    shadow_closure_pairs = tuple((state_data['shadow_sign'][index], state_data['closure_pair'][index]) for index in range(len(state_data['labels'])))
    theorem_result = all((
        all(decoded == value for value, encodings in representation_rows for _, _, decoded in encodings),
        all(row[1] and row[2] and row[3] for row in permutation_rows),
        shadow_image == (Fraction(-SHIFT), Fraction(0), Fraction(SHIFT)),
        len(set(state_data['shadow_sign'])) == ROUTE_TRIPLET,
        len(set(shadow_closure_pairs)) == len(state_data['labels']),
        len(root_data['roots']) == C12,
        len(root_data['edges']) == DUAL * C12,
        len(root_data['facets']) == C12 + DUAL,
    ))
    return {
        'proof_title': 'RADIX INDEPENDENT RELATION STRUCTURE THEOREM',
        'radix_representation_rows': representation_rows,
        'all_state_relabeling_invariance_rows': tuple(permutation_rows),
        'ternary_shadow_image': shadow_image,
        'ternary_shadow_is_not_injective': True,
        'shadow_plus_closure_is_injective': len(set(shadow_closure_pairs)) == len(state_data['labels']),
        'invariant_relation_counts': (len(root_data['roots']), len(root_data['edges']), len(root_data['triangles']), len(root_data['squares']), len(root_data['facets'])),
        'scope': 'representation independence under binary, ternary, decimal, duodecimal, and all state relabelings, with the physical invariants carried by matrices, ranks, roots, incidence, and closed cycles rather than numeral notation',
        'theorem_result': theorem_result,
    }


