def _u882_residual_closure_phase_ledger_theorem():
    """Separate conserved polarity content, closed-pair depth, and the binary open-closed phase without deleting balanced content."""
    rows = []
    for negative in range(G5):
        for closure_phase in range(DUAL):
            for positive in range(G5):
                pair_depth = min(negative, positive)
                residue = positive - negative
                burden = negative + positive
                recovered_negative = pair_depth + max(-residue, 0)
                recovered_positive = pair_depth + max(residue, 0)
                rows.append((
                    (negative, closure_phase, positive),
                    residue,
                    pair_depth,
                    closure_phase,
                    burden,
                    recovered_negative,
                    recovered_positive,
                    recovered_negative == negative and recovered_positive == positive,
                    burden == abs(residue) + DUAL * pair_depth,
                ))
    reduction_rows = []
    for negative in range(G5):
        for closed_pairs in range(G5):
            for positive in range(G5):
                transfer = min(negative, positive)
                reduced = (negative - transfer, closed_pairs + transfer, positive - transfer)
                before_burden = negative + positive + DUAL * closed_pairs
                after_burden = reduced[0] + reduced[2] + DUAL * reduced[1]
                reduction_rows.append((
                    (negative, closed_pairs, positive),
                    transfer,
                    reduced,
                    positive - negative,
                    reduced[2] - reduced[0],
                    before_burden,
                    after_burden,
                    reduced[0] == 0 or reduced[2] == 0,
                ))
    theorem_result = all((
        all(row[-2] and row[-1] for row in rows),
        all(row[3] in (0, SHIFT) for row in rows),
        all(row[3] == row[4] and row[5] == row[6] and row[7] for row in reduction_rows),
        len(rows) == G5 * DUAL * G5,
        len(reduction_rows) == G5 ** ROUTE_TRIPLET,
    ))
    return {
        'proof_title': 'RESIDUAL CLOSURE PHASE LEDGER THEOREM',
        'lossless_residue_pair_phase_rows': tuple(rows),
        'pair_transfer_reduction_rows': tuple(reduction_rows),
        'balanced_content_identity': 'T=ABS(R)+2C',
        'phase_is_distinct_from_pair_depth': True,
        'scope': 'lossless decomposition of arbitrary nonnegative polarity counts into signed residue and pair depth while retaining an independent binary closure phase; pair transfer changes representation but preserves sign and total constituent burden',
        'theorem_result': theorem_result,
    }


