def _u883_rational_null_triples():
    """Generate primitive rational null triples from internal integer pairs."""
    generator_pairs = ((DUAL, SHIFT), (ROUTE_TRIPLET, DUAL), (DUAL * DUAL, SHIFT))
    return tuple(
        (major * major + minor * minor, major * major - minor * minor, DUAL * major * minor)
        for major, minor in generator_pairs
    )


def _u883_minkowski_dot(left, right):
    """Return the exact (-,+,+,+) bilinear form."""
    return -left[0] * right[0] + sum((left[index] * right[index] for index in range(1, 4)), Fraction(0))


def _u883_field_tensor(momentum, polarization):
    """Return F^{mu nu}=k^mu e^nu-k^nu e^mu."""
    return tuple(
        tuple(momentum[mu] * polarization[nu] - momentum[nu] * polarization[mu] for nu in range(4))
        for mu in range(4)
    )


def _u883_complex_pair_multiply(left, right):
    """Multiply exact complex numbers represented by rational pairs."""
    return (
        left[0] * right[0] - left[1] * right[1],
        left[0] * right[1] + left[1] * right[0],
    )


def _u883_kronecker(left, right):
    """Return an exact Kronecker product."""
    return tuple(
        tuple(left[i][j] * right[k][ell] for j in range(len(left[0])) for ell in range(len(right[0])))
        for i in range(len(left))
        for k in range(len(right))
    )


def _u883_maxwell_from_open_balanced_zero_theorem():
    """Derive exact vacuum Maxwell identities from the open balanced two-polarization carrier."""
    triples = _u883_rational_null_triples()
    rows = []
