def _u883_polarization_helicity_theorem():
    """Derive two exact transverse helicity sectors without trigonometric input."""
    quarter_turn = (
        (Fraction(0), Fraction(-SHIFT)),
        (Fraction(SHIFT), Fraction(0)),
    )
    minus_identity = _u876_scale(Fraction(-SHIFT), _u876_identity(DUAL))
    helicity_rows = []
    for helicity_sign in (-SHIFT, SHIFT):
        real = (Fraction(SHIFT), Fraction(0))
        imaginary = (Fraction(0), Fraction(-helicity_sign))
