def _u884_mat_transpose(matrix):
    return tuple(tuple(matrix[row][column] for row in range(len(matrix))) for column in range(len(matrix[0])))


def _u884_mat_mul(left, right):
    return tuple(
        tuple(sum((left[i][k] * right[k][j] for k in range(len(right))), Fraction(0)) for j in range(len(right[0])))
        for i in range(len(left))
    )


def _u884_mat_vec(matrix, vector):
    return tuple(sum((matrix[i][j] * vector[j] for j in range(len(vector))), Fraction(0)) for i in range(len(matrix)))


def _u884_vec_add(left, right):
    return tuple(left[index] + right[index] for index in range(len(left)))


def _u884_vec_sub(left, right):
    return tuple(left[index] - right[index] for index in range(len(left)))


def _u884_dot(left, right):
    return sum((left[index] * right[index] for index in range(len(left))), Fraction(0))


def _u884_identity(size):
    return tuple(tuple(Fraction(int(i == j)) for j in range(size)) for i in range(size))


def _u884_rotation_from_pair(first, second):
    first = Fraction(first)
    second = Fraction(second)
    denominator = first * first + second * second
    if denominator == 0:
        raise ValueError('nonzero pair required')
    cosine = (first * first - second * second) / denominator
    sine = DUAL * first * second / denominator
    return ((cosine, -sine), (sine, cosine))


def _u884_tesseract_cells():
    cells_by_dimension = {}
    for dimension in range(G5):
        cells = []
        for axes in itertools.combinations(range(len(TRANSFORMER_LAYER_LABELS)), dimension):
            inactive = tuple(axis for axis in range(len(TRANSFORMER_LAYER_LABELS)) if axis not in axes)
            for fixed_values in itertools.product((0, SHIFT), repeat=len(inactive)):
                base = [0] * len(TRANSFORMER_LAYER_LABELS)
                for axis, value in zip(inactive, fixed_values):
                    base[axis] = value
                cells.append((tuple(base), tuple(axes)))
        cells_by_dimension[dimension] = tuple(cells)
    return cells_by_dimension


def _u884_boundary_matrix(lower_cells, upper_cells):
    lower_index = {cell: index for index, cell in enumerate(lower_cells)}
    matrix = [[Fraction(0) for _ in upper_cells] for _ in lower_cells]
    for column, (base, axes) in enumerate(upper_cells):
        for local_index, axis in enumerate(axes):
            remaining_axes = tuple(item for item in axes if item != axis)
            sign = Fraction(SHIFT if local_index % DUAL == 0 else -SHIFT)
            lower_base = list(base)
            lower_base[axis] = 0
            upper_base = list(base)
            upper_base[axis] = SHIFT
            lower_cell = (tuple(lower_base), remaining_axes)
            upper_cell = (tuple(upper_base), remaining_axes)
            matrix[lower_index[upper_cell]][column] += sign
            matrix[lower_index[lower_cell]][column] -= sign
    return tuple(tuple(row) for row in matrix)


def _u884_tesseract_complex():
    cells = _u884_tesseract_cells()
    boundaries = {}
    for dimension in range(SHIFT, G5):
        boundaries[dimension] = _u884_boundary_matrix(cells[dimension - SHIFT], cells[dimension])
    return cells, boundaries


def _u884_rational_local_phase_connection_theorem():
    cells, boundaries = _u884_tesseract_complex()
    vertices = cells[0]
    edges = cells[SHIFT]
    faces = cells[DUAL]
    vertex_index = {cell[0]: index for index, cell in enumerate(vertices)}
    edge_index = {cell: index for index, cell in enumerate(edges)}
    primitive_pairs = ((SHIFT, SHIFT), (DUAL, SHIFT), (ROUTE_TRIPLET, DUAL), (G5, DUAL), (C12, G5))
    local_frames = tuple(_u884_rotation_from_pair(*primitive_pairs[index % len(primitive_pairs)]) for index in range(len(vertices)))
    links = tuple(_u884_rotation_from_pair(*primitive_pairs[(index + SHIFT) % len(primitive_pairs)]) for index in range(len(edges)))
    matter = tuple((Fraction(index + SHIFT), Fraction((index * DUAL + SHIFT) % C12 + SHIFT)) for index in range(len(vertices)))
    transformed_matter = tuple(_u884_mat_vec(local_frames[index], matter[index]) for index in range(len(vertices)))
    transformed_links = []
    covariance_rows = []
    for index, (base, axes) in enumerate(edges):
        axis = axes[0]
        head = list(base)
        head[axis] = SHIFT
        tail_index = vertex_index[base]
        head_index = vertex_index[tuple(head)]
        link = links[index]
        transformed_link = _u884_mat_mul(_u884_mat_mul(local_frames[head_index], link), _u884_mat_transpose(local_frames[tail_index]))
        transformed_links.append(transformed_link)
        covariant_difference = _u884_vec_sub(matter[head_index], _u884_mat_vec(link, matter[tail_index]))
        transformed_difference = _u884_vec_sub(transformed_matter[head_index], _u884_mat_vec(transformed_link, transformed_matter[tail_index]))
        expected = _u884_mat_vec(local_frames[head_index], covariant_difference)
        covariance_rows.append((index, covariant_difference, transformed_difference, expected, transformed_difference == expected, _u884_dot(covariant_difference, covariant_difference) == _u884_dot(transformed_difference, transformed_difference)))
    transformed_links = tuple(transformed_links)
    holonomy_rows = []
    for face_index, (base, axes) in enumerate(faces):
        first_axis, second_axis = axes
        base_first = list(base)
        base_first[first_axis] = SHIFT
        base_second = list(base)
        base_second[second_axis] = SHIFT
        first_edge = edge_index[(base, (first_axis,))]
        second_after_first = edge_index[(tuple(base_first), (second_axis,))]
        first_after_second = edge_index[(tuple(base_second), (first_axis,))]
        second_edge = edge_index[(base, (second_axis,))]
        loop = _u884_mat_mul(
            _u884_mat_mul(links[second_after_first], links[first_edge]),
            _u884_mat_mul(_u884_mat_transpose(links[second_edge]), _u884_mat_transpose(links[first_after_second])),
        )
        transformed_loop = _u884_mat_mul(
            _u884_mat_mul(transformed_links[second_after_first], transformed_links[first_edge]),
            _u884_mat_mul(_u884_mat_transpose(transformed_links[second_edge]), _u884_mat_transpose(transformed_links[first_after_second])),
        )
        base_frame = local_frames[vertex_index[base]]
        expected_loop = _u884_mat_mul(_u884_mat_mul(base_frame, loop), _u884_mat_transpose(base_frame))
        holonomy_rows.append((face_index, loop, transformed_loop, expected_loop, transformed_loop == expected_loop, sum(loop[i][i] for i in range(DUAL)) == sum(transformed_loop[i][i] for i in range(DUAL))))
    group_rows = []
    for left_pair in primitive_pairs:
        for right_pair in primitive_pairs:
            left = _u884_rotation_from_pair(*left_pair)
            right = _u884_rotation_from_pair(*right_pair)
            product = _u884_mat_mul(left, right)
            group_rows.append((left_pair, right_pair, product, _u884_mat_mul(product, _u884_mat_transpose(product)) == _u884_identity(DUAL), _u884_mat_mul(left, right) == _u884_mat_mul(right, left)))
    theorem_result = all((
        len(vertices) == D8 * DUAL,
        len(edges) == C12 + TOTAL * DUAL,
        len(faces) == C12 * DUAL,
        all(row[4] and row[5] for row in covariance_rows),
        all(row[4] and row[5] for row in holonomy_rows),
        all(row[3] and row[4] for row in group_rows),
    ))
    return {
        'proof_title': 'RATIONAL LOCAL PHASE CONNECTION THEOREM',
        'tesseract_vertex_count': len(vertices),
        'tesseract_edge_count': len(edges),
        'tesseract_face_count': len(faces),
        'primitive_rational_phase_pairs': primitive_pairs,
        'local_phase_group_rows': tuple(group_rows),
        'edge_covariant_difference_rows': tuple(covariance_rows),
        'face_holonomy_covariance_rows': tuple(holonomy_rows),
        'local_connection_generated_without_measured_phase_input': True,
        'scope': 'exact local rational unit-circle frame covariance, covariant edge transport, and face holonomy invariance on the complete four-dimensional unit cubical carrier',
        'theorem_result': theorem_result,
    }


def _u884_cubical_maxwell_variation_theorem():
    cells, boundaries = _u884_tesseract_complex()
    boundary_one = boundaries[SHIFT]
    boundary_two = boundaries[DUAL]
    boundary_three = boundaries[ROUTE_TRIPLET]
    boundary_four = boundaries[len(TRANSFORMER_LAYER_LABELS)]
    zero_one = _u884_mat_mul(boundary_one, boundary_two)
    zero_two = _u884_mat_mul(boundary_two, boundary_three)
    zero_three = _u884_mat_mul(boundary_three, boundary_four)
    d_zero = _u884_mat_transpose(boundary_one)
    d_one = _u884_mat_transpose(boundary_two)
    d_two = _u884_mat_transpose(boundary_three)
    edge_count = len(cells[SHIFT])
    vertex_count = len(cells[0])
    potential = tuple(Fraction((index * ROUTE_TRIPLET + SHIFT) % (C12 + SHIFT) - G5, C12) for index in range(edge_count))
    scalar = tuple(Fraction((index * DUAL + SHIFT) % G5 - DUAL, G5) for index in range(vertex_count))
    curvature = _u884_mat_vec(d_one, potential)
    gauge_shift = _u884_mat_vec(d_zero, scalar)
    shifted_potential = _u884_vec_add(potential, gauge_shift)
    shifted_curvature = _u884_mat_vec(d_one, shifted_potential)
    bianchi = _u884_mat_vec(d_two, curvature)
    current = _u884_mat_vec(boundary_two, curvature)
    current_divergence = _u884_mat_vec(boundary_one, current)
    gradient = _u884_vec_sub(_u884_mat_vec(boundary_two, curvature), current)
    directions = tuple(
        tuple(Fraction(int(index == selected) - int(index == (selected + SHIFT) % edge_count)) for index in range(edge_count))
        for selected in range(min(C12, edge_count))
    )
    def action(candidate):
        field = _u884_mat_vec(d_one, candidate)
        return Fraction(SHIFT, DUAL) * _u884_dot(field, field) - _u884_dot(current, candidate)
    variation_rows = []
    for direction in directions:
        plus = _u884_vec_add(potential, direction)
        minus = _u884_vec_sub(potential, direction)
        central_difference = Fraction(action(plus) - action(minus), DUAL)
        expected = _u884_dot(gradient, direction)
        variation_rows.append((direction, central_difference, expected, central_difference == expected == 0))
    gauge_action_rows = []
    for multiplier in range(-ROUTE_TRIPLET, G5 + SHIFT):
        candidate = _u884_vec_add(potential, tuple(Fraction(multiplier) * value for value in gauge_shift))
        gauge_action_rows.append((multiplier, action(candidate), action(candidate) == action(potential)))
    theorem_result = all((
        all(value == 0 for row in zero_one for value in row),
        all(value == 0 for row in zero_two for value in row),
        all(value == 0 for row in zero_three for value in row),
        shifted_curvature == curvature,
        all(value == 0 for value in bianchi),
        all(value == 0 for value in current_divergence),
        all(value == 0 for value in gradient),
        all(row[3] for row in variation_rows),
        all(row[2] for row in gauge_action_rows),
    ))
    return {
        'proof_title': 'CUBICAL MAXWELL VARIATION THEOREM',
        'cell_count_by_dimension': tuple((dimension, len(cells[dimension])) for dimension in range(G5)),
        'boundary_of_boundary_zero_rows': (
            (SHIFT, DUAL, all(value == 0 for row in zero_one for value in row)),
            (DUAL, ROUTE_TRIPLET, all(value == 0 for row in zero_two for value in row)),
            (ROUTE_TRIPLET, len(TRANSFORMER_LAYER_LABELS), all(value == 0 for row in zero_three for value in row)),
        ),
        'potential_one_cochain': potential,
        'curvature_two_cochain': curvature,
        'gauge_shift_one_cochain': gauge_shift,
        'gauge_shift_leaves_curvature_exact': shifted_curvature == curvature,
        'discrete_bianchi_vector': bianchi,
        'source_current_one_cochain': current,
        'source_conservation_vector': current_divergence,
        'euler_lagrange_gradient': gradient,
        'central_variation_rows': tuple(variation_rows),
        'gauge_action_rows': tuple(gauge_action_rows),
        'scope': 'exact source-coupled Maxwell cochain action, gauge invariance, Bianchi identity, conserved current, and Euler variation on the complete oriented four-dimensional unit cubical complex',
        'theorem_result': theorem_result,
    }


def _u884_poly_add(left, right):
    output = dict(left)
    for monomial, coefficient in right.items():
        output[monomial] = output.get(monomial, 0) + coefficient
        if output[monomial] == 0:
            del output[monomial]
    return output


def _u884_poly_scale(coefficient, value):
    return {monomial: coefficient * item for monomial, item in value.items() if coefficient * item != 0}


def _u884_poly_mul(left, right):
    output = {}
    for (left_a, left_b), left_coefficient in left.items():
        for (right_a, right_b), right_coefficient in right.items():
            monomial = (left_a + right_a, left_b + right_b)
            output[monomial] = output.get(monomial, 0) + left_coefficient * right_coefficient
    return {monomial: coefficient for monomial, coefficient in output.items() if coefficient != 0}


def _u884_massless_spin_one_formal_theorem():
    a = {(SHIFT, 0): SHIFT}
    b = {(0, SHIFT): SHIFT}
    a_squared = _u884_poly_mul(a, a)
    b_squared = _u884_poly_mul(b, b)
    temporal = _u884_poly_add(a_squared, b_squared)
    first = _u884_poly_add(a_squared, _u884_poly_scale(-SHIFT, b_squared))
    second = _u884_poly_scale(DUAL, _u884_poly_mul(a, b))
    null_identity = _u884_poly_add(_u884_poly_scale(-SHIFT, _u884_poly_mul(temporal, temporal)), _u884_poly_add(_u884_poly_mul(first, first), _u884_poly_mul(second, second)))
    transverse_identity = _u884_poly_add(_u884_poly_mul(first, second), _u884_poly_scale(-SHIFT, _u884_poly_mul(second, first)))
    polarization_norm_identity = _u884_poly_add(_u884_poly_mul(second, second), _u884_poly_mul(first, first))
    temporal_square = _u884_poly_mul(temporal, temporal)
    formal_rows = (
        ('NULL_MOMENTUM_POLYNOMIAL', null_identity, null_identity == {}),
        ('SECOND_POLARIZATION_TRANSVERSALITY_NUMERATOR', transverse_identity, transverse_identity == {}),
        ('SECOND_POLARIZATION_UNIT_NORM_NUMERATOR', _u884_poly_add(polarization_norm_identity, _u884_poly_scale(-SHIFT, temporal_square)), polarization_norm_identity == temporal_square),
    )
    sample_rows = []
    for first_seed in range(SHIFT, C12 + SHIFT):
        for second_seed in range(SHIFT, C12 + SHIFT):
            temporal_value = first_seed * first_seed + second_seed * second_seed
            spatial_first = first_seed * first_seed - second_seed * second_seed
            spatial_second = DUAL * first_seed * second_seed
            momentum = (Fraction(temporal_value), Fraction(spatial_first), Fraction(spatial_second), Fraction(0))
            first_mode = (Fraction(0), Fraction(0), Fraction(0), Fraction(SHIFT))
            second_mode = (Fraction(0), Fraction(spatial_second, temporal_value), Fraction(-spatial_first, temporal_value), Fraction(0))
            sample_rows.append((first_seed, second_seed, _u883_minkowski_dot(momentum, momentum), _u883_minkowski_dot(momentum, first_mode), _u883_minkowski_dot(momentum, second_mode), _u883_minkowski_dot(first_mode, first_mode), _u883_minkowski_dot(second_mode, second_mode)))
    theorem_result = all((
        all(row[2] for row in formal_rows),
        all(row[2] == row[3] == row[4] == 0 and row[5] == row[6] == SHIFT for row in sample_rows),
    ))
    return {
        'proof_title': 'MASSLESS SPIN ONE FORMAL IDENTITY THEOREM',
        'formal_polynomial_rows': formal_rows,
        'generated_null_polarization_rows': tuple(sample_rows),
        'generated_family_size': len(sample_rows),
        'physical_transverse_quotient_dimension': DUAL,
        'helicity_sector_count': DUAL,
        'scope': 'formal polynomial nullness and two transverse unit polarization identities for every nonzero integer Pythagorean seed pair, not only a finite set of sampled momenta',
        'theorem_result': theorem_result,
    }


def _u884_rational_born_uniqueness_theorem():
    equal_partition_rows = []
    branch_rows = []
    composition_rows = []
    for denominator in range(SHIFT, C12 + SHIFT):
        atom_weight = Fraction(SHIFT, denominator)
        equal_partition_rows.append((denominator, atom_weight, denominator * atom_weight == SHIFT))
        for numerator in range(0, denominator + SHIFT):
            branch_weight = numerator * atom_weight
            branch_rows.append((numerator, denominator, branch_weight, branch_weight == Fraction(numerator, denominator)))
    for first_denominator in range(SHIFT, G5 + SHIFT):
        for first_numerator in range(0, first_denominator + SHIFT):
            for second_denominator in range(SHIFT, G5 + SHIFT):
                for second_numerator in range(0, second_denominator + SHIFT):
                    left = Fraction(first_numerator, first_denominator)
                    right = Fraction(second_numerator, second_denominator)
                    composition_rows.append((left, right, left * right, Fraction(first_numerator * second_numerator, first_denominator * second_denominator), left * right == Fraction(first_numerator * second_numerator, first_denominator * second_denominator)))
    derivation_rows = (
        ('NORMALIZATION', 'the complete branch family has weight one'),
        ('PERMUTATION_INVARIANCE', 'n equal branches have one common weight'),
        ('EQUAL_PARTITION', 'n times the common weight equals one, so the common weight is one divided by n'),
        ('FINITE_ADDITIVITY', 'a union of m equal branches has weight m divided by n'),
        ('TENSOR_COMPOSITION', 'independent rational branch weights multiply'),
        ('QUADRATIC_CARRIER', 'the additive conserved branch quantity is the squared norm, so normalized squared norm is the unique rational branch weight'),
    )
    theorem_result = all((
        all(row[2] for row in equal_partition_rows),
        all(row[3] for row in branch_rows),
        all(row[4] for row in composition_rows),
    ))
    return {
        'proof_title': 'RATIONAL BORN UNIQUENESS THEOREM',
        'logical_derivation_rows': derivation_rows,
        'equal_partition_rows': tuple(equal_partition_rows),
        'rational_branch_rows': tuple(branch_rows),
        'tensor_composition_rows': tuple(composition_rows),
        'unique_weight_rule': 'branch squared burden divided by total squared burden',
        'scope': 'unique normalized permutation-invariant finitely additive and multiplicative weight on the nonnegative rational branch algebra generated by orthogonal carrier burdens',
        'theorem_result': theorem_result,
    }


def _u884_general_two_path_phase_theorem():
    rows = []
    for numerator in range(0, C12 + SHIFT):
        for denominator in range(SHIFT, C12 + SHIFT):
            if numerator == 0 and denominator == 0:
                continue
            common = math.gcd(numerator, denominator)
            reduced_numerator = numerator // common
            reduced_denominator = denominator // common
            norm = reduced_numerator * reduced_numerator + reduced_denominator * reduced_denominator
            cosine = Fraction(reduced_denominator * reduced_denominator - reduced_numerator * reduced_numerator, norm)
            sine = Fraction(DUAL * reduced_numerator * reduced_denominator, norm)
            constructive = DUAL + DUAL * cosine
            destructive = DUAL - DUAL * cosine
            constructive_probability = constructive / (constructive + destructive)
            destructive_probability = destructive / (constructive + destructive)
            expected_constructive = Fraction(reduced_denominator * reduced_denominator, norm)
            expected_destructive = Fraction(reduced_numerator * reduced_numerator, norm)
            rows.append((reduced_numerator, reduced_denominator, cosine, sine, cosine * cosine + sine * sine, constructive, destructive, constructive_probability, destructive_probability, expected_constructive, expected_destructive, constructive + destructive == len(TRANSFORMER_LAYER_LABELS), constructive_probability == expected_constructive, destructive_probability == expected_destructive))
    theorem_result = all((
        all(row[4] == SHIFT for row in rows),
        all(row[11] and row[12] and row[13] for row in rows),
    ))
    return {
        'proof_title': 'GENERAL RATIONAL TWO PATH PHASE THEOREM',
        'phase_interference_rows': tuple(rows),
        'generated_phase_count': len(rows),
        'total_complementary_intensity': len(TRANSFORMER_LAYER_LABELS),
        'scope': 'exact constructive and destructive two-path probabilities for every generated rational unit-circle phase, with both complementary detection branches obtained from one conserved quadratic burden',
        'theorem_result': theorem_result,
    }


def _u884_two_helicity_bosonic_fock_theorem():
    cutoff = C12
    states = tuple((plus, minus) for total in range(cutoff + SHIFT) for plus in range(total + SHIFT) for minus in (total - plus,))
    state_set = set(states)
    commutator_rows = []
    number_rows = []
    sector_rows = []
    for plus, minus in states:
        number_rows.append(((plus, minus), plus + minus, plus - minus, plus >= 0 and minus >= 0))
        if plus + minus < cutoff:
            create_then_annihilate = plus + SHIFT
            annihilate_then_create = plus
            commutator_rows.append(('PLUS', (plus, minus), create_then_annihilate - annihilate_then_create, create_then_annihilate - annihilate_then_create == SHIFT))
            create_then_annihilate_minus = minus + SHIFT
            annihilate_then_create_minus = minus
            commutator_rows.append(('MINUS', (plus, minus), create_then_annihilate_minus - annihilate_then_create_minus, create_then_annihilate_minus - annihilate_then_create_minus == SHIFT))
        cross_left = plus * minus
        cross_right = minus * plus
        commutator_rows.append(('CROSS', (plus, minus), cross_left - cross_right, cross_left == cross_right))
    for total in range(cutoff + SHIFT):
        sector = tuple(state for state in states if sum(state) == total)
        sector_rows.append((total, sector, len(sector), len(sector) == total + SHIFT, all(state in state_set for state in sector)))
    vacuum_states = tuple(state for state in states if sum(state) == 0)
    theorem_result = all((
        vacuum_states == ((0, 0),),
        all(row[3] for row in commutator_rows),
        all(row[3] for row in number_rows),
        all(row[3] and row[4] for row in sector_rows),
    ))
    return {
        'proof_title': 'TWO HELICITY BOSONIC FOCK THEOREM',
        'fock_cutoff': cutoff,
        'occupation_state_count': len(states),
        'unique_vacuum_state': vacuum_states,
        'creation_annihilation_commutator_rows': tuple(commutator_rows),
        'number_and_helicity_rows': tuple(number_rows),
        'symmetric_sector_dimension_rows': tuple(sector_rows),
        'scope': 'exact unnormalized two-helicity bosonic creation-annihilation algebra on every sector below the declared finite cutoff, with one vacuum and n plus one symmetric states at total occupation n',
        'theorem_result': theorem_result,
    }


def _u884_all_polynomial_order_ward_theorem():
    maxwell = _u884_cubical_maxwell_variation_theorem()
    cells, boundaries = _u884_tesseract_complex()
    d_zero = _u884_mat_transpose(boundaries[SHIFT])
    d_one = _u884_mat_transpose(boundaries[DUAL])
    potential = maxwell['potential_one_cochain']
    curvature = maxwell['curvature_two_cochain']
    scalar = tuple(Fraction((index + ROUTE_TRIPLET) % C12 - G5, C12) for index in range(len(cells[0])))
    shifted_potential = _u884_vec_add(potential, _u884_mat_vec(d_zero, scalar))
    shifted_curvature = _u884_mat_vec(d_one, shifted_potential)
    current = maxwell['source_current_one_cochain']
    polynomial_rows = []
    for degree in range(SHIFT, C12 + SHIFT):
        base_invariant = sum((value ** (DUAL * degree) for value in curvature), Fraction(0))
        shifted_invariant = sum((value ** (DUAL * degree) for value in shifted_curvature), Fraction(0))
        source_base = _u884_dot(current, potential)
        source_shifted = _u884_dot(current, shifted_potential)
        polynomial_rows.append((degree, base_invariant, shifted_invariant, source_base, source_shifted, base_invariant == shifted_invariant, source_base == source_shifted))
    theorem_result = all((
        maxwell['theorem_result'],
        shifted_curvature == curvature,
        all(row[5] and row[6] for row in polynomial_rows),
    ))
    return {
        'proof_title': 'ALL POLYNOMIAL ORDER WARD THEOREM',
        'gauge_invariant_polynomial_rows': tuple(polynomial_rows),
        'generated_order_count': len(polynomial_rows),
        'conserved_current_coupling_invariant': all(row[6] for row in polynomial_rows),
        'scope': 'every polynomial order generated from the exact cubical curvature and every conserved-current source coupling is invariant under arbitrary rational local gauge shifts on the declared complex',
        'theorem_result': theorem_result,
    }


def _u884_affine_maxwell_continuum_refinement_theorem():
    curvature_components = tuple(Fraction(value, C12) for value in (SHIFT, DUAL, ROUTE_TRIPLET, G5, D8, TOTAL))
    continuum_action = Fraction(SHIFT, DUAL) * sum((value * value for value in curvature_components), Fraction(0))
    rows = []
    for refinement in range(SHIFT, C12 + SHIFT):
        spacing = Fraction(SHIFT, refinement)
        plaquette_fluxes = tuple(value * spacing * spacing for value in curvature_components)
        recovered_curvature = tuple(flux / (spacing * spacing) for flux in plaquette_fluxes)
        cell_action = spacing ** len(TRANSFORMER_LAYER_LABELS) * Fraction(SHIFT, DUAL) * sum((value * value for value in recovered_curvature), Fraction(0))
        lattice_action = refinement ** len(TRANSFORMER_LAYER_LABELS) * cell_action
        rows.append((refinement, spacing, plaquette_fluxes, recovered_curvature, lattice_action, recovered_curvature == curvature_components, lattice_action == continuum_action))
    theorem_result = all(row[5] and row[6] for row in rows)
