def _u885_mpoly_clean(poly):
    return {tuple(exponent): Fraction(coefficient) for exponent, coefficient in poly.items() if coefficient != 0}


def _u885_mpoly_add(left, right):
    output = dict(left)
    for exponent, coefficient in right.items():
        output[exponent] = output.get(exponent, Fraction(0)) + coefficient
        if output[exponent] == 0:
            del output[exponent]
    return output


def _u885_mpoly_scale(coefficient, poly):
    coefficient = Fraction(coefficient)
    return {exponent: coefficient * value for exponent, value in poly.items() if coefficient * value != 0}


def _u885_mpoly_mul(left, right):
    output = {}
    for left_exponent, left_coefficient in left.items():
        for right_exponent, right_coefficient in right.items():
            exponent = tuple(left_exponent[index] + right_exponent[index] for index in range(len(left_exponent)))
            output[exponent] = output.get(exponent, Fraction(0)) + left_coefficient * right_coefficient
    return _u885_mpoly_clean(output)


def _u885_mpoly_derivative(poly, axis):
    output = {}
    for exponent, coefficient in poly.items():
        power = exponent[axis]
        if power == 0:
            continue
        next_exponent = list(exponent)
        next_exponent[axis] -= SHIFT
        next_exponent = tuple(next_exponent)
        output[next_exponent] = output.get(next_exponent, Fraction(0)) + coefficient * power
    return _u885_mpoly_clean(output)


def _u885_mpoly_integral_unit(poly):
    total = Fraction(0)
    for exponent, coefficient in poly.items():
        factor = Fraction(1)
        for power in exponent:
            factor /= power + SHIFT
        total += coefficient * factor
    return total


def _u885_mpoly_integral_cell(poly, cell, refinement):
    total = Fraction(0)
    for exponent, coefficient in poly.items():
        factor = Fraction(1)
        for axis, power in enumerate(exponent):
            lower = cell[axis]
            upper = lower + SHIFT
            numerator = upper ** (power + SHIFT) - lower ** (power + SHIFT)
            denominator = (power + SHIFT) * refinement ** (power + SHIFT)
            factor *= Fraction(numerator, denominator)
        total += coefficient * factor
    return total


