def _ofc_cmatrix_scale(coefficient, matrix):
    return tuple(tuple((coefficient * value[0], coefficient * value[1]) for value in row) for row in matrix)


def _ofc_cmatrix_linear_combination(basis, coefficients):
    total = _ofc_czero_matrix(len(basis[0]))
    for coefficient, matrix in zip(coefficients, basis):
        total = _ofc_cmatrix_add(total, _ofc_cmatrix_scale(coefficient, matrix))
    return total


def _ofc_antihermitian_energy(matrix):
    square = _ofc_cmatrix_multiply(matrix, matrix)
    trace = _ofc_cmatrix_trace(square)
    return -trace[0]


