# ---------- nested sign residual genesis ----------
def _nsr_sign(value):
    value = Fraction(value)
    if value < 0:
        return -1
    if value > 0:
        return 1
    return 0


def _nsr_kron_vector(left, right):
    return tuple(Fraction(a) * Fraction(b) for a in left for b in right)


def _nsr_kron_matrix(left, right):
    rows = []
    for left_row in left:
        for right_row in right:
            row = []
            for left_entry in left_row:
                for right_entry in right_row:
                    row.append(Fraction(left_entry) * Fraction(right_entry))
            rows.append(tuple(row))
    return tuple(rows)


def _nsr_identity(size):
    return tuple(tuple(Fraction(int(row == column)) for column in range(size)) for row in range(size))


def _nsr_dot(left, right):
    return sum((Fraction(a) * Fraction(b) for a, b in zip(left, right)), Fraction(0))


def _nsr_outer(left, right):
    return tuple(tuple(Fraction(a) * Fraction(b) for b in right) for a in left)


def _nsr_matrix_sum(matrices, size):
    result = [[Fraction(0) for _ in range(size)] for _ in range(size)]
    for matrix in matrices:
        for row in range(size):
            for column in range(size):
                result[row][column] += Fraction(matrix[row][column])
    return tuple(tuple(row) for row in result)


def _nsr_matvec(matrix, vector):
    return tuple(
        sum((Fraction(matrix[row][column]) * Fraction(vector[column]) for column in range(len(vector))), Fraction(0))
        for row in range(len(matrix))
    )


def _nsr_projector(vectors):
    size = len(vectors[0])
    terms = []
    for vector in vectors:
        norm = _nsr_dot(vector, vector)
        if norm == 0:
            raise ValueError('zero vector')
        terms.append(tuple(tuple(value / norm for value in row) for row in _nsr_outer(vector, vector)))
    return _nsr_matrix_sum(tuple(terms), size)




# ---------- zero structure, saturation, rebasing, and recursive self-similarity ----------
def _zfr_pairwise_contrast(signs):
    return sum(
        abs(signs[left] - signs[right])
        for left in range(len(signs))
        for right in range(left + SHIFT, len(signs))
    )


def _zfr_flow_trajectory(minus_count, plus_count):
    if minus_count < 0 or plus_count < 0:
        raise ValueError('occupation counts must be nonnegative')
    rows = []
    step = 0
    while True:
        half_residual = Fraction(plus_count - minus_count, DUAL)
        mixed_pair_count = minus_count * plus_count
        directional_order = (plus_count - minus_count) * (plus_count - minus_count)
        rows.append((step, minus_count, plus_count, half_residual, mixed_pair_count, directional_order))
        if minus_count == plus_count or minus_count == 0 or plus_count == 0:
            break
        if plus_count > minus_count:
            minus_count -= SHIFT
            plus_count += SHIFT
        else:
            minus_count += SHIFT
            plus_count -= SHIFT
        step += SHIFT
    return tuple(rows)


