def _x893_clip_sign(value: int) -> int:
    return -1 if value < 0 else (1 if value > 0 else 0)


def _x893_qca_norm(state: dict[int, tuple[Fraction, Fraction]]) -> Fraction:
    return sum((left * left + right * right for left, right in state.values()), Fraction(0, 1))


def _x893_qca_step(state: dict[int, tuple[Fraction, Fraction]]) -> dict[int, tuple[Fraction, Fraction]]:
    """One exact local orthogonal coin followed by a conditional nearest-neighbour shift."""
    out: dict[int, tuple[Fraction, Fraction]] = {}
    for position, (left, right) in state.items():
        mixed_left = Fraction(3, 5) * left + Fraction(4, 5) * right
        mixed_right = Fraction(-4, 5) * left + Fraction(3, 5) * right
        a0, b0 = out.get(position - 1, (Fraction(0, 1), Fraction(0, 1)))
        out[position - 1] = (a0 + mixed_left, b0)
        a1, b1 = out.get(position + 1, (Fraction(0, 1), Fraction(0, 1)))
        out[position + 1] = (a1, b1 + mixed_right)
    return {position: pair for position, pair in out.items() if pair != (Fraction(0, 1), Fraction(0, 1))}


