@functools.lru_cache(maxsize=None)
def _onion_shell_closure_theorem() -> dict[str, object]:
    """Derive shell counts, balanced boundary ledgers, and the exact distinction between symbolic closure and a chosen spatial shape."""
    bidirectional = _bidirectional_fractal_limit_theorem()
    alphabet = bidirectional['relation_alphabet']
    branch = len(alphabet)
    outer_sum = sum(seat[0] for seat in alphabet)
    inner_sum = sum(seat[1] for seat in alphabet)
    parity_sum = sum(-SHIFT if seat[2] == 0 else SHIFT for seat in alphabet)
    shell_rows = []
    for depth in range(1, 8):
        word_count = branch ** depth
        repetitions_per_position = branch ** (depth - SHIFT)
        total_outer_flux = depth * repetitions_per_position * outer_sum
        total_inner_flux = depth * repetitions_per_position * inner_sum
        total_fill_flux = depth * repetitions_per_position * parity_sum
        full_occupancy_entries = depth * repetitions_per_position * sum(seat[2] for seat in alphabet)
        cumulative = (branch ** (depth + SHIFT) - SHIFT) // (branch - SHIFT)
        shell_rows.append((
            depth,
            word_count,
            cumulative,
            total_outer_flux,
            total_inner_flux,
            total_fill_flux,
            full_occupancy_entries,
            total_outer_flux == total_inner_flux == total_fill_flux == 0,
        ))
    line_embedding = tuple((index, 0) for index in range(branch))
    grid_embedding = tuple((index % 6, index // 6) for index in range(branch))
    line_distance_signature = tuple(sorted((line_embedding[i][0] - line_embedding[j][0]) ** 2 + (line_embedding[i][1] - line_embedding[j][1]) ** 2 for i in range(branch) for j in range(i + SHIFT, branch)))
    grid_distance_signature = tuple(sorted((grid_embedding[i][0] - grid_embedding[j][0]) ** 2 + (grid_embedding[i][1] - grid_embedding[j][1]) ** 2 for i in range(branch) for j in range(i + SHIFT, branch)))
    orientation_cycle = ((SHIFT, 0), (0, SHIFT), (-SHIFT, 0), (0, -SHIFT))
    orientation_displacement = (
        sum(vector[0] for vector in orientation_cycle),
        sum(vector[1] for vector in orientation_cycle),
    )
    theorem_result = all((
        bidirectional['theorem_result'],
        branch == 18,
        outer_sum == 0,
        inner_sum == 0,
        parity_sum == 0,
        all(row[-1] for row in shell_rows),
        all(row[2] == sum(branch ** level for level in range(row[0] + SHIFT)) for row in shell_rows),
        line_distance_signature != grid_distance_signature,
        orientation_displacement == (0, 0),
    ))
    return {
        'proof_title': 'ONION SHELL CLOSURE THEOREM',
        'reader_principle': 'Layering produces exact shell and cumulative-count laws.  Complete shells close their signed relation ledger, but the same symbolic shell admits inequivalent spatial embeddings, so no sphere, cone, torus, spiral, or branch is selected without an additional embedding rule.',
        'reader_exposition_rows': (
            'The onion analogy refers to nested closure boundaries, not to a claim that the native universe is literally an onion or a sphere.',
            'At every depth the complete relation shell has zero net outer-sign, inner-sign, and fill-parity flux, while its internal occupancy can remain nonzero.',
            'A closed orientation cycle demonstrates how a geometric embedding may close, but another orientation rule may produce an axis, spiral, branch, or another readout.',
        ),
        'single_alphabet_flux': (outer_sum, inner_sum, parity_sum),
        'shell_closure_rows': tuple(shell_rows),
        'shell_count_formula': 'SHELL(depth)=18**depth',
        'cumulative_count_formula': 'CUMULATIVE(depth)=(18**(depth+1)-1)/17',
        'line_embedding_distance_signature': line_distance_signature,
        'grid_embedding_distance_signature': grid_distance_signature,
        'same_symbolic_tree_has_inequivalent_geometric_embeddings': line_distance_signature != grid_distance_signature,
        'closed_orientation_cycle': orientation_cycle,
        'closed_orientation_cycle_displacement': orientation_displacement,
        'symbolic_closure_is_not_a_unique_spatial_shape': True,
        'spatial_embedding_rule_required_for_geometric_or_topological_shape': True,
        'scope': 'exact signed shell closure and geometric-series count laws together with a constructive proof that the relation tree alone underdetermines spatial embedding',
        'theorem_result': theorem_result,
    }


