def _e897_shortest_path(vertices, adjacency, start, target):
    """Return one exact minimum-cost path on a finite rational weighted graph."""
    infinity = None
    distances = {vertex: infinity for vertex in vertices}
    paths = {vertex: None for vertex in vertices}
    distances[start] = Fraction(0, 1)
    paths[start] = (start,)
    unvisited = set(vertices)
    while unvisited:
        current = min(
            (vertex for vertex in unvisited if distances[vertex] is not None),
            key=lambda vertex: (distances[vertex], paths[vertex]),
            default=None,
        )
        if current is None:
            break
        unvisited.remove(current)
        if current == target:
            break
        for neighbor, cost in adjacency[current]:
            candidate_distance = distances[current] + cost
            candidate_path = paths[current] + (neighbor,)
            if distances[neighbor] is None or candidate_distance < distances[neighbor] or (candidate_distance == distances[neighbor] and candidate_path < paths[neighbor]):
                distances[neighbor] = candidate_distance
                paths[neighbor] = candidate_path
    return distances[target], paths[target]


