def _cru_positive_fraction(value):
    return Fraction(value) > 0


def _cru_integer_power(base, exponent):
    base = Fraction(base)
    exponent = int(exponent)
    if exponent >= 0:
        return base ** exponent
    return Fraction(1, 1) / (base ** (-exponent))


def _cru_sector_offsets(dimensions):
    offsets = []
    start = 0
    for dimension in dimensions:
        offsets.append(start)
        start += dimension
    return tuple(offsets)


def _cru_matrix_equal(left, right):
    return tuple(tuple(Fraction(v) for v in row) for row in left) == tuple(tuple(Fraction(v) for v in row) for row in right)


def _cru_quadratic_form(matrix, vector):
    vector = tuple(Fraction(value) for value in vector)
    return sum(
        vector[row] * Fraction(matrix[row][column]) * vector[column]
        for row in range(len(vector))
        for column in range(len(vector))
    )


def _cru_poly_zero_matrix(dimension):
    return _zero_matrix(dimension)


def _cru_poly_matrix_add(left, right):
    degree = max(len(left), len(right))
    dimension = len(left[0] if left else right[0])
    zero = _cru_poly_zero_matrix(dimension)
    rows = []
    for index in range(degree):
        a = left[index] if index < len(left) else zero
        b = right[index] if index < len(right) else zero
        rows.append(_matrix_add(a, b))
    return tuple(rows)


def _cru_poly_matrix_multiply(left, right, maximum_degree=2):
    dimension = len(left[0])
    result = [_cru_poly_zero_matrix(dimension) for _ in range(maximum_degree + 1)]
    for left_degree, left_matrix in enumerate(left):
        for right_degree, right_matrix in enumerate(right):
            degree = left_degree + right_degree
            if degree <= maximum_degree:
                result[degree] = _matrix_add(result[degree], _matrix_multiply(left_matrix, right_matrix))
    return tuple(result)


def _cru_linear_link_series(generator):
    dimension = len(generator)
    return (_u905_identity(dimension), generator, _zero_matrix(dimension))


def _cru_linear_link_inverse_series(generator):
    dimension = len(generator)
    return (
        _u905_identity(dimension),
        _matrix_scale(generator, Fraction(-1)),
        _matrix_multiply(generator, generator),
    )


def _cru_sector_edge_scalars(source_depth, target_depth, source_scale, target_scale, eigenvalues, gravity_index):
    depth_difference = target_depth - source_depth
    values = []
    for index, eigenvalue in enumerate(eigenvalues):
        spectral = _cru_integer_power(Fraction(eigenvalue), depth_difference)
        if index == gravity_index:
            spectral *= Fraction(target_scale, source_scale)
        values.append(spectral)
    return tuple(values)


