def _e898_matrix_multiply(left, right):
    return tuple(
        tuple(sum((left[i][k] * right[k][j] for k in range(len(right))), Fraction(0, 1)) for j in range(len(right[0])))
        for i in range(len(left))
    )


def _e898_matrix_transpose(matrix):
    return tuple(tuple(matrix[j][i] for j in range(len(matrix))) for i in range(len(matrix[0])))


def _e898_matrix_vector(matrix, vector):
    return tuple(sum((matrix[i][j] * vector[j] for j in range(len(vector))), Fraction(0, 1)) for i in range(len(matrix)))


