# READER ORIENTATION: THE FIBER RULE IS NOT LIMITED TO LINEAR MAPS
# Polynomial native motion may be highly nonlinear inside one projection fiber.  A
# projected law remains autonomous exactly when every polynomial readout after the
# native map factors through the chosen effective coordinates.  Polynomial identities
# are represented coefficient by coefficient over exact rational arithmetic.
def _nc_poly_clean(poly):
    return {tuple(monomial): Fraction(coefficient) for monomial, coefficient in poly.items() if Fraction(coefficient) != 0}


def _nc_poly_constant(dimension, value):
    value = Fraction(value)
    return {} if value == 0 else {(0,) * dimension: value}


def _nc_poly_variable(dimension, index):
    exponent = [0] * dimension
    exponent[index] = 1
    return {tuple(exponent): Fraction(1, 1)}


def _nc_poly_add(left, right):
    result = dict(_nc_poly_clean(left))
    for monomial, coefficient in _nc_poly_clean(right).items():
        result[monomial] = result.get(monomial, Fraction(0, 1)) + coefficient
    return _nc_poly_clean(result)


def _nc_poly_scale(scale, poly):
    scale = Fraction(scale)
    return _nc_poly_clean({monomial: scale * coefficient for monomial, coefficient in _nc_poly_clean(poly).items()})


def _nc_poly_multiply(left, right):
    left = _nc_poly_clean(left)
    right = _nc_poly_clean(right)
    if not left or not right:
        return {}
    result = {}
    for monomial_left, coefficient_left in left.items():
        for monomial_right, coefficient_right in right.items():
            monomial = tuple(a + b for a, b in zip(monomial_left, monomial_right))
            result[monomial] = result.get(monomial, Fraction(0, 1)) + coefficient_left * coefficient_right
    return _nc_poly_clean(result)


def _nc_poly_power(poly, power):
    if power < 0:
        raise ValueError('negative polynomial power is not admitted')
    dimension = len(next(iter(poly))) if poly else 1
    result = _nc_poly_constant(dimension, 1)
    factor = _nc_poly_clean(poly)
    for _ in range(power):
        result = _nc_poly_multiply(result, factor)
    return result


def _nc_poly_compose(poly, substitutions):
    poly = _nc_poly_clean(poly)
    target_dimension = len(next(iter(substitutions[0]))) if substitutions and substitutions[0] else len(next((iter(item) for item in substitutions if item), {(0,)}))
    result = _nc_poly_constant(target_dimension, 0)
    for monomial, coefficient in poly.items():
        term = _nc_poly_constant(target_dimension, coefficient)
        for index, exponent in enumerate(monomial):
            term = _nc_poly_multiply(term, _nc_poly_power(substitutions[index], exponent))
        result = _nc_poly_add(result, term)
    return _nc_poly_clean(result)


def _nc_poly_evaluate(poly, values):
    total = Fraction(0, 1)
    for monomial, coefficient in _nc_poly_clean(poly).items():
        term = coefficient
        for value, exponent in zip(values, monomial):
            term *= Fraction(value) ** exponent
        total += term
    return total


def _nc_poly_packet(poly):
    return tuple(sorted(_nc_poly_clean(poly).items()))


def _nc_monomials(dimension, maximum_degree):
    rows = []
    for exponents in itertools.product(range(maximum_degree + SHIFT), repeat=dimension):
        if sum(exponents) <= maximum_degree:
            rows.append(tuple(exponents))
    return tuple(sorted(rows, key=lambda row: (sum(row), row)))


def _nc_poly_vector(poly, universe):
    clean = _nc_poly_clean(poly)
    return tuple(clean.get(monomial, Fraction(0, 1)) for monomial in universe)


def _nc_poly_in_span(poly, basis, universe):
    rows = tuple(_nc_poly_vector(item, universe) for item in basis)
    candidate = _nc_poly_vector(poly, universe)
    return fraction_rank(rows + (candidate,)) == fraction_rank(rows)


def _nc_polynomial_native_model():
    u = _nc_poly_variable(ROUTE_TRIPLET, 0)
    v = _nc_poly_variable(ROUTE_TRIPLET, SHIFT)
