    native = (
        _nc_poly_add(u, h_squared),
        _nc_poly_add(v, _nc_poly_scale(-SHIFT, h_squared)),
        _nc_poly_add(h, _nc_poly_add(u, v)),
    )
    sum_readout = _nc_poly_add(u, v)
    difference_readout = _nc_poly_add(u, _nc_poly_scale(-SHIFT, v))
    projection = (sum_readout, h)
    effective_sum = _nc_poly_variable(DUAL, 0)
    effective_hidden = _nc_poly_variable(DUAL, SHIFT)
    effective = (effective_sum, _nc_poly_add(effective_hidden, effective_sum))
    return u, v, h, native, projection, effective, difference_readout


