# READER ORIENTATION: CONTINUOUS EFFECTIVE LAWS ARE LIE-CLOSED OBSERVABLE ALGEBRAS
# A polynomial projection is autonomous when every projected coordinate has a Lie
# derivative that factors through the same projection.  This is the continuous-time
# counterpart of exact fiber preservation and is checked as a polynomial identity.
def _gdc_poly_partial(poly, axis):
    result = {}
    for monomial, coefficient in _nc_poly_clean(poly).items():
        exponent = monomial[axis]
        if exponent == 0:
            continue
        reduced = list(monomial)
        reduced[axis] -= SHIFT
        key = tuple(reduced)
        result[key] = result.get(key, Fraction(0, 1)) + coefficient * exponent
    return _nc_poly_clean(result)


def _gdc_lie_derivative(poly, vector_field):
    dimension = len(vector_field)
    result = _nc_poly_constant(dimension, 0)
    for axis in range(dimension):
        result = _nc_poly_add(result, _nc_poly_multiply(_gdc_poly_partial(poly, axis), vector_field[axis]))
    return _nc_poly_clean(result)


def _gdc_polynomial_vector_field_model():
    u = _nc_poly_variable(ROUTE_TRIPLET, 0)
