        parent_action = common_stiffness * common_stationary * common_stationary / DUAL + common_stationary * source + sum(diagonal[index] * vector[index] * vector[index] / DUAL for index in range(len(names)))
        effective_action = _gdc_quadratic_form(schur, vector)
        parent_sector_gradient = tuple(diagonal[row] * vector[row] + couplings[row] * common_stationary for row in range(len(names)))
        effective_gradient = tuple(sum(schur[row][column] * vector[column] for column in range(len(names))) for row in range(len(names)))
