# READER ORIENTATION: A WHOLE POLYNOMIAL FLOW FAMILY CAN BE INTEGRATED EXACTLY
# The projected total is conserved, the hidden coordinate advances linearly, and an
# arbitrary rational polynomial transfer in the hidden coordinate is integrated by a
# finite binomial identity.  No exponential, logarithm, or trigonometric evaluation is
# required.
def _native_flow_polynomial_value(coefficients, value):
    value = Fraction(value)
    return sum((Fraction(coefficient) * value ** power for power, coefficient in enumerate(coefficients)), Fraction(0, 1))


def _native_flow_integrated_shift_polynomial(coefficients, hidden, total, time):
    hidden = Fraction(hidden)
    total = Fraction(total)
    time = Fraction(time)
    result = Fraction(0, 1)
    for power, coefficient in enumerate(coefficients):
        coefficient = Fraction(coefficient)
        for shift_power in range(power + SHIFT):
            result += (
                coefficient
                * math.comb(power, shift_power)
                * hidden ** (power - shift_power)
                * total ** shift_power
                * time ** (shift_power + SHIFT)
                / Fraction(shift_power + SHIFT, 1)
            )
    return result


def _native_flow_triangular_flow(state, time, coefficients):
    total, difference, hidden = tuple(Fraction(value) for value in state)
    transfer = _native_flow_integrated_shift_polynomial(coefficients, hidden, total, time)
    return (total, difference + transfer, hidden + Fraction(time) * total)


