def _u905_identity(dimension):
    return tuple(
        tuple(Fraction(1) if row == column else Fraction(0) for column in range(dimension))
        for row in range(dimension)
    )


def _u905_zero(rows, columns):
    return tuple(tuple(Fraction(0) for _ in range(columns)) for _ in range(rows))


def _u905_add(left, right):
    return tuple(
        tuple(left[row][column] + right[row][column] for column in range(len(left[0])))
        for row in range(len(left))
    )


def _u905_subtract(left, right):
    return tuple(
        tuple(left[row][column] - right[row][column] for column in range(len(left[0])))
        for row in range(len(left))
    )


def _u905_scale(coefficient, matrix):
    return tuple(tuple(coefficient * value for value in row) for row in matrix)


def _u905_multiply(left, right):
    return tuple(
        tuple(
            sum((left[row][inner] * right[inner][column] for inner in range(len(right))), Fraction(0))
            for column in range(len(right[0]))
        )
        for row in range(len(left))
    )


def _u905_transpose(matrix):
    return tuple(tuple(matrix[row][column] for row in range(len(matrix))) for column in range(len(matrix[0])))


def _u905_vector(matrix, vector):
    return tuple(
        sum((matrix[row][column] * vector[column] for column in range(len(vector))), Fraction(0))
        for row in range(len(matrix))
    )


def _u905_dot(left, right):
    return sum((first * second for first, second in zip(left, right)), Fraction(0))


def _u905_trace(matrix):
    return sum((matrix[index][index] for index in range(len(matrix))), Fraction(0))


def _u905_kronecker(left, right):
    return tuple(
        tuple(
            left[left_row][left_column] * right[right_row][right_column]
            for left_column in range(len(left[0]))
            for right_column in range(len(right[0]))
        )
        for left_row in range(len(left))
        for right_row in range(len(right))
    )


def _u905_determinant(matrix):
    dimension = len(matrix)
    if dimension == 1:
        return matrix[0][0]
    total = Fraction(0)
    for column in range(dimension):
        minor = tuple(
            tuple(matrix[row][inner] for inner in range(dimension) if inner != column)
            for row in range(1, dimension)
        )
        total += (Fraction(1) if column % 2 == 0 else Fraction(-1)) * matrix[0][column] * _u905_determinant(minor)
    return total


def _u905_polynomial_add(left, right):
    length = max(len(left), len(right))
    return tuple(
        (left[index] if index < len(left) else Fraction(0))
        + (right[index] if index < len(right) else Fraction(0))
        for index in range(length)
    )


def _u905_polynomial_scale(coefficient, polynomial):
    return tuple(coefficient * value for value in polynomial)


def _u905_polynomial_multiply(left, right):
    result = [Fraction(0) for _ in range(len(left) + len(right) - 1)]
    for left_degree, left_value in enumerate(left):
        for right_degree, right_value in enumerate(right):
            result[left_degree + right_degree] += left_value * right_value
    return tuple(result)


def _u905_polynomial_shift(polynomial):
    result = (Fraction(0),)
    base = (Fraction(1), Fraction(1))
    power = (Fraction(1),)
    for coefficient in polynomial:
        result = _u905_polynomial_add(result, _u905_polynomial_scale(coefficient, power))
        power = _u905_polynomial_multiply(power, base)
    while len(result) > 1 and result[-1] == 0:
        result = result[:-1]
    return result


