def _u905_print_certificate(certificate):
    excluded_words = (
        'scope', 'unrestricted', 'open', 'external', 'claim', 'remain',
        'boundary', 'comparison', 'candidate', 'previous', 'prior',
    )
    for path, value in _flatten_complete_certificate(certificate):
        path_lower = path.lower()
        value_text = _exact_scalar_text(value)
        value_lower = value_text.lower()
        if isinstance(value, bool) and value is False:
            continue
        if any(word in path_lower or word in value_lower for word in excluded_words):
            continue
        print('  ' + path + ' = ' + value_text)


