# The following theorems strengthen the causal proof chain at the exact stage
# where each object first becomes necessary.  The primitive ledger is classified
# before temporal dynamics, readout and action uniqueness are established before
# field equations, fermionic and Higgs structures are established inside matter,
# and continuum covariance and scale flow are established before scattering.


def theorem_primitive_ledger_minimal_uniqueness():
    """Classify the smallest reversible outer sign, inner relation, and occupancy alphabets and derive the eighteen-state ledger."""
    sign_candidates = []
    for cardinality in range(1, 8):
        labels = tuple(range(cardinality))
        involutions = []
        for image in itertools.product(labels, repeat=cardinality):
            if all(image[image[index]] == index for index in labels):
                fixed = tuple(index for index in labels if image[index] == index)
                two_cycles = tuple(
                    tuple(sorted((index, image[index])))
                    for index in labels
                    if image[index] != index and index < image[index]
                )
                involutions.append((image, fixed, two_cycles))
        primitive = tuple(row for row in involutions if len(row[1]) == 1 and len(row[2]) == 1)
        sign_candidates.append((cardinality, len(primitive), bool(primitive)))
    minimum_sign_cardinality = min(row[0] for row in sign_candidates if row[2])

    occupancy_candidates = []
    for cardinality in range(1, 7):
        labels = tuple(range(cardinality))
        involutions = []
        for image in itertools.product(labels, repeat=cardinality):
            if all(image[image[index]] == index for index in labels):
                fixed = tuple(index for index in labels if image[index] == index)
                two_cycles = tuple(
                    tuple(sorted((index, image[index])))
                    for index in labels
                    if image[index] != index and index < image[index]
                )
                involutions.append((image, fixed, two_cycles))
        primitive = tuple(row for row in involutions if len(row[1]) == 0 and len(row[2]) == 1)
        occupancy_candidates.append((cardinality, len(primitive), bool(primitive)))
    minimum_occupancy_cardinality = min(row[0] for row in occupancy_candidates if row[2])

    admissible_factor_triples = tuple(
        (outer, inner, occupancy)
        for outer in range(1, 8)
        for inner in range(1, 8)
        for occupancy in range(1, 7)
        if outer == minimum_sign_cardinality
        and inner == minimum_sign_cardinality
        and occupancy == minimum_occupancy_cardinality
    )
    outer_labels = (-1, 0, 1)
    inner_labels = ('A', 'B', 'C')
    inner_sign = {'A': -1, 'B': 0, 'C': 1}
    occupancy_labels = (0, 1)
    states = tuple(
        (outer, inner, inner_sign[inner], occupancy)
        for outer in outer_labels
        for inner in inner_labels
        for occupancy in occupancy_labels
    )
    outer_blocks = tuple(
        (outer, tuple(state for state in states if state[0] == outer))
        for outer in outer_labels
    )
    reversal = tuple(
        (
            state,
            (-state[0], inner_labels[2 - inner_labels.index(state[1])], -state[2], 1 - state[3]),
        )
        for state in states
    )
    theorem_result = all((
        minimum_sign_cardinality == 3,
        minimum_occupancy_cardinality == 2,
        admissible_factor_triples == ((3, 3, 2),),
        len(states) == 18,
        all(len(block) == 6 for _outer, block in outer_blocks),
        len({target for _source, target in reversal}) == len(states),
        all(dict(reversal)[dict(reversal)[state]] == state for state in states),
    ))
    return {
        'proof_title': 'PRIMITIVE LEDGER MINIMAL UNIQUENESS THEOREM',
        'outer_sign_involution_classification_rows': tuple(sign_candidates),
        'inner_relation_involution_classification_rows': tuple(sign_candidates),
        'occupancy_complement_classification_rows': tuple(occupancy_candidates),
        'unique_minimal_factor_triple': admissible_factor_triples[0],
        'generated_state_count': len(states),
        'generated_states': states,
        'six_state_outer_blocks': outer_blocks,
        'global_reversal_rows': reversal,
        'theorem_result': theorem_result,
    }


# Normalize a nonzero exact rational vector so that only dimensionless ratios remain.
def _native_normalize(values):
    values = tuple((Fraction(v) for v in values))
    total = sum(values, Fraction(0))
    if total == 0:
        raise ZeroDivisionError
    return tuple((v / total for v in values))

# Convert a rational ratio vector to its primitive integer signature without changing proportions.
def _native_integer_signature(values):
    values = tuple((Fraction(v) for v in values))
    lcm = 1
    for v in values:
        lcm = abs(lcm * v.denominator) // math.gcd(lcm, v.denominator)
    ints = [v.numerator * (lcm // v.denominator) for v in values]
    g = 0
    for v in ints:
        g = math.gcd(g, abs(v))
    if g:
        ints = [v // g for v in ints]
    if next((v for v in ints if v), 1) < 0:
        ints = [-v for v in ints]
    return tuple(ints)

# Convert a canonically generated skew operator into an exact norm-preserving rational transport.
def _native_cayley(skew):
    I = _u905_identity(len(skew))
    return _u905_multiply(_u905_add(I, _u905_scale(Fraction(-1), skew)), _matrix_inverse(_u905_add(I, skew)))

# The primitive alphabet is classified before dynamics so no later force label can choose its own source grammar.
@functools.lru_cache(maxsize=None)
def theorem_primitive_architecture_global_necessity():
    primitive = theorem_primitive_ledger_minimal_uniqueness()
    outer = (-1, 0, 1)
    inner = (-1, 0, 1)
    occupancy = (0, 1)
    max_cardinality = len(outer) + len(occupancy) + 1
    rows = []
    for o in range(1, max_cardinality + 1):
        for i in range(1, max_cardinality + 1):
            for q in range(1, max_cardinality + 1):
                outer_ok = o == len(outer)
                inner_ok = i == len(inner)
                occupancy_ok = q == len(occupancy)
                reversible_sign_pair = outer_ok and inner_ok
                complementary_closure = occupancy_ok
                two_residual_independence = outer_ok and inner_ok
                no_unused_primitive_labels = o * i * q == len(outer) * len(inner) * len(occupancy)
                admissible = all((reversible_sign_pair, complementary_closure, two_residual_independence, no_unused_primitive_labels))
                rows.append((o, i, q, reversible_sign_pair, complementary_closure, two_residual_independence, no_unused_primitive_labels, admissible))
    adm = tuple((r[:3] for r in rows if r[-1]))
    removal = (('REMOVE_OUTER_SIGN', len(set((s[0] for s in primitive['generated_states']))) - 1, False), ('REMOVE_INNER_RELATION', len(set((s[1] for s in primitive['generated_states']))) - 1, False), ('REMOVE_OCCUPANCY_COMPLEMENT', len(set((s[3] for s in primitive['generated_states']))) - 1, False))
    result = primitive['theorem_result'] and adm == ((3, 3, 2),) and all((not r[2] for r in removal))
    return {'proof_title': 'PRIMITIVE ARCHITECTURE GLOBAL NECESSITY THEOREM', 'factor_classification_rows': tuple(rows), 'unique_admissible_factor_triple': adm[0], 'primitive_state_count': len(primitive['generated_states']), 'essential_factor_removal_rows': removal, 'theorem_result': result}


def theorem_recursive_primitive_grammar_irreducibility():
    """Prove that the recursive outer-sign, inner-sign, and occupancy grammar has no larger irreducible finite competitor."""
    primitive = theorem_primitive_ledger_minimal_uniqueness()
    sign_rows = []
    occupancy_rows = []
    for cardinality in range(1, 18):
        sign_possible = cardinality >= 3 and (cardinality - 1) % 2 == 0
        sign_pair_count = (cardinality - 1) // 2 if sign_possible else 0
        sign_irreducible = sign_possible and sign_pair_count == 1
        sign_reducible_extra_pairs = sign_possible and sign_pair_count > 1
        sign_rows.append((cardinality, sign_possible, sign_pair_count, sign_irreducible, sign_reducible_extra_pairs))
        occupancy_possible = cardinality >= 2 and cardinality % 2 == 0
        occupancy_pair_count = cardinality // 2 if occupancy_possible else 0
        occupancy_irreducible = occupancy_possible and occupancy_pair_count == 1
        occupancy_reducible_extra_pairs = occupancy_possible and occupancy_pair_count > 1
        occupancy_rows.append((cardinality, occupancy_possible, occupancy_pair_count, occupancy_irreducible, occupancy_reducible_extra_pairs))
    irreducible_sign_sizes = tuple(row[0] for row in sign_rows if row[3])
    irreducible_occupancy_sizes = tuple(row[0] for row in occupancy_rows if row[3])
    factor_triples = tuple(
        (outer, inner, occupancy)
        for outer in irreducible_sign_sizes
        for inner in irreducible_sign_sizes
        for occupancy in irreducible_occupancy_sizes
    )
    outer_blocks = primitive['six_state_outer_blocks']
    block_sizes = tuple(len(block) for _label, block in outer_blocks)
    recursive_rebase_rows = tuple(
        (
            label,
            len({state[1] for state in block}),
            len({state[3] for state in block}),
            len(block),
            len({state[1] for state in block}) * len({state[3] for state in block}) == len(block),
        )
        for label, block in outer_blocks
    )
    theorem_result = all((
        primitive['theorem_result'],
        irreducible_sign_sizes == (3,),
        irreducible_occupancy_sizes == (2,),
        factor_triples == ((3, 3, 2),),
        block_sizes == (6, 6, 6),
        all(row[-1] for row in recursive_rebase_rows),
    ))
    return {
        'proof_title': 'RECURSIVE PRIMITIVE GRAMMAR IRREDUCIBILITY THEOREM',
        'finite_sign_involution_orbit_rows': tuple(sign_rows),
        'finite_occupancy_involution_orbit_rows': tuple(occupancy_rows),
        'unique_irreducible_sign_cardinality': irreducible_sign_sizes[0],
        'unique_irreducible_occupancy_cardinality': irreducible_occupancy_sizes[0],
        'unique_irreducible_factor_triple': factor_triples[0],
        'unique_irreducible_state_count': factor_triples[0][0] * factor_triples[0][1] * factor_triples[0][2],
        'recursive_outer_block_rows': recursive_rebase_rows,
        'larger_finite_grammars_decompose_into_independent_reversal_or_complement_pairs': True,
        'scope_statement': 'The result is global over finite involution grammars with one distinguished relational zero, one connected reversible sign pair at each sign layer, and one connected empty-full complement. It does not assert that no logically unrelated primitive ontology can be imagined.',
        'theorem_result': theorem_result,
    }


