# CANONICAL PARENT-SHADOW DECOMPOSITION AND REFINEMENT
# ============================================================================
# The primitive source is one product grammar, not a collection of competing
# force hypotheses.  The unique uniform conditional expectations of the three
# primitive factors decompose its complete function space by interaction order.
# This produces all shadow components simultaneously.  Physical names are
# attached only after the anonymous invariant blocks have been generated.


def _ps_identity(size):
    return tuple(tuple(Fraction(int(row == column)) for column in range(size)) for row in range(size))


def _ps_constant_projector(size):
    return tuple(tuple(Fraction(1, size) for _column in range(size)) for _row in range(size))


def _ps_matrix_add(*matrices):
    if not matrices:
        return tuple()
    rows = len(matrices[0])
    columns = len(matrices[0][0])
    return tuple(tuple(sum((matrix[row][column] for matrix in matrices), Fraction(0)) for column in range(columns)) for row in range(rows))


def _ps_matrix_subtract(left, right):
    return tuple(tuple(left[row][column] - right[row][column] for column in range(len(left[0]))) for row in range(len(left)))


def _ps_matrix_scale(scalar, matrix):
    scalar = Fraction(scalar)
    return tuple(tuple(scalar * value for value in row) for row in matrix)


def _ps_matrix_multiply(left, right):
    transpose = tuple(zip(*right))
    return tuple(tuple(sum((a * b for a, b in zip(row, column)), Fraction(0)) for column in transpose) for row in left)


def _ps_matrix_transpose(matrix):
    return tuple(tuple(row) for row in zip(*matrix))


def _ps_kronecker(left, right):
    return tuple(
        tuple(left_row_value * right_row[right_column] for left_column, left_row_value in enumerate(left_row) for right_column in range(len(right_row)))
        for left_row in left
        for right_row in right
    )


def _ps_vector_dot(left, right):
    return sum((a * b for a, b in zip(left, right)), Fraction(0))


def _ps_outer(left, right):
    return tuple(tuple(a * b for b in right) for a in left)


def _ps_projector(vector):
    norm = _ps_vector_dot(vector, vector)
    if norm == 0:
        raise ValueError('zero projector vector')
    return _ps_matrix_scale(Fraction(1, 1) / norm, _ps_outer(vector, vector))


def _ps_is_zero(matrix):
    return all(value == 0 for row in matrix for value in row)


def _ps_projector_exact(projector):
    return _ps_matrix_multiply(projector, projector) == projector and projector == _ps_matrix_transpose(projector)


def _ps_state_index(outer, inner, occupancy):
    return (outer * 3 + inner) * 2 + occupancy


def _ps_diagonal_relation_permutation_matrix(permutation, flip_occupancy=False):
    size = 18
    matrix = [[Fraction(0) for _column in range(size)] for _row in range(size)]
    for outer in range(3):
        for inner in range(3):
            for occupancy in range(2):
                source = _ps_state_index(outer, inner, occupancy)
                target = _ps_state_index(permutation[outer], permutation[inner], 1 - occupancy if flip_occupancy else occupancy)
                matrix[target][source] = Fraction(1)
    return tuple(tuple(row) for row in matrix)


@functools.lru_cache(maxsize=None)
def theorem_parent_shadow_canonical_decomposition():
    """Derive the anonymous ranks five, eight, one and three from the unique interaction-order decomposition of the three-by-three-by-two grammar."""
    factor_sizes = (3, 3, 2)
    constants = tuple(_ps_constant_projector(size) for size in factor_sizes)
    centered = tuple(_ps_matrix_subtract(_ps_identity(size), constants[index]) for index, size in enumerate(factor_sizes))
    c_outer, c_inner, c_occupancy = constants
    q_outer, q_inner, q_occupancy = centered

    constant = _ps_kronecker(_ps_kronecker(c_outer, c_inner), c_occupancy)
    main = _ps_matrix_add(
        _ps_kronecker(_ps_kronecker(q_outer, c_inner), c_occupancy),
        _ps_kronecker(_ps_kronecker(c_outer, q_inner), c_occupancy),
        _ps_kronecker(_ps_kronecker(c_outer, c_inner), q_occupancy),
    )
    pair = _ps_matrix_add(
        _ps_kronecker(_ps_kronecker(q_outer, q_inner), c_occupancy),
        _ps_kronecker(_ps_kronecker(q_outer, c_inner), q_occupancy),
        _ps_kronecker(_ps_kronecker(c_outer, q_inner), q_occupancy),
    )
    triple = _ps_kronecker(_ps_kronecker(q_outer, q_inner), q_occupancy)

    centered_basis = ((Fraction(1), Fraction(-1), Fraction(0)), (Fraction(1), Fraction(1), Fraction(-2)))
    occupancy_sign = (Fraction(1), Fraction(-1))
    scalar_vector = []
    for outer in range(3):
        for inner in range(3):
            kernel = sum(
                (basis[outer] * basis[inner] / _ps_vector_dot(basis, basis) for basis in centered_basis),
                Fraction(0),
            )
            for occupancy in range(2):
                scalar_vector.append(kernel * occupancy_sign[occupancy])
    scalar_vector = tuple(scalar_vector)
    triple_scalar = _ps_projector(scalar_vector)
    triple_traceless = _ps_matrix_subtract(triple, triple_scalar)

    projectors = (constant, main, pair, triple_scalar, triple_traceless)
    identity = _ps_identity(18)
    pairwise_rows = tuple(
        (left, right, _ps_is_zero(_ps_matrix_multiply(projectors[left], projectors[right])))
        for left in range(len(projectors))
        for right in range(len(projectors))
        if left != right
    )
    ranks = tuple(fraction_rank(projector) for projector in projectors)
    expected_ranks = (
        1,
        (factor_sizes[0] - 1) + (factor_sizes[1] - 1) + (factor_sizes[2] - 1),
        (factor_sizes[0] - 1) * (factor_sizes[1] - 1)
        + (factor_sizes[0] - 1) * (factor_sizes[2] - 1)
        + (factor_sizes[1] - 1) * (factor_sizes[2] - 1),
        1,
        (factor_sizes[0] - 1) * (factor_sizes[1] - 1) * (factor_sizes[2] - 1) - 1,
    )

    diagonal_group = tuple(_ps_diagonal_relation_permutation_matrix(permutation, False) for permutation in itertools.permutations(range(3)))
    group_average = _ps_matrix_scale(Fraction(1, len(diagonal_group)), _ps_matrix_add(*diagonal_group))
    triple_invariant = _ps_matrix_multiply(_ps_matrix_multiply(triple, group_average), triple)
    symmetry_rows = []
    for permutation in itertools.permutations(range(3)):
        for flip in (False, True):
            action = _ps_diagonal_relation_permutation_matrix(permutation, flip)
            inverse = _ps_matrix_transpose(action)
            symmetry_rows.append((
                permutation,
                flip,
                tuple(_ps_matrix_multiply(_ps_matrix_multiply(action, projector), inverse) == projector for projector in projectors),
            ))

    theorem_result = all((
        all(_ps_projector_exact(projector) for projector in projectors),
        all(row[-1] for row in pairwise_rows),
        _ps_matrix_add(*projectors) == identity,
        ranks == expected_ranks,
        triple_invariant == triple_scalar,
        fraction_rank(triple_invariant) == 1,
        all(all(row[2]) for row in symmetry_rows),
    ))
    return {
        'proof_title': 'PARENT SHADOW CANONICAL DECOMPOSITION THEOREM',
        'reader_principle': 'The source does not choose one force path.  One complete product grammar is decomposed simultaneously by its unique uniform conditional expectations.  Main effects, pair interactions and the scalar plus traceless parts of the full triple interaction are the canonical anonymous shadows.',
        'primitive_factor_sizes': factor_sizes,
        'primitive_state_count': 18,
        'constant_projector': constant,
        'main_effect_projector': main,
        'pair_interaction_projector': pair,
        'triple_scalar_projector': triple_scalar,
        'triple_traceless_projector': triple_traceless,
        'canonical_projector_ranks': ranks,
        'canonical_nonconstant_shadow_ranks': (ranks[1], ranks[3], ranks[4], ranks[2]),
        'derived_rank_formula': expected_ranks,
        'pairwise_orthogonality_rows': pairwise_rows,
        'diagonal_relation_and_occupancy_symmetry_rows': tuple(symmetry_rows),
        'unique_diagonal_relation_invariant_line_in_triple_block': fraction_rank(triple_invariant) == 1 and triple_invariant == triple_scalar,
        'force_names_used_in_decomposition': False,
        'measured_values_used_in_decomposition': False,
        'nature_path_selection_required': False,
        'all_shadow_components_generated_simultaneously': True,
        'theorem_result': theorem_result,
    }


