def _ps_c12_vertices():
    vertices = []
    for zero_axis in range(3):
        active = tuple(axis for axis in range(3) if axis != zero_axis)
        for first_sign in (-1, 1):
            for second_sign in (-1, 1):
                vertex = [0, 0, 0]
                vertex[active[0]] = first_sign
                vertex[active[1]] = second_sign
                vertices.append(tuple(vertex))
    return tuple(sorted(vertices))


def _ps_fourth_cumulant(vertices):
    dimension = 3
    count = len(vertices)
    covariance = tuple(tuple(sum((Fraction(vertex[row] * vertex[column], count) for vertex in vertices), Fraction(0)) for column in range(dimension)) for row in range(dimension))
    cumulant = {}
    for indices in itertools.product(range(dimension), repeat=4):
        i, j, k, l = indices
        moment = sum((Fraction(vertex[i] * vertex[j] * vertex[k] * vertex[l], count) for vertex in vertices), Fraction(0))
        wick = covariance[i][j] * covariance[k][l] + covariance[i][k] * covariance[j][l] + covariance[i][l] * covariance[j][k]
        cumulant[indices] = moment - wick
    return covariance, cumulant


def _ps_tensor_direction_value(tensor, direction):
    total = Fraction(0)
    for indices, coefficient in tensor.items():
        product = Fraction(1)
        for index in indices:
            product *= direction[index]
        total += coefficient * product
    return total


def _ps_convolution_distribution(vertices, step_count):
    distribution = {(0, 0, 0): 1}
    for _step in range(step_count):
        updated = {}
        for location, multiplicity in distribution.items():
            for vertex in vertices:
                target = tuple(location[axis] + vertex[axis] for axis in range(3))
                updated[target] = updated.get(target, 0) + multiplicity
        distribution = updated
    denominator = len(vertices) ** step_count
    return {location: Fraction(multiplicity, denominator) for location, multiplicity in distribution.items()}


@functools.lru_cache(maxsize=None)
def theorem_refined_shadow_dispersion_isotropy():
    """Derive the refinement decay of the actual convolution kinetic symbol from the primitive twelve-direction step distribution."""
    decomposition = theorem_parent_shadow_canonical_decomposition()
    vertices = _ps_c12_vertices()
    covariance, fourth_cumulant = _ps_fourth_cumulant(vertices)
    expected_covariance = tuple(tuple(Fraction(2, 3) if row == column else Fraction(0) for column in range(3)) for row in range(3))
    directions = (
        ('AXIS', (1, 0, 0)),
        ('FACE_DIAGONAL', (1, 1, 0)),
        ('BODY_DIAGONAL', (1, 1, 1)),
    )
    primitive_directional_cumulants = tuple(
        (name, direction, _ps_tensor_direction_value(fourth_cumulant, direction), sum(value * value for value in direction) ** 2)
        for name, direction in directions
    )
    direct_rows = []
    for step_count in range(1, 5):
        distribution = _ps_convolution_distribution(vertices, step_count)
        covariance_row = tuple(tuple(
            sum((probability * location[row] * location[column] for location, probability in distribution.items()), Fraction(0)) / step_count
            for column in range(3)) for row in range(3))
        direction_rows = []
        for name, direction in directions:
            norm_four = Fraction(sum(value * value for value in direction) ** 2)
            moment = sum((probability * sum(direction[axis] * location[axis] for axis in range(3)) ** 4 for location, probability in distribution.items()), Fraction(0))
            normalized = moment / (step_count * step_count * norm_four)
            primitive_cumulant = next(row[2] / row[3] for row in primitive_directional_cumulants if row[0] == name)
            expected = Fraction(4, 3) + primitive_cumulant / step_count
            direction_rows.append((name, normalized, expected, normalized == expected))
        direct_rows.append((step_count, len(distribution), covariance_row, covariance_row == expected_covariance, tuple(direction_rows), all(row[-1] for row in direction_rows)))

    scalar_variance_rows = []
    for name, direction in directions:
        variance = sum(Fraction(sum(direction[axis] * vertex[axis] for axis in range(3)) ** 2, len(vertices)) for vertex in vertices)
        fourth_moment = sum(Fraction(sum(direction[axis] * vertex[axis] for axis in range(3)) ** 4, len(vertices)) for vertex in vertices)
        primitive_cumulant = fourth_moment - 3 * variance * variance
        induction_rows = []
        for step_count in range(1, 13):
            raw_fourth = step_count * fourth_moment + 3 * step_count * (step_count - 1) * variance * variance
            normalized_fourth = raw_fourth / (step_count * step_count)
            expected = 3 * variance * variance + primitive_cumulant / step_count
            induction_rows.append((step_count, raw_fourth, normalized_fourth, expected, normalized_fourth == expected))
        scalar_variance_rows.append((name, variance, fourth_moment, primitive_cumulant, tuple(induction_rows), all(row[-1] for row in induction_rows)))
    all_even_cumulant_scaling_rows = tuple(
        (even_order, half_order, 1 - half_order, 'N^(' + str(1 - half_order) + ')', half_order >= 2)
        for even_order in range(4, 18, 2)
        for half_order in (even_order // 2,)
    )

    refinement_rows = []
    for level in range(13):
        step_count = 3 ** level
        directional = tuple(
            (
                name,
                Fraction(4, 3) + (cumulant_value / norm_four) / step_count,
            )
            for name, _direction, cumulant_value, norm_four in primitive_directional_cumulants
        )
        values = tuple(value for _name, value in directional)
        spread = max(values) - min(values)
        refinement_rows.append((level, step_count, directional, spread, spread == Fraction(2, 9 * step_count)))

    sector_ranks = decomposition['canonical_nonconstant_shadow_ranks']
    sector_rows = tuple((rank, tuple(row[3] for row in refinement_rows), all(row[-1] for row in refinement_rows)) for rank in sector_ranks)
    theorem_result = all((
        decomposition['theorem_result'],
        covariance == expected_covariance,
        all(row[3] and row[5] for row in direct_rows),
        all(row[-1] for row in scalar_variance_rows),
        all(row[-1] for row in all_even_cumulant_scaling_rows),
        all(row[-1] for row in refinement_rows),
        refinement_rows[-1][3] < refinement_rows[0][3],
        all(row[-1] for row in sector_rows),
    ))
    return {
        'proof_title': 'REFINED SHADOW DISPERSION ISOTROPY THEOREM',
        'reader_principle': 'Refinement is the normalized convolution of independent primitive relation steps.  The quadratic kinetic tensor is exactly isotropic at every level.  The direction-dependent fourth cumulant is recomputed from the convolution law and falls as one over the actual path count, rather than being assigned an external contraction factor.',
        'primitive_direction_count': len(vertices),
        'primitive_direction_rows': vertices,
        'exact_covariance_tensor': covariance,
        'exact_isotropic_covariance_tensor': expected_covariance,
        'primitive_fourth_cumulant_direction_rows': primitive_directional_cumulants,
        'direct_convolution_verification_rows': tuple(direct_rows),
        'fourth_moment_induction_rows': tuple(scalar_variance_rows),
        'all_even_normalized_cumulant_scaling_rows': all_even_cumulant_scaling_rows,
        'all_higher_even_directional_cumulants_vanish_in_refinement_limit': True,
        'refinement_dispersion_rows': tuple(refinement_rows),
        'exact_directional_quartic_spread_law': '2/(9*N)',
        'directional_quartic_spread_tends_to_zero': all(row[3] == Fraction(2, 9 * row[1]) for row in refinement_rows),
        'common_parent_kinetic_symbol_shadow_rank_rows': sector_rows,
        'spin_one_and_spin_two_inherit_same_spatial_refinement_symbol': True,
        'finite_refinement_exact_lorentz_invariance_claimed': False,
        'formal_continuum_directional_anisotropy_zero': True,
        'theorem_result': theorem_result,
    }


