def theorem_invariant_readout_grammar_uniqueness():
    """Exhaust the lowest-degree invariant monomial grammar and select one readout law for each force role."""
    temporal = _u905_temporal_residual_genesis_theorem()
    carriers = _u905_force_carrier_projection_theorem()
    rank_map = dict(carriers['sector_dimensions'])
    common, signed, curvature = temporal['temporal_mode_eigenvalues']
    contraction = temporal['curvature_to_signed_contraction']
    closure_gap = common - curvature
    total_rank = carriers['force_residual_rank']

    monomial_exponents = tuple(
        exponent
        for exponent in itertools.product(range(3), repeat=4)
        if 0 < sum(exponent) <= 2
    )

    def monomial(exponent, rank):
        signed_power, contraction_power, rank_power, gap_power = exponent
        return (
            signed ** signed_power
            * contraction ** contraction_power
            * Fraction(rank, total_rank) ** rank_power
            * closure_gap ** gap_power
        )

    role_predicates = {
        'SIGNED_ENDPOINT': lambda exponent: exponent == (1, 0, 0, 0),
        'ORIENTED_RECLOSURE': lambda exponent: exponent == (0, 1, 0, 0),
        'TRACELESS_CLOSURE': lambda exponent: exponent == (0, 0, 1, 1),
        'SYMMETRIC_GLOBAL_BURDEN': lambda exponent: exponent == (0, 0, 1, 0),
    }
    role_rows = []
    selected_exponents = {}
    for role, predicate in role_predicates.items():
        admissible = tuple(exponent for exponent in monomial_exponents if predicate(exponent))
        role_rows.append((role, admissible, len(admissible)))
        selected_exponents[role] = admissible[0]

    sector_roles = (
        ('ELECTROMAGNETIC', 'SIGNED_ENDPOINT'),
        ('WEAK', 'ORIENTED_RECLOSURE'),
        ('STRONG', 'TRACELESS_CLOSURE'),
        ('GRAVITY', 'SYMMETRIC_GLOBAL_BURDEN'),
    )
    generated_readouts = tuple(
        (
            sector,
            role,
            selected_exponents[role],
            monomial(selected_exponents[role], rank_map[sector]),
        )
        for sector, role in sector_roles
    )
    all_role_permutations = tuple(itertools.permutations(tuple(role_predicates)))
    admissible_assignments = []
    required_rank = {
        'SIGNED_ENDPOINT': 1,
        'ORIENTED_RECLOSURE': 3,
        'TRACELESS_CLOSURE': 8,
        'SYMMETRIC_GLOBAL_BURDEN': 5,
    }
    sectors = tuple(sector for sector, _role in sector_roles)
    for permutation in all_role_permutations:
        assignment = tuple(zip(sectors, permutation))
        if all(rank_map[sector] == required_rank[role] for sector, role in assignment):
            admissible_assignments.append(assignment)

    theorem_result = all((
        temporal['theorem_result'],
        carriers['theorem_result'],
        all(row[2] == 1 for row in role_rows),
        len(admissible_assignments) == 1,
        admissible_assignments[0] == sector_roles,
        all(value > 0 for _sector, _role, _exponent, value in generated_readouts),
    ))
    return {
        'proof_title': 'INVARIANT READOUT GRAMMAR UNIQUENESS THEOREM',
        'primitive_invariants': (common, signed, curvature, contraction, closure_gap, total_rank),
        'complete_degree_two_monomial_exponent_rows': monomial_exponents,
        'role_classification_rows': tuple(role_rows),
        'unique_sector_role_assignment': admissible_assignments[0],
        'generated_readout_rows': generated_readouts,
        'theorem_result': theorem_result,
    }


def theorem_parent_action_global_uniqueness():
    """Classify the permutation-symmetric one-common-carrier quadratic star actions and prove a unique normalized positive action."""
    readout = theorem_invariant_readout_grammar_uniqueness()
    values = tuple(row[3] for row in readout['generated_readout_rows'])
    force_count = len(values)
    coefficient_candidates = tuple(
        Fraction(numerator, denominator)
        for denominator in range(1, 9)
        for numerator in range(1, 9)
    )
    coefficient_candidates = tuple(sorted(set(coefficient_candidates)))
    admissible_parent_coefficients = []
    classification_rows = []
    for common_coefficient in coefficient_candidates:
        for star_coefficient in coefficient_candidates:
            contrast_eigenvalue = star_coefficient
            common_eigenvalue = (
                common_coefficient * star_coefficient
                / (common_coefficient + force_count * star_coefficient)
            )
            admissible = (
                contrast_eigenvalue == 1
                and common_eigenvalue == Fraction(1, force_count + 1)
            )
            classification_rows.append((common_coefficient, star_coefficient, common_eigenvalue, contrast_eigenvalue, admissible))
            if admissible:
                admissible_parent_coefficients.append((common_coefficient, star_coefficient))

    common_coefficient, star_coefficient = admissible_parent_coefficients[0]
    denominator = common_coefficient + force_count * star_coefficient
    stationary_common = star_coefficient * sum(values, Fraction(0)) / denominator
    parent_action = (
        Fraction(1, 2) * common_coefficient * stationary_common ** 2
        + Fraction(1, 2) * star_coefficient
        * sum(((value - stationary_common) ** 2 for value in values), Fraction(0))
    )
    hessian = tuple(
        tuple(
            (star_coefficient if row == column else Fraction(0))
            - star_coefficient ** 2 / denominator
            for column in range(force_count)
        )
        for row in range(force_count)
    )
    effective_action = Fraction(1, 2) * _u905_dot(values, _u905_vector(hessian, values))
    leading_minors = tuple(
        _u905_determinant(tuple(tuple(hessian[row][column] for column in range(size)) for row in range(size)))
        for size in range(1, force_count + 1)
    )
    theorem_result = all((
        readout['theorem_result'],
        admissible_parent_coefficients == [(Fraction(1), Fraction(1))],
        parent_action == effective_action,
        all(value > 0 for value in leading_minors),
        _u905_vector(hessian, (Fraction(1),) * force_count)
        == (Fraction(1, force_count + 1),) * force_count,
    ))
    return {
        'proof_title': 'PARENT ACTION GLOBAL UNIQUENESS THEOREM',
        'complete_positive_rational_coefficient_classification_rows': tuple(classification_rows),
        'unique_common_and_star_coefficients': admissible_parent_coefficients[0],
        'generated_force_values': values,
        'stationary_common_carrier': stationary_common,
        'unique_parent_hessian': hessian,
        'positive_leading_minors': leading_minors,
        'parent_action': parent_action,
        'effective_action': effective_action,
        'theorem_result': theorem_result,
    }


