def theorem_lorentz_refinement_isotropy():
    """Prove exact second-moment spatial isotropy, rational Lorentz covariance, and refinement-exact quadratic kinetic operators."""
    vertices = set()
    for zero_axis in range(3):
        active = tuple(axis for axis in range(3) if axis != zero_axis)
        for first_sign in (-1, 1):
            for second_sign in (-1, 1):
                vertex = [0, 0, 0]
                vertex[active[0]] = first_sign
                vertex[active[1]] = second_sign
                vertices.add(tuple(vertex))
    vertices = tuple(sorted(vertices))
    first_moment = tuple(sum(Fraction(vertex[axis]) for vertex in vertices) for axis in range(3))
    second_moment = tuple(
        tuple(sum(Fraction(vertex[row] * vertex[column]) for vertex in vertices) for column in range(3))
        for row in range(3)
    )
    normalized_second_moment = _u905_scale(Fraction(1, 8), second_moment)

    eta = (
        (Fraction(1), Fraction(0), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(-1), Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(-1), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(0), Fraction(-1)),
    )

    def boost(parameter):
        denominator = 1 - parameter * parameter
        gamma = (1 + parameter * parameter) / denominator
        velocity_component = 2 * parameter / denominator
        return (
            (gamma, -velocity_component, Fraction(0), Fraction(0)),
            (-velocity_component, gamma, Fraction(0), Fraction(0)),
            (Fraction(0), Fraction(0), Fraction(1), Fraction(0)),
            (Fraction(0), Fraction(0), Fraction(0), Fraction(1)),
        )

    parameters = tuple(sorted({Fraction(numerator, denominator) for denominator in range(2, 10) for numerator in range(1, denominator)}))
    boost_rows = tuple(
        (
            parameter,
            boost(parameter),
            _u905_multiply(_u905_multiply(_u905_transpose(boost(parameter)), eta), boost(parameter)) == eta,
            _u905_determinant(boost(parameter)) == 1,
        )
        for parameter in parameters
    )
    composition_rows = []
    for first in parameters[:8]:
        for second in parameters[:8]:
            composed_parameter = (first + second) / (1 + first * second)
            if composed_parameter < 1:
                composition_rows.append((first, second, composed_parameter, _u905_multiply(boost(first), boost(second)) == boost(composed_parameter)))

    def polynomial_value(coefficients, point):
        return sum((coefficient * point ** degree for degree, coefficient in enumerate(coefficients)), Fraction(0))

    kinetic_rows = []
    coefficient_family = tuple(itertools.product(range(-2, 3), repeat=3))
    for refinement in range(1, 19):
        step = Fraction(1, refinement)
        for coefficients in coefficient_family:
            coefficients = tuple(Fraction(value) for value in coefficients)
            for point in (Fraction(-2), Fraction(-1), Fraction(0), Fraction(1), Fraction(2)):
                second_difference = (
                    polynomial_value(coefficients, point + step)
                    - 2 * polynomial_value(coefficients, point)
                    + polynomial_value(coefficients, point - step)
                ) / (step * step)
                exact_second_derivative = 2 * coefficients[2]
                kinetic_rows.append((refinement, coefficients, point, second_difference, exact_second_derivative, second_difference == exact_second_derivative))

    refinement_isotropy_rows = tuple(
        (
            refinement,
            tuple(
                tuple(
                    sum(Fraction(vertex[row] * vertex[column], refinement * refinement) for vertex in vertices)
                    for column in range(3)
                )
                for row in range(3)
            ),
        )
        for refinement in range(1, 19)
    )
    theorem_result = all((
        len(vertices) == 12,
        first_moment == (0, 0, 0),
        normalized_second_moment == _u905_identity(3),
        all(row[2] and row[3] for row in boost_rows),
        all(row[3] for row in composition_rows),
        all(row[5] for row in kinetic_rows),
        all(
            _u905_scale(Fraction(refinement * refinement, 8), moment) == _u905_identity(3)
            for refinement, moment in refinement_isotropy_rows
        ),
    ))
    return {
        'proof_title': 'LORENTZ REFINEMENT ISOTROPY THEOREM',
        'twelve_direction_vertices': vertices,
        'first_moment': first_moment,
        'normalized_second_moment': normalized_second_moment,
        'rational_boost_covariance_rows': boost_rows,
        'rational_boost_composition_rows': tuple(composition_rows),
        'quadratic_kinetic_refinement_rows': tuple(kinetic_rows),
        'refinement_second_moment_rows': refinement_isotropy_rows,
        'theorem_result': theorem_result,
    }


