    second_shadow_operator = _matrix_multiply(_matrix_multiply(second_projection, source_operator), second_inverse)
    intertwiner = _matrix_multiply(second_projection, first_inverse)
    intertwining_exact = _matrix_multiply(second_shadow_operator, intertwiner) == _matrix_multiply(intertwiner, first_shadow_operator)
