def theorem_source_action_variation_pushforward():
    """Prove exact commutation of source variation, shadow pushforward, and measure reconstruction for an invertible complete projection family."""
    packet = _source_shadow_monomial_packet()
    projection = packet['evaluation']
    inverse = packet['inverse']
    size = len(projection)
    identity = _u905_identity(size)
    all_ones = tuple(tuple(Fraction(1) for _ in range(size)) for _ in range(size))
    source_hessian = _u905_subtract(_u905_scale(Fraction(size + 1), identity), all_ones)
    shadow_hessian = _matrix_multiply(
        _matrix_multiply(_u905_transpose(inverse), source_hessian),
        inverse,
    )
    pullback_hessian = _matrix_multiply(
        _matrix_multiply(_u905_transpose(projection), shadow_hessian),
        projection,
    )
    test_vectors = tuple(
        tuple(Fraction((seed + 1) * (index + 1) % 11 - 5) for index in range(size))
        for seed in range(6)
    )
    variation_rows = []
    for vector in test_vectors:
        shadow = _u905_vector(projection, vector)
        source_gradient = _u905_vector(source_hessian, vector)
        shadow_gradient = _u905_vector(shadow_hessian, shadow)
        pulled_gradient = _u905_vector(_u905_transpose(projection), shadow_gradient)
        source_action = Fraction(1, 2) * _u905_dot(vector, source_gradient)
        shadow_action = Fraction(1, 2) * _u905_dot(shadow, shadow_gradient)
        variation_rows.append((source_action == shadow_action, source_gradient == pulled_gradient))
    theorem_result = all((
        packet['left_inverse_exact'],
        packet['right_inverse_exact'],
        pullback_hessian == source_hessian,
        all(row[0] and row[1] for row in variation_rows),
        all(Fraction(size + 1) ** (order - 1) * Fraction(size + 1 - order) > 0 for order in range(1, size + 1)),
    ))
    return {
        'proof_title': 'SOURCE ACTION VARIATION PUSHFORWARD THEOREM',
        'source_hessian': source_hessian,
        'shadow_hessian': shadow_hessian,
        'pullback_hessian': pullback_hessian,
        'variation_and_action_commuting_rows': tuple(variation_rows),
        'theorem_result': theorem_result,
    }


