def theorem_all_rational_lorentz_group_identity():
    """Prove the Lorentz metric, determinant, and composition identities as polynomial identities for every admissible rational boost parameter."""
    zero = {}
    one = {(0, 0): Fraction(1)}
    p = {(1, 0): Fraction(1)}
    q = {(0, 1): Fraction(1)}

    def clean(poly):
        return {key: Fraction(value) for key, value in poly.items() if value}

    def add(left, right):
        result = dict(left)
        for key, value in right.items():
            result[key] = result.get(key, Fraction(0)) + value
        return clean(result)

    def scale(value, poly):
        return clean({key: Fraction(value) * coefficient for key, coefficient in poly.items()})

    def sub(left, right):
        return add(left, scale(-1, right))

    def mul(left, right):
        result = {}
        for (lp, lq), lv in left.items():
            for (rp, rq), rv in right.items():
                key = (lp + rp, lq + rq)
                result[key] = result.get(key, Fraction(0)) + lv * rv
        return clean(result)

    def power(poly, exponent):
        result = one
        base = poly
        value = exponent
        while value:
            if value % 2:
                result = mul(result, base)
            base = mul(base, base)
            value //= 2
        return result

    def const(value):
        return {} if value == 0 else {(0, 0): Fraction(value)}

    def matrix_transpose(matrix):
        return tuple(tuple(matrix[row][column] for row in range(len(matrix))) for column in range(len(matrix[0])))

    def matrix_multiply(left, right):
        right_t = matrix_transpose(right)
        return tuple(tuple(
            sum_poly((mul(a, b) for a, b in zip(row, column)))
            for column in right_t
        ) for row in left)

    def sum_poly(items):
        result = zero
        for item in items:
            result = add(result, item)
        return result

    def matrix_scale(poly, matrix):
        return tuple(tuple(mul(poly, entry) for entry in row) for row in matrix)

    def matrix_equal(left, right):
        return all(clean(left[row][column]) == clean(right[row][column]) for row in range(len(left)) for column in range(len(left[0])))

    def determinant(matrix):
        size = len(matrix)
        if size == 1:
            return matrix[0][0]
        total = zero
        for column in range(size):
            minor = tuple(tuple(matrix[row][c] for c in range(size) if c != column) for row in range(1, size))
            term = mul(matrix[0][column], determinant(minor))
            total = add(total, term if column % 2 == 0 else scale(-1, term))
        return clean(total)

    p2 = power(p, 2)
    q2 = power(q, 2)
    dp = sub(one, p2)
    dq = sub(one, q2)
    np = (
        (add(one, p2), scale(-2, p), zero, zero),
        (scale(-2, p), add(one, p2), zero, zero),
        (zero, zero, dp, zero),
        (zero, zero, zero, dp),
    )
    nq = (
        (add(one, q2), scale(-2, q), zero, zero),
        (scale(-2, q), add(one, q2), zero, zero),
        (zero, zero, dq, zero),
        (zero, zero, zero, dq),
    )
    eta = (
        (const(1), zero, zero, zero),
        (zero, const(-1), zero, zero),
        (zero, zero, const(-1), zero),
        (zero, zero, zero, const(-1)),
    )
    metric_left = matrix_multiply(matrix_multiply(matrix_transpose(np), eta), np)
    metric_right = matrix_scale(power(dp, 2), eta)
    determinant_identity = determinant(np) == power(dp, 4)

    a = add(one, mul(p, q))
    s = add(p, q)
    dpdq = mul(dp, dq)
    target_numerator = (
        (add(power(a, 2), power(s, 2)), scale(-2, mul(s, a)), zero, zero),
        (scale(-2, mul(s, a)), add(power(a, 2), power(s, 2)), zero, zero),
        (zero, zero, dpdq, zero),
        (zero, zero, zero, dpdq),
    )
    composition_identity = matrix_equal(matrix_multiply(np, nq), target_numerator)
    metric_residual = tuple(tuple(clean(sub(metric_left[row][column], metric_right[row][column])) for column in range(4)) for row in range(4))
    composition_residual = tuple(tuple(clean(sub(matrix_multiply(np, nq)[row][column], target_numerator[row][column])) for column in range(4)) for row in range(4))
    theorem_result = all((
        all(not entry for row in metric_residual for entry in row),
        determinant_identity,
        all(not entry for row in composition_residual for entry in row),
    ))
    return {
        'proof_title': 'ALL RATIONAL LORENTZ GROUP IDENTITY THEOREM',
        'boost_parameter_variables': ('p', 'q'),
        'admissibility_conditions': ('1-p^2 nonzero', '1-q^2 nonzero', '1+p*q nonzero'),
        'cross_multiplied_metric_residual': metric_residual,
        'cross_multiplied_determinant_identity': determinant_identity,
        'cross_multiplied_composition_residual': composition_residual,
        'composition_parameter_law': '(p+q)/(1+p*q)',
        'identity_holds_for_every_admissible_rational_parameter': theorem_result,
        'theorem_result': theorem_result,
    }



