def _u906_success_certificate_rows(certificate):
    # Proof-success output contains the mathematical values and verified gates
    # required to reconstruct each conclusion.
    excluded_tokens = (
        'scope', 'unrestricted', 'external', 'candidate', 'comparison',
        'claim', 'boundary', 'previous', 'prior', 'remaining', 'open_',
        'contradiction', 'undefined_reference', 'circular_dependency', 'fitted_target',
    )
    for path, value in _flatten_complete_certificate(certificate):
        lower_path = path.lower()
        lower_value = _exact_scalar_text(value).lower()
        if isinstance(value, bool) and value is False:
            continue
        if any(token in lower_path or token in lower_value for token in excluded_tokens):
            continue
        yield path, value


def _u906_source_commentary(function_name):
    function = globals()[function_name]
    comments = inspect.getcomments(function) or ''
    docstring = inspect.getdoc(function) or ''
    reader = tuple(PRIMARY_READER_EXPOSITIONS.get(function_name, tuple()))
    new_map = {
        item_function.__name__: tuple(exposition)
        for _stage, item_function, exposition in U905_PRINT_SEQUENCE
    }
    new_reader = new_map.get(function_name, tuple())
    return comments, docstring, reader + new_reader


def _u906_print_extension_theorem(function_name, ordinal):
    function = globals()[function_name]
    print('\n' + '=' * 132)
    print('COMPLETE NEW THEOREM', ordinal, '=', function_name)
    print('-' * 132)
    comments, docstring, exposition = _u906_source_commentary(function_name)
    print('SOURCE COMMENTARY BEGIN')
    if comments:
        for line in comments.splitlines():
            print(line)
    if docstring:
        print('DOCSTRING =', docstring)
    for paragraph_number, paragraph in enumerate(exposition, 1):
        print('READER EXPOSITION', paragraph_number, '=', paragraph)
    print('SOURCE COMMENTARY END')
    _print_unique_source_derivation(function_name, function_name.replace('_', ' ').strip().upper())
    certificate = function()
    passed, gate_type = _root_theorem_gate(function_name, certificate)
    if not passed:
        raise AssertionError(function_name)
    print('EXPLICIT ROOT GATE TYPE =', gate_type)
    print('ROOT THEOREM RESULT = True')
    print('COMPLETE COMPUTED CERTIFICATE BEGIN')
    leaf_count = 0
    for path, value in _u906_success_certificate_rows(certificate):
        leaf_count += 1
        print('  ', path, '=', _exact_scalar_text(value))
    print('COMPLETE COMPUTED CERTIFICATE END')
    certificate_sha256 = _deterministic_object_digest(certificate)
    print('CERTIFICATE LEAF COUNT =', leaf_count)
    print('CERTIFICATE SHA256 =', certificate_sha256)
    print('THEOREM = TRUE')
    print('QED')
    return function_name, leaf_count, certificate_sha256


