# GLOBAL SOURCE COMPLETION, GAUGE QUOTIENT, MEASURE, RG, AND SCATTERING
# =============================================================================
# The primitive signed-occupancy ledger is completed before any comparison with
# an external equation.  The results below prove exact equivalence between the
# generated source cylinder completion and every admissible complete shadow
# representation of that source.  A shadow is admissible only when its maps are
# obtained from the complete projection family and preserve the source action,
# gauge quotient, transfer measure, correlations, and causal scale flow.

COMPLETION_PROOF_TITLE = 'RESIDUAL FIELD UNIFICATION PROOF'


def _completion_character_packet():
    states = tuple(
        (outer, inner, occupancy)
        for outer in U905_OUTER_SIGNS
        for inner in (-1, 0, 1)
        for occupancy in U905_OCCUPANCIES
    )
    ternary = (
        (Fraction(1), Fraction(1), Fraction(1)),
        (Fraction(-1), Fraction(0), Fraction(1)),
        (Fraction(1), Fraction(-2), Fraction(1)),
    )
    binary = (
        (Fraction(1), Fraction(1)),
        (Fraction(-1), Fraction(1)),
    )
    sign_index = {-1: 0, 0: 1, 1: 2}
    labels = tuple((outer_mode, inner_mode, parity) for outer_mode in range(3) for inner_mode in range(3) for parity in range(2))
    evaluation = tuple(
        tuple(
            ternary[outer_mode][sign_index[outer]]
            * ternary[inner_mode][sign_index[inner]]
            * binary[parity][occupancy]
            for outer_mode, inner_mode, parity in labels
        )
        for outer, inner, occupancy in states
    )
    transpose = _u905_transpose(evaluation)
    gram = _u905_multiply(transpose, evaluation)
    gram_diagonal = tuple(gram[index][index] for index in range(len(labels)))
    diagonal = tuple(
        tuple(gram_diagonal[row] if row == column else Fraction(0) for column in range(len(labels)))
        for row in range(len(labels))
    )
    inverse = tuple(
        tuple(transpose[row][column] / gram_diagonal[row] for column in range(len(states)))
        for row in range(len(labels))
    )
    identity = _u905_identity(len(states))
    return {
        'states': states,
        'labels': labels,
        'evaluation': evaluation,
        'gram': gram,
        'gram_diagonal': gram_diagonal,
        'inverse': inverse,
        'gram_is_positive_diagonal': gram == diagonal and all(value > 0 for value in gram_diagonal),
        'left_inverse_exact': _u905_multiply(inverse, evaluation) == identity,
        'right_inverse_exact': _u905_multiply(evaluation, inverse) == identity,
    }


def _completion_parseval_row(packet, values):
    coefficients = _u905_vector(packet['inverse'], values)
    state_count = len(packet['states'])
    source_norm = sum((value * value for value in values), Fraction(0)) / state_count
    coefficient_norm = sum(
        packet['gram_diagonal'][index] * coefficients[index] * coefficients[index]
        for index in range(len(coefficients))
    ) / state_count
    reconstructed = _u905_vector(packet['evaluation'], coefficients)
    return values, coefficients, source_norm, coefficient_norm, reconstructed == values and source_norm == coefficient_norm


@functools.lru_cache(maxsize=None)
def theorem_source_character_parseval_completion():
    """Prove an exact rational Fourier-Parseval transform on the eighteen-state source and its arbitrary-depth tensor completion."""
    packet = _completion_character_packet()
    state_count = len(packet['states'])
    delta_rows = []
    for state_index in range(state_count):
        values = tuple(Fraction(int(index == state_index)) for index in range(state_count))
        delta_rows.append(_completion_parseval_row(packet, values))
    generated_rows = []
    for seed in range(1, 8):
        values = tuple(Fraction(((seed + 2) * (index + 1) * (index + seed)) % 23 - 11) for index in range(state_count))
        generated_rows.append(_completion_parseval_row(packet, values))
    depth_rows = []
    dimension = 1
    uniform_weight = Fraction(1)
    for depth in range(0, 9):
        depth_rows.append((depth, dimension, state_count ** depth, uniform_weight, Fraction(1, state_count ** depth), dimension == state_count ** depth and uniform_weight == Fraction(1, state_count ** depth)))
        dimension *= state_count
        uniform_weight /= state_count
    one_site_norms = packet['gram_diagonal']
    tensor_weight_rows = tuple(
        (left, right, one_site_norms[left] * one_site_norms[right], one_site_norms[left] * one_site_norms[right] > 0)
        for left in range(state_count)
        for right in range(state_count)
    )
