def _completion_transfer_packet():
    packet = _completion_character_packet()
    state_count = len(packet['states'])
    identity = _u905_identity(state_count)
    all_ones = tuple(tuple(Fraction(1) for _column in range(state_count)) for _row in range(state_count))
    fixed = _u905_scale(Fraction(1, state_count), all_ones)
    residual = _u905_subtract(identity, fixed)
    contraction = Fraction(1, state_count + 1)
    kernel = _u905_add(fixed, _u905_scale(contraction, residual))
    generator = _u905_subtract(identity, kernel)
    return {
        'character': packet,
        'state_count': state_count,
        'fixed': fixed,
        'residual': residual,
        'contraction': contraction,
        'kernel': kernel,
        'generator': generator,
    }


