def _completion_diagonal(values):
    return tuple(
        tuple(values[row] if row == column else Fraction(0) for column in range(len(values)))
        for row in range(len(values))
    )


def _completion_correlation(initial_row, operators, transfers, terminal):
    row = initial_row
    for index, operator in enumerate(operators):
        row = _completion_row_times_matrix(row, operator)
        if index < len(transfers):
            row = _completion_row_times_matrix(row, transfers[index])
    return sum(row[index] * terminal[index] for index in range(len(row)))


