    classification_rows = []
    allowed_rows = []
    for initial in states:
        for final in states:
            same_role = initial[0] == final[0]
            strict_descent = final[1] < initial[1]
            charge_color_weak_fingerprint_conserved = same_role
            allowed = same_role and strict_descent and charge_color_weak_fingerprint_conserved
            row = (initial, final, same_role, strict_descent, charge_color_weak_fingerprint_conserved, allowed)
            classification_rows.append(row)
            if allowed:
                allowed_rows.append(row)
    directed = tuple(
        tuple(probabilities[final][initial] if final < initial else Fraction(0) for initial in range(3))
        for final in range(3)
    )
