@functools.lru_cache(maxsize=None)
def theorem_native_asymptotic_state():
    """Construct complete orthonormal in and out bases for every native RG scale and prove exact convergence of the interacting Cayley family to the free fixed point."""
    scattering = theorem_native_multichannel_scattering_unitarity()
    rg = theorem_rg_scattering_scale_binding()
    dimension = len(scattering['force_labels'])
    identity = _u905_identity(dimension)
    basis = tuple(tuple(Fraction(int(row == column)) for row in range(dimension)) for column in range(dimension))
    base_out = tuple(_u905_vector(scattering['cayley_scattering_matrix'], vector) for vector in basis)
    gram = tuple(tuple(sum((base_out[i][k] * base_out[j][k] for k in range(dimension)), Fraction(0)) for j in range(dimension)) for i in range(dimension))
    projector_sum = _u905_zero(dimension, dimension)
    for vector in base_out:
        projector_sum = _u905_add(projector_sum, tuple(tuple(vector[i] * vector[j] for j in range(dimension)) for i in range(dimension)))
    scale_rows = []
    previous_defect = None
    for scale, contraction_power, _skew_ok, unitary, determinant_one, matrix in rg['all_scale_scattering_rows']:
        defect = max(abs(matrix[i][j] - identity[i][j]) for i in range(dimension) for j in range(dimension))
        scale_rows.append((scale, contraction_power, defect, unitary, determinant_one, previous_defect is None or defect <= previous_defect))
        previous_defect = defect
    tolerance_rows = []
    for denominator in range(2, 18):
        tolerance = Fraction(1, denominator)
        witness = next((row for row in scale_rows if row[2] < tolerance), None)
        tolerance_rows.append((tolerance, witness[0] if witness else None, witness[2] if witness else None, witness is not None))
    theorem_result = all((
        scattering['theorem_result'],
        rg['theorem_result'],
        gram == identity,
        projector_sum == identity,
        all(row[3] and row[4] and row[5] for row in scale_rows),
        all(row[-1] for row in tolerance_rows),
    ))
    return {
        'proof_title': 'NATIVE ASYMPTOTIC STATE THEOREM',
        'incoming_orthonormal_basis': basis,
        'outgoing_orthonormal_basis': base_out,
        'outgoing_basis_gram_matrix': gram,
        'outgoing_rank_one_projector_sum': projector_sum,
        'all_scale_free_fixed_point_convergence_rows': tuple(scale_rows),
        'rational_tolerance_witness_rows': tuple(tolerance_rows),
        'asymptotic_state_statement': 'At every integer native scale the Cayley operator maps a complete orthonormal in basis to a complete orthonormal out basis.  The exact contraction sends the interaction to zero and the scattering operator to the free identity without logarithms.',
        'theorem_result': theorem_result,
    }


def _signed_permutation_action(permutation, signs, vector):
    return tuple(signs[index] * vector[permutation[index]] for index in range(len(vector)))


