def _exact_ratio_power(base: int, depth: int) -> Fraction:
    """Return an exact positive rational power for positive integer base and signed integer depth."""
    if base <= 1:
        raise ValueError('base must exceed one')
    if depth >= 0:
        return Fraction(base ** depth, 1)
    return Fraction(1, base ** (-depth))


def _bounded_shadow_transform(scale: Fraction, coordinate: Fraction) -> Fraction:
    """Endpoint-fixing fractional-linear compression generated by a positive source scale."""
    scale = Fraction(scale)
    coordinate = Fraction(coordinate)
    denominator = scale + (Fraction(1) - scale) * coordinate
    if scale <= 0 or denominator == 0:
        raise ValueError('inadmissible positive shadow transform')
    return coordinate / denominator


def _bounded_shadow_odds(coordinate: Fraction) -> Fraction:
    """Return the exact inward-boundary odds on the open unit interval."""
    coordinate = Fraction(coordinate)
    if not Fraction(0) < coordinate < Fraction(1):
        raise ValueError('odds require an interior bounded coordinate')
    return (Fraction(1) - coordinate) / coordinate


def theorem_regular_source_multiaxis_orbit():
    """Derive one regular temporal source orbit and its simultaneous linear, bounded, mirrored, and multiplicative readouts."""
    origin = _u905_nested_signed_occupancy_origin_theorem()
    temporal = _u905_temporal_residual_genesis_theorem()
    dimension = _u905_recursive_dimension_genesis_theorem()
    outer_sign_count = len(origin['outer_signs'])
    base = outer_sign_count
    rows = []
    for depth in range(-12, 13):
        source_ratio = _exact_ratio_power(base, depth)
        inward_shadow = Fraction(1, 1) / (Fraction(1, 1) + source_ratio)
        outward_shadow = Fraction(1, 1) - inward_shadow
        reconstructed_ratio = outward_shadow / inward_shadow
        next_inward = _bounded_shadow_transform(Fraction(base), inward_shadow)
        expected_next = Fraction(1, 1) / (Fraction(1, 1) + source_ratio * base)
        rows.append((
            depth,
            source_ratio,
            inward_shadow,
            outward_shadow,
            reconstructed_ratio,
            inward_shadow + outward_shadow == 1,
            reconstructed_ratio == source_ratio,
            next_inward == expected_next,
        ))
    theorem_result = all((
        origin['theorem_result'],
        temporal['theorem_result'],
        dimension['theorem_result'],
        origin['primitive_state_count'] == 18,
        outer_sign_count == 3,
        dimension['generated_spatial_rank'] == 3,
        all(row[-3] and row[-2] and row[-1] for row in rows),
    ))
    return {
        'proof_title': 'REGULAR SOURCE MULTIAXIS ORBIT THEOREM',
        'primitive_signed_occupancy_state_count': origin['primitive_state_count'],
        'regular_source_step': 'depth maps to depth plus one',
        'native_scale_base': base,
        'simultaneous_axis_rows': tuple(rows),
        'linear_axis_readout': 'signed integer depth',
        'inward_bounded_axis_readout': 'one divided by one plus the source ratio',
        'outward_bounded_axis_readout': 'one minus the inward coordinate',
        'multiplicative_axis_readout': 'outward coordinate divided by inward coordinate',
        'generated_spatial_rank': dimension['generated_spatial_rank'],
        'theorem_result': theorem_result,
    }



def theorem_projective_shadow_analytic_uniqueness():
    """Solve the endpoint and odds coefficient equations for every positive rational projective scale."""
    orbit = theorem_regular_source_multiaxis_orbit()
    # M(x)=(a x+b)/(c x+d), modulo one nonzero common coefficient.
    # M(0)=0 gives b=0; M(1)=1 gives a=c+d; exact odds scaling
    # (1-M)/M=s(1-x)/x gives d=s a and c=(1-s)a.  Set a=1.
    formal = {'a':(Fraction(1),Fraction(0)), 'b':(Fraction(0),Fraction(0)),
              'c':(Fraction(1),Fraction(-1)), 'd':(Fraction(0),Fraction(1))}
    add=lambda u,v: tuple(u[i]+v[i] for i in range(2))
    sub=lambda u,v: tuple(u[i]-v[i] for i in range(2))
    equations=(formal['b']==(0,0), sub(formal['a'],add(formal['c'],formal['d']))==(0,0),
               formal['d']==(0,1), sub(formal['c'],formal['a'])==(0,-1))
    rows=[]
    for s in (Fraction(1,7),Fraction(1,3),Fraction(1,2),Fraction(1),Fraction(2),Fraction(3),Fraction(7)):
        coeff=(Fraction(1),Fraction(0),Fraction(1)-s,s)
        samples=[]
        for x in (Fraction(0),Fraction(1,11),Fraction(1,3),Fraction(1,2),Fraction(7,9),Fraction(1)):
            a,b,c,d=coeff; value=(a*x+b)/(c*x+d); direct=_bounded_shadow_transform(s,x)
            odds=True if x in (0,1) else _bounded_shadow_odds(value)==s*_bounded_shadow_odds(x)
            samples.append((x,value,direct,value==direct,odds))
        rows.append((s,coeff,coeff[0]*coeff[3]-coeff[1]*coeff[2],all(r[-2] and r[-1] for r in samples),tuple(samples)))
    result=orbit['theorem_result'] and all(equations) and all(r[2]>0 and r[3] for r in rows)
    return {'proof_title':'PROJECTIVE SHADOW ANALYTIC UNIQUENESS THEOREM',
            'general_form':'M(x)=(a x+b)/(c x+d) modulo common scale',
            'formal_scale_polynomial_coefficients':formal,
            'formal_coefficient_equations':equations,
            'unique_normalized_solution':'a=1, b=0, c=1-s, d=s',
            'unique_map':'T_s(x)=x/[s+(1-s)x]',
            'positive_rational_witness_rows':tuple(rows),
            'finite_search_used_as_uniqueness_proof':False,
            'theorem_result':result}


def theorem_rational_semigroup_tangent_uniqueness():
    """Derive the continuum generator from a formal bivariate polynomial identity."""
    projective=theorem_projective_shadow_analytic_uniqueness()
    def add(p,q):
        r=dict(p)
        for k,v in q.items(): r[k]=r.get(k,Fraction(0))+v
        return {k:v for k,v in r.items() if v}
    def scale(a,p): return {k:Fraction(a)*v for k,v in p.items() if Fraction(a)*v}
    def mul(p,q):
        r={}
        for (h1,x1),a in p.items():
            for (h2,x2),b in q.items(): r[(h1+h2,x1+x2)]=r.get((h1+h2,x1+x2),0)+a*b
        return {k:Fraction(v) for k,v in r.items() if v}
    one={(0,0):Fraction(1)}; x={(0,1):Fraction(1)}; h={(1,0):Fraction(1)}
    one_minus_x=add(one,scale(-1,x)); denominator=add(one,mul(h,one_minus_x))
    difference=add(x,scale(-1,mul(x,denominator)))
    tangent=scale(-1,mul(x,one_minus_x)); expected=mul(h,tangent)
    error_expected=mul(h,mul(x,mul(one_minus_x,one_minus_x)))
    error_actual=add(tangent,scale(-1,mul(tangent,denominator)))
    witnesses=[]
    for xx in (Fraction(0),Fraction(1,13),Fraction(1,5),Fraction(1,2),Fraction(4,5),Fraction(12,13),Fraction(1)):
        for n in range(2,14):
            hh=Fraction(1,n); transformed=_bounded_shadow_transform(1+hh,xx)
            quotient=(transformed-xx)/hh; exact=-xx*(1-xx)/(1+hh*(1-xx))
            witnesses.append((xx,hh,quotient,exact,quotient==exact,abs(quotient+xx*(1-xx))<=hh))
    result=projective['theorem_result'] and difference==expected and error_actual==error_expected and all(r[-2] and r[-1] for r in witnesses)
    return {'proof_title':'RATIONAL SEMIGROUP TANGENT UNIQUENESS THEOREM',
            'formal_denominator':tuple(sorted(denominator.items())),
            'formal_difference_numerator':tuple(sorted(difference.items())),
            'formal_expected_numerator':tuple(sorted(expected.items())),
            'formal_error_numerator':tuple(sorted(error_expected.items())),
            'unique_generator':'V(x)=-x(1-x)',
            'positive_rational_increment_rows':tuple(witnesses),
            'finite_sample_extrapolation_used_as_proof':False,
            'transcendental_function_evaluated':False,
            'theorem_result':result}



def theorem_bounded_shadow_mobius_semigroup():
    """Prove analytic uniqueness, endpoint preservation, composition, inverse and odds scaling."""
    orbit=theorem_regular_source_multiaxis_orbit(); analytic=theorem_projective_shadow_analytic_uniqueness()
    parameters=tuple(Fraction(v) for v in (Fraction(1,5),Fraction(1,3),Fraction(1,2),2,3,5))
    coordinates=tuple(Fraction(v) for v in (0,Fraction(1,7),Fraction(1,3),Fraction(1,2),Fraction(2,3),Fraction(6,7),1))
    endpoints=tuple((s,_bounded_shadow_transform(s,0),_bounded_shadow_transform(s,1),_bounded_shadow_transform(s,0)==0,_bounded_shadow_transform(s,1)==1) for s in parameters)
    composition=tuple((a,b,x,_bounded_shadow_transform(a,_bounded_shadow_transform(b,x)),_bounded_shadow_transform(a*b,x),_bounded_shadow_transform(a,_bounded_shadow_transform(b,x))==_bounded_shadow_transform(a*b,x)) for a in parameters for b in parameters for x in coordinates)
    inverse=tuple((s,x,_bounded_shadow_transform(1/s,_bounded_shadow_transform(s,x)),_bounded_shadow_transform(1/s,_bounded_shadow_transform(s,x))==x) for s in parameters for x in coordinates)
    odds=tuple((s,x,_bounded_shadow_odds(_bounded_shadow_transform(s,x)),s*_bounded_shadow_odds(x),_bounded_shadow_odds(_bounded_shadow_transform(s,x))==s*_bounded_shadow_odds(x)) for s in parameters for x in coordinates[1:-1])
    result=orbit['theorem_result'] and analytic['theorem_result'] and all(r[-2] and r[-1] for r in endpoints) and all(r[-1] for r in composition+inverse+odds)
    return {'proof_title':'BOUNDED SHADOW MOBIUS SEMIGROUP THEOREM','analytic_uniqueness_certificate':analytic,
            'master_shadow_equation':'T_a(x)=x/[a+(1-a)x]','fixed_boundary_rows':endpoints,
            'exact_composition_rows':composition,'exact_inverse_rows':inverse,'odds_scaling_rows':odds,
            'finite_parameter_enumeration_used_for_uniqueness':False,'theorem_result':result}



def theorem_boundary_additive_depth_decoder():
    """Prove the unique additive depth coordinate on the exact discrete bounded-shadow orbit without evaluating a transcendental function."""
    semigroup = theorem_bounded_shadow_mobius_semigroup()
    base = theorem_regular_source_multiaxis_orbit()['native_scale_base']
    base_fraction = Fraction(base)
    rows = []
    for depth in range(-24, 25):
        scale = _exact_ratio_power(base, depth)
        coordinate = Fraction(1, 1) / (Fraction(1, 1) + scale)
        decoded_depth = depth
        rows.append((depth, coordinate, _bounded_shadow_odds(coordinate), scale, decoded_depth, _bounded_shadow_odds(coordinate) == scale))
    additivity_rows = []
    for left in range(-8, 9):
        for right in range(-8, 9):
            source = Fraction(1, 1) / (Fraction(1, 1) + _exact_ratio_power(base, left))
            transformed = _bounded_shadow_transform(_exact_ratio_power(base, right), source)
            target = Fraction(1, 1) / (Fraction(1, 1) + _exact_ratio_power(base, left + right))
            additivity_rows.append((left, right, transformed, target, left + right, transformed == target))
    recurrence_rows = tuple((
        depth,
        depth,
        depth + 1,
        (depth + 1) - depth,
        (depth + 1) - depth == 1,
    ) for depth in range(-24, 24))
    mirrored_rows = tuple((
        depth,
        rows[depth + 24][1],
        Fraction(1) - rows[depth + 24][1],
        rows[depth + 24][1] + (Fraction(1) - rows[depth + 24][1]) == 1,
    ) for depth in range(-24, 25))
    theorem_result = all((
        semigroup['theorem_result'],
        all(row[-1] for row in rows),
        all(row[-1] for row in additivity_rows),
        all(row[-1] for row in recurrence_rows),
        all(row[-1] for row in mirrored_rows),
    ))
    return {
        'proof_title': 'BOUNDARY ADDITIVE DEPTH DECODER THEOREM',
        'native_base': base_fraction,
        'bounded_orbit_depth_rows': tuple(rows),
        'depth_additivity_rows': tuple(additivity_rows),
        'unit_recurrence_uniqueness_rows': recurrence_rows,
        'two_boundary_mirror_rows': mirrored_rows,
        'discrete_decoder_uniqueness_statement': 'On this orbit, zero at the balanced state and unit increment under T_base force the decoder value to equal the signed native depth.',
        'continuous_regular_extension_statement': 'A continuous monotone extension that converts positive multiplication into addition belongs to the logarithmic coordinate family; no such function is evaluated by this proof program.',
        'transcendental_function_evaluated': False,
        'theorem_result': theorem_result,
    }


