def _completion_block_projectors(dimensions):
    """Construct the mutually orthogonal exact block projectors fixed by generated sector dimensions."""
    total = sum(dimensions)
    projectors = []
    start = 0
    for dimension in dimensions:
        stop = start + dimension
        projector = tuple(
            tuple(Fraction(int(row == column and start <= row < stop)) for column in range(total))
            for row in range(total)
        )
        projectors.append(projector)
        start = stop
    return tuple(projectors)


def _completion_cross_ratio(points):
    """Return the ordered projective cross ratio of four distinct exact rational points."""
    first, second, third, fourth = tuple(Fraction(value) for value in points)
    denominator = (first - fourth) * (second - third)
    if denominator == 0:
        raise AssertionError('cross-ratio denominator vanishes')
    return (first - third) * (second - fourth) / denominator


def _completion_mobius(scale, coordinate):
    scale = Fraction(scale)
    coordinate = Fraction(coordinate)
    return coordinate / (scale + (1 - scale) * coordinate)


