    zero = _zero_matrix(total_dimension)
    projector_rows = []
    for left_index, left in enumerate(projectors):
        for right_index, right in enumerate(projectors):
            product = _matrix_multiply(left, right)
            expected = left if left_index == right_index else zero
            projector_rows.append((left_index, right_index, product == expected))
    projector_sum = zero
    for projector in projectors:
        projector_sum = _matrix_add(projector_sum, projector)
    operator = zero
    for eigenvalue, projector in zip(eigenvalues, projectors):
        operator = _matrix_add(operator, _matrix_scale(projector, eigenvalue))
