# ============================================================================
# EXACT NONLINEAR METRIC AND PARENT-FIELD LIFT
# ============================================================================
# A finite relational carrier fixes algebraic incidence and representation
# content.  The coframe coefficients remain fields over the generated base.
# The following exact rational-function construction computes the full
# Levi-Civita connection, Ricci tensor, Einstein tensor and covariant Bianchi
# identity for a genuinely variable four-dimensional metric.


def _nlf_poly_trim(coefficients):
    values = [Fraction(value) for value in coefficients]
    while len(values) > 1 and values[-1] == 0:
        values.pop()
    return tuple(values or (Fraction(0),))


def _nlf_poly_add(left, right):
    size = max(len(left), len(right))
    return _nlf_poly_trim(tuple(
        (left[index] if index < len(left) else Fraction(0))
        + (right[index] if index < len(right) else Fraction(0))
        for index in range(size)
    ))


def _nlf_poly_subtract(left, right):
    size = max(len(left), len(right))
    return _nlf_poly_trim(tuple(
        (left[index] if index < len(left) else Fraction(0))
        - (right[index] if index < len(right) else Fraction(0))
        for index in range(size)
    ))


def _nlf_poly_scale(polynomial, scalar):
    scalar = Fraction(scalar)
    return _nlf_poly_trim(tuple(scalar * value for value in polynomial))


def _nlf_poly_multiply(left, right):
    result = [Fraction(0) for _ in range(len(left) + len(right) - 1)]
    for left_index, left_value in enumerate(left):
        for right_index, right_value in enumerate(right):
            result[left_index + right_index] += left_value * right_value
    return _nlf_poly_trim(tuple(result))


def _nlf_poly_derivative(polynomial):
    if len(polynomial) <= 1:
        return (Fraction(0),)
    return _nlf_poly_trim(tuple(Fraction(index) * polynomial[index] for index in range(1, len(polynomial))))


def _nlf_poly_divmod(dividend, divisor):
    dividend = list(_nlf_poly_trim(dividend))
    divisor = _nlf_poly_trim(divisor)
    if divisor == (Fraction(0),):
        raise ZeroDivisionError('zero polynomial divisor')
    quotient = [Fraction(0) for _ in range(max(1, len(dividend) - len(divisor) + 1))]
    while len(dividend) >= len(divisor) and any(dividend):
        degree = len(dividend) - len(divisor)
        coefficient = dividend[-1] / divisor[-1]
        quotient[degree] = coefficient
        for index, value in enumerate(divisor):
            dividend[degree + index] -= coefficient * value
        dividend = list(_nlf_poly_trim(tuple(dividend)))
    return _nlf_poly_trim(tuple(quotient)), _nlf_poly_trim(tuple(dividend))


def _nlf_poly_gcd(left, right):
    left = _nlf_poly_trim(left)
    right = _nlf_poly_trim(right)
    while right != (Fraction(0),):
        _quotient, remainder = _nlf_poly_divmod(left, right)
        left, right = right, remainder
    if left == (Fraction(0),):
        return (Fraction(1),)
    return _nlf_poly_scale(left, Fraction(1, 1) / left[-1])


def _nlf_poly_evaluate(polynomial, coordinate):
    coordinate = Fraction(coordinate)
    value = Fraction(0)
    for coefficient in reversed(polynomial):
        value = value * coordinate + coefficient
    return value


class _NLFRational:
    __slots__ = ('numerator', 'denominator')

    def __init__(self, numerator=0, denominator=(1,)):
        if isinstance(numerator, _NLFRational):
            self.numerator = numerator.numerator
            self.denominator = numerator.denominator
            return
        if isinstance(numerator, (int, Fraction)):
            numerator = (Fraction(numerator),)
        if isinstance(denominator, (int, Fraction)):
            denominator = (Fraction(denominator),)
        numerator = _nlf_poly_trim(numerator)
        denominator = _nlf_poly_trim(denominator)
        if denominator == (Fraction(0),):
            raise ZeroDivisionError('zero rational-function denominator')
        if numerator == (Fraction(0),):
            self.numerator = (Fraction(0),)
            self.denominator = (Fraction(1),)
            return
        common = _nlf_poly_gcd(numerator, denominator)
        numerator, remainder_n = _nlf_poly_divmod(numerator, common)
        denominator, remainder_d = _nlf_poly_divmod(denominator, common)
        if remainder_n != (Fraction(0),) or remainder_d != (Fraction(0),):
            raise AssertionError('polynomial gcd division failed')
        leading = denominator[-1]
        self.numerator = _nlf_poly_scale(numerator, Fraction(1, 1) / leading)
        self.denominator = _nlf_poly_scale(denominator, Fraction(1, 1) / leading)

    @staticmethod
    def coerce(value):
        return value if isinstance(value, _NLFRational) else _NLFRational(value)

    def __add__(self, other):
        other = self.coerce(other)
        numerator = _nlf_poly_add(
            _nlf_poly_multiply(self.numerator, other.denominator),
            _nlf_poly_multiply(other.numerator, self.denominator),
        )
        denominator = _nlf_poly_multiply(self.denominator, other.denominator)
        return _NLFRational(numerator, denominator)

    __radd__ = __add__

    def __neg__(self):
        return _NLFRational(_nlf_poly_scale(self.numerator, -1), self.denominator)

    def __sub__(self, other):
        return self + (-self.coerce(other))

    def __rsub__(self, other):
        return self.coerce(other) - self

    def __mul__(self, other):
        other = self.coerce(other)
        return _NLFRational(
            _nlf_poly_multiply(self.numerator, other.numerator),
            _nlf_poly_multiply(self.denominator, other.denominator),
        )

    __rmul__ = __mul__

    def __truediv__(self, other):
        other = self.coerce(other)
        return _NLFRational(
            _nlf_poly_multiply(self.numerator, other.denominator),
            _nlf_poly_multiply(self.denominator, other.numerator),
        )

    def __rtruediv__(self, other):
        return self.coerce(other) / self

    def __pow__(self, exponent):
        exponent = int(exponent)
        if exponent < 0:
            return (_NLFRational(1) / self) ** (-exponent)
        result = _NLFRational(1)
        base = self
        while exponent:
            if exponent & 1:
                result = result * base
            base = base * base
            exponent //= 2
        return result

    def derivative(self):
        numerator = _nlf_poly_subtract(
            _nlf_poly_multiply(_nlf_poly_derivative(self.numerator), self.denominator),
            _nlf_poly_multiply(self.numerator, _nlf_poly_derivative(self.denominator)),
        )
        denominator = _nlf_poly_multiply(self.denominator, self.denominator)
        return _NLFRational(numerator, denominator)

    def evaluate(self, coordinate):
        return _nlf_poly_evaluate(self.numerator, coordinate) / _nlf_poly_evaluate(self.denominator, coordinate)

    def as_exact_pair(self):
        return (self.numerator, self.denominator)

    def __eq__(self, other):
        other = self.coerce(other)
        return self.numerator == other.numerator and self.denominator == other.denominator

    def __bool__(self):
        return self.numerator != (Fraction(0),)

    def __repr__(self):
        return '_NLFRational(' + repr(self.numerator) + ',' + repr(self.denominator) + ')'


def _nlf_zero_matrix(size):
    zero = _NLFRational(0)
    return [[zero for _column in range(size)] for _row in range(size)]


def _nlf_partial(function, coordinate_index):
    return function.derivative() if coordinate_index == 0 else _NLFRational(0)


@functools.lru_cache(maxsize=None)
def _nlf_exact_conformal_geometry_packet():
    zero = _NLFRational(0)
    one = _NLFRational(1)
    coordinate = _NLFRational((Fraction(0), Fraction(1)))
    scale_factor = one + coordinate + coordinate * coordinate
    eta = theorem_causal_signature_uniqueness()['unique_lorentz_form']
    dimension = len(eta)
    metric = _nlf_zero_matrix(dimension)
    inverse_metric = _nlf_zero_matrix(dimension)
    for index in range(dimension):
        metric[index][index] = _NLFRational(eta[index][index]) * scale_factor * scale_factor
        inverse_metric[index][index] = _NLFRational(eta[index][index]) / (scale_factor * scale_factor)

    connection = [[[_NLFRational(0) for _nu in range(dimension)] for _mu in range(dimension)] for _rho in range(dimension)]
    for rho in range(dimension):
        for mu in range(dimension):
            for nu in range(dimension):
                value = _NLFRational(0)
                for sigma in range(dimension):
                    value += inverse_metric[rho][sigma] * (
                        _nlf_partial(metric[sigma][nu], mu)
                        + _nlf_partial(metric[sigma][mu], nu)
                        - _nlf_partial(metric[mu][nu], sigma)
                    ) / 2
                connection[rho][mu][nu] = value

    ricci = _nlf_zero_matrix(dimension)
    for mu in range(dimension):
        for nu in range(dimension):
            value = _NLFRational(0)
            for rho in range(dimension):
                value += _nlf_partial(connection[rho][mu][nu], rho)
                value -= _nlf_partial(connection[rho][mu][rho], nu)
                for sigma in range(dimension):
                    value += connection[rho][mu][nu] * connection[sigma][rho][sigma]
                    value -= connection[sigma][mu][rho] * connection[rho][nu][sigma]
            ricci[mu][nu] = value

    scalar_curvature = _NLFRational(0)
    for mu in range(dimension):
        for nu in range(dimension):
            scalar_curvature += inverse_metric[mu][nu] * ricci[mu][nu]

    einstein = _nlf_zero_matrix(dimension)
    mixed_einstein = _nlf_zero_matrix(dimension)
    for mu in range(dimension):
        for nu in range(dimension):
            einstein[mu][nu] = ricci[mu][nu] - metric[mu][nu] * scalar_curvature / 2
    for mu in range(dimension):
        for nu in range(dimension):
            mixed_einstein[mu][nu] = sum(
                (inverse_metric[mu][rho] * einstein[rho][nu] for rho in range(dimension)),
                _NLFRational(0),
            )

    ordinary_divergence = []
    connection_correction = []
    covariant_divergence = []
    for nu in range(dimension):
        ordinary = _NLFRational(0)
        correction = _NLFRational(0)
        for mu in range(dimension):
            ordinary += _nlf_partial(mixed_einstein[mu][nu], mu)
            for lam in range(dimension):
                correction += connection[mu][mu][lam] * mixed_einstein[lam][nu]
                correction -= connection[lam][mu][nu] * mixed_einstein[mu][lam]
        ordinary_divergence.append(ordinary)
        connection_correction.append(correction)
        covariant_divergence.append(ordinary + correction)

    sample_coordinates = (Fraction(0), Fraction(1, 3), Fraction(1), Fraction(2))
    sample_rows = tuple(
        (
            value,
            scale_factor.evaluate(value),
            scalar_curvature.evaluate(value),
            tuple(einstein[index][index].evaluate(value) for index in range(dimension)),
            tuple(ordinary_divergence[index].evaluate(value) for index in range(dimension)),
            tuple(connection_correction[index].evaluate(value) for index in range(dimension)),
            tuple(covariant_divergence[index].evaluate(value) for index in range(dimension)),
        )
        for value in sample_coordinates
    )
    return {
        'scale_factor': scale_factor,
        'metric': tuple(tuple(row) for row in metric),
        'inverse_metric': tuple(tuple(row) for row in inverse_metric),
        'connection': tuple(tuple(tuple(row) for row in plane) for plane in connection),
        'ricci': tuple(tuple(row) for row in ricci),
        'scalar_curvature': scalar_curvature,
        'einstein': tuple(tuple(row) for row in einstein),
        'mixed_einstein': tuple(tuple(row) for row in mixed_einstein),
        'ordinary_divergence': tuple(ordinary_divergence),
        'connection_correction': tuple(connection_correction),
        'covariant_divergence': tuple(covariant_divergence),
        'sample_rows': sample_rows,
    }


