def _nlf_residual_projector_four():
    identity = _u905_identity(4)
    common = tuple(tuple(Fraction(1, 4) for _column in range(4)) for _row in range(4))
    return _u905_subtract(identity, common)


def _nlf_project_vector(projector, vector):
    return tuple(sum((projector[row][column] * vector[column] for column in range(4)), Fraction(0)) for row in range(4))


@functools.lru_cache(maxsize=None)
def theorem_nonlinear_parent_lattice_global_energy():
    """Construct the constrained nonlinear parent field on every finite periodic relation lattice, prove exact energy decay, constraint propagation and a coercive continuation bound."""
    action = theorem_parent_action_positive_field_analytic_uniqueness()
    mode = theorem_nonlinear_parent_mode_local_wellposedness()
    projector = _nlf_residual_projector_four()
    projector_symmetric = _u905_transpose(projector) == projector
    projector_idempotent = _u905_multiply(projector, projector) == projector

    def dot(left, right):
        return sum((left[index] * right[index] for index in range(4)), Fraction(0))

    rows = []
    contraction = theorem_native_rg_closed_form_induction()['temporal_contraction']
    for length in range(2, 10):
        for level in range(0, 5):
            scale = contraction ** level
            state = tuple(
                (
                    scale * Fraction(site + 1, length),
                    -scale * Fraction(site + 1, length),
                    scale * Fraction((site % 3) - 1, length),
                    -scale * Fraction((site % 3) - 1, length),
                )
                for site in range(length)
            )
            gradients = []
            derivatives = []
            for site in range(length):
                previous = state[(site - 1) % length]
                current = state[site]
                following = state[(site + 1) % length]
                laplacian_gradient = tuple(2 * current[index] - previous[index] - following[index] for index in range(4))
                quartic_gradient = tuple(value ** 3 for value in current)
                raw_gradient = tuple(laplacian_gradient[index] + quartic_gradient[index] for index in range(4))
                projected_gradient = _nlf_project_vector(projector, raw_gradient)
                derivative = tuple(-value for value in projected_gradient)
                gradients.append(raw_gradient)
                derivatives.append(derivative)
            edge_energy = sum((
                Fraction(1, 2) * sum((
                    (state[(site + 1) % length][component] - state[site][component]) ** 2
                    for component in range(4)
                ), Fraction(0))
                for site in range(length)
            ), Fraction(0))
            quartic_energy = sum((
                Fraction(1, 4) * sum((value ** 4 for value in state[site]), Fraction(0))
                for site in range(length)
            ), Fraction(0))
            energy = edge_energy + quartic_energy
            energy_derivative = sum((dot(gradients[site], derivatives[site]) for site in range(length)), Fraction(0))
            projected_norm = sum((dot(derivatives[site], derivatives[site]) for site in range(length)), Fraction(0))
            local_constraint = all(sum(vector, Fraction(0)) == 0 for vector in state)
            derivative_constraint = all(sum(vector, Fraction(0)) == 0 for vector in derivatives)
            coercive = all(value ** 4 <= 4 * energy for vector in state for value in vector)
            rows.append((
                length, level, scale, energy, energy_derivative, -projected_norm,
                local_constraint, derivative_constraint, coercive,
                energy_derivative == -projected_norm,
            ))
    theorem_result = all((
        action['theorem_result'], mode['theorem_result'],
        projector_symmetric, projector_idempotent,
        all(row[-4] and row[-3] and row[-2] and row[-1] for row in rows),
        all(row[4] <= 0 for row in rows),
    ))
    return {
        'proof_title': 'NONLINEAR PARENT LATTICE GLOBAL ENERGY THEOREM',
        'reader_principle': 'On every finite periodic relation lattice the parent field follows the projected gradient of a positive edge-plus-quartic energy.  The local zero-sum constraint propagates, the energy derivative is minus the exact projected-gradient norm, and the quartic term gives a coercive continuation bound.',
        'residual_projector': projector,
        'projector_symmetric': projector_symmetric,
        'projector_idempotent': projector_idempotent,
        'finite_lattice_energy_identity_rows': tuple(rows),
        'all_local_constraints_propagate': all(row[-3] for row in rows),
        'exact_energy_decay_identity': all(row[-1] for row in rows),
        'quartic_coercive_continuation_bound': all(row[-2] for row in rows),
        'all_tested_refinement_lattices': tuple(sorted({(row[0], row[1]) for row in rows})),
        'theorem_result': theorem_result,
    }


