# ============================================================================
# PARENT SOURCE--SHADOW COVARIANT RESIDUAL FIELD EQUATION
# ============================================================================
# The bounded shadow coordinate is not converted to an additive logarithmic
# variable inside the native dynamics.  Instead, the exact rational residual
# operator R(X)=(I-X)X^{-1} carries multiplicative temporal compression,
# covariant frame transport, four-sector projection, local clock-rate ratios,
# finite holonomy, and the parent curvature/action bridge in one equation.
# Every construction below is performed with exact rational arithmetic.


def _crf_matrix_subtract(left, right):
    return _matrix_add(left, _matrix_scale(right, Fraction(-1)))


def _crf_matrix_commutator(left, right):
    return _crf_matrix_subtract(_matrix_multiply(left, right), _matrix_multiply(right, left))


def _crf_frobenius_square(matrix):
    return sum((Fraction(value) * Fraction(value) for row in matrix for value in row), Fraction(0))


def _crf_diagonal(values):
    values = tuple(Fraction(value) for value in values)
    return tuple(
        tuple(values[row] if row == column else Fraction(0) for column in range(len(values)))
        for row in range(len(values))
    )


def _crf_block_diagonal(blocks):
    blocks = tuple(blocks)
    dimensions = tuple(len(block) for block in blocks)
    total = sum(dimensions)
    result = [[Fraction(0) for _ in range(total)] for _ in range(total)]
    offset = 0
    for block, dimension in zip(blocks, dimensions):
        for row in range(dimension):
            for column in range(dimension):
                result[offset + row][offset + column] = Fraction(block[row][column])
        offset += dimension
    return tuple(tuple(row) for row in result)


def _crf_extract_block(matrix, start, dimension):
    return tuple(
        tuple(Fraction(matrix[start + row][start + column]) for column in range(dimension))
        for row in range(dimension)
    )


def _crf_skew_plane(dimension, left, right, amplitude):
    amplitude = Fraction(amplitude)
    matrix = [[Fraction(0) for _ in range(dimension)] for _ in range(dimension)]
    if dimension > 1:
        matrix[left][right] = -amplitude
        matrix[right][left] = amplitude
    return tuple(tuple(row) for row in matrix)


def _crf_cayley(skew):
    dimension = len(skew)
    identity = _u905_identity(dimension)
    return _matrix_multiply(
        _matrix_inverse(_crf_matrix_subtract(identity, skew)),
        _matrix_add(identity, skew),
    )


def _crf_transport_block(dimension, amplitude, variant):
    if dimension == 1:
        return _u905_identity(1)
    amplitude = Fraction(amplitude)
    first = _crf_skew_plane(dimension, 0, 1, amplitude)
    skew = first
    if dimension >= 3:
        second_amplitude = amplitude * Fraction(variant + 1, variant + 2)
        second = _crf_skew_plane(dimension, 1, 2, second_amplitude)
        skew = _matrix_add(skew, second)
    return _crf_cayley(skew)


def _crf_parent_transport(dimensions, amplitude, variant):
    return _crf_block_diagonal(tuple(
        _crf_transport_block(dimension, amplitude, variant + index)
        for index, dimension in enumerate(dimensions)
    ))


def _crf_shadow_to_residual(shadow):
    identity = _u905_identity(len(shadow))
    return _matrix_multiply(_crf_matrix_subtract(identity, shadow), _matrix_inverse(shadow))


def _crf_residual_to_shadow(residual):
    identity = _u905_identity(len(residual))
    return _matrix_inverse(_matrix_add(identity, residual))


def _crf_sector_scalar_operator(projectors, scalars):
    total = len(projectors[0])
    result = _zero_matrix(total)
    for projector, scalar in zip(projectors, scalars):
        result = _matrix_add(result, _matrix_scale(projector, Fraction(scalar)))
    return result


def _crf_probe_residual(dimensions, eigenvalues, temporal_step):
    blocks = []
    for dimension, eigenvalue in zip(dimensions, eigenvalues):
        entries = tuple(
            Fraction(eigenvalue) * (Fraction(1) + Fraction(temporal_step) * Fraction(index + 1, dimension + 1))
            for index in range(dimension)
        )
        blocks.append(_crf_diagonal(entries))
    return _crf_block_diagonal(tuple(blocks))


def _crf_residual_equation_step(residual, compression, transport):
    transport_inverse = _matrix_inverse(transport)
    return _matrix_multiply(
        compression,
        _matrix_multiply(_matrix_multiply(transport, residual), transport_inverse),
    )


def _crf_trace_sector(matrix, projector):
    return _matrix_trace(_matrix_multiply(projector, matrix))


