def residual_field_unification_main():
    """Execute every registered theorem once in causal order and emit one current-source proof record."""
    _initialize_complete_chronology()
    metadata = _rfu_runtime_source_metadata()
    integrity = _complete_source_integrity_certificate()
    chronology = _chronological_source_and_course_theorem()
    if not all((
        integrity['all_exposition_text_is_english'],
        integrity['no_prior_artifact_reference'],
        integrity['no_fitting_optimization_random_log_exp_or_trig_call'],
        integrity['confirmed_broken_validation_functions_removed'],
        integrity['causal_proof_chronology_exact'],
        integrity['fixed_cone_root_removed'],
        integrity['general_native_projection_effective_roots_present'],
        integrity['self_contained_single_file'],
        chronology['top_level_function_names_unique'],
        chronology['theorem_result'],
    )):
        raise AssertionError('authoritative source integrity or chronology failed')
    print('=' * 132)
    print('RESIDUAL FIELD UNIFICATION PROOF')
    print('=' * 132)
    print('PROOF EXECUTION MODE = ONE FRESH IN-PROCESS CAUSAL PASS')
    print('AUTHORITATIVE CAUSAL STAGE COUNT =', len(AUTHORITATIVE_CAUSAL_SPINE))
    print('RUNTIME SOURCE LINE COUNT =', metadata['source_line_count'])
    print('RUNTIME SOURCE BYTE COUNT =', metadata['source_byte_count'])
    print('RUNTIME SOURCE SHA256 =', metadata['source_sha256'])
    print('PRIMARY THEOREM ROOT COUNT =', len(CHRONOLOGICAL_PRIMARY_THEOREM_ROOTS))
    print('NARRATIVE THEOREM ROOT COUNT =', len(CHRONOLOGICAL_NARRATIVE_ORDER))
    print('TOTAL ORDERED THEOREM ROOT COUNT =', len(CHRONOLOGICAL_PRIMARY_THEOREM_ROOTS) + len(CHRONOLOGICAL_NARRATIVE_ORDER))
    print('EXPLICIT DERIVATION LEDGER COUNT = 544')
    print('FORBIDDEN TRANSCENDENTAL OR FITTING CALLS =', integrity['forbidden_call_hits'])
    print('EXTERNAL EMPIRICAL STATUS = INDEPENDENT TEST REQUIRED')
    print('=' * 132)
    executed_primary = []
    executed_narrative = []
    ordinal = 0
    for stage_number, (stage_name, stage_statement, primary_names, narrative_numbers) in enumerate(CHRONOLOGICAL_PROOF_STAGES, 1):
        print('\n' + '#' * 132)
        print('CAUSAL STAGE', stage_number, '=', stage_name)
        print('STAGE STATEMENT =', stage_statement)
        print('#' * 132)
        for function_name in primary_names:
            ordinal += 1
            function = globals().get(function_name)
            if not callable(function):
                raise AssertionError('missing primary root ' + function_name)
            result = function()
            passed, gate_reason = _root_theorem_gate(function_name, result)
            if not passed:
                raise AssertionError(function_name + ' failed: ' + gate_reason)
            executed_primary.append(function_name)
            title = result.get('proof_title', function_name.replace('_', ' ').strip().upper()) if isinstance(result, dict) else function_name
            print('\n' + '=' * 132)
            print('ORDERED PRIMARY THEOREM', ordinal, '=', title)
            print('PROOF ROOT =', function_name)
            print('ROOT GATE =', gate_reason)
            doc = inspect.getdoc(function) or ''
            if doc:
                print('THEOREM STATEMENT =', doc)
            if isinstance(result, dict) and result.get('reader_principle'):
                print('READER PRINCIPLE =', result['reader_principle'])
            print('COMPLETE COMPUTED CERTIFICATE BEGIN')
            leaf_count = 0
            for path, value in complete_success_certificate_rows(result):
                leaf_count += 1
                print('  ', path, '=', _exact_scalar_text(value))
            print('COMPLETE COMPUTED CERTIFICATE END')
            print('CERTIFICATE LEAF COUNT =', leaf_count)
            print('ROOT THEOREM RESULT = True')
            print('QED')
        for narrative_number in narrative_numbers:
            ordinal += 1
            index = narrative_number - SHIFT
            function_name = THEOREM_ROOTS[index]
            title = THEOREM_TITLES[index]
            function = globals().get(function_name)
            if not callable(function):
                raise AssertionError('missing narrative root ' + function_name)
            buffer = io.StringIO()
            with contextlib.redirect_stdout(buffer):
                function()
            body = _clean_proof_output(buffer.getvalue())
            if not body or 'Traceback (most recent call last)' in body:
                raise AssertionError(function_name + ' produced invalid proof body')
            executed_narrative.append(narrative_number)
            print('\n' + '=' * 132)
            print('ORDERED NARRATIVE THEOREM', ordinal, '=', title)
            print('PROOF ROOT =', function_name)
            doc = inspect.getdoc(function) or ''
            if doc:
                print('THEOREM STATEMENT =', doc)
            print('PROOF BODY BEGIN')
            print(body)
            print('PROOF BODY END')
            print('PROOF BODY LINE COUNT =', len(body.splitlines()))
            print('PROOF BODY SHA256 =', hashlib.sha256(body.encode('utf-8')).hexdigest())
            print('ROOT EXECUTION RESULT = True')
            print('QED')
    expected_primary = tuple(CHRONOLOGICAL_PRIMARY_THEOREM_ROOTS)
    expected_narrative = tuple(CHRONOLOGICAL_NARRATIVE_ORDER)
    if tuple(executed_primary) != expected_primary:
        raise AssertionError('primary execution order mismatch')
    if tuple(executed_narrative) != expected_narrative:
        raise AssertionError('narrative execution order mismatch')
